#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub struct ModelVersionRollupKey {
    pub model_id: String,
    pub model_version: String,
    #[serde(default)]
    pub model_family: Option<String>,
    #[serde(default)]
    pub dataset_fingerprint: Option<String>,
    #[serde(default)]
    pub feature_schema_hash: Option<String>,
    #[serde(default)]
    pub label_manifest_hash: Option<String>,
    #[serde(default)]
    pub split_policy: Option<String>,
    #[serde(default)]
    pub prediction_schema_version: Option<String>,
}

impl ModelVersionRollupKey {
    pub fn validate(
        &self,
        require_model_id: bool,
        require_model_version: bool,
    ) -> Result<(), String> {
        if require_model_id && self.model_id.trim().is_empty() {
            return Err("model version rollup key requires model_id".to_string());
        }
        if require_model_version && self.model_version.trim().is_empty() {
            return Err("model version rollup key requires model_version".to_string());
        }
        Ok(())
    }

    pub fn stable_id(&self) -> String {
        format!("{}:{}", self.model_id, self.model_version)
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ModelOpsRollupConfig {
    pub rollup_id: String,
    #[serde(default)]
    pub model_review_closure_paths: Vec<String>,
    #[serde(default)]
    pub prediction_history_pack_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_decision_log_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_operator_qa_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_regression_guard_paths: Vec<String>,
    #[serde(default)]
    pub control_tower_model_ops_refresh_paths: Vec<String>,
    #[serde(default)]
    pub external_model_research_ops_paths: Vec<String>,
    #[serde(default)]
    pub conservative_leaderboard_paths: Vec<String>,
    #[serde(default)]
    pub calibration_drift_paths: Vec<String>,
    #[serde(default)]
    pub model_risk_profile_paths: Vec<String>,
    #[serde(default)]
    pub owner_model_review_paths: Vec<String>,
    #[serde(default = "default_rollup_output_root")]
    pub output_root: String,
    #[serde(default = "default_max_models")]
    pub max_models: usize,
    #[serde(default = "default_max_versions")]
    pub max_versions: usize,
    #[serde(default = "default_max_artifacts")]
    pub max_artifacts: usize,
    #[serde(default = "default_max_bytes")]
    pub max_bytes: usize,
    #[serde(default = "default_true")]
    pub deduplicate_by_model_version: bool,
    #[serde(default = "default_true")]
    pub require_model_id: bool,
    #[serde(default = "default_true")]
    pub require_model_version: bool,
    #[serde(default)]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for ModelOpsRollupConfig {
    fn default() -> Self {
        Self {
            rollup_id: "sprint67-model-ops-rollup".to_string(),
            model_review_closure_paths: Vec::new(),
            prediction_history_pack_paths: Vec::new(),
            model_ops_decision_log_paths: Vec::new(),
            model_ops_operator_qa_paths: Vec::new(),
            model_ops_regression_guard_paths: Vec::new(),
            control_tower_model_ops_refresh_paths: Vec::new(),
            external_model_research_ops_paths: Vec::new(),
            conservative_leaderboard_paths: Vec::new(),
            calibration_drift_paths: Vec::new(),
            model_risk_profile_paths: Vec::new(),
            owner_model_review_paths: Vec::new(),
            output_root: default_rollup_output_root(),
            max_models: default_max_models(),
            max_versions: default_max_versions(),
            max_artifacts: default_max_artifacts(),
            max_bytes: default_max_bytes(),
            deduplicate_by_model_version: true,
            require_model_id: true,
            require_model_version: true,
            reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsRollupConfigBuilt]),
        }
    }
}

impl ModelOpsRollupConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let mut config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.reason_codes = stable_reason_codes(&[ReasonCode::ModelOpsRollupConfigBuilt]);
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.rollup_id.trim().is_empty()
            || self.max_models == 0
            || self.max_versions == 0
            || self.max_artifacts == 0
            || self.max_bytes == 0
        {
            return Err(
                "model ops rollup config requires rollup_id and positive limits".to_string(),
            );
        }
        let all_paths = self
            .model_review_closure_paths
            .iter()
            .chain(self.prediction_history_pack_paths.iter())
            .chain(self.model_ops_decision_log_paths.iter())
            .chain(self.model_ops_operator_qa_paths.iter())
            .chain(self.model_ops_regression_guard_paths.iter())
            .chain(self.control_tower_model_ops_refresh_paths.iter())
            .chain(self.external_model_research_ops_paths.iter())
            .chain(self.conservative_leaderboard_paths.iter())
            .chain(self.calibration_drift_paths.iter())
            .chain(self.model_risk_profile_paths.iter())
            .chain(self.owner_model_review_paths.iter())
            .chain(std::iter::once(&self.output_root));
        if all_paths.clone().any(|path| path.contains("://")) {
            return Err("model ops rollup config paths must be local".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.rollup_id)
    }

    pub fn input_paths(&self) -> Vec<String> {
        self.model_review_closure_paths
            .iter()
            .chain(self.prediction_history_pack_paths.iter())
            .chain(self.model_ops_decision_log_paths.iter())
            .chain(self.model_ops_operator_qa_paths.iter())
            .chain(self.model_ops_regression_guard_paths.iter())
            .chain(self.control_tower_model_ops_refresh_paths.iter())
            .chain(self.external_model_research_ops_paths.iter())
            .chain(self.conservative_leaderboard_paths.iter())
            .chain(self.calibration_drift_paths.iter())
            .chain(self.model_risk_profile_paths.iter())
            .chain(self.owner_model_review_paths.iter())
            .cloned()
            .collect()
    }
}

