pub struct RegressionCauseExplainer;

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ModelOpsRollupRunner;

#[derive(Clone, Debug, Default)]
struct RollupContext {
    closure: Option<ModelReviewClosureReport>,
    history: Option<PredictionHistoryPackReport>,
    decision_log: Option<ModelOpsDecisionLog>,
    operator_qa: Option<ModelOpsOperatorQAReport>,
    regression_guard: Option<ModelOpsRegressionGuardReport>,
    refresh: Option<ControlTowerModelOpsRefreshReport>,
    external_ops: Option<ExternalModelResearchOpsBundle>,
    leaderboard: Option<ConservativeExternalLeaderboard>,
    calibration_drift: Option<CalibrationDriftReport>,
    risk_profiles: Vec<ModelEvidenceRiskProfile>,
    owner_actions: Vec<OwnerModelReviewAction>,
    input_artifact_count: usize,
    input_storage_bytes: usize,
}

impl ModelOpsRollupRunner {
    pub fn run(&self, config: &ModelOpsRollupConfig) -> Result<ModelOpsRollupBundle, String> {
        config.validate()?;
        let context = load_context(config)?;
        let identities = collect_identities(config, &context)?;
        enforce_rollup_limits(config, &context, &identities)?;
        let cards = build_model_version_summary_cards(config, &context, &identities)?;
        let regression = RegressionCauseExplainer::default().build(&context, &identities);
        let decision_log_rollup = build_decision_log_rollup(&context, &identities);
        let operator_qa_rollup =
            build_operator_qa_rollup(config, &context, &identities, &regression);
        let risk_rollup = build_model_ops_risk_rollup(&context, &identities, &regression);
        let action_priority =
            build_action_priority_report(&cards, &operator_qa_rollup, &risk_rollup, &regression);
        let static_summary = build_static_summary_report(
            config,
            &cards,
            &regression,
            &operator_qa_rollup,
            &action_priority,
        );
        let panel = Some(build_control_tower_model_ops_rollup_panel(
            config,
            &cards,
            &regression,
            &operator_qa_rollup,
            &decision_log_rollup,
            &action_priority,
            &context,
        ));
        let storage_report = build_storage_report(config, &context);
        let final_summary = build_final_summary(&static_summary, panel.as_ref());
        let bundle = ModelOpsRollupBundle {
            model_version_summary_cards: cards,
            regression_cause_explanation_report: regression,
            operator_qa_rollup_report: operator_qa_rollup,
            decision_log_rollup_report: decision_log_rollup,
            model_ops_risk_rollup_report: risk_rollup,
            model_ops_action_priority_report: action_priority,
            model_ops_static_summary_report: static_summary,
            control_tower_model_ops_rollup_panel: panel,
            storage_report,
            final_summary,
            reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsRollupBundleBuilt]),
        };
        write_rollup_bundle(config, &bundle)?;
        Ok(bundle)
    }

    pub fn run_regression_explain(
        &self,
        config: &ModelOpsRollupConfig,
    ) -> Result<RegressionCauseExplanationReport, String> {
        Ok(self.run(config)?.regression_cause_explanation_report)
    }

    pub fn run_operator_qa_rollup(
        &self,
        config: &ModelOpsRollupConfig,
    ) -> Result<OperatorQARollupReport, String> {
        Ok(self.run(config)?.operator_qa_rollup_report)
    }

    pub fn run_decision_log_rollup(
        &self,
        config: &ModelOpsRollupConfig,
    ) -> Result<DecisionLogRollupReport, String> {
        Ok(self.run(config)?.decision_log_rollup_report)
    }

    pub fn run_model_risk_rollup(
        &self,
        config: &ModelOpsRollupConfig,
    ) -> Result<ModelOpsRiskRollupReport, String> {
        Ok(self.run(config)?.model_ops_risk_rollup_report)
    }

    pub fn run_action_priority(
        &self,
        config: &ModelOpsRollupConfig,
    ) -> Result<ModelOpsActionPriorityReport, String> {
        Ok(self.run(config)?.model_ops_action_priority_report)
    }

    pub fn run_control_tower_model_ops_rollup(
        &self,
        config: &ModelOpsRollupConfig,
    ) -> Result<ControlTowerModelOpsRollupPanel, String> {
        self.run(config)?
            .control_tower_model_ops_rollup_panel
            .ok_or_else(|| "control tower model ops rollup panel unavailable".to_string())
    }
}

impl RegressionCauseExplainer {
    fn build(
        &self,
        context: &RollupContext,
        identities: &BTreeSet<String>,
    ) -> RegressionCauseExplanationReport {
        let Some(guard) = &context.regression_guard else {
            return RegressionCauseExplanationReport {
                explanations: Vec::new(),
                by_model: BTreeMap::new(),
                critical_count: 0,
                warning_count: 0,
                no_regression_count: 0,
                report_status: RegressionCauseExplanationStatus::DiagnosticOnly,
                reason_codes: stable_reason_codes(&[
                    ReasonCode::RegressionCauseExplanationReportBuilt,
                ]),
            };
        };

        let mut explanations = Vec::new();
        let mut push_for_keys = |keys: &[String],
                                 cause_kind: RegressionCauseKind,
                                 severity: RegressionSeverity,
                                 human: &str,
                                 technical: &str,
                                 action: ModelOpsDecisionKind| {
            for key in keys {
                let Some((model_id, model_version)) = key.split_once(':') else {
                    continue;
                };
                explanations.push(RegressionCauseExplanation {
                    model_id: model_id.to_string(),
                    model_version: model_version.to_string(),
                    cause_kind,
                    severity,
                    human_summary: human.to_string(),
                    technical_summary: technical.to_string(),
                    recommended_action: action,
                    reason_codes: stable_reason_codes(&[
                        ReasonCode::RegressionCauseExplanationBuilt,
                    ]),
                });
            }
        };

        push_for_keys(
            &guard.coverage_regressions,
            RegressionCauseKind::CoverageRegression,
            RegressionSeverity::Warning,
            "prediction coverage regressed and needs more offline history",
            "coverage band weakened versus baseline snapshot",
            ModelOpsDecisionKind::RequestMorePredictions,
        );
        push_for_keys(
            &guard.calibration_regressions,
            RegressionCauseKind::CalibrationRegression,
            RegressionSeverity::Warning,
            "calibration drift needs review before further comparison",
            "calibration band weakened versus baseline snapshot",
            ModelOpsDecisionKind::RequestCalibrationReview,
        );
        push_for_keys(
            &guard.risk_regressions,
            RegressionCauseKind::RiskRegression,
            RegressionSeverity::Critical,
            "risk behavior regressed and needs conservative review",
            "risk band weakened versus baseline snapshot",
            ModelOpsDecisionKind::RequestRiskReview,
        );
        push_for_keys(
            &guard.comparability_regressions,
            RegressionCauseKind::ComparabilityRegression,
            RegressionSeverity::Error,
            "comparability regressed and the model should stay diagnostic-only until clarified",
            "comparability band weakened versus baseline snapshot",
            ModelOpsDecisionKind::DowngradeToDiagnostic,
        );
        push_for_keys(
            &guard.artifact_completeness_regressions,
            RegressionCauseKind::ArtifactCompletenessRegression,
            RegressionSeverity::Warning,
            "artifact completeness regressed and evidence should be rebuilt conservatively",
            "artifact completeness band weakened versus baseline snapshot",
            ModelOpsDecisionKind::RequestMorePredictions,
        );
        push_for_keys(
            &guard.leaderboard_regressions,
            RegressionCauseKind::LeaderboardRegression,
            RegressionSeverity::Error,
            "leaderboard status regressed and ranking should be treated conservatively",
            "leaderboard band weakened versus baseline snapshot",
            ModelOpsDecisionKind::RetireModelVersion,
        );

        if guard.guard_status == ModelOpsRegressionGuardStatus::MissingBaseline {
            if identities.is_empty() {
                explanations.push(RegressionCauseExplanation {
                    model_id: "unknown".to_string(),
                    model_version: "unknown".to_string(),
                    cause_kind: RegressionCauseKind::MissingBaseline,
                    severity: RegressionSeverity::Warning,
                    human_summary:
                        "baseline snapshot is missing, so regression review stays conservative"
                            .to_string(),
                    technical_summary: "regression guard reported MissingBaseline".to_string(),
                    recommended_action: ModelOpsDecisionKind::RequestMorePredictions,
                    reason_codes: stable_reason_codes(&[
                        ReasonCode::RegressionCauseExplanationBuilt,
                    ]),
                });
            } else {
                for key in identities {
                    let Some((model_id, model_version)) = key.split_once(':') else {
                        continue;
                    };
                    explanations.push(RegressionCauseExplanation {
                        model_id: model_id.to_string(),
                        model_version: model_version.to_string(),
                        cause_kind: RegressionCauseKind::MissingBaseline,
                        severity: RegressionSeverity::Warning,
                        human_summary:
                            "baseline snapshot is missing, so regression review stays conservative"
                                .to_string(),
                        technical_summary: "regression guard reported MissingBaseline".to_string(),
                        recommended_action: ModelOpsDecisionKind::RequestMorePredictions,
                        reason_codes: stable_reason_codes(&[
                            ReasonCode::RegressionCauseExplanationBuilt,
                        ]),
                    });
                }
            }
        } else if explanations.is_empty() {
            for key in identities {
                let Some((model_id, model_version)) = key.split_once(':') else {
                    continue;
                };
                explanations.push(RegressionCauseExplanation {
                    model_id: model_id.to_string(),
                    model_version: model_version.to_string(),
                    cause_kind: RegressionCauseKind::NoRegression,
                    severity: RegressionSeverity::Info,
                    human_summary: "no regression is visible for this model version in the current snapshot".to_string(),
                    technical_summary: "regression guard did not report weakened coverage, calibration, risk, comparability, artifacts, or leaderboard".to_string(),
                    recommended_action: ModelOpsDecisionKind::KeepResearchCandidate,
                    reason_codes: stable_reason_codes(&[ReasonCode::RegressionCauseExplanationBuilt]),
                });
            }
        }

        explanations.sort_by(|left, right| {
            (
                left.model_id.clone(),
                left.model_version.clone(),
                format!("{:?}", left.cause_kind),
            )
                .cmp(&(
                    right.model_id.clone(),
                    right.model_version.clone(),
                    format!("{:?}", right.cause_kind),
                ))
        });
        let by_model = explanations.iter().fold(BTreeMap::new(), |mut acc, item| {
            acc.entry(format!("{}:{}", item.model_id, item.model_version))
                .or_insert_with(Vec::new)
                .push(item.human_summary.clone());
            acc
        });
        let critical_count = explanations
            .iter()
            .filter(|item| item.severity == RegressionSeverity::Critical)
            .count();
        let warning_count = explanations
            .iter()
            .filter(|item| {
                matches!(
                    item.severity,
                    RegressionSeverity::Warning | RegressionSeverity::Error
                )
            })
            .count();
        let no_regression_count = explanations
            .iter()
            .filter(|item| item.cause_kind == RegressionCauseKind::NoRegression)
            .count();
        let report_status = if guard.guard_status == ModelOpsRegressionGuardStatus::MissingBaseline
        {
            RegressionCauseExplanationStatus::NeedsBaseline
        } else if explanations
            .iter()
            .any(|item| item.cause_kind != RegressionCauseKind::NoRegression)
        {
            RegressionCauseExplanationStatus::RegressionDetected
        } else if explanations.is_empty() {
            RegressionCauseExplanationStatus::DiagnosticOnly
        } else {
            RegressionCauseExplanationStatus::NoRegression
        };
        RegressionCauseExplanationReport {
            explanations,
            by_model,
            critical_count,
            warning_count,
            no_regression_count,
            report_status,
            reason_codes: stable_reason_codes(&[ReasonCode::RegressionCauseExplanationReportBuilt]),
        }
    }
}

fn load_context(config: &ModelOpsRollupConfig) -> Result<RollupContext, String> {
    let input_paths = config.input_paths();
    let input_storage_bytes = input_paths.iter().try_fold(0usize, |acc, path| {
        let size = fs::metadata(path)
            .map(|meta| meta.len() as usize)
            .unwrap_or_default();
        Ok::<usize, String>(acc + size)
    })?;
    Ok(RollupContext {
        closure: load_first_closure_report(&config.model_review_closure_paths)?,
        history: load_first_history_report(&config.prediction_history_pack_paths)?,
        decision_log: load_first_decision_log(&config.model_ops_decision_log_paths)?,
        operator_qa: load_first_operator_qa(&config.model_ops_operator_qa_paths)?,
        regression_guard: load_first_regression_guard(&config.model_ops_regression_guard_paths)?,
        refresh: load_first_refresh_report(&config.control_tower_model_ops_refresh_paths)?,
        external_ops: load_first_external_ops_bundle(&config.external_model_research_ops_paths)?,
        leaderboard: load_first_report::<ConservativeExternalLeaderboard>(
            &config.conservative_leaderboard_paths,
        )?,
        calibration_drift: load_first_report::<CalibrationDriftReport>(
            &config.calibration_drift_paths,
        )?,
        risk_profiles: load_risk_profiles(config)?,
        owner_actions: load_owner_actions(
            &config.owner_model_review_paths,
            &config.external_model_research_ops_paths,
        )?,
        input_artifact_count: input_paths.len(),
        input_storage_bytes,
    })
}

fn collect_identities(
    config: &ModelOpsRollupConfig,
    context: &RollupContext,
) -> Result<BTreeSet<String>, String> {
    let mut ids = BTreeSet::new();
    if let Some(closure) = &context.closure {
        ids.extend(
            closure
                .actions
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
    }
    if let Some(history) = &context.history {
        ids.extend(
            history
                .records
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
    }
    if let Some(log) = &context.decision_log {
        ids.extend(
            log.records
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
    }
    if let Some(qa) = &context.operator_qa {
        for item in qa
            .models_to_review
            .iter()
            .chain(qa.models_to_retire.iter())
            .chain(qa.models_to_downgrade.iter())
            .chain(qa.models_to_request_predictions.iter())
            .chain(qa.models_to_watch.iter())
            .chain(qa.blocked_models.iter())
        {
            if is_valid_identity(item) {
                ids.insert(item.clone());
            }
        }
    }
    if let Some(guard) = &context.regression_guard {
        for item in guard
            .coverage_regressions
            .iter()
            .chain(guard.calibration_regressions.iter())
            .chain(guard.risk_regressions.iter())
            .chain(guard.comparability_regressions.iter())
            .chain(guard.artifact_completeness_regressions.iter())
            .chain(guard.leaderboard_regressions.iter())
        {
            if is_valid_identity(item) {
                ids.insert(item.clone());
            }
        }
    }
    if let Some(bundle) = &context.external_ops {
        ids.extend(
            bundle
                .lifecycle_records
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
        ids.extend(
            bundle
                .external_model_watchlist
                .entries
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
        ids.extend(
            bundle
                .artifact_completeness_scores
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
        ids.extend(
            bundle
                .model_evidence_risk_profiles
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
        ids.extend(
            bundle
                .model_leaderboard_changelog
                .changes
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
    }
    if let Some(leaderboard) = &context.leaderboard {
        ids.extend(
            leaderboard
                .entries
                .iter()
                .map(|item| format!("{}:{}", item.model_id, item.model_version)),
        );
    }
    ids.extend(
        context
            .risk_profiles
            .iter()
            .map(|item| format!("{}:{}", item.model_id, item.model_version)),
    );
    ids.extend(
        context
            .owner_actions
            .iter()
            .map(|item| format!("{}:{}", item.model_id, item.model_version)),
    );
    if config.require_model_id || config.require_model_version {
        for id in &ids {
            let Some((model_id, model_version)) = id.split_once(':') else {
                return Err("rollup identity requires model_id:model_version".to_string());
            };
            let key = ModelVersionRollupKey {
                model_id: model_id.to_string(),
                model_version: model_version.to_string(),
                model_family: None,
                dataset_fingerprint: None,
                feature_schema_hash: None,
                label_manifest_hash: None,
                split_policy: None,
                prediction_schema_version: None,
            };
            key.validate(config.require_model_id, config.require_model_version)?;
        }
    }
    Ok(ids)
}

fn enforce_rollup_limits(
    config: &ModelOpsRollupConfig,
    context: &RollupContext,
    identities: &BTreeSet<String>,
) -> Result<(), String> {
    if context.input_artifact_count > config.max_artifacts {
        return Err("max_artifacts exceeded".to_string());
    }
    if context.input_storage_bytes > config.max_bytes {
        return Err("max_bytes exceeded".to_string());
    }
    let model_count = identities
        .iter()
        .filter_map(|item| {
            item.split_once(':')
                .map(|(model_id, _)| model_id.to_string())
        })
        .collect::<BTreeSet<_>>()
        .len();
    if model_count > config.max_models {
        return Err("max_models exceeded".to_string());
    }
    if identities.len() > config.max_versions {
        return Err("max_versions exceeded".to_string());
    }
    Ok(())
}

fn build_model_version_summary_cards(
    config: &ModelOpsRollupConfig,
    context: &RollupContext,
    identities: &BTreeSet<String>,
) -> Result<Vec<ModelVersionSummaryCard>, String> {
    let leaderboard_map = leaderboard_map(context.leaderboard.as_ref());
    let completeness_map = completeness_map(context.external_ops.as_ref());
    let lifecycle_map = lifecycle_map(context.external_ops.as_ref());
    let watchlist_map = watchlist_map(context.external_ops.as_ref());
    let changelog_map = changelog_map(context.external_ops.as_ref());
    let drift_map = drift_map(context.calibration_drift.as_ref());
    let risk_map = risk_profile_map(&context.risk_profiles, context.external_ops.as_ref());
    let comparability_values = comparability_value_map(context.external_ops.as_ref());
    let decision_counts_map = decision_counts_map(context.decision_log.as_ref());
    let closure_map = closure_action_map(context.closure.as_ref());
    let owner_notes_map = owner_notes_map(&context.owner_actions);
    let regression_report = RegressionCauseExplainer::default().build(context, identities);

    let mut cards = Vec::new();
    for identity in identities {
        let Some((model_id, model_version)) = identity.split_once(':') else {
            continue;
        };
        let rollup_key = build_rollup_key(
            model_id,
            model_version,
            leaderboard_map.get(identity).copied(),
            comparability_values.get(identity),
        );
        rollup_key.validate(config.require_model_id, config.require_model_version)?;

        let closure_decisions = closure_map.get(identity).cloned().unwrap_or_default();
        let status = derive_summary_status(
            &closure_decisions,
            risk_map.get(identity),
            regression_report.by_model.get(identity),
            watchlist_map.get(identity),
        );
        let regression_causes = regression_report
            .by_model
            .get(identity)
            .cloned()
            .unwrap_or_default();
        let completeness_ratio = completeness_map
            .get(identity)
            .map(|item| format!("{:.4}", item.completeness_ratio));
        let risk_profile = risk_map.get(identity).copied();
        let leaderboard_entry = leaderboard_map.get(identity).copied();
        let card = ModelVersionSummaryCard {
            rollup_key,
            display_name: identity.clone(),
            lifecycle_status: lifecycle_map
                .get(identity)
                .cloned()
                .unwrap_or_else(|| "DiagnosticOnly".to_string()),
            review_status: if closure_decisions.is_empty() {
                "NoClosureDecision".to_string()
            } else {
                stable_ordered_strings(
                    &closure_decisions
                        .iter()
                        .map(|item| format!("{:?}", item))
                        .collect::<Vec<_>>(),
                )
                .join("|")
            },
            watchlist_status: watchlist_map
                .get(identity)
                .cloned()
                .unwrap_or_else(|| "NotWatched".to_string()),
            leaderboard_status: changelog_map
                .get(identity)
                .cloned()
                .or_else(|| leaderboard_entry.map(|item| format!("{:?}", item.entry_status)))
                .unwrap_or_else(|| "Unknown".to_string()),
            promotion_status: leaderboard_entry.and_then(|item| item.promotion_status.clone()),
            coverage_ratio: risk_profile
                .map(|item| item.coverage_ratio.clone())
                .or_else(|| leaderboard_entry.map(|item| format!("{:.4}", item.coverage_ratio))),
            calibration_status: risk_profile
                .map(|item| item.calibration_status.clone())
                .or_else(|| drift_map.get(identity).cloned()),
            drift_status: risk_profile.map(|item| item.drift_status.clone()),
            risk_level: risk_profile.map(|item| format!("{:?}", item.evidence_risk_level)),
            ablation_status: risk_profile
                .map(|item| item.ablation_status.clone())
                .or_else(|| leaderboard_entry.and_then(|item| item.ablation_status.clone())),
            regression_status: Some(match regression_causes.is_empty() {
                true => "NoRegression".to_string(),
                false => "RegressionNeedsReview".to_string(),
            }),
            artifact_completeness_ratio: completeness_ratio,
            decision_counts: decision_counts_map
                .get(identity)
                .cloned()
                .unwrap_or_default(),
            regression_causes,
            owner_notes_summary: owner_notes_map
                .get(identity)
                .cloned()
                .unwrap_or_else(|| "no owner note".to_string()),
            recommended_action: status,
            forbidden_actions: stable_ordered_strings(&forbidden_actions()),
            reason_codes: stable_reason_codes(&[ReasonCode::ModelVersionSummaryCardBuilt]),
        };
        cards.push(card);
    }
    cards.sort_by(|left, right| left.display_name.cmp(&right.display_name));
    Ok(cards)
}

fn build_decision_log_rollup(
    context: &RollupContext,
    identities: &BTreeSet<String>,
) -> DecisionLogRollupReport {
    let Some(log) = &context.decision_log else {
        return DecisionLogRollupReport {
            model_decision_summaries: Vec::new(),
            total_decisions: 0,
            by_kind_counts: BTreeMap::new(),
            by_source_counts: BTreeMap::new(),
            repeated_decision_count: 0,
            conflict_count: 0,
            report_status: DecisionLogRollupStatus::MissingDecisionLog,
            reason_codes: stable_reason_codes(&[ReasonCode::DecisionLogRollupReportBuilt]),
        };
    };
    let mut by_key: BTreeMap<String, Vec<&ModelOpsDecisionRecord>> = BTreeMap::new();
    let mut by_kind_counts = BTreeMap::new();
    let mut by_source_counts = BTreeMap::new();
    for record in &log.records {
        *by_kind_counts
            .entry(format!("{:?}", record.decision_kind))
            .or_insert(0) += 1;
        *by_source_counts
            .entry(format!("{:?}", record.source))
            .or_insert(0) += 1;
        by_key
            .entry(format!("{}:{}", record.model_id, record.model_version))
            .or_default()
            .push(record);
    }
    for identity in identities {
        by_key.entry(identity.clone()).or_default();
    }
    let mut repeated_decision_count = 0usize;
    let mut conflict_count = 0usize;
    let mut model_decision_summaries = Vec::new();
    for (identity, mut records) in by_key {
        let Some((model_id, model_version)) = identity.split_once(':') else {
            continue;
        };
        records.sort_by(|left, right| left.decision_id.cmp(&right.decision_id));
        let mut decision_counts = BTreeMap::new();
        for record in &records {
            *decision_counts
                .entry(format!("{:?}", record.decision_kind))
                .or_insert(0) += 1;
        }
        repeated_decision_count += decision_counts
            .values()
            .map(|count| (*count as usize).saturating_sub(1))
            .sum::<usize>();
        let conflicting_decisions = if decision_counts.len() > 1 {
            conflict_count += 1;
            decision_counts.keys().cloned().collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let latest_decision = records.last().map(|record| record.decision_kind);
        model_decision_summaries.push(ModelDecisionSummary {
            model_id: model_id.to_string(),
            model_version: model_version.to_string(),
            decision_counts,
            latest_decision,
            conflicting_decisions,
            reason_codes: stable_reason_codes(&[ReasonCode::DecisionLogRollupReportBuilt]),
        });
    }
    model_decision_summaries.sort_by(|left, right| {
        (left.model_id.clone(), left.model_version.clone())
            .cmp(&(right.model_id.clone(), right.model_version.clone()))
    });
    let report_status = if log.records.is_empty() {
        DecisionLogRollupStatus::DiagnosticOnly
    } else if conflict_count > 0 {
        DecisionLogRollupStatus::ConflictsDetected
    } else {
        DecisionLogRollupStatus::RollupReady
    };
    DecisionLogRollupReport {
        model_decision_summaries,
        total_decisions: log.records.len(),
        by_kind_counts,
        by_source_counts,
        repeated_decision_count,
        conflict_count,
        report_status,
        reason_codes: stable_reason_codes(&[ReasonCode::DecisionLogRollupReportBuilt]),
    }
}

fn build_operator_qa_rollup(
    config: &ModelOpsRollupConfig,
    context: &RollupContext,
    identities: &BTreeSet<String>,
    regression: &RegressionCauseExplanationReport,
) -> OperatorQARollupReport {
    let Some(raw) = &context.operator_qa else {
        return OperatorQARollupReport {
            items: Vec::new(),
            ready_count: 0,
            needs_prediction_count: 0,
            needs_calibration_count: 0,
            needs_risk_count: 0,
            blocked_count: 0,
            report_status: OperatorQARollupStatus::DiagnosticOnly,
            reason_codes: stable_reason_codes(&[ReasonCode::OperatorQARollupReportBuilt]),
        };
    };
    let predictions = raw
        .models_to_request_predictions
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let retire = raw
        .models_to_retire
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let downgrade = raw
        .models_to_downgrade
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let watch = raw.models_to_watch.iter().cloned().collect::<BTreeSet<_>>();
    let blocked = raw.blocked_models.iter().cloned().collect::<BTreeSet<_>>();
    let unsafe_detected = raw
        .unsafe_actions_detected
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let owner_actions = owner_actions_by_identity(&context.owner_actions);

    let mut items = Vec::new();
    let mut ready_count = 0usize;
    let mut needs_prediction_count = 0usize;
    let mut needs_calibration_count = 0usize;
    let mut needs_risk_count = 0usize;
    let mut blocked_count = 0usize;

    for identity in identities {
        let Some((model_id, model_version)) = identity.split_once(':') else {
            continue;
        };
        let owner = owner_actions.get(identity).cloned().unwrap_or_default();
        let blocked_actions = stable_ordered_strings(
            &owner
                .iter()
                .filter(|action| !action.allowed)
                .map(|action| format!("{:?}", action.action_kind))
                .chain(
                    unsafe_detected
                        .iter()
                        .filter(|item| item.contains(identity))
                        .cloned(),
                )
                .collect::<Vec<_>>(),
        );
        let safe_actions = stable_ordered_strings(
            &owner
                .iter()
                .filter(|action| action.allowed)
                .map(|action| format!("{:?}", action.action_kind))
                .chain(if watch.contains(identity) {
                    vec!["WatchModel".to_string()]
                } else {
                    Vec::new()
                })
                .collect::<Vec<_>>(),
        );
        let required_owner_actions = stable_ordered_strings(
            &owner
                .iter()
                .map(|action| format!("{:?}", action.action_kind))
                .collect::<Vec<_>>(),
        );
        let regression_notes = regression
            .by_model
            .get(identity)
            .cloned()
            .unwrap_or_default();
        let status = if blocked.contains(identity) || !blocked_actions.is_empty() {
            blocked_count += 1;
            OperatorQARollupStatus::BlockedBySafety
        } else if predictions.contains(identity) {
            needs_prediction_count += 1;
            OperatorQARollupStatus::NeedsMorePredictions
        } else if regression_notes
            .iter()
            .any(|item| item.contains("calibration"))
        {
            needs_calibration_count += 1;
            OperatorQARollupStatus::NeedsCalibrationReview
        } else if downgrade.contains(identity)
            || retire.contains(identity)
            || regression_notes.iter().any(|item| item.contains("risk"))
        {
            needs_risk_count += 1;
            OperatorQARollupStatus::NeedsRiskReview
        } else if safe_actions.is_empty() && required_owner_actions.is_empty() {
            ready_count += 1;
            OperatorQARollupStatus::ReadyForOperatorReview
        } else {
            ready_count += 1;
            OperatorQARollupStatus::ReadyForOperatorReview
        };
        items.push(OperatorQARollupItem {
            model_id: model_id.to_string(),
            model_version: model_version.to_string(),
            checklist_summary: raw.checklist_items.join(" | "),
            safe_actions,
            blocked_actions,
            required_owner_actions,
            next_command: Some(command_for_status(config, status)),
            status,
            reason_codes: stable_reason_codes(&[ReasonCode::OperatorQARollupReportBuilt]),
        });
    }
    items.sort_by(|left, right| {
        (left.model_id.clone(), left.model_version.clone())
            .cmp(&(right.model_id.clone(), right.model_version.clone()))
    });
    let report_status = if blocked_count > 0 {
        OperatorQARollupStatus::BlockedBySafety
    } else if needs_prediction_count > 0 {
        OperatorQARollupStatus::NeedsMorePredictions
    } else if needs_calibration_count > 0 {
        OperatorQARollupStatus::NeedsCalibrationReview
    } else if needs_risk_count > 0 {
        OperatorQARollupStatus::NeedsRiskReview
    } else if items.is_empty() {
        OperatorQARollupStatus::DiagnosticOnly
    } else {
        OperatorQARollupStatus::ReadyForOperatorReview
    };
    OperatorQARollupReport {
        items,
        ready_count,
        needs_prediction_count,
        needs_calibration_count,
        needs_risk_count,
        blocked_count,
        report_status,
        reason_codes: stable_reason_codes(&[ReasonCode::OperatorQARollupReportBuilt]),
    }
}

fn build_model_ops_risk_rollup(
    context: &RollupContext,
    identities: &BTreeSet<String>,
    regression: &RegressionCauseExplanationReport,
) -> ModelOpsRiskRollupReport {
    let risk_map = risk_profile_map(&context.risk_profiles, context.external_ops.as_ref());
    let completeness_map = completeness_map(context.external_ops.as_ref());
    let history_map = history_record_map(context.history.as_ref());
    let mut items = Vec::new();
    let mut low_count = 0usize;
    let mut medium_count = 0usize;
    let mut high_count = 0usize;
    let mut critical_count = 0usize;
    let mut blocked_count = 0usize;
    for identity in identities {
        let Some((model_id, model_version)) = identity.split_once(':') else {
            continue;
        };
        let risk = risk_map.get(identity).copied();
        let completeness = completeness_map.get(identity).copied();
        let history = history_map.get(identity).copied();
        let regression_text = regression
            .by_model
            .get(identity)
            .cloned()
            .unwrap_or_default()
            .join(" ");
        let coverage_risk = coverage_risk_label(risk, history);
        let calibration_risk = calibration_risk_label(risk);
        let drift_risk = drift_risk_label(risk);
        let risk_behavior_risk = risk_behavior_label(risk);
        let ablation_risk = ablation_risk_label(risk);
        let comparability_risk = comparability_risk_label(history, &regression_text);
        let artifact_completeness_risk = artifact_risk_label(completeness);
        let severity = [
            risk_bucket(&coverage_risk),
            risk_bucket(&calibration_risk),
            risk_bucket(&drift_risk),
            risk_bucket(&risk_behavior_risk),
            risk_bucket(&ablation_risk),
            risk_bucket(&comparability_risk),
            risk_bucket(&artifact_completeness_risk),
            risk.map(|item| base_risk_bucket(item.evidence_risk_level))
                .unwrap_or(1),
        ]
        .into_iter()
        .max()
        .unwrap_or(1);
        let (final_risk_level, recommended_action, status) = match severity {
            0 => {
                low_count += 1;
                (
                    "Low".to_string(),
                    ModelOpsDecisionKind::KeepResearchCandidate,
                    ModelOpsRiskRollupStatus::LowRiskResearch,
                )
            }
            1 => {
                medium_count += 1;
                (
                    "Medium".to_string(),
                    ModelOpsDecisionKind::KeepResearchCandidate,
                    ModelOpsRiskRollupStatus::MediumRiskResearch,
                )
            }
            2 => {
                high_count += 1;
                (
                    "High".to_string(),
                    ModelOpsDecisionKind::DowngradeToDiagnostic,
                    ModelOpsRiskRollupStatus::HighRiskDiagnostic,
                )
            }
            3 => {
                critical_count += 1;
                let action = if coverage_risk == "Critical" {
                    ModelOpsDecisionKind::RequestMorePredictions
                } else {
                    ModelOpsDecisionKind::RetireModelVersion
                };
                (
                    "Critical".to_string(),
                    action,
                    ModelOpsRiskRollupStatus::CriticalRiskDiagnostic,
                )
            }
            _ => {
                blocked_count += 1;
                (
                    "Blocked".to_string(),
                    ModelOpsDecisionKind::RequestRiskReview,
                    ModelOpsRiskRollupStatus::BlockedBySafety,
                )
            }
        };
        items.push(ModelOpsRiskRollup {
            model_id: model_id.to_string(),
            model_version: model_version.to_string(),
            coverage_risk,
            calibration_risk,
            drift_risk,
            risk_behavior_risk,
            ablation_risk,
            comparability_risk,
            artifact_completeness_risk,
            final_risk_level,
            recommended_action,
            status,
            reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsRiskRollupReportBuilt]),
        });
    }
    items.sort_by(|left, right| {
        (left.model_id.clone(), left.model_version.clone())
            .cmp(&(right.model_id.clone(), right.model_version.clone()))
    });
    ModelOpsRiskRollupReport {
        items,
        low_count,
        medium_count,
        high_count,
        critical_count,
        blocked_count,
        reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsRiskRollupReportBuilt]),
    }
}

fn build_action_priority_report(
    cards: &[ModelVersionSummaryCard],
    operator_qa: &OperatorQARollupReport,
    risk_rollup: &ModelOpsRiskRollupReport,
    regression: &RegressionCauseExplanationReport,
) -> ModelOpsActionPriorityReport {
    let qa_map = operator_qa
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let risk_map = risk_rollup
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();

    let mut required_actions = Vec::new();
    let mut recommended_actions = Vec::new();
    let mut optional_actions = Vec::new();
    let mut blocked_actions = Vec::new();

    for card in cards {
        let identity = card.display_name.clone();
        let qa_item = qa_map.get(&identity).copied();
        let risk_item = risk_map.get(&identity).copied();
        let regression_summary = regression
            .by_model
            .get(&identity)
            .cloned()
            .unwrap_or_default()
            .join(" | ");
        let (priority, action, reason, safe_to_run) = match card.recommended_action {
            ModelVersionSummaryStatus::RequestMorePredictions => (
                ActionPriorityLevel::Required,
                ModelOpsDecisionKind::RequestMorePredictions,
                "weak coverage or missing prediction evidence".to_string(),
                true,
            ),
            ModelVersionSummaryStatus::RequestCalibrationReview => (
                ActionPriorityLevel::Required,
                ModelOpsDecisionKind::RequestCalibrationReview,
                "calibration regression needs review".to_string(),
                true,
            ),
            ModelVersionSummaryStatus::RequestRiskReview => (
                ActionPriorityLevel::Required,
                ModelOpsDecisionKind::RequestRiskReview,
                "risk regression needs conservative review".to_string(),
                true,
            ),
            ModelVersionSummaryStatus::DowngradeToDiagnostic => (
                ActionPriorityLevel::Recommended,
                ModelOpsDecisionKind::DowngradeToDiagnostic,
                "risk or comparability remains too weak for active comparison".to_string(),
                true,
            ),
            ModelVersionSummaryStatus::RetireModelVersion => (
                ActionPriorityLevel::Required,
                ModelOpsDecisionKind::RetireModelVersion,
                "retired or critically regressed model version".to_string(),
                true,
            ),
            ModelVersionSummaryStatus::Deferred => (
                ActionPriorityLevel::Optional,
                ModelOpsDecisionKind::DeferReview,
                "review may be deferred while artifacts stay static".to_string(),
                true,
            ),
            ModelVersionSummaryStatus::Blocked => (
                ActionPriorityLevel::Required,
                ModelOpsDecisionKind::RequestRiskReview,
                "blocked by safety and cannot advance".to_string(),
                false,
            ),
            ModelVersionSummaryStatus::KeepResearchCandidate => (
                ActionPriorityLevel::Optional,
                if qa_item
                    .map(|item| item.safe_actions.iter().any(|entry| entry == "WatchModel"))
                    .unwrap_or(false)
                {
                    ModelOpsDecisionKind::WatchModel
                } else {
                    ModelOpsDecisionKind::KeepResearchCandidate
                },
                if regression_summary.is_empty() {
                    "keep as offline research candidate".to_string()
                } else {
                    format!("keep conservatively while tracking: {regression_summary}")
                },
                true,
            ),
        };
        let command_suggestion = if safe_to_run {
            Some(command_for_action(action))
        } else {
            None
        };
        let item = ModelOpsActionPriority {
            priority,
            action,
            model_id: card.rollup_key.model_id.clone(),
            model_version: card.rollup_key.model_version.clone(),
            reason: if let Some(risk_item) = risk_item {
                if matches!(
                    risk_item.status,
                    ModelOpsRiskRollupStatus::HighRiskDiagnostic
                        | ModelOpsRiskRollupStatus::CriticalRiskDiagnostic
                ) {
                    format!("{reason}; final_risk_level={}", risk_item.final_risk_level)
                } else {
                    reason
                }
            } else {
                reason
            },
            command_suggestion,
            safe_to_run,
            reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsActionPriorityReportBuilt]),
        };
        match (priority, safe_to_run) {
            (_, false) => blocked_actions.push(item),
            (ActionPriorityLevel::Required, true) => required_actions.push(item),
            (ActionPriorityLevel::Recommended, true) => recommended_actions.push(item),
            (ActionPriorityLevel::Optional, true) => optional_actions.push(item),
        }
    }
    sort_action_items(&mut required_actions);
    sort_action_items(&mut recommended_actions);
    sort_action_items(&mut optional_actions);
    sort_action_items(&mut blocked_actions);
    let primary_next_action = required_actions
        .first()
        .cloned()
        .or_else(|| recommended_actions.first().cloned())
        .or_else(|| optional_actions.first().cloned());
    ModelOpsActionPriorityReport {
        required_actions,
        recommended_actions,
        optional_actions,
        blocked_actions,
        primary_next_action,
        reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsActionPriorityReportBuilt]),
    }
}

fn build_static_summary_report(
    config: &ModelOpsRollupConfig,
    cards: &[ModelVersionSummaryCard],
    regression: &RegressionCauseExplanationReport,
    operator_qa_rollup: &OperatorQARollupReport,
    action_priority: &ModelOpsActionPriorityReport,
) -> ModelOpsStaticSummaryReport {
    let overall_status = if cards.is_empty() {
        ModelOpsStaticSummaryStatus::DiagnosticOnly
    } else if cards
        .iter()
        .any(|card| card.recommended_action == ModelVersionSummaryStatus::RequestMorePredictions)
    {
        ModelOpsStaticSummaryStatus::NeedsMorePredictions
    } else if matches!(
        regression.report_status,
        RegressionCauseExplanationStatus::RegressionDetected
            | RegressionCauseExplanationStatus::NeedsBaseline
    ) {
        ModelOpsStaticSummaryStatus::NeedsRegressionReview
    } else if matches!(
        operator_qa_rollup.report_status,
        OperatorQARollupStatus::NeedsOwnerAction | OperatorQARollupStatus::BlockedBySafety
    ) {
        ModelOpsStaticSummaryStatus::NeedsOwnerReview
    } else if regression.warning_count > 0 || !action_priority.recommended_actions.is_empty() {
        ModelOpsStaticSummaryStatus::ModelOpsSummaryReadyWithWarnings
    } else {
        ModelOpsStaticSummaryStatus::ModelOpsSummaryReady
    };
    let plain_language_summary = format!(
        "rollup_id={} cards={} overall_status={:?}; regression_status={:?}; operator_qa_status={:?}; primary_next_action={}; mamba_runtime=deferred; no live or production claim",
        config.rollup_id,
        cards.len(),
        overall_status,
        regression.report_status,
        operator_qa_rollup.report_status,
        action_priority
            .primary_next_action
            .as_ref()
            .map(|item| format!("{:?}:{}:{}", item.action, item.model_id, item.model_version))
            .unwrap_or_else(|| "none".to_string())
    );
    ModelOpsStaticSummaryReport {
        summary_id: config.rollup_id.clone(),
        cards: cards.to_vec(),
        regression_explanations: regression.clone(),
        operator_qa_rollup: operator_qa_rollup.clone(),
        action_priority: action_priority.clone(),
        overall_status,
        plain_language_summary,
        reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsStaticSummaryReportBuilt]),
    }
}

fn build_control_tower_model_ops_rollup_panel(
    config: &ModelOpsRollupConfig,
    cards: &[ModelVersionSummaryCard],
    regression: &RegressionCauseExplanationReport,
    operator_qa_rollup: &OperatorQARollupReport,
    decision_log_rollup: &DecisionLogRollupReport,
    action_priority: &ModelOpsActionPriorityReport,
    context: &RollupContext,
) -> ControlTowerModelOpsRollupPanel {
    let history_map = history_record_map(context.history.as_ref());
    let qa_map = operator_qa_rollup
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let action_map = action_priority
        .required_actions
        .iter()
        .chain(action_priority.recommended_actions.iter())
        .chain(action_priority.optional_actions.iter())
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let mut panel = ControlTowerModelOpsRollupPanel {
        panel_id: config.rollup_id.clone(),
        summary_cards: cards
            .iter()
            .map(|card| {
                let history_status = history_map
                    .get(&card.display_name)
                    .map(|record| {
                        if record.comparable && record.has_prediction_file {
                            "PredictionHistoryReady"
                        } else {
                            "PredictionHistoryNeedsReview"
                        }
                    })
                    .unwrap_or("PredictionHistoryUnknown");
                let qa_status = qa_map
                    .get(&card.display_name)
                    .map(|item| format!("{:?}", item.status))
                    .unwrap_or_else(|| "DiagnosticOnly".to_string());
                let action_status = action_map
                    .get(&card.display_name)
                    .map(|item| format!("{:?}", item.action))
                    .unwrap_or_else(|| "None".to_string());
                format!(
                    "{} status={:?} risk={} coverage={} history={} qa={} action={} regression={}",
                    card.display_name,
                    card.recommended_action,
                    card.risk_level
                        .clone()
                        .unwrap_or_else(|| "unknown".to_string()),
                    card.coverage_ratio
                        .clone()
                        .unwrap_or_else(|| "unknown".to_string()),
                    history_status,
                    qa_status,
                    action_status,
                    if card.regression_causes.is_empty() {
                        "none".to_string()
                    } else {
                        card.regression_causes.join(" / ")
                    }
                )
            })
            .collect(),
        regression_summary: format!(
            "{:?} critical={} warning={} no_regression={}",
            regression.report_status,
            regression.critical_count,
            regression.warning_count,
            regression.no_regression_count
        ),
        operator_qa_summary: format!(
            "{:?} ready={} needs_prediction={} blocked={}",
            operator_qa_rollup.report_status,
            operator_qa_rollup.ready_count,
            operator_qa_rollup.needs_prediction_count,
            operator_qa_rollup.blocked_count
        ),
        decision_summary: format!(
            "{:?} total={} conflicts={}",
            decision_log_rollup.report_status,
            decision_log_rollup.total_decisions,
            decision_log_rollup.conflict_count
        ),
        action_priority_summary: format!(
            "required={} recommended={} optional={} blocked={}",
            action_priority.required_actions.len(),
            action_priority.recommended_actions.len(),
            action_priority.optional_actions.len(),
            action_priority.blocked_actions.len()
        ),
        mamba_family_status: "HoldMamba3RuntimeDeferred".to_string(),
        next_commands: stable_ordered_strings(
            &action_priority
                .required_actions
                .iter()
                .chain(action_priority.recommended_actions.iter())
                .filter_map(|item| item.command_suggestion.clone())
                .collect::<Vec<_>>(),
        ),
        warnings: regression
            .explanations
            .iter()
            .filter(|item| item.cause_kind != RegressionCauseKind::NoRegression)
            .map(|item| {
                format!(
                    "{}:{} {:?}",
                    item.model_id, item.model_version, item.cause_kind
                )
            })
            .collect(),
        blockers: operator_qa_rollup
            .items
            .iter()
            .filter(|item| item.status == OperatorQARollupStatus::BlockedBySafety)
            .map(|item| format!("{}:{} blocked_by_safety", item.model_id, item.model_version))
            .collect(),
        reason_codes: stable_reason_codes(&[ReasonCode::ControlTowerModelOpsRollupPanelBuilt]),
    };
    if context.refresh.as_ref().is_some_and(|item| {
        item.refresh_status == ControlTowerModelOpsRefreshStatus::UnsafeControlDetected
    }) {
        panel
            .blockers
            .push("unsafe control detected in prior refresh".to_string());
    }
    panel.stabilize();
    panel
}

fn build_storage_report(
    config: &ModelOpsRollupConfig,
    context: &RollupContext,
) -> ModelOpsRollupStorageReport {
    ModelOpsRollupStorageReport {
        artifact_count: context.input_artifact_count,
        storage_bytes: context.input_storage_bytes,
        max_artifacts: config.max_artifacts,
        max_bytes: config.max_bytes,
        within_budget: context.input_artifact_count <= config.max_artifacts
            && context.input_storage_bytes <= config.max_bytes,
        reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsRollupStorageBuilt]),
    }
}

fn build_final_summary(
    summary: &ModelOpsStaticSummaryReport,
    panel: Option<&ControlTowerModelOpsRollupPanel>,
) -> String {
    [
        format!("rollup_status={:?}", summary.overall_status),
        format!(
            "regression_status={:?}",
            summary.regression_explanations.report_status
        ),
        format!(
            "operator_qa_status={:?}",
            summary.operator_qa_rollup.report_status
        ),
        format!(
            "panel_status={}",
            if panel.is_some() {
                "ControlTowerModelOpsRollupReady"
            } else {
                "DiagnosticOnly"
            }
        ),
        "runtime_status=HoldMamba3RuntimeDeferred".to_string(),
    ]
    .join("\n")
}

fn write_rollup_bundle(
    config: &ModelOpsRollupConfig,
    bundle: &ModelOpsRollupBundle,
) -> Result<(), String> {
    let dir = config.output_dir();
    fs::create_dir_all(&dir).map_err(|err| err.to_string())?;
    write_text_report(
        &dir,
        "model_version_summary_cards.txt",
        &bundle.model_version_summary_cards,
    )?;
    write_text_report(
        &dir,
        "regression_cause_explanations.txt",
        &bundle.regression_cause_explanation_report,
    )?;
    write_text_report(
        &dir,
        "operator_qa_rollup.txt",
        &bundle.operator_qa_rollup_report,
    )?;
    write_text_report(
        &dir,
        "decision_log_rollup.txt",
        &bundle.decision_log_rollup_report,
    )?;
    write_text_report(
        &dir,
        "model_ops_risk_rollup.txt",
        &bundle.model_ops_risk_rollup_report,
    )?;
    write_text_report(
        &dir,
        "model_ops_action_priority.txt",
        &bundle.model_ops_action_priority_report,
    )?;
    write_text_report(
        &dir,
        "model_ops_static_summary.txt",
        &bundle.model_ops_static_summary_report,
    )?;
    if let Some(panel) = &bundle.control_tower_model_ops_rollup_panel {
        write_text_report(&dir, "control_tower_model_ops_rollup_panel.txt", panel)?;
    }
    write_text_report(&dir, "storage_report.txt", &bundle.storage_report)?;
    fs::write(dir.join("summary.txt"), &bundle.final_summary).map_err(|err| err.to_string())?;
    Ok(())
}

fn write_text_report<T: Serialize>(dir: &Path, name: &str, value: &T) -> Result<(), String> {
    let text = serde_json::to_string_pretty(value).map_err(|err| err.to_string())?;
    fs::write(dir.join(name), text).map_err(|err| err.to_string())
}

fn load_first_report<T>(paths: &[String]) -> Result<Option<T>, String>
where
    T: for<'de> Deserialize<'de>,
{
    for path in paths {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let parsed = serde_json::from_str::<T>(&text).map_err(|err| err.to_string())?;
        return Ok(Some(parsed));
    }
    Ok(None)
}

fn read_json_file<T>(path: &str) -> Result<T, String>
where
    T: for<'de> Deserialize<'de>,
{
    let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
    serde_json::from_str(&text).map_err(|err| err.to_string())
}

fn load_first_closure_report(paths: &[String]) -> Result<Option<ModelReviewClosureReport>, String> {
    for path in paths {
        if let Ok(report) = read_json_file::<ModelReviewClosureReport>(path) {
            return Ok(Some(report));
        }
        if let Ok(bundle) = read_json_file::<super::ModelOpsReviewClosureBundle>(path) {
            return Ok(Some(bundle.model_review_closure_report));
        }
    }
    Ok(None)
}

