fn load_owner_actions(
    paths: &[String],
    external_paths: &[String],
) -> Result<Vec<OwnerModelReviewAction>, String> {
    let mut actions = Vec::new();
    for path in paths {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        if let Ok(parsed) = serde_json::from_str::<Vec<OwnerModelReviewAction>>(&text) {
            actions.extend(parsed);
            continue;
        }
        if let Ok(parsed) = serde_json::from_str::<OwnerModelReviewImpactReport>(&text) {
            actions.extend(parsed.actions);
            continue;
        }
        return Err("owner model review paths must contain local owner action json".to_string());
    }
    if actions.is_empty() {
        if let Some(bundle) = load_first_external_ops_bundle(external_paths)? {
            if let Some(report) = bundle.owner_model_review_impact_report {
                actions.extend(report.actions);
            }
        }
    }
    actions.sort_by(|left, right| left.action_id.cmp(&right.action_id));
    Ok(actions)
}

fn load_risk_profiles(
    config: &ModelOpsRollupConfig,
) -> Result<Vec<ModelEvidenceRiskProfile>, String> {
    let mut profiles = Vec::new();
    for path in &config.model_risk_profile_paths {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        if let Ok(parsed) = serde_json::from_str::<Vec<ModelEvidenceRiskProfile>>(&text) {
            profiles.extend(parsed);
            continue;
        }
        if let Ok(parsed) = serde_json::from_str::<ModelEvidenceRiskProfile>(&text) {
            profiles.push(parsed);
            continue;
        }
        if let Ok(bundle) = serde_json::from_str::<ExternalModelResearchOpsBundle>(&text) {
            profiles.extend(bundle.model_evidence_risk_profiles);
            continue;
        }
        return Err("model risk profile paths must contain local risk profile json".to_string());
    }
    if profiles.is_empty() {
        if let Some(bundle) =
            load_first_external_ops_bundle(&config.external_model_research_ops_paths)?
        {
            profiles.extend(bundle.model_evidence_risk_profiles);
        }
    }
    profiles.sort_by(|left, right| {
        (left.model_id.clone(), left.model_version.clone())
            .cmp(&(right.model_id.clone(), right.model_version.clone()))
    });
    Ok(profiles)
}

fn build_rollup_key(
    model_id: &str,
    model_version: &str,
    leaderboard: Option<&ConservativeLeaderboardEntry>,
    comparability_values: Option<&BTreeMap<String, String>>,
) -> ModelVersionRollupKey {
    ModelVersionRollupKey {
        model_id: model_id.to_string(),
        model_version: model_version.to_string(),
        model_family: leaderboard.map(|item| item.model_family.clone()),
        dataset_fingerprint: leaderboard.map(|item| item.dataset_fingerprint.clone()),
        feature_schema_hash: leaderboard.map(|item| item.feature_schema_hash.clone()),
        label_manifest_hash: leaderboard.map(|item| item.label_manifest_hash.clone()),
        split_policy: comparability_values.and_then(|values| values.get("SplitPolicy").cloned()),
        prediction_schema_version: comparability_values
            .and_then(|values| values.get("PredictionSchemaVersion").cloned()),
    }
}

fn derive_summary_status(
    closure_decisions: &[ModelReviewClosureDecision],
    risk_profile: Option<&&ModelEvidenceRiskProfile>,
    regression_causes: Option<&Vec<String>>,
    watch_status: Option<&String>,
) -> ModelVersionSummaryStatus {
    if closure_decisions
        .iter()
        .any(|item| *item == ModelReviewClosureDecision::RetireModelVersion)
        || watch_status.is_some_and(|item| item == "Retired")
    {
        return ModelVersionSummaryStatus::RetireModelVersion;
    }
    if closure_decisions
        .iter()
        .any(|item| *item == ModelReviewClosureDecision::RequestMorePredictions)
    {
        return ModelVersionSummaryStatus::RequestMorePredictions;
    }
    if closure_decisions
        .iter()
        .any(|item| *item == ModelReviewClosureDecision::RequestCalibrationReview)
        || regression_causes
            .is_some_and(|items| items.iter().any(|item| item.contains("calibration")))
    {
        return ModelVersionSummaryStatus::RequestCalibrationReview;
    }
    if closure_decisions
        .iter()
        .any(|item| *item == ModelReviewClosureDecision::RequestRiskReview)
        || regression_causes.is_some_and(|items| items.iter().any(|item| item.contains("risk")))
    {
        return ModelVersionSummaryStatus::RequestRiskReview;
    }
    if closure_decisions
        .iter()
        .any(|item| *item == ModelReviewClosureDecision::DeferReview)
    {
        return ModelVersionSummaryStatus::Deferred;
    }
    if risk_profile.is_some_and(|item| {
        matches!(
            item.evidence_risk_level,
            ModelEvidenceRiskLevel::High
                | ModelEvidenceRiskLevel::Critical
                | ModelEvidenceRiskLevel::DiagnosticOnly
        )
    }) {
        return ModelVersionSummaryStatus::DowngradeToDiagnostic;
    }
    if closure_decisions
        .iter()
        .any(|item| *item == ModelReviewClosureDecision::DismissReview)
    {
        return ModelVersionSummaryStatus::Blocked;
    }
    ModelVersionSummaryStatus::KeepResearchCandidate
}

fn forbidden_actions() -> Vec<String> {
    vec![
        "train".to_string(),
        "live".to_string(),
        "runtime".to_string(),
        "broker".to_string(),
        "order".to_string(),
        "account".to_string(),
    ]
}

fn command_for_status(config: &ModelOpsRollupConfig, status: OperatorQARollupStatus) -> String {
    match status {
        OperatorQARollupStatus::NeedsMorePredictions => {
            "cargo run --quiet --bin soma_experiment -- model-ops-rollup --config examples/soma_model_ops_rollup.toml".to_string()
        }
        OperatorQARollupStatus::NeedsCalibrationReview => {
            "cargo run --quiet --bin soma_experiment -- model-regression-explain --config examples/soma_model_regression_explain.toml".to_string()
        }
        OperatorQARollupStatus::NeedsRiskReview | OperatorQARollupStatus::BlockedBySafety => {
            "cargo run --quiet --bin soma_experiment -- model-risk-rollup --config examples/soma_model_risk_rollup.toml".to_string()
        }
        OperatorQARollupStatus::NeedsOwnerAction => {
            "cargo run --quiet --bin soma_experiment -- decision-log-rollup --config examples/soma_decision_log_rollup.toml".to_string()
        }
        OperatorQARollupStatus::ReadyForOperatorReview | OperatorQARollupStatus::DiagnosticOnly => {
            format!(
                "cargo run --quiet --bin soma_experiment -- control-tower-model-ops-rollup --config examples/{}.toml",
                if config.rollup_id.contains("control-tower") {
                    "soma_control_tower_model_ops_rollup"
                } else {
                    "soma_control_tower_model_ops_rollup"
                }
            )
        }
    }
}

fn command_for_action(action: ModelOpsDecisionKind) -> String {
    match action {
        ModelOpsDecisionKind::RequestMorePredictions => {
            "cargo run --quiet --bin soma_experiment -- model-ops-rollup --config examples/soma_model_ops_rollup.toml".to_string()
        }
        ModelOpsDecisionKind::RequestCalibrationReview => {
            "cargo run --quiet --bin soma_experiment -- model-regression-explain --config examples/soma_model_regression_explain.toml".to_string()
        }
        ModelOpsDecisionKind::RequestRiskReview => {
            "cargo run --quiet --bin soma_experiment -- model-risk-rollup --config examples/soma_model_risk_rollup.toml".to_string()
        }
        ModelOpsDecisionKind::DowngradeToDiagnostic => {
            "cargo run --quiet --bin soma_experiment -- operator-qa-rollup --config examples/soma_operator_qa_rollup.toml".to_string()
        }
        ModelOpsDecisionKind::RetireModelVersion => {
            "cargo run --quiet --bin soma_experiment -- decision-log-rollup --config examples/soma_decision_log_rollup.toml".to_string()
        }
        ModelOpsDecisionKind::KeepResearchCandidate | ModelOpsDecisionKind::WatchModel => {
            "cargo run --quiet --bin soma_experiment -- control-tower-model-ops-rollup --config examples/soma_control_tower_model_ops_rollup.toml".to_string()
        }
        ModelOpsDecisionKind::DeferReview | ModelOpsDecisionKind::DismissReview | ModelOpsDecisionKind::UnwatchModel => {
            "cargo run --quiet --bin soma_experiment -- model-action-priority --config examples/soma_model_action_priority.toml".to_string()
        }
    }
}

fn sort_action_items(items: &mut [ModelOpsActionPriority]) {
    items.sort_by(|left, right| {
        (
            left.priority,
            action_sort_key(left.action),
            left.model_id.clone(),
            left.model_version.clone(),
        )
            .cmp(&(
                right.priority,
                action_sort_key(right.action),
                right.model_id.clone(),
                right.model_version.clone(),
            ))
    });
}

fn action_sort_key(action: ModelOpsDecisionKind) -> usize {
    match action {
        ModelOpsDecisionKind::RequestMorePredictions => 0,
        ModelOpsDecisionKind::RequestCalibrationReview => 1,
        ModelOpsDecisionKind::RequestRiskReview => 2,
        ModelOpsDecisionKind::DowngradeToDiagnostic => 3,
        ModelOpsDecisionKind::RetireModelVersion => 4,
        ModelOpsDecisionKind::KeepResearchCandidate => 5,
        ModelOpsDecisionKind::WatchModel => 6,
        ModelOpsDecisionKind::DeferReview => 7,
        ModelOpsDecisionKind::DismissReview => 8,
        ModelOpsDecisionKind::UnwatchModel => 9,
    }
}

fn is_valid_identity(value: &str) -> bool {
    value.split_once(':').is_some()
}

