fn risk_profile_map<'a>(
    profiles: &'a [ModelEvidenceRiskProfile],
    bundle: Option<&'a ExternalModelResearchOpsBundle>,
) -> BTreeMap<String, &'a ModelEvidenceRiskProfile> {
    let mut map = bundle
        .map(|item| {
            item.model_evidence_risk_profiles
                .iter()
                .map(|entry| (format!("{}:{}", entry.model_id, entry.model_version), entry))
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default();
    for profile in profiles {
        map.insert(
            format!("{}:{}", profile.model_id, profile.model_version),
            profile,
        );
    }
    map
}

fn decision_counts_map(
    log: Option<&ModelOpsDecisionLog>,
) -> BTreeMap<String, BTreeMap<String, usize>> {
    let mut map = BTreeMap::new();
    if let Some(log) = log {
        for record in &log.records {
            *map.entry(format!("{}:{}", record.model_id, record.model_version))
                .or_insert_with(BTreeMap::new)
                .entry(format!("{:?}", record.decision_kind))
                .or_insert(0) += 1;
        }
    }
    map
}

fn closure_action_map(
    closure: Option<&ModelReviewClosureReport>,
) -> BTreeMap<String, Vec<ModelReviewClosureDecision>> {
    let mut map = BTreeMap::new();
    if let Some(closure) = closure {
        for action in &closure.actions {
            map.entry(format!("{}:{}", action.model_id, action.model_version))
                .or_insert_with(Vec::new)
                .push(action.action);
        }
    }
    map
}

fn owner_notes_map(actions: &[OwnerModelReviewAction]) -> BTreeMap<String, String> {
    actions.iter().fold(BTreeMap::new(), |mut acc, action| {
        let note = action
            .note
            .clone()
            .unwrap_or_else(|| format!("{:?}", action.action_kind));
        acc.entry(format!("{}:{}", action.model_id, action.model_version))
            .and_modify(|existing| {
                if !existing.contains(&note) {
                    existing.push_str(" | ");
                    existing.push_str(&note);
                }
            })
            .or_insert(note);
        acc
    })
}

fn owner_actions_by_identity(
    actions: &[OwnerModelReviewAction],
) -> BTreeMap<String, Vec<OwnerModelReviewAction>> {
    actions.iter().fold(BTreeMap::new(), |mut acc, action| {
        acc.entry(format!("{}:{}", action.model_id, action.model_version))
            .or_insert_with(Vec::new)
            .push(action.clone());
        acc
    })
}

fn comparability_value_map(
    bundle: Option<&ExternalModelResearchOpsBundle>,
) -> BTreeMap<String, BTreeMap<String, String>> {
    let mut map = BTreeMap::new();
    if let Some(bundle) = bundle {
        for cell in &bundle.model_comparability_matrix.cells {
            if let Some(value) = &cell.value {
                map.entry(format!("{}:{}", cell.model_id, cell.model_version))
                    .or_insert_with(BTreeMap::new)
                    .insert(format!("{:?}", cell.dimension), value.clone());
            }
        }
    }
    map
}

fn history_record_map(
    history: Option<&PredictionHistoryPackReport>,
) -> BTreeMap<String, &super::PredictionHistoryPackVersionRecord> {
    history
        .map(|item| {
            item.records
                .iter()
                .map(|record| {
                    (
                        format!("{}:{}", record.model_id, record.model_version),
                        record,
                    )
                })
                .collect()
        })
        .unwrap_or_default()
}

fn coverage_risk_label(
    risk: Option<&ModelEvidenceRiskProfile>,
    history: Option<&super::PredictionHistoryPackVersionRecord>,
) -> String {
    if let Some(risk) = risk {
        let ratio = risk.coverage_ratio.parse::<f64>().unwrap_or(0.0);
        if ratio < 0.75 {
            return "Critical".to_string();
        }
        if ratio < 1.0 {
            return "High".to_string();
        }
        return "Low".to_string();
    }
    if let Some(history) = history {
        if !history.has_prediction_file {
            return "High".to_string();
        }
    }
    "Medium".to_string()
}

fn calibration_risk_label(risk: Option<&ModelEvidenceRiskProfile>) -> String {
    match risk.map(|item| item.calibration_status.as_str()) {
        Some("Stable") => "Low".to_string(),
        Some("Review") => "High".to_string(),
        Some("InsufficientHistory") => "Medium".to_string(),
        Some(_) => "Medium".to_string(),
        None => "Medium".to_string(),
    }
}

fn drift_risk_label(risk: Option<&ModelEvidenceRiskProfile>) -> String {
    match risk.map(|item| item.drift_status.as_str()) {
        Some("Stable") => "Low".to_string(),
        Some("Mild") => "Medium".to_string(),
        Some("Severe") => "Critical".to_string(),
        Some("InsufficientHistory") => "High".to_string(),
        Some(_) => "Medium".to_string(),
        None => "Medium".to_string(),
    }
}

fn risk_behavior_label(risk: Option<&ModelEvidenceRiskProfile>) -> String {
    match risk.map(|item| item.risk_status.as_str()) {
        Some("Pass") => "Low".to_string(),
        Some("Review") => "High".to_string(),
        Some(_) => "Medium".to_string(),
        None => "Medium".to_string(),
    }
}

fn ablation_risk_label(risk: Option<&ModelEvidenceRiskProfile>) -> String {
    match risk.map(|item| item.ablation_status.as_str()) {
        Some("Stable") => "Low".to_string(),
        Some("Missing") => "High".to_string(),
        Some("Unstable") => "Critical".to_string(),
        Some(_) => "Medium".to_string(),
        None => "Medium".to_string(),
    }
}

fn comparability_risk_label(
    history: Option<&super::PredictionHistoryPackVersionRecord>,
    regression_text: &str,
) -> String {
    if regression_text.contains("comparability") {
        return "High".to_string();
    }
    if let Some(history) = history {
        if !history.comparable {
            return "High".to_string();
        }
        return "Low".to_string();
    }
    "Medium".to_string()
}

fn artifact_risk_label(completeness: Option<&ArtifactCompletenessScore>) -> String {
    match completeness.map(|item| item.completeness_status) {
        Some(ArtifactCompletenessStatus::Complete) => "Low".to_string(),
        Some(ArtifactCompletenessStatus::MostlyComplete) => "Low".to_string(),
        Some(ArtifactCompletenessStatus::Incomplete) => "High".to_string(),
        Some(ArtifactCompletenessStatus::MissingCriticalArtifacts) => "Critical".to_string(),
        _ => "Medium".to_string(),
    }
}

fn risk_bucket(label: &str) -> usize {
    match label {
        "Low" => 0,
        "Medium" => 1,
        "High" => 2,
        "Critical" => 3,
        "Blocked" => 4,
        _ => 1,
    }
}

fn base_risk_bucket(level: ModelEvidenceRiskLevel) -> usize {
    match level {
        ModelEvidenceRiskLevel::Low => 0,
        ModelEvidenceRiskLevel::Medium => 1,
        ModelEvidenceRiskLevel::High => 2,
        ModelEvidenceRiskLevel::Critical => 3,
        ModelEvidenceRiskLevel::DiagnosticOnly => 2,
    }
}

fn default_trace_output_root() -> String {
    "target/soma_model_ops_trace".to_string()
}

fn default_max_trace_edges() -> usize {
    48
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ModelOpsTraceConfig {
    pub trace_id: String,
    #[serde(default)]
    pub model_ops_rollup_paths: Vec<String>,
    #[serde(default)]
    pub model_version_summary_card_paths: Vec<String>,
    #[serde(default)]
    pub regression_explanation_paths: Vec<String>,
    #[serde(default)]
    pub operator_qa_rollup_paths: Vec<String>,
    #[serde(default)]
    pub decision_log_rollup_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_risk_rollup_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_action_priority_paths: Vec<String>,
    #[serde(default)]
    pub external_artifact_registry_paths: Vec<String>,
    #[serde(default)]
    pub external_model_research_ops_paths: Vec<String>,
    #[serde(default)]
    pub conservative_leaderboard_paths: Vec<String>,
    #[serde(default)]
    pub prediction_history_pack_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_regression_guard_paths: Vec<String>,
    #[serde(default)]
    pub baseline_artifact_paths: Vec<String>,
    #[serde(default)]
    pub current_artifact_paths: Vec<String>,
    #[serde(default = "default_trace_output_root")]
    pub output_root: String,
    #[serde(default = "default_max_models")]
    pub max_models: usize,
    #[serde(default = "default_max_versions")]
    pub max_versions: usize,
    #[serde(default = "default_max_trace_edges")]
    pub max_trace_edges: usize,
    #[serde(default = "default_max_artifacts")]
    pub max_artifacts: usize,
    #[serde(default = "default_max_bytes")]
    pub max_bytes: usize,
    #[serde(default = "default_true")]
    pub require_local_paths: bool,
    #[serde(default = "default_true")]
    pub generate_html_fragments: bool,
    #[serde(default)]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for ModelOpsTraceConfig {
    fn default() -> Self {
        Self {
            trace_id: "sprint68-model-ops-trace".to_string(),
            model_ops_rollup_paths: Vec::new(),
            model_version_summary_card_paths: Vec::new(),
            regression_explanation_paths: Vec::new(),
            operator_qa_rollup_paths: Vec::new(),
            decision_log_rollup_paths: Vec::new(),
            model_ops_risk_rollup_paths: Vec::new(),
            model_ops_action_priority_paths: Vec::new(),
            external_artifact_registry_paths: Vec::new(),
            external_model_research_ops_paths: Vec::new(),
            conservative_leaderboard_paths: Vec::new(),
            prediction_history_pack_paths: Vec::new(),
            model_ops_regression_guard_paths: Vec::new(),
            baseline_artifact_paths: Vec::new(),
            current_artifact_paths: Vec::new(),
            output_root: default_trace_output_root(),
            max_models: default_max_models(),
            max_versions: default_max_versions(),
            max_trace_edges: default_max_trace_edges(),
            max_artifacts: default_max_artifacts(),
            max_bytes: default_max_bytes(),
            require_local_paths: true,
            generate_html_fragments: true,
            reason_codes: stable_reason_codes(&[ReasonCode::ModelOpsTraceConfigBuilt]),
        }
    }
}

impl ModelOpsTraceConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let mut config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.reason_codes = stable_reason_codes(&[ReasonCode::ModelOpsTraceConfigBuilt]);
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.trace_id.trim().is_empty()
            || self.max_models == 0
            || self.max_versions == 0
            || self.max_trace_edges == 0
            || self.max_artifacts == 0
            || self.max_bytes == 0
        {
            return Err("model ops trace config requires trace_id and positive limits".to_string());
        }
        if self.require_local_paths && self.input_paths().iter().any(|path| path.contains("://")) {
            return Err("model ops trace config paths must be local".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.trace_id)
    }

    pub fn input_paths(&self) -> Vec<String> {
        self.model_ops_rollup_paths
            .iter()
            .chain(self.model_version_summary_card_paths.iter())
            .chain(self.regression_explanation_paths.iter())
            .chain(self.operator_qa_rollup_paths.iter())
            .chain(self.decision_log_rollup_paths.iter())
            .chain(self.model_ops_risk_rollup_paths.iter())
            .chain(self.model_ops_action_priority_paths.iter())
            .chain(self.external_artifact_registry_paths.iter())
            .chain(self.external_model_research_ops_paths.iter())
            .chain(self.conservative_leaderboard_paths.iter())
            .chain(self.prediction_history_pack_paths.iter())
            .chain(self.model_ops_regression_guard_paths.iter())
            .chain(self.baseline_artifact_paths.iter())
            .chain(self.current_artifact_paths.iter())
            .cloned()
            .collect()
    }
}

