fn register_trace_artifacts(
    artifacts: &mut Vec<TraceArtifactRef>,
    by_model_version: &mut BTreeMap<String, Vec<String>>,
    unsafe_artifacts: &mut Vec<String>,
    config: &ModelOpsTraceConfig,
    paths: &[String],
    kind: TraceArtifactKind,
    keys: &BTreeSet<String>,
) {
    for path in paths {
        if is_unsafe_artifact_path(path) {
            unsafe_artifacts.push(path.clone());
            continue;
        }
        for key in keys {
            let Some((model_id, model_version)) = key.split_once(':') else {
                continue;
            };
            let artifact = build_trace_artifact(
                config,
                kind,
                path,
                Some(model_id),
                Some(model_version),
                None,
                format!("{:?} backing {}", kind, key),
            );
            by_model_version
                .entry(key.clone())
                .or_default()
                .push(artifact.artifact_id.clone());
            artifacts.push(artifact);
        }
    }
}

fn register_card_artifacts(
    artifacts: &mut Vec<TraceArtifactRef>,
    by_model_version: &mut BTreeMap<String, Vec<String>>,
    unsafe_artifacts: &mut Vec<String>,
    config: &ModelOpsTraceConfig,
    paths: &[String],
    cards: &[ModelVersionSummaryCard],
) {
    for path in paths {
        if is_unsafe_artifact_path(path) {
            unsafe_artifacts.push(path.clone());
            continue;
        }
        for card in cards {
            let artifact = build_trace_artifact(
                config,
                TraceArtifactKind::ModelVersionSummaryCard,
                path,
                Some(&card.rollup_key.model_id),
                Some(&card.rollup_key.model_version),
                card.rollup_key.dataset_fingerprint.clone(),
                format!(
                    "{:?} card for {}",
                    card.recommended_action, card.display_name
                ),
            );
            by_model_version
                .entry(card.display_name.clone())
                .or_default()
                .push(artifact.artifact_id.clone());
            artifacts.push(artifact);
        }
    }
}

fn register_regression_artifacts(
    artifacts: &mut Vec<TraceArtifactRef>,
    by_model_version: &mut BTreeMap<String, Vec<String>>,
    unsafe_artifacts: &mut Vec<String>,
    config: &ModelOpsTraceConfig,
    paths: &[String],
    regression: Option<&RegressionCauseExplanationReport>,
) {
    let Some(regression) = regression else {
        return;
    };
    for path in paths {
        if is_unsafe_artifact_path(path) {
            unsafe_artifacts.push(path.clone());
            continue;
        }
        for explanation in &regression.explanations {
            let key = format!("{}:{}", explanation.model_id, explanation.model_version);
            let artifact = build_trace_artifact(
                config,
                TraceArtifactKind::RegressionExplanation,
                path,
                Some(&explanation.model_id),
                Some(&explanation.model_version),
                None,
                explanation.human_summary.clone(),
            );
            by_model_version
                .entry(key)
                .or_default()
                .push(artifact.artifact_id.clone());
            artifacts.push(artifact);
        }
    }
}

