fn snapshot_ref_map<'a>(
    refs: &'a [ModelOpsSnapshotRef],
) -> BTreeMap<String, &'a ModelOpsSnapshotRef> {
    refs.iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect()
}

fn versions_by_model(keys: &BTreeSet<String>) -> BTreeMap<&str, Vec<&str>> {
    let mut map = BTreeMap::new();
    for key in keys {
        let Some((model_id, model_version)) = key.split_once(':') else {
            continue;
        };
        map.entry(model_id)
            .or_insert_with(Vec::new)
            .push(model_version);
    }
    for versions in map.values_mut() {
        versions.sort_by_key(|version| compare_versionish_key(version));
    }
    map
}

fn resolve_comparison_target<'a>(
    config: &BaselineSnapshotCoverageConfig,
    key: &str,
    card: Option<&ModelVersionSummaryCard>,
    baseline_map: &BTreeMap<String, &'a ModelOpsSnapshotRef>,
    current_map: &BTreeMap<String, &'a ModelOpsSnapshotRef>,
    versions: Option<&Vec<&str>>,
) -> ComparisonResolution {
    let has_card = card.is_some();
    let baseline = baseline_map.get(key).copied();
    let current = current_map.get(key).copied();
    let Some((model_id, model_version)) = key.split_once(':') else {
        return ComparisonResolution {
            kind: ComparisonTargetKind::Missing,
            baseline_snapshot_id: None,
            current_snapshot_id: None,
            previous_model_version: None,
            comparable: false,
            diagnostic_only: false,
        };
    };
    if !has_card && baseline.is_none() && current.is_none() {
        return ComparisonResolution {
            kind: ComparisonTargetKind::Missing,
            baseline_snapshot_id: None,
            current_snapshot_id: None,
            previous_model_version: None,
            comparable: false,
            diagnostic_only: false,
        };
    }
    let previous_model_version = versions
        .and_then(|versions| previous_version_for(model_version, versions).map(str::to_string));
    let previous_key = previous_model_version
        .as_ref()
        .map(|version| format!("{model_id}:{version}"));
    let previous_available = previous_key
        .as_ref()
        .is_some_and(|key| baseline_map.contains_key(key) || current_map.contains_key(key));
    let contract_match = snapshot_contract_match(baseline, current, card);
    if !contract_match {
        return ComparisonResolution {
            kind: ComparisonTargetKind::Missing,
            baseline_snapshot_id: baseline.map(|item| item.snapshot_id.clone()),
            current_snapshot_id: current.map(|item| item.snapshot_id.clone()),
            previous_model_version,
            comparable: false,
            diagnostic_only: false,
        };
    }
    if baseline.is_some() && (!config.require_current_snapshot || current.is_some()) {
        return ComparisonResolution {
            kind: ComparisonTargetKind::Baseline,
            baseline_snapshot_id: baseline.map(|item| item.snapshot_id.clone()),
            current_snapshot_id: current.map(|item| item.snapshot_id.clone()),
            previous_model_version,
            comparable: true,
            diagnostic_only: false,
        };
    }
    if previous_available && current.is_some() {
        return ComparisonResolution {
            kind: ComparisonTargetKind::PreviousVersion,
            baseline_snapshot_id: baseline.map(|item| item.snapshot_id.clone()),
            current_snapshot_id: current.map(|item| item.snapshot_id.clone()),
            previous_model_version,
            comparable: true,
            diagnostic_only: false,
        };
    }
    if current.is_some() && config.allow_current_only_diagnostic {
        return ComparisonResolution {
            kind: ComparisonTargetKind::CurrentOnlyDiagnostic,
            baseline_snapshot_id: baseline.map(|item| item.snapshot_id.clone()),
            current_snapshot_id: current.map(|item| item.snapshot_id.clone()),
            previous_model_version,
            comparable: false,
            diagnostic_only: true,
        };
    }
    if current.is_some() {
        return ComparisonResolution {
            kind: ComparisonTargetKind::SameVersionCurrent,
            baseline_snapshot_id: None,
            current_snapshot_id: current.map(|item| item.snapshot_id.clone()),
            previous_model_version,
            comparable: false,
            diagnostic_only: false,
        };
    }
    if config.require_current_snapshot && current.is_none() {
        return ComparisonResolution {
            kind: ComparisonTargetKind::Missing,
            baseline_snapshot_id: baseline.map(|item| item.snapshot_id.clone()),
            current_snapshot_id: None,
            previous_model_version,
            comparable: false,
            diagnostic_only: false,
        };
    }
    ComparisonResolution {
        kind: ComparisonTargetKind::Missing,
        baseline_snapshot_id: baseline.map(|item| item.snapshot_id.clone()),
        current_snapshot_id: current.map(|item| item.snapshot_id.clone()),
        previous_model_version,
        comparable: false,
        diagnostic_only: false,
    }
}

fn previous_version_for<'a>(current: &str, versions: &'a [&str]) -> Option<&'a str> {
    let position = versions.iter().position(|version| *version == current)?;
    position.checked_sub(1).map(|index| versions[index])
}

fn compare_versionish_key(version: &str) -> Vec<(u8, String)> {
    version
        .split('.')
        .map(|segment| {
            if let Ok(number) = segment.parse::<u64>() {
                (0, format!("{number:020}"))
            } else {
                (1, segment.to_string())
            }
        })
        .collect()
}

fn baseline_coverage_missing_reason(
    config: &BaselineSnapshotCoverageConfig,
    record: &ComparisonTargetRecord,
) -> Option<String> {
    if record.diagnostic_only {
        Some("CurrentOnlyDiagnosticAllowed".to_string())
    } else if record.comparable {
        None
    } else if record.current_snapshot_id.is_none() && config.require_current_snapshot {
        Some("MissingCurrentSnapshot".to_string())
    } else if record.baseline_snapshot_id.is_none()
        && config.require_baseline_for_comparable_versions
    {
        Some("MissingBaselineSnapshot".to_string())
    } else if matches!(
        record.comparison_target_kind,
        ComparisonTargetKind::SameVersionCurrent
    ) {
        Some("SameVersionCurrentWithoutBaseline".to_string())
    } else {
        Some("MissingComparisonTarget".to_string())
    }
}

fn missing_kind_for_record(
    context: &BaselineSnapshotCoverageContext,
    diff: Option<&ModelVersionDiffTrace>,
    record: &ComparisonTargetRecord,
    key: &str,
) -> MissingComparisonTargetKind {
    if record.comparable {
        return MissingComparisonTargetKind::NoMissingTarget;
    }
    if record.diagnostic_only {
        return MissingComparisonTargetKind::CurrentOnlyDiagnosticAllowed;
    }
    if context
        .unsafe_snapshot_paths
        .iter()
        .any(|path| key.contains(path) || !context.unsafe_snapshot_paths.is_empty())
        && record.baseline_snapshot_id.is_none()
        && record.current_snapshot_id.is_none()
    {
        return MissingComparisonTargetKind::UnsafeArtifact;
    }
    if matches!(
        diff.map(|item| item.diff_status),
        Some(ModelVersionDiffStatus::MissingComparisonTarget)
    ) && record.baseline_snapshot_id.is_some()
    {
        return MissingComparisonTargetKind::NoMissingTarget;
    }
    if matches!(
        record.comparison_target_kind,
        ComparisonTargetKind::SameVersionCurrent
    ) {
        return MissingComparisonTargetKind::MissingBaselineSnapshot;
    }
    if record.current_snapshot_id.is_none() {
        return MissingComparisonTargetKind::MissingCurrentSnapshot;
    }
    if record.previous_model_version.is_none() && record.baseline_snapshot_id.is_none() {
        return MissingComparisonTargetKind::MissingPreviousVersion;
    }
    MissingComparisonTargetKind::UnknownModelVersion
}

fn required_artifact_for_missing_kind(kind: MissingComparisonTargetKind) -> String {
    match kind {
        MissingComparisonTargetKind::MissingBaselineSnapshot => "baseline_snapshot".to_string(),
        MissingComparisonTargetKind::MissingCurrentSnapshot => "current_snapshot".to_string(),
        MissingComparisonTargetKind::MissingPreviousVersion => {
            "previous_version_snapshot".to_string()
        }
        MissingComparisonTargetKind::ContractMismatch => "matching_contract_snapshot".to_string(),
        MissingComparisonTargetKind::UnsafeArtifact => "safe_local_snapshot".to_string(),
        MissingComparisonTargetKind::UnknownModelVersion => {
            "model_version_summary_card".to_string()
        }
        MissingComparisonTargetKind::CurrentOnlyDiagnosticAllowed => {
            "current_only_diagnostic_marker".to_string()
        }
        MissingComparisonTargetKind::NoMissingTarget => "none".to_string(),
    }
}

