#[allow(clippy::too_many_arguments)]
fn trace_dimension_presence(
    key: &str,
    dimension: TraceCompletenessDimension,
    bundle_index: Option<&ModelOpsArtifactTraceIndex>,
    graph: Option<&ModelCardTraceGraph>,
    card_keys: &BTreeSet<String>,
    decision_keys: &BTreeSet<String>,
    regression_keys: &BTreeSet<String>,
    diff_keys: &BTreeSet<String>,
    qa_keys: &BTreeSet<String>,
    action_keys: &BTreeSet<String>,
    baseline_map: &BTreeMap<String, &ModelOpsSnapshotRef>,
    current_map: &BTreeMap<String, &ModelOpsSnapshotRef>,
    leaderboard_keys: &BTreeSet<String>,
    external_ops_keys: &BTreeSet<String>,
    prediction_keys: &BTreeSet<String>,
    registry_record: Option<&ComparisonTargetRecord>,
) -> (bool, Option<String>, Option<String>) {
    let artifact = match dimension {
        TraceCompletenessDimension::SummaryCard => artifact_for_kind(
            bundle_index,
            key,
            TraceArtifactKind::ModelVersionSummaryCard,
        ),
        TraceCompletenessDimension::ModelCard => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::ModelCard)
        }
        TraceCompletenessDimension::DecisionLog => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::DecisionLogRollup)
        }
        TraceCompletenessDimension::RegressionEvidence => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::RegressionExplanation)
        }
        TraceCompletenessDimension::OperatorQA => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::OperatorQARollup)
        }
        TraceCompletenessDimension::ActionPriority => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::ActionPriority)
        }
        TraceCompletenessDimension::RiskRollup => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::RiskRollup)
        }
        TraceCompletenessDimension::BaselineSnapshot => {
            baseline_map.get(key).map(|item| item.snapshot_id.clone())
        }
        TraceCompletenessDimension::CurrentSnapshot => {
            current_map.get(key).map(|item| item.snapshot_id.clone())
        }
        TraceCompletenessDimension::Leaderboard => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::Leaderboard)
        }
        TraceCompletenessDimension::Registry => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::Registry)
        }
        TraceCompletenessDimension::PredictionHistory => {
            artifact_for_kind(bundle_index, key, TraceArtifactKind::PredictionHistory)
        }
        TraceCompletenessDimension::OwnerReview => None,
        TraceCompletenessDimension::MambaDeferredState => None,
    };
    let present = match dimension {
        TraceCompletenessDimension::SummaryCard => card_keys.contains(key) || artifact.is_some(),
        TraceCompletenessDimension::ModelCard => artifact.is_some(),
        TraceCompletenessDimension::DecisionLog => {
            decision_keys.contains(key) || artifact.is_some()
        }
        TraceCompletenessDimension::RegressionEvidence => {
            regression_keys.contains(key) || diff_keys.contains(key) || artifact.is_some()
        }
        TraceCompletenessDimension::OperatorQA => qa_keys.contains(key) || artifact.is_some(),
        TraceCompletenessDimension::ActionPriority => {
            action_keys.contains(key) || artifact.is_some()
        }
        TraceCompletenessDimension::RiskRollup => artifact.is_some(),
        TraceCompletenessDimension::BaselineSnapshot => baseline_map.contains_key(key),
        TraceCompletenessDimension::CurrentSnapshot => current_map.contains_key(key),
        TraceCompletenessDimension::Leaderboard => {
            leaderboard_keys.contains(key) || artifact.is_some()
        }
        TraceCompletenessDimension::Registry => {
            external_ops_keys.contains(key) || artifact.is_some() || registry_record.is_some()
        }
        TraceCompletenessDimension::PredictionHistory => {
            prediction_keys.contains(key) || artifact.is_some()
        }
        TraceCompletenessDimension::OwnerReview => {
            graph.is_some_and(|graph| graph.nodes.iter().any(|node| node.title.contains("Owner")))
                || decision_keys.contains(key)
        }
        TraceCompletenessDimension::MambaDeferredState => graph.is_some_and(|graph| {
            graph
                .nodes
                .iter()
                .any(|node| node.node_kind == TraceNodeKind::MambaDeferredState)
        }),
    };
    let missing_reason = if present {
        None
    } else {
        Some(format!("missing {:?}", dimension))
    };
    (present, artifact, missing_reason)
}

fn artifact_for_kind(
    bundle_index: Option<&ModelOpsArtifactTraceIndex>,
    key: &str,
    kind: TraceArtifactKind,
) -> Option<String> {
    bundle_index.and_then(|index| first_artifact_id(index, key, kind))
}

fn group_cells_by_key(
    cells: &[TraceCompletenessCell],
) -> BTreeMap<String, Vec<&TraceCompletenessCell>> {
    let mut map = BTreeMap::new();
    for cell in cells {
        map.entry(format!("{}:{}", cell.model_id, cell.model_version))
            .or_insert_with(Vec::new)
            .push(cell);
    }
    map
}

fn has_missing_dimension(
    cells: &[TraceCompletenessCell],
    dimension: TraceCompletenessDimension,
) -> bool {
    cells
        .iter()
        .any(|cell| cell.dimension == dimension && !cell.present)
}

fn downgrade_recommendation_for(
    card: Option<&ModelVersionSummaryCard>,
    action: Option<&ActionPriorityTrace>,
    record: Option<&ComparisonTargetRecord>,
) -> Option<String> {
    if card.is_some_and(|card| {
        card.recommended_action == ModelVersionSummaryStatus::RetireModelVersion
    }) {
        return Some("RetireModelVersion".to_string());
    }
    if card.is_some_and(|card| {
        card.recommended_action == ModelVersionSummaryStatus::DowngradeToDiagnostic
    }) {
        return Some("DowngradeToDiagnostic".to_string());
    }
    if action.is_some_and(|item| item.action == ModelOpsDecisionKind::RetireModelVersion) {
        return Some("RetireModelVersion".to_string());
    }
    if record.is_some_and(|item| item.diagnostic_only) {
        return Some("DowngradeToDiagnostic".to_string());
    }
    None
}

fn downgrade_evidence_present(
    key: &str,
    regression: Option<&Vec<&RegressionEvidenceTrace>>,
    conflicts: Option<&Vec<&DecisionConflictTrace>>,
    baseline: Option<&ModelOpsSnapshotRef>,
    current: Option<&ModelOpsSnapshotRef>,
) -> Vec<DowngradeEvidenceRequirement> {
    let mut present = BTreeSet::new();
    if regression.is_some_and(|items| !items.is_empty()) {
        present.insert(DowngradeEvidenceRequirement::RegressionEvidence);
    }
    if baseline.is_some() || current.is_some() {
        present.insert(DowngradeEvidenceRequirement::RiskEvidence);
        present.insert(DowngradeEvidenceRequirement::CoverageEvidence);
        present.insert(DowngradeEvidenceRequirement::ArtifactCompletenessEvidence);
    }
    if regression.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::CalibrationRegression)
    }) {
        present.insert(DowngradeEvidenceRequirement::CalibrationEvidence);
    }
    if regression.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::ComparabilityRegression)
    }) {
        present.insert(DowngradeEvidenceRequirement::ComparabilityEvidence);
    }
    if conflicts.is_some_and(|items| !items.is_empty()) {
        present.insert(DowngradeEvidenceRequirement::DecisionConflictEvidence);
    }
    if conflicts.is_some_and(|items| {
        items.iter().any(|item| {
            item.recommended_resolution == DecisionConflictResolution::RequestOwnerReview
        })
    }) || key.contains("owner")
    {
        present.insert(DowngradeEvidenceRequirement::OwnerReviewEvidence);
    }
    present.into_iter().collect()
}

fn required_downgrade_evidence(
    recommendation: Option<&str>,
    regression: Option<&Vec<&RegressionEvidenceTrace>>,
) -> Vec<DowngradeEvidenceRequirement> {
    let mut required = vec![
        DowngradeEvidenceRequirement::RegressionEvidence,
        DowngradeEvidenceRequirement::RiskEvidence,
    ];
    if regression.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::CalibrationRegression)
    }) {
        required.push(DowngradeEvidenceRequirement::CalibrationEvidence);
    }
    if regression.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::CoverageRegression)
    }) {
        required.push(DowngradeEvidenceRequirement::CoverageEvidence);
    }
    if regression.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::ComparabilityRegression)
    }) {
        required.push(DowngradeEvidenceRequirement::ComparabilityEvidence);
    }
    if regression.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::ArtifactCompletenessRegression)
    }) || recommendation == Some("RetireModelVersion")
    {
        required.push(DowngradeEvidenceRequirement::ArtifactCompletenessEvidence);
    }
    if recommendation == Some("RetireModelVersion") {
        required.push(DowngradeEvidenceRequirement::DecisionConflictEvidence);
    }
    required.sort_by_key(|item| format!("{:?}", item));
    required.dedup();
    required
}

fn snapshot_contract_fingerprint(snapshot: &ModelOpsSnapshotRef) -> String {
    stable_hash_string(&format!(
        "{}:{}:{}",
        snapshot.dataset_fingerprint.clone().unwrap_or_default(),
        snapshot.feature_schema_hash.clone().unwrap_or_default(),
        snapshot.label_manifest_hash.clone().unwrap_or_default()
    ))
}

fn snapshot_contract_match(
    baseline: Option<&ModelOpsSnapshotRef>,
    current: Option<&ModelOpsSnapshotRef>,
    card: Option<&ModelVersionSummaryCard>,
) -> bool {
    let Some(card) = card else {
        return baseline.is_none() || current.is_none() || baseline.zip(current).is_some();
    };
    let baseline_match = baseline.is_none_or(|snapshot| {
        optional_field_matches(
            snapshot.dataset_fingerprint.as_deref(),
            card.rollup_key.dataset_fingerprint.as_deref(),
        ) && optional_field_matches(
            snapshot.feature_schema_hash.as_deref(),
            card.rollup_key.feature_schema_hash.as_deref(),
        ) && optional_field_matches(
            snapshot.label_manifest_hash.as_deref(),
            card.rollup_key.label_manifest_hash.as_deref(),
        )
    });
    let current_match = current.is_none_or(|snapshot| {
        optional_field_matches(
            snapshot.dataset_fingerprint.as_deref(),
            card.rollup_key.dataset_fingerprint.as_deref(),
        ) && optional_field_matches(
            snapshot.feature_schema_hash.as_deref(),
            card.rollup_key.feature_schema_hash.as_deref(),
        ) && optional_field_matches(
            snapshot.label_manifest_hash.as_deref(),
            card.rollup_key.label_manifest_hash.as_deref(),
        )
    });
    baseline_match && current_match
}

fn optional_field_matches(left: Option<&str>, right: Option<&str>) -> bool {
    match (left, right) {
        (Some(left), Some(right)) => left == right,
        _ => true,
    }
}

fn stable_ratio_string(numerator: usize, denominator: usize) -> String {
    if denominator == 0 {
        return "0.0000".to_string();
    }
    format!("{:.4}", numerator as f64 / denominator as f64)
}

fn next_trace_coverage_actions(
    missing_report: &MissingComparisonTargetReport,
    downgrade_audit: &ConservativeDowngradeEvidenceAudit,
    diff_integrity: &SnapshotDiffIntegrityReport,
) -> Vec<String> {
    let mut actions = Vec::new();
    for item in &missing_report.items {
        match item.suggested_action {
            MissingComparisonSuggestedAction::ProvideBaselineSnapshot => actions.push(format!(
                "ProvideBaselineSnapshot:{}:{}",
                item.model_id, item.model_version
            )),
            MissingComparisonSuggestedAction::ProvideCurrentSnapshot => actions.push(format!(
                "ProvideCurrentSnapshot:{}:{}",
                item.model_id, item.model_version
            )),
            MissingComparisonSuggestedAction::ProvidePreviousVersionSnapshot => {
                actions.push(format!(
                    "ProvidePreviousVersionSnapshot:{}:{}",
                    item.model_id, item.model_version
                ))
            }
            MissingComparisonSuggestedAction::FixContractMismatch => actions.push(format!(
                "FixContractMismatch:{}:{}",
                item.model_id, item.model_version
            )),
            MissingComparisonSuggestedAction::MarkCurrentOnlyDiagnostic => actions.push(format!(
                "MarkCurrentOnlyDiagnostic:{}:{}",
                item.model_id, item.model_version
            )),
            MissingComparisonSuggestedAction::NoAction => {}
        }
    }
    for item in &downgrade_audit.items {
        if item.downgrade_recommendation.is_some() && !item.missing_evidence.is_empty() {
            actions.push(format!(
                "RequestMorePredictions:{}:{}",
                item.model_id, item.model_version
            ));
        }
    }
    for item in &diff_integrity.items {
        if item.diff_status == SnapshotDiffIntegrityStatus::UnexpectedDiff {
            actions.push(format!(
                "RequestOwnerReview:{}:{}",
                item.model_id, item.model_version
            ));
        }
    }
    stable_ordered_strings(&actions)
}

fn render_trace_coverage_overview_fragment(report: &BaselineSnapshotCoverageReport) -> String {
    let items = report
        .items
        .iter()
        .map(|item| {
            format!(
                "<li>{}: baseline={} current={} target={} diagnostic={}</li>",
                html_escape(&format!("{}:{}", item.model_id, item.model_version)),
                item.has_baseline_snapshot,
                item.has_current_snapshot,
                item.comparison_target_available,
                item.current_only_diagnostic
            )
        })
        .collect::<Vec<_>>()
        .join("");
    format!(
        "<section><h1>baseline snapshot coverage</h1><p>static/read-only local coverage overview</p><p>status={:?};ratio={}</p><ul>{}</ul></section>",
        report.coverage_status,
        html_escape(&report.coverage_ratio),
        items
    )
}

