fn default_unexpected_diff_triage_output_root() -> String {
    "target/soma_unexpected_diff_triage".to_string()
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct UnexpectedDiffTriageConfig {
    pub triage_id: String,
    pub coverage_config_path: String,
    #[serde(default = "default_unexpected_diff_triage_output_root")]
    pub output_root: String,
    #[serde(default = "default_true")]
    pub render_static_fragments: bool,
    #[serde(default)]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for UnexpectedDiffTriageConfig {
    fn default() -> Self {
        Self {
            triage_id: "sprint70-unexpected-diff-triage".to_string(),
            coverage_config_path: "examples/soma_baseline_snapshot_coverage.toml".to_string(),
            output_root: default_unexpected_diff_triage_output_root(),
            render_static_fragments: true,
            reason_codes: stable_reason_codes(&[ReasonCode::UnexpectedDiffTriageConfigBuilt]),
        }
    }
}

impl UnexpectedDiffTriageConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let mut config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.reason_codes = stable_reason_codes(&[ReasonCode::UnexpectedDiffTriageConfigBuilt]);
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.triage_id.trim().is_empty() || self.coverage_config_path.trim().is_empty() {
            return Err(
                "unexpected diff triage config requires triage_id and local coverage_config_path"
                    .to_string(),
            );
        }
        if self.coverage_config_path.contains("://") || self.output_root.contains("://") {
            return Err("unexpected diff triage config paths must be local".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.triage_id)
    }

    pub fn load_coverage_config(&self) -> Result<BaselineSnapshotCoverageConfig, String> {
        let config =
            BaselineSnapshotCoverageConfig::from_toml_path(Path::new(&self.coverage_config_path))?;
        config.validate()?;
        Ok(config)
    }
}

