#[derive(Clone, Debug, Default)]
pub struct UnexpectedDiffTriageRunner;

impl UnexpectedDiffTriageRunner {
    pub fn run(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<UnexpectedDiffTriageBundle, String> {
        config.validate()?;
        let coverage_config = config.load_coverage_config()?;
        let coverage_bundle = BaselineSnapshotCoverageRunner::default().run(&coverage_config)?;
        let context = load_baseline_snapshot_coverage_context(&coverage_config)?;
        let unexpected_keys =
            collect_unexpected_diff_keys(&coverage_bundle.snapshot_diff_integrity_report);
        let classification_report =
            build_snapshot_diff_classification_report(config, &context, &unexpected_keys);
        let contract_alignment_audit_v2 =
            build_contract_alignment_audit_v2(config, &context, &unexpected_keys);
        let downgrade_evidence_closure_plan = build_downgrade_evidence_closure_plan(
            config,
            &coverage_bundle.conservative_downgrade_evidence_audit,
            &classification_report,
        );
        let owner_review_closure_v2_report = build_owner_review_closure_v2_report(
            config,
            &coverage_bundle.trace_completeness_audit,
            &coverage_bundle.conservative_downgrade_evidence_audit,
            &classification_report,
            &context,
        );
        let trace_completeness_warning_reduction_report =
            build_trace_completeness_warning_reduction_report(
                config,
                &coverage_bundle.trace_completeness_audit,
                &owner_review_closure_v2_report,
            );
        let diff_root_cause_report = build_diff_root_cause_report(
            config,
            &context,
            &classification_report,
            &contract_alignment_audit_v2,
        );
        let model_version_review_disposition_report = build_model_version_review_disposition_report(
            config,
            &coverage_bundle.baseline_snapshot_coverage_report,
            &owner_review_closure_v2_report,
            &trace_completeness_warning_reduction_report,
            &downgrade_evidence_closure_plan,
        );
        let unexpected_diff_triage_report = build_unexpected_diff_triage_report(
            config,
            &classification_report,
            &contract_alignment_audit_v2,
            &owner_review_closure_v2_report,
            &diff_root_cause_report,
        );
        let control_tower_diff_triage_panel = build_control_tower_diff_triage_panel(
            config,
            &unexpected_diff_triage_report,
            &contract_alignment_audit_v2,
            &owner_review_closure_v2_report,
            &trace_completeness_warning_reduction_report,
            &downgrade_evidence_closure_plan,
            &model_version_review_disposition_report,
        );
        let mut static_fragments = if config.render_static_fragments {
            Some(write_unexpected_diff_triage_fragments(
                config,
                &unexpected_diff_triage_report,
                &contract_alignment_audit_v2,
                &owner_review_closure_v2_report,
                &trace_completeness_warning_reduction_report,
                &downgrade_evidence_closure_plan,
            )?)
        } else {
            None
        };
        if let Some(fragments) = static_fragments.as_mut() {
            *fragments = fragments
                .iter()
                .map(|(key, value)| (key.clone(), value.clone()))
                .collect::<BTreeMap<_, _>>();
        }
        let final_summary = build_unexpected_diff_triage_final_summary(
            &unexpected_diff_triage_report,
            &contract_alignment_audit_v2,
            &owner_review_closure_v2_report,
            &trace_completeness_warning_reduction_report,
            &downgrade_evidence_closure_plan,
            &control_tower_diff_triage_panel,
        );
        let bundle = UnexpectedDiffTriageBundle {
            baseline_snapshot_coverage_bundle: coverage_bundle,
            unexpected_diff_triage_report,
            snapshot_diff_classification_report: classification_report,
            contract_alignment_audit_v2,
            owner_review_closure_v2_report,
            trace_completeness_warning_reduction_report,
            downgrade_evidence_closure_plan,
            diff_root_cause_report,
            model_version_review_disposition_report,
            control_tower_diff_triage_panel,
            static_fragments,
            final_summary,
            reason_codes: stable_reason_codes(&[
                ReasonCode::UnexpectedDiffTriageRunnerBuilt,
                ReasonCode::UnexpectedDiffTriageBundleBuilt,
            ]),
        };
        write_unexpected_diff_triage_bundle(config, &bundle)?;
        Ok(bundle)
    }

    pub fn run_unexpected_diff_triage(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<UnexpectedDiffTriageReport, String> {
        Ok(self.run(config)?.unexpected_diff_triage_report)
    }

    pub fn run_snapshot_diff_classification(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<SnapshotDiffClassificationReport, String> {
        Ok(self.run(config)?.snapshot_diff_classification_report)
    }

    pub fn run_contract_alignment_audit_v2(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<ContractAlignmentAuditV2, String> {
        Ok(self.run(config)?.contract_alignment_audit_v2)
    }

    pub fn run_owner_review_closure_v2(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<OwnerReviewClosureV2Report, String> {
        Ok(self.run(config)?.owner_review_closure_v2_report)
    }

    pub fn run_trace_warning_reduction(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<TraceCompletenessWarningReductionReport, String> {
        Ok(self
            .run(config)?
            .trace_completeness_warning_reduction_report)
    }

    pub fn run_downgrade_evidence_closure_plan(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<DowngradeEvidenceClosurePlan, String> {
        Ok(self.run(config)?.downgrade_evidence_closure_plan)
    }

    pub fn run_diff_root_cause(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<DiffRootCauseReport, String> {
        Ok(self.run(config)?.diff_root_cause_report)
    }

    pub fn run_model_version_review_disposition(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<ModelVersionReviewDispositionReport, String> {
        Ok(self.run(config)?.model_version_review_disposition_report)
    }

    pub fn run_control_tower_diff_triage(
        &self,
        config: &UnexpectedDiffTriageConfig,
    ) -> Result<ControlTowerDiffTriagePanel, String> {
        Ok(self.run(config)?.control_tower_diff_triage_panel)
    }
}

fn collect_unexpected_diff_keys(report: &SnapshotDiffIntegrityReport) -> BTreeSet<String> {
    report
        .items
        .iter()
        .filter(|item| item.diff_status == SnapshotDiffIntegrityStatus::UnexpectedDiff)
        .map(|item| format!("{}:{}", item.model_id, item.model_version))
        .collect()
}

fn build_snapshot_diff_classification_report(
    config: &UnexpectedDiffTriageConfig,
    context: &BaselineSnapshotCoverageContext,
    keys: &BTreeSet<String>,
) -> SnapshotDiffClassificationReport {
    let diff_map = diff_trace_map(context.diff_trace_report.as_ref());
    let conflict_map = decision_conflict_map(context.decision_conflict_trace_report.as_ref());
    let baseline_map = snapshot_ref_map(&context.baseline_snapshot_refs);
    let current_map = snapshot_ref_map(&context.current_snapshot_refs);
    let card_map = summary_card_map(&context.cards);
    let mut items = Vec::new();
    for key in keys {
        let Some((model_id, model_version)) = key.split_once(':') else {
            continue;
        };
        let classification = classify_unexpected_diff(
            diff_map.get(key).copied(),
            baseline_map.get(key).copied(),
            current_map.get(key).copied(),
            card_map.get(key).copied(),
            conflict_map.get(key),
        );
        items.push(SnapshotDiffClassificationItem {
            model_id: model_id.to_string(),
            model_version: model_version.to_string(),
            classification,
            supporting_signals: classification_supporting_signals(
                diff_map.get(key).copied(),
                baseline_map.get(key).copied(),
                current_map.get(key).copied(),
                card_map.get(key).copied(),
                conflict_map.get(key),
            ),
            reason_codes: stable_reason_codes(&[ReasonCode::SnapshotDiffClassificationReportBuilt]),
        });
    }
    items.sort_by(|left, right| {
        (
            left.model_id.clone(),
            compare_versionish_key(&left.model_version),
        )
            .cmp(&(
                right.model_id.clone(),
                compare_versionish_key(&right.model_version),
            ))
    });
    let classified_count = items.len();
    let unknown_count = items
        .iter()
        .filter(|item| item.classification == UnexpectedDiffClassification::UnknownUnexpectedDiff)
        .count();
    let report_status = if items.is_empty() {
        UnexpectedDiffTriageStatus::NoUnexpectedDiffs
    } else if unknown_count == 0 {
        UnexpectedDiffTriageStatus::UnexpectedDiffExplained
    } else {
        UnexpectedDiffTriageStatus::UnexpectedDiffNeedsReview
    };
    SnapshotDiffClassificationReport {
        classification_id: format!("{}-classification", config.triage_id),
        items,
        classified_count,
        unknown_count,
        report_status,
        reason_codes: stable_reason_codes(&[ReasonCode::SnapshotDiffClassificationReportBuilt]),
    }
}

fn build_contract_alignment_audit_v2(
    config: &UnexpectedDiffTriageConfig,
    context: &BaselineSnapshotCoverageContext,
    keys: &BTreeSet<String>,
) -> ContractAlignmentAuditV2 {
    let baseline_map = snapshot_ref_map(&context.baseline_snapshot_refs);
    let current_map = snapshot_ref_map(&context.current_snapshot_refs);
    let card_map = summary_card_map(&context.cards);
    let mut items = Vec::new();
    for key in keys {
        let Some((model_id, model_version)) = key.split_once(':') else {
            continue;
        };
        let baseline = baseline_map.get(key).copied();
        let current = current_map.get(key).copied();
        let card = card_map.get(key).copied();
        let baseline_dataset = resolved_contract_value(
            baseline.and_then(|item| item.dataset_fingerprint.as_deref()),
            card.and_then(|item| item.rollup_key.dataset_fingerprint.as_deref()),
        );
        let current_dataset = resolved_contract_value(
            current.and_then(|item| item.dataset_fingerprint.as_deref()),
            card.and_then(|item| item.rollup_key.dataset_fingerprint.as_deref()),
        );
        let baseline_feature = resolved_contract_value(
            baseline.and_then(|item| item.feature_schema_hash.as_deref()),
            card.and_then(|item| item.rollup_key.feature_schema_hash.as_deref()),
        );
        let current_feature = resolved_contract_value(
            current.and_then(|item| item.feature_schema_hash.as_deref()),
            card.and_then(|item| item.rollup_key.feature_schema_hash.as_deref()),
        );
        let baseline_label = resolved_contract_value(
            baseline.and_then(|item| item.label_manifest_hash.as_deref()),
            card.and_then(|item| item.rollup_key.label_manifest_hash.as_deref()),
        );
        let current_label = resolved_contract_value(
            current.and_then(|item| item.label_manifest_hash.as_deref()),
            card.and_then(|item| item.rollup_key.label_manifest_hash.as_deref()),
        );
        let used_summary_card_fallback =
            used_summary_card_contract_fallback(baseline, current, card);
        let dataset_changed =
            contract_values_changed(baseline_dataset.as_deref(), current_dataset.as_deref());
        let feature_changed =
            contract_values_changed(baseline_feature.as_deref(), current_feature.as_deref());
        let label_changed =
            contract_values_changed(baseline_label.as_deref(), current_label.as_deref());
        let all_missing = baseline_dataset.is_none()
            && current_dataset.is_none()
            && baseline_feature.is_none()
            && current_feature.is_none()
            && baseline_label.is_none()
            && current_label.is_none();
        let alignment_status = if feature_changed {
            ContractAlignmentAuditStatusV2::FeatureSchemaChange
        } else if label_changed {
            ContractAlignmentAuditStatusV2::LabelManifestChange
        } else if dataset_changed {
            ContractAlignmentAuditStatusV2::ContractAlignmentChanged
        } else if all_missing {
            ContractAlignmentAuditStatusV2::NeedsContractClarification
        } else {
            ContractAlignmentAuditStatusV2::ContractAligned
        };
        items.push(ContractAlignmentAuditItemV2 {
            model_id: model_id.to_string(),
            model_version: model_version.to_string(),
            baseline_dataset_fingerprint: baseline_dataset,
            current_dataset_fingerprint: current_dataset,
            baseline_feature_schema_hash: baseline_feature,
            current_feature_schema_hash: current_feature,
            baseline_label_manifest_hash: baseline_label,
            current_label_manifest_hash: current_label,
            used_summary_card_fallback,
            explanation: contract_alignment_explanation(
                alignment_status,
                used_summary_card_fallback,
            ),
            alignment_status,
            reason_codes: stable_reason_codes(&[ReasonCode::ContractAlignmentAuditV2Built]),
        });
    }
    items.sort_by(|left, right| {
        (
            left.model_id.clone(),
            compare_versionish_key(&left.model_version),
        )
            .cmp(&(
                right.model_id.clone(),
                compare_versionish_key(&right.model_version),
            ))
    });
    let aligned_count = items
        .iter()
        .filter(|item| item.alignment_status == ContractAlignmentAuditStatusV2::ContractAligned)
        .count();
    let changed_count = items
        .iter()
        .filter(|item| {
            matches!(
                item.alignment_status,
                ContractAlignmentAuditStatusV2::ContractAlignmentChanged
                    | ContractAlignmentAuditStatusV2::FeatureSchemaChange
                    | ContractAlignmentAuditStatusV2::LabelManifestChange
            )
        })
        .count();
    let clarification_count = items
        .iter()
        .filter(|item| {
            item.alignment_status == ContractAlignmentAuditStatusV2::NeedsContractClarification
        })
        .count();
    let audit_status = if items.is_empty() {
        ContractAlignmentAuditStatusV2::DiagnosticOnly
    } else if clarification_count > 0 {
        ContractAlignmentAuditStatusV2::NeedsContractClarification
    } else if items.iter().any(|item| {
        matches!(
            item.alignment_status,
            ContractAlignmentAuditStatusV2::ContractAlignmentChanged
                | ContractAlignmentAuditStatusV2::FeatureSchemaChange
                | ContractAlignmentAuditStatusV2::LabelManifestChange
        )
    }) {
        items
            .iter()
            .find_map(|item| match item.alignment_status {
                ContractAlignmentAuditStatusV2::FeatureSchemaChange => {
                    Some(ContractAlignmentAuditStatusV2::FeatureSchemaChange)
                }
                ContractAlignmentAuditStatusV2::LabelManifestChange => {
                    Some(ContractAlignmentAuditStatusV2::LabelManifestChange)
                }
                ContractAlignmentAuditStatusV2::ContractAlignmentChanged => {
                    Some(ContractAlignmentAuditStatusV2::ContractAlignmentChanged)
                }
                _ => None,
            })
            .unwrap_or(ContractAlignmentAuditStatusV2::ContractAlignmentChanged)
    } else {
        ContractAlignmentAuditStatusV2::ContractAligned
    };
    ContractAlignmentAuditV2 {
        audit_id: format!("{}-contract-alignment", config.triage_id),
        items,
        aligned_count,
        changed_count,
        clarification_count,
        audit_status,
        reason_codes: stable_reason_codes(&[ReasonCode::ContractAlignmentAuditV2Built]),
    }
}

fn build_owner_review_closure_v2_report(
    config: &UnexpectedDiffTriageConfig,
    trace_audit: &TraceCompletenessAudit,
    downgrade_audit: &ConservativeDowngradeEvidenceAudit,
    classification_report: &SnapshotDiffClassificationReport,
    context: &BaselineSnapshotCoverageContext,
) -> OwnerReviewClosureV2Report {
    let missing_owner_review = trace_audit
        .cells
        .iter()
        .filter(|cell| !cell.present && cell.dimension == TraceCompletenessDimension::OwnerReview)
        .map(|cell| {
            (
                format!("{}:{}", cell.model_id, cell.model_version),
                cell.missing_reason
                    .clone()
                    .unwrap_or_else(|| "missing OwnerReview".to_string()),
            )
        })
        .collect::<BTreeMap<_, _>>();
    let classification_map = classification_report
        .items
        .iter()
        .map(|item| {
            (
                format!("{}:{}", item.model_id, item.model_version),
                item.classification,
            )
        })
        .collect::<BTreeMap<_, _>>();
    let downgrade_map = downgrade_item_map(&downgrade_audit.items);
    let conflict_map = decision_conflict_map(context.decision_conflict_trace_report.as_ref());
    let regression_map = regression_trace_map(context.regression_trace_report.as_ref());
    let qa_map = operator_qa_trace_map(context.operator_qa_trace_report.as_ref());
    let action_map = action_priority_trace_map(context.action_priority_trace_report.as_ref());
    let keys = collect_all_model_version_keys_from_context(context);
    let mut items = Vec::new();
    for key in keys {
        let Some((model_id, model_version)) = key.split_once(':') else {
            continue;
        };
        let owner_review_present = !missing_owner_review.contains_key(&key);
        let closure = resolve_owner_review_closure(
            classification_map.get(&key).copied(),
            downgrade_map.get(&key).copied(),
            conflict_map.get(&key),
            regression_map.get(&key),
            qa_map.get(&key).copied(),
            action_map.get(&key).copied(),
        );
        items.push(OwnerReviewClosureV2Item {
            model_id: model_id.to_string(),
            model_version: model_version.to_string(),
            owner_review_present,
            safe_to_close: closure.safe_to_close,
            closure_action: closure.action,
            retirement_supported: closure.retirement_supported,
            diagnostic_only: closure.action == OwnerReviewClosureActionV2::MarkDiagnosticOnly,
            explanation: closure.explanation,
            supporting_signals: closure.supporting_signals,
            reason_codes: stable_reason_codes(&[ReasonCode::OwnerReviewClosureV2Built]),
        });
    }
    items.sort_by(|left, right| {
        (
            left.model_id.clone(),
            compare_versionish_key(&left.model_version),
        )
            .cmp(&(
                right.model_id.clone(),
                compare_versionish_key(&right.model_version),
            ))
    });
    let missing_owner_review_count = items
        .iter()
        .filter(|item| !item.owner_review_present)
        .count();
    let resolved_missing_owner_review_count = items
        .iter()
        .filter(|item| !item.owner_review_present && item.safe_to_close)
        .count();
    let pending_owner_review_count = items
        .iter()
        .filter(|item| !item.owner_review_present && !item.safe_to_close)
        .count();
    let diagnostic_only_count = items.iter().filter(|item| item.diagnostic_only).count();
    let closure_status = if missing_owner_review_count == 0 {
        OwnerReviewClosureV2Status::OwnerReviewClosureReady
    } else if pending_owner_review_count == 0 {
        OwnerReviewClosureV2Status::OwnerReviewClosureReady
    } else if resolved_missing_owner_review_count > 0 {
        OwnerReviewClosureV2Status::OwnerReviewClosurePartial
    } else {
        OwnerReviewClosureV2Status::NeedMoreEvidence
    };
    OwnerReviewClosureV2Report {
        closure_id: format!("{}-owner-review", config.triage_id),
        items,
        missing_owner_review_count,
        resolved_missing_owner_review_count,
        pending_owner_review_count,
        diagnostic_only_count,
        closure_status,
        reason_codes: stable_reason_codes(&[ReasonCode::OwnerReviewClosureV2Built]),
    }
}

fn build_trace_completeness_warning_reduction_report(
    config: &UnexpectedDiffTriageConfig,
    audit: &TraceCompletenessAudit,
    owner_review_closure: &OwnerReviewClosureV2Report,
) -> TraceCompletenessWarningReductionReport {
    let owner_review_map = owner_review_closure
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let mut items = Vec::new();
    for cell in audit.cells.iter().filter(|cell| !cell.present) {
        let key = format!("{}:{}", cell.model_id, cell.model_version);
        let (reduced, resolution) = if cell.dimension == TraceCompletenessDimension::OwnerReview {
            owner_review_map
                .get(&key)
                .map(|item| {
                    (
                        item.safe_to_close,
                        if item.safe_to_close {
                            format!("resolved_owner_review={:?}", item.closure_action)
                        } else {
                            format!("owner_review_pending={:?}", item.closure_action)
                        },
                    )
                })
                .unwrap_or_else(|| {
                    (
                        false,
                        "owner review still missing conservative closure".to_string(),
                    )
                })
        } else {
            (
                false,
                cell.missing_reason
                    .clone()
                    .unwrap_or_else(|| format!("missing {:?}", cell.dimension)),
            )
        };
        items.push(TraceCompletenessWarningReductionItem {
            model_id: cell.model_id.clone(),
            model_version: cell.model_version.clone(),
            dimension: cell.dimension,
            original_missing_reason: cell
                .missing_reason
                .clone()
                .unwrap_or_else(|| format!("missing {:?}", cell.dimension)),
            reduced,
            resolution,
            reason_codes: stable_reason_codes(&[
                ReasonCode::TraceCompletenessWarningReductionReportBuilt,
            ]),
        });
    }
    items.sort_by(|left, right| {
        (
            left.model_id.clone(),
            compare_versionish_key(&left.model_version),
            format!("{:?}", left.dimension),
        )
            .cmp(&(
                right.model_id.clone(),
                compare_versionish_key(&right.model_version),
                format!("{:?}", right.dimension),
            ))
    });
    let original_warning_count = items.len();
    let reduced_warning_count = items.iter().filter(|item| item.reduced).count();
    let remaining_warning_count = original_warning_count.saturating_sub(reduced_warning_count);
    let report_status = if original_warning_count == 0 {
        TraceWarningReductionStatus::NoWarnings
    } else if reduced_warning_count > 0 {
        TraceWarningReductionStatus::TraceWarningsReduced
    } else {
        TraceWarningReductionStatus::TraceWarningsUnchanged
    };
    TraceCompletenessWarningReductionReport {
        reduction_id: format!("{}-trace-warnings", config.triage_id),
        items,
        original_warning_count,
        reduced_warning_count,
        remaining_warning_count,
        warning_reduction_ratio: stable_ratio_string(reduced_warning_count, original_warning_count),
        report_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TraceCompletenessWarningReductionReportBuilt,
        ]),
    }
}

fn build_downgrade_evidence_closure_plan(
    config: &UnexpectedDiffTriageConfig,
    audit: &ConservativeDowngradeEvidenceAudit,
    classification_report: &SnapshotDiffClassificationReport,
) -> DowngradeEvidenceClosurePlan {
    let classification_map = classification_report
        .items
        .iter()
        .map(|item| {
            (
                format!("{}:{}", item.model_id, item.model_version),
                item.classification,
            )
        })
        .collect::<BTreeMap<_, _>>();
    let mut items = Vec::new();
    for item in &audit.items {
        let key = format!("{}:{}", item.model_id, item.model_version);
        let closure_action = if item.enough_for_retirement {
            DowngradeEvidenceClosureAction::RetireModelVersion
        } else if item.enough_for_diagnostic_downgrade {
            DowngradeEvidenceClosureAction::MarkDiagnosticOnly
        } else if item
            .missing_evidence
            .contains(&DowngradeEvidenceRequirement::CalibrationEvidence)
        {
            DowngradeEvidenceClosureAction::RequestCalibrationReview
        } else if item
            .missing_evidence
            .contains(&DowngradeEvidenceRequirement::RiskEvidence)
        {
            DowngradeEvidenceClosureAction::RequestRiskReview
        } else if item.downgrade_recommendation.is_some() {
            DowngradeEvidenceClosureAction::NeedMoreEvidence
        } else if matches!(
            classification_map.get(&key),
            Some(UnexpectedDiffClassification::RiskMetricChange)
        ) {
            DowngradeEvidenceClosureAction::MarkDiagnosticOnly
        } else {
            DowngradeEvidenceClosureAction::NoAction
        };
        items.push(DowngradeEvidenceClosurePlanItem {
            model_id: item.model_id.clone(),
            model_version: item.model_version.clone(),
            downgrade_recommendation: item.downgrade_recommendation.clone(),
            missing_evidence: item.missing_evidence.clone(),
            closure_action,
            enough_for_retirement: item.enough_for_retirement,
            enough_for_diagnostic_downgrade: item.enough_for_diagnostic_downgrade,
            explanation: downgrade_evidence_closure_explanation(item, closure_action),
            reason_codes: stable_reason_codes(&[ReasonCode::DowngradeEvidenceClosurePlanBuilt]),
        });
    }
    let ready_count = items
        .iter()
        .filter(|item| {
            matches!(
                item.closure_action,
                DowngradeEvidenceClosureAction::RetireModelVersion
                    | DowngradeEvidenceClosureAction::MarkDiagnosticOnly
            )
        })
        .count();
    let incomplete_count = items
        .iter()
        .filter(|item| item.closure_action == DowngradeEvidenceClosureAction::NeedMoreEvidence)
        .count();
    let plan_status = if items.is_empty() {
        DowngradeEvidenceClosurePlanStatus::NoDowngradeAction
    } else if incomplete_count > 0 {
        DowngradeEvidenceClosurePlanStatus::DowngradeEvidenceStillIncomplete
    } else if ready_count > 0 {
        DowngradeEvidenceClosurePlanStatus::DowngradeEvidenceReady
    } else {
        DowngradeEvidenceClosurePlanStatus::NoDowngradeAction
    };
    DowngradeEvidenceClosurePlan {
        plan_id: format!("{}-downgrade-closure", config.triage_id),
        items,
        ready_count,
        incomplete_count,
        plan_status,
        reason_codes: stable_reason_codes(&[ReasonCode::DowngradeEvidenceClosurePlanBuilt]),
    }
}

fn build_diff_root_cause_report(
    config: &UnexpectedDiffTriageConfig,
    context: &BaselineSnapshotCoverageContext,
    classification_report: &SnapshotDiffClassificationReport,
    contract_alignment_audit: &ContractAlignmentAuditV2,
) -> DiffRootCauseReport {
    let diff_map = diff_trace_map(context.diff_trace_report.as_ref());
    let regression_map = regression_trace_map(context.regression_trace_report.as_ref());
    let conflict_map = decision_conflict_map(context.decision_conflict_trace_report.as_ref());
    let alignment_map = contract_alignment_audit
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let baseline_map = snapshot_ref_map(&context.baseline_snapshot_refs);
    let current_map = snapshot_ref_map(&context.current_snapshot_refs);
    let mut items = Vec::new();
    for item in &classification_report.items {
        let key = format!("{}:{}", item.model_id, item.model_version);
        let diff = diff_map.get(&key).copied();
        let regressions = regression_map.get(&key);
        let conflicts = conflict_map.get(&key);
        let alignment = alignment_map.get(&key).copied();
        let mut evidence_refs = Vec::new();
        if let Some(snapshot) = baseline_map.get(&key).copied() {
            evidence_refs.push(snapshot.snapshot_id.clone());
        }
        if let Some(snapshot) = current_map.get(&key).copied() {
            evidence_refs.push(snapshot.snapshot_id.clone());
        }
        if let Some(regressions) = regressions {
            for regression in regressions {
                if let Some(value) = regression.baseline_artifact.as_ref() {
                    evidence_refs.push(value.clone());
                }
                if let Some(value) = regression.current_artifact.as_ref() {
                    evidence_refs.push(value.clone());
                }
            }
        }
        if let Some(conflicts) = conflicts {
            for conflict in conflicts {
                evidence_refs.extend(conflict.source_artifacts.clone());
            }
        }
        evidence_refs = stable_ordered_strings(&evidence_refs);
        let root_causes =
            diff_root_causes(item.classification, diff, regressions, conflicts, alignment);
        items.push(DiffRootCauseItem {
            model_id: item.model_id.clone(),
            model_version: item.model_version.clone(),
            primary_classification: item.classification,
            explanation: diff_root_cause_explanation(item.classification, &root_causes),
            root_causes,
            evidence_refs,
            reason_codes: stable_reason_codes(&[ReasonCode::DiffRootCauseReportBuilt]),
        });
    }
    let explained_count = items
        .iter()
        .filter(|item| {
            item.primary_classification != UnexpectedDiffClassification::UnknownUnexpectedDiff
        })
        .count();
    let needs_review_count = items.len().saturating_sub(explained_count);
    let report_status = if items.is_empty() {
        DiffRootCauseReportStatus::NoUnexpectedDiffs
    } else if needs_review_count == 0 {
        DiffRootCauseReportStatus::RootCausesReady
    } else {
        DiffRootCauseReportStatus::RootCausesNeedReview
    };
    DiffRootCauseReport {
        root_cause_id: format!("{}-root-cause", config.triage_id),
        items,
        explained_count,
        needs_review_count,
        report_status,
        reason_codes: stable_reason_codes(&[ReasonCode::DiffRootCauseReportBuilt]),
    }
}

fn build_model_version_review_disposition_report(
    config: &UnexpectedDiffTriageConfig,
    coverage_report: &BaselineSnapshotCoverageReport,
    owner_review_closure: &OwnerReviewClosureV2Report,
    warning_reduction: &TraceCompletenessWarningReductionReport,
    downgrade_plan: &DowngradeEvidenceClosurePlan,
) -> ModelVersionReviewDispositionReport {
    let owner_map = owner_review_closure
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let warning_map = grouped_warning_reduction_map(&warning_reduction.items);
    let downgrade_map = downgrade_closure_plan_map(&downgrade_plan.items);
    let mut items = Vec::new();
    for coverage_item in &coverage_report.items {
        let key = format!("{}:{}", coverage_item.model_id, coverage_item.model_version);
        let owner = owner_map.get(&key).copied();
        let warnings = warning_map.get(&key);
        let downgrade = downgrade_map.get(&key).copied();
        let disposition = model_version_disposition(owner, warnings, downgrade);
        items.push(ModelVersionReviewDispositionItem {
            model_id: coverage_item.model_id.clone(),
            model_version: coverage_item.model_version.clone(),
            explanation: model_version_disposition_explanation(
                disposition,
                owner,
                warnings,
                downgrade,
            ),
            supporting_signals: model_version_disposition_signals(owner, warnings, downgrade),
            disposition,
            reason_codes: stable_reason_codes(&[
                ReasonCode::ModelVersionReviewDispositionReportBuilt,
            ]),
        });
    }
    items.sort_by(|left, right| {
        (
            left.model_id.clone(),
            compare_versionish_key(&left.model_version),
        )
            .cmp(&(
                right.model_id.clone(),
                compare_versionish_key(&right.model_version),
            ))
    });
    let keep_count = items
        .iter()
        .filter(|item| item.disposition == ModelVersionReviewDispositionKind::KeepResearchCandidate)
        .count();
    let review_count = items
        .iter()
        .filter(|item| {
            matches!(
                item.disposition,
                ModelVersionReviewDispositionKind::RequestMorePredictions
                    | ModelVersionReviewDispositionKind::RequestCalibrationReview
                    | ModelVersionReviewDispositionKind::RequestRiskReview
            )
        })
        .count();
    let diagnostic_only_count = items
        .iter()
        .filter(|item| item.disposition == ModelVersionReviewDispositionKind::MarkDiagnosticOnly)
        .count();
    let need_more_evidence_count = items
        .iter()
        .filter(|item| item.disposition == ModelVersionReviewDispositionKind::NeedMoreEvidence)
        .count();
    let disposition_status = if items.is_empty() {
        ModelVersionReviewDispositionStatus::DiagnosticOnly
    } else if need_more_evidence_count > 0 {
        ModelVersionReviewDispositionStatus::NeedMoreEvidence
    } else {
        ModelVersionReviewDispositionStatus::DispositionsReady
    };
    ModelVersionReviewDispositionReport {
        disposition_id: format!("{}-dispositions", config.triage_id),
        items,
        keep_count,
        review_count,
        diagnostic_only_count,
        need_more_evidence_count,
        disposition_status,
        reason_codes: stable_reason_codes(&[ReasonCode::ModelVersionReviewDispositionReportBuilt]),
    }
}

fn build_unexpected_diff_triage_report(
    config: &UnexpectedDiffTriageConfig,
    classification_report: &SnapshotDiffClassificationReport,
    contract_alignment_audit: &ContractAlignmentAuditV2,
    owner_review_closure: &OwnerReviewClosureV2Report,
    diff_root_cause_report: &DiffRootCauseReport,
) -> UnexpectedDiffTriageReport {
    let alignment_map = contract_alignment_audit
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let owner_map = owner_review_closure
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let root_cause_map = diff_root_cause_report
        .items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect::<BTreeMap<_, _>>();
    let mut items = Vec::new();
    for item in &classification_report.items {
        let key = format!("{}:{}", item.model_id, item.model_version);
        let alignment_status = alignment_map
            .get(&key)
            .map(|value| value.alignment_status)
            .unwrap_or(ContractAlignmentAuditStatusV2::NeedsContractClarification);
        let owner_action = owner_map
            .get(&key)
            .map(|value| value.closure_action)
            .unwrap_or(OwnerReviewClosureActionV2::NeedMoreEvidence);
        let safe_to_close_owner_review =
            owner_map.get(&key).is_some_and(|value| value.safe_to_close);
        let explanation = root_cause_map
            .get(&key)
            .map(|value| value.explanation.clone())
            .unwrap_or_else(|| "unexpected diff needs more evidence".to_string());
        items.push(UnexpectedDiffTriageItem {
            model_id: item.model_id.clone(),
            model_version: item.model_version.clone(),
            classification: item.classification,
            contract_alignment_status: alignment_status,
            owner_review_action: owner_action,
            safe_to_close_owner_review,
            explanation,
            reason_codes: stable_reason_codes(&[ReasonCode::UnexpectedDiffTriageReportBuilt]),
        });
    }
    let unexpected_diff_count = items.len();
    let explained_count = items
        .iter()
        .filter(|item| {
            item.classification != UnexpectedDiffClassification::UnknownUnexpectedDiff
                && item.contract_alignment_status
                    != ContractAlignmentAuditStatusV2::NeedsContractClarification
        })
        .count();
    let unknown_count = items
        .iter()
        .filter(|item| item.classification == UnexpectedDiffClassification::UnknownUnexpectedDiff)
        .count();
    let triage_status = if items.is_empty() {
        UnexpectedDiffTriageStatus::NoUnexpectedDiffs
    } else if unknown_count == 0 && explained_count == items.len() {
        UnexpectedDiffTriageStatus::UnexpectedDiffExplained
    } else if unknown_count == 0 {
        UnexpectedDiffTriageStatus::UnexpectedDiffTriaged
    } else {
        UnexpectedDiffTriageStatus::UnexpectedDiffNeedsReview
    };
    UnexpectedDiffTriageReport {
        triage_id: config.triage_id.clone(),
        items,
        unexpected_diff_count,
        explained_count,
        unknown_count,
        triage_status,
        reason_codes: stable_reason_codes(&[ReasonCode::UnexpectedDiffTriageReportBuilt]),
    }
}

fn build_control_tower_diff_triage_panel(
    config: &UnexpectedDiffTriageConfig,
    triage_report: &UnexpectedDiffTriageReport,
    contract_alignment_audit: &ContractAlignmentAuditV2,
    owner_review_closure: &OwnerReviewClosureV2Report,
    warning_reduction: &TraceCompletenessWarningReductionReport,
    downgrade_plan: &DowngradeEvidenceClosurePlan,
    disposition_report: &ModelVersionReviewDispositionReport,
) -> ControlTowerDiffTriagePanel {
    let mut panel = ControlTowerDiffTriagePanel {
        panel_id: config.triage_id.clone(),
        panel_status: if triage_report.triage_status
            == UnexpectedDiffTriageStatus::UnexpectedDiffExplained
            && owner_review_closure.closure_status
                == OwnerReviewClosureV2Status::OwnerReviewClosureReady
            && warning_reduction.remaining_warning_count == 0
            && downgrade_plan.plan_status
                != DowngradeEvidenceClosurePlanStatus::DowngradeEvidenceStillIncomplete
        {
            ControlTowerDiffTriagePanelStatus::TriageReady
        } else if disposition_report.disposition_status
            == ModelVersionReviewDispositionStatus::NeedMoreEvidence
        {
            ControlTowerDiffTriagePanelStatus::NeedMoreEvidence
        } else {
            ControlTowerDiffTriagePanelStatus::TriageReadyWithWarnings
        },
        unexpected_diff_summary: format!(
            "{:?};triaged={};explained={};unknown={}",
            triage_report.triage_status,
            triage_report.unexpected_diff_count,
            triage_report.explained_count,
            triage_report.unknown_count
        ),
        contract_alignment_summary: format!(
            "{:?};aligned={};changed={};clarify={}",
            contract_alignment_audit.audit_status,
            contract_alignment_audit.aligned_count,
            contract_alignment_audit.changed_count,
            contract_alignment_audit.clarification_count
        ),
        owner_review_closure_summary: format!(
            "{:?};missing={};resolved={};pending={}",
            owner_review_closure.closure_status,
            owner_review_closure.missing_owner_review_count,
            owner_review_closure.resolved_missing_owner_review_count,
            owner_review_closure.pending_owner_review_count
        ),
        trace_warning_summary: format!(
            "{:?};original={};reduced={};remaining={};ratio={}",
            warning_reduction.report_status,
            warning_reduction.original_warning_count,
            warning_reduction.reduced_warning_count,
            warning_reduction.remaining_warning_count,
            warning_reduction.warning_reduction_ratio
        ),
        downgrade_evidence_summary: format!(
            "{:?};ready={};incomplete={}",
            downgrade_plan.plan_status, downgrade_plan.ready_count, downgrade_plan.incomplete_count
        ),
        disposition_summary: format!(
            "{:?};keep={};review={};diagnostic={};need_more_evidence={}",
            disposition_report.disposition_status,
            disposition_report.keep_count,
            disposition_report.review_count,
            disposition_report.diagnostic_only_count,
            disposition_report.need_more_evidence_count
        ),
        per_model_dispositions: disposition_report
            .items
            .iter()
            .map(|item| {
                (
                    format!("{}:{}", item.model_id, item.model_version),
                    format!("{:?}", item.disposition),
                )
            })
            .collect(),
        next_actions: build_diff_triage_next_actions(
            owner_review_closure,
            warning_reduction,
            disposition_report,
        ),
        mamba_deferred_status: "PredictionCsvOnly+ContractOnly+RuntimeDeferred".to_string(),
        reason_codes: stable_reason_codes(&[ReasonCode::ControlTowerDiffTriagePanelBuilt]),
    };
    panel.stabilize();
    panel
}

fn write_unexpected_diff_triage_fragments(
    config: &UnexpectedDiffTriageConfig,
    triage_report: &UnexpectedDiffTriageReport,
    contract_alignment_audit: &ContractAlignmentAuditV2,
    owner_review_closure: &OwnerReviewClosureV2Report,
    warning_reduction: &TraceCompletenessWarningReductionReport,
    downgrade_plan: &DowngradeEvidenceClosurePlan,
) -> Result<BTreeMap<String, String>, String> {
    let fragments_dir = config.output_dir().join("fragments");
    fs::create_dir_all(&fragments_dir).map_err(|err| err.to_string())?;
    let fragments = BTreeMap::from([
        (
            "unexpected_diff_triage".to_string(),
            (
                "unexpected_diff_triage.html".to_string(),
                render_unexpected_diff_triage_fragment(triage_report),
            ),
        ),
        (
            "contract_alignment_audit".to_string(),
            (
                "contract_alignment_audit.html".to_string(),
                render_contract_alignment_audit_fragment(contract_alignment_audit),
            ),
        ),
        (
            "owner_review_closure".to_string(),
            (
                "owner_review_closure.html".to_string(),
                render_owner_review_closure_fragment(owner_review_closure),
            ),
        ),
        (
            "trace_warning_reduction".to_string(),
            (
                "trace_warning_reduction.html".to_string(),
                render_trace_warning_reduction_fragment(warning_reduction),
            ),
        ),
        (
            "downgrade_evidence_closure".to_string(),
            (
                "downgrade_evidence_closure.html".to_string(),
                render_downgrade_evidence_closure_fragment(downgrade_plan),
            ),
        ),
    ]);
    let mut paths = BTreeMap::new();
    for (_key, (file_name, content)) in fragments {
        fs::write(fragments_dir.join(&file_name), content).map_err(|err| err.to_string())?;
        paths.insert(
            file_name.trim_end_matches(".html").to_string(),
            format!("fragments/{file_name}"),
        );
    }
    Ok(paths)
}

