fn diff_trace_map<'a>(
    report: Option<&'a ModelVersionDiffTraceReport>,
) -> BTreeMap<String, &'a ModelVersionDiffTrace> {
    report
        .map(|report| {
            report
                .diffs
                .iter()
                .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default()
}

fn regression_trace_map<'a>(
    report: Option<&'a RegressionEvidenceTraceReport>,
) -> BTreeMap<String, Vec<&'a RegressionEvidenceTrace>> {
    let mut map = BTreeMap::<String, Vec<&RegressionEvidenceTrace>>::new();
    if let Some(report) = report {
        for item in &report.traces {
            map.entry(format!("{}:{}", item.model_id, item.model_version))
                .or_default()
                .push(item);
        }
    }
    for values in map.values_mut() {
        values.sort_by_key(|item| format!("{:?}", item.cause_kind));
    }
    map
}

fn decision_conflict_map<'a>(
    report: Option<&'a DecisionConflictTraceReport>,
) -> BTreeMap<String, Vec<&'a DecisionConflictTrace>> {
    let mut map = BTreeMap::<String, Vec<&DecisionConflictTrace>>::new();
    if let Some(report) = report {
        for item in &report.conflicts {
            map.entry(format!("{}:{}", item.model_id, item.model_version))
                .or_default()
                .push(item);
        }
    }
    for values in map.values_mut() {
        values.sort_by_key(|item| format!("{:?}", item.conflict_kind));
    }
    map
}

