fn classify_unexpected_diff(
    diff: Option<&ModelVersionDiffTrace>,
    baseline: Option<&ModelOpsSnapshotRef>,
    current: Option<&ModelOpsSnapshotRef>,
    card: Option<&ModelVersionSummaryCard>,
    conflicts: Option<&Vec<&DecisionConflictTrace>>,
) -> UnexpectedDiffClassification {
    if contract_values_changed(
        resolved_contract_value(
            baseline.and_then(|item| item.feature_schema_hash.as_deref()),
            card.and_then(|item| item.rollup_key.feature_schema_hash.as_deref()),
        )
        .as_deref(),
        resolved_contract_value(
            current.and_then(|item| item.feature_schema_hash.as_deref()),
            card.and_then(|item| item.rollup_key.feature_schema_hash.as_deref()),
        )
        .as_deref(),
    ) {
        return UnexpectedDiffClassification::FeatureSchemaChange;
    }
    if contract_values_changed(
        resolved_contract_value(
            baseline.and_then(|item| item.label_manifest_hash.as_deref()),
            card.and_then(|item| item.rollup_key.label_manifest_hash.as_deref()),
        )
        .as_deref(),
        resolved_contract_value(
            current.and_then(|item| item.label_manifest_hash.as_deref()),
            card.and_then(|item| item.rollup_key.label_manifest_hash.as_deref()),
        )
        .as_deref(),
    ) {
        return UnexpectedDiffClassification::LabelManifestChange;
    }
    if contract_values_changed(
        resolved_contract_value(
            baseline.and_then(|item| item.dataset_fingerprint.as_deref()),
            card.and_then(|item| item.rollup_key.dataset_fingerprint.as_deref()),
        )
        .as_deref(),
        resolved_contract_value(
            current.and_then(|item| item.dataset_fingerprint.as_deref()),
            card.and_then(|item| item.rollup_key.dataset_fingerprint.as_deref()),
        )
        .as_deref(),
    ) {
        return UnexpectedDiffClassification::ContractAlignmentChange;
    }
    if diff.is_some_and(|item| item.changed_risk_status.is_some()) {
        return UnexpectedDiffClassification::RiskMetricChange;
    }
    if diff.is_some_and(|item| item.changed_leaderboard_status.is_some()) {
        return UnexpectedDiffClassification::LeaderboardStatusChange;
    }
    if diff.is_some_and(|item| {
        item.changed_fields
            .iter()
            .any(|field| field.starts_with("recommended_action:"))
    }) || conflicts.is_some_and(|values| !values.is_empty())
    {
        return UnexpectedDiffClassification::OwnerDecisionChange;
    }
    if diff.is_some_and(|item| {
        (!item.added_artifacts.is_empty() || !item.removed_artifacts.is_empty())
            && item.changed_metrics.is_empty()
    }) {
        return UnexpectedDiffClassification::ExpectedArtifactRefresh;
    }
    if diff.is_some_and(|item| !item.changed_metrics.is_empty() || !item.changed_fields.is_empty())
    {
        return UnexpectedDiffClassification::ExpectedMetricDrift;
    }
    UnexpectedDiffClassification::UnknownUnexpectedDiff
}

fn classification_supporting_signals(
    diff: Option<&ModelVersionDiffTrace>,
    baseline: Option<&ModelOpsSnapshotRef>,
    current: Option<&ModelOpsSnapshotRef>,
    card: Option<&ModelVersionSummaryCard>,
    conflicts: Option<&Vec<&DecisionConflictTrace>>,
) -> Vec<String> {
    let mut signals = Vec::new();
    if let Some(diff) = diff {
        if let Some(value) = diff.changed_risk_status.as_ref() {
            signals.push(format!("changed_risk_status={value}"));
        }
        if let Some(value) = diff.changed_leaderboard_status.as_ref() {
            signals.push(format!("changed_leaderboard_status={value}"));
        }
        signals.extend(
            diff.changed_fields
                .iter()
                .map(|item| format!("changed_field={item}")),
        );
        signals.extend(
            diff.changed_metrics
                .iter()
                .map(|item| format!("changed_metric={item}")),
        );
        signals.extend(
            diff.added_artifacts
                .iter()
                .map(|item| format!("added_artifact={item}")),
        );
        signals.extend(
            diff.removed_artifacts
                .iter()
                .map(|item| format!("removed_artifact={item}")),
        );
    }
    if let Some(card) = card {
        signals.push(format!("recommended_action={:?}", card.recommended_action));
    }
    if let Some(baseline) = baseline {
        signals.push(format!("baseline_snapshot={}", baseline.snapshot_id));
    }
    if let Some(current) = current {
        signals.push(format!("current_snapshot={}", current.snapshot_id));
    }
    if let Some(conflicts) = conflicts {
        signals.extend(conflicts.iter().map(|item| {
            format!(
                "conflict={:?}->{:?}",
                item.conflict_kind, item.recommended_resolution
            )
        }));
    }
    stable_ordered_strings(&signals)
}

fn resolved_contract_value(
    snapshot_value: Option<&str>,
    card_value: Option<&str>,
) -> Option<String> {
    snapshot_value
        .map(str::to_string)
        .or_else(|| card_value.map(str::to_string))
}

fn contract_values_changed(left: Option<&str>, right: Option<&str>) -> bool {
    left.zip(right).is_some_and(|(left, right)| left != right)
}

fn used_summary_card_contract_fallback(
    baseline: Option<&ModelOpsSnapshotRef>,
    current: Option<&ModelOpsSnapshotRef>,
    card: Option<&ModelVersionSummaryCard>,
) -> bool {
    let Some(card) = card else {
        return false;
    };
    let baseline_fallback = baseline.is_some_and(|snapshot| {
        (snapshot.dataset_fingerprint.is_none() && card.rollup_key.dataset_fingerprint.is_some())
            || (snapshot.feature_schema_hash.is_none()
                && card.rollup_key.feature_schema_hash.is_some())
            || (snapshot.label_manifest_hash.is_none()
                && card.rollup_key.label_manifest_hash.is_some())
    });
    let current_fallback = current.is_some_and(|snapshot| {
        (snapshot.dataset_fingerprint.is_none() && card.rollup_key.dataset_fingerprint.is_some())
            || (snapshot.feature_schema_hash.is_none()
                && card.rollup_key.feature_schema_hash.is_some())
            || (snapshot.label_manifest_hash.is_none()
                && card.rollup_key.label_manifest_hash.is_some())
    });
    baseline_fallback || current_fallback
}

fn contract_alignment_explanation(
    status: ContractAlignmentAuditStatusV2,
    used_summary_card_fallback: bool,
) -> String {
    let suffix = if used_summary_card_fallback {
        " summary card contract fields were used to fill missing snapshot contract metadata."
    } else {
        ""
    };
    match status {
        ContractAlignmentAuditStatusV2::ContractAligned => {
            format!("no dataset/schema/label contract change was detected.{suffix}")
        }
        ContractAlignmentAuditStatusV2::ContractAlignmentChanged => {
            format!("dataset contract changed between baseline and current snapshots.{suffix}")
        }
        ContractAlignmentAuditStatusV2::FeatureSchemaChange => {
            format!("feature schema changed between baseline and current snapshots.{suffix}")
        }
        ContractAlignmentAuditStatusV2::LabelManifestChange => {
            format!("label manifest changed between baseline and current snapshots.{suffix}")
        }
        ContractAlignmentAuditStatusV2::NeedsContractClarification => {
            format!("contract metadata is insufficient and must remain conservative.{suffix}")
        }
        ContractAlignmentAuditStatusV2::DiagnosticOnly => {
            "contract audit is diagnostic only".to_string()
        }
    }
}

struct OwnerReviewClosureDecision {
    action: OwnerReviewClosureActionV2,
    safe_to_close: bool,
    retirement_supported: bool,
    explanation: String,
    supporting_signals: Vec<String>,
}

fn resolve_owner_review_closure(
    classification: Option<UnexpectedDiffClassification>,
    downgrade_item: Option<&DowngradeEvidenceAuditItem>,
    conflicts: Option<&Vec<&DecisionConflictTrace>>,
    regressions: Option<&Vec<&RegressionEvidenceTrace>>,
    qa: Option<&OperatorQAEvidenceTrace>,
    action: Option<&ActionPriorityTrace>,
) -> OwnerReviewClosureDecision {
    if downgrade_item.is_some_and(|item| item.enough_for_retirement) {
        return OwnerReviewClosureDecision {
            action: OwnerReviewClosureActionV2::RetireModelVersion,
            safe_to_close: true,
            retirement_supported: true,
            explanation:
                "retirement remains conservative but is supported by the required evidence."
                    .to_string(),
            supporting_signals: vec!["retirement_evidence_ready".to_string()],
        };
    }
    if regressions.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::ComparabilityRegression)
    }) {
        return OwnerReviewClosureDecision {
            action: OwnerReviewClosureActionV2::MarkDiagnosticOnly,
            safe_to_close: true,
            retirement_supported: false,
            explanation:
                "comparability regressed, so the safest owner closure is diagnostic-only until clarified."
                    .to_string(),
            supporting_signals: vec!["comparability_regression".to_string()],
        };
    }
    if regressions.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::RiskRegression)
    }) {
        return OwnerReviewClosureDecision {
            action: OwnerReviewClosureActionV2::RequestRiskReview,
            safe_to_close: true,
            retirement_supported: false,
            explanation:
                "risk evidence regressed, so owner closure should request explicit risk review."
                    .to_string(),
            supporting_signals: vec!["risk_regression".to_string()],
        };
    }
    if regressions.is_some_and(|items| {
        items
            .iter()
            .any(|item| item.cause_kind == RegressionCauseKind::CalibrationRegression)
    }) {
        return OwnerReviewClosureDecision {
            action: OwnerReviewClosureActionV2::RequestCalibrationReview,
            safe_to_close: true,
            retirement_supported: false,
            explanation:
                "calibration evidence regressed, so owner closure should request calibration review."
                    .to_string(),
            supporting_signals: vec!["calibration_regression".to_string()],
        };
    }
    if regressions.is_some_and(|items| {
        items.iter().any(|item| {
            matches!(
                item.cause_kind,
                RegressionCauseKind::CoverageRegression
                    | RegressionCauseKind::ArtifactCompletenessRegression
            )
        })
    }) || qa
        .is_some_and(|item| item.required_action.as_deref() == Some("RequestMorePredictions"))
    {
        return OwnerReviewClosureDecision {
            action: OwnerReviewClosureActionV2::RequestMorePredictions,
            safe_to_close: true,
            retirement_supported: false,
            explanation:
                "coverage or artifact evidence is still weak, so owner closure should request more predictions."
                    .to_string(),
            supporting_signals: vec!["coverage_gap".to_string()],
        };
    }
    if matches!(
        classification,
        Some(UnexpectedDiffClassification::LeaderboardStatusChange)
    ) || action.is_some_and(|item| {
        matches!(
            item.action,
            ModelOpsDecisionKind::KeepResearchCandidate | ModelOpsDecisionKind::WatchModel
        )
    }) || qa.is_some_and(|item| item.status == "ReadyForOperatorReview")
    {
        return OwnerReviewClosureDecision {
            action: OwnerReviewClosureActionV2::KeepResearchCandidate,
            safe_to_close: true,
            retirement_supported: false,
            explanation:
                "the current trace stays research-only and can be closed conservatively as a research candidate."
                    .to_string(),
            supporting_signals: vec!["research_candidate".to_string()],
        };
    }
    if conflicts.is_some_and(|items| !items.is_empty()) {
        return OwnerReviewClosureDecision {
            action: OwnerReviewClosureActionV2::NeedMoreEvidence,
            safe_to_close: false,
            retirement_supported: false,
            explanation:
                "decision conflict remains unresolved and owner closure must stay conservative."
                    .to_string(),
            supporting_signals: vec!["decision_conflict".to_string()],
        };
    }
    OwnerReviewClosureDecision {
        action: OwnerReviewClosureActionV2::NeedMoreEvidence,
        safe_to_close: false,
        retirement_supported: false,
        explanation: "owner closure is still missing evidence and should remain pending."
            .to_string(),
        supporting_signals: vec!["need_more_evidence".to_string()],
    }
}

fn downgrade_item_map<'a>(
    items: &'a [DowngradeEvidenceAuditItem],
) -> BTreeMap<String, &'a DowngradeEvidenceAuditItem> {
    items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect()
}

fn downgrade_evidence_closure_explanation(
    item: &DowngradeEvidenceAuditItem,
    action: DowngradeEvidenceClosureAction,
) -> String {
    match action {
        DowngradeEvidenceClosureAction::RetireModelVersion => {
            "retirement is supported by the required conservative evidence.".to_string()
        }
        DowngradeEvidenceClosureAction::MarkDiagnosticOnly => {
            "diagnostic-only is safer than stronger action until more evidence exists.".to_string()
        }
        DowngradeEvidenceClosureAction::RequestCalibrationReview => {
            "calibration evidence is still incomplete for stronger downgrade.".to_string()
        }
        DowngradeEvidenceClosureAction::RequestRiskReview => {
            "risk evidence must be reviewed before any stronger downgrade claim.".to_string()
        }
        DowngradeEvidenceClosureAction::RequestMorePredictions => {
            "more prediction history is needed before stronger downgrade action.".to_string()
        }
        DowngradeEvidenceClosureAction::NeedMoreEvidence => format!(
            "downgrade recommendation {:?} remains unsupported until missing evidence is closed.",
            item.downgrade_recommendation
        ),
        DowngradeEvidenceClosureAction::NoAction => {
            "no stronger downgrade closure action is justified from the current evidence."
                .to_string()
        }
    }
}

fn diff_root_causes(
    classification: UnexpectedDiffClassification,
    diff: Option<&ModelVersionDiffTrace>,
    regressions: Option<&Vec<&RegressionEvidenceTrace>>,
    conflicts: Option<&Vec<&DecisionConflictTrace>>,
    alignment: Option<&ContractAlignmentAuditItemV2>,
) -> Vec<String> {
    let mut causes = Vec::new();
    causes.push(format!("classification={classification:?}"));
    if let Some(diff) = diff {
        if let Some(value) = diff.changed_risk_status.as_ref() {
            causes.push(format!("risk_status={value}"));
        }
        if let Some(value) = diff.changed_leaderboard_status.as_ref() {
            causes.push(format!("leaderboard_status={value}"));
        }
        causes.extend(diff.changed_fields.iter().cloned());
        causes.extend(diff.changed_metrics.iter().cloned());
        causes.extend(
            diff.added_artifacts
                .iter()
                .map(|item| format!("added:{item}")),
        );
        causes.extend(
            diff.removed_artifacts
                .iter()
                .map(|item| format!("removed:{item}")),
        );
    }
    if let Some(regressions) = regressions {
        causes.extend(
            regressions
                .iter()
                .map(|item| format!("{:?}:{}", item.cause_kind, item.explanation)),
        );
    }
    if let Some(conflicts) = conflicts {
        causes.extend(
            conflicts
                .iter()
                .map(|item| format!("{:?}:{:?}", item.conflict_kind, item.recommended_resolution)),
        );
    }
    if let Some(alignment) = alignment {
        causes.push(format!(
            "contract_alignment={:?}",
            alignment.alignment_status
        ));
    }
    stable_ordered_strings(&causes)
}

fn diff_root_cause_explanation(
    classification: UnexpectedDiffClassification,
    causes: &[String],
) -> String {
    let joined = causes.join(" | ");
    match classification {
        UnexpectedDiffClassification::LeaderboardStatusChange => {
            format!(
                "unexpected diff is explained by leaderboard movement while the trace stayed offline-only: {joined}"
            )
        }
        UnexpectedDiffClassification::RiskMetricChange => {
            format!(
                "unexpected diff is explained by risk deterioration and its downstream evidence changes: {joined}"
            )
        }
        UnexpectedDiffClassification::ExpectedArtifactRefresh => {
            format!(
                "unexpected diff is explained by deterministic artifact refresh activity: {joined}"
            )
        }
        UnexpectedDiffClassification::ExpectedMetricDrift => {
            format!(
                "unexpected diff is explained by deterministic metric drift in local artifacts: {joined}"
            )
        }
        UnexpectedDiffClassification::ContractAlignmentChange
        | UnexpectedDiffClassification::FeatureSchemaChange
        | UnexpectedDiffClassification::LabelManifestChange => {
            format!(
                "unexpected diff is explained by a contract change that must stay research-only: {joined}"
            )
        }
        UnexpectedDiffClassification::OwnerDecisionChange => {
            format!(
                "unexpected diff is explained by a conservative owner/policy decision change: {joined}"
            )
        }
        UnexpectedDiffClassification::UnknownUnexpectedDiff => {
            format!(
                "unexpected diff remains conservative because the current evidence is insufficient: {joined}"
            )
        }
    }
}

fn grouped_warning_reduction_map<'a>(
    items: &'a [TraceCompletenessWarningReductionItem],
) -> BTreeMap<String, Vec<&'a TraceCompletenessWarningReductionItem>> {
    let mut map = BTreeMap::<String, Vec<&TraceCompletenessWarningReductionItem>>::new();
    for item in items {
        map.entry(format!("{}:{}", item.model_id, item.model_version))
            .or_default()
            .push(item);
    }
    map
}

fn downgrade_closure_plan_map<'a>(
    items: &'a [DowngradeEvidenceClosurePlanItem],
) -> BTreeMap<String, &'a DowngradeEvidenceClosurePlanItem> {
    items
        .iter()
        .map(|item| (format!("{}:{}", item.model_id, item.model_version), item))
        .collect()
}

fn model_version_disposition(
    owner: Option<&OwnerReviewClosureV2Item>,
    warnings: Option<&Vec<&TraceCompletenessWarningReductionItem>>,
    downgrade: Option<&DowngradeEvidenceClosurePlanItem>,
) -> ModelVersionReviewDispositionKind {
    if downgrade.is_some_and(|item| {
        item.closure_action == DowngradeEvidenceClosureAction::RetireModelVersion
    }) {
        return ModelVersionReviewDispositionKind::RetireWeakModelVersion;
    }
    match owner.map(|item| item.closure_action) {
        Some(OwnerReviewClosureActionV2::MarkDiagnosticOnly) => {
            return ModelVersionReviewDispositionKind::MarkDiagnosticOnly;
        }
        Some(OwnerReviewClosureActionV2::RequestMorePredictions) => {
            return ModelVersionReviewDispositionKind::RequestMorePredictions;
        }
        Some(OwnerReviewClosureActionV2::RequestCalibrationReview) => {
            return ModelVersionReviewDispositionKind::RequestCalibrationReview;
        }
        Some(OwnerReviewClosureActionV2::RequestRiskReview) => {
            return ModelVersionReviewDispositionKind::RequestRiskReview;
        }
        Some(OwnerReviewClosureActionV2::NeedMoreEvidence) => {
            return ModelVersionReviewDispositionKind::NeedMoreEvidence;
        }
        _ => {}
    }
    if warnings.is_some_and(|items| {
        items
            .iter()
            .any(|item| !item.reduced && item.dimension == TraceCompletenessDimension::OwnerReview)
    }) {
        return ModelVersionReviewDispositionKind::NeedMoreEvidence;
    }
    ModelVersionReviewDispositionKind::KeepResearchCandidate
}

fn model_version_disposition_explanation(
    disposition: ModelVersionReviewDispositionKind,
    owner: Option<&OwnerReviewClosureV2Item>,
    warnings: Option<&Vec<&TraceCompletenessWarningReductionItem>>,
    downgrade: Option<&DowngradeEvidenceClosurePlanItem>,
) -> String {
    let mut parts = Vec::new();
    if let Some(owner) = owner {
        parts.push(format!("owner_closure={:?}", owner.closure_action));
    }
    if let Some(downgrade) = downgrade {
        parts.push(format!("downgrade_closure={:?}", downgrade.closure_action));
    }
    if let Some(warnings) = warnings {
        parts.push(format!(
            "remaining_warnings={}",
            warnings.iter().filter(|item| !item.reduced).count()
        ));
    }
    format!("{:?}: {}", disposition, parts.join(" | "))
}

fn model_version_disposition_signals(
    owner: Option<&OwnerReviewClosureV2Item>,
    warnings: Option<&Vec<&TraceCompletenessWarningReductionItem>>,
    downgrade: Option<&DowngradeEvidenceClosurePlanItem>,
) -> Vec<String> {
    let mut signals = Vec::new();
    if let Some(owner) = owner {
        signals.extend(owner.supporting_signals.clone());
    }
    if let Some(warnings) = warnings {
        signals.extend(warnings.iter().map(|item| item.resolution.clone()));
    }
    if let Some(downgrade) = downgrade {
        signals.push(format!("downgrade_closure={:?}", downgrade.closure_action));
    }
    stable_ordered_strings(&signals)
}

fn build_diff_triage_next_actions(
    owner_review_closure: &OwnerReviewClosureV2Report,
    warning_reduction: &TraceCompletenessWarningReductionReport,
    disposition_report: &ModelVersionReviewDispositionReport,
) -> Vec<String> {
    let mut actions = owner_review_closure
        .items
        .iter()
        .filter_map(|item| {
            let action = match item.closure_action {
                OwnerReviewClosureActionV2::KeepResearchCandidate => None,
                OwnerReviewClosureActionV2::RequestMorePredictions => {
                    Some("RequestMorePredictions")
                }
                OwnerReviewClosureActionV2::RequestCalibrationReview => {
                    Some("RequestCalibrationReview")
                }
                OwnerReviewClosureActionV2::RequestRiskReview => Some("RequestRiskReview"),
                OwnerReviewClosureActionV2::MarkDiagnosticOnly => Some("MarkDiagnosticOnly"),
                OwnerReviewClosureActionV2::RetireModelVersion => Some("RetireWeakModelVersion"),
                OwnerReviewClosureActionV2::NeedMoreEvidence => Some("NeedMoreEvidence"),
            }?;
            Some(format!("{action}:{}:{}", item.model_id, item.model_version))
        })
        .collect::<Vec<_>>();
    actions.extend(
        warning_reduction
            .items
            .iter()
            .filter(|item| !item.reduced)
            .map(|item| {
                format!(
                    "ResolveWarning:{}:{}:{:?}",
                    item.model_id, item.model_version, item.dimension
                )
            }),
    );
    actions.extend(disposition_report.items.iter().filter_map(|item| {
        if item.disposition == ModelVersionReviewDispositionKind::KeepResearchCandidate {
            None
        } else {
            Some(format!(
                "{:?}:{}:{}",
                item.disposition, item.model_id, item.model_version
            ))
        }
    }));
    actions.push("KeepBaselineAndTrinity".to_string());
    actions.push("HoldMamba3RuntimeDeferred".to_string());
    actions.push("KeepStaticDashboardNow".to_string());
    actions.push("KeepTrinity".to_string());
    actions = stable_ordered_strings(&actions);
    actions.dedup();
    actions
}

