#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct OperatorBriefingConfig {
    pub briefing_id: String,
    #[serde(default)]
    pub unexpected_diff_triage_paths: Vec<String>,
    #[serde(default)]
    pub control_tower_diff_triage_paths: Vec<String>,
    #[serde(default)]
    pub trace_coverage_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_rollup_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_trace_paths: Vec<String>,
    #[serde(default)]
    pub baseline_snapshot_coverage_paths: Vec<String>,
    #[serde(default)]
    pub conservative_leaderboard_paths: Vec<String>,
    #[serde(default)]
    pub owner_review_paths: Vec<String>,
    #[serde(default)]
    pub kis_evidence_paths: Vec<String>,
    #[serde(default)]
    pub sequence_dataset_paths: Vec<String>,
    #[serde(default)]
    pub trinity_loop_paths: Vec<String>,
    #[serde(default)]
    pub risk_report_paths: Vec<String>,
    #[serde(default)]
    pub previous_briefing_paths: Vec<String>,
    #[serde(default = "default_operator_briefing_output_root")]
    pub output_root: String,
    #[serde(default = "default_operator_briefing_max_sections")]
    pub max_sections: usize,
    #[serde(default = "default_operator_briefing_max_items_per_section")]
    pub max_items_per_section: usize,
    #[serde(default = "default_operator_briefing_max_commands")]
    pub max_commands: usize,
    #[serde(default = "default_max_bytes")]
    pub max_bytes: usize,
    #[serde(default = "default_true")]
    pub render_html: bool,
    #[serde(default = "default_true")]
    pub render_json: bool,
    #[serde(default = "default_true")]
    pub render_text: bool,
    #[serde(default)]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for OperatorBriefingConfig {
    fn default() -> Self {
        Self {
            briefing_id: "sprint71-operator-briefing".to_string(),
            unexpected_diff_triage_paths: vec![
                "examples/soma_unexpected_diff_triage.toml".to_string(),
            ],
            control_tower_diff_triage_paths: Vec::new(),
            trace_coverage_paths: vec!["examples/soma_baseline_snapshot_coverage.toml".to_string()],
            model_ops_rollup_paths: vec!["examples/soma_model_ops_rollup.toml".to_string()],
            model_ops_trace_paths: Vec::new(),
            baseline_snapshot_coverage_paths: Vec::new(),
            conservative_leaderboard_paths: vec![
                "examples/sprint67_data/conservative_leaderboard.json".to_string(),
            ],
            owner_review_paths: Vec::new(),
            kis_evidence_paths: Vec::new(),
            sequence_dataset_paths: Vec::new(),
            trinity_loop_paths: Vec::new(),
            risk_report_paths: Vec::new(),
            previous_briefing_paths: Vec::new(),
            output_root: default_operator_briefing_output_root(),
            max_sections: default_operator_briefing_max_sections(),
            max_items_per_section: default_operator_briefing_max_items_per_section(),
            max_commands: default_operator_briefing_max_commands(),
            max_bytes: default_max_bytes(),
            render_html: true,
            render_json: true,
            render_text: true,
            reason_codes: stable_reason_codes(&[ReasonCode::OperatorBriefingConfigBuilt]),
        }
    }
}

impl OperatorBriefingConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let mut config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.reason_codes = stable_reason_codes(&[ReasonCode::OperatorBriefingConfigBuilt]);
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.briefing_id.trim().is_empty()
            || self.max_sections == 0
            || self.max_items_per_section == 0
            || self.max_commands == 0
            || self.max_bytes == 0
        {
            return Err(
                "operator briefing config requires briefing_id and positive limits".to_string(),
            );
        }
        if !(self.render_html || self.render_json || self.render_text) {
            return Err("operator briefing config requires at least one render target".to_string());
        }
        if self
            .input_paths()
            .into_iter()
            .chain(std::iter::once(self.output_root.clone()))
            .any(|path| path.contains("://"))
        {
            return Err("operator briefing config paths must be local".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.briefing_id)
    }

    pub fn input_paths(&self) -> Vec<String> {
        self.unexpected_diff_triage_paths
            .iter()
            .chain(self.control_tower_diff_triage_paths.iter())
            .chain(self.trace_coverage_paths.iter())
            .chain(self.model_ops_rollup_paths.iter())
            .chain(self.model_ops_trace_paths.iter())
            .chain(self.baseline_snapshot_coverage_paths.iter())
            .chain(self.conservative_leaderboard_paths.iter())
            .chain(self.owner_review_paths.iter())
            .chain(self.kis_evidence_paths.iter())
            .chain(self.sequence_dataset_paths.iter())
            .chain(self.trinity_loop_paths.iter())
            .chain(self.risk_report_paths.iter())
            .chain(self.previous_briefing_paths.iter())
            .cloned()
            .collect()
    }
}

