impl ControlTowerBriefingPanel {
    pub fn stabilize(&mut self) {
        self.section_summaries = stable_ordered_strings(&self.section_summaries);
        self.next_command_blocks
            .sort_by(|left, right| left.command_id.cmp(&right.command_id));
        self.fragment_links = self
            .fragment_links
            .iter()
            .map(|(key, value)| (key.clone(), value.clone()))
            .collect();
        self.reason_codes = stable_reason_codes(&self.reason_codes);
    }
}

