impl OperatorBriefingRunner {
    pub fn run(&self, config: &OperatorBriefingConfig) -> Result<OperatorBriefingBundle, String> {
        config.validate()?;
        let context = load_operator_briefing_context(config)?;
        let leaderboard_warning_closure_report =
            build_leaderboard_warning_closure_report(config, &context);
        let retirement_evidence_completion_report =
            build_retirement_evidence_completion_report(config, &context);
        let evidence_gap_closure_checklist = build_evidence_gap_closure_checklist(
            config,
            &context,
            &leaderboard_warning_closure_report,
            &retirement_evidence_completion_report,
        );
        let owner_action_checklist = build_owner_action_checklist(
            config,
            &context,
            &leaderboard_warning_closure_report,
            &retirement_evidence_completion_report,
        );
        let operator_decision_queue = build_operator_decision_queue(
            config,
            &owner_action_checklist,
            &leaderboard_warning_closure_report,
            &retirement_evidence_completion_report,
        );
        let runbook_command_blocks = build_runbook_command_blocks(config);
        let sections = build_briefing_sections(
            config,
            &context,
            &owner_action_checklist,
            &operator_decision_queue,
            &runbook_command_blocks,
            &leaderboard_warning_closure_report,
            &retirement_evidence_completion_report,
            &evidence_gap_closure_checklist,
        );
        let operator_briefing_report = build_operator_briefing_report(
            config,
            &context,
            sections,
            &owner_action_checklist,
            &operator_decision_queue,
            &runbook_command_blocks,
        );
        let daily_briefing_snapshot =
            build_daily_briefing_snapshot(config, &context, &operator_briefing_report);
        let briefing_delta_report =
            build_briefing_delta_report(config, &context, &operator_briefing_report);
        let mut control_tower_briefing_panel = build_control_tower_briefing_panel(
            config,
            &operator_briefing_report,
            &owner_action_checklist,
            &operator_decision_queue,
            &runbook_command_blocks,
            &evidence_gap_closure_checklist,
        );
        let rendered = StaticBriefingRenderer::default().render(
            config,
            &operator_briefing_report,
            &owner_action_checklist,
            &operator_decision_queue,
            &runbook_command_blocks,
            &daily_briefing_snapshot,
            briefing_delta_report.as_ref(),
            &leaderboard_warning_closure_report,
            &retirement_evidence_completion_report,
            &evidence_gap_closure_checklist,
            &mut control_tower_briefing_panel,
        )?;
        let final_summary = build_operator_briefing_final_summary(
            &operator_briefing_report,
            &owner_action_checklist,
            &leaderboard_warning_closure_report,
            &retirement_evidence_completion_report,
            &control_tower_briefing_panel,
            rendered.storage_report.storage_bytes,
        );
        let bundle = OperatorBriefingBundle {
            operator_briefing_report,
            owner_action_checklist,
            operator_decision_queue,
            runbook_command_blocks,
            daily_briefing_snapshot,
            briefing_delta_report,
            leaderboard_warning_closure_report,
            retirement_evidence_completion_report,
            evidence_gap_closure_checklist,
            control_tower_briefing_panel,
            static_briefing_files: rendered.static_files,
            storage_report: rendered.storage_report,
            final_summary,
            reason_codes: stable_reason_codes(&[
                ReasonCode::OperatorBriefingRunnerBuilt,
                ReasonCode::OperatorBriefingBundleBuilt,
            ]),
        };
        Ok(bundle)
    }

    pub fn run_operator_briefing(
        &self,
        config: &OperatorBriefingConfig,
    ) -> Result<OperatorBriefingReport, String> {
        Ok(self.run(config)?.operator_briefing_report)
    }

    pub fn run_owner_action_checklist(
        &self,
        config: &OperatorBriefingConfig,
    ) -> Result<OwnerActionChecklist, String> {
        Ok(self.run(config)?.owner_action_checklist)
    }

    pub fn run_operator_decision_queue(
        &self,
        config: &OperatorBriefingConfig,
    ) -> Result<OperatorDecisionQueue, String> {
        Ok(self.run(config)?.operator_decision_queue)
    }

    pub fn run_briefing_delta(
        &self,
        config: &OperatorBriefingConfig,
    ) -> Result<BriefingDeltaReport, String> {
        self.run(config)?
            .briefing_delta_report
            .ok_or_else(|| "no briefing delta report available".to_string())
    }

    pub fn run_leaderboard_warning_closure(
        &self,
        config: &OperatorBriefingConfig,
    ) -> Result<LeaderboardWarningClosureReport, String> {
        Ok(self.run(config)?.leaderboard_warning_closure_report)
    }

    pub fn run_retirement_evidence_completion(
        &self,
        config: &OperatorBriefingConfig,
    ) -> Result<RetirementEvidenceCompletionReport, String> {
        Ok(self.run(config)?.retirement_evidence_completion_report)
    }

    pub fn run_control_tower_briefing(
        &self,
        config: &OperatorBriefingConfig,
    ) -> Result<ControlTowerBriefingPanel, String> {
        Ok(self.run(config)?.control_tower_briefing_panel)
    }
}

