fn load_operator_briefing_context(
    config: &OperatorBriefingConfig,
) -> Result<OperatorBriefingContext, String> {
    let triage_bundle =
        load_operator_briefing_triage_bundle(if config.unexpected_diff_triage_paths.is_empty() {
            &config.control_tower_diff_triage_paths
        } else {
            &config.unexpected_diff_triage_paths
        })?;
    let coverage_bundle =
        load_operator_briefing_coverage_bundle(if config.trace_coverage_paths.is_empty() {
            &config.baseline_snapshot_coverage_paths
        } else {
            &config.trace_coverage_paths
        })?;
    let rollup_bundle = load_operator_briefing_rollup_bundle(&config.model_ops_rollup_paths)?;
    let trace_bundle = load_operator_briefing_trace_bundle(&config.model_ops_trace_paths)?;
    let leaderboard = load_first_report::<ConservativeExternalLeaderboard>(
        &config.conservative_leaderboard_paths,
    )?;
    let previous_briefing =
        load_previous_operator_briefing_report(&config.previous_briefing_paths)?;
    let input_paths = config.input_paths();
    let input_storage_bytes = input_paths
        .iter()
        .filter_map(|path| fs::metadata(path).ok())
        .map(|meta| meta.len() as usize)
        .sum();
    Ok(OperatorBriefingContext {
        triage_bundle,
        coverage_bundle,
        rollup_bundle,
        trace_bundle,
        leaderboard,
        previous_briefing,
        source_artifacts: unique_basenames(&input_paths),
        input_storage_bytes,
        kis_source_count: config.kis_evidence_paths.len(),
        sequence_source_count: config.sequence_dataset_paths.len(),
        trinity_source_count: config.trinity_loop_paths.len(),
        risk_source_count: config.risk_report_paths.len(),
        owner_review_source_count: config.owner_review_paths.len(),
    })
}

fn load_operator_briefing_triage_bundle(
    paths: &[String],
) -> Result<Option<UnexpectedDiffTriageBundle>, String> {
    for path in paths {
        if path.ends_with(".toml") {
            let config = UnexpectedDiffTriageConfig::from_toml_path(Path::new(path))?;
            config.validate()?;
            return Ok(Some(UnexpectedDiffTriageRunner::default().run(&config)?));
        }
        if let Ok(bundle) = read_json_file::<UnexpectedDiffTriageBundle>(path) {
            return Ok(Some(bundle));
        }
    }
    Ok(None)
}

