fn build_leaderboard_warning_closure_report(
    config: &OperatorBriefingConfig,
    context: &OperatorBriefingContext,
) -> LeaderboardWarningClosureReport {
    let card = rollup_cards(context).iter().find(|item| {
        item.rollup_key.model_id == "ext-model-a" && item.rollup_key.model_version == "1.2.0"
    });
    let entry = context.leaderboard.as_ref().and_then(|leaderboard| {
        leaderboard
            .entries
            .iter()
            .find(|item| item.model_id == "ext-model-a" && item.model_version == "1.2.0")
    });
    let (closure_status, closure_reason, next_action) = if let Some(entry) = entry {
        (
            LeaderboardWarningClosureStatus::WarningClosed,
            format!(
                "conservative leaderboard already contains ext-model-a:1.2.0 as {:?}; the warning can stay closed without any live promotion claim",
                entry.entry_status
            ),
            "no live promotion; keep the model in offline research-only comparison".to_string(),
        )
    } else if let Some(card) = card {
        (
            LeaderboardWarningClosureStatus::WarningExplained,
            format!(
                "rollup still marks ext-model-a:1.2.0 leaderboard_status={} and no conservative leaderboard entry is available, so the warning is explained but not over-claimed as closed",
                card.leaderboard_status
            ),
            "review the static leaderboard evidence locally and keep the model research-only"
                .to_string(),
        )
    } else {
        (
            LeaderboardWarningClosureStatus::NeedsMoreEvidence,
            "no ext-model-a:1.2.0 rollup card or conservative leaderboard evidence was available to interpret the warning".to_string(),
            "rerun local model-ops rollup and operator briefing inputs before making any comparison claim".to_string(),
        )
    };
    LeaderboardWarningClosureReport {
        warning_id: format!("{}-leaderboard-warning-ext-model-a-1-2-0", config.briefing_id),
        target_model_id: "ext-model-a".to_string(),
        target_model_version: "1.2.0".to_string(),
        warning_summary: "ext-model-a:1.2.0 leaderboard warning remains conservative and never implies rank promotion".to_string(),
        source_artifacts: collect_source_artifacts(
            &context.source_artifacts,
            &["conservative_leaderboard.json", "soma_model_ops_rollup.toml"],
        ),
        closure_status,
        closure_reason,
        next_action,
        reason_codes: stable_reason_codes(&[ReasonCode::LeaderboardWarningClosureBuilt]),
    }
}

fn build_retirement_evidence_completion_report(
    _config: &OperatorBriefingConfig,
    context: &OperatorBriefingContext,
) -> RetirementEvidenceCompletionReport {
    let card = rollup_cards(context).iter().find(|item| {
        item.rollup_key.model_id == "ext-model-a" && item.rollup_key.model_version == "1.0.0"
    });
    let newer_successor_exists = rollup_cards(context).iter().any(|item| {
        item.rollup_key.model_id == "ext-model-a" && item.rollup_key.model_version == "1.1.0"
    });
    let mut present_evidence = Vec::new();
    if let Some(card) = card {
        if card.recommended_action == ModelVersionSummaryStatus::RetireModelVersion {
            present_evidence.push("rollup recommends RetireModelVersion".to_string());
        }
        if card.lifecycle_status.eq_ignore_ascii_case("retired") {
            present_evidence.push("lifecycle status already marks the version retired".to_string());
        }
        if card.risk_level.as_deref() == Some("DiagnosticOnly") {
            present_evidence.push("risk rollup supports diagnostic-only handling".to_string());
        }
    }
    if newer_successor_exists {
        present_evidence.push("a newer comparable ext-model-a version exists locally".to_string());
    }
    if context.leaderboard.as_ref().is_some_and(|leaderboard| {
        leaderboard
            .entries
            .iter()
            .any(|item| item.model_id == "ext-model-a" && item.model_version == "1.0.0")
    }) {
        present_evidence.push("historical conservative leaderboard evidence exists".to_string());
    }
    let mut missing_evidence = Vec::new();
    if triage_regression_count(context, "ext-model-a", "1.0.0") == 0 {
        missing_evidence
            .push("regression evidence for ext-model-a:1.0.0 is still missing".to_string());
    }
    if context.owner_review_source_count == 0 {
        missing_evidence.push("owner review artifact for the retirement rationale is not attached directly to the briefing config".to_string());
    }
    let supports_retirement = missing_evidence.is_empty();
    let supports_diagnostic_downgrade = card
        .is_some_and(|item| item.risk_level.as_deref() == Some("DiagnosticOnly"))
        || present_evidence.iter().any(|item| item.contains("retired"));
    let completion_status = if supports_retirement {
        RetirementEvidenceCompletionStatus::RetirementEvidenceReady
    } else if missing_evidence
        .iter()
        .any(|item| item.to_ascii_lowercase().contains("regression"))
    {
        RetirementEvidenceCompletionStatus::NeedsMoreRegressionEvidence
    } else if supports_diagnostic_downgrade {
        RetirementEvidenceCompletionStatus::DiagnosticDowngradeSupported
    } else if context.owner_review_source_count == 0 {
        RetirementEvidenceCompletionStatus::NeedsOwnerReview
    } else {
        RetirementEvidenceCompletionStatus::RetirementEvidenceStillIncomplete
    };
    RetirementEvidenceCompletionReport {
        target_model_id: "ext-model-a".to_string(),
        target_model_version: "1.0.0".to_string(),
        required_evidence: vec![
            "owner retirement rationale".to_string(),
            "conservative regression evidence".to_string(),
            "historical leaderboard or comparable baseline evidence".to_string(),
            "newer local successor comparison".to_string(),
        ],
        present_evidence,
        missing_evidence,
        supports_retirement,
        supports_diagnostic_downgrade,
        completion_status,
        conservative_action: if supports_retirement {
            "retain the retirement decision in current comparisons; do not delete the model history"
                .to_string()
        } else if supports_diagnostic_downgrade {
            "keep ext-model-a:1.0.0 diagnostic-only and retired-from-current-comparison pending more evidence".to_string()
        } else {
            "request more local evidence before treating retirement as complete".to_string()
        },
        reason_codes: stable_reason_codes(&[ReasonCode::RetirementEvidenceCompletionBuilt]),
    }
}

fn build_evidence_gap_closure_checklist(
    config: &OperatorBriefingConfig,
    context: &OperatorBriefingContext,
    leaderboard_report: &LeaderboardWarningClosureReport,
    retirement_report: &RetirementEvidenceCompletionReport,
) -> EvidenceGapClosureChecklist {
    let mut gaps = Vec::new();
    gaps.push(EvidenceGapRecord {
        gap_id: format!("{}-gap-leaderboard-ext-model-a-1-2-0", config.briefing_id),
        gap_kind: EvidenceGapKind::MissingLeaderboardEvidence,
        target_id: "ext-model-a:1.2.0".to_string(),
        summary: leaderboard_report.closure_reason.clone(),
        closeable_now: leaderboard_report.closure_status
            != LeaderboardWarningClosureStatus::NeedsMoreEvidence,
        requires_owner_review: leaderboard_report.closure_status
            == LeaderboardWarningClosureStatus::WarningStillOpen,
        reason_codes: stable_reason_codes(&[ReasonCode::EvidenceGapClosureChecklistBuilt]),
    });
    gaps.push(EvidenceGapRecord {
        gap_id: format!("{}-gap-owner-reason-ext-model-a-1-2-0", config.briefing_id),
        gap_kind: EvidenceGapKind::MissingOwnerReason,
        target_id: "ext-model-a:1.2.0".to_string(),
        summary: "ext-model-a:1.2.0 has no explicit owner note in the rollup summary and should stay conservative".to_string(),
        closeable_now: false,
        requires_owner_review: true,
        reason_codes: stable_reason_codes(&[ReasonCode::EvidenceGapClosureChecklistBuilt]),
    });
    gaps.push(EvidenceGapRecord {
        gap_id: format!("{}-gap-retirement-ext-model-a-1-0-0", config.briefing_id),
        gap_kind: EvidenceGapKind::MissingRetirementEvidence,
        target_id: "ext-model-a:1.0.0".to_string(),
        summary: retirement_report.conservative_action.clone(),
        closeable_now: retirement_report.supports_retirement,
        requires_owner_review: true,
        reason_codes: stable_reason_codes(&[ReasonCode::EvidenceGapClosureChecklistBuilt]),
    });
    if !retirement_report
        .missing_evidence
        .iter()
        .all(|item| !item.to_ascii_lowercase().contains("regression"))
    {
        gaps.push(EvidenceGapRecord {
            gap_id: format!("{}-gap-regression-ext-model-a-1-0-0", config.briefing_id),
            gap_kind: EvidenceGapKind::MissingRegressionEvidence,
            target_id: "ext-model-a:1.0.0".to_string(),
            summary: "retirement still lacks explicit conservative regression evidence".to_string(),
            closeable_now: false,
            requires_owner_review: false,
            reason_codes: stable_reason_codes(&[ReasonCode::EvidenceGapClosureChecklistBuilt]),
        });
    }
    if let Some(card) = rollup_cards(context).iter().find(|item| {
        item.rollup_key.model_id == "ext-model-b" && item.rollup_key.model_version == "1.0.0"
    }) {
        if card.recommended_action == ModelVersionSummaryStatus::RequestMorePredictions {
            gaps.push(EvidenceGapRecord {
                gap_id: format!("{}-gap-predictions-ext-model-b-1-0-0", config.briefing_id),
                gap_kind: EvidenceGapKind::MissingPredictionHistory,
                target_id: "ext-model-b:1.0.0".to_string(),
                summary: "ext-model-b:1.0.0 still needs more offline prediction history"
                    .to_string(),
                closeable_now: false,
                requires_owner_review: false,
                reason_codes: stable_reason_codes(&[ReasonCode::EvidenceGapClosureChecklistBuilt]),
            });
        }
    }
    if context.sequence_source_count == 0 {
        gaps.push(EvidenceGapRecord {
            gap_id: format!("{}-gap-sequence", config.briefing_id),
            gap_kind: EvidenceGapKind::MissingSequenceRows,
            target_id: "sequence-dataset".to_string(),
            summary:
                "sequence dataset rows are not attached to the operator briefing and stay deferred"
                    .to_string(),
            closeable_now: false,
            requires_owner_review: false,
            reason_codes: stable_reason_codes(&[ReasonCode::EvidenceGapClosureChecklistBuilt]),
        });
    }
    let gap_count = gaps.len();
    let closeable_now_count = gaps.iter().filter(|item| item.closeable_now).count();
    let requires_owner_review_count = gaps
        .iter()
        .filter(|item| item.requires_owner_review)
        .count();
    let requires_data_count = gaps
        .iter()
        .filter(|item| !item.closeable_now && !item.requires_owner_review)
        .count();
    EvidenceGapClosureChecklist {
        checklist_id: format!("{}-evidence-gap-closure", config.briefing_id),
        gaps,
        gap_count,
        closeable_now_count,
        requires_data_count,
        requires_owner_review_count,
        reason_codes: stable_reason_codes(&[ReasonCode::EvidenceGapClosureChecklistBuilt]),
    }
}

fn build_owner_action_checklist(
    config: &OperatorBriefingConfig,
    context: &OperatorBriefingContext,
    leaderboard_report: &LeaderboardWarningClosureReport,
    retirement_report: &RetirementEvidenceCompletionReport,
) -> OwnerActionChecklist {
    let mut items = Vec::new();
    items.push(OwnerActionChecklistItem {
        item_id: format!("{}-leaderboard-warning", config.briefing_id),
        item_kind: OwnerActionChecklistItemKind::ReviewLeaderboardWarning,
        target_type: OwnerActionChecklistTargetType::ModelVersion,
        target_id: "ext-model-a:1.2.0".to_string(),
        title: "Review ext-model-a:1.2.0 leaderboard warning".to_string(),
        why_it_matters: leaderboard_report.closure_reason.clone(),
        safe_actions: vec![
            "review the static leaderboard evidence".to_string(),
            "rerun the local operator briefing".to_string(),
        ],
        forbidden_actions: default_forbidden_actions(),
        recommended_action: OwnerActionChecklistItemKind::ReviewLeaderboardWarning,
        command_suggestion: Some(
            "cargo run --quiet --bin soma_experiment -- leaderboard-warning-closure --config examples/soma_leaderboard_warning_closure.toml".to_string(),
        ),
        severity: if leaderboard_report.closure_status == LeaderboardWarningClosureStatus::WarningClosed {
            BriefingSeverity::Good
        } else {
            BriefingSeverity::Watch
        },
        reason_codes: stable_reason_codes(&[ReasonCode::OwnerActionChecklistBuilt]),
    });
    items.push(OwnerActionChecklistItem {
        item_id: format!("{}-retirement-evidence", config.briefing_id),
        item_kind: OwnerActionChecklistItemKind::ReviewRetirementEvidence,
        target_type: OwnerActionChecklistTargetType::ModelVersion,
        target_id: "ext-model-a:1.0.0".to_string(),
        title: "Review ext-model-a:1.0.0 retirement evidence".to_string(),
        why_it_matters: retirement_report.conservative_action.clone(),
        safe_actions: vec![
            "keep the version diagnostic-only".to_string(),
            "review local regression and owner-review evidence".to_string(),
        ],
        forbidden_actions: default_forbidden_actions(),
        recommended_action: if retirement_report.supports_retirement {
            OwnerActionChecklistItemKind::ReviewRetirementEvidence
        } else {
            OwnerActionChecklistItemKind::MarkDiagnosticOnly
        },
        command_suggestion: Some(
            "cargo run --quiet --bin soma_experiment -- retirement-evidence-completion --config examples/soma_retirement_evidence_completion.toml".to_string(),
        ),
        severity: if retirement_report.supports_retirement {
            BriefingSeverity::Watch
        } else {
            BriefingSeverity::Blocked
        },
        reason_codes: stable_reason_codes(&[ReasonCode::OwnerActionChecklistBuilt]),
    });
    if let Some(card) = rollup_cards(context).iter().find(|item| {
        item.rollup_key.model_id == "ext-model-b" && item.rollup_key.model_version == "1.0.0"
    }) {
        items.push(OwnerActionChecklistItem {
            item_id: format!("{}-review-model-disposition", config.briefing_id),
            item_kind: OwnerActionChecklistItemKind::ReviewModelDisposition,
            target_type: OwnerActionChecklistTargetType::ModelVersion,
            target_id: "ext-model-b:1.0.0".to_string(),
            title: "Review ext-model-b:1.0.0 model disposition".to_string(),
            why_it_matters: card.owner_notes_summary.clone(),
            safe_actions: vec![
                "review offline prediction coverage".to_string(),
                "keep the model research-only".to_string(),
            ],
            forbidden_actions: default_forbidden_actions(),
            recommended_action: OwnerActionChecklistItemKind::ProvideMorePredictions,
            command_suggestion: Some(
                "cargo run --quiet --bin soma_experiment -- operator-decision-queue --config examples/soma_operator_decision_queue.toml".to_string(),
            ),
            severity: BriefingSeverity::NeedsAction,
            reason_codes: stable_reason_codes(&[ReasonCode::OwnerActionChecklistBuilt]),
        });
        items.push(OwnerActionChecklistItem {
            item_id: format!("{}-provide-more-predictions", config.briefing_id),
            item_kind: OwnerActionChecklistItemKind::ProvideMorePredictions,
            target_type: OwnerActionChecklistTargetType::ModelVersion,
            target_id: "ext-model-b:1.0.0".to_string(),
            title: "Provide more offline predictions for ext-model-b:1.0.0".to_string(),
            why_it_matters: "current evidence remains conservative and prediction history is still too weak".to_string(),
            safe_actions: vec![
                "collect more offline predictions".to_string(),
                "rerun the static briefing after local artifacts update".to_string(),
            ],
            forbidden_actions: default_forbidden_actions(),
            recommended_action: OwnerActionChecklistItemKind::ProvideMorePredictions,
            command_suggestion: Some(
                "cargo run --quiet --bin soma_experiment -- operator-briefing --config examples/soma_operator_briefing.toml".to_string(),
            ),
            severity: BriefingSeverity::NeedsAction,
            reason_codes: stable_reason_codes(&[ReasonCode::OwnerActionChecklistBuilt]),
        });
    }
    items.sort_by(|left, right| left.item_id.cmp(&right.item_id));
    let required_count = items
        .iter()
        .filter(|item| {
            matches!(
                item.severity,
                BriefingSeverity::NeedsAction | BriefingSeverity::Blocked
            )
        })
        .count();
    let recommended_count = items
        .iter()
        .filter(|item| item.severity == BriefingSeverity::Watch)
        .count();
    let optional_count = items
        .iter()
        .filter(|item| item.severity == BriefingSeverity::Good)
        .count();
    let blocked_count = items
        .iter()
        .filter(|item| item.severity == BriefingSeverity::Blocked)
        .count();
    OwnerActionChecklist {
        checklist_id: format!("{}-owner-action-checklist", config.briefing_id),
        items,
        required_count,
        recommended_count,
        optional_count,
        blocked_count,
        checklist_status: if blocked_count > 0 || required_count > 0 {
            OwnerActionChecklistStatus::NeedsOwnerAction
        } else if recommended_count > 0 {
            OwnerActionChecklistStatus::ChecklistReady
        } else {
            OwnerActionChecklistStatus::NoOwnerActionNeeded
        },
        reason_codes: stable_reason_codes(&[ReasonCode::OwnerActionChecklistBuilt]),
    }
}

fn build_operator_decision_queue(
    config: &OperatorBriefingConfig,
    checklist: &OwnerActionChecklist,
    leaderboard_report: &LeaderboardWarningClosureReport,
    retirement_report: &RetirementEvidenceCompletionReport,
) -> OperatorDecisionQueue {
    let mut items = Vec::new();
    items.push(OperatorDecisionQueueItem {
        decision_id: format!("{}-queue-leaderboard", config.briefing_id),
        title: "Accept conservative leaderboard warning handling".to_string(),
        target_id: "ext-model-a:1.2.0".to_string(),
        status: if leaderboard_report.closure_status
            == LeaderboardWarningClosureStatus::NeedsMoreEvidence
        {
            OperatorDecisionQueueItemStatus::Blocked
        } else {
            OperatorDecisionQueueItemStatus::ReadyToReview
        },
        decision_options: vec![
            OperatorDecisionOption::KeepResearchCandidate,
            OperatorDecisionOption::DeferReview,
            OperatorDecisionOption::NoAction,
        ],
        forbidden_options: default_forbidden_decision_options(),
        default_safe_option: OperatorDecisionOption::DeferReview,
        reason_codes: stable_reason_codes(&[ReasonCode::OperatorDecisionQueueBuilt]),
    });
    items.push(OperatorDecisionQueueItem {
        decision_id: format!("{}-queue-retirement", config.briefing_id),
        title: "Keep ext-model-a:1.0.0 diagnostic-only until retirement evidence is complete"
            .to_string(),
        target_id: "ext-model-a:1.0.0".to_string(),
        status: if retirement_report.supports_retirement {
            OperatorDecisionQueueItemStatus::ReadyToReview
        } else {
            OperatorDecisionQueueItemStatus::Blocked
        },
        decision_options: vec![
            OperatorDecisionOption::MarkDiagnosticOnly,
            OperatorDecisionOption::DeferReview,
            OperatorDecisionOption::NoAction,
        ],
        forbidden_options: default_forbidden_decision_options(),
        default_safe_option: OperatorDecisionOption::MarkDiagnosticOnly,
        reason_codes: stable_reason_codes(&[ReasonCode::OperatorDecisionQueueBuilt]),
    });
    items.push(OperatorDecisionQueueItem {
        decision_id: format!("{}-queue-predictions", config.briefing_id),
        title: "Request more offline predictions for ext-model-b:1.0.0".to_string(),
        target_id: "ext-model-b:1.0.0".to_string(),
        status: OperatorDecisionQueueItemStatus::Pending,
        decision_options: vec![
            OperatorDecisionOption::RequestMorePredictions,
            OperatorDecisionOption::RequestCalibrationReview,
            OperatorDecisionOption::RequestRiskReview,
            OperatorDecisionOption::DeferReview,
        ],
        forbidden_options: default_forbidden_decision_options(),
        default_safe_option: OperatorDecisionOption::RequestMorePredictions,
        reason_codes: stable_reason_codes(&[ReasonCode::OperatorDecisionQueueBuilt]),
    });
    items.push(OperatorDecisionQueueItem {
        decision_id: format!("{}-queue-keep-current", config.briefing_id),
        title: "Keep ext-model-a:1.1.0 as the current research candidate".to_string(),
        target_id: "ext-model-a:1.1.0".to_string(),
        status: OperatorDecisionQueueItemStatus::Closed,
        decision_options: vec![
            OperatorDecisionOption::KeepResearchCandidate,
            OperatorDecisionOption::NoAction,
        ],
        forbidden_options: default_forbidden_decision_options(),
        default_safe_option: OperatorDecisionOption::KeepResearchCandidate,
        reason_codes: stable_reason_codes(&[ReasonCode::OperatorDecisionQueueBuilt]),
    });
    if checklist.recommended_count > 0 || checklist.required_count > 0 {
        items.push(OperatorDecisionQueueItem {
            decision_id: format!("{}-queue-deferred-runtime", config.briefing_id),
            title: "Runtime, training, live, order, and account capabilities remain deferred"
                .to_string(),
            target_id: "system".to_string(),
            status: OperatorDecisionQueueItemStatus::Deferred,
            decision_options: vec![
                OperatorDecisionOption::DeferReview,
                OperatorDecisionOption::NoAction,
            ],
            forbidden_options: default_forbidden_decision_options(),
            default_safe_option: OperatorDecisionOption::DeferReview,
            reason_codes: stable_reason_codes(&[ReasonCode::OperatorDecisionQueueBuilt]),
        });
    }
    items.sort_by(|left, right| left.decision_id.cmp(&right.decision_id));
    OperatorDecisionQueue {
        queue_id: format!("{}-operator-decision-queue", config.briefing_id),
        pending_count: items
            .iter()
            .filter(|item| item.status == OperatorDecisionQueueItemStatus::Pending)
            .count(),
        ready_count: items
            .iter()
            .filter(|item| item.status == OperatorDecisionQueueItemStatus::ReadyToReview)
            .count(),
        blocked_count: items
            .iter()
            .filter(|item| item.status == OperatorDecisionQueueItemStatus::Blocked)
            .count(),
        closed_count: items
            .iter()
            .filter(|item| item.status == OperatorDecisionQueueItemStatus::Closed)
            .count(),
        items,
        reason_codes: stable_reason_codes(&[ReasonCode::OperatorDecisionQueueBuilt]),
    }
}

fn build_runbook_command_blocks(config: &OperatorBriefingConfig) -> Vec<RunbookCommandBlock> {
    let commands = [
        (
            "operator-briefing",
            "Generate the full static operator briefing",
            "cargo run --quiet --bin soma_experiment -- operator-briefing --config examples/soma_operator_briefing.toml",
            "operator briefing JSON report",
        ),
        (
            "owner-action-checklist",
            "Render the owner action checklist",
            "cargo run --quiet --bin soma_experiment -- owner-action-checklist --config examples/soma_owner_action_checklist.toml",
            "owner action checklist JSON report",
        ),
        (
            "operator-decision-queue",
            "Render the operator decision queue",
            "cargo run --quiet --bin soma_experiment -- operator-decision-queue --config examples/soma_operator_decision_queue.toml",
            "operator decision queue JSON report",
        ),
        (
            "briefing-delta",
            "Render the current briefing delta",
            "cargo run --quiet --bin soma_experiment -- briefing-delta --config examples/soma_briefing_delta.toml",
            "briefing delta JSON report",
        ),
        (
            "leaderboard-warning-closure",
            "Render the leaderboard warning closure report",
            "cargo run --quiet --bin soma_experiment -- leaderboard-warning-closure --config examples/soma_leaderboard_warning_closure.toml",
            "leaderboard warning closure JSON report",
        ),
        (
            "retirement-evidence-completion",
            "Render the retirement evidence completion report",
            "cargo run --quiet --bin soma_experiment -- retirement-evidence-completion --config examples/soma_retirement_evidence_completion.toml",
            "retirement evidence completion JSON report",
        ),
        (
            "control-tower-briefing",
            "Render the one-screen Control Tower briefing panel",
            "cargo run --quiet --bin soma_experiment -- control-tower-briefing --config examples/soma_control_tower_briefing.toml",
            "control tower briefing panel JSON report",
        ),
    ];
    let mut blocks = commands
        .iter()
        .take(config.max_commands.saturating_sub(1))
        .map(|(id, title, command, output)| RunbookCommandBlock {
            command_id: format!("{}-{}", config.briefing_id, id),
            title: (*title).to_string(),
            command_text: (*command).to_string(),
            expected_output: (*output).to_string(),
            safe_to_copy: true,
            safe_to_run: true,
            forbidden_reason: None,
            reason_codes: stable_reason_codes(&[ReasonCode::RunbookCommandBlockBuilt]),
        })
        .collect::<Vec<_>>();
    blocks.push(RunbookCommandBlock {
        command_id: format!("{}-forbidden-runtime", config.briefing_id),
        title: "Runtime, training, and execution commands remain unavailable".to_string(),
        command_text: "not-available".to_string(),
        expected_output:
            "operator briefing mode intentionally omits live/runtime/order/account commands"
                .to_string(),
        safe_to_copy: false,
        safe_to_run: false,
        forbidden_reason: Some(
            "live, runtime, training, order, and account paths are outside operator briefing mode"
                .to_string(),
        ),
        reason_codes: stable_reason_codes(&[ReasonCode::RunbookCommandBlockBuilt]),
    });
    blocks.sort_by(|left, right| left.command_id.cmp(&right.command_id));
    blocks
}

fn build_briefing_sections(
    config: &OperatorBriefingConfig,
    context: &OperatorBriefingContext,
    checklist: &OwnerActionChecklist,
    queue: &OperatorDecisionQueue,
    runbook_blocks: &[RunbookCommandBlock],
    leaderboard_report: &LeaderboardWarningClosureReport,
    retirement_report: &RetirementEvidenceCompletionReport,
    gaps: &EvidenceGapClosureChecklist,
) -> Vec<BriefingSection> {
    let readiness_estimate =
        direct_watch_readiness_estimate(checklist, leaderboard_report, retirement_report);
    let copyable_commands = runbook_blocks
        .iter()
        .filter(|item| item.safe_to_copy)
        .map(|item| item.command_text.clone())
        .take(config.max_items_per_section)
        .collect::<Vec<_>>();
    let mut sections = vec![
        BriefingSection {
            section_id: format!("{}-system-health", config.briefing_id),
            section_kind: BriefingSectionKind::SystemHealth,
            title: "System health".to_string(),
            severity: if checklist.blocked_count > 0 {
                BriefingSeverity::Watch
            } else {
                BriefingSeverity::Good
            },
            headline: format!(
                "static direct-watch readiness {} for local paper/research monitoring only; never live-ready",
                readiness_estimate
            ),
            bullet_items: vec![
                format!("source_artifacts={}", context.source_artifacts.len()),
                format!("input_storage_bytes={}", context.input_storage_bytes),
                "control plane remains static/read-only with no execution buttons".to_string(),
            ],
            blockers: Vec::new(),
            warnings: vec![
                "live trading, runtime inference, and model training remain out of scope"
                    .to_string(),
            ],
            next_actions: copyable_commands.iter().take(2).cloned().collect(),
            source_artifacts: context.source_artifacts.clone(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-kis-data", config.briefing_id),
            section_kind: BriefingSectionKind::KISData,
            title: "KIS data".to_string(),
            severity: if context.kis_source_count == 0 {
                BriefingSeverity::Deferred
            } else {
                BriefingSeverity::Watch
            },
            headline: if context.kis_source_count == 0 {
                "KIS evidence is not attached to this briefing and remains deferred".to_string()
            } else {
                format!(
                    "{} local KIS evidence artifact(s) are attached for static review",
                    context.kis_source_count
                )
            },
            bullet_items: Vec::new(),
            blockers: Vec::new(),
            warnings: if context.kis_source_count == 0 {
                vec![
                    "no KIS runtime or account path is available from operator briefing mode"
                        .to_string(),
                ]
            } else {
                Vec::new()
            },
            next_actions: Vec::new(),
            source_artifacts: collect_source_artifacts(&context.source_artifacts, &[]),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-evidence", config.briefing_id),
            section_kind: BriefingSectionKind::Evidence,
            title: "Evidence".to_string(),
            severity: if gaps.requires_data_count > 0 {
                BriefingSeverity::NeedsAction
            } else {
                BriefingSeverity::Good
            },
            headline: format!(
                "evidence gaps={} closeable_now={} requires_data={} trace_status={}",
                gaps.gap_count,
                gaps.closeable_now_count,
                gaps.requires_data_count,
                context
                    .coverage_bundle
                    .as_ref()
                    .map(|bundle| format!("{:?}", bundle.trace_completeness_audit.audit_status))
                    .unwrap_or_else(|| "Deferred".to_string())
            ),
            bullet_items: gaps
                .gaps
                .iter()
                .take(config.max_items_per_section)
                .map(|item| item.summary.clone())
                .collect(),
            blockers: retirement_report.missing_evidence.clone(),
            warnings: vec![leaderboard_report.warning_summary.clone()],
            next_actions: copyable_commands.iter().take(2).cloned().collect(),
            source_artifacts: collect_source_artifacts(
                &context.source_artifacts,
                &[
                    "soma_baseline_snapshot_coverage.toml",
                    "soma_unexpected_diff_triage.toml",
                ],
            ),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-committee", config.briefing_id),
            section_kind: BriefingSectionKind::Committee,
            title: "Committee".to_string(),
            severity: if context.trinity_source_count == 0 {
                BriefingSeverity::Deferred
            } else {
                BriefingSeverity::Watch
            },
            headline: if context.trinity_source_count == 0 {
                "committee/trinity loop artifacts are not attached and stay deferred".to_string()
            } else {
                format!(
                    "{} local trinity loop artifact(s) available for static review",
                    context.trinity_source_count
                )
            },
            bullet_items: Vec::new(),
            blockers: Vec::new(),
            warnings: vec![
                "committee status still does not imply live execution readiness".to_string(),
            ],
            next_actions: Vec::new(),
            source_artifacts: Vec::new(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-chair", config.briefing_id),
            section_kind: BriefingSectionKind::Chair,
            title: "Chair".to_string(),
            severity: if queue.ready_count > 0 {
                BriefingSeverity::Watch
            } else {
                BriefingSeverity::Deferred
            },
            headline: format!(
                "chair-facing decisions ready={} blocked={} closed={}",
                queue.ready_count, queue.blocked_count, queue.closed_count
            ),
            bullet_items: queue
                .items
                .iter()
                .take(config.max_items_per_section)
                .map(|item| item.title.clone())
                .collect(),
            blockers: queue
                .items
                .iter()
                .filter(|item| item.status == OperatorDecisionQueueItemStatus::Blocked)
                .map(|item| item.title.clone())
                .collect(),
            warnings: Vec::new(),
            next_actions: copyable_commands.iter().take(1).cloned().collect(),
            source_artifacts: Vec::new(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-risk", config.briefing_id),
            section_kind: BriefingSectionKind::Risk,
            title: "Risk".to_string(),
            severity: if context.risk_source_count == 0
                && model_ops_risk_count(context, "Critical") == 0
            {
                BriefingSeverity::Deferred
            } else if model_ops_risk_count(context, "Critical") > 0 {
                BriefingSeverity::NeedsAction
            } else {
                BriefingSeverity::Watch
            },
            headline: format!(
                "critical_risk_models={} risk_inputs={}",
                model_ops_risk_count(context, "Critical"),
                context.risk_source_count
            ),
            bullet_items: rollup_cards(context)
                .iter()
                .filter_map(|item| {
                    item.risk_level.clone().map(|risk| {
                        format!(
                            "{}:{}={}",
                            item.rollup_key.model_id, item.rollup_key.model_version, risk
                        )
                    })
                })
                .take(config.max_items_per_section)
                .collect(),
            blockers: Vec::new(),
            warnings: vec![
                "risk review stays paper-only and does not create live trading permission"
                    .to_string(),
            ],
            next_actions: copyable_commands.iter().take(1).cloned().collect(),
            source_artifacts: collect_source_artifacts(
                &context.source_artifacts,
                &["soma_model_ops_rollup.toml"],
            ),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-owner-review", config.briefing_id),
            section_kind: BriefingSectionKind::OwnerReview,
            title: "Owner review".to_string(),
            severity: if checklist.blocked_count > 0 || checklist.required_count > 0 {
                BriefingSeverity::NeedsAction
            } else {
                BriefingSeverity::Watch
            },
            headline: format!(
                "owner checklist status={:?} required={} recommended={} blocked={}",
                checklist.checklist_status,
                checklist.required_count,
                checklist.recommended_count,
                checklist.blocked_count
            ),
            bullet_items: checklist
                .items
                .iter()
                .take(config.max_items_per_section)
                .map(|item| item.title.clone())
                .collect(),
            blockers: checklist
                .items
                .iter()
                .filter(|item| item.severity == BriefingSeverity::Blocked)
                .map(|item| item.title.clone())
                .collect(),
            warnings: checklist
                .items
                .iter()
                .filter(|item| item.severity == BriefingSeverity::Watch)
                .map(|item| item.title.clone())
                .take(config.max_items_per_section)
                .collect(),
            next_actions: copyable_commands.iter().take(2).cloned().collect(),
            source_artifacts: collect_source_artifacts(&context.source_artifacts, &[]),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-paper-ops", config.briefing_id),
            section_kind: BriefingSectionKind::PaperOps,
            title: "Paper ops".to_string(),
            severity: BriefingSeverity::Good,
            headline: "operator briefing mode stays local, static, copy-only, and paper-only"
                .to_string(),
            bullet_items: vec![
                "no browser POST or execution control exists".to_string(),
                "copyable commands remain local-only and deterministic".to_string(),
            ],
            blockers: Vec::new(),
            warnings: vec![
                "paper-only does not mean broker or account execution exists".to_string(),
            ],
            next_actions: copyable_commands.iter().take(2).cloned().collect(),
            source_artifacts: Vec::new(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-sequence-dataset", config.briefing_id),
            section_kind: BriefingSectionKind::SequenceDataset,
            title: "Sequence dataset".to_string(),
            severity: if context.sequence_source_count == 0 {
                BriefingSeverity::Deferred
            } else {
                BriefingSeverity::Watch
            },
            headline: if context.sequence_source_count == 0 {
                "sequence dataset artifacts are not attached and stay deferred".to_string()
            } else {
                format!(
                    "{} local sequence artifact(s) attached for static review",
                    context.sequence_source_count
                )
            },
            bullet_items: Vec::new(),
            blockers: Vec::new(),
            warnings: vec!["no sequence export implies training or model runtime".to_string()],
            next_actions: Vec::new(),
            source_artifacts: Vec::new(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-external-models", config.briefing_id),
            section_kind: BriefingSectionKind::ExternalModels,
            title: "External models".to_string(),
            severity: if checklist.required_count > 0 {
                BriefingSeverity::Watch
            } else {
                BriefingSeverity::Good
            },
            headline: format!(
                "{} external model card(s) summarized",
                rollup_cards(context).len()
            ),
            bullet_items: rollup_cards(context)
                .iter()
                .take(config.max_items_per_section)
                .map(|item| {
                    format!(
                        "{}:{} -> {:?}",
                        item.rollup_key.model_id,
                        item.rollup_key.model_version,
                        item.recommended_action
                    )
                })
                .collect(),
            blockers: Vec::new(),
            warnings: vec!["research candidate status never implies deployment".to_string()],
            next_actions: copyable_commands.iter().take(2).cloned().collect(),
            source_artifacts: collect_source_artifacts(
                &context.source_artifacts,
                &["soma_model_ops_rollup.toml"],
            ),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-leaderboard", config.briefing_id),
            section_kind: BriefingSectionKind::Leaderboard,
            title: "Leaderboard".to_string(),
            severity: if leaderboard_report.closure_status
                == LeaderboardWarningClosureStatus::WarningClosed
            {
                BriefingSeverity::Good
            } else {
                BriefingSeverity::Watch
            },
            headline: format!(
                "leaderboard warning status={:?} for ext-model-a:1.2.0",
                leaderboard_report.closure_status
            ),
            bullet_items: vec![leaderboard_report.closure_reason.clone()],
            blockers: Vec::new(),
            warnings: vec!["leaderboard closure never implies usefulness or promotion".to_string()],
            next_actions: vec![leaderboard_report.next_action.clone()],
            source_artifacts: leaderboard_report.source_artifacts.clone(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-diff-trace", config.briefing_id),
            section_kind: BriefingSectionKind::DiffTrace,
            title: "Diff trace".to_string(),
            severity: if context.triage_bundle.is_some() {
                BriefingSeverity::Watch
            } else {
                BriefingSeverity::Deferred
            },
            headline: if let Some(bundle) = &context.triage_bundle {
                format!(
                    "triage_status={:?} unexpected_diff_count={} remaining_trace_warnings={}",
                    bundle.unexpected_diff_triage_report.triage_status,
                    bundle.unexpected_diff_triage_report.unexpected_diff_count,
                    bundle
                        .trace_completeness_warning_reduction_report
                        .remaining_warning_count
                )
            } else {
                "unexpected diff triage inputs are not attached and stay deferred".to_string()
            },
            bullet_items: if let Some(bundle) = &context.triage_bundle {
                bundle
                    .unexpected_diff_triage_report
                    .items
                    .iter()
                    .take(config.max_items_per_section)
                    .map(|item| {
                        format!(
                            "{}:{} -> {:?}",
                            item.model_id, item.model_version, item.classification
                        )
                    })
                    .collect()
            } else {
                Vec::new()
            },
            blockers: if let Some(bundle) = &context.triage_bundle {
                bundle
                    .trace_completeness_warning_reduction_report
                    .items
                    .iter()
                    .filter(|item| !item.reduced)
                    .map(|item| {
                        format!(
                            "{}:{} {:?}",
                            item.model_id, item.model_version, item.dimension
                        )
                    })
                    .collect()
            } else {
                Vec::new()
            },
            warnings: Vec::new(),
            next_actions: copyable_commands.iter().take(2).cloned().collect(),
            source_artifacts: collect_source_artifacts(
                &context.source_artifacts,
                &[
                    "soma_unexpected_diff_triage.toml",
                    "soma_baseline_snapshot_coverage.toml",
                ],
            ),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-deferred-items", config.briefing_id),
            section_kind: BriefingSectionKind::DeferredItems,
            title: "Deferred items".to_string(),
            severity: BriefingSeverity::Deferred,
            headline: "runtime, training, broker, order, account, and cloud UI remain deferred"
                .to_string(),
            bullet_items: build_deferred_items(context),
            blockers: Vec::new(),
            warnings: Vec::new(),
            next_actions: Vec::new(),
            source_artifacts: Vec::new(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
        BriefingSection {
            section_id: format!("{}-next-actions", config.briefing_id),
            section_kind: BriefingSectionKind::NextActions,
            title: "Next actions".to_string(),
            severity: if checklist.required_count > 0 {
                BriefingSeverity::NeedsAction
            } else {
                BriefingSeverity::Watch
            },
            headline: "copyable local commands only; no browser execution".to_string(),
            bullet_items: runbook_blocks
                .iter()
                .filter(|item| item.safe_to_copy)
                .take(config.max_items_per_section)
                .map(|item| item.title.clone())
                .collect(),
            blockers: runbook_blocks
                .iter()
                .filter(|item| !item.safe_to_run)
                .map(|item| item.title.clone())
                .collect(),
            warnings: vec!["unsafe runtime and live commands are intentionally absent".to_string()],
            next_actions: copyable_commands,
            source_artifacts: Vec::new(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingSectionBuilt]),
        },
    ];
    for section in &mut sections {
        section.bullet_items = limit_strings(&section.bullet_items, config.max_items_per_section);
        section.blockers = limit_strings(&section.blockers, config.max_items_per_section);
        section.warnings = limit_strings(&section.warnings, config.max_items_per_section);
        section.next_actions = limit_strings(&section.next_actions, config.max_items_per_section);
        section.source_artifacts = unique_basenames(&section.source_artifacts);
        section.reason_codes = stable_reason_codes(&section.reason_codes);
    }
    sections.truncate(config.max_sections);
    sections
}

fn build_operator_briefing_report(
    config: &OperatorBriefingConfig,
    context: &OperatorBriefingContext,
    sections: Vec<BriefingSection>,
    checklist: &OwnerActionChecklist,
    queue: &OperatorDecisionQueue,
    runbook_blocks: &[RunbookCommandBlock],
) -> OperatorBriefingReport {
    let overall_severity = aggregate_briefing_severity(&sections);
    let copyable_commands = runbook_blocks
        .iter()
        .filter(|item| item.safe_to_copy)
        .map(|item| item.command_text.clone())
        .take(config.max_commands)
        .collect::<Vec<_>>();
    let blocked_items = sections
        .iter()
        .flat_map(|item| item.blockers.iter().cloned())
        .collect::<Vec<_>>();
    let deferred_items = build_deferred_items(context);
    let owner_attention_items = checklist
        .items
        .iter()
        .filter(|item| {
            matches!(
                item.severity,
                BriefingSeverity::Watch | BriefingSeverity::NeedsAction | BriefingSeverity::Blocked
            )
        })
        .map(|item| item.title.clone())
        .take(config.max_items_per_section)
        .collect::<Vec<_>>();
    let briefing_status = if context.source_artifacts.is_empty() {
        OperatorBriefingStatus::MissingSourceArtifacts
    } else if queue.blocked_count > 0 {
        OperatorBriefingStatus::NeedsMoreEvidence
    } else if checklist.required_count > 0 || checklist.blocked_count > 0 {
        OperatorBriefingStatus::NeedsOwnerAction
    } else if briefing_severity_rank(overall_severity)
        >= briefing_severity_rank(BriefingSeverity::Watch)
    {
        OperatorBriefingStatus::BriefingReadyWithWarnings
    } else {
        OperatorBriefingStatus::BriefingReady
    };
    OperatorBriefingReport {
        briefing_id: config.briefing_id.clone(),
        sections,
        overall_severity,
        primary_headline: format!(
            "operator briefing {:?}; direct-watch readiness {} for local paper/research monitoring only",
            briefing_status,
            direct_watch_readiness_estimate(
                checklist,
                &build_leaderboard_warning_closure_report(config, context),
                &build_retirement_evidence_completion_report(config, context),
            )
        ),
        primary_next_action: copyable_commands
            .first()
            .cloned()
            .unwrap_or_else(|| "no copyable commands available".to_string()),
        owner_attention_items,
        blocked_items: limit_strings(&blocked_items, config.max_items_per_section),
        deferred_items,
        copyable_commands,
        source_artifacts: context.source_artifacts.clone(),
        briefing_status,
        reason_codes: stable_reason_codes(&[ReasonCode::OperatorBriefingReportBuilt]),
    }
}

fn build_daily_briefing_snapshot(
    config: &OperatorBriefingConfig,
    context: &OperatorBriefingContext,
    report: &OperatorBriefingReport,
) -> DailyBriefingSnapshot {
    let sections_hash = stable_hash_string(
        &serde_json::to_string(&report.sections).unwrap_or_else(|_| "[]".to_string()),
    );
    let source_artifact_hash = stable_hash_string(&report.source_artifacts.join("|"));
    DailyBriefingSnapshot {
        snapshot_id: format!("{}-{}", config.briefing_id, &sections_hash[..12]),
        briefing_id: config.briefing_id.clone(),
        generated_from: context.source_artifacts.clone(),
        sections_hash,
        source_artifact_hash,
        primary_status: format!("{:?}", report.briefing_status),
        primary_next_action: report.primary_next_action.clone(),
        owner_attention_count: report.owner_attention_items.len(),
        deferred_count: report.deferred_items.len(),
        reason_codes: stable_reason_codes(&[ReasonCode::DailyBriefingSnapshotBuilt]),
    }
}

fn build_briefing_delta_report(
    config: &OperatorBriefingConfig,
    context: &OperatorBriefingContext,
    report: &OperatorBriefingReport,
) -> Option<BriefingDeltaReport> {
    let previous = if let Some(previous) = context.previous_briefing.as_ref() {
        previous
    } else {
        return Some(BriefingDeltaReport {
            records: vec![BriefingDeltaRecord {
                delta_id: format!("{}-delta-no-previous", config.briefing_id),
                delta_kind: BriefingDeltaKind::NoChange,
                target_id: None,
                before: None,
                after: None,
                summary: "no previous briefing was provided".to_string(),
                reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
            }],
            changed_count: 0,
            added_warning_count: 0,
            resolved_warning_count: 0,
            owner_action_delta_count: 0,
            report_status: BriefingDeltaStatus::NoPreviousBriefing,
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    };
    let mut records = Vec::new();
    if previous.briefing_status != report.briefing_status {
        records.push(BriefingDeltaRecord {
            delta_id: format!("{}-delta-status", config.briefing_id),
            delta_kind: BriefingDeltaKind::StatusChanged,
            target_id: None,
            before: Some(format!("{:?}", previous.briefing_status)),
            after: Some(format!("{:?}", report.briefing_status)),
            summary: "briefing status changed".to_string(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    let previous_warnings = flatten_section_items(&previous.sections, |section| &section.warnings);
    let current_warnings = flatten_section_items(&report.sections, |section| &section.warnings);
    for warning in current_warnings.difference(&previous_warnings) {
        records.push(BriefingDeltaRecord {
            delta_id: format!(
                "{}-delta-warning-added-{}",
                config.briefing_id,
                stable_hash_string(warning)
            ),
            delta_kind: BriefingDeltaKind::WarningAdded,
            target_id: None,
            before: None,
            after: Some(warning.clone()),
            summary: format!("warning added: {warning}"),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    for warning in previous_warnings.difference(&current_warnings) {
        records.push(BriefingDeltaRecord {
            delta_id: format!(
                "{}-delta-warning-removed-{}",
                config.briefing_id,
                stable_hash_string(warning)
            ),
            delta_kind: BriefingDeltaKind::WarningRemoved,
            target_id: None,
            before: Some(warning.clone()),
            after: None,
            summary: format!("warning removed: {warning}"),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    let previous_attention = previous
        .owner_attention_items
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let current_attention = report
        .owner_attention_items
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    for item in current_attention.difference(&previous_attention) {
        records.push(BriefingDeltaRecord {
            delta_id: format!(
                "{}-delta-owner-added-{}",
                config.briefing_id,
                stable_hash_string(item)
            ),
            delta_kind: BriefingDeltaKind::OwnerActionAdded,
            target_id: None,
            before: None,
            after: Some(item.clone()),
            summary: format!("owner action added: {item}"),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    for item in previous_attention.difference(&current_attention) {
        records.push(BriefingDeltaRecord {
            delta_id: format!(
                "{}-delta-owner-resolved-{}",
                config.briefing_id,
                stable_hash_string(item)
            ),
            delta_kind: BriefingDeltaKind::OwnerActionResolved,
            target_id: None,
            before: Some(item.clone()),
            after: None,
            summary: format!("owner action resolved: {item}"),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    let previous_deferred = previous
        .deferred_items
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let current_deferred = report
        .deferred_items
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    for item in current_deferred.difference(&previous_deferred) {
        records.push(BriefingDeltaRecord {
            delta_id: format!(
                "{}-delta-deferred-added-{}",
                config.briefing_id,
                stable_hash_string(item)
            ),
            delta_kind: BriefingDeltaKind::DeferredAdded,
            target_id: None,
            before: None,
            after: Some(item.clone()),
            summary: format!("deferred item added: {item}"),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    for item in previous_deferred.difference(&current_deferred) {
        records.push(BriefingDeltaRecord {
            delta_id: format!(
                "{}-delta-deferred-removed-{}",
                config.briefing_id,
                stable_hash_string(item)
            ),
            delta_kind: BriefingDeltaKind::DeferredRemoved,
            target_id: None,
            before: Some(item.clone()),
            after: None,
            summary: format!("deferred item removed: {item}"),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    if previous.copyable_commands != report.copyable_commands {
        records.push(BriefingDeltaRecord {
            delta_id: format!("{}-delta-command-changed", config.briefing_id),
            delta_kind: BriefingDeltaKind::CommandChanged,
            target_id: None,
            before: Some(previous.copyable_commands.join(" || ")),
            after: Some(report.copyable_commands.join(" || ")),
            summary: "copyable command set changed".to_string(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    if records.is_empty() {
        records.push(BriefingDeltaRecord {
            delta_id: format!("{}-delta-no-change", config.briefing_id),
            delta_kind: BriefingDeltaKind::NoChange,
            target_id: None,
            before: None,
            after: None,
            summary: "no briefing change detected".to_string(),
            reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
        });
    }
    records.sort_by(|left, right| left.delta_id.cmp(&right.delta_id));
    Some(BriefingDeltaReport {
        changed_count: records
            .iter()
            .filter(|item| item.delta_kind != BriefingDeltaKind::NoChange)
            .count(),
        added_warning_count: records
            .iter()
            .filter(|item| item.delta_kind == BriefingDeltaKind::WarningAdded)
            .count(),
        resolved_warning_count: records
            .iter()
            .filter(|item| item.delta_kind == BriefingDeltaKind::WarningRemoved)
            .count(),
        owner_action_delta_count: records
            .iter()
            .filter(|item| {
                matches!(
                    item.delta_kind,
                    BriefingDeltaKind::OwnerActionAdded | BriefingDeltaKind::OwnerActionResolved
                )
            })
            .count(),
        report_status: if records.len() == 1 && records[0].delta_kind == BriefingDeltaKind::NoChange
        {
            BriefingDeltaStatus::NoChange
        } else {
            BriefingDeltaStatus::DeltaReady
        },
        records,
        reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
    })
}

fn build_control_tower_briefing_panel(
    config: &OperatorBriefingConfig,
    report: &OperatorBriefingReport,
    checklist: &OwnerActionChecklist,
    queue: &OperatorDecisionQueue,
    runbook_blocks: &[RunbookCommandBlock],
    gaps: &EvidenceGapClosureChecklist,
) -> ControlTowerBriefingPanel {
    let mut panel = ControlTowerBriefingPanel {
        panel_id: config.briefing_id.clone(),
        briefing_status: report.briefing_status,
        overall_severity: report.overall_severity,
        primary_headline: report.primary_headline.clone(),
        section_summaries: report
            .sections
            .iter()
            .map(|item| format!("{}: {:?} - {}", item.title, item.severity, item.headline))
            .collect(),
        owner_attention_summary: format!(
            "required={} recommended={} blocked={}",
            checklist.required_count, checklist.recommended_count, checklist.blocked_count
        ),
        model_attention_summary: format!(
            "ready={} blocked={} closed={}",
            queue.ready_count, queue.blocked_count, queue.closed_count
        ),
        evidence_attention_summary: format!(
            "gaps={} closeable_now={} requires_data={}",
            gaps.gap_count, gaps.closeable_now_count, gaps.requires_data_count
        ),
        deferred_summary: report.deferred_items.join(" | "),
        next_command_blocks: runbook_blocks
            .iter()
            .filter(|item| item.safe_to_copy)
            .take(config.max_commands)
            .cloned()
            .collect(),
        direct_watch_score_v2: None,
        attached_evidence_count: 0,
        prediction_history_expansion_status: None,
        retirement_evidence_pack_status: None,
        gap_closure_summary: None,
        owner_checklist_closure_summary: None,
        forbidden_controls_absent: true,
        fragment_links: BTreeMap::new(),
        reason_codes: stable_reason_codes(&[ReasonCode::ControlTowerBriefingPanelBuilt]),
    };
    panel.stabilize();
    panel
}

fn render_operator_briefing_files(
    config: &OperatorBriefingConfig,
    report: &OperatorBriefingReport,
    checklist: &OwnerActionChecklist,
    queue: &OperatorDecisionQueue,
    runbook_blocks: &[RunbookCommandBlock],
    snapshot: &DailyBriefingSnapshot,
    delta: Option<&BriefingDeltaReport>,
    leaderboard_report: &LeaderboardWarningClosureReport,
    retirement_report: &RetirementEvidenceCompletionReport,
    gaps: &EvidenceGapClosureChecklist,
    panel: &mut ControlTowerBriefingPanel,
) -> Result<OperatorBriefingRenderArtifacts, String> {
    let dir = config.output_dir();
    fs::create_dir_all(&dir).map_err(|err| err.to_string())?;
    let mut contents = BTreeMap::<String, String>::new();
    if config.render_html {
        let fragment_dir = dir.join("fragments");
        fs::create_dir_all(&fragment_dir).map_err(|err| err.to_string())?;
        let fragments = BTreeMap::from([
            (
                "owner_review_briefing".to_string(),
                render_owner_review_briefing_fragment(checklist),
            ),
            (
                "next_actions".to_string(),
                render_briefing_next_actions_fragment(runbook_blocks),
            ),
            (
                "model_attention".to_string(),
                render_model_attention_fragment(queue, leaderboard_report, retirement_report),
            ),
            (
                "deferred_items".to_string(),
                render_deferred_items_fragment(&report.deferred_items),
            ),
        ]);
        for (name, content) in fragments {
            let relative_path = format!("fragments/{name}.html");
            panel.fragment_links.insert(name, relative_path.clone());
            contents.insert(relative_path, content);
        }
        panel.stabilize();
        contents.insert(
            "control_tower_briefing.html".to_string(),
            render_control_tower_briefing_html(report, panel),
        );
    }
    if config.render_json {
        contents.insert(
            "briefing_state.json".to_string(),
            serde_json::to_string_pretty(&serde_json::json!({
                "operator_briefing_report": report,
                "owner_action_checklist": checklist,
                "operator_decision_queue": queue,
                "daily_briefing_snapshot": snapshot,
                "leaderboard_warning_closure_report": leaderboard_report,
                "retirement_evidence_completion_report": retirement_report,
                "evidence_gap_closure_checklist": gaps,
                "control_tower_briefing_panel": panel,
            }))
            .map_err(|err| err.to_string())?,
        );
    }
    if config.render_text {
        contents.insert("briefing_summary.txt".to_string(), report_to_text(report));
        contents.insert(
            "owner_action_checklist.txt".to_string(),
            serde_json::to_string_pretty(checklist).map_err(|err| err.to_string())?,
        );
        contents.insert(
            "operator_decision_queue.txt".to_string(),
            serde_json::to_string_pretty(queue).map_err(|err| err.to_string())?,
        );
        contents.insert(
            "briefing_delta.txt".to_string(),
            serde_json::to_string_pretty(&delta.cloned().unwrap_or(BriefingDeltaReport {
                records: vec![BriefingDeltaRecord {
                    delta_id: format!("{}-delta-none", config.briefing_id),
                    delta_kind: BriefingDeltaKind::NoChange,
                    target_id: None,
                    before: None,
                    after: None,
                    summary: "no previous briefing".to_string(),
                    reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
                }],
                changed_count: 0,
                added_warning_count: 0,
                resolved_warning_count: 0,
                owner_action_delta_count: 0,
                report_status: BriefingDeltaStatus::NoPreviousBriefing,
                reason_codes: stable_reason_codes(&[ReasonCode::BriefingDeltaReportBuilt]),
            }))
            .map_err(|err| err.to_string())?,
        );
        contents.insert(
            "leaderboard_warning_closure.txt".to_string(),
            serde_json::to_string_pretty(leaderboard_report).map_err(|err| err.to_string())?,
        );
        contents.insert(
            "retirement_evidence_completion.txt".to_string(),
            serde_json::to_string_pretty(retirement_report).map_err(|err| err.to_string())?,
        );
        contents.insert(
            "evidence_gap_closure_checklist.txt".to_string(),
            serde_json::to_string_pretty(gaps).map_err(|err| err.to_string())?,
        );
    }
    let storage_bytes = contents.values().map(|text| text.len()).sum::<usize>();
    if storage_bytes > config.max_bytes {
        return Err(format!(
            "operator briefing output exceeded max_bytes: {} > {}",
            storage_bytes, config.max_bytes
        ));
    }
    let storage_report = OperatorBriefingStorageReport {
        artifact_count: contents.len(),
        storage_bytes,
        max_bytes: config.max_bytes,
        within_budget: true,
        reason_codes: stable_reason_codes(&[ReasonCode::OperatorBriefingStorageBuilt]),
    };
    if config.render_text {
        contents.insert(
            "storage_report.txt".to_string(),
            serde_json::to_string_pretty(&storage_report).map_err(|err| err.to_string())?,
        );
        contents.insert(
            "summary.txt".to_string(),
            format!(
                "briefing_status={:?}\nchecklist_status={:?}\nleaderboard_warning_status={:?}\nretirement_evidence_status={:?}\npanel_status={:?}",
                report.briefing_status,
                checklist.checklist_status,
                leaderboard_report.closure_status,
                retirement_report.completion_status,
                panel.briefing_status
            ),
        );
    }
    let mut static_files = BTreeMap::new();
    for (relative_path, content) in &contents {
        let full_path = dir.join(relative_path);
        if let Some(parent) = full_path.parent() {
            fs::create_dir_all(parent).map_err(|err| err.to_string())?;
        }
        fs::write(&full_path, content).map_err(|err| err.to_string())?;
        static_files.insert(relative_path.clone(), full_path.display().to_string());
    }
    Ok(OperatorBriefingRenderArtifacts {
        static_files,
        storage_report,
    })
}

fn build_operator_briefing_final_summary(
    report: &OperatorBriefingReport,
    checklist: &OwnerActionChecklist,
    leaderboard_report: &LeaderboardWarningClosureReport,
    retirement_report: &RetirementEvidenceCompletionReport,
    panel: &ControlTowerBriefingPanel,
    storage_bytes: usize,
) -> String {
    format!(
        "briefing_status={:?}\nbriefing_recommendation={}\ndirect_watch_mode_status={}\nchecklist_status={:?}\nowner_checklist_recommendation={}\nleaderboard_warning_status={:?}\nleaderboard_recommendation={}\nretirement_evidence_status={:?}\nretirement_recommendation={}\npanel_status={:?}\nmamba_status=HoldMamba3RuntimeDeferred\nui_status=KeepStaticDashboardNow\ntrinity_status=KeepTrinity\ncopyable_command_count={}\nstorage_bytes={}",
        report.briefing_status,
        operator_briefing_recommendation(report.briefing_status),
        direct_watch_mode_status(report.briefing_status),
        checklist.checklist_status,
        owner_checklist_recommendation(checklist.checklist_status),
        leaderboard_report.closure_status,
        leaderboard_warning_recommendation(leaderboard_report.closure_status),
        retirement_report.completion_status,
        retirement_evidence_recommendation(retirement_report.completion_status),
        panel.briefing_status,
        report.copyable_commands.len(),
        storage_bytes
    )
}

fn rollup_cards(context: &OperatorBriefingContext) -> &[ModelVersionSummaryCard] {
    context
        .rollup_bundle
        .as_ref()
        .map(|bundle| bundle.model_version_summary_cards.as_slice())
        .unwrap_or(&[])
}

fn triage_regression_count(
    context: &OperatorBriefingContext,
    model_id: &str,
    model_version: &str,
) -> usize {
    context
        .trace_bundle
        .as_ref()
        .map(|bundle| {
            bundle
                .regression_evidence_trace_report
                .traces
                .iter()
                .filter(|item| item.model_id == model_id && item.model_version == model_version)
                .count()
        })
        .unwrap_or(0)
}

fn model_ops_risk_count(context: &OperatorBriefingContext, level: &str) -> usize {
    context
        .rollup_bundle
        .as_ref()
        .map(|bundle| {
            bundle
                .model_ops_risk_rollup_report
                .items
                .iter()
                .filter(|item| item.final_risk_level.eq_ignore_ascii_case(level))
                .count()
        })
        .unwrap_or(0)
}

fn build_deferred_items(context: &OperatorBriefingContext) -> Vec<String> {
    let mut items = vec![
        "runtime LLM remains deferred".to_string(),
        "runtime Mamba remains deferred".to_string(),
        "live trading remains deferred".to_string(),
        "broker, order, and account controls remain deferred".to_string(),
    ];
    if context.kis_source_count == 0 {
        items.push("KIS evidence remains deferred until local artifacts are attached".to_string());
    }
    if context.sequence_source_count == 0 {
        items.push(
            "sequence dataset review remains deferred until local rows are attached".to_string(),
        );
    }
    if context.trinity_source_count == 0 {
        items.push("committee/trinity loop review remains deferred until local loop artifacts are attached".to_string());
    }
    stable_ordered_strings(&items)
}

fn direct_watch_readiness_estimate(
    checklist: &OwnerActionChecklist,
    leaderboard_report: &LeaderboardWarningClosureReport,
    retirement_report: &RetirementEvidenceCompletionReport,
) -> &'static str {
    if checklist.blocked_count > 0
        || leaderboard_report.closure_status != LeaderboardWarningClosureStatus::WarningClosed
        || retirement_report.completion_status
            == RetirementEvidenceCompletionStatus::NeedsMoreRegressionEvidence
    {
        "82~86%"
    } else {
        "86~88%"
    }
}

fn briefing_severity_rank(severity: BriefingSeverity) -> usize {
    match severity {
        BriefingSeverity::Good => 0,
        BriefingSeverity::Deferred => 1,
        BriefingSeverity::Watch => 2,
        BriefingSeverity::NeedsAction => 3,
        BriefingSeverity::Blocked => 4,
    }
}

fn aggregate_briefing_severity(sections: &[BriefingSection]) -> BriefingSeverity {
    sections
        .iter()
        .map(|item| item.severity)
        .max_by_key(|severity| briefing_severity_rank(*severity))
        .unwrap_or(BriefingSeverity::Deferred)
}

fn operator_briefing_recommendation(status: OperatorBriefingStatus) -> &'static str {
    match status {
        OperatorBriefingStatus::BriefingReady
        | OperatorBriefingStatus::BriefingReadyWithWarnings => "OperatorBriefingReady",
        OperatorBriefingStatus::NeedsOwnerAction => "RequestOwnerReview",
        OperatorBriefingStatus::NeedsMoreEvidence
        | OperatorBriefingStatus::MissingSourceArtifacts => "NeedMoreEvidence",
        OperatorBriefingStatus::DiagnosticOnly => "MarkDiagnosticOnly",
    }
}

fn direct_watch_mode_status(status: OperatorBriefingStatus) -> &'static str {
    match status {
        OperatorBriefingStatus::MissingSourceArtifacts => "NeedMoreEvidence",
        _ => "DirectWatchModeReady",
    }
}

fn owner_checklist_recommendation(status: OwnerActionChecklistStatus) -> &'static str {
    match status {
        OwnerActionChecklistStatus::ChecklistReady => "OwnerActionChecklistReady",
        OwnerActionChecklistStatus::NeedsOwnerAction => "RequestOwnerReview",
        OwnerActionChecklistStatus::NoOwnerActionNeeded => "KeepResearchCandidate",
        OwnerActionChecklistStatus::DiagnosticOnly => "MarkDiagnosticOnly",
    }
}

fn leaderboard_warning_recommendation(status: LeaderboardWarningClosureStatus) -> &'static str {
    match status {
        LeaderboardWarningClosureStatus::WarningClosed => "LeaderboardWarningClosed",
        LeaderboardWarningClosureStatus::WarningExplained => "KeepResearchCandidate",
        LeaderboardWarningClosureStatus::WarningStillOpen
        | LeaderboardWarningClosureStatus::NeedsMoreEvidence => "NeedMoreEvidence",
        LeaderboardWarningClosureStatus::DiagnosticOnly => "MarkDiagnosticOnly",
    }
}

fn retirement_evidence_recommendation(status: RetirementEvidenceCompletionStatus) -> &'static str {
    match status {
        RetirementEvidenceCompletionStatus::RetirementEvidenceReady => {
            "RetirementEvidenceCompleted"
        }
        RetirementEvidenceCompletionStatus::RetirementEvidenceStillIncomplete
        | RetirementEvidenceCompletionStatus::NeedsMoreRegressionEvidence
        | RetirementEvidenceCompletionStatus::NeedsOwnerReview => {
            "RetirementEvidenceStillIncomplete"
        }
        RetirementEvidenceCompletionStatus::DiagnosticDowngradeSupported => "MarkDiagnosticOnly",
        RetirementEvidenceCompletionStatus::DiagnosticOnly => "MarkDiagnosticOnly",
    }
}

