fn unique_basenames(paths: &[String]) -> Vec<String> {
    let set = paths
        .iter()
        .map(|path| {
            Path::new(path)
                .file_name()
                .map(|value| value.to_string_lossy().to_string())
                .unwrap_or_else(|| path.clone())
        })
        .collect::<BTreeSet<_>>();
    set.into_iter().collect()
}

fn collect_source_artifacts(base: &[String], required: &[&str]) -> Vec<String> {
    let mut combined = base.iter().cloned().collect::<BTreeSet<_>>();
    for item in required {
        combined.insert((*item).to_string());
    }
    combined.into_iter().collect()
}

fn limit_strings(items: &[String], max_items: usize) -> Vec<String> {
    items.iter().take(max_items).cloned().collect()
}

fn flatten_section_items<F>(sections: &[BriefingSection], accessor: F) -> BTreeSet<String>
where
    F: Fn(&BriefingSection) -> &Vec<String>,
{
    sections
        .iter()
        .flat_map(|section| accessor(section).iter().cloned())
        .collect()
}

fn report_to_text(report: &OperatorBriefingReport) -> String {
    format!(
        "briefing_status={:?}\noverall_severity={:?}\nprimary_headline={}\nprimary_next_action={}\nowner_attention_items={}\nblocked_items={}\ndeferred_items={}",
        report.briefing_status,
        report.overall_severity,
        report.primary_headline,
        report.primary_next_action,
        report.owner_attention_items.join(" | "),
        report.blocked_items.join(" | "),
        report.deferred_items.join(" | "),
    )
}

fn render_owner_review_briefing_fragment(checklist: &OwnerActionChecklist) -> String {
    let items = checklist
        .items
        .iter()
        .map(|item| {
            format!(
                "<li><strong>{}</strong>: {} ({:?})</li>",
                html_escape(&item.title),
                html_escape(&item.why_it_matters),
                item.severity
            )
        })
        .collect::<Vec<_>>()
        .join("");
    format!(
        "<section><h1>owner review briefing</h1><p>static owner checklist only</p><ul>{}</ul></section>",
        items
    )
}

fn render_briefing_next_actions_fragment(runbook_blocks: &[RunbookCommandBlock]) -> String {
    let items = runbook_blocks
        .iter()
        .filter(|item| item.safe_to_copy)
        .map(|item| {
            format!(
                "<li><strong>{}</strong><pre>{}</pre><p>{}</p></li>",
                html_escape(&item.title),
                html_escape(&item.command_text),
                html_escape(&item.expected_output)
            )
        })
        .collect::<Vec<_>>()
        .join("");
    format!(
        "<section><h1>next actions</h1><p>copyable local commands only</p><ul>{}</ul></section>",
        items
    )
}

fn render_model_attention_fragment(
    queue: &OperatorDecisionQueue,
    leaderboard_report: &LeaderboardWarningClosureReport,
    retirement_report: &RetirementEvidenceCompletionReport,
) -> String {
    let items = queue
        .items
        .iter()
        .map(|item| format!("<li>{}: {:?}</li>", html_escape(&item.title), item.status))
        .collect::<Vec<_>>()
        .join("");
    format!(
        "<section><h1>model attention</h1><p>leaderboard={:?} retirement={:?}</p><ul>{}</ul></section>",
        leaderboard_report.closure_status, retirement_report.completion_status, items
    )
}

fn render_deferred_items_fragment(items: &[String]) -> String {
    let rows = items
        .iter()
        .map(|item| format!("<li>{}</li>", html_escape(item)))
        .collect::<Vec<_>>()
        .join("");
    format!(
        "<section><h1>deferred items</h1><p>deferred by design in Sprint 71</p><ul>{}</ul></section>",
        rows
    )
}

fn render_control_tower_briefing_html(
    report: &OperatorBriefingReport,
    panel: &ControlTowerBriefingPanel,
) -> String {
    let sections = report
        .sections
        .iter()
        .map(|section| {
            let bullets = section
                .bullet_items
                .iter()
                .map(|item| format!("<li>{}</li>", html_escape(item)))
                .collect::<Vec<_>>()
                .join("");
            let warnings = section
                .warnings
                .iter()
                .map(|item| format!("<li>{}</li>", html_escape(item)))
                .collect::<Vec<_>>()
                .join("");
            let blockers = section
                .blockers
                .iter()
                .map(|item| format!("<li>{}</li>", html_escape(item)))
                .collect::<Vec<_>>()
                .join("");
            let actions = section
                .next_actions
                .iter()
                .map(|item| format!("<li><code>{}</code></li>", html_escape(item)))
                .collect::<Vec<_>>()
                .join("");
            format!(
                "<section><h2>{}</h2><p><strong>{:?}</strong> {}</p><ul>{}</ul><h3>warnings</h3><ul>{}</ul><h3>blockers</h3><ul>{}</ul><h3>next</h3><ul>{}</ul></section>",
                html_escape(&section.title),
                section.severity,
                html_escape(&section.headline),
                bullets,
                warnings,
                blockers,
                actions
            )
        })
        .collect::<Vec<_>>()
        .join("");
    let fragments = panel
        .fragment_links
        .iter()
        .map(|(label, path)| {
            format!(
                "<li><a href=\"{}\">{}</a></li>",
                html_escape(path),
                html_escape(label)
            )
        })
        .collect::<Vec<_>>()
        .join("");
    format!(
        "<!doctype html><html><head><meta charset=\"utf-8\"><title>{}</title></head><body><main><h1>{}</h1><p>{}</p><p>owner_attention: {}</p><p>model_attention: {}</p><p>evidence_attention: {}</p><p>deferred: {}</p><h2>Fragments</h2><ul>{}</ul>{}</main></body></html>",
        html_escape(&report.briefing_id),
        html_escape(&panel.primary_headline),
        html_escape(&format!(
            "{:?} / {:?}",
            panel.briefing_status, panel.overall_severity
        )),
        html_escape(&panel.owner_attention_summary),
        html_escape(&panel.model_attention_summary),
        html_escape(&panel.evidence_attention_summary),
        html_escape(&panel.deferred_summary),
        fragments,
        sections
    )
}

