fn load_sprint73_foundation(
    config: &ExtModelBPredictionClosureConfig,
) -> Result<Sprint73Foundation, String> {
    let mut previous_prediction_report = None;
    let mut previous_gap_report = None;
    let mut owner_closure = None;
    let mut retirement_pack = None;
    let mut previous_score = None;
    let mut previous_refresh = None;
    let mut previous_gate = None;
    let mut registry = None;

    for path in &config.previous_prediction_history_paths {
        if let Ok(report) = read_json_file::<PredictionHistoryExpansionReport>(path) {
            previous_prediction_report = Some(report);
            break;
        }
        if let Ok(state) = read_json_file::<Sprint73StateInput>(path) {
            previous_prediction_report = state.prediction_history_expansion_report;
            if previous_prediction_report.is_some() {
                break;
            }
        }
    }

    for path in &config.offline_evidence_attachment_paths {
        if let Ok(bundle) = read_json_file::<OfflineEvidenceAttachmentBundle>(path) {
            previous_prediction_report
                .get_or_insert(bundle.prediction_history_expansion_report.clone());
            previous_gap_report.get_or_insert(bundle.evidence_gap_closure_v2_report.clone());
            owner_closure.get_or_insert(bundle.owner_checklist_closure_report.clone());
            retirement_pack.get_or_insert(bundle.retirement_regression_evidence_pack.clone());
            previous_score.get_or_insert(bundle.direct_watch_readiness_score_v2.clone());
            previous_refresh.get_or_insert(bundle.control_tower_briefing_refresh_v2.clone());
            previous_gate.get_or_insert(bundle.operator_briefing_readiness_gate.clone());
            registry.get_or_insert(bundle.offline_evidence_attachment_registry.clone());
            continue;
        }
        if let Ok(state) = read_json_file::<Sprint73StateInput>(path) {
            if let Some(report) = state.prediction_history_expansion_report {
                previous_prediction_report.get_or_insert(report);
            }
            if let Some(report) = state.evidence_gap_closure_v2_report {
                previous_gap_report.get_or_insert(report);
            }
            if let Some(report) = state.owner_checklist_closure_report {
                owner_closure.get_or_insert(report);
            }
            if let Some(report) = state.retirement_regression_evidence_pack {
                retirement_pack.get_or_insert(report);
            }
            if let Some(report) = state.direct_watch_readiness_score_v2 {
                previous_score.get_or_insert(report);
            }
            if let Some(report) = state.control_tower_briefing_refresh_v2 {
                previous_refresh.get_or_insert(report);
            }
            if let Some(report) = state.operator_briefing_readiness_gate {
                previous_gate.get_or_insert(report);
            }
            if let Some(report) = state.offline_evidence_attachment_registry {
                registry.get_or_insert(report);
            }
        }
    }

    Ok(Sprint73Foundation {
        previous_prediction_report: previous_prediction_report
            .unwrap_or_else(default_sprint72_prediction_history_report),
        previous_gap_report: previous_gap_report.unwrap_or_else(default_sprint72_gap_report),
        owner_closure: owner_closure.unwrap_or_else(default_sprint72_owner_closure),
        retirement_pack: retirement_pack.unwrap_or_else(default_sprint72_retirement_pack),
        previous_score: previous_score.unwrap_or_else(default_sprint72_direct_watch_score),
        previous_refresh: previous_refresh.unwrap_or_else(default_sprint72_control_tower_refresh),
        previous_gate: previous_gate.unwrap_or_else(default_sprint72_gate),
        registry,
    })
}

fn load_sprint73_sequence_context(
    paths: &[String],
    target_model_id: &str,
    target_model_version: &str,
) -> Result<Option<Sprint73SequenceContext>, String> {
    for path in paths {
        if let Ok(context) = read_json_file::<Sprint73SequenceContext>(path) {
            if context.model_id == target_model_id && context.model_version == target_model_version
            {
                return Ok(Some(context));
            }
        }
    }
    Ok(None)
}

fn has_matching_model_card(
    paths: &[String],
    model_id: &str,
    model_version: &str,
) -> Result<bool, String> {
    for path in paths {
        let card = read_json_file::<ExternalModelCardV2>(path)?;
        if card.model_id == model_id && card.model_version == model_version {
            return Ok(true);
        }
    }
    Ok(false)
}

fn load_sprint73_prediction_rows(
    config: &ExtModelBPredictionClosureConfig,
    sequence_context: Option<&Sprint73SequenceContext>,
) -> Result<Sprint73PredictionRowsSummary, String> {
    if config.new_prediction_csv_paths.len() > config.max_prediction_files {
        return Err("ext-model-b prediction closure max_prediction_files exceeded".to_string());
    }
    let total_bytes = config
        .new_prediction_csv_paths
        .iter()
        .filter_map(|path| fs::metadata(path).ok())
        .map(|meta| meta.len() as usize)
        .sum::<usize>();
    if total_bytes > config.max_bytes {
        return Err("ext-model-b prediction closure max_bytes exceeded".to_string());
    }

    let allowed_sequences = sequence_context.map(|context| {
        context
            .sequence_ids
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>()
    });
    let mut seen = BTreeSet::new();
    let mut summary = Sprint73PredictionRowsSummary::default();
    let mut row_count = 0usize;
    for path in &config.new_prediction_csv_paths {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let mut lines = text.lines();
        let header = lines
            .next()
            .ok_or_else(|| "prediction closure csv missing header".to_string())?;
        let headers = header.split(',').collect::<Vec<_>>();
        let model_id_idx = headers
            .iter()
            .position(|column| *column == "model_id")
            .ok_or_else(|| "prediction closure csv missing model_id".to_string())?;
        let model_version_idx = headers
            .iter()
            .position(|column| *column == "model_version")
            .ok_or_else(|| "prediction closure csv missing model_version".to_string())?;
        let sequence_id_idx = headers
            .iter()
            .position(|column| *column == "sequence_id")
            .ok_or_else(|| "prediction closure csv missing sequence_id".to_string())?;
        let probability_idx = headers
            .iter()
            .position(|column| *column == "probability")
            .or_else(|| headers.iter().position(|column| *column == "score"))
            .ok_or_else(|| "prediction closure csv missing probability or score".to_string())?;
        for line in lines {
            if line.trim().is_empty() {
                continue;
            }
            row_count += 1;
            if row_count > config.max_prediction_rows {
                return Err(
                    "ext-model-b prediction closure max_prediction_rows exceeded".to_string(),
                );
            }
            let values = line.split(',').collect::<Vec<_>>();
            let model_id = values.get(model_id_idx).copied().unwrap_or("");
            let model_version = values.get(model_version_idx).copied().unwrap_or("");
            let sequence_id = values.get(sequence_id_idx).copied().unwrap_or("").trim();
            let probability_text = values.get(probability_idx).copied().unwrap_or("").trim();
            let probability = probability_text.parse::<f64>().ok();
            if model_id != config.target_model_id
                || model_version != config.target_model_version
                || sequence_id.is_empty()
            {
                summary.invalid_count += 1;
                continue;
            }
            if config.require_probability_sanity
                && probability
                    .is_none_or(|value| !value.is_finite() || !(0.0..=1.0).contains(&value))
            {
                summary.invalid_count += 1;
                continue;
            }
            if config.require_sequence_id_match
                && allowed_sequences
                    .as_ref()
                    .is_some_and(|allowed| !allowed.contains(sequence_id))
            {
                summary.invalid_count += 1;
                continue;
            }
            if config.require_no_duplicates && !seen.insert(sequence_id.to_string()) {
                summary.duplicate_count += 1;
                continue;
            }
            summary.rows.push(sequence_id.to_string());
        }
    }
    Ok(summary)
}

fn build_ext_model_b_prediction_closure_report(
    config: &ExtModelBPredictionClosureConfig,
    previous: &PredictionHistoryExpansionReport,
    sequence_context: Option<&Sprint73SequenceContext>,
    model_card_present: bool,
    rows: &Sprint73PredictionRowsSummary,
) -> ExtModelBPredictionClosureReport {
    let total_sequences = sequence_context
        .map(|context| context.total_sequences)
        .unwrap_or(0);
    let coverage_before = previous.coverage_after.unwrap_or(0.0);
    let predicted_before = if total_sequences == 0 {
        0
    } else {
        ((coverage_before * total_sequences as f64).round() as usize).min(total_sequences)
    };
    let predicted_after = (predicted_before + rows.rows.len()).min(total_sequences);
    let coverage_after = if total_sequences == 0 {
        0.0
    } else {
        coverage_ratio(predicted_after, total_sequences)
    };
    let missing_before = total_sequences.saturating_sub(predicted_before);
    let missing_after = total_sequences.saturating_sub(predicted_after);
    let closure_status = if config.require_model_card && !model_card_present {
        ExtModelBPredictionClosureStatus::MissingModelCard
    } else if sequence_context.is_none() {
        ExtModelBPredictionClosureStatus::MissingSequenceContext
    } else if rows.invalid_count > 0 || rows.duplicate_count > 0 {
        ExtModelBPredictionClosureStatus::InvalidPredictions
    } else if coverage_after >= config.min_coverage_ratio {
        ExtModelBPredictionClosureStatus::PredictionGapClosed
    } else if coverage_after > coverage_before {
        ExtModelBPredictionClosureStatus::PredictionGapReduced
    } else {
        ExtModelBPredictionClosureStatus::StillNeedMorePredictions
    };
    let final_recommendation = match closure_status {
        ExtModelBPredictionClosureStatus::PredictionGapClosed => {
            ExtModelBPredictionClosureRecommendation::RerunEvidenceGapClosure
        }
        ExtModelBPredictionClosureStatus::PredictionGapReduced
        | ExtModelBPredictionClosureStatus::StillNeedMorePredictions => {
            ExtModelBPredictionClosureRecommendation::AddMorePredictions
        }
        ExtModelBPredictionClosureStatus::InvalidPredictions => {
            ExtModelBPredictionClosureRecommendation::FixPredictionSchema
        }
        ExtModelBPredictionClosureStatus::MissingModelCard => {
            ExtModelBPredictionClosureRecommendation::FixModelCard
        }
        ExtModelBPredictionClosureStatus::MissingSequenceContext => {
            ExtModelBPredictionClosureRecommendation::NeedMoreEvidence
        }
        ExtModelBPredictionClosureStatus::DiagnosticOnly => {
            ExtModelBPredictionClosureRecommendation::KeepDiagnosticUntilCoverage
        }
    };
    ExtModelBPredictionClosureReport {
        closure_id: config.closure_id.clone(),
        model_id: config.target_model_id.clone(),
        model_version: config.target_model_version.clone(),
        prediction_files_before: previous.prediction_files_after,
        prediction_files_after: previous.prediction_files_after
            + config.new_prediction_csv_paths.len(),
        coverage_before,
        coverage_after,
        missing_sequence_count_before: Some(missing_before),
        missing_sequence_count_after: missing_after,
        duplicate_count: rows.duplicate_count,
        invalid_count: rows.invalid_count,
        closure_status,
        final_recommendation,
        reason_codes: stable_reason_codes(&[ReasonCode::ExtModelBPredictionClosureReportBuilt]),
    }
}

fn build_prediction_coverage_finalization_report(
    config: &ExtModelBPredictionClosureConfig,
    closure: &ExtModelBPredictionClosureReport,
    sequence_context: Option<&Sprint73SequenceContext>,
) -> PredictionCoverageFinalizationReport {
    let total_sequences = sequence_context
        .map(|context| context.total_sequences)
        .unwrap_or(0);
    let missing_sequences = closure.missing_sequence_count_after.min(total_sequences);
    let predicted_sequences = total_sequences.saturating_sub(missing_sequences);
    let coverage_passed =
        total_sequences > 0 && closure.coverage_after >= config.min_coverage_ratio;
    let coverage_status = if total_sequences == 0
        || matches!(
            closure.closure_status,
            ExtModelBPredictionClosureStatus::InvalidPredictions
        ) {
        PredictionCoverageFinalizationStatus::InvalidCoverage
    } else if coverage_passed && missing_sequences == 0 {
        PredictionCoverageFinalizationStatus::CoverageFinalized
    } else if coverage_passed {
        PredictionCoverageFinalizationStatus::CoverageFinalizedWithWarnings
    } else {
        PredictionCoverageFinalizationStatus::CoverageStillInsufficient
    };
    PredictionCoverageFinalizationReport {
        report_id: format!("{}-coverage-finalization", config.closure_id),
        model_id: config.target_model_id.clone(),
        model_version: config.target_model_version.clone(),
        total_sequences,
        predicted_sequences,
        missing_sequences,
        coverage_ratio: closure.coverage_after,
        min_required_coverage_ratio: config.min_coverage_ratio,
        coverage_passed,
        coverage_status,
        reason_codes: stable_reason_codes(&[ReasonCode::PredictionCoverageFinalizationReportBuilt]),
    }
}

fn build_evidence_gap_final_closure_report(
    config: &ExtModelBPredictionClosureConfig,
    previous_gap: &EvidenceGapClosureV2Report,
    coverage: &PredictionCoverageFinalizationReport,
    owner_closure: &OwnerChecklistClosureReport,
    retirement_pack: &RetirementRegressionEvidencePack,
) -> EvidenceGapFinalClosureReport {
    let target_gap = format!("{}:{}", config.target_model_id, config.target_model_version);
    let prediction_history_gap_closed =
        coverage.coverage_passed && previous_gap.remaining_gaps.contains(&target_gap);
    let mut remaining_gaps = previous_gap.remaining_gaps.clone();
    if prediction_history_gap_closed {
        remaining_gaps.retain(|gap| gap != &target_gap);
    }
    let closed_gaps = if prediction_history_gap_closed {
        vec![target_gap]
    } else {
        Vec::new()
    };
    let owner_gap_closed = matches!(
        owner_closure.closure_status,
        OwnerChecklistClosureStatus::OwnerChecklistClosed
            | OwnerChecklistClosureStatus::OwnerChecklistReduced
    ) && owner_closure.blocked_after == 0;
    let retirement_gap_stable = matches!(
        retirement_pack.pack_status,
        RetirementRegressionEvidencePackStatus::RetirementEvidenceReady
            | RetirementRegressionEvidencePackStatus::DiagnosticOnlySupported
            | RetirementRegressionEvidencePackStatus::RetirementEvidenceStillIncomplete
    );
    let gaps_before = previous_gap.remaining_gaps.len();
    let gaps_after = remaining_gaps.len();
    let evidence_status = if gaps_after == 0 {
        EvidenceGapFinalClosureStatus::EvidenceGapClosed
    } else if !owner_gap_closed {
        EvidenceGapFinalClosureStatus::StillNeedsOwnerReview
    } else if !coverage.coverage_passed {
        EvidenceGapFinalClosureStatus::StillNeedsPredictionHistory
    } else if gaps_after < gaps_before {
        EvidenceGapFinalClosureStatus::EvidenceGapReduced
    } else {
        EvidenceGapFinalClosureStatus::StillNeedsData
    };
    EvidenceGapFinalClosureReport {
        closure_id: format!("{}-evidence-gap-final", config.closure_id),
        gaps_before,
        gaps_after,
        remaining_gaps: stable_ordered_strings(&remaining_gaps),
        closed_gaps,
        prediction_history_gap_closed,
        retirement_gap_stable,
        owner_gap_closed,
        evidence_status,
        reason_codes: stable_reason_codes(&[ReasonCode::EvidenceGapFinalClosureReportBuilt]),
    }
}

fn build_direct_watch_readiness_final_gate(
    config: &ExtModelBPredictionClosureConfig,
    previous_score: &DirectWatchReadinessScoreV2,
    evidence: &EvidenceGapFinalClosureReport,
    coverage: &PredictionCoverageFinalizationReport,
    owner_closure: &OwnerChecklistClosureReport,
    retirement_pack: &RetirementRegressionEvidencePack,
    registry: Option<&OfflineEvidenceAttachmentRegistry>,
    previous_gate: Option<&OperatorBriefingReadinessGate>,
) -> DirectWatchReadinessFinalGate {
    let owner_checklist_closed = matches!(
        owner_closure.closure_status,
        OwnerChecklistClosureStatus::OwnerChecklistClosed
            | OwnerChecklistClosureStatus::OwnerChecklistReduced
    ) && owner_closure.blocked_after == 0;
    let evidence_gap_closed = evidence.gaps_after == 0;
    let prediction_history_sufficient = coverage.coverage_passed;
    let retirement_evidence_stable = matches!(
        retirement_pack.pack_status,
        RetirementRegressionEvidencePackStatus::RetirementEvidenceReady
            | RetirementRegressionEvidencePackStatus::DiagnosticOnlySupported
    );
    let forbidden_controls_absent = previous_score.forbidden_controls_absent;
    let static_only = previous_gate.map(|gate| gate.static_only).unwrap_or(true);
    let paper_only = previous_gate.map(|gate| gate.paper_only).unwrap_or(true);
    let no_secret_values = registry.is_none_or(|registry| {
        registry
            .records
            .iter()
            .all(|record| record.secret_scan_passed)
    });
    let current_score_min = if evidence_gap_closed && prediction_history_sufficient {
        88
    } else if coverage.coverage_ratio > 0.5 {
        86
    } else {
        previous_score.target_score_min
    };
    let current_score_max = if evidence_gap_closed && prediction_history_sufficient {
        90
    } else {
        previous_score.target_score_max
    };
    let gate_status =
        if !forbidden_controls_absent || !static_only || !paper_only || !no_secret_values {
            DirectWatchReadinessFinalStatus::BlockedByUnsafeControl
        } else if !owner_checklist_closed {
            DirectWatchReadinessFinalStatus::StillNeedsOwnerAction
        } else if !evidence_gap_closed || !prediction_history_sufficient {
            DirectWatchReadinessFinalStatus::StillNeedsEvidence
        } else if current_score_min >= 90 {
            DirectWatchReadinessFinalStatus::DirectWatchReady
        } else {
            DirectWatchReadinessFinalStatus::DirectWatchReadyWithWarnings
        };
    let final_recommendation = match gate_status {
        DirectWatchReadinessFinalStatus::DirectWatchReady => {
            DirectWatchReadinessFinalRecommendation::UseDirectWatchMode
        }
        DirectWatchReadinessFinalStatus::DirectWatchReadyWithWarnings => {
            DirectWatchReadinessFinalRecommendation::UseDirectWatchModeWithWarnings
        }
        DirectWatchReadinessFinalStatus::StillNeedsEvidence => {
            if !prediction_history_sufficient {
                DirectWatchReadinessFinalRecommendation::AddMorePredictions
            } else {
                DirectWatchReadinessFinalRecommendation::AttachMoreEvidence
            }
        }
        DirectWatchReadinessFinalStatus::StillNeedsOwnerAction => {
            DirectWatchReadinessFinalRecommendation::ResolveOwnerChecklist
        }
        DirectWatchReadinessFinalStatus::BlockedByUnsafeControl => {
            DirectWatchReadinessFinalRecommendation::HoldMamba3RuntimeDeferred
        }
        DirectWatchReadinessFinalStatus::DiagnosticOnly => {
            DirectWatchReadinessFinalRecommendation::NeedMoreEvidence
        }
    };
    DirectWatchReadinessFinalGate {
        gate_id: format!("{}-direct-watch-final-gate", config.closure_id),
        previous_score_min: previous_score.current_score_min,
        previous_score_max: previous_score.current_score_max,
        current_score_min,
        current_score_max,
        evidence_gap_closed,
        owner_checklist_closed,
        prediction_history_sufficient,
        retirement_evidence_stable,
        forbidden_controls_absent,
        static_only,
        paper_only,
        no_secret_values,
        gate_status,
        final_recommendation,
        reason_codes: stable_reason_codes(&[ReasonCode::DirectWatchReadinessFinalGateBuilt]),
    }
}

fn build_control_tower_briefing_final_refresh(
    config: &ExtModelBPredictionClosureConfig,
    previous_refresh: &ControlTowerBriefingRefreshV2,
    final_gate: &DirectWatchReadinessFinalGate,
    evidence: &EvidenceGapFinalClosureReport,
    closure: &ExtModelBPredictionClosureReport,
    retirement_pack: &RetirementRegressionEvidencePack,
    owner_closure: &OwnerChecklistClosureReport,
) -> ControlTowerBriefingFinalRefresh {
    let briefing_state_after = match final_gate.gate_status {
        DirectWatchReadinessFinalStatus::DirectWatchReady => "BriefingReady",
        DirectWatchReadinessFinalStatus::DirectWatchReadyWithWarnings => {
            "BriefingReadyWithWarnings"
        }
        DirectWatchReadinessFinalStatus::StillNeedsOwnerAction => "StillNeedsOwnerAction",
        DirectWatchReadinessFinalStatus::BlockedByUnsafeControl => "UnsafeControlDetected",
        _ => "StillNeedsEvidence",
    };
    let refresh_status = match briefing_state_after {
        "BriefingReady" => ControlTowerBriefingFinalRefreshStatus::BriefingReady,
        "BriefingReadyWithWarnings" => {
            ControlTowerBriefingFinalRefreshStatus::BriefingReadyWithWarnings
        }
        "StillNeedsOwnerAction" => ControlTowerBriefingFinalRefreshStatus::StillNeedsOwnerAction,
        "UnsafeControlDetected" => ControlTowerBriefingFinalRefreshStatus::UnsafeControlDetected,
        _ => ControlTowerBriefingFinalRefreshStatus::StillNeedsEvidence,
    };
    ControlTowerBriefingFinalRefresh {
        refresh_id: format!("{}-control-tower-final-refresh", config.closure_id),
        briefing_state_before: previous_refresh.briefing_state_after.clone(),
        briefing_state_after: briefing_state_after.to_string(),
        direct_watch_gate_status: format!("{:?}", final_gate.gate_status),
        evidence_gap_status: format!("{:?}", evidence.evidence_status),
        prediction_history_status: format!("{:?}", closure.closure_status),
        retirement_evidence_status: format!("{:?}", retirement_pack.pack_status),
        owner_checklist_status: format!("{:?}", owner_closure.closure_status),
        dashboard_html_path: None,
        briefing_state_path: None,
        briefing_summary_path: None,
        refresh_status,
        reason_codes: stable_reason_codes(&[ReasonCode::ControlTowerBriefingFinalRefreshBuilt]),
    }
}

fn render_sprint73_fragments(
    closure: &ExtModelBPredictionClosureReport,
    evidence: &EvidenceGapFinalClosureReport,
    gate: &DirectWatchReadinessFinalGate,
) -> BTreeMap<String, String> {
    let mut fragments = BTreeMap::new();
    fragments.insert(
        "fragments/prediction_history_final.html".to_string(),
        format!(
            "<section><h1>prediction history final</h1><p>{}:{} before={} after={} coverage={} -> {} status={:?}</p></section>",
            html_escape(&closure.model_id),
            html_escape(&closure.model_version),
            closure.prediction_files_before,
            closure.prediction_files_after,
            closure.coverage_before,
            closure.coverage_after,
            closure.closure_status,
        ),
    );
    fragments.insert(
        "fragments/evidence_gap_final.html".to_string(),
        format!(
            "<section><h1>evidence gap final</h1><p>before={} after={} status={:?}</p><ul><li>closed_gaps={}</li><li>remaining_gaps={}</li></ul></section>",
            evidence.gaps_before,
            evidence.gaps_after,
            evidence.evidence_status,
            html_escape(&evidence.closed_gaps.join(" | ")),
            html_escape(&evidence.remaining_gaps.join(" | ")),
        ),
    );
    fragments.insert(
        "fragments/direct_watch_final.html".to_string(),
        format!(
            "<section><h1>direct watch final</h1><p>{}~{} status={:?}</p><ul><li>monitoring-only=true</li><li>static_only={}</li><li>paper_only={}</li><li>forbidden_controls_absent={}</li></ul></section>",
            gate.current_score_min,
            gate.current_score_max,
            gate.gate_status,
            gate.static_only,
            gate.paper_only,
            gate.forbidden_controls_absent,
        ),
    );
    fragments
}

fn render_sprint73_control_tower_html(refresh: &ControlTowerBriefingFinalRefresh) -> String {
    format!(
        "<section><h1>control tower briefing final refresh</h1><p>before={} after={} status={:?}</p><ul><li>direct_watch_gate_status={}</li><li>evidence_gap_status={}</li><li>prediction_history_status={}</li><li>retirement_evidence_status={}</li><li>owner_checklist_status={}</li></ul></section>",
        html_escape(&refresh.briefing_state_before),
        html_escape(&refresh.briefing_state_after),
        refresh.refresh_status,
        html_escape(&refresh.direct_watch_gate_status),
        html_escape(&refresh.evidence_gap_status),
        html_escape(&refresh.prediction_history_status),
        html_escape(&refresh.retirement_evidence_status),
        html_escape(&refresh.owner_checklist_status),
    )
}

fn build_sprint73_briefing_summary(
    closure: &ExtModelBPredictionClosureReport,
    evidence: &EvidenceGapFinalClosureReport,
    gate: &DirectWatchReadinessFinalGate,
    refresh: &ControlTowerBriefingFinalRefresh,
    acceptance: &Sprint73WorkspaceAcceptanceReport,
) -> String {
    format!(
        "ext_model_b_prediction_status={:?}\nprediction_coverage={}\nevidence_gap_status={:?}\ndirect_watch_final_status={:?}\ncontrol_tower_final_refresh_status={:?}\nworkspace_acceptance_status={:?}",
        closure.closure_status,
        closure.coverage_after,
        evidence.evidence_status,
        gate.gate_status,
        refresh.refresh_status,
        acceptance.acceptance_status,
    )
}

fn build_sprint73_final_summary(
    closure: &ExtModelBPredictionClosureReport,
    coverage: &PredictionCoverageFinalizationReport,
    evidence: &EvidenceGapFinalClosureReport,
    gate: &DirectWatchReadinessFinalGate,
    refresh: &ControlTowerBriefingFinalRefresh,
    acceptance: &Sprint73WorkspaceAcceptanceReport,
) -> String {
    let mut recommendations = Vec::new();
    recommendations.push(
        if matches!(
            closure.closure_status,
            ExtModelBPredictionClosureStatus::PredictionGapClosed
        ) {
            "ExtModelBPredictionGapClosed"
        } else {
            "NeedMoreEvidence"
        }
        .to_string(),
    );
    recommendations.push(
        if coverage.coverage_passed {
            "PredictionHistoryCompleteEnoughForCurrentFixture"
        } else {
            "NeedMoreEvidence"
        }
        .to_string(),
    );
    recommendations.push(
        if matches!(
            evidence.evidence_status,
            EvidenceGapFinalClosureStatus::EvidenceGapClosed
        ) {
            "EvidenceGapClosed"
        } else {
            "NeedMoreEvidence"
        }
        .to_string(),
    );
    recommendations.push(
        match gate.gate_status {
            DirectWatchReadinessFinalStatus::DirectWatchReady => "DirectWatchReady",
            DirectWatchReadinessFinalStatus::DirectWatchReadyWithWarnings => {
                "DirectWatchReadyWithWarnings"
            }
            _ => "NeedMoreEvidence",
        }
        .to_string(),
    );
    recommendations.push(
        match refresh.refresh_status {
            ControlTowerBriefingFinalRefreshStatus::BriefingReady => "ControlTowerBriefingReady",
            ControlTowerBriefingFinalRefreshStatus::BriefingReadyWithWarnings => {
                "ControlTowerBriefingReadyWithWarnings"
            }
            _ => "KeepStaticDashboardNow",
        }
        .to_string(),
    );
    recommendations.push(
        match acceptance.acceptance_status {
            WorkspaceAcceptanceStatus::FullWorkspaceAccepted => "FullWorkspaceAcceptancePassed",
            WorkspaceAcceptanceStatus::FocusedOnly => "FocusedValidationOnly",
            _ => "NeedMoreEvidence",
        }
        .to_string(),
    );
    recommendations.push("StillNeedsMoreRealEvidence".to_string());
    recommendations.push("KeepResearchOnly".to_string());
    recommendations.push("KeepStaticDashboardNow".to_string());
    recommendations.push("KeepTrinity".to_string());
    recommendations.push("HoldMamba3RuntimeDeferred".to_string());
    format!(
        "ext_model_b_prediction_status={:?}\nprediction_coverage_status={:?}\nevidence_gap_status={:?}\ndirect_watch_final_status={:?}\ncontrol_tower_final_refresh_status={:?}\nworkspace_acceptance_status={:?}\nrecommendations={}",
        closure.closure_status,
        coverage.coverage_status,
        evidence.evidence_status,
        gate.gate_status,
        refresh.refresh_status,
        acceptance.acceptance_status,
        stable_ordered_strings(&recommendations).join(" | "),
    )
}

fn write_sprint73_bundle(
    config: &ExtModelBPredictionClosureConfig,
    closure: &ExtModelBPredictionClosureReport,
    coverage: &PredictionCoverageFinalizationReport,
    evidence: &EvidenceGapFinalClosureReport,
    gate: &DirectWatchReadinessFinalGate,
    refresh: &ControlTowerBriefingFinalRefresh,
    acceptance: &Sprint73WorkspaceAcceptanceReport,
    fragments: &BTreeMap<String, String>,
) -> Result<
    (
        ControlTowerBriefingFinalRefresh,
        BTreeMap<String, String>,
        OperatorBriefingStorageReport,
        String,
    ),
    String,
> {
    let dir = config.output_dir();
    fs::create_dir_all(&dir).map_err(|err| err.to_string())?;
    let mut refresh_with_paths = refresh.clone();
    refresh_with_paths.dashboard_html_path = Some(
        dir.join("control_tower_briefing.html")
            .display()
            .to_string(),
    );
    refresh_with_paths.briefing_state_path =
        Some(dir.join("briefing_state.json").display().to_string());
    refresh_with_paths.briefing_summary_path =
        Some(dir.join("briefing_summary.txt").display().to_string());
    let control_tower_html = render_sprint73_control_tower_html(&refresh_with_paths);
    let briefing_summary =
        build_sprint73_briefing_summary(closure, evidence, gate, &refresh_with_paths, acceptance);
    let final_summary = build_sprint73_final_summary(
        closure,
        coverage,
        evidence,
        gate,
        &refresh_with_paths,
        acceptance,
    );
    let mut files = BTreeMap::from([
        (
            "ext_model_b_prediction_closure.txt".to_string(),
            serde_json::to_string_pretty(closure).map_err(|err| err.to_string())?,
        ),
        (
            "prediction_coverage_finalization.txt".to_string(),
            serde_json::to_string_pretty(coverage).map_err(|err| err.to_string())?,
        ),
        (
            "evidence_gap_final_closure.txt".to_string(),
            serde_json::to_string_pretty(evidence).map_err(|err| err.to_string())?,
        ),
        (
            "direct_watch_readiness_final_gate.txt".to_string(),
            serde_json::to_string_pretty(gate).map_err(|err| err.to_string())?,
        ),
        (
            "control_tower_briefing_final_refresh.txt".to_string(),
            serde_json::to_string_pretty(&refresh_with_paths).map_err(|err| err.to_string())?,
        ),
        (
            "sprint73_workspace_acceptance.txt".to_string(),
            serde_json::to_string_pretty(acceptance).map_err(|err| err.to_string())?,
        ),
        (
            "control_tower_briefing.html".to_string(),
            control_tower_html,
        ),
        (
            "briefing_state.json".to_string(),
            serde_json::to_string_pretty(&refresh_with_paths).map_err(|err| err.to_string())?,
        ),
        ("briefing_summary.txt".to_string(), briefing_summary),
        ("summary.txt".to_string(), final_summary.clone()),
    ]);
    for (path, content) in fragments {
        files.insert(path.clone(), content.clone());
    }
    let storage_bytes = files.values().map(|text| text.len()).sum::<usize>();
    if storage_bytes > config.max_bytes {
        return Err("sprint73 output exceeded max_bytes".to_string());
    }
    let storage_report = OperatorBriefingStorageReport {
        artifact_count: files.len() + 1,
        storage_bytes,
        max_bytes: config.max_bytes,
        within_budget: true,
        reason_codes: stable_reason_codes(&[ReasonCode::ExtModelBPredictionGapClosureStorageBuilt]),
    };
    files.insert(
        "storage_report.txt".to_string(),
        serde_json::to_string_pretty(&storage_report).map_err(|err| err.to_string())?,
    );
    let mut static_fragments = BTreeMap::new();
    for (relative_path, content) in files {
        let full_path = dir.join(&relative_path);
        if let Some(parent) = full_path.parent() {
            fs::create_dir_all(parent).map_err(|err| err.to_string())?;
        }
        fs::write(&full_path, content).map_err(|err| err.to_string())?;
        if relative_path.starts_with("fragments/") {
            static_fragments.insert(relative_path, full_path.display().to_string());
        }
    }
    Ok((
        refresh_with_paths,
        static_fragments,
        storage_report,
        final_summary,
    ))
}

fn run_sprint73_workspace_acceptance_commands(
    config: &ExtModelBPredictionClosureConfig,
) -> Result<Sprint73WorkspaceAcceptanceReport, String> {
    config.validate()?;
    let repo_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let mut checks = Vec::new();
    checks.push(run_workspace_acceptance_check(
        "cargo fmt --all",
        "cargo fmt --all",
        {
            let mut command = Command::new("cargo");
            command.current_dir(&repo_root).args(["fmt", "--all"]);
            command
        },
    )?);
    checks.push(run_workspace_acceptance_check(
        "cargo check --workspace",
        "cargo check --workspace",
        {
            let mut command = Command::new("cargo");
            command
                .current_dir(&repo_root)
                .args(["check", "--workspace"]);
            command
        },
    )?);
    checks.push(run_workspace_acceptance_check(
        "cargo test --workspace --quiet",
        "cargo test --workspace --quiet",
        {
            let mut command = Command::new("cargo");
            command
                .current_dir(&repo_root)
                .args(["test", "--workspace", "--quiet"]);
            command
        },
    )?);
    checks.push(run_workspace_acceptance_check(
        "focused Sprint 73 test suite",
        "cargo test --quiet --test ext_model_b_prediction_closure --test prediction_coverage_finalization --test evidence_gap_final_closure --test direct_watch_final_gate --test control_tower_briefing_final_refresh --test sprint73_workspace_acceptance --test ext_model_b_prediction_closure_cli_safety --test ext_model_b_prediction_closure_determinism -- --test-threads=1",
        {
            let mut command = Command::new("cargo");
            command.current_dir(&repo_root).args([
                "test",
                "--quiet",
                "--test",
                "ext_model_b_prediction_closure",
                "--test",
                "prediction_coverage_finalization",
                "--test",
                "evidence_gap_final_closure",
                "--test",
                "direct_watch_final_gate",
                "--test",
                "control_tower_briefing_final_refresh",
                "--test",
                "sprint73_workspace_acceptance",
                "--test",
                "ext_model_b_prediction_closure_cli_safety",
                "--test",
                "ext_model_b_prediction_closure_determinism",
                "--",
                "--test-threads=1",
            ]);
            command
        },
    )?);
    let binary_path = sprint73_binary_path(&repo_root)?;
    checks.push(run_sprint73_cli_smoke_check(&repo_root, &binary_path)?);
    Ok(build_sprint73_workspace_acceptance_report(
        &format!("{}-workspace-acceptance", config.closure_id),
        checks,
    ))
}

fn sprint73_binary_path(repo_root: &Path) -> Result<PathBuf, String> {
    let candidate = repo_root
        .join("target")
        .join("debug")
        .join("soma_experiment");
    if candidate.exists() {
        Ok(candidate)
    } else {
        std::env::current_exe().map_err(|err| err.to_string())
    }
}

fn run_workspace_acceptance_check(
    name: &str,
    command_text: &str,
    mut command: Command,
) -> Result<WorkspaceAcceptanceCheck, String> {
    let output = command.output().map_err(|err| err.to_string())?;
    let summary = summarize_command_output(&output.stdout, &output.stderr);
    Ok(WorkspaceAcceptanceCheck {
        name: name.to_string(),
        command: command_text.to_string(),
        passed: output.status.success(),
        output_summary: summary,
        reason_codes: stable_reason_codes(&[ReasonCode::WorkspaceAcceptanceCheckBuilt]),
    })
}

fn run_sprint73_cli_smoke_check(
    repo_root: &Path,
    binary_path: &Path,
) -> Result<WorkspaceAcceptanceCheck, String> {
    let commands = [
        (
            "ext-model-b-prediction-close",
            "examples/soma_ext_model_b_prediction_close.toml",
        ),
        (
            "prediction-coverage-finalize",
            "examples/soma_prediction_coverage_finalize.toml",
        ),
        (
            "evidence-gap-final-close",
            "examples/soma_evidence_gap_final_close.toml",
        ),
        (
            "direct-watch-final-gate",
            "examples/soma_direct_watch_final_gate.toml",
        ),
        (
            "control-tower-final-refresh",
            "examples/soma_control_tower_final_refresh.toml",
        ),
    ];
    let mut all_passed = true;
    let mut summaries = Vec::new();
    for (command_name, config_path) in commands {
        let output = Command::new(binary_path)
            .current_dir(repo_root)
            .args([command_name, "--config", config_path])
            .output()
            .map_err(|err| err.to_string())?;
        all_passed &= output.status.success();
        summaries.push(format!(
            "{}={}",
            command_name,
            if output.status.success() {
                "ok"
            } else {
                "failed"
            }
        ));
    }
    Ok(WorkspaceAcceptanceCheck {
        name: "Sprint 73 CLI smoke commands".to_string(),
        command: "soma_experiment ext-model-b-prediction-close && prediction-coverage-finalize && evidence-gap-final-close && direct-watch-final-gate && control-tower-final-refresh".to_string(),
        passed: all_passed,
        output_summary: Some(summaries.join(" | ")),
        reason_codes: stable_reason_codes(&[ReasonCode::WorkspaceAcceptanceCheckBuilt]),
    })
}

fn summarize_command_output(stdout: &[u8], stderr: &[u8]) -> Option<String> {
    let combined = [
        String::from_utf8_lossy(stdout).to_string(),
        String::from_utf8_lossy(stderr).to_string(),
    ]
    .join("\n");
    combined
        .lines()
        .rev()
        .find(|line| !line.trim().is_empty())
        .map(|line| {
            let trimmed = line.trim();
            if trimmed.len() > 200 {
                trimmed[..200].to_string()
            } else {
                trimmed.to_string()
            }
        })
}

