impl Default for RealEvidenceFollowupConfig {
    fn default() -> Self {
        Self {
            followup_id: "sprint74-real-evidence-followup".to_string(),
            sprint73_final_bundle_paths: vec![
                "examples/sprint74_data/sprint73_final_briefing_state.json".to_string(),
                "examples/sprint74_data/sprint73_final_gate.json".to_string(),
            ],
            operator_briefing_paths: Vec::new(),
            kis_canonical_csv_paths: vec![
                "examples/sprint74_data/kis_real_canonical_sample.csv".to_string(),
            ],
            kis_provenance_paths: vec![
                "examples/sprint74_data/kis_real_provenance_sample.json".to_string(),
            ],
            kis_preflight_paths: vec![
                "examples/sprint74_data/kis_real_preflight_sample.json".to_string(),
            ],
            kis_manifest_paths: vec![
                "examples/sprint74_data/kis_real_manifest_sample.json".to_string(),
            ],
            kis_collection_plan_paths: Vec::new(),
            sequence_export_manifest_paths: vec![
                "examples/sprint74_data/kis_real_manifest_sample.json".to_string(),
            ],
            model_ops_paths: vec!["examples/sprint74_data/model_ops_state.json".to_string()],
            output_root: default_sprint74_output_root(),
            max_artifacts: default_max_artifacts(),
            max_rows: default_max_real_evidence_rows(),
            max_symbols: default_max_real_evidence_symbols(),
            max_timeframes: default_max_real_evidence_timeframes(),
            max_bytes: default_max_bytes(),
            prefer_local_import: true,
            allow_operator_market_data_collection: false,
            require_provenance: true,
            require_preflight: true,
            require_no_lookahead_safe: true,
            reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceFollowupConfigBuilt]),
        }
    }
}

impl RealEvidenceFollowupConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let mut config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.reason_codes = stable_reason_codes(&[ReasonCode::RealEvidenceFollowupConfigBuilt]);
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.followup_id.trim().is_empty()
            || self.max_artifacts == 0
            || self.max_rows == 0
            || self.max_symbols == 0
            || self.max_timeframes == 0
            || self.max_bytes == 0
        {
            return Err(
                "real evidence follow-up config requires identifiers and positive limits"
                    .to_string(),
            );
        }
        if self
            .input_paths()
            .into_iter()
            .chain(std::iter::once(self.output_root.clone()))
            .any(|path| path.contains("://"))
        {
            return Err("real evidence follow-up config paths must be local".to_string());
        }
        Ok(())
    }

    pub fn input_paths(&self) -> Vec<String> {
        self.sprint73_final_bundle_paths
            .iter()
            .chain(self.operator_briefing_paths.iter())
            .chain(self.kis_canonical_csv_paths.iter())
            .chain(self.kis_provenance_paths.iter())
            .chain(self.kis_preflight_paths.iter())
            .chain(self.kis_manifest_paths.iter())
            .chain(self.kis_collection_plan_paths.iter())
            .chain(self.sequence_export_manifest_paths.iter())
            .chain(self.model_ops_paths.iter())
            .cloned()
            .collect()
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.followup_id)
    }
}

impl RealEvidenceFollowupRunner {
    pub fn run(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidenceFollowupBundle, String> {
        self.run_internal(config)
    }

    pub fn run_attachment_report(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidenceAttachmentReport, String> {
        Ok(self.run(config)?.real_evidence_attachment_report)
    }

    pub fn run_import_plan(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<KISRealEvidenceImportPlan, String> {
        Ok(self.run(config)?.kis_real_evidence_import_plan)
    }

    pub fn run_validation(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<KISRealEvidenceValidationReport, String> {
        Ok(self.run(config)?.kis_real_evidence_validation_report)
    }

    pub fn run_provenance_audit(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidenceProvenanceAudit, String> {
        Ok(self.run(config)?.real_evidence_provenance_audit)
    }

    pub fn run_preflight_audit(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidencePreflightAudit, String> {
        Ok(self.run(config)?.real_evidence_preflight_audit)
    }

    pub fn run_outcome_readiness(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidenceOutcomeReadinessReport, String> {
        Ok(self.run(config)?.real_evidence_outcome_readiness_report)
    }

    pub fn run_sequence_readiness(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidenceSequenceReadinessReport, String> {
        Ok(self.run(config)?.real_evidence_sequence_readiness_report)
    }

    pub fn run_model_ops_impact(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidenceModelOpsImpactReport, String> {
        Ok(self.run(config)?.real_evidence_model_ops_impact_report)
    }

    pub fn run_warning_reduction(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<ControlTowerWarningReductionReport, String> {
        Ok(self.run(config)?.control_tower_warning_reduction_report)
    }

    pub fn run_direct_watch_warning_rationale(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<DirectWatchWarningRationaleReport, String> {
        Ok(self.run(config)?.direct_watch_warning_rationale_report)
    }

    pub fn run_runbook(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidenceOperatorRunbook, String> {
        Ok(self.run(config)?.real_evidence_operator_runbook)
    }

    pub fn run_control_tower_refresh(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<ControlTowerRealEvidenceRefresh, String> {
        Ok(self.run(config)?.control_tower_real_evidence_refresh)
    }

    fn run_internal(
        &self,
        config: &RealEvidenceFollowupConfig,
    ) -> Result<RealEvidenceFollowupBundle, String> {
        config.validate()?;
        if config.input_paths().len() > config.max_artifacts {
            return Err("real evidence follow-up max_artifacts exceeded".to_string());
        }
        let total_input_bytes = config
            .input_paths()
            .iter()
            .filter_map(|path| fs::metadata(path).ok())
            .map(|meta| meta.len() as usize)
            .sum::<usize>();
        if total_input_bytes > config.max_bytes {
            return Err("real evidence follow-up max_bytes exceeded".to_string());
        }
        let context = load_sprint74_context(config)?;
        let csv_summary = load_sprint74_csv_summary(config)?;
        let attachment = build_real_evidence_attachment_report(config, &context, &csv_summary)?;
        let import_plan = build_kis_real_evidence_import_plan(config, &attachment);
        let validation =
            build_kis_real_evidence_validation_report(config, &attachment, &csv_summary);
        let provenance = build_real_evidence_provenance_audit(config, &attachment, &context);
        let preflight = build_real_evidence_preflight_audit(config, &attachment, &context);
        let outcome = build_real_evidence_outcome_readiness_report(
            config,
            &attachment,
            &validation,
            &context,
        );
        let sequence = build_real_evidence_sequence_readiness_report(
            config,
            &attachment,
            &validation,
            &context,
        );
        let model_ops =
            build_real_evidence_model_ops_impact_report(config, &attachment, &sequence, &context);
        let warning_reduction = build_control_tower_warning_reduction_report(
            config,
            &context,
            &attachment,
            &provenance,
            &preflight,
            &outcome,
            &sequence,
            &model_ops,
        );
        let rationale = build_direct_watch_warning_rationale_report(
            config,
            &context,
            &warning_reduction,
            &provenance,
            &preflight,
            &outcome,
            &sequence,
            &model_ops,
        );
        let runbook = build_real_evidence_operator_runbook(
            config,
            &provenance,
            &preflight,
            &outcome,
            &sequence,
            &model_ops,
        );
        let refresh = build_control_tower_real_evidence_refresh(
            config,
            &attachment,
            &validation,
            &provenance,
            &preflight,
            &outcome,
            &sequence,
            &model_ops,
            &warning_reduction,
            &rationale,
        );
        let (storage_report, final_summary) = write_real_evidence_followup_bundle(
            config,
            &attachment,
            &import_plan,
            &validation,
            &provenance,
            &preflight,
            &outcome,
            &sequence,
            &model_ops,
            &warning_reduction,
            &rationale,
            &runbook,
            &refresh,
        )?;
        Ok(RealEvidenceFollowupBundle {
            real_evidence_attachment_report: attachment,
            kis_real_evidence_import_plan: import_plan,
            kis_real_evidence_validation_report: validation,
            real_evidence_provenance_audit: provenance,
            real_evidence_preflight_audit: preflight,
            real_evidence_outcome_readiness_report: outcome,
            real_evidence_sequence_readiness_report: sequence,
            real_evidence_model_ops_impact_report: model_ops,
            control_tower_warning_reduction_report: warning_reduction,
            direct_watch_warning_rationale_report: rationale,
            real_evidence_operator_runbook: runbook,
            control_tower_real_evidence_refresh: refresh,
            storage_report,
            final_summary,
            reason_codes: stable_reason_codes(&[
                ReasonCode::RealEvidenceFollowupRunnerBuilt,
                ReasonCode::RealEvidenceFollowupBundleBuilt,
            ]),
        })
    }
}

fn load_sprint74_context(config: &RealEvidenceFollowupConfig) -> Result<Sprint74Context, String> {
    let mut context = Sprint74Context {
        briefing_state: default_sprint74_briefing_state(),
        final_gate: default_sprint74_final_gate(),
        provenance_records: load_sprint74_provenance_records(&config.kis_provenance_paths)?,
        preflight_records: load_sprint74_preflight_records(&config.kis_preflight_paths)?,
        manifest_records: load_sprint74_manifest_records(
            &config.kis_manifest_paths,
            &config.sequence_export_manifest_paths,
        )?,
        model_ops_state: load_sprint74_model_ops_state(&config.model_ops_paths)?,
    };

    for path in config
        .sprint73_final_bundle_paths
        .iter()
        .chain(config.operator_briefing_paths.iter())
    {
        if let Ok(bundle) = read_json_file::<ExtModelBPredictionGapClosureBundle>(path) {
            context.briefing_state = Sprint74BriefingStateInput {
                briefing_state_after: bundle
                    .control_tower_briefing_final_refresh
                    .briefing_state_after
                    .clone(),
                warning_kinds: vec![
                    ControlTowerWarningKind::EvidenceFixtureOnly,
                    ControlTowerWarningKind::ModelPredictionsStale,
                    ControlTowerWarningKind::DirectWatchMonitoringOnly,
                    ControlTowerWarningKind::RuntimeMambaDeferred,
                    ControlTowerWarningKind::LiveTradingForbidden,
                    ControlTowerWarningKind::BrokerForbidden,
                ],
            };
            context.final_gate = Sprint74FinalGateInput {
                gate_status: format!("{:?}", bundle.direct_watch_readiness_final_gate.gate_status),
                current_score_min: bundle.direct_watch_readiness_final_gate.current_score_min,
                current_score_max: bundle.direct_watch_readiness_final_gate.current_score_max,
            };
            break;
        }
        if let Ok(state) = read_json_file::<Sprint74StateInput>(path) {
            if let Some(refresh) = state.control_tower_briefing_final_refresh {
                context.briefing_state.briefing_state_after = refresh.briefing_state_after;
            }
            if let Some(gate) = state.direct_watch_readiness_final_gate {
                context.final_gate = Sprint74FinalGateInput {
                    gate_status: format!("{:?}", gate.gate_status),
                    current_score_min: gate.current_score_min,
                    current_score_max: gate.current_score_max,
                };
            }
        }
        if let Ok(briefing) = read_json_file::<Sprint74BriefingStateInput>(path) {
            if !briefing.briefing_state_after.is_empty() {
                context.briefing_state = briefing;
            }
        }
        if let Ok(gate) = read_json_file::<Sprint74FinalGateInput>(path) {
            if !gate.gate_status.is_empty() {
                context.final_gate = gate;
            }
        }
    }
    Ok(context)
}

fn default_sprint74_briefing_state() -> Sprint74BriefingStateInput {
    Sprint74BriefingStateInput {
        briefing_state_after: "BriefingReadyWithWarnings".to_string(),
        warning_kinds: vec![
            ControlTowerWarningKind::EvidenceFixtureOnly,
            ControlTowerWarningKind::ModelPredictionsStale,
            ControlTowerWarningKind::DirectWatchMonitoringOnly,
            ControlTowerWarningKind::RuntimeMambaDeferred,
            ControlTowerWarningKind::LiveTradingForbidden,
            ControlTowerWarningKind::BrokerForbidden,
        ],
    }
}

fn default_sprint74_final_gate() -> Sprint74FinalGateInput {
    Sprint74FinalGateInput {
        gate_status: "DirectWatchReadyWithWarnings".to_string(),
        current_score_min: 88,
        current_score_max: 90,
    }
}

fn load_sprint74_model_ops_state(paths: &[String]) -> Result<Sprint74ModelOpsStateInput, String> {
    for path in paths {
        if let Ok(state) = read_json_file::<Sprint74ModelOpsStateInput>(path) {
            return Ok(state);
        }
    }
    Ok(Sprint74ModelOpsStateInput {
        evidence_rows_added: 0,
        sequence_windows_added: 0,
        existing_prediction_coverage_affected: false,
        models_requiring_new_predictions: Vec::new(),
        models_requiring_reevaluation: Vec::new(),
    })
}

fn load_sprint74_provenance_records(
    paths: &[String],
) -> Result<Vec<Sprint74ProvenanceRecordInput>, String> {
    let mut records = Vec::new();
    for path in paths {
        let input = read_json_file::<Sprint74ProvenanceInput>(path)?;
        records.extend(input.records);
    }
    Ok(records)
}

fn load_sprint74_preflight_records(
    paths: &[String],
) -> Result<Vec<Sprint74PreflightRecordInput>, String> {
    let mut records = Vec::new();
    for path in paths {
        let input = read_json_file::<Sprint74PreflightInput>(path)?;
        records.extend(input.records);
    }
    Ok(records)
}

fn load_sprint74_manifest_records(
    manifest_paths: &[String],
    sequence_manifest_paths: &[String],
) -> Result<Vec<Sprint74ManifestRecordInput>, String> {
    let mut records = BTreeMap::new();
    for path in manifest_paths.iter().chain(sequence_manifest_paths.iter()) {
        if let Ok(input) = read_json_file::<Sprint74ManifestInput>(path) {
            for record in input.records {
                records.entry(record.local_path.clone()).or_insert(record);
            }
            continue;
        }
        if let Ok(manifest) = read_json_file::<SequenceExportManifest>(path) {
            records.entry(manifest.dataset_csv_path.clone()).or_insert(
                Sprint74ManifestRecordInput {
                    local_path: manifest.dataset_csv_path,
                    row_count: Some(manifest.row_count),
                    no_lookahead_safe: Some(!manifest.no_lookahead_proof_path.trim().is_empty()),
                    feature_schema_match: Some(true),
                    label_manifest_match: Some(true),
                    barrier_profile_present: Some(true),
                    outcome_links_present: Some(true),
                    future_window_gap_count: Some(0),
                    estimated_windows: Some(manifest.sequence_count),
                    storage_within_budget: Some(true),
                    source_class: Some(RealEvidenceSourceClass::OfficialKIS),
                    symbol: None,
                    market: None,
                    timeframe: None,
                },
            );
        }
    }
    Ok(records.into_values().collect())
}

fn load_sprint74_csv_summary(
    config: &RealEvidenceFollowupConfig,
) -> Result<Sprint74CsvSummary, String> {
    let mut summary = Sprint74CsvSummary::default();
    let mut seen_timestamps = BTreeSet::new();
    for path in &config.kis_canonical_csv_paths {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let mut lines = text.lines();
        let header = lines
            .next()
            .ok_or_else(|| "real evidence canonical csv missing header".to_string())?;
        let headers = header
            .split(',')
            .map(|item| item.trim())
            .collect::<Vec<_>>();
        let required = [
            "symbol",
            "market",
            "timeframe",
            "timestamp",
            "open",
            "high",
            "low",
            "close",
            "volume",
        ];
        let missing = required
            .iter()
            .filter(|name| !headers.iter().any(|column| column == *name))
            .count();
        summary.missing_columns_count += missing;
        if missing > 0 {
            continue;
        }
        let symbol_idx = headers
            .iter()
            .position(|column| *column == "symbol")
            .unwrap_or(0);
        let market_idx = headers
            .iter()
            .position(|column| *column == "market")
            .unwrap_or(1);
        let timeframe_idx = headers
            .iter()
            .position(|column| *column == "timeframe")
            .unwrap_or(2);
        let timestamp_idx = headers
            .iter()
            .position(|column| *column == "timestamp")
            .unwrap_or(3);
        let open_idx = headers
            .iter()
            .position(|column| *column == "open")
            .unwrap_or(4);
        let high_idx = headers
            .iter()
            .position(|column| *column == "high")
            .unwrap_or(5);
        let low_idx = headers
            .iter()
            .position(|column| *column == "low")
            .unwrap_or(6);
        let close_idx = headers
            .iter()
            .position(|column| *column == "close")
            .unwrap_or(7);
        let mut per_file_rows = 0usize;
        let mut first_meta = None;
        for line in lines {
            if line.trim().is_empty() {
                continue;
            }
            let values = line.split(',').map(|item| item.trim()).collect::<Vec<_>>();
            let symbol = values.get(symbol_idx).copied().unwrap_or("").to_string();
            let market = values.get(market_idx).copied().unwrap_or("").to_string();
            let timeframe = values.get(timeframe_idx).copied().unwrap_or("").to_string();
            let timestamp = values.get(timestamp_idx).copied().unwrap_or("").to_string();
            let open = values
                .get(open_idx)
                .and_then(|value| value.parse::<f64>().ok())
                .unwrap_or(0.0);
            let high = values
                .get(high_idx)
                .and_then(|value| value.parse::<f64>().ok())
                .unwrap_or(0.0);
            let low = values
                .get(low_idx)
                .and_then(|value| value.parse::<f64>().ok())
                .unwrap_or(0.0);
            let close = values
                .get(close_idx)
                .and_then(|value| value.parse::<f64>().ok())
                .unwrap_or(0.0);
            summary.total_rows += 1;
            per_file_rows += 1;
            if summary.total_rows > config.max_rows {
                return Err("real evidence follow-up max_rows exceeded".to_string());
            }
            summary.unique_symbols.insert(symbol.clone());
            summary.unique_timeframes.insert(timeframe.clone());
            if !seen_timestamps.insert((
                symbol.clone(),
                market.clone(),
                timeframe.clone(),
                timestamp,
            )) {
                summary.duplicate_timestamp_count += 1;
            }
            if low > high || low > open.min(close) || high < open.max(close) {
                summary.ohlc_invariant_fail_count += 1;
            }
            if first_meta.is_none() {
                first_meta = Some((symbol, market, timeframe));
            }
        }
        summary
            .row_count_by_path
            .insert(path.clone(), per_file_rows);
        if let Some(meta) = first_meta {
            summary.meta_by_path.insert(path.clone(), meta);
        }
    }
    if summary.unique_symbols.len() > config.max_symbols {
        return Err("real evidence follow-up max_symbols exceeded".to_string());
    }
    if summary.unique_timeframes.len() > config.max_timeframes {
        return Err("real evidence follow-up max_timeframes exceeded".to_string());
    }
    Ok(summary)
}

fn build_real_evidence_attachment_report(
    config: &RealEvidenceFollowupConfig,
    context: &Sprint74Context,
    csv_summary: &Sprint74CsvSummary,
) -> Result<RealEvidenceAttachmentReport, String> {
    let mut records = Vec::new();
    for path in &config.kis_canonical_csv_paths {
        let manifest = find_manifest_record(&context.manifest_records, path);
        let provenance = find_provenance_record(&context.provenance_records, path);
        let preflight = find_preflight_record(&context.preflight_records, path);
        let (symbol, market, timeframe) = manifest
            .and_then(|record| {
                Some((
                    record.symbol.clone()?,
                    record.market.clone()?,
                    record.timeframe.clone()?,
                ))
            })
            .or_else(|| {
                csv_summary
                    .meta_by_path
                    .get(path)
                    .map(|(symbol, market, timeframe)| {
                        (symbol.clone(), market.clone(), timeframe.clone())
                    })
            })
            .unwrap_or_else(|| ("".to_string(), "".to_string(), "".to_string()));
        let source_class = manifest
            .and_then(|record| record.source_class)
            .or_else(|| provenance.and_then(|record| record.source_class))
            .unwrap_or(RealEvidenceSourceClass::Unknown);
        let provider_kind = match source_class {
            RealEvidenceSourceClass::OfficialKIS => "KoreaInvestmentMarketData",
            RealEvidenceSourceClass::OfficialKRXReference => "KrxOpenApi",
            RealEvidenceSourceClass::OfficialAlphaVantageFallback => "AlphaVantage",
            RealEvidenceSourceClass::ResearchOnly => "ResearchOnly",
            RealEvidenceSourceClass::DiagnosticOnly => "DiagnosticOnly",
            RealEvidenceSourceClass::FixtureOnly => "FixtureOnly",
            RealEvidenceSourceClass::Unknown => "Unknown",
        }
        .to_string();
        let row_count = manifest
            .and_then(|record| record.row_count)
            .or_else(|| csv_summary.row_count_by_path.get(path).copied());
        let storage_bytes = fs::metadata(path)
            .map(|meta| meta.len() as usize)
            .unwrap_or(0);
        let has_manifest = manifest.is_some();
        let has_provenance = provenance.is_some();
        let has_preflight = preflight.is_some();
        let no_lookahead_safe = manifest.and_then(|record| record.no_lookahead_safe);
        let valid = Path::new(path).exists()
            && !path.contains("://")
            && !matches!(source_class, RealEvidenceSourceClass::Unknown)
            && (!matches!(source_class, RealEvidenceSourceClass::OfficialKIS)
                || (!config.require_provenance || has_provenance)
                    && (!config.require_preflight || has_preflight));
        let diagnostic_only = matches!(
            source_class,
            RealEvidenceSourceClass::DiagnosticOnly | RealEvidenceSourceClass::Unknown
        );
        records.push(RealEvidenceAttachmentRecord {
            evidence_id: format!("{}-{}", config.followup_id, stable_hash_string(path)),
            source_class,
            provider_kind,
            local_path: path.clone(),
            symbol: if symbol.is_empty() {
                None
            } else {
                Some(symbol)
            },
            market: if market.is_empty() {
                None
            } else {
                Some(market)
            },
            timeframe: if timeframe.is_empty() {
                None
            } else {
                Some(timeframe)
            },
            row_count,
            has_provenance,
            has_preflight,
            has_manifest,
            no_lookahead_safe,
            storage_bytes,
            valid,
            diagnostic_only,
            reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceAttachmentRecordBuilt]),
        });
    }
    records.sort_by(|left, right| left.local_path.cmp(&right.local_path));
    let official_kis_count = records
        .iter()
        .filter(|record| matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS))
        .count();
    let official_ready_count = records
        .iter()
        .filter(|record| {
            matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS)
                && record.valid
                && record.has_manifest
                && (!config.require_no_lookahead_safe || record.no_lookahead_safe.unwrap_or(false))
        })
        .count();
    let research_only_count = records
        .iter()
        .filter(|record| matches!(record.source_class, RealEvidenceSourceClass::ResearchOnly))
        .count();
    let diagnostic_only_count = records
        .iter()
        .filter(|record| matches!(record.source_class, RealEvidenceSourceClass::DiagnosticOnly))
        .count();
    let fixture_only_count = records
        .iter()
        .filter(|record| matches!(record.source_class, RealEvidenceSourceClass::FixtureOnly))
        .count();
    let invalid_count = records.iter().filter(|record| !record.valid).count();
    let total_rows = records
        .iter()
        .filter_map(|record| record.row_count)
        .sum::<usize>();
    let attachment_status = if records.is_empty() {
        RealEvidenceAttachmentStatus::DiagnosticOnly
    } else if invalid_count > 0 {
        RealEvidenceAttachmentStatus::InvalidEvidence
    } else if config.require_provenance
        && records.iter().any(|record| {
            matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS)
                && !record.has_provenance
        })
    {
        RealEvidenceAttachmentStatus::MissingProvenance
    } else if config.require_preflight
        && records.iter().any(|record| {
            matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS)
                && !record.has_preflight
        })
    {
        RealEvidenceAttachmentStatus::MissingPreflight
    } else if records.iter().any(|record| {
        matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS) && !record.has_manifest
    }) {
        RealEvidenceAttachmentStatus::MissingManifest
    } else if config.require_no_lookahead_safe
        && records.iter().any(|record| {
            matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS)
                && !record.no_lookahead_safe.unwrap_or(false)
        })
    {
        RealEvidenceAttachmentStatus::MissingNoLookaheadProof
    } else if official_ready_count == 0 {
        RealEvidenceAttachmentStatus::DiagnosticOnly
    } else if research_only_count > 0 || diagnostic_only_count > 0 || fixture_only_count > 0 {
        RealEvidenceAttachmentStatus::RealEvidenceAttachedWithWarnings
    } else {
        RealEvidenceAttachmentStatus::RealEvidenceAttached
    };
    Ok(RealEvidenceAttachmentReport {
        followup_id: config.followup_id.clone(),
        records,
        official_kis_count,
        official_ready_count,
        research_only_count,
        diagnostic_only_count,
        fixture_only_count,
        invalid_count,
        total_rows,
        attachment_status,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceAttachmentReportBuilt]),
    })
}

fn build_kis_real_evidence_import_plan(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
) -> KISRealEvidenceImportPlan {
    let mut jobs = Vec::new();
    for record in &attachment.records {
        let symbol = record
            .symbol
            .clone()
            .unwrap_or_else(|| "UNKNOWN".to_string());
        let market = record
            .market
            .clone()
            .unwrap_or_else(|| "UNKNOWN".to_string());
        let timeframe = record.timeframe.clone().unwrap_or_else(|| "1d".to_string());
        jobs.push(KISRealEvidenceImportJob {
            job_id: format!(
                "{}-local-{}",
                config.followup_id,
                stable_hash_string(&record.local_path)
            ),
            import_mode: KISRealEvidenceImportMode::LocalOfficialCsv,
            symbol: symbol.clone(),
            market: market.clone(),
            timeframe: timeframe.clone(),
            expected_canonical_csv: Some(record.local_path.clone()),
            expected_provenance: if record.has_provenance {
                Some("local provenance attached".to_string())
            } else {
                None
            },
            expected_preflight: if record.has_preflight {
                Some("local preflight attached".to_string())
            } else {
                None
            },
            expected_manifest: if record.has_manifest {
                Some("local manifest attached".to_string())
            } else {
                None
            },
            runnable: Path::new(&record.local_path).exists(),
            skipped_reason: None,
            reason_codes: stable_reason_codes(&[ReasonCode::KISRealEvidenceImportJobBuilt]),
        });
        jobs.push(KISRealEvidenceImportJob {
            job_id: format!(
                "{}-reuse-{}",
                config.followup_id,
                stable_hash_string(&record.local_path)
            ),
            import_mode: KISRealEvidenceImportMode::ExistingCanonicalReuse,
            symbol: symbol.clone(),
            market: market.clone(),
            timeframe: timeframe.clone(),
            expected_canonical_csv: Some(record.local_path.clone()),
            expected_provenance: None,
            expected_preflight: None,
            expected_manifest: None,
            runnable: record.valid,
            skipped_reason: if record.valid {
                None
            } else {
                Some("existing canonical evidence is not yet valid".to_string())
            },
            reason_codes: stable_reason_codes(&[ReasonCode::KISRealEvidenceImportJobBuilt]),
        });
        jobs.push(KISRealEvidenceImportJob {
            job_id: format!(
                "{}-collect-{}",
                config.followup_id,
                stable_hash_string(&record.local_path)
            ),
            import_mode: if config.allow_operator_market_data_collection {
                KISRealEvidenceImportMode::OperatorMarketDataCollectionLiveEnabled
            } else {
                KISRealEvidenceImportMode::OperatorMarketDataCollectionDryRun
            },
            symbol,
            market,
            timeframe,
            expected_canonical_csv: None,
            expected_provenance: None,
            expected_preflight: None,
            expected_manifest: None,
            runnable: config.allow_operator_market_data_collection,
            skipped_reason: if config.allow_operator_market_data_collection {
                None
            } else {
                Some("collection live disabled by default".to_string())
            },
            reason_codes: stable_reason_codes(&[ReasonCode::KISRealEvidenceImportJobBuilt]),
        });
    }
    jobs.sort_by(|left, right| left.job_id.cmp(&right.job_id));
    let runnable_jobs = jobs.iter().filter(|job| job.runnable).count();
    let skipped_jobs = jobs.len().saturating_sub(runnable_jobs);
    let operator_actions = vec![
        "cargo run --quiet --bin soma_experiment -- real-evidence-attach --config examples/soma_real_evidence_attach.toml".to_string(),
        "cargo run --quiet --bin soma_experiment -- kis-real-evidence-validate --config examples/soma_kis_real_evidence_validate.toml".to_string(),
    ];
    let plan_status = if attachment.official_kis_count == 0 {
        KISRealEvidenceImportPlanStatus::MissingLocalEvidence
    } else if matches!(
        attachment.attachment_status,
        RealEvidenceAttachmentStatus::MissingProvenance
    ) {
        KISRealEvidenceImportPlanStatus::MissingProvenance
    } else if matches!(
        attachment.attachment_status,
        RealEvidenceAttachmentStatus::MissingPreflight
    ) {
        KISRealEvidenceImportPlanStatus::MissingPreflight
    } else if !config.allow_operator_market_data_collection {
        KISRealEvidenceImportPlanStatus::CollectionDisabled
    } else if attachment.official_ready_count > 0 {
        KISRealEvidenceImportPlanStatus::ImportPlanReady
    } else {
        KISRealEvidenceImportPlanStatus::DiagnosticOnly
    };
    KISRealEvidenceImportPlan {
        plan_id: format!("{}-kis-import-plan", config.followup_id),
        jobs,
        runnable_jobs,
        skipped_jobs,
        operator_actions,
        plan_status,
        reason_codes: stable_reason_codes(&[ReasonCode::KISRealEvidenceImportPlanBuilt]),
    }
}

fn build_kis_real_evidence_validation_report(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
    csv_summary: &Sprint74CsvSummary,
) -> KISRealEvidenceValidationReport {
    let provenance_ready_rows = attachment
        .records
        .iter()
        .filter(|record| record.has_provenance)
        .filter_map(|record| record.row_count)
        .sum::<usize>();
    let preflight_ready_rows = attachment
        .records
        .iter()
        .filter(|record| record.has_preflight)
        .filter_map(|record| record.row_count)
        .sum::<usize>();
    let official_ready_rows = attachment
        .records
        .iter()
        .filter(|record| {
            matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS)
                && record.valid
                && record.has_manifest
                && (!config.require_no_lookahead_safe || record.no_lookahead_safe.unwrap_or(false))
        })
        .filter_map(|record| record.row_count)
        .sum::<usize>();
    let invalid_records =
        csv_summary.duplicate_timestamp_count + csv_summary.ohlc_invariant_fail_count;
    let mut data_quality_warnings = Vec::new();
    if csv_summary.duplicate_timestamp_count > 0 {
        data_quality_warnings.push("duplicate timestamps detected".to_string());
    }
    if csv_summary.ohlc_invariant_fail_count > 0 {
        data_quality_warnings.push("OHLC invariant failures detected".to_string());
    }
    let validation_status = if attachment.records.is_empty() {
        KISRealEvidenceValidationStatus::DiagnosticOnly
    } else if csv_summary.missing_columns_count > 0 {
        KISRealEvidenceValidationStatus::MissingRequiredColumns
    } else if config.require_provenance && provenance_ready_rows < csv_summary.total_rows {
        KISRealEvidenceValidationStatus::MissingProvenance
    } else if config.require_preflight && preflight_ready_rows < csv_summary.total_rows {
        KISRealEvidenceValidationStatus::MissingPreflight
    } else if invalid_records > 0 {
        KISRealEvidenceValidationStatus::DataQualityTooLow
    } else if !data_quality_warnings.is_empty() {
        KISRealEvidenceValidationStatus::ValidationReadyWithWarnings
    } else {
        KISRealEvidenceValidationStatus::ValidationReady
    };
    KISRealEvidenceValidationReport {
        validation_id: format!("{}-kis-validation", config.followup_id),
        validated_records: csv_summary.total_rows.saturating_sub(invalid_records),
        invalid_records,
        canonical_rows: csv_summary.total_rows,
        official_ready_rows,
        preflight_ready_rows,
        provenance_ready_rows,
        missing_columns_count: csv_summary.missing_columns_count,
        duplicate_timestamp_count: csv_summary.duplicate_timestamp_count,
        ohlc_invariant_fail_count: csv_summary.ohlc_invariant_fail_count,
        data_quality_warnings: stable_ordered_strings(&data_quality_warnings),
        validation_status,
        reason_codes: stable_reason_codes(&[ReasonCode::KISRealEvidenceValidationReportBuilt]),
    }
}

fn build_real_evidence_provenance_audit(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
    context: &Sprint74Context,
) -> RealEvidenceProvenanceAudit {
    let records_checked = attachment.records.len();
    let provenance_present_count = attachment
        .records
        .iter()
        .filter(|record| record.has_provenance)
        .count();
    let provenance_missing_count = records_checked.saturating_sub(provenance_present_count);
    let provider_label_present_count = attachment
        .records
        .iter()
        .filter_map(|record| {
            find_provenance_record(&context.provenance_records, &record.local_path)
        })
        .filter(|record| {
            record
                .provider_label
                .as_ref()
                .is_some_and(|value| !value.trim().is_empty())
        })
        .count();
    let source_class_present_count = attachment
        .records
        .iter()
        .filter_map(|record| {
            find_provenance_record(&context.provenance_records, &record.local_path)
        })
        .filter(|record| {
            !matches!(
                record
                    .source_class
                    .unwrap_or(RealEvidenceSourceClass::Unknown),
                RealEvidenceSourceClass::Unknown
            )
        })
        .count();
    let downloaded_by_soma_count = context
        .provenance_records
        .iter()
        .filter(|record| record.downloaded_by_soma)
        .count();
    let remote_url_like_count = context
        .provenance_records
        .iter()
        .filter(|record| {
            record
                .remote_url
                .as_ref()
                .is_some_and(|value| value.contains("://"))
                || record.local_path.contains("://")
        })
        .count();
    let audit_status = if records_checked == 0 {
        RealEvidenceProvenanceAuditStatus::DiagnosticOnly
    } else if remote_url_like_count > 0 {
        RealEvidenceProvenanceAuditStatus::UnsafeRemoteSource
    } else if config.require_provenance
        && (provenance_missing_count > 0
            || provider_label_present_count < provenance_present_count
            || source_class_present_count < provenance_present_count)
    {
        RealEvidenceProvenanceAuditStatus::MissingProvenance
    } else if downloaded_by_soma_count > 0 {
        RealEvidenceProvenanceAuditStatus::ProvenanceReadyWithWarnings
    } else {
        RealEvidenceProvenanceAuditStatus::ProvenanceReady
    };
    RealEvidenceProvenanceAudit {
        audit_id: format!("{}-provenance-audit", config.followup_id),
        records_checked,
        provenance_present_count,
        provenance_missing_count,
        provider_label_present_count,
        source_class_present_count,
        downloaded_by_soma_count,
        remote_url_like_count,
        audit_status,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceProvenanceAuditBuilt]),
    }
}

fn build_real_evidence_preflight_audit(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
    context: &Sprint74Context,
) -> RealEvidencePreflightAudit {
    let records_checked = attachment.records.len();
    let preflight_present_count = attachment
        .records
        .iter()
        .filter(|record| record.has_preflight)
        .count();
    let preflight_missing_count = records_checked.saturating_sub(preflight_present_count);
    let preflight_pass_count = context
        .preflight_records
        .iter()
        .filter(|record| record.passed)
        .count();
    let preflight_fail_count = context
        .preflight_records
        .len()
        .saturating_sub(preflight_pass_count);
    let qualities = context
        .preflight_records
        .iter()
        .map(|record| record.data_quality_score)
        .collect::<Vec<_>>();
    let data_quality_min = qualities.iter().copied().reduce(f64::min).unwrap_or(0.0);
    let data_quality_avg = if qualities.is_empty() {
        0.0
    } else {
        qualities.iter().sum::<f64>() / qualities.len() as f64
    };
    let audit_status = if records_checked == 0 {
        RealEvidencePreflightAuditStatus::DiagnosticOnly
    } else if config.require_preflight && preflight_missing_count > 0 {
        RealEvidencePreflightAuditStatus::MissingPreflight
    } else if preflight_fail_count > 0 {
        RealEvidencePreflightAuditStatus::PreflightFailed
    } else if data_quality_min < 0.95 {
        RealEvidencePreflightAuditStatus::PreflightReadyWithWarnings
    } else {
        RealEvidencePreflightAuditStatus::PreflightReady
    };
    RealEvidencePreflightAudit {
        audit_id: format!("{}-preflight-audit", config.followup_id),
        records_checked,
        preflight_present_count,
        preflight_missing_count,
        preflight_pass_count,
        preflight_fail_count,
        data_quality_min,
        data_quality_avg,
        audit_status,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidencePreflightAuditBuilt]),
    }
}

fn build_real_evidence_outcome_readiness_report(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
    validation: &KISRealEvidenceValidationReport,
    context: &Sprint74Context,
) -> RealEvidenceOutcomeReadinessReport {
    let eligible_rows = validation.official_ready_rows;
    let complete_rows = eligible_rows;
    let outcome_links_present = context
        .manifest_records
        .iter()
        .all(|record| record.outcome_links_present.unwrap_or(true));
    let future_window_gap_count = context
        .manifest_records
        .iter()
        .map(|record| record.future_window_gap_count.unwrap_or(0))
        .sum::<usize>();
    let barrier_profile_present = !context.manifest_records.is_empty()
        && context
            .manifest_records
            .iter()
            .all(|record| record.barrier_profile_present.unwrap_or(true));
    let no_lookahead_safe = attachment.records.iter().all(|record| {
        !matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS)
            || record.no_lookahead_safe.unwrap_or(false)
    });
    let outcome_links_possible = complete_rows > 0
        && !matches!(
            attachment.attachment_status,
            RealEvidenceAttachmentStatus::MissingProvenance
                | RealEvidenceAttachmentStatus::MissingPreflight
                | RealEvidenceAttachmentStatus::InvalidEvidence
        );
    let readiness_status = if eligible_rows == 0 || complete_rows == 0 {
        RealEvidenceOutcomeReadinessStatus::NeedMoreRows
    } else if !barrier_profile_present {
        RealEvidenceOutcomeReadinessStatus::NeedBarrierProfile
    } else if config.require_no_lookahead_safe && !no_lookahead_safe {
        RealEvidenceOutcomeReadinessStatus::NeedNoLookaheadProof
    } else if future_window_gap_count > 0 {
        RealEvidenceOutcomeReadinessStatus::NeedFutureWindows
    } else if !outcome_links_present {
        RealEvidenceOutcomeReadinessStatus::NeedOutcomeLinks
    } else if complete_rows < 8 {
        RealEvidenceOutcomeReadinessStatus::OutcomeReadyWithWarnings
    } else {
        RealEvidenceOutcomeReadinessStatus::OutcomeReady
    };
    let next_actions = match readiness_status {
        RealEvidenceOutcomeReadinessStatus::NeedMoreRows => {
            vec!["attach more local official KIS rows".to_string()]
        }
        RealEvidenceOutcomeReadinessStatus::NeedBarrierProfile => {
            vec!["attach barrier profile manifest".to_string()]
        }
        RealEvidenceOutcomeReadinessStatus::NeedNoLookaheadProof => {
            vec!["attach no-lookahead proof".to_string()]
        }
        RealEvidenceOutcomeReadinessStatus::NeedFutureWindows => {
            vec!["extend future windows conservatively".to_string()]
        }
        RealEvidenceOutcomeReadinessStatus::NeedOutcomeLinks => {
            vec!["materialize outcome links from validated evidence".to_string()]
        }
        _ => vec!["keep research-only outcome audit".to_string()],
    };
    RealEvidenceOutcomeReadinessReport {
        readiness_id: format!("{}-outcome-readiness", config.followup_id),
        eligible_rows,
        complete_rows,
        outcome_links_possible,
        outcome_links_present,
        future_window_gap_count,
        barrier_profile_present,
        no_lookahead_safe,
        readiness_status,
        next_actions,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceOutcomeReadinessReportBuilt]),
    }
}

fn build_real_evidence_sequence_readiness_report(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
    validation: &KISRealEvidenceValidationReport,
    context: &Sprint74Context,
) -> RealEvidenceSequenceReadinessReport {
    let eligible_rows = validation.official_ready_rows;
    let estimated_windows = context
        .manifest_records
        .iter()
        .map(|record| record.estimated_windows.unwrap_or(0))
        .sum::<usize>();
    let feature_schema_match = !context.manifest_records.is_empty()
        && context
            .manifest_records
            .iter()
            .all(|record| record.feature_schema_match.unwrap_or(true));
    let label_manifest_match = !context.manifest_records.is_empty()
        && context
            .manifest_records
            .iter()
            .all(|record| record.label_manifest_match.unwrap_or(true));
    let no_lookahead_safe = attachment.records.iter().all(|record| {
        !matches!(record.source_class, RealEvidenceSourceClass::OfficialKIS)
            || record.no_lookahead_safe.unwrap_or(false)
    });
    let storage_within_budget = context
        .manifest_records
        .iter()
        .all(|record| record.storage_within_budget.unwrap_or(true))
        && attachment
            .records
            .iter()
            .map(|record| record.storage_bytes)
            .sum::<usize>()
            <= config.max_bytes;
    let readiness_status = if eligible_rows == 0 || estimated_windows == 0 {
        RealEvidenceSequenceReadinessStatus::NeedMoreRows
    } else if !feature_schema_match {
        RealEvidenceSequenceReadinessStatus::NeedFeatureSchema
    } else if !label_manifest_match {
        RealEvidenceSequenceReadinessStatus::NeedLabelManifest
    } else if config.require_no_lookahead_safe && !no_lookahead_safe {
        RealEvidenceSequenceReadinessStatus::NeedNoLookaheadProof
    } else if !storage_within_budget {
        RealEvidenceSequenceReadinessStatus::NeedStorageBudget
    } else if estimated_windows < 4 {
        RealEvidenceSequenceReadinessStatus::SequenceReadyWithWarnings
    } else {
        RealEvidenceSequenceReadinessStatus::SequenceReady
    };
    let next_actions = match readiness_status {
        RealEvidenceSequenceReadinessStatus::NeedMoreRows => {
            vec!["attach more validated rows before sequence export".to_string()]
        }
        RealEvidenceSequenceReadinessStatus::NeedFeatureSchema => {
            vec!["align feature schema manifest".to_string()]
        }
        RealEvidenceSequenceReadinessStatus::NeedLabelManifest => {
            vec!["align label manifest".to_string()]
        }
        RealEvidenceSequenceReadinessStatus::NeedNoLookaheadProof => {
            vec!["attach no-lookahead proof".to_string()]
        }
        RealEvidenceSequenceReadinessStatus::NeedStorageBudget => {
            vec!["reduce storage footprint before export".to_string()]
        }
        _ => vec!["keep sequence export research-only".to_string()],
    };
    RealEvidenceSequenceReadinessReport {
        readiness_id: format!("{}-sequence-readiness", config.followup_id),
        eligible_rows,
        estimated_windows,
        feature_schema_match,
        label_manifest_match,
        no_lookahead_safe,
        storage_within_budget,
        readiness_status,
        next_actions,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceSequenceReadinessReportBuilt]),
    }
}

fn build_real_evidence_model_ops_impact_report(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
    sequence: &RealEvidenceSequenceReadinessReport,
    context: &Sprint74Context,
) -> RealEvidenceModelOpsImpactReport {
    let evidence_rows_added = if context.model_ops_state.evidence_rows_added > 0 {
        context.model_ops_state.evidence_rows_added
    } else {
        attachment.total_rows
    };
    let sequence_windows_added = if context.model_ops_state.sequence_windows_added > 0 {
        context.model_ops_state.sequence_windows_added
    } else {
        sequence.estimated_windows
    };
    let models_requiring_new_predictions =
        stable_ordered_strings(&context.model_ops_state.models_requiring_new_predictions);
    let models_requiring_reevaluation =
        stable_ordered_strings(&context.model_ops_state.models_requiring_reevaluation);
    let impact_status = if evidence_rows_added == 0 {
        RealEvidenceModelOpsImpactStatus::NoModelOpsImpact
    } else if !models_requiring_new_predictions.is_empty() {
        RealEvidenceModelOpsImpactStatus::NeedNewPredictionCsv
    } else if !models_requiring_reevaluation.is_empty() {
        RealEvidenceModelOpsImpactStatus::NeedReevaluation
    } else if context
        .model_ops_state
        .existing_prediction_coverage_affected
    {
        RealEvidenceModelOpsImpactStatus::NeedLeaderboardRefresh
    } else {
        RealEvidenceModelOpsImpactStatus::NoModelOpsImpact
    };
    RealEvidenceModelOpsImpactReport {
        impact_id: format!("{}-model-ops-impact", config.followup_id),
        evidence_rows_added,
        sequence_windows_added,
        existing_prediction_coverage_affected: context
            .model_ops_state
            .existing_prediction_coverage_affected,
        models_requiring_new_predictions,
        models_requiring_reevaluation,
        impact_status,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceModelOpsImpactReportBuilt]),
    }
}

fn build_control_tower_warning_reduction_report(
    config: &RealEvidenceFollowupConfig,
    context: &Sprint74Context,
    attachment: &RealEvidenceAttachmentReport,
    provenance: &RealEvidenceProvenanceAudit,
    preflight: &RealEvidencePreflightAudit,
    outcome: &RealEvidenceOutcomeReadinessReport,
    sequence: &RealEvidenceSequenceReadinessReport,
    model_ops: &RealEvidenceModelOpsImpactReport,
) -> ControlTowerWarningReductionReport {
    let prior = context
        .briefing_state
        .warning_kinds
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let item = |warning_kind: ControlTowerWarningKind,
                after_present: bool,
                explanation: &str,
                next_action: Option<&str>| {
        let before_present = prior.contains(&warning_kind)
            || matches!(
                warning_kind,
                ControlTowerWarningKind::DirectWatchMonitoringOnly
                    | ControlTowerWarningKind::RuntimeMambaDeferred
                    | ControlTowerWarningKind::LiveTradingForbidden
                    | ControlTowerWarningKind::BrokerForbidden
            );
        ControlTowerWarningReductionItem {
            warning_kind,
            before_present,
            after_present,
            reduced: before_present && !after_present,
            explanation: explanation.to_string(),
            next_action: next_action.map(|value| value.to_string()),
            reason_codes: stable_reason_codes(&[ReasonCode::ControlTowerWarningReductionItemBuilt]),
        }
    };
    let items = vec![
        item(
            ControlTowerWarningKind::EvidenceFixtureOnly,
            !matches!(
                attachment.attachment_status,
                RealEvidenceAttachmentStatus::RealEvidenceAttached
                    | RealEvidenceAttachmentStatus::RealEvidenceAttachedWithWarnings
            ),
            "fixture-only warning is reduced only when local official evidence is attached",
            Some("attach local official KIS evidence"),
        ),
        item(
            ControlTowerWarningKind::RealEvidenceMissingProvenance,
            !matches!(
                provenance.audit_status,
                RealEvidenceProvenanceAuditStatus::ProvenanceReady
            ),
            "missing provenance remains visible until every official record has explicit source metadata",
            Some("run real-provenance-audit"),
        ),
        item(
            ControlTowerWarningKind::RealEvidenceMissingPreflight,
            !matches!(
                preflight.audit_status,
                RealEvidencePreflightAuditStatus::PreflightReady
            ),
            "missing preflight remains visible until validation preflight passes",
            Some("run real-preflight-audit"),
        ),
        item(
            ControlTowerWarningKind::OutcomeLinksMissing,
            !matches!(
                outcome.readiness_status,
                RealEvidenceOutcomeReadinessStatus::OutcomeReady
                    | RealEvidenceOutcomeReadinessStatus::OutcomeReadyWithWarnings
            ),
            "outcome-link warning is reduced only when conservative readiness is explicit",
            Some("run real-outcome-readiness"),
        ),
        item(
            ControlTowerWarningKind::SequenceRowsWeak,
            !matches!(
                sequence.readiness_status,
                RealEvidenceSequenceReadinessStatus::SequenceReady
                    | RealEvidenceSequenceReadinessStatus::SequenceReadyWithWarnings
            ),
            "sequence-row warning remains until sequence export prerequisites are visible",
            Some("run real-sequence-readiness"),
        ),
        item(
            ControlTowerWarningKind::ModelPredictionsStale,
            !matches!(
                model_ops.impact_status,
                RealEvidenceModelOpsImpactStatus::NoModelOpsImpact
            ),
            "new real evidence may make external predictions stale even when direct-watch remains monitoring-only",
            Some("run real-modelops-impact"),
        ),
        item(
            ControlTowerWarningKind::DirectWatchMonitoringOnly,
            true,
            "direct-watch remains monitoring-only and cannot imply execution permission",
            None,
        ),
        item(
            ControlTowerWarningKind::RuntimeMambaDeferred,
            true,
            "Mamba runtime remains deferred and warning reduction does not hide that deferment",
            None,
        ),
        item(
            ControlTowerWarningKind::LiveTradingForbidden,
            true,
            "live trading stays forbidden regardless of evidence attachment",
            None,
        ),
        item(
            ControlTowerWarningKind::BrokerForbidden,
            true,
            "broker/order/account paths remain forbidden regardless of follow-up evidence",
            None,
        ),
    ];
    let warnings_before = items.iter().filter(|item| item.before_present).count();
    let warnings_after = items.iter().filter(|item| item.after_present).count();
    let reduced_count = items.iter().filter(|item| item.reduced).count();
    let remaining_count = warnings_after;
    let reduction_status = if warnings_after == 0 {
        ControlTowerWarningReductionStatus::NoWarnings
    } else if reduced_count > 0 {
        ControlTowerWarningReductionStatus::WarningsReduced
    } else if items.iter().all(|item| !item.explanation.trim().is_empty()) {
        ControlTowerWarningReductionStatus::WarningsExplained
    } else {
        ControlTowerWarningReductionStatus::WarningsRemain
    };
    ControlTowerWarningReductionReport {
        report_id: format!("{}-warning-reduction", config.followup_id),
        items,
        warnings_before,
        warnings_after,
        reduced_count,
        remaining_count,
        reduction_status,
        reason_codes: stable_reason_codes(&[ReasonCode::ControlTowerWarningReductionReportBuilt]),
    }
}

fn build_direct_watch_warning_rationale_report(
    config: &RealEvidenceFollowupConfig,
    context: &Sprint74Context,
    warning_reduction: &ControlTowerWarningReductionReport,
    provenance: &RealEvidenceProvenanceAudit,
    preflight: &RealEvidencePreflightAudit,
    outcome: &RealEvidenceOutcomeReadinessReport,
    sequence: &RealEvidenceSequenceReadinessReport,
    model_ops: &RealEvidenceModelOpsImpactReport,
) -> DirectWatchWarningRationaleReport {
    let warning_rationales = warning_reduction
        .items
        .iter()
        .filter(|item| item.after_present)
        .map(|item| format!("{:?}: {}", item.warning_kind, item.explanation))
        .collect::<Vec<_>>();
    let mut evidence_limitations = Vec::new();
    if !matches!(
        provenance.audit_status,
        RealEvidenceProvenanceAuditStatus::ProvenanceReady
    ) {
        evidence_limitations.push(format!("provenance={:?}", provenance.audit_status));
    }
    if !matches!(
        preflight.audit_status,
        RealEvidencePreflightAuditStatus::PreflightReady
    ) {
        evidence_limitations.push(format!("preflight={:?}", preflight.audit_status));
    }
    if !matches!(
        outcome.readiness_status,
        RealEvidenceOutcomeReadinessStatus::OutcomeReady
            | RealEvidenceOutcomeReadinessStatus::OutcomeReadyWithWarnings
    ) {
        evidence_limitations.push(format!("outcome={:?}", outcome.readiness_status));
    }
    if !matches!(
        sequence.readiness_status,
        RealEvidenceSequenceReadinessStatus::SequenceReady
            | RealEvidenceSequenceReadinessStatus::SequenceReadyWithWarnings
    ) {
        evidence_limitations.push(format!("sequence={:?}", sequence.readiness_status));
    }
    if !matches!(
        model_ops.impact_status,
        RealEvidenceModelOpsImpactStatus::NoModelOpsImpact
    ) {
        evidence_limitations.push(format!("model_ops={:?}", model_ops.impact_status));
    }
    let next_actions = warning_reduction
        .items
        .iter()
        .filter(|item| item.after_present)
        .filter_map(|item| item.next_action.clone())
        .collect::<Vec<_>>();
    let rationale_status = if warning_rationales.is_empty() {
        DirectWatchWarningRationaleStatus::NeedsClearerWarnings
    } else if evidence_limitations.iter().any(|item| {
        item.starts_with("provenance=")
            || item.starts_with("preflight=")
            || item.starts_with("outcome=")
            || item.starts_with("sequence=")
    }) {
        DirectWatchWarningRationaleStatus::NeedsMoreEvidence
    } else {
        DirectWatchWarningRationaleStatus::RationaleReady
    };
    DirectWatchWarningRationaleReport {
        report_id: format!("{}-direct-watch-warning-rationale", config.followup_id),
        warning_rationales,
        monitoring_only_explanation: format!(
            "direct-watch remains monitoring-only even when gate={} and score={}~{}",
            context.final_gate.gate_status,
            context.final_gate.current_score_min,
            context.final_gate.current_score_max
        ),
        execution_forbidden_explanation:
            "execution stays forbidden: no broker/order/account path, no live trading, and no execution buttons"
                .to_string(),
        evidence_limitations: stable_ordered_strings(&evidence_limitations),
        next_actions: stable_ordered_strings(&next_actions),
        rationale_status,
        reason_codes: stable_reason_codes(&[ReasonCode::DirectWatchWarningRationaleReportBuilt]),
    }
}

fn build_real_evidence_operator_runbook(
    config: &RealEvidenceFollowupConfig,
    provenance: &RealEvidenceProvenanceAudit,
    preflight: &RealEvidencePreflightAudit,
    outcome: &RealEvidenceOutcomeReadinessReport,
    sequence: &RealEvidenceSequenceReadinessReport,
    model_ops: &RealEvidenceModelOpsImpactReport,
) -> RealEvidenceOperatorRunbook {
    let mut steps = vec![
        build_runbook_step(
            "attach",
            RealEvidenceRunbookStepKind::AttachLocalKISEvidence,
            Some(
                "cargo run --quiet --bin soma_experiment -- real-evidence-attach --config examples/soma_real_evidence_attach.toml",
            ),
            Some("real_evidence_attachment.txt"),
            true,
        ),
        build_runbook_step(
            "validate",
            RealEvidenceRunbookStepKind::ValidateKISEvidence,
            Some(
                "cargo run --quiet --bin soma_experiment -- kis-real-evidence-validate --config examples/soma_kis_real_evidence_validate.toml",
            ),
            Some("kis_real_evidence_validation.txt"),
            true,
        ),
        build_runbook_step(
            "provenance",
            RealEvidenceRunbookStepKind::RunProvenanceAudit,
            Some(
                "cargo run --quiet --bin soma_experiment -- real-provenance-audit --config examples/soma_real_provenance_audit.toml",
            ),
            Some("provenance_audit.txt"),
            true,
        ),
        build_runbook_step(
            "preflight",
            RealEvidenceRunbookStepKind::RunPreflightAudit,
            Some(
                "cargo run --quiet --bin soma_experiment -- real-preflight-audit --config examples/soma_real_preflight_audit.toml",
            ),
            Some("preflight_audit.txt"),
            !matches!(
                provenance.audit_status,
                RealEvidenceProvenanceAuditStatus::UnsafeRemoteSource
            ),
        ),
        build_runbook_step(
            "outcome",
            RealEvidenceRunbookStepKind::RunOutcomeReadiness,
            Some(
                "cargo run --quiet --bin soma_experiment -- real-outcome-readiness --config examples/soma_real_outcome_readiness.toml",
            ),
            Some("outcome_readiness.txt"),
            matches!(
                provenance.audit_status,
                RealEvidenceProvenanceAuditStatus::ProvenanceReady
            ) && matches!(
                preflight.audit_status,
                RealEvidencePreflightAuditStatus::PreflightReady
            ),
        ),
        build_runbook_step(
            "sequence",
            RealEvidenceRunbookStepKind::RunSequenceReadiness,
            Some(
                "cargo run --quiet --bin soma_experiment -- real-sequence-readiness --config examples/soma_real_sequence_readiness.toml",
            ),
            Some("sequence_readiness.txt"),
            matches!(
                provenance.audit_status,
                RealEvidenceProvenanceAuditStatus::ProvenanceReady
            ) && matches!(
                preflight.audit_status,
                RealEvidencePreflightAuditStatus::PreflightReady
            ),
        ),
        build_runbook_step(
            "modelops",
            RealEvidenceRunbookStepKind::RunModelOpsImpact,
            Some(
                "cargo run --quiet --bin soma_experiment -- real-modelops-impact --config examples/soma_real_modelops_impact.toml",
            ),
            Some("model_ops_impact.txt"),
            matches!(
                outcome.readiness_status,
                RealEvidenceOutcomeReadinessStatus::OutcomeReady
                    | RealEvidenceOutcomeReadinessStatus::OutcomeReadyWithWarnings
            ) && matches!(
                sequence.readiness_status,
                RealEvidenceSequenceReadinessStatus::SequenceReady
                    | RealEvidenceSequenceReadinessStatus::SequenceReadyWithWarnings
            ),
        ),
        build_runbook_step(
            "refresh",
            RealEvidenceRunbookStepKind::RefreshControlTower,
            Some(
                "cargo run --quiet --bin soma_experiment -- control-tower-warning-reduce --config examples/soma_control_tower_warning_reduce.toml",
            ),
            Some("control_tower_warning_reduction.txt"),
            true,
        ),
        build_runbook_step(
            "briefing",
            RealEvidenceRunbookStepKind::UpdateBriefing,
            Some(
                "cargo run --quiet --bin soma_experiment -- real-evidence-followup --config examples/soma_real_evidence_followup.toml",
            ),
            Some("summary.txt"),
            true,
        ),
    ];
    let mut blocked_steps = Vec::new();
    let runbook_status = if matches!(
        provenance.audit_status,
        RealEvidenceProvenanceAuditStatus::UnsafeRemoteSource
    ) {
        steps.push(build_runbook_step(
            "stop-unsafe-source",
            RealEvidenceRunbookStepKind::StopDueToUnsafeSource,
            None,
            None,
            false,
        ));
        blocked_steps.push("stop-unsafe-source".to_string());
        RealEvidenceOperatorRunbookStatus::BlockedByUnsafeSource
    } else if matches!(
        provenance.audit_status,
        RealEvidenceProvenanceAuditStatus::MissingProvenance
    ) {
        steps.push(build_runbook_step(
            "stop-missing-provenance",
            RealEvidenceRunbookStepKind::StopDueToMissingProvenance,
            None,
            None,
            false,
        ));
        blocked_steps.push("stop-missing-provenance".to_string());
        RealEvidenceOperatorRunbookStatus::BlockedByProvenance
    } else if matches!(
        preflight.audit_status,
        RealEvidencePreflightAuditStatus::MissingPreflight
            | RealEvidencePreflightAuditStatus::PreflightFailed
    ) {
        steps.push(build_runbook_step(
            "stop-missing-preflight",
            RealEvidenceRunbookStepKind::StopDueToMissingPreflight,
            None,
            None,
            false,
        ));
        blocked_steps.push("stop-missing-preflight".to_string());
        RealEvidenceOperatorRunbookStatus::BlockedByPreflight
    } else {
        RealEvidenceOperatorRunbookStatus::RunbookReady
    };
    let primary_next_step = if !blocked_steps.is_empty() {
        blocked_steps[0].clone()
    } else if !matches!(
        model_ops.impact_status,
        RealEvidenceModelOpsImpactStatus::NoModelOpsImpact
    ) {
        "modelops".to_string()
    } else {
        "refresh".to_string()
    };
    RealEvidenceOperatorRunbook {
        runbook_id: format!("{}-runbook", config.followup_id),
        steps,
        primary_next_step,
        blocked_steps,
        runbook_status,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceOperatorRunbookBuilt]),
    }
}

fn build_runbook_step(
    step_id: &str,
    step_kind: RealEvidenceRunbookStepKind,
    command_suggestion: Option<&str>,
    expected_artifact: Option<&str>,
    safe_to_run: bool,
) -> RealEvidenceRunbookStep {
    RealEvidenceRunbookStep {
        step_id: step_id.to_string(),
        step_kind,
        command_suggestion: command_suggestion.map(|value| value.to_string()),
        expected_artifact: expected_artifact.map(|value| value.to_string()),
        safe_to_run,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceRunbookStepBuilt]),
    }
}

fn build_control_tower_real_evidence_refresh(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
    validation: &KISRealEvidenceValidationReport,
    provenance: &RealEvidenceProvenanceAudit,
    preflight: &RealEvidencePreflightAudit,
    outcome: &RealEvidenceOutcomeReadinessReport,
    sequence: &RealEvidenceSequenceReadinessReport,
    model_ops: &RealEvidenceModelOpsImpactReport,
    warning_reduction: &ControlTowerWarningReductionReport,
    rationale: &DirectWatchWarningRationaleReport,
) -> ControlTowerRealEvidenceRefresh {
    let refresh_status = if matches!(
        provenance.audit_status,
        RealEvidenceProvenanceAuditStatus::MissingProvenance
            | RealEvidenceProvenanceAuditStatus::UnsafeRemoteSource
    ) {
        ControlTowerRealEvidenceRefreshStatus::MissingProvenance
    } else if matches!(
        preflight.audit_status,
        RealEvidencePreflightAuditStatus::MissingPreflight
            | RealEvidencePreflightAuditStatus::PreflightFailed
    ) {
        ControlTowerRealEvidenceRefreshStatus::MissingPreflight
    } else if !matches!(
        outcome.readiness_status,
        RealEvidenceOutcomeReadinessStatus::OutcomeReady
            | RealEvidenceOutcomeReadinessStatus::OutcomeReadyWithWarnings
    ) || !matches!(
        sequence.readiness_status,
        RealEvidenceSequenceReadinessStatus::SequenceReady
            | RealEvidenceSequenceReadinessStatus::SequenceReadyWithWarnings
    ) {
        ControlTowerRealEvidenceRefreshStatus::NeedsMoreRealEvidence
    } else if warning_reduction.remaining_count == 0 {
        ControlTowerRealEvidenceRefreshStatus::RealEvidenceRefreshReady
    } else {
        ControlTowerRealEvidenceRefreshStatus::RealEvidenceRefreshReadyWithWarnings
    };
    ControlTowerRealEvidenceRefresh {
        refresh_id: format!("{}-control-tower-real-evidence-refresh", config.followup_id),
        real_evidence_attachment_status: format!("{:?}", attachment.attachment_status),
        kis_validation_status: format!("{:?}", validation.validation_status),
        provenance_status: format!("{:?}", provenance.audit_status),
        preflight_status: format!("{:?}", preflight.audit_status),
        outcome_readiness_status: format!("{:?}", outcome.readiness_status),
        sequence_readiness_status: format!("{:?}", sequence.readiness_status),
        model_ops_impact_status: format!("{:?}", model_ops.impact_status),
        warning_reduction_status: format!("{:?}", warning_reduction.reduction_status),
        direct_watch_rationale_status: format!("{:?}", rationale.rationale_status),
        briefing_state_path: None,
        dashboard_html_path: None,
        refresh_status,
        reason_codes: stable_reason_codes(&[ReasonCode::ControlTowerRealEvidenceRefreshBuilt]),
    }
}

fn write_real_evidence_followup_bundle(
    config: &RealEvidenceFollowupConfig,
    attachment: &RealEvidenceAttachmentReport,
    import_plan: &KISRealEvidenceImportPlan,
    validation: &KISRealEvidenceValidationReport,
    provenance: &RealEvidenceProvenanceAudit,
    preflight: &RealEvidencePreflightAudit,
    outcome: &RealEvidenceOutcomeReadinessReport,
    sequence: &RealEvidenceSequenceReadinessReport,
    model_ops: &RealEvidenceModelOpsImpactReport,
    warning_reduction: &ControlTowerWarningReductionReport,
    rationale: &DirectWatchWarningRationaleReport,
    runbook: &RealEvidenceOperatorRunbook,
    refresh: &ControlTowerRealEvidenceRefresh,
) -> Result<(OperatorBriefingStorageReport, String), String> {
    let dir = config.output_dir();
    fs::create_dir_all(&dir).map_err(|err| err.to_string())?;
    let files = BTreeMap::from([
        (
            "real_evidence_attachment.txt".to_string(),
            serde_json::to_string_pretty(attachment).map_err(|err| err.to_string())?,
        ),
        (
            "kis_real_evidence_import_plan.txt".to_string(),
            serde_json::to_string_pretty(import_plan).map_err(|err| err.to_string())?,
        ),
        (
            "kis_real_evidence_validation.txt".to_string(),
            serde_json::to_string_pretty(validation).map_err(|err| err.to_string())?,
        ),
        (
            "provenance_audit.txt".to_string(),
            serde_json::to_string_pretty(provenance).map_err(|err| err.to_string())?,
        ),
        (
            "preflight_audit.txt".to_string(),
            serde_json::to_string_pretty(preflight).map_err(|err| err.to_string())?,
        ),
        (
            "outcome_readiness.txt".to_string(),
            serde_json::to_string_pretty(outcome).map_err(|err| err.to_string())?,
        ),
        (
            "sequence_readiness.txt".to_string(),
            serde_json::to_string_pretty(sequence).map_err(|err| err.to_string())?,
        ),
        (
            "model_ops_impact.txt".to_string(),
            serde_json::to_string_pretty(model_ops).map_err(|err| err.to_string())?,
        ),
        (
            "control_tower_warning_reduction.txt".to_string(),
            serde_json::to_string_pretty(warning_reduction).map_err(|err| err.to_string())?,
        ),
        (
            "direct_watch_warning_rationale.txt".to_string(),
            serde_json::to_string_pretty(rationale).map_err(|err| err.to_string())?,
        ),
        (
            "real_evidence_runbook.txt".to_string(),
            serde_json::to_string_pretty(runbook).map_err(|err| err.to_string())?,
        ),
        (
            "control_tower_real_evidence_refresh.txt".to_string(),
            serde_json::to_string_pretty(refresh).map_err(|err| err.to_string())?,
        ),
    ]);
    for (name, text) in &files {
        fs::write(dir.join(name), text).map_err(|err| err.to_string())?;
    }
    let final_summary = build_real_evidence_final_summary(
        attachment,
        validation,
        provenance,
        preflight,
        outcome,
        sequence,
        model_ops,
        warning_reduction,
        rationale,
        refresh,
    );
    fs::write(dir.join("summary.txt"), &final_summary).map_err(|err| err.to_string())?;
    let mut artifact_count = files.len() + 1;
    let mut storage_bytes = final_summary.len();
    for text in files.values() {
        storage_bytes += text.len();
    }
    let storage_report = OperatorBriefingStorageReport {
        artifact_count,
        storage_bytes,
        max_bytes: config.max_bytes,
        within_budget: storage_bytes <= config.max_bytes,
        reason_codes: stable_reason_codes(&[ReasonCode::RealEvidenceFollowupStorageBuilt]),
    };
    fs::write(
        dir.join("storage_report.txt"),
        serde_json::to_string_pretty(&storage_report).map_err(|err| err.to_string())?,
    )
    .map_err(|err| err.to_string())?;
    artifact_count += 1;
    let storage_report = OperatorBriefingStorageReport {
        artifact_count,
        ..storage_report
    };
    Ok((storage_report, final_summary))
}

fn build_real_evidence_final_summary(
    attachment: &RealEvidenceAttachmentReport,
    validation: &KISRealEvidenceValidationReport,
    provenance: &RealEvidenceProvenanceAudit,
    preflight: &RealEvidencePreflightAudit,
    outcome: &RealEvidenceOutcomeReadinessReport,
    sequence: &RealEvidenceSequenceReadinessReport,
    model_ops: &RealEvidenceModelOpsImpactReport,
    warning_reduction: &ControlTowerWarningReductionReport,
    rationale: &DirectWatchWarningRationaleReport,
    refresh: &ControlTowerRealEvidenceRefresh,
) -> String {
    let mut recommendations = Vec::new();
    if matches!(
        attachment.attachment_status,
        RealEvidenceAttachmentStatus::RealEvidenceAttached
            | RealEvidenceAttachmentStatus::RealEvidenceAttachedWithWarnings
    ) {
        recommendations.push("RealEvidenceAttached".to_string());
    }
    if matches!(
        validation.validation_status,
        KISRealEvidenceValidationStatus::ValidationReady
            | KISRealEvidenceValidationStatus::ValidationReadyWithWarnings
    ) {
        recommendations.push("RealEvidenceValidated".to_string());
    }
    if matches!(
        provenance.audit_status,
        RealEvidenceProvenanceAuditStatus::MissingProvenance
    ) {
        recommendations.push("RealEvidenceNeedsProvenance".to_string());
    }
    if matches!(
        preflight.audit_status,
        RealEvidencePreflightAuditStatus::MissingPreflight
    ) {
        recommendations.push("RealEvidenceNeedsPreflight".to_string());
    }
    if matches!(
        outcome.readiness_status,
        RealEvidenceOutcomeReadinessStatus::OutcomeReady
            | RealEvidenceOutcomeReadinessStatus::OutcomeReadyWithWarnings
    ) {
        recommendations.push("RealEvidenceOutcomeReady".to_string());
    } else {
        recommendations.push("RealEvidenceNeedsOutcomeLinks".to_string());
    }
    if matches!(
        sequence.readiness_status,
        RealEvidenceSequenceReadinessStatus::SequenceReady
            | RealEvidenceSequenceReadinessStatus::SequenceReadyWithWarnings
    ) {
        recommendations.push("RealEvidenceSequenceReady".to_string());
    } else {
        recommendations.push("RealEvidenceNeedsMoreRows".to_string());
    }
    if matches!(
        warning_reduction.reduction_status,
        ControlTowerWarningReductionStatus::WarningsReduced
    ) {
        recommendations.push("ControlTowerWarningsReduced".to_string());
    }
    if matches!(
        rationale.rationale_status,
        DirectWatchWarningRationaleStatus::RationaleReady
    ) {
        recommendations.push("DirectWatchWarningsExplained".to_string());
    }
    recommendations.push("DirectWatchReadyWithWarnings".to_string());
    recommendations.push("KeepResearchOnly".to_string());
    recommendations.push("KeepPaperOnly".to_string());
    recommendations.push("KeepStaticDashboardNow".to_string());
    recommendations.push("KeepTrinity".to_string());
    recommendations.push("HoldMamba3RuntimeDeferred".to_string());
    recommendations.push("NeedMoreRealEvidence".to_string());
    format!(
        "real_evidence_status={:?}\nkis_validation_status={:?}\nprovenance_status={:?}\npreflight_status={:?}\noutcome_status={:?}\nsequence_status={:?}\nmodel_ops_status={:?}\nwarning_reduction_status={:?}\ndirect_watch_warning_status={:?}\ncontrol_tower_refresh_status={:?}\nrecommendations={}",
        attachment.attachment_status,
        validation.validation_status,
        provenance.audit_status,
        preflight.audit_status,
        outcome.readiness_status,
        sequence.readiness_status,
        model_ops.impact_status,
        warning_reduction.reduction_status,
        rationale.rationale_status,
        refresh.refresh_status,
        stable_ordered_strings(&recommendations).join(" | "),
    )
}

fn find_manifest_record<'a>(
    records: &'a [Sprint74ManifestRecordInput],
    path: &str,
) -> Option<&'a Sprint74ManifestRecordInput> {
    records
        .iter()
        .find(|record| paths_match(&record.local_path, path))
}

fn find_provenance_record<'a>(
    records: &'a [Sprint74ProvenanceRecordInput],
    path: &str,
) -> Option<&'a Sprint74ProvenanceRecordInput> {
    records
        .iter()
        .find(|record| paths_match(&record.local_path, path))
}

fn find_preflight_record<'a>(
    records: &'a [Sprint74PreflightRecordInput],
    path: &str,
) -> Option<&'a Sprint74PreflightRecordInput> {
    records
        .iter()
        .find(|record| paths_match(&record.local_path, path))
}

fn paths_match(left: &str, right: &str) -> bool {
    left == right
        || Path::new(left)
            .file_name()
            .zip(Path::new(right).file_name())
            .is_some_and(|(left, right)| left == right)
}

