#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct RustToolchainModernizationConfig {
    pub modernization_id: String,
    #[serde(default)]
    pub current_toolchain_report_paths: Vec<String>,
    #[serde(default = "default_rust_toolchain_speed_output_root")]
    pub output_root: String,
    #[serde(default = "default_rust_toolchain_channel")]
    pub target_channel: RustToolchainChannel,
    #[serde(default = "default_true")]
    pub require_latest_stable: bool,
    #[serde(default = "default_false")]
    pub allow_nightly: bool,
    #[serde(default = "default_true")]
    pub write_rust_toolchain_toml: bool,
    #[serde(default = "default_true")]
    pub pin_exact_version: bool,
    #[serde(default = "default_true")]
    pub audit_cargo_workspace: bool,
    #[serde(default = "default_true")]
    pub audit_profiles: bool,
    #[serde(default = "default_true")]
    pub audit_test_tiers: bool,
    #[serde(default = "default_false")]
    pub run_performance_baseline: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for RustToolchainModernizationConfig {
    fn default() -> Self {
        Self {
            modernization_id: "sprint76-rust-toolchain-modernization".to_string(),
            current_toolchain_report_paths: Vec::new(),
            output_root: default_rust_toolchain_speed_output_root(),
            target_channel: default_rust_toolchain_channel(),
            require_latest_stable: true,
            allow_nightly: false,
            write_rust_toolchain_toml: true,
            pin_exact_version: true,
            audit_cargo_workspace: true,
            audit_profiles: true,
            audit_test_tiers: true,
            run_performance_baseline: false,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl RustToolchainModernizationConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.modernization_id.trim().is_empty() {
            return Err(
                "rust toolchain modernization config requires modernization_id".to_string(),
            );
        }
        if !path_is_local(&self.output_root) {
            return Err("rust toolchain modernization output_root must be local".to_string());
        }
        if !matches!(self.target_channel, RustToolchainChannel::Stable) {
            return Err("rust toolchain modernization target_channel must be stable".to_string());
        }
        if self.allow_nightly {
            return Err("rust toolchain modernization does not allow nightly".to_string());
        }
        for path in &self.current_toolchain_report_paths {
            if !path_is_local(path) {
                return Err("rust toolchain modernization support paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(path);
            if !absolute.exists() {
                return Err(format!(
                    "rust toolchain modernization support path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.output_root).join(&self.modernization_id)
    }
}

