pub fn build_test_runtime_budget_report(
    config: &TestRuntimeBudgetConfig,
    reports: &[TestTierRunnerReport],
) -> TestRuntimeBudgetReport {
    let actual_quick_ms = runtime_for_tier(reports, TestTierKind::Quick);
    let actual_sprint_ms = runtime_for_tier(reports, TestTierKind::Sprint);
    let actual_full_ms = runtime_for_tier(reports, TestTierKind::Full);
    let actual_smoke_ms = runtime_for_tier(reports, TestTierKind::Smoke);
    let actual_audit_ms = runtime_for_tier(reports, TestTierKind::Audit);
    let mut over_budget_tiers = Vec::new();
    for (name, actual, budget) in [
        ("quick", actual_quick_ms, config.quick_budget_ms),
        ("sprint", actual_sprint_ms, config.sprint_budget_ms),
        ("full", actual_full_ms, config.full_budget_ms),
        ("smoke", actual_smoke_ms, config.smoke_budget_ms),
        ("audit", actual_audit_ms, config.audit_budget_ms),
    ] {
        if actual.is_some_and(|value| value > budget) {
            over_budget_tiers.push(name.to_string());
        }
    }
    let budget_status = if actual_quick_ms.is_none()
        && actual_sprint_ms.is_none()
        && actual_full_ms.is_none()
        && actual_smoke_ms.is_none()
        && actual_audit_ms.is_none()
    {
        TestRuntimeBudgetStatus::MissingTiming
    } else if !over_budget_tiers.is_empty() {
        TestRuntimeBudgetStatus::OverBudget
    } else {
        TestRuntimeBudgetStatus::WithinBudget
    };
    TestRuntimeBudgetReport {
        budget_id: config.budget_id.clone(),
        actual_quick_ms,
        actual_sprint_ms,
        actual_full_ms,
        actual_smoke_ms,
        actual_audit_ms,
        over_budget_tiers,
        budget_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TestRuntimeBudgetReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

pub fn build_optional_nextest_plan(nextest_available: bool) -> OptionalNextestPlan {
    OptionalNextestPlan {
        nextest_available,
        recommended: true,
        install_command: (!nextest_available).then(|| "cargo install cargo-nextest".to_string()),
        sample_commands: if nextest_available {
            vec![
                "cargo nextest run --workspace --status-level fail".to_string(),
                "cargo nextest run --test rust_toolchain_modernization".to_string(),
            ]
        } else {
            vec!["cargo nextest run --workspace --status-level fail".to_string()]
        },
        fallback_cargo_test_commands: vec![
            "cargo test --workspace --quiet".to_string(),
            "cargo test --quiet --test rust_toolchain_modernization -- --test-threads=1"
                .to_string(),
        ],
        plan_status: if nextest_available {
            OptionalNextestPlanStatus::NextestReady
        } else {
            OptionalNextestPlanStatus::NextestRecommended
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::OptionalNextestPlanBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

pub fn build_optional_sccache_plan(sccache_available: bool) -> OptionalSccachePlan {
    OptionalSccachePlan {
        sccache_available,
        recommended: true,
        local_cache_only: true,
        sample_env: vec![
            "RUSTC_WRAPPER=sccache".to_string(),
            "SCCACHE_DIR=target/sccache".to_string(),
        ],
        fallback_without_sccache: vec![
            "cargo check --workspace".to_string(),
            "cargo test --workspace --quiet".to_string(),
        ],
        plan_status: if sccache_available {
            OptionalSccachePlanStatus::SccacheReady
        } else {
            OptionalSccachePlanStatus::SccacheRecommended
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::OptionalSccachePlanBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

pub fn build_developer_speed_runbook(
    runbook_id: &str,
    tier_config: &TestTierConfig,
    nextest_plan: &OptionalNextestPlan,
    sccache_plan: &OptionalSccachePlan,
) -> DeveloperSpeedRunbook {
    DeveloperSpeedRunbook {
        runbook_id: runbook_id.to_string(),
        dev_loop_commands: vec![
            "cargo check --workspace".to_string(),
            "cargo test --test rust_toolchain_modernization --quiet".to_string(),
            "cargo run --quiet --bin soma_experiment -- toolchain-version-report --config examples/soma_toolchain_version_report.toml".to_string(),
        ],
        sprint_loop_commands: tier_config
            .sprint_commands
            .iter()
            .map(|command| command.command.clone())
            .collect(),
        full_acceptance_commands: tier_config
            .full_commands
            .iter()
            .map(|command| command.command.clone())
            .collect(),
        cache_setup_commands: sccache_plan.recommended.then(|| sccache_plan.sample_env.clone()),
        nextest_commands: nextest_plan.recommended.then(|| nextest_plan.sample_commands.clone()),
        when_to_run_full_workspace:
            "Run the full workspace before shipping, after cross-cutting changes, and whenever quick/sprint tiers stop matching expected behavior.".to_string(),
        when_to_run_audit:
            "Run the audit tier whenever safety-sensitive CLI, determinism, or absence guarantees might have changed.".to_string(),
        runbook_status: if nextest_plan.nextest_available || sccache_plan.sccache_available {
            DeveloperSpeedRunbookStatus::RunbookReady
        } else {
            DeveloperSpeedRunbookStatus::RunbookReadyWithWarnings
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeveloperSpeedRunbookBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

pub fn build_workspace_acceptance_v2_report(
    report_id: &str,
    toolchain_status: ToolchainVersionStatus,
    reports: &[TestTierRunnerReport],
) -> WorkspaceAcceptanceV2Report {
    let quick_tier_status = tier_status(reports, TestTierKind::Quick);
    let sprint_tier_status = tier_status(reports, TestTierKind::Sprint);
    let full_tier_status =
        tier_status(reports, TestTierKind::Full).unwrap_or(TestTierStatus::TierNotRun);
    let smoke_status =
        tier_status(reports, TestTierKind::Smoke).unwrap_or(TestTierStatus::TierNotRun);
    let audit_status =
        tier_status(reports, TestTierKind::Audit).unwrap_or(TestTierStatus::TierNotRun);
    let full_workspace_test_passed = matches!(
        full_tier_status,
        TestTierStatus::TierPassed | TestTierStatus::TierPassedWithWarnings
    );
    let acceptance_status = if quick_tier_status.is_none()
        && sprint_tier_status.is_none()
        && matches!(full_tier_status, TestTierStatus::TierNotRun)
        && matches!(smoke_status, TestTierStatus::TierNotRun)
        && matches!(audit_status, TestTierStatus::TierNotRun)
    {
        WorkspaceAcceptanceV2Status::NotRun
    } else if matches!(full_tier_status, TestTierStatus::TierFailed)
        || matches!(smoke_status, TestTierStatus::TierFailed)
        || matches!(audit_status, TestTierStatus::TierFailed)
        || matches!(
            toolchain_status,
            ToolchainVersionStatus::ToolchainCheckFailed
        )
    {
        WorkspaceAcceptanceV2Status::Failed
    } else if full_workspace_test_passed
        && matches!(
            smoke_status,
            TestTierStatus::TierPassed | TestTierStatus::TierPassedWithWarnings
        )
        && matches!(
            audit_status,
            TestTierStatus::TierPassed | TestTierStatus::TierPassedWithWarnings
        )
    {
        if matches!(
            toolchain_status,
            ToolchainVersionStatus::LatestStablePinned | ToolchainVersionStatus::StablePinned
        ) && !matches!(full_tier_status, TestTierStatus::TierPassedWithWarnings)
        {
            WorkspaceAcceptanceV2Status::FullWorkspaceAccepted
        } else {
            WorkspaceAcceptanceV2Status::FullWorkspaceAcceptedWithWarnings
        }
    } else if matches!(
        sprint_tier_status,
        Some(TestTierStatus::TierPassed | TestTierStatus::TierPassedWithWarnings)
    ) && matches!(full_tier_status, TestTierStatus::TierNotRun)
        && matches!(
            smoke_status,
            TestTierStatus::TierPassed | TestTierStatus::TierPassedWithWarnings
        )
        && matches!(
            audit_status,
            TestTierStatus::TierPassed | TestTierStatus::TierPassedWithWarnings
        )
    {
        WorkspaceAcceptanceV2Status::TieredAcceptanceReady
    } else if matches!(
        quick_tier_status,
        Some(TestTierStatus::TierPassed | TestTierStatus::TierPassedWithWarnings)
    ) || matches!(
        sprint_tier_status,
        Some(TestTierStatus::TierPassed | TestTierStatus::TierPassedWithWarnings)
    ) {
        WorkspaceAcceptanceV2Status::FocusedOnly
    } else {
        WorkspaceAcceptanceV2Status::Failed
    };
    WorkspaceAcceptanceV2Report {
        report_id: report_id.to_string(),
        toolchain_status,
        quick_tier_status,
        sprint_tier_status,
        full_tier_status,
        smoke_status,
        audit_status,
        full_workspace_test_passed,
        acceptance_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::WorkspaceAcceptanceV2ReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn default_false() -> bool {
    false
}

fn default_sprint76_reason_codes() -> Vec<ReasonCode> {
    stable_reason_codes(&[ReasonCode::DeterministicPath, ReasonCode::LocalFileOnly])
}

fn path_is_local(path: &str) -> bool {
    !path.contains("://")
}

fn repo_relative_display_path(path: &str) -> String {
    if !path_is_local(path) {
        return path.to_string();
    }
    let absolute = sprint76_absolutize(path);
    let repo_root = Path::new(env!("CARGO_MANIFEST_DIR"));
    absolute
        .strip_prefix(repo_root)
        .map(|relative| relative.to_string_lossy().into_owned())
        .unwrap_or_else(|_| path.to_string())
}

fn sprint76_absolutize(path: &str) -> PathBuf {
    let candidate = Path::new(path);
    if candidate.is_absolute() {
        candidate.to_path_buf()
    } else {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(candidate)
    }
}

fn repo_local_path(path: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(path)
}

fn load_sprint76_support_data(paths: &[String]) -> Result<Sprint76SupportData, String> {
    let mut support = Sprint76SupportData::default();
    for path in paths {
        let text = fs::read_to_string(sprint76_absolutize(path)).map_err(|err| err.to_string())?;
        let parsed: Sprint76SupportInput =
            serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if parsed.previous_rustc_version.is_some() {
            support.previous_rustc_version = parsed.previous_rustc_version;
        }
        if parsed.previous_cargo_version.is_some() {
            support.previous_cargo_version = parsed.previous_cargo_version;
        }
        if parsed.previous_rustup_version.is_some() {
            support.previous_rustup_version = parsed.previous_rustup_version;
        }
        if parsed.baseline.is_some() {
            support.baseline = parsed
                .baseline
                .map(normalize_build_test_performance_baseline_report);
        }
        if let Some(mut reports) = parsed.tier_reports {
            reports.sort_by_key(|report| report.tier);
            support.tier_reports = reports;
        }
        if parsed.slow_inventory.is_some() {
            support.slow_inventory = parsed.slow_inventory.map(normalize_slow_test_inventory);
        }
        if parsed.heavy_fixture_inventory.is_some() {
            support.heavy_fixture_inventory = parsed
                .heavy_fixture_inventory
                .map(normalize_heavy_fixture_inventory);
        }
        if parsed.cli_smoke_tiering.is_some() {
            support.cli_smoke_tiering = parsed
                .cli_smoke_tiering
                .map(normalize_cli_smoke_tiering_report);
        }
    }
    Ok(support)
}

fn command_version(program: &str, args: &[&str]) -> Result<Option<String>, String> {
    let output = Command::new(program).args(args).output();
    match output {
        Ok(output) if output.status.success() => Ok(parse_version_token(&String::from_utf8_lossy(
            &output.stdout,
        ))),
        Ok(_) => Ok(None),
        Err(err) => {
            if err.kind() == std::io::ErrorKind::NotFound {
                Ok(None)
            } else {
                Err(err.to_string())
            }
        }
    }
}

fn command_version_optional(program: &str, args: &[&str]) -> Result<Option<String>, String> {
    command_version(program, args)
}

fn parse_version_token(text: &str) -> Option<String> {
    text.split_whitespace()
        .nth(1)
        .map(|value| value.to_string())
}

fn collect_cargo_manifest_paths(root: &Path) -> Result<Vec<PathBuf>, String> {
    fn visit(dir: &Path, out: &mut Vec<PathBuf>) -> Result<(), String> {
        for entry in fs::read_dir(dir).map_err(|err| err.to_string())? {
            let entry = entry.map_err(|err| err.to_string())?;
            let path = entry.path();
            if path.file_name().is_some_and(|name| name == "target") {
                continue;
            }
            if path.is_dir() {
                visit(&path, out)?;
            } else if path.file_name().is_some_and(|name| name == "Cargo.toml") {
                out.push(path);
            }
        }
        Ok(())
    }

    let mut manifests = Vec::new();
    visit(root, &mut manifests)?;
    manifests.sort();
    Ok(manifests)
}

fn build_cargo_workspace_audit_report(
    cargo_toml: &toml::Value,
    manifest_paths: &[PathBuf],
    audit_profiles: bool,
) -> CargoWorkspaceAuditReport {
    let workspace_resolver = cargo_toml
        .get("workspace")
        .and_then(|workspace| workspace.get("resolver"))
        .and_then(|value| value.as_str())
        .unwrap_or("missing")
        .to_string();
    let editions = manifest_paths
        .iter()
        .filter_map(|path| {
            let text = fs::read_to_string(path).ok()?;
            let value: toml::Value = toml::from_str(&text).ok()?;
            Some(
                value
                    .get("package")
                    .and_then(|package| package.get("edition"))
                    .and_then(|value| value.as_str())
                    .unwrap_or("unknown")
                    .to_string(),
            )
        })
        .collect::<Vec<_>>();
    let mut edition_counts = BTreeMap::new();
    for edition in editions {
        *edition_counts.entry(edition).or_insert(0usize) += 1;
    }
    let edition_summary = edition_counts
        .into_iter()
        .map(|(edition, count)| format!("{edition} x{count}"))
        .collect::<Vec<_>>()
        .join(", ");
    let member_count = cargo_toml
        .get("workspace")
        .and_then(|workspace| workspace.get("members"))
        .and_then(|value| value.as_array())
        .map(|members| members.len().max(1))
        .unwrap_or(1);
    let crate_count = manifest_paths.len();
    let binary_count = cargo_toml
        .get("bin")
        .and_then(|value| value.as_array())
        .map(|bins| bins.len())
        .unwrap_or_else(|| usize::from(repo_local_path("src/main.rs").exists()));
    let dev_dependency_summary = stable_ordered_strings(
        &cargo_toml
            .get("dev-dependencies")
            .and_then(|value| value.as_table())
            .map(|table| table.keys().cloned().collect::<Vec<_>>())
            .unwrap_or_else(|| vec!["none".to_string()]),
    );
    let dependency_names = cargo_toml
        .get("dependencies")
        .and_then(|value| value.as_table())
        .map(|table| table.keys().cloned().collect::<Vec<_>>())
        .unwrap_or_default();
    let heavy_dependency_candidates = stable_ordered_strings(
        &dependency_names
            .into_iter()
            .filter(|name| {
                matches!(
                    name.as_str(),
                    "tokio" | "reqwest" | "tauri" | "polars" | "criterion"
                )
            })
            .collect::<Vec<_>>(),
    );
    let profile_dev_summary =
        profile_summary(cargo_toml.get("profile").and_then(|value| value.get("dev")));
    let profile_test_summary = profile_summary(
        cargo_toml
            .get("profile")
            .and_then(|value| value.get("test")),
    );
    let profile_bench_summary = profile_summary(
        cargo_toml
            .get("profile")
            .and_then(|value| value.get("bench")),
    );
    let audit_status = if workspace_resolver == "missing" {
        CargoWorkspaceAuditStatus::NeedsResolverUpdate
    } else if audit_profiles
        && (!profile_dev_summary.contains("incremental=true")
            || !profile_test_summary.contains("lto=false"))
    {
        CargoWorkspaceAuditStatus::NeedsProfileTuning
    } else if !heavy_dependency_candidates.is_empty() {
        CargoWorkspaceAuditStatus::HeavyDepsDetected
    } else {
        CargoWorkspaceAuditStatus::WorkspaceAuditReady
    };
    CargoWorkspaceAuditReport {
        workspace_resolver,
        edition_summary,
        member_count,
        crate_count,
        binary_count,
        dev_dependency_summary,
        heavy_dependency_candidates,
        profile_dev_summary,
        profile_test_summary,
        profile_bench_summary,
        audit_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CargoWorkspaceAuditReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn profile_summary(value: Option<&toml::Value>) -> String {
    if let Some(table) = value.and_then(|value| value.as_table()) {
        let incremental = table
            .get("incremental")
            .and_then(|value| value.as_bool())
            .unwrap_or(false);
        let lto = table
            .get("lto")
            .and_then(|value| value.as_bool())
            .unwrap_or(false);
        let codegen_units = table
            .get("codegen-units")
            .and_then(|value| value.as_integer())
            .unwrap_or(0);
        let debug = table
            .get("debug")
            .map(|value| value.to_string())
            .unwrap_or_else(|| "default".to_string());
        return format!(
            "incremental={incremental}, lto={lto}, codegen-units={codegen_units}, debug={debug}"
        );
    }
    "incremental=default, lto=default, codegen-units=default, debug=default".to_string()
}

fn build_test_performance_baseline_config(
    config: &RustToolchainModernizationConfig,
) -> BuildTestPerformanceBaselineConfig {
    BuildTestPerformanceBaselineConfig {
        baseline_id: format!("{}-baseline", config.modernization_id),
        commands: vec![
            "cargo fmt --all".to_string(),
            "cargo check --workspace".to_string(),
            "cargo test --workspace --quiet".to_string(),
            "focused Sprint 76 tests".to_string(),
            "representative CLI smoke".to_string(),
        ],
        output_root: config.output_root.clone(),
        record_wall_time: true,
        record_artifact_count: true,
        record_target_dir_size: true,
        reason_codes: stable_reason_codes(&[
            ReasonCode::BuildTestPerformanceBaselineReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn run_baseline_shell_command(
    command_name: &str,
    mut command: Command,
    record_wall_time: bool,
) -> Result<BaselineCommandResult, String> {
    let start = std::time::Instant::now();
    let output = command.output().map_err(|err| err.to_string())?;
    let wall_time_ms = record_wall_time.then_some(start.elapsed().as_millis() as u64);
    let stderr = String::from_utf8_lossy(&output.stderr);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut summary_parts = Vec::new();
    if !stdout.trim().is_empty() {
        summary_parts.push(stdout.lines().take(3).collect::<Vec<_>>().join(" | "));
    }
    if !stderr.trim().is_empty() {
        summary_parts.push(stderr.lines().take(3).collect::<Vec<_>>().join(" | "));
    }
    Ok(BaselineCommandResult {
        command: command_name.to_string(),
        passed: output.status.success(),
        wall_time_ms,
        output_summary: (!summary_parts.is_empty()).then(|| summary_parts.join(" | ")),
        reason_codes: stable_reason_codes(&[
            ReasonCode::BuildTestPerformanceBaselineReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    })
}

fn build_slowest_commands(results: &[BaselineCommandResult]) -> Vec<String> {
    let mut pairs = results
        .iter()
        .map(|result| (result.command.clone(), result.wall_time_ms.unwrap_or(0)))
        .collect::<Vec<_>>();
    pairs.sort_by(|left, right| right.1.cmp(&left.1).then_with(|| left.0.cmp(&right.0)));
    pairs.into_iter().map(|(command, _)| command).collect()
}

fn normalize_build_test_performance_baseline_report(
    mut report: BuildTestPerformanceBaselineReport,
) -> BuildTestPerformanceBaselineReport {
    report
        .command_results
        .sort_by(|left, right| left.command.cmp(&right.command));
    report.slowest_commands = build_slowest_commands(&report.command_results);
    report
}

