fn build_test_tier_runner_reports(
    run_id_prefix: &str,
    config: &TestTierConfig,
    sample_reports: &[TestTierRunnerReport],
) -> Vec<TestTierRunnerReport> {
    let mut reports = BTreeMap::from([
        (
            TestTierKind::Quick,
            build_test_tier_runner_report(
                &format!("{run_id_prefix}-quick"),
                TestTierKind::Quick,
                tier_commands(&config.quick_commands),
                0,
                0,
                config.quick_commands.len(),
                None,
            ),
        ),
        (
            TestTierKind::Sprint,
            build_test_tier_runner_report(
                &format!("{run_id_prefix}-sprint"),
                TestTierKind::Sprint,
                tier_commands(&config.sprint_commands),
                0,
                0,
                config.sprint_commands.len(),
                None,
            ),
        ),
        (
            TestTierKind::Full,
            build_test_tier_runner_report(
                &format!("{run_id_prefix}-full"),
                TestTierKind::Full,
                tier_commands(&config.full_commands),
                0,
                0,
                config.full_commands.len(),
                None,
            ),
        ),
        (
            TestTierKind::Smoke,
            build_test_tier_runner_report(
                &format!("{run_id_prefix}-smoke"),
                TestTierKind::Smoke,
                tier_commands(&config.smoke_commands),
                0,
                0,
                config.smoke_commands.len(),
                None,
            ),
        ),
        (
            TestTierKind::Audit,
            build_test_tier_runner_report(
                &format!("{run_id_prefix}-audit"),
                TestTierKind::Audit,
                tier_commands(&config.audit_commands),
                0,
                0,
                config.audit_commands.len(),
                None,
            ),
        ),
    ]);
    for report in sample_reports {
        reports.insert(
            report.tier,
            normalize_test_tier_runner_report(report.clone()),
        );
    }
    reports.into_values().collect()
}

pub fn build_test_tier_runner_report(
    run_id: &str,
    tier: TestTierKind,
    commands_run: Vec<String>,
    passed_count: usize,
    failed_count: usize,
    skipped_count: usize,
    runtime_ms: Option<u64>,
) -> TestTierRunnerReport {
    let tier_status = if commands_run.is_empty()
        || (passed_count == 0 && failed_count == 0 && skipped_count > 0)
    {
        TestTierStatus::TierNotRun
    } else if failed_count > 0 {
        TestTierStatus::TierFailed
    } else if skipped_count > 0 {
        TestTierStatus::TierPassedWithWarnings
    } else {
        TestTierStatus::TierPassed
    };
    TestTierRunnerReport {
        run_id: run_id.to_string(),
        tier,
        commands_run,
        passed_count,
        failed_count,
        skipped_count,
        runtime_ms,
        tier_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TestTierRunnerReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn normalize_test_tier_runner_report(mut report: TestTierRunnerReport) -> TestTierRunnerReport {
    report.commands_run = stable_ordered_strings(&report.commands_run);
    report
}

fn tier_commands(commands: &[TestTierCommand]) -> Vec<String> {
    commands
        .iter()
        .map(|command| command.command.clone())
        .collect()
}

