#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct RepeatedWorkspaceTimingConfig {
    pub timing_id: String,
    #[serde(default = "default_test_optimization_output_root")]
    pub output_root: String,
    #[serde(default = "default_repeated_timing_commands")]
    pub commands: Vec<String>,
    #[serde(default = "default_repetitions")]
    pub repetitions: usize,
    #[serde(default = "default_warmup_runs")]
    pub warmup_runs: usize,
    #[serde(default = "default_true")]
    pub include_cold_run: bool,
    #[serde(default = "default_true")]
    pub include_warm_run: bool,
    #[serde(default = "default_true")]
    pub include_target_dir_size: bool,
    #[serde(default = "default_true")]
    pub include_artifact_count: bool,
    #[serde(default = "default_false")]
    pub run_real_commands: bool,
    #[serde(default)]
    pub sample_timing_paths: Vec<String>,
    #[serde(default)]
    pub max_total_runtime_ms: Option<u64>,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for RepeatedWorkspaceTimingConfig {
    fn default() -> Self {
        Self {
            timing_id: "sprint77-test-optimization".to_string(),
            output_root: default_test_optimization_output_root(),
            commands: default_repeated_timing_commands(),
            repetitions: default_repetitions(),
            warmup_runs: default_warmup_runs(),
            include_cold_run: true,
            include_warm_run: true,
            include_target_dir_size: true,
            include_artifact_count: true,
            run_real_commands: false,
            sample_timing_paths: Vec::new(),
            max_total_runtime_ms: None,
            reason_codes: stable_reason_codes(&[
                ReasonCode::RepeatedWorkspaceTimingConfigBuilt,
                ReasonCode::DeterministicPath,
                ReasonCode::LocalFileOnly,
            ]),
        }
    }
}

impl RepeatedWorkspaceTimingConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.timing_id.trim().is_empty() {
            return Err("repeated workspace timing config requires timing_id".to_string());
        }
        if !path_is_local(&self.output_root) {
            return Err("repeated workspace timing output_root must be local".to_string());
        }
        if self.commands.is_empty() {
            return Err("repeated workspace timing commands must not be empty".to_string());
        }
        if self.repetitions == 0 {
            return Err(
                "repeated workspace timing repetitions must be greater than zero".to_string(),
            );
        }
        if self.warmup_runs >= self.repetitions {
            return Err(
                "repeated workspace timing warmup_runs must be smaller than repetitions"
                    .to_string(),
            );
        }
        for path in &self.sample_timing_paths {
            if !path_is_local(path) {
                return Err("repeated workspace timing sample paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(path);
            if !absolute.exists() {
                return Err(format!(
                    "repeated workspace timing sample path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.output_root).join(&self.timing_id)
    }
}

