#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct CliSmokeCostReductionConfig {
    pub reduction_id: String,
    #[serde(default)]
    pub cli_smoke_tiering_paths: Vec<String>,
    #[serde(default)]
    pub timing_report_paths: Vec<String>,
    #[serde(default = "default_test_optimization_output_root")]
    pub output_root: String,
    #[serde(default = "default_true")]
    pub require_required_smoke: bool,
    #[serde(default = "default_true")]
    pub allow_representative_smoke_only_for_sprint: bool,
    #[serde(default = "default_true")]
    pub allow_exhaustive_smoke_only_for_full: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl CliSmokeCostReductionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.reduction_id.trim().is_empty() {
            return Err("cli smoke cost reduction config requires reduction_id".to_string());
        }
        if !path_is_local(&self.output_root) {
            return Err("cli smoke cost reduction output_root must be local".to_string());
        }
        for path in self
            .cli_smoke_tiering_paths
            .iter()
            .chain(self.timing_report_paths.iter())
        {
            if !path_is_local(path) {
                return Err("cli smoke cost reduction paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(path);
            if !absolute.exists() {
                return Err(format!(
                    "cli smoke cost reduction path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        Ok(())
    }
}

