pub struct CoreCompletionV2Config {
    pub core_id: String,
    #[serde(default)]
    pub core_check_paths: Vec<String>,
    #[serde(default)]
    pub committee_v1_paths: Vec<String>,
    #[serde(default)]
    pub sequence_export_paths: Vec<String>,
    #[serde(default)]
    pub real_evidence_paths: Vec<String>,
    #[serde(default)]
    pub model_ops_paths: Vec<String>,
    #[serde(default)]
    pub toolchain_speed_paths: Vec<String>,
    #[serde(default = "default_core_committee_mamba_output_root")]
    pub output_root: String,
    #[serde(default = "default_true")]
    pub require_core_check: bool,
    #[serde(default = "default_true")]
    pub require_committee_gate: bool,
    #[serde(default = "default_true")]
    pub require_training_storage_contract: bool,
    #[serde(default = "default_true")]
    pub require_mamba_contract: bool,
    #[serde(default = "default_true")]
    pub require_risk_governor: bool,
    #[serde(default = "default_true")]
    pub require_no_live_paths: bool,
    #[serde(default = "default_true")]
    pub require_no_broker_paths: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for CoreCompletionV2Config {
    fn default() -> Self {
        Self {
            core_id: "sprint78-core-completion".to_string(),
            core_check_paths: Vec::new(),
            committee_v1_paths: Vec::new(),
            sequence_export_paths: Vec::new(),
            real_evidence_paths: Vec::new(),
            model_ops_paths: Vec::new(),
            toolchain_speed_paths: Vec::new(),
            output_root: default_core_committee_mamba_output_root(),
            require_core_check: true,
            require_committee_gate: true,
            require_training_storage_contract: true,
            require_mamba_contract: true,
            require_risk_governor: true,
            require_no_live_paths: true,
            require_no_broker_paths: true,
            reason_codes: stable_reason_codes(&[
                ReasonCode::CoreCompletionV2ConfigBuilt,
                ReasonCode::DeterministicPath,
                ReasonCode::LocalFileOnly,
            ]),
        }
    }
}

impl CoreCompletionV2Config {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.core_id.trim().is_empty() {
            return Err("core completion v2 config requires core_id".to_string());
        }
        if !path_is_local(&self.output_root) {
            return Err("core completion v2 output_root must be local".to_string());
        }
        for path in self
            .core_check_paths
            .iter()
            .chain(self.committee_v1_paths.iter())
            .chain(self.sequence_export_paths.iter())
            .chain(self.real_evidence_paths.iter())
            .chain(self.model_ops_paths.iter())
            .chain(self.toolchain_speed_paths.iter())
        {
            if !path_is_local(path) {
                return Err("core completion v2 paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(path);
            if !absolute.exists() {
                return Err(format!(
                    "core completion v2 path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.output_root).join(&self.core_id)
    }

    fn all_support_paths(&self) -> Vec<String> {
        stable_ordered_strings(
            &self
                .core_check_paths
                .iter()
                .chain(self.committee_v1_paths.iter())
                .chain(self.sequence_export_paths.iter())
                .chain(self.real_evidence_paths.iter())
                .chain(self.model_ops_paths.iter())
                .chain(self.toolchain_speed_paths.iter())
                .cloned()
                .collect::<Vec<_>>(),
        )
    }
}

