fn build_training_data_lineage_spec(lineage_id: &str) -> TrainingDataLineageSpec {
    let raw_to_canonical =
        "normalize provider rows into canonical candle/reference records".to_string();
    let canonical_to_features = "derive feature rows under locked feature schema hash".to_string();
    let features_to_labels =
        "build labels under locked label manifest and barrier profile".to_string();
    let labels_to_sequences =
        "window features+labels into sequence dataset with no-lookahead proof".to_string();
    let sequences_to_predictions =
        "store offline prediction csv only with schema version".to_string();
    let predictions_to_evaluations =
        "run research-only evaluation and risk-aware comparison artifacts".to_string();
    let evaluations_to_leaderboard =
        "leaderboard remains research-only and model-card gated".to_string();
    let lineage_fingerprint = stable_hash_string(&format!(
        "{}|{}|{}|{}|{}|{}|{}",
        raw_to_canonical,
        canonical_to_features,
        features_to_labels,
        labels_to_sequences,
        sequences_to_predictions,
        predictions_to_evaluations,
        evaluations_to_leaderboard
    ));
    TrainingDataLineageSpec {
        lineage_id: lineage_id.to_string(),
        raw_to_canonical,
        canonical_to_features,
        features_to_labels,
        labels_to_sequences,
        sequences_to_predictions,
        predictions_to_evaluations,
        evaluations_to_leaderboard,
        lineage_fingerprint,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TrainingDataLineageSpecBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

