fn build_mamba3_implementation_roadmap(
    roadmap_id: &str,
    core_report: &CoreCompletionV2Report,
    readiness_gate: &Mamba3FinRuntimeReadinessGate,
    committee_report: &CommitteeCompletionGateReport,
) -> Mamba3ImplementationRoadmap {
    let stages = vec![
        Mamba3ImplementationStage::DataStorageImplementation,
        Mamba3ImplementationStage::SequenceDatasetScaleout,
        Mamba3ImplementationStage::ExternalPrototypeEvaluation,
        Mamba3ImplementationStage::RustRuntimeScaffold,
        Mamba3ImplementationStage::RustInferenceParityTest,
        Mamba3ImplementationStage::RiskIntegrationTest,
        Mamba3ImplementationStage::ControlTowerVisibility,
        Mamba3ImplementationStage::RuntimeStillDeferred,
    ];
    let current_stage = if readiness_gate.training_data_storage_ready {
        Mamba3ImplementationStage::DataStorageImplementation
    } else {
        Mamba3ImplementationStage::RuntimeStillDeferred
    };
    let mut blocked_stages = Vec::new();
    if !core_report.training_storage_contract_ready {
        blocked_stages.push(Mamba3ImplementationStage::DataStorageImplementation);
    }
    if committee_report.gate_status != CommitteeCompletionGateStatus::CommitteeCoreReady {
        blocked_stages.push(Mamba3ImplementationStage::SequenceDatasetScaleout);
    }
    blocked_stages.push(Mamba3ImplementationStage::RustRuntimeScaffold);
    blocked_stages.push(Mamba3ImplementationStage::RustInferenceParityTest);
    let final_recommendation = if !core_report.training_storage_contract_ready {
        Mamba3ImplementationRecommendation::BuildTrainingDataStorageNext
    } else if committee_report.gate_status != CommitteeCompletionGateStatus::CommitteeCoreReady {
        Mamba3ImplementationRecommendation::ImproveCommitteeMaterializationFirst
    } else if readiness_gate.external_bridge_ready {
        Mamba3ImplementationRecommendation::ExternalPrototypeBeforeRuntime
    } else {
        Mamba3ImplementationRecommendation::HoldRuntimeDeferred
    };
    let prerequisites_by_stage = BTreeMap::from([
        (
            "DataStorageImplementation".to_string(),
            vec![
                "training data storage contract frozen".to_string(),
                "CSV/JSON manifest decision accepted".to_string(),
            ],
        ),
        (
            "SequenceDatasetScaleout".to_string(),
            vec![
                "no-lookahead proof preserved".to_string(),
                "committee completion gate stable".to_string(),
            ],
        ),
        (
            "ExternalPrototypeEvaluation".to_string(),
            vec![
                "external bridge ready".to_string(),
                "risk integration still required".to_string(),
            ],
        ),
        (
            "RustRuntimeScaffold".to_string(),
            vec![
                "training data storage implemented".to_string(),
                "evidence depth sufficient".to_string(),
                "test budget confirmed".to_string(),
            ],
        ),
    ]);
    let acceptance_by_stage = BTreeMap::from([
        (
            "DataStorageImplementation".to_string(),
            vec!["registry/layout/lineage/versioning round-trip is deterministic".to_string()],
        ),
        (
            "ExternalPrototypeEvaluation".to_string(),
            vec!["prototype remains research-only and csv-import based".to_string()],
        ),
        (
            "RustRuntimeScaffold".to_string(),
            vec!["runtime still forbidden from live inference or training".to_string()],
        ),
    ]);
    Mamba3ImplementationRoadmap {
        roadmap_id: roadmap_id.to_string(),
        stages,
        current_stage,
        blocked_stages: stable_mamba_stages(&blocked_stages),
        prerequisites_by_stage,
        acceptance_by_stage,
        forbidden_until_satisfied: vec![
            "live trading".to_string(),
            "broker execution".to_string(),
            "runtime llm decision".to_string(),
            "rust-native training".to_string(),
        ],
        final_recommendation,
        reason_codes: stable_reason_codes(&[
            ReasonCode::Mamba3ImplementationRoadmapBuilt,
            ReasonCode::DeterministicPath,
            ReasonCode::MambaRuntimeDeferred,
        ]),
    }
}

fn build_control_tower_core_mamba_data_panel(
    panel_id: &str,
    core_report: &CoreCompletionV2Report,
    committee_report: &CommitteeCompletionGateReport,
    decision_report: &TrainingDataStorageDecisionReport,
    readiness_gate: &Mamba3FinRuntimeReadinessGate,
    roadmap: &Mamba3ImplementationRoadmap,
) -> ControlTowerCoreMambaDataPanel {
    let mut next_actions = vec![
        "keep Mamba runtime deferred".to_string(),
        "keep Trinity active".to_string(),
    ];
    if committee_report.gate_status != CommitteeCompletionGateStatus::CommitteeCoreReady {
        next_actions.push("improve committee materialization first".to_string());
    }
    if !core_report.training_storage_contract_ready {
        next_actions.push("freeze training data storage contract".to_string());
    }
    let mut warnings = vec![
        "no runtime implementation in Sprint 78".to_string(),
        "no model training in Sprint 78".to_string(),
    ];
    if readiness_gate.readiness_status
        == Mamba3FinRuntimeReadinessStatus::ReadyForStorageImplementation
    {
        warnings.push("storage-ready does not mean runtime-ready".to_string());
    }
    ControlTowerCoreMambaDataPanel {
        panel_id: panel_id.to_string(),
        core_completion_v2_status: core_report.status,
        committee_completion_status: committee_report.gate_status,
        training_data_storage_status: decision_report.decision_status,
        mamba_contract_status: if core_report.mamba_contract_ready {
            Mamba3FinContractPanelStatus::ContractReady
        } else {
            Mamba3FinContractPanelStatus::ContractOnly
        },
        mamba_runtime_readiness_status: readiness_gate.readiness_status,
        storage_format_decision: decision_report.selected_now,
        next_actions: stable_ordered_strings(&next_actions),
        warnings: stable_ordered_strings(&warnings),
        deferred_items: vec![
            "Mamba runtime".to_string(),
            "model training".to_string(),
            "6/12 persona expansion".to_string(),
            format!("roadmap::{:?}", roadmap.final_recommendation),
        ],
        reason_codes: stable_reason_codes(&[
            ReasonCode::ControlTowerCoreMambaDataPanelBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

