fn write_core_committee_mamba_bundle(
    config: &CoreCompletionV2Config,
    core_completion_v2_report: &CoreCompletionV2Report,
    mamba3fin_core_contract: &Mamba3FinCoreContract,
    mamba3fin_runtime_readiness_gate: &Mamba3FinRuntimeReadinessGate,
    mamba3fin_data_dependency_report: &Mamba3FinDataDependencyReport,
    committee_completion_gate_report: &CommitteeCompletionGateReport,
    committee_evidence_materialization_plan_v2: &CommitteeEvidenceMaterializationPlanV2,
    committee_chair_risk_completion_report: &CommitteeChairRiskCompletionReport,
    training_data_storage_decision_report: &TrainingDataStorageDecisionReport,
    training_data_registry_spec: &TrainingDataRegistrySpec,
    training_data_layout_plan: &TrainingDataLayoutPlan,
    training_data_lineage_spec: &TrainingDataLineageSpec,
    dataset_versioning_policy: &DatasetVersioningPolicy,
    feature_label_storage_contract: &FeatureLabelStorageContract,
    sequence_training_data_contract: &SequenceTrainingDataContract,
    prediction_model_card_storage_contract: &PredictionAndModelCardStorageContract,
    storage_format_decision_report: &StorageFormatDecisionReport,
    control_tower_core_mamba_data_panel: &ControlTowerCoreMambaDataPanel,
    mamba3_implementation_roadmap: &Mamba3ImplementationRoadmap,
    final_summary: &str,
) -> Result<(OperatorBriefingStorageReport, String), String> {
    let dir = config.output_dir();
    fs::create_dir_all(&dir).map_err(|err| err.to_string())?;
    let files = BTreeMap::from([
        (
            "core_completion_v2.txt".to_string(),
            serde_json::to_string_pretty(core_completion_v2_report)
                .map_err(|err| err.to_string())?,
        ),
        (
            "mamba3fin_core_contract.txt".to_string(),
            serde_json::to_string_pretty(mamba3fin_core_contract).map_err(|err| err.to_string())?,
        ),
        (
            "mamba3fin_runtime_readiness_gate.txt".to_string(),
            serde_json::to_string_pretty(mamba3fin_runtime_readiness_gate)
                .map_err(|err| err.to_string())?,
        ),
        (
            "mamba3fin_data_dependency.txt".to_string(),
            serde_json::to_string_pretty(mamba3fin_data_dependency_report)
                .map_err(|err| err.to_string())?,
        ),
        (
            "committee_completion_gate.txt".to_string(),
            serde_json::to_string_pretty(committee_completion_gate_report)
                .map_err(|err| err.to_string())?,
        ),
        (
            "committee_materialization_plan_v2.txt".to_string(),
            serde_json::to_string_pretty(committee_evidence_materialization_plan_v2)
                .map_err(|err| err.to_string())?,
        ),
        (
            "committee_chair_risk_completion.txt".to_string(),
            serde_json::to_string_pretty(committee_chair_risk_completion_report)
                .map_err(|err| err.to_string())?,
        ),
        (
            "training_data_storage_decision.txt".to_string(),
            serde_json::to_string_pretty(training_data_storage_decision_report)
                .map_err(|err| err.to_string())?,
        ),
        (
            "training_data_registry_spec.txt".to_string(),
            serde_json::to_string_pretty(training_data_registry_spec)
                .map_err(|err| err.to_string())?,
        ),
        (
            "training_data_layout_plan.txt".to_string(),
            serde_json::to_string_pretty(training_data_layout_plan)
                .map_err(|err| err.to_string())?,
        ),
        (
            "training_data_lineage_spec.txt".to_string(),
            serde_json::to_string_pretty(training_data_lineage_spec)
                .map_err(|err| err.to_string())?,
        ),
        (
            "dataset_versioning_policy.txt".to_string(),
            serde_json::to_string_pretty(dataset_versioning_policy)
                .map_err(|err| err.to_string())?,
        ),
        (
            "feature_label_storage_contract.txt".to_string(),
            serde_json::to_string_pretty(feature_label_storage_contract)
                .map_err(|err| err.to_string())?,
        ),
        (
            "sequence_training_data_contract.txt".to_string(),
            serde_json::to_string_pretty(sequence_training_data_contract)
                .map_err(|err| err.to_string())?,
        ),
        (
            "prediction_model_card_storage_contract.txt".to_string(),
            serde_json::to_string_pretty(prediction_model_card_storage_contract)
                .map_err(|err| err.to_string())?,
        ),
        (
            "storage_format_decision.txt".to_string(),
            serde_json::to_string_pretty(storage_format_decision_report)
                .map_err(|err| err.to_string())?,
        ),
        (
            "mamba3_implementation_roadmap.txt".to_string(),
            serde_json::to_string_pretty(mamba3_implementation_roadmap)
                .map_err(|err| err.to_string())?,
        ),
        (
            "control_tower_core_mamba_data_panel.txt".to_string(),
            serde_json::to_string_pretty(control_tower_core_mamba_data_panel)
                .map_err(|err| err.to_string())?,
        ),
    ]);
    for (name, text) in &files {
        fs::write(dir.join(name), text).map_err(|err| err.to_string())?;
    }
    fs::write(dir.join("summary.txt"), final_summary).map_err(|err| err.to_string())?;
    let mut storage_bytes = final_summary.len();
    for text in files.values() {
        storage_bytes += text.len();
    }
    let storage_report = OperatorBriefingStorageReport {
        artifact_count: files.len() + 2,
        storage_bytes,
        max_bytes: 1_000_000,
        within_budget: storage_bytes <= 1_000_000,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CoreCommitteeMambaReadinessBundleBuilt,
            ReasonCode::DeterministicPath,
        ]),
    };
    fs::write(
        dir.join("storage_report.txt"),
        serde_json::to_string_pretty(&storage_report).map_err(|err| err.to_string())?,
    )
    .map_err(|err| err.to_string())?;
    Ok((storage_report, final_summary.to_string()))
}

