fn load_sprint78_support_data(paths: &[String]) -> Result<Sprint78SupportData, String> {
    let mut support = Sprint78SupportData::default();
    for path in paths {
        let absolute = sprint76_absolutize(path);
        let text = fs::read_to_string(&absolute).map_err(|err| err.to_string())?;
        let parsed: Sprint78SupportInput =
            serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if let Some(state) = parsed.core_current_state {
            support.core_current_state = state;
        }
        if let Some(state) = parsed.committee_v1_state {
            support.committee_v1_state = state;
        }
        if let Some(state) = parsed.sequence_export_state {
            support.sequence_export_state = state;
        }
        if let Some(state) = parsed.real_evidence_state {
            support.real_evidence_state = state;
        }
        if let Some(state) = parsed.model_ops_state {
            support.model_ops_state = state;
        }
        if let Some(expected) = parsed.training_data_storage_expected {
            support.training_data_storage_expected = expected;
        }
        if let Some(expected) = parsed.mamba3_contract_expected {
            support.mamba3_contract_expected = expected;
        }
        if let Some(expected) = parsed.committee_completion_expected {
            support.committee_completion_expected = expected;
        }
    }
    Ok(support)
}

fn stable_mamba_stages(stages: &[Mamba3ImplementationStage]) -> Vec<Mamba3ImplementationStage> {
    let mut stages = stages.to_vec();
    stages.sort();
    stages.dedup();
    stages
}

fn stable_storage_format_candidates(
    values: &[StorageFormatCandidate],
) -> Vec<StorageFormatCandidate> {
    let mut values = values.to_vec();
    values.sort_by(|left, right| format!("{:?}", left).cmp(&format!("{:?}", right)));
    values.dedup();
    values
}

