fn build_sequence_core_candidates(
    config: &SequenceCoreCandidateRegistryConfig,
    support: &Sprint79SupportData,
) -> Vec<SequenceCoreCandidateContract> {
    let mut candidates = Vec::new();
    if !config.mamba3fin_contract_paths.is_empty() {
        candidates.push(build_mamba3fin_sequence_candidate_contract(
            &config.registry_id,
            support,
        ));
    }
    if !config.gated_deltanet_contract_paths.is_empty() {
        candidates.push(build_gated_deltanet_sequence_candidate_contract(
            &config.registry_id,
            support,
        ));
    }
    stable_sequence_core_candidates(&candidates)
}

