fn build_sequence_core_candidate_registry(
    config: &SequenceCoreCandidateRegistryConfig,
    candidates: &[SequenceCoreCandidateContract],
) -> SequenceCoreCandidateRegistry {
    let candidates = stable_sequence_core_candidates(candidates);
    let common_input_spec_ready = candidates
        .iter()
        .map(|candidate| candidate.input_tensor_spec.as_str())
        .all_equal();
    let common_prediction_heads_ready = candidates
        .iter()
        .map(|candidate| candidate.prediction_heads.join("|"))
        .all_equal();
    let has_mamba = candidates
        .iter()
        .any(|candidate| candidate.family == SequenceCoreCandidateFamily::Mamba3Fin);
    let has_gated = candidates
        .iter()
        .any(|candidate| candidate.family == SequenceCoreCandidateFamily::GatedDeltaNet);
    let risk_integration_ready = candidates
        .iter()
        .all(|candidate| candidate.risk_integration_required);
    let registry_status = if config.require_mamba3fin && !has_mamba {
        SequenceCoreCandidateRegistryStatus::MissingMamba3Fin
    } else if config.require_gated_deltanet && !has_gated {
        SequenceCoreCandidateRegistryStatus::MissingGatedDeltaNet
    } else if config.require_common_input_spec && !common_input_spec_ready {
        SequenceCoreCandidateRegistryStatus::InputSpecMismatch
    } else if config.require_common_prediction_heads && !common_prediction_heads_ready {
        SequenceCoreCandidateRegistryStatus::PredictionHeadMismatch
    } else if config.require_risk_integration && !risk_integration_ready {
        SequenceCoreCandidateRegistryStatus::RiskIntegrationMissing
    } else {
        SequenceCoreCandidateRegistryStatus::SequenceCoreRegistryReady
    };
    SequenceCoreCandidateRegistry {
        registry_id: config.registry_id.clone(),
        candidate_count: candidates.len(),
        neural_candidate_count: candidates
            .iter()
            .filter(|candidate| {
                matches!(
                    candidate.family,
                    SequenceCoreCandidateFamily::Mamba3Fin
                        | SequenceCoreCandidateFamily::GatedDeltaNet
                )
            })
            .count(),
        non_neural_candidate_count: candidates
            .iter()
            .filter(|candidate| {
                !matches!(
                    candidate.family,
                    SequenceCoreCandidateFamily::Mamba3Fin
                        | SequenceCoreCandidateFamily::GatedDeltaNet
                )
            })
            .count(),
        runtime_deferred_count: candidates
            .iter()
            .filter(|candidate| {
                candidate.runtime_status == SequenceCoreCandidateRuntimeStatus::RuntimeDeferred
            })
            .count(),
        common_input_spec_ready,
        common_prediction_heads_ready,
        candidates,
        registry_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCoreCandidateRegistryBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_gated_deltanet_runtime_readiness_gate(
    registry_id: &str,
    registry: &SequenceCoreCandidateRegistry,
    support: &Sprint79SupportData,
) -> GatedDeltaNetRuntimeReadinessGate {
    let storage = &support.training_data_storage_plan;
    let committee = &support.committee_gate_state;
    let registry_state = &support.training_data_registry_spec;
    let gated_delta_contract_ready = registry
        .candidates
        .iter()
        .any(|candidate| candidate.family == SequenceCoreCandidateFamily::GatedDeltaNet);
    let readiness_status = if !registry_state.training_storage_manifest_present {
        GatedDeltaNetRuntimeReadinessStatus::BlockedByTrainingDataStorage
    } else if !committee.evidence_depth_ready {
        GatedDeltaNetRuntimeReadinessStatus::BlockedByEvidenceDepth
    } else if !committee.committee_gate_ready {
        GatedDeltaNetRuntimeReadinessStatus::BlockedByCommitteeGate
    } else if !storage.test_budget_ready {
        GatedDeltaNetRuntimeReadinessStatus::BlockedByTestBudget
    } else if storage.external_bridge_ready && gated_delta_contract_ready {
        GatedDeltaNetRuntimeReadinessStatus::ReadyForExternalPrototypeOnly
    } else {
        GatedDeltaNetRuntimeReadinessStatus::RuntimeStillDeferred
    };
    let final_recommendation = match readiness_status {
        GatedDeltaNetRuntimeReadinessStatus::ReadyForExternalPrototypeOnly => {
            "ExternalPrototypeBeforeRuntime".to_string()
        }
        GatedDeltaNetRuntimeReadinessStatus::BlockedByTrainingDataStorage => {
            "BuildTrainingDataArtifactNext".to_string()
        }
        GatedDeltaNetRuntimeReadinessStatus::BlockedByEvidenceDepth => {
            "NeedMoreRealEvidence".to_string()
        }
        GatedDeltaNetRuntimeReadinessStatus::BlockedByCommitteeGate => "KeepTrinity".to_string(),
        GatedDeltaNetRuntimeReadinessStatus::BlockedByTestBudget
        | GatedDeltaNetRuntimeReadinessStatus::ReadyForStorageImplementation
        | GatedDeltaNetRuntimeReadinessStatus::ReadyForRustRuntimeScaffold
        | GatedDeltaNetRuntimeReadinessStatus::RuntimeStillDeferred
        | GatedDeltaNetRuntimeReadinessStatus::DiagnosticOnly => {
            "HoldGatedDeltaNetRuntimeDeferred".to_string()
        }
    };
    GatedDeltaNetRuntimeReadinessGate {
        gate_id: registry_id.to_string(),
        training_data_storage_ready: registry_state.training_storage_manifest_present,
        sequence_dataset_ready: registry_state.dataset_registry_present,
        feature_schema_ready: storage.feature_schema_ready,
        label_manifest_ready: storage.label_manifest_ready,
        no_lookahead_ready: storage.no_lookahead_ready,
        evidence_depth_ready: committee.evidence_depth_ready,
        committee_comparison_ready: committee.committee_gate_ready,
        external_bridge_ready: storage.external_bridge_ready,
        risk_integration_ready: committee.risk_governor_ready,
        storage_budget_ready: storage.storage_budget_ready,
        test_budget_ready: storage.test_budget_ready,
        gated_delta_contract_ready,
        readiness_status,
        final_recommendation,
        reason_codes: stable_reason_codes(&[
            ReasonCode::GatedDeltaNetRuntimeReadinessGateBuilt,
            ReasonCode::GatedDeltaNetRuntimeDeferred,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_gated_deltanet_data_dependency_report(
    registry_id: &str,
    registry: &SequenceCoreCandidateRegistry,
    support: &Sprint79SupportData,
) -> GatedDeltaNetDataDependencyReport {
    let registry_state = &support.training_data_registry_spec;
    let required_artifacts = vec![
        "dataset_registry",
        "dataset_version_manifest",
        "feature_schema_manifest",
        "label_manifest",
        "sequence_export_manifest",
        "split_manifest",
        "no_lookahead_proof",
        "source_class_manifest",
        "training_storage_manifest",
        "evaluation_protocol",
        "sequence_core_candidate_registry",
    ]
    .into_iter()
    .map(ToString::to_string)
    .collect::<Vec<_>>();
    let present_artifacts = vec![
        (registry_state.dataset_registry_present, "dataset_registry"),
        (
            registry_state.dataset_version_manifest_present,
            "dataset_version_manifest",
        ),
        (
            support.training_data_storage_plan.feature_schema_ready,
            "feature_schema_manifest",
        ),
        (
            support.training_data_storage_plan.label_manifest_ready,
            "label_manifest",
        ),
        (true, "sequence_export_manifest"),
        (true, "split_manifest"),
        (
            support.training_data_storage_plan.no_lookahead_ready,
            "no_lookahead_proof",
        ),
        (
            registry_state.source_class_manifest_present,
            "source_class_manifest",
        ),
        (
            registry_state.training_storage_manifest_present,
            "training_storage_manifest",
        ),
        (true, "evaluation_protocol"),
        (
            registry.registry_status
                == SequenceCoreCandidateRegistryStatus::SequenceCoreRegistryReady,
            "sequence_core_candidate_registry",
        ),
    ]
    .into_iter()
    .filter(|(present, _)| *present)
    .map(|(_, name)| name.to_string())
    .collect::<Vec<_>>();
    let missing_artifacts = required_artifacts
        .iter()
        .filter(|artifact| !present_artifacts.contains(*artifact))
        .cloned()
        .collect::<Vec<_>>();
    let dependency_status = if missing_artifacts
        .iter()
        .any(|artifact| artifact == "sequence_core_candidate_registry")
    {
        GatedDeltaNetDataDependencyStatus::MissingCandidateRegistry
    } else if missing_artifacts
        .iter()
        .any(|artifact| artifact == "training_storage_manifest")
    {
        GatedDeltaNetDataDependencyStatus::MissingTrainingStorage
    } else if missing_artifacts
        .iter()
        .any(|artifact| artifact == "feature_schema_manifest")
    {
        GatedDeltaNetDataDependencyStatus::MissingFeatureSchema
    } else if missing_artifacts
        .iter()
        .any(|artifact| artifact == "label_manifest")
    {
        GatedDeltaNetDataDependencyStatus::MissingLabelManifest
    } else if missing_artifacts
        .iter()
        .any(|artifact| artifact == "sequence_export_manifest")
    {
        GatedDeltaNetDataDependencyStatus::MissingSequenceExport
    } else if missing_artifacts
        .iter()
        .any(|artifact| artifact == "no_lookahead_proof")
    {
        GatedDeltaNetDataDependencyStatus::MissingNoLookaheadProof
    } else {
        GatedDeltaNetDataDependencyStatus::DependenciesReady
    };
    GatedDeltaNetDataDependencyReport {
        dependency_id: registry_id.to_string(),
        required_artifacts,
        present_artifacts,
        missing_artifacts,
        dependency_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::GatedDeltaNetDataDependencyReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_sequence_core_candidate_comparison_plan(
    registry_id: &str,
    registry: &SequenceCoreCandidateRegistry,
    support: &Sprint79SupportData,
) -> SequenceCoreCandidateComparisonPlan {
    let expected = &support.sequence_core_registry_expected;
    let comparison_status = if !expected.common_dataset_ready {
        SequenceCoreCandidateComparisonStatus::NeedCommonDataset
    } else if !expected.common_feature_schema_ready {
        SequenceCoreCandidateComparisonStatus::NeedCommonFeatureSchema
    } else if !expected.common_label_manifest_ready {
        SequenceCoreCandidateComparisonStatus::NeedCommonLabels
    } else if !expected.external_prototype_outputs_ready {
        SequenceCoreCandidateComparisonStatus::NeedExternalPrototypeOutputs
    } else {
        SequenceCoreCandidateComparisonStatus::ComparisonPlanReady
    };
    SequenceCoreCandidateComparisonPlan {
        plan_id: registry_id.to_string(),
        candidates: registry
            .candidates
            .iter()
            .map(|candidate| candidate.family)
            .collect(),
        common_dataset_required: true,
        common_feature_schema_required: true,
        common_label_manifest_required: true,
        common_split_required: true,
        metrics: vec![
            "coverage".to_string(),
            "calibration".to_string(),
            "risk_adjusted_score".to_string(),
            "no_trade_comparison".to_string(),
            "risk_denied_defensive_value".to_string(),
            "latency_budget_estimate".to_string(),
            "storage_budget_estimate".to_string(),
            "test_budget_estimate".to_string(),
        ],
        comparison_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCoreCandidateComparisonPlanBuilt,
            ReasonCode::DeterministicPath,
            ReasonCode::ExternalPrototypeComparisonReady,
        ]),
    }
}

