fn materialize_training_data_storage(
    config: &TrainingDataStorageMaterializationConfig,
    support: &Sprint79SupportData,
) -> Result<TrainingDataStorageMaterializationReport, String> {
    let storage_root = config.storage_dir();
    fs::create_dir_all(&storage_root).map_err(|err| err.to_string())?;
    let required_directories = support
        .training_data_storage_plan
        .required_directories
        .clone();
    let created_directories = if config.create_directories {
        for directory in &required_directories {
            let relative = directory
                .strip_prefix("data/")
                .unwrap_or(directory.as_str());
            fs::create_dir_all(storage_root.join(relative)).map_err(|err| err.to_string())?;
        }
        required_directories.clone()
    } else {
        Vec::new()
    };
    let written_manifests = if config.write_placeholder_manifests {
        for manifest in &support.training_data_storage_plan.required_manifests {
            let relative = manifest.strip_prefix("data/").unwrap_or(manifest.as_str());
            let path = storage_root.join(relative);
            if let Some(parent) = path.parent() {
                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
            }
            let manifest_name = Path::new(manifest)
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("manifest.json");
            let value = serde_json::json!({
                "manifest_name": manifest_name,
                "materialization_id": config.materialization_id,
                "placeholder": support.storage_materialization_expected.explicit_placeholders,
                "data_available": false,
                "research_only": true,
                "paper_only": true,
                "note": "explicit placeholder manifest; no data materialized"
            });
            let text = serde_json::to_string_pretty(&value).map_err(|err| err.to_string())?;
            fs::write(path, text).map_err(|err| err.to_string())?;
        }
        support
            .training_data_storage_plan
            .required_manifests
            .clone()
    } else {
        Vec::new()
    };
    let materialization_status = if support
        .training_data_storage_plan
        .required_directories
        .is_empty()
    {
        TrainingDataStorageMaterializationStatus::MissingLayoutPlan
    } else if support.training_data_registry_spec.dataset_registry_present {
        TrainingDataStorageMaterializationStatus::StorageMaterialized
    } else {
        TrainingDataStorageMaterializationStatus::MissingRegistrySpec
    };
    Ok(TrainingDataStorageMaterializationReport {
        materialization_id: config.materialization_id.clone(),
        created_directories,
        existing_directories: Vec::new(),
        written_manifests,
        skipped_manifests: Vec::new(),
        storage_root: default_sprint79_storage_root_report(),
        materialization_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TrainingDataStorageMaterializationReportBuilt,
            ReasonCode::TrainingDataStorageMaterialized,
            ReasonCode::DeterministicPath,
        ]),
    })
}

fn build_training_data_storage_integrity_check(
    config: &TrainingDataStorageMaterializationConfig,
    support: &Sprint79SupportData,
) -> Result<TrainingDataStorageIntegrityCheck, String> {
    let storage_root = config.storage_dir();
    let required_directories_present = support
        .training_data_storage_plan
        .required_directories
        .iter()
        .all(|directory| {
            storage_root
                .join(directory.strip_prefix("data/").unwrap_or(directory))
                .exists()
        });
    let required_manifests_present = support
        .training_data_storage_plan
        .required_manifests
        .iter()
        .all(|manifest| {
            storage_root
                .join(manifest.strip_prefix("data/").unwrap_or(manifest))
                .exists()
        });
    let source_class_manifest_present = storage_root
        .join("registry/source_class_manifest.json")
        .exists();
    let lineage_manifest_present = storage_root.join("registry/lineage_manifest.json").exists();
    let storage_layout_manifest_present = storage_root
        .join("registry/storage_layout_manifest.json")
        .exists();
    let mut manifest_json_valid = true;
    let mut no_secret_values = true;
    let mut no_order_account_fields = true;
    for manifest in &support.training_data_storage_plan.required_manifests {
        let path = storage_root.join(manifest.strip_prefix("data/").unwrap_or(manifest));
        if !path.exists() {
            continue;
        }
        let text = fs::read_to_string(&path).map_err(|err| err.to_string())?;
        manifest_json_valid &= serde_json::from_str::<serde_json::Value>(&text).is_ok();
        let lower = text.to_ascii_lowercase();
        no_secret_values &= !lower.contains("app_key")
            && !lower.contains("app_secret")
            && !lower.contains("kis_base_url");
        no_order_account_fields &= !lower.contains("\"order\"")
            && !lower.contains("\"account\"")
            && !lower.contains("\"broker\"");
    }
    let integrity_status = if !required_directories_present {
        TrainingDataStorageIntegrityStatus::MissingDirectories
    } else if !required_manifests_present {
        TrainingDataStorageIntegrityStatus::MissingManifests
    } else if !manifest_json_valid {
        TrainingDataStorageIntegrityStatus::InvalidManifestJson
    } else if !no_secret_values {
        TrainingDataStorageIntegrityStatus::SecretLeakDetected
    } else if !no_order_account_fields {
        TrainingDataStorageIntegrityStatus::UnsafeFieldsDetected
    } else {
        TrainingDataStorageIntegrityStatus::StorageIntegrityReady
    };
    Ok(TrainingDataStorageIntegrityCheck {
        check_id: config.materialization_id.clone(),
        required_directories_present,
        required_manifests_present,
        source_class_manifest_present: if config.require_source_class_manifest {
            source_class_manifest_present
        } else {
            true
        },
        lineage_manifest_present: if config.require_lineage_manifest {
            lineage_manifest_present
        } else {
            true
        },
        storage_layout_manifest_present: if config.require_storage_layout_manifest {
            storage_layout_manifest_present
        } else {
            true
        },
        manifest_json_valid,
        no_secret_values,
        no_order_account_fields,
        integrity_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TrainingDataStorageIntegrityCheckBuilt,
            ReasonCode::TrainingDataStorageIntegrityReady,
            ReasonCode::DeterministicPath,
        ]),
    })
}

