fn write_sequence_core_storage_bundle(
    registry_config: &SequenceCoreCandidateRegistryConfig,
    materialization_config: &TrainingDataStorageMaterializationConfig,
    registry: &SequenceCoreCandidateRegistry,
    _mamba_summary: &Mamba3FinCoreContractSummary,
    gated_contract: &GatedDeltaNetCoreContract,
    readiness: &GatedDeltaNetRuntimeReadinessGate,
    dependency_report: &GatedDeltaNetDataDependencyReport,
    comparison: &SequenceCoreCandidateComparisonPlan,
    external_contract: &SequenceCoreExternalPrototypeContract,
    materialization: &TrainingDataStorageMaterializationReport,
    integrity: &TrainingDataStorageIntegrityCheck,
    model_family_storage_contracts: &[ModelFamilyStorageContract],
    panel: &ControlTowerSequenceCorePanel,
    final_summary: &str,
) -> Result<(OperatorBriefingStorageReport, String), String> {
    let dir = materialization_config.output_dir();
    fs::create_dir_all(&dir).map_err(|err| err.to_string())?;
    write_text_report(&dir, "sequence_core_candidate_registry.txt", registry)?;
    write_text_report(&dir, "gated_deltanet_core_contract.txt", gated_contract)?;
    write_text_report(&dir, "gated_deltanet_runtime_readiness_gate.txt", readiness)?;
    write_text_report(
        &dir,
        "gated_deltanet_data_dependency.txt",
        dependency_report,
    )?;
    write_text_report(
        &dir,
        "sequence_core_candidate_comparison_plan.txt",
        comparison,
    )?;
    write_text_report(
        &dir,
        "sequence_core_external_prototype_contract.txt",
        external_contract,
    )?;
    write_text_report(
        &dir,
        "training_data_storage_materialization.txt",
        materialization,
    )?;
    write_text_report(&dir, "training_data_storage_integrity_check.txt", integrity)?;
    write_text_report(
        &dir,
        "model_family_storage_contracts.txt",
        &model_family_storage_contracts,
    )?;
    write_text_report(&dir, "control_tower_sequence_core_panel.txt", panel)?;
    fs::write(dir.join("summary.txt"), final_summary).map_err(|err| err.to_string())?;
    let storage_bytes = fs::read_dir(&dir)
        .map_err(|err| err.to_string())?
        .filter_map(Result::ok)
        .filter_map(|entry| entry.metadata().ok().map(|meta| meta.len() as usize))
        .sum::<usize>();
    let storage_report = OperatorBriefingStorageReport {
        artifact_count: 12,
        storage_bytes,
        max_bytes: materialization_config.max_bytes as usize,
        within_budget: storage_bytes <= materialization_config.max_bytes as usize,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    };
    write_text_report(&dir, "storage_report.txt", &storage_report)?;
    let _ = registry_config.output_dir();
    Ok((storage_report, final_summary.to_string()))
}

fn load_sprint79_support_data(paths: &[String]) -> Result<Sprint79SupportData, String> {
    let mut support = Sprint79SupportData::default();
    for path in paths {
        let absolute = sprint76_absolutize(path);
        let text = fs::read_to_string(&absolute).map_err(|err| err.to_string())?;
        let parsed: Sprint79SupportInput =
            serde_json::from_str(&text).map_err(|err| err.to_string())?;
        if let Some(value) = parsed.mamba3fin_contract_state {
            support.mamba3fin_contract_state = value;
        }
        if let Some(value) = parsed.gated_deltanet_contract_expected {
            support.gated_deltanet_contract_expected = value;
        }
        if let Some(value) = parsed.training_data_storage_plan {
            support.training_data_storage_plan = value;
        }
        if let Some(value) = parsed.training_data_registry_spec {
            support.training_data_registry_spec = value;
        }
        if let Some(value) = parsed.committee_gate_state {
            support.committee_gate_state = value;
        }
        if let Some(value) = parsed.sequence_core_registry_expected {
            support.sequence_core_registry_expected = value;
        }
        if let Some(value) = parsed.storage_materialization_expected {
            support.storage_materialization_expected = value;
        }
    }
    Ok(support)
}

fn stable_sequence_core_candidates(
    candidates: &[SequenceCoreCandidateContract],
) -> Vec<SequenceCoreCandidateContract> {
    let mut candidates = candidates.to_vec();
    candidates.sort_by(|left, right| left.candidate_id.cmp(&right.candidate_id));
    candidates
}

fn stable_model_family_storage_contracts(
    contracts: &[ModelFamilyStorageContract],
) -> Vec<ModelFamilyStorageContract> {
    let mut contracts = contracts.to_vec();
    contracts
        .sort_by(|left, right| format!("{:?}", left.family).cmp(&format!("{:?}", right.family)));
    contracts
}

trait IteratorAllEqual: Iterator
where
    Self::Item: PartialEq,
    Self: Sized,
{
    fn all_equal(mut self) -> bool {
        let Some(first) = self.next() else {
            return true;
        };
        self.all(|item| item == first)
    }
}

impl<I> IteratorAllEqual for I
where
    I: Iterator,
    I::Item: PartialEq,
{
}

