impl Default for SequenceCorePrototypeComparisonConfig {
    fn default() -> Self {
        Self {
            comparison_id: "sprint80-sequence-core-prototype".to_string(),
            sequence_core_registry_paths: Vec::new(),
            training_storage_manifest_paths: Vec::new(),
            dataset_registry_paths: Vec::new(),
            sequence_export_manifest_paths: Vec::new(),
            feature_schema_manifest_paths: Vec::new(),
            label_manifest_paths: Vec::new(),
            split_manifest_paths: Vec::new(),
            no_lookahead_proof_paths: Vec::new(),
            mamba3fin_prediction_csv_paths: Vec::new(),
            gated_deltanet_prediction_csv_paths: Vec::new(),
            mamba3fin_model_card_paths: Vec::new(),
            gated_deltanet_model_card_paths: Vec::new(),
            committee_evidence_paths: Vec::new(),
            output_root: default_sequence_core_prototype_output_root(),
            max_prediction_rows: default_sequence_core_prototype_rows(),
            max_models: default_max_models(),
            max_bytes: default_storage_budget_bytes(),
            require_common_dataset: true,
            require_common_feature_schema: true,
            require_common_label_manifest: true,
            require_common_split: true,
            require_model_cards: true,
            require_prediction_schema: true,
            reason_codes: stable_reason_codes(&[
                ReasonCode::SequenceCorePrototypeComparisonConfigBuilt,
                ReasonCode::DeterministicPath,
                ReasonCode::LocalFileOnly,
            ]),
        }
    }
}

impl SequenceCorePrototypeComparisonConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.comparison_id.trim().is_empty() {
            return Err(
                "sequence core prototype comparison config requires comparison_id".to_string(),
            );
        }
        if !path_is_local(&self.output_root) {
            return Err("sequence core prototype comparison output_root must be local".to_string());
        }
        for path in self.all_support_paths() {
            if !path_is_local(&path) {
                return Err("sequence core prototype comparison paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(&path);
            if !absolute.exists() {
                return Err(format!(
                    "sequence core prototype comparison path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        if self.max_prediction_rows == 0 || self.max_models == 0 || self.max_bytes == 0 {
            return Err("sequence core prototype comparison limits must be positive".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.output_root).join(&self.comparison_id)
    }

    fn all_support_paths(&self) -> Vec<String> {
        stable_ordered_strings(
            &self
                .sequence_core_registry_paths
                .iter()
                .chain(self.training_storage_manifest_paths.iter())
                .chain(self.dataset_registry_paths.iter())
                .chain(self.sequence_export_manifest_paths.iter())
                .chain(self.feature_schema_manifest_paths.iter())
                .chain(self.label_manifest_paths.iter())
                .chain(self.split_manifest_paths.iter())
                .chain(self.no_lookahead_proof_paths.iter())
                .chain(self.mamba3fin_prediction_csv_paths.iter())
                .chain(self.gated_deltanet_prediction_csv_paths.iter())
                .chain(self.mamba3fin_model_card_paths.iter())
                .chain(self.gated_deltanet_model_card_paths.iter())
                .chain(self.committee_evidence_paths.iter())
                .cloned()
                .collect::<Vec<_>>(),
        )
    }
}

