#[derive(Clone, Debug, Default)]
pub struct SequenceCorePrototypeComparisonRunner;

impl CommitteeEvidenceExpansionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.expansion_id.trim().is_empty() {
            return Err("committee evidence expansion config requires expansion_id".to_string());
        }
        if !path_is_local(&self.output_root) {
            return Err("committee evidence expansion output_root must be local".to_string());
        }
        for path in self.all_support_paths() {
            if !path_is_local(&path) {
                return Err("committee evidence expansion paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(&path);
            if !absolute.exists() {
                return Err(format!(
                    "committee evidence expansion path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        if self.max_scenarios == 0 || self.max_rows == 0 || self.max_bytes == 0 {
            return Err("committee evidence expansion limits must be positive".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.output_root).join(&self.expansion_id)
    }

    fn all_support_paths(&self) -> Vec<String> {
        stable_ordered_strings(
            &self
                .committee_completion_gate_paths
                .iter()
                .chain(self.materialization_plan_paths.iter())
                .chain(self.real_evidence_paths.iter())
                .chain(self.sequence_export_manifest_paths.iter())
                .chain(self.outcome_reference_paths.iter())
                .chain(self.baseline_reference_paths.iter())
                .chain(self.no_trade_reference_paths.iter())
                .chain(self.risk_denied_reference_paths.iter())
                .cloned()
                .collect::<Vec<_>>(),
        )
    }
}

impl TrainingDataArtifactPopulationConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.population_id.trim().is_empty() {
            return Err(
                "training data artifact population config requires population_id".to_string(),
            );
        }
        for path in [self.storage_root.as_str(), self.output_root.as_str()] {
            if !path_is_local(path) {
                return Err("training data artifact population paths must be local".to_string());
            }
        }
        for path in self.all_support_paths() {
            if !path_is_local(&path) {
                return Err(
                    "training data artifact population support paths must be local".to_string(),
                );
            }
        }
        if self.max_artifacts == 0 || self.max_bytes == 0 {
            return Err("training data artifact population limits must be positive".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.output_root).join(&self.population_id)
    }

    pub fn storage_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.storage_root)
    }

    fn all_support_paths(&self) -> Vec<String> {
        stable_ordered_strings(
            &self
                .registry_manifest_paths
                .iter()
                .chain(self.sequence_export_manifest_paths.iter())
                .chain(self.feature_schema_manifest_paths.iter())
                .chain(self.label_manifest_paths.iter())
                .chain(self.split_manifest_paths.iter())
                .chain(self.prediction_csv_paths.iter())
                .chain(self.model_card_paths.iter())
                .chain(self.evaluation_report_paths.iter())
                .chain(self.committee_pack_paths.iter())
                .cloned()
                .collect::<Vec<_>>(),
        )
    }
}

