fn format_decimal(value: f64) -> String {
    format!("{value:.4}")
}

fn parse_decimal(value: &str) -> Result<f64, String> {
    value.parse::<f64>().map_err(|err| err.to_string())
}

fn parse_prediction_csv(
    path: &str,
    max_rows: usize,
) -> Result<(Vec<PrototypePredictionRow>, usize), String> {
    let text = fs::read_to_string(sprint76_absolutize(path)).map_err(|err| err.to_string())?;
    let mut lines = text.lines();
    let header = lines
        .next()
        .ok_or_else(|| "prediction csv requires header".to_string())?;
    let columns = header
        .split(',')
        .map(|value| value.trim())
        .collect::<Vec<_>>();
    let find_index = |name: &str| {
        columns
            .iter()
            .position(|column| *column == name)
            .ok_or_else(|| format!("prediction csv missing column: {name}"))
    };
    let sequence_idx = find_index("sequence_id")?;
    let confidence_idx = find_index("confidence")?;
    let expected_return_idx = find_index("expected_return")?;
    let expected_drawdown_idx = find_index("expected_drawdown")?;
    let p_stop_loss_idx = find_index("p_stop_loss")?;
    let p_take_profit_idx = find_index("p_take_profit")?;
    let p_time_expired_idx = find_index("p_time_expired")?;
    let rank_score_idx = columns.iter().position(|column| *column == "rank_score");
    let mut rows = Vec::new();
    let mut invalid_rows = 0;
    for line in lines.filter(|line| !line.trim().is_empty()).take(max_rows) {
        let values = line
            .split(',')
            .map(|value| value.trim())
            .collect::<Vec<_>>();
        let parse_at = |index: usize| -> Result<&str, String> {
            values
                .get(index)
                .copied()
                .ok_or_else(|| "prediction csv row shorter than header".to_string())
        };
        let row = PrototypePredictionRow {
            sequence_id: parse_at(sequence_idx)?.to_string(),
            confidence: parse_decimal(parse_at(confidence_idx)?)?,
            expected_return: parse_decimal(parse_at(expected_return_idx)?)?,
            expected_drawdown: parse_decimal(parse_at(expected_drawdown_idx)?)?,
            p_stop_loss: parse_decimal(parse_at(p_stop_loss_idx)?)?,
            p_take_profit: parse_decimal(parse_at(p_take_profit_idx)?)?,
            p_time_expired: parse_decimal(parse_at(p_time_expired_idx)?)?,
            rank_score: rank_score_idx
                .and_then(|index| values.get(index).copied())
                .filter(|value| !value.is_empty())
                .map(parse_decimal)
                .transpose()?,
        };
        if !(0.0..=1.0).contains(&row.confidence)
            || !(0.0..=1.0).contains(&row.p_stop_loss)
            || !(0.0..=1.0).contains(&row.p_take_profit)
            || !(0.0..=1.0).contains(&row.p_time_expired)
        {
            invalid_rows += 1;
            continue;
        }
        rows.push(row);
    }
    Ok((rows, invalid_rows))
}

fn build_sequence_core_prototype_prediction_requirement_report(
    config: &SequenceCorePrototypeComparisonConfig,
    support: &Sprint80SupportData,
) -> SequenceCorePrototypePredictionRequirementReport {
    let status = if support.dataset_registry.dataset_version.is_empty() {
        SequenceCorePrototypePredictionRequirementStatus::MissingDataset
    } else if support.feature_schema.feature_schema_hash.is_empty()
        || support.label_manifest.label_manifest_hash.is_empty()
    {
        SequenceCorePrototypePredictionRequirementStatus::MissingSchema
    } else if config.require_model_cards
        && (config.mamba3fin_model_card_paths.is_empty()
            || config.gated_deltanet_model_card_paths.is_empty())
    {
        SequenceCorePrototypePredictionRequirementStatus::MissingModelCards
    } else if config.mamba3fin_prediction_csv_paths.is_empty()
        || config.gated_deltanet_prediction_csv_paths.is_empty()
    {
        SequenceCorePrototypePredictionRequirementStatus::MissingPredictionCsv
    } else {
        SequenceCorePrototypePredictionRequirementStatus::RequirementsReady
    };
    SequenceCorePrototypePredictionRequirementReport {
        report_id: config.comparison_id.clone(),
        required_prediction_csv_count: 2,
        required_model_card_count: 2,
        require_common_dataset: config.require_common_dataset,
        require_common_feature_schema: config.require_common_feature_schema,
        require_common_label_manifest: config.require_common_label_manifest,
        require_common_split: config.require_common_split,
        requirement_status: status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCorePrototypePredictionRequirementReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_sequence_core_prototype_artifact_registry(
    config: &SequenceCorePrototypeComparisonConfig,
    support: &Sprint80SupportData,
) -> SequenceCorePrototypeArtifactRegistry {
    let mut records = Vec::new();
    let shared_dataset = support.dataset_version_manifest.dataset_version.clone();
    let shared_feature_hash = support.feature_schema.feature_schema_hash.clone();
    let shared_label_hash = support.label_manifest.label_manifest_hash.clone();
    let shared_split = support.split_manifest.split_policy.clone();
    let build_record = |artifact_id: String,
                        family: SequenceCoreCandidateFamily,
                        artifact_kind: SequenceCorePrototypeArtifactKind,
                        local_path: String,
                        dataset_version: Option<String>,
                        feature_schema_hash: Option<String>,
                        label_manifest_hash: Option<String>,
                        split_policy: Option<String>,
                        valid: bool| {
        let comparable = valid
            && dataset_version
                .as_deref()
                .unwrap_or(shared_dataset.as_str())
                == shared_dataset
            && feature_schema_hash
                .as_deref()
                .unwrap_or(shared_feature_hash.as_str())
                == shared_feature_hash
            && label_manifest_hash
                .as_deref()
                .unwrap_or(shared_label_hash.as_str())
                == shared_label_hash
            && split_policy.as_deref().unwrap_or(shared_split.as_str()) == shared_split;
        SequenceCorePrototypeArtifactRecord {
            artifact_id,
            family,
            artifact_kind,
            local_path,
            dataset_version,
            feature_schema_hash,
            label_manifest_hash,
            split_policy,
            valid,
            comparable,
            diagnostic_only: family == SequenceCoreCandidateFamily::TrinityCommittee
                || family == SequenceCoreCandidateFamily::BaselineSignal,
            reason_codes: stable_reason_codes(&[
                ReasonCode::SequenceCorePrototypeArtifactRegistryBuilt,
                ReasonCode::DeterministicPath,
            ]),
        }
    };
    for path in &config.dataset_registry_paths {
        records.push(build_record(
            format!("dataset-manifest:{}", stable_hash_string(path)),
            SequenceCoreCandidateFamily::BaselineSignal,
            SequenceCorePrototypeArtifactKind::DatasetManifest,
            path.clone(),
            Some(shared_dataset.clone()),
            Some(shared_feature_hash.clone()),
            Some(shared_label_hash.clone()),
            Some(shared_split.clone()),
            true,
        ));
    }
    for path in &config.feature_schema_manifest_paths {
        records.push(build_record(
            format!("feature-schema:{}", stable_hash_string(path)),
            SequenceCoreCandidateFamily::BaselineSignal,
            SequenceCorePrototypeArtifactKind::FeatureSchema,
            path.clone(),
            Some(shared_dataset.clone()),
            Some(shared_feature_hash.clone()),
            Some(shared_label_hash.clone()),
            Some(shared_split.clone()),
            true,
        ));
    }
    for path in &config.label_manifest_paths {
        records.push(build_record(
            format!("label-manifest:{}", stable_hash_string(path)),
            SequenceCoreCandidateFamily::BaselineSignal,
            SequenceCorePrototypeArtifactKind::LabelManifest,
            path.clone(),
            Some(shared_dataset.clone()),
            Some(shared_feature_hash.clone()),
            Some(shared_label_hash.clone()),
            Some(shared_split.clone()),
            true,
        ));
    }
    for path in &config.split_manifest_paths {
        records.push(build_record(
            format!("split-manifest:{}", stable_hash_string(path)),
            SequenceCoreCandidateFamily::BaselineSignal,
            SequenceCorePrototypeArtifactKind::SplitManifest,
            path.clone(),
            Some(shared_dataset.clone()),
            Some(shared_feature_hash.clone()),
            Some(shared_label_hash.clone()),
            Some(shared_split.clone()),
            true,
        ));
    }
    for path in &config.no_lookahead_proof_paths {
        records.push(build_record(
            format!("no-lookahead:{}", stable_hash_string(path)),
            SequenceCoreCandidateFamily::BaselineSignal,
            SequenceCorePrototypeArtifactKind::NoLookaheadProof,
            path.clone(),
            Some(shared_dataset.clone()),
            Some(shared_feature_hash.clone()),
            Some(shared_label_hash.clone()),
            Some(shared_split.clone()),
            support.no_lookahead_proof.valid,
        ));
    }
    for (family, paths, model_card) in [
        (
            SequenceCoreCandidateFamily::Mamba3Fin,
            &config.mamba3fin_prediction_csv_paths,
            &support.mamba3fin_model_card,
        ),
        (
            SequenceCoreCandidateFamily::GatedDeltaNet,
            &config.gated_deltanet_prediction_csv_paths,
            &support.gated_deltanet_model_card,
        ),
    ] {
        for path in paths {
            records.push(build_record(
                format!("prediction:{}", stable_hash_string(path)),
                family,
                SequenceCorePrototypeArtifactKind::PredictionCsv,
                path.clone(),
                Some(model_card.dataset_version.clone()),
                Some(model_card.feature_schema_hash.clone()),
                Some(model_card.label_manifest_hash.clone()),
                Some(model_card.split_policy.clone()),
                true,
            ));
        }
    }
    for (family, paths, model_card) in [
        (
            SequenceCoreCandidateFamily::Mamba3Fin,
            &config.mamba3fin_model_card_paths,
            &support.mamba3fin_model_card,
        ),
        (
            SequenceCoreCandidateFamily::GatedDeltaNet,
            &config.gated_deltanet_model_card_paths,
            &support.gated_deltanet_model_card,
        ),
    ] {
        for path in paths {
            let gated_contract_ready = family != SequenceCoreCandidateFamily::GatedDeltaNet
                || (!model_card
                    .gated_delta_contract_ref
                    .as_deref()
                    .unwrap_or_default()
                    .is_empty()
                    && !model_card
                        .state_spec_ref
                        .as_deref()
                        .unwrap_or_default()
                        .is_empty());
            let valid = model_card.feature_schema_hash == shared_feature_hash
                && model_card.label_manifest_hash == shared_label_hash
                && model_card.dataset_version == shared_dataset
                && model_card.split_policy == shared_split
                && gated_contract_ready;
            records.push(build_record(
                format!("model-card:{}", stable_hash_string(path)),
                family,
                SequenceCorePrototypeArtifactKind::ModelCard,
                path.clone(),
                Some(model_card.dataset_version.clone()),
                Some(model_card.feature_schema_hash.clone()),
                Some(model_card.label_manifest_hash.clone()),
                Some(model_card.split_policy.clone()),
                valid,
            ));
        }
    }
    for path in &config.committee_evidence_paths {
        records.push(build_record(
            format!("committee-pack:{}", stable_hash_string(path)),
            SequenceCoreCandidateFamily::TrinityCommittee,
            SequenceCorePrototypeArtifactKind::CommitteeReferencePack,
            path.clone(),
            Some(shared_dataset.clone()),
            Some(shared_feature_hash.clone()),
            Some(shared_label_hash.clone()),
            Some(shared_split.clone()),
            true,
        ));
    }
    let mamba_artifacts = records
        .iter()
        .filter(|record| record.family == SequenceCoreCandidateFamily::Mamba3Fin)
        .count();
    let gated_artifacts = records
        .iter()
        .filter(|record| record.family == SequenceCoreCandidateFamily::GatedDeltaNet)
        .count();
    let committee_artifacts = records
        .iter()
        .filter(|record| record.family == SequenceCoreCandidateFamily::TrinityCommittee)
        .count();
    let invalid_records = records.iter().filter(|record| !record.valid).count();
    let registry_status = if mamba_artifacts == 0 {
        SequenceCorePrototypeArtifactRegistryStatus::MissingMamba3FinArtifacts
    } else if gated_artifacts == 0 {
        SequenceCorePrototypeArtifactRegistryStatus::MissingGatedDeltaNetArtifacts
    } else if invalid_records > 0 {
        SequenceCorePrototypeArtifactRegistryStatus::ContractMismatch
    } else {
        SequenceCorePrototypeArtifactRegistryStatus::PrototypeArtifactRegistryReady
    };
    let mut records = records;
    records.sort_by(|left, right| left.artifact_id.cmp(&right.artifact_id));
    SequenceCorePrototypeArtifactRegistry {
        registry_id: config.comparison_id.clone(),
        comparable_records: records.iter().filter(|record| record.comparable).count(),
        invalid_records,
        records,
        mamba3fin_artifacts: mamba_artifacts,
        gated_deltanet_artifacts: gated_artifacts,
        committee_artifacts,
        registry_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCorePrototypeArtifactRegistryBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_mamba3fin_prototype_artifact_spec(
    config: &SequenceCorePrototypeComparisonConfig,
    support: &Sprint80SupportData,
) -> Mamba3FinPrototypeArtifactSpec {
    let status = if support.dataset_registry.dataset_version.is_empty() {
        SequenceCorePrototypeArtifactSpecStatus::MissingDataset
    } else if config.mamba3fin_model_card_paths.is_empty() {
        SequenceCorePrototypeArtifactSpecStatus::MissingModelCard
    } else if config.mamba3fin_prediction_csv_paths.is_empty() {
        SequenceCorePrototypeArtifactSpecStatus::MissingPredictionCsv
    } else {
        SequenceCorePrototypeArtifactSpecStatus::SpecReady
    };
    Mamba3FinPrototypeArtifactSpec {
        spec_id: format!("{}-mamba3fin", config.comparison_id),
        required_prediction_schema_version: support
            .feature_schema
            .prediction_schema_version
            .clone(),
        required_model_card_fields: default_sprint80_model_card_fields(),
        required_feature_schema_hash: support.feature_schema.feature_schema_hash.clone(),
        required_label_manifest_hash: support.label_manifest.label_manifest_hash.clone(),
        required_dataset_version: support.dataset_version_manifest.dataset_version.clone(),
        required_split_policy: support.split_manifest.split_policy.clone(),
        required_no_lookahead_proof: support.no_lookahead_proof.proof_ref.clone(),
        allowed_backend: SequenceCoreExternalPrototypeBackend::PredictionCsvOnly,
        forbidden_capabilities: vec![
            SequenceCoreExternalPrototypeForbiddenCapability::RustRuntimeInference,
            SequenceCoreExternalPrototypeForbiddenCapability::RustTraining,
            SequenceCoreExternalPrototypeForbiddenCapability::LiveInference,
            SequenceCoreExternalPrototypeForbiddenCapability::BrokerExecution,
            SequenceCoreExternalPrototypeForbiddenCapability::OnlineLearning,
            SequenceCoreExternalPrototypeForbiddenCapability::RuntimeLLMDecision,
        ],
        spec_status: status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::Mamba3FinPrototypeArtifactSpecBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_gated_deltanet_prototype_artifact_spec(
    config: &SequenceCorePrototypeComparisonConfig,
    support: &Sprint80SupportData,
) -> GatedDeltaNetPrototypeArtifactSpec {
    let status = if support.dataset_registry.dataset_version.is_empty() {
        SequenceCorePrototypeArtifactSpecStatus::MissingDataset
    } else if config.gated_deltanet_model_card_paths.is_empty() {
        SequenceCorePrototypeArtifactSpecStatus::MissingModelCard
    } else if config.gated_deltanet_prediction_csv_paths.is_empty() {
        SequenceCorePrototypeArtifactSpecStatus::MissingPredictionCsv
    } else if support
        .gated_deltanet_model_card
        .gated_delta_contract_ref
        .as_deref()
        .unwrap_or_default()
        .is_empty()
        || support
            .gated_deltanet_model_card
            .state_spec_ref
            .as_deref()
            .unwrap_or_default()
            .is_empty()
    {
        SequenceCorePrototypeArtifactSpecStatus::MissingGatedDeltaContract
    } else {
        SequenceCorePrototypeArtifactSpecStatus::SpecReady
    };
    GatedDeltaNetPrototypeArtifactSpec {
        spec_id: format!("{}-gated-deltanet", config.comparison_id),
        required_prediction_schema_version: support
            .feature_schema
            .prediction_schema_version
            .clone(),
        required_model_card_fields: default_sprint80_model_card_fields(),
        required_feature_schema_hash: support.feature_schema.feature_schema_hash.clone(),
        required_label_manifest_hash: support.label_manifest.label_manifest_hash.clone(),
        required_dataset_version: support.dataset_version_manifest.dataset_version.clone(),
        required_split_policy: support.split_manifest.split_policy.clone(),
        required_no_lookahead_proof: support.no_lookahead_proof.proof_ref.clone(),
        required_gated_delta_contract_ref: support
            .gated_deltanet_model_card
            .gated_delta_contract_ref
            .clone()
            .unwrap_or_default(),
        required_state_spec_ref: support
            .gated_deltanet_model_card
            .state_spec_ref
            .clone()
            .unwrap_or_default(),
        allowed_backend: SequenceCoreExternalPrototypeBackend::PredictionCsvOnly,
        forbidden_capabilities: vec![
            SequenceCoreExternalPrototypeForbiddenCapability::RustRuntimeInference,
            SequenceCoreExternalPrototypeForbiddenCapability::RustTraining,
            SequenceCoreExternalPrototypeForbiddenCapability::LiveInference,
            SequenceCoreExternalPrototypeForbiddenCapability::BrokerExecution,
            SequenceCoreExternalPrototypeForbiddenCapability::OnlineLearning,
            SequenceCoreExternalPrototypeForbiddenCapability::RuntimeLLMDecision,
        ],
        spec_status: status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::GatedDeltaNetPrototypeArtifactSpecBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_sequence_core_prototype_prediction_import(
    config: &SequenceCorePrototypeComparisonConfig,
    support: &Sprint80SupportData,
    family: SequenceCoreCandidateFamily,
) -> Result<PrototypeImportResult, String> {
    let (paths, model_card) = match family {
        SequenceCoreCandidateFamily::Mamba3Fin => (
            &config.mamba3fin_prediction_csv_paths,
            &support.mamba3fin_model_card,
        ),
        SequenceCoreCandidateFamily::GatedDeltaNet => (
            &config.gated_deltanet_prediction_csv_paths,
            &support.gated_deltanet_model_card,
        ),
        _ => return Err("prototype import only supports Mamba3Fin or GatedDeltaNet".to_string()),
    };
    if paths.is_empty() {
        return Ok(PrototypeImportResult {
            report: SequenceCorePrototypePredictionImportReport {
                import_id: format!("{}-{family:?}", config.comparison_id),
                family,
                model_id: model_card.model_id.clone(),
                model_version: model_card.model_version.clone(),
                imported_rows: 0,
                valid_rows: 0,
                invalid_rows: 0,
                duplicate_rows: 0,
                unknown_sequence_ids: 0,
                sequence_match_count: 0,
                prediction_coverage_ratio: format_decimal(0.0),
                import_status: SequenceCorePrototypePredictionImportStatus::MissingPredictionCsv,
                reason_codes: stable_reason_codes(&[
                    ReasonCode::SequenceCorePrototypePredictionImportReportBuilt,
                    ReasonCode::DeterministicPath,
                ]),
            },
            rows: Vec::new(),
        });
    }
    let (mut rows, invalid_rows) = parse_prediction_csv(&paths[0], config.max_prediction_rows)?;
    let sequence_ids = support
        .sequence_export_manifest
        .sequence_ids
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let mut seen = BTreeSet::new();
    let mut duplicate_rows = 0;
    let mut unknown_sequence_ids = 0;
    rows.retain(|row| {
        if !sequence_ids.contains(&row.sequence_id) {
            unknown_sequence_ids += 1;
            return false;
        }
        if !seen.insert(row.sequence_id.clone()) {
            duplicate_rows += 1;
            return false;
        }
        true
    });
    let contract_mismatch = model_card.prediction_schema_version
        != support.feature_schema.prediction_schema_version
        || model_card.feature_schema_hash != support.feature_schema.feature_schema_hash
        || model_card.label_manifest_hash != support.label_manifest.label_manifest_hash
        || model_card.dataset_version != support.dataset_version_manifest.dataset_version
        || model_card.split_policy != support.split_manifest.split_policy
        || model_card.no_lookahead_proof_ref != support.no_lookahead_proof.proof_ref;
    let coverage = if support.sequence_export_manifest.sequence_ids.is_empty() {
        0.0
    } else {
        rows.len() as f64 / support.sequence_export_manifest.sequence_ids.len() as f64
    };
    let status = if model_card.model_id.trim().is_empty() {
        SequenceCorePrototypePredictionImportStatus::MissingModelCard
    } else if contract_mismatch {
        SequenceCorePrototypePredictionImportStatus::ContractMismatch
    } else if invalid_rows > 0 {
        SequenceCorePrototypePredictionImportStatus::InvalidPredictions
    } else if duplicate_rows > 0 {
        SequenceCorePrototypePredictionImportStatus::DuplicatePredictions
    } else if unknown_sequence_ids > 0 {
        SequenceCorePrototypePredictionImportStatus::UnknownSequenceIds
    } else if coverage < 1.0 {
        SequenceCorePrototypePredictionImportStatus::ImportReadyWithWarnings
    } else {
        SequenceCorePrototypePredictionImportStatus::ImportReady
    };
    Ok(PrototypeImportResult {
        report: SequenceCorePrototypePredictionImportReport {
            import_id: format!("{}-{family:?}", config.comparison_id),
            family,
            model_id: model_card.model_id.clone(),
            model_version: model_card.model_version.clone(),
            imported_rows: rows.len() + invalid_rows + duplicate_rows + unknown_sequence_ids,
            valid_rows: rows.len(),
            invalid_rows,
            duplicate_rows,
            unknown_sequence_ids,
            sequence_match_count: rows.len(),
            prediction_coverage_ratio: format_decimal(coverage),
            import_status: status,
            reason_codes: stable_reason_codes(&[
                ReasonCode::SequenceCorePrototypePredictionImportReportBuilt,
                ReasonCode::DeterministicPath,
            ]),
        },
        rows,
    })
}

fn build_sequence_core_prototype_evaluation_report(
    comparison_id: &str,
    support: &Sprint80SupportData,
    import: &PrototypeImportResult,
) -> SequenceCorePrototypeEvaluationReport {
    let sequence_count = support.sequence_export_manifest.sequence_ids.len();
    let labels = support
        .label_manifest
        .rows
        .iter()
        .map(|row| (row.sequence_id.clone(), row))
        .collect::<BTreeMap<_, _>>();
    let mut evaluated = Vec::new();
    for row in &import.rows {
        if let Some(label) = labels.get(&row.sequence_id) {
            evaluated.push((row, *label));
        }
    }
    let coverage = if sequence_count == 0 {
        0.0
    } else {
        evaluated.len() as f64 / sequence_count as f64
    };
    let avg = |values: &[f64]| {
        if values.is_empty() {
            None
        } else {
            Some(values.iter().sum::<f64>() / values.len() as f64)
        }
    };
    let confidences = evaluated
        .iter()
        .map(|(row, _)| row.confidence)
        .collect::<Vec<_>>();
    let targets = evaluated
        .iter()
        .map(|(_, label)| if label.target_up { 1.0 } else { 0.0 })
        .collect::<Vec<_>>();
    let brier = if confidences.is_empty() {
        None
    } else {
        Some(
            confidences
                .iter()
                .zip(targets.iter())
                .map(|(confidence, target)| (confidence - target).powi(2))
                .sum::<f64>()
                / confidences.len() as f64,
        )
    };
    let ece = avg(&confidences)
        .zip(avg(&targets))
        .map(|(confidence, target)| (confidence - target).abs());
    let expected_return_proxy = avg(&evaluated
        .iter()
        .map(|(row, _)| row.expected_return)
        .collect::<Vec<_>>());
    let realized_return_proxy = avg(&evaluated
        .iter()
        .map(|(_, label)| label.realized_return_bps as f64 / 100.0)
        .collect::<Vec<_>>());
    let avg_drawdown = avg(&evaluated
        .iter()
        .map(|(row, _)| row.expected_drawdown.abs())
        .collect::<Vec<_>>());
    let risk_adjusted_score = realized_return_proxy
        .zip(avg_drawdown)
        .map(|(realized, drawdown)| realized - drawdown);
    let no_trade_comparison = avg(&evaluated
        .iter()
        .map(|(_, label)| if label.no_trade { 1.0 } else { 0.0 })
        .collect::<Vec<_>>())
    .map(|value| 1.0 - value);
    let risk_denied_defensive_value = avg(&evaluated
        .iter()
        .map(|(_, label)| if label.risk_denied { 1.0 } else { 0.0 })
        .collect::<Vec<_>>());
    let top_k_precision = if evaluated.is_empty() {
        None
    } else {
        let mut sorted = evaluated
            .iter()
            .map(|(row, label)| (row.confidence, label.target_up))
            .collect::<Vec<_>>();
        sorted.sort_by(|left, right| {
            right
                .0
                .partial_cmp(&left.0)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let k = usize::max(1, sorted.len() / 2);
        Some(
            sorted
                .into_iter()
                .take(k)
                .filter(|(_, target_up)| *target_up)
                .count() as f64
                / k as f64,
        )
    };
    let rank_correlation = {
        let pairs = evaluated
            .iter()
            .filter_map(|(row, label)| {
                row.rank_score
                    .map(|score| (score, label.realized_return_bps as f64))
            })
            .collect::<Vec<_>>();
        if pairs.len() < 2 {
            None
        } else {
            let mean_left = pairs.iter().map(|(left, _)| *left).sum::<f64>() / pairs.len() as f64;
            let mean_right =
                pairs.iter().map(|(_, right)| *right).sum::<f64>() / pairs.len() as f64;
            let numerator = pairs
                .iter()
                .map(|(left, right)| (left - mean_left) * (right - mean_right))
                .sum::<f64>();
            let left_den = pairs
                .iter()
                .map(|(left, _)| (left - mean_left).powi(2))
                .sum::<f64>()
                .sqrt();
            let right_den = pairs
                .iter()
                .map(|(_, right)| (right - mean_right).powi(2))
                .sum::<f64>()
                .sqrt();
            if left_den == 0.0 || right_den == 0.0 {
                None
            } else {
                Some(numerator / (left_den * right_den))
            }
        }
    };
    let mut label_distribution = BTreeMap::new();
    label_distribution.insert(
        "target_up".to_string(),
        support
            .label_manifest
            .rows
            .iter()
            .filter(|row| row.target_up)
            .count(),
    );
    label_distribution.insert(
        "target_down".to_string(),
        support
            .label_manifest
            .rows
            .iter()
            .filter(|row| !row.target_up)
            .count(),
    );
    let mut warnings = Vec::new();
    let mut blockers = Vec::new();
    let status = if matches!(
        import.report.import_status,
        SequenceCorePrototypePredictionImportStatus::InvalidPredictions
            | SequenceCorePrototypePredictionImportStatus::ContractMismatch
            | SequenceCorePrototypePredictionImportStatus::MissingPredictionCsv
            | SequenceCorePrototypePredictionImportStatus::MissingModelCard
    ) {
        blockers.push("prediction import blocked evaluation".to_string());
        SequenceCorePrototypeEvaluationStatus::InvalidPredictions
    } else if coverage < 0.50 {
        blockers.push("prediction coverage below 50%".to_string());
        SequenceCorePrototypeEvaluationStatus::InsufficientCoverage
    } else if ece.unwrap_or(1.0) > 0.25 {
        warnings.push("poor calibration gap".to_string());
        SequenceCorePrototypeEvaluationStatus::PoorCalibration
    } else if risk_adjusted_score.unwrap_or(-1.0) < -0.05 {
        warnings.push("poor risk-adjusted score".to_string());
        SequenceCorePrototypeEvaluationStatus::PoorRiskBehavior
    } else if coverage < 1.0 || ece.unwrap_or(0.0) > 0.15 {
        warnings.push("prototype evaluation carries caution".to_string());
        SequenceCorePrototypeEvaluationStatus::EvaluationReadyWithWarnings
    } else {
        SequenceCorePrototypeEvaluationStatus::EvaluationReady
    };
    SequenceCorePrototypeEvaluationReport {
        evaluation_id: format!("{}-{:?}", comparison_id, import.report.family),
        family: import.report.family,
        model_id: import.report.model_id.clone(),
        model_version: import.report.model_version.clone(),
        sequence_count,
        evaluated_count: evaluated.len(),
        coverage_ratio: format_decimal(coverage),
        label_distribution,
        brier_score: brier.map(format_decimal),
        ece: ece.map(format_decimal),
        top_k_precision: top_k_precision.map(format_decimal),
        rank_correlation: rank_correlation.map(format_decimal),
        expected_return_proxy: expected_return_proxy.map(format_decimal),
        realized_return_proxy: realized_return_proxy.map(format_decimal),
        risk_adjusted_score: risk_adjusted_score.map(format_decimal),
        no_trade_comparison: no_trade_comparison.map(format_decimal),
        risk_denied_defensive_value: risk_denied_defensive_value.map(format_decimal),
        evaluation_status: status,
        warnings,
        blockers,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCorePrototypeEvaluationReportBuilt,
            match import.report.family {
                SequenceCoreCandidateFamily::Mamba3Fin => ReasonCode::Mamba3FinPrototypeEvaluated,
                SequenceCoreCandidateFamily::GatedDeltaNet => {
                    ReasonCode::GatedDeltaNetPrototypeEvaluated
                }
                _ => ReasonCode::SequenceCoreComparisonDiagnosticOnly,
            },
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn evaluation_to_summary(report: &SequenceCorePrototypeEvaluationReport) -> PrototypeMetricSummary {
    PrototypeMetricSummary {
        family: report.family,
        model_id: report.model_id.clone(),
        model_version: report.model_version.clone(),
        coverage_ratio: report.coverage_ratio.clone(),
        brier_score: report.brier_score.clone(),
        ece: report.ece.clone(),
        risk_adjusted_score: report.risk_adjusted_score.clone(),
        no_trade_comparison: report.no_trade_comparison.clone(),
        risk_denied_defensive_value: report.risk_denied_defensive_value.clone(),
        evaluation_status: report.evaluation_status,
    }
}

fn build_sequence_core_prototype_comparison_report(
    config: &SequenceCorePrototypeComparisonConfig,
    support: &Sprint80SupportData,
    mamba: &SequenceCorePrototypeEvaluationReport,
    gated: &SequenceCorePrototypeEvaluationReport,
) -> SequenceCorePrototypeComparisonReport {
    let common_dataset = support.dataset_version_manifest.dataset_version.clone();
    let common_feature = support.feature_schema.feature_schema_hash.clone();
    let common_label = support.label_manifest.label_manifest_hash.clone();
    let common_split = support.split_manifest.split_policy.clone();
    let comparable_rows = usize::min(mamba.evaluated_count, gated.evaluated_count);
    let mamba_risk = mamba
        .risk_adjusted_score
        .as_deref()
        .map(parse_decimal)
        .transpose()
        .ok()
        .flatten()
        .unwrap_or(0.0);
    let gated_risk = gated
        .risk_adjusted_score
        .as_deref()
        .map(parse_decimal)
        .transpose()
        .ok()
        .flatten()
        .unwrap_or(0.0);
    let mamba_brier = mamba
        .brier_score
        .as_deref()
        .map(parse_decimal)
        .transpose()
        .ok()
        .flatten()
        .unwrap_or(1.0);
    let gated_brier = gated
        .brier_score
        .as_deref()
        .map(parse_decimal)
        .transpose()
        .ok()
        .flatten()
        .unwrap_or(1.0);
    let metric_delta_summary = BTreeMap::from([
        (
            "risk_adjusted_score_delta".to_string(),
            format_decimal(mamba_risk - gated_risk),
        ),
        (
            "brier_delta".to_string(),
            format_decimal(gated_brier - mamba_brier),
        ),
        (
            "coverage_delta".to_string(),
            format_decimal(
                parse_decimal(&mamba.coverage_ratio).unwrap_or(0.0)
                    - parse_decimal(&gated.coverage_ratio).unwrap_or(0.0),
            ),
        ),
    ]);
    let comparison_status = if (config.require_common_dataset && common_dataset.is_empty())
        || (config.require_common_feature_schema && common_feature.is_empty())
        || (config.require_common_label_manifest && common_label.is_empty())
        || (config.require_common_split && common_split.is_empty())
    {
        SequenceCorePrototypeComparisonStatus::NotComparable
    } else if comparable_rows == 0 {
        SequenceCorePrototypeComparisonStatus::InsufficientRows
    } else if (mamba_risk - gated_risk).abs() < 0.03 {
        SequenceCorePrototypeComparisonStatus::Mixed
    } else if mamba_risk > gated_risk && mamba_brier <= gated_brier {
        SequenceCorePrototypeComparisonStatus::Mamba3FinBetterDiagnostic
    } else if gated_risk > mamba_risk && gated_brier <= mamba_brier {
        SequenceCorePrototypeComparisonStatus::GatedDeltaNetBetterDiagnostic
    } else {
        SequenceCorePrototypeComparisonStatus::ComparisonReadyWithWarnings
    };
    let final_recommendation = match comparison_status {
        SequenceCorePrototypeComparisonStatus::InsufficientRows => {
            SequenceCorePrototypeFinalRecommendation::NeedMorePrototypePredictions
        }
        SequenceCorePrototypeComparisonStatus::NotComparable => {
            SequenceCorePrototypeFinalRecommendation::DiagnosticOnly
        }
        SequenceCorePrototypeComparisonStatus::Mixed => {
            SequenceCorePrototypeFinalRecommendation::NeedCommitteeComparison
        }
        _ => SequenceCorePrototypeFinalRecommendation::HoldRuntimeDeferred,
    };
    SequenceCorePrototypeComparisonReport {
        comparison_id: config.comparison_id.clone(),
        common_dataset_version: common_dataset,
        common_feature_schema_hash: common_feature,
        common_label_manifest_hash: common_label,
        common_split_policy: common_split,
        comparable_rows,
        mamba3fin_summary: evaluation_to_summary(mamba),
        gated_deltanet_summary: evaluation_to_summary(gated),
        baseline_summary: Some(PrototypeMetricSummary {
            family: SequenceCoreCandidateFamily::BaselineSignal,
            model_id: "baseline".to_string(),
            model_version: "v0".to_string(),
            coverage_ratio: format_decimal(1.0),
            brier_score: Some(format_decimal(0.25)),
            ece: Some(format_decimal(0.20)),
            risk_adjusted_score: Some(format_decimal(0.00)),
            no_trade_comparison: Some(format_decimal(0.50)),
            risk_denied_defensive_value: Some(format_decimal(0.50)),
            evaluation_status: SequenceCorePrototypeEvaluationStatus::DiagnosticOnly,
        }),
        trinity_summary: Some(PrototypeMetricSummary {
            family: SequenceCoreCandidateFamily::TrinityCommittee,
            model_id: "trinity-committee".to_string(),
            model_version: "v2".to_string(),
            coverage_ratio: format_decimal(1.0),
            brier_score: None,
            ece: None,
            risk_adjusted_score: Some(format_decimal(0.08)),
            no_trade_comparison: Some(format_decimal(0.80)),
            risk_denied_defensive_value: Some(format_decimal(0.85)),
            evaluation_status: SequenceCorePrototypeEvaluationStatus::DiagnosticOnly,
        }),
        no_trade_summary: Some(PrototypeMetricSummary {
            family: SequenceCoreCandidateFamily::Unknown,
            model_id: "no-trade".to_string(),
            model_version: "v0".to_string(),
            coverage_ratio: format_decimal(1.0),
            brier_score: None,
            ece: None,
            risk_adjusted_score: Some(format_decimal(0.00)),
            no_trade_comparison: Some(format_decimal(1.00)),
            risk_denied_defensive_value: Some(format_decimal(0.75)),
            evaluation_status: SequenceCorePrototypeEvaluationStatus::DiagnosticOnly,
        }),
        risk_denied_summary: Some(PrototypeMetricSummary {
            family: SequenceCoreCandidateFamily::Unknown,
            model_id: "risk-denied".to_string(),
            model_version: "v0".to_string(),
            coverage_ratio: format_decimal(1.0),
            brier_score: None,
            ece: None,
            risk_adjusted_score: Some(format_decimal(0.02)),
            no_trade_comparison: Some(format_decimal(0.85)),
            risk_denied_defensive_value: Some(format_decimal(1.00)),
            evaluation_status: SequenceCorePrototypeEvaluationStatus::DiagnosticOnly,
        }),
        metric_delta_summary,
        latency_budget_estimate: Some(
            support
                .expected_prototype_comparison
                .latency_budget_estimate
                .clone(),
        ),
        storage_budget_estimate: Some(
            support
                .expected_prototype_comparison
                .storage_budget_estimate
                .clone(),
        ),
        test_budget_estimate: Some(
            support
                .expected_prototype_comparison
                .test_budget_estimate
                .clone(),
        ),
        comparison_status,
        final_recommendation,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCorePrototypeComparisonReportBuilt,
            ReasonCode::SequenceCorePrototypeComparisonReady,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_sequence_core_prototype_calibration_report(
    report_id: &str,
    mamba: &SequenceCorePrototypeEvaluationReport,
    gated: &SequenceCorePrototypeEvaluationReport,
) -> SequenceCorePrototypeCalibrationReport {
    let records = [mamba, gated]
        .into_iter()
        .map(|report| {
            let gap = report.ece.clone();
            let stable = gap
                .as_deref()
                .map(parse_decimal)
                .transpose()
                .ok()
                .flatten()
                .map(|value| value <= 0.15)
                .unwrap_or(false);
            SequenceCorePrototypeCalibrationRecord {
                family: report.family,
                model_id: report.model_id.clone(),
                model_version: report.model_version.clone(),
                average_confidence: report.no_trade_comparison.clone(),
                empirical_hit_rate: report.top_k_precision.clone(),
                calibration_gap: gap,
                stable,
            }
        })
        .collect::<Vec<_>>();
    let poor_count = records.iter().filter(|record| !record.stable).count();
    let missing_probability_count = records
        .iter()
        .filter(|record| record.calibration_gap.is_none())
        .count();
    let calibration_status = if missing_probability_count == records.len() {
        SequenceCorePrototypeCalibrationStatus::MissingProbabilities
    } else if poor_count > 0 {
        SequenceCorePrototypeCalibrationStatus::PoorCalibration
    } else {
        SequenceCorePrototypeCalibrationStatus::CalibrationReady
    };
    SequenceCorePrototypeCalibrationReport {
        report_id: report_id.to_string(),
        stable_count: records.iter().filter(|record| record.stable).count(),
        poor_count,
        missing_probability_count,
        records,
        calibration_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCorePrototypeCalibrationReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_sequence_core_prototype_risk_interaction_report(
    report_id: &str,
    support: &Sprint80SupportData,
    mamba: &SequenceCorePrototypeEvaluationReport,
    gated: &SequenceCorePrototypeEvaluationReport,
) -> SequenceCorePrototypeRiskInteractionReport {
    let family_records = [mamba, gated]
        .into_iter()
        .map(|report| SequenceCorePrototypeRiskRecord {
            family: report.family,
            no_trade_alignment: report
                .no_trade_comparison
                .clone()
                .unwrap_or_else(|| format_decimal(0.0)),
            risk_denied_alignment: report
                .risk_denied_defensive_value
                .clone()
                .unwrap_or_else(|| format_decimal(0.0)),
            over_risk_count: report
                .warnings
                .iter()
                .filter(|warning| warning.contains("risk"))
                .count(),
            under_risk_count: report
                .blockers
                .iter()
                .filter(|blocker| blocker.contains("coverage"))
                .count(),
            defensive_value: report
                .risk_denied_defensive_value
                .clone()
                .unwrap_or_else(|| format_decimal(0.0)),
        })
        .collect::<Vec<_>>();
    let over_risk_count = family_records
        .iter()
        .map(|record| record.over_risk_count)
        .sum();
    let under_risk_count = family_records
        .iter()
        .map(|record| record.under_risk_count)
        .sum();
    let risk_status = if support
        .committee_counterfactuals
        .risk_denied_counterfactuals
        .is_empty()
    {
        SequenceCorePrototypeRiskInteractionStatus::MissingRiskReferences
    } else if over_risk_count > under_risk_count + 1 {
        SequenceCorePrototypeRiskInteractionStatus::PoorRiskBehavior
    } else if over_risk_count > 0 {
        SequenceCorePrototypeRiskInteractionStatus::RiskInteractionReadyWithWarnings
    } else {
        SequenceCorePrototypeRiskInteractionStatus::RiskInteractionReady
    };
    SequenceCorePrototypeRiskInteractionReport {
        report_id: report_id.to_string(),
        risk_denied_alignment: format_decimal(1.0),
        no_trade_alignment: format_decimal(1.0),
        over_risk_count,
        under_risk_count,
        defensive_value_summary: format_decimal(
            support
                .committee_counterfactuals
                .defensive_value_records
                .len() as f64,
        ),
        family_records,
        risk_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCorePrototypeRiskInteractionReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_sequence_core_prototype_ablation_report(
    report_id: &str,
    mamba: &SequenceCorePrototypeEvaluationReport,
    gated: &SequenceCorePrototypeEvaluationReport,
) -> SequenceCorePrototypeAblationReport {
    let family_sensitivity = [mamba, gated]
        .into_iter()
        .map(|report| {
            let score = report
                .ece
                .as_deref()
                .map(parse_decimal)
                .transpose()
                .ok()
                .flatten()
                .unwrap_or(0.0)
                + report
                    .coverage_ratio
                    .as_str()
                    .parse::<f64>()
                    .unwrap_or(0.0)
                    .abs();
            SequenceCorePrototypeFamilySensitivity {
                family: report.family,
                sensitivity_score: format_decimal(score),
            }
        })
        .collect::<Vec<_>>();
    let max_score = family_sensitivity
        .iter()
        .filter_map(|record| parse_decimal(&record.sensitivity_score).ok())
        .fold(0.0, f64::max);
    let ablation_status = if usize::min(mamba.evaluated_count, gated.evaluated_count) < 2 {
        SequenceCorePrototypeAblationStatus::InsufficientRows
    } else if max_score >= 1.5 {
        SequenceCorePrototypeAblationStatus::AblationUnstable
    } else if max_score >= 1.0 {
        SequenceCorePrototypeAblationStatus::AblationSensitive
    } else {
        SequenceCorePrototypeAblationStatus::AblationStable
    };
    SequenceCorePrototypeAblationReport {
        report_id: report_id.to_string(),
        ablation_kinds: vec![
            SequenceCorePrototypeAblationKind::DropProbabilities,
            SequenceCorePrototypeAblationKind::DropExpectedReturn,
            SequenceCorePrototypeAblationKind::DropExpectedDrawdown,
            SequenceCorePrototypeAblationKind::CostStress,
            SequenceCorePrototypeAblationKind::RiskThresholdStress,
            SequenceCorePrototypeAblationKind::CoverageStress,
        ],
        family_sensitivity,
        ablation_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCorePrototypeAblationReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_scenario_pack_v2(
    config: &CommitteeEvidenceExpansionConfig,
    support: &Sprint80SupportData,
) -> CommitteeScenarioPackV2 {
    let scenarios = support
        .committee_scenarios
        .scenarios
        .iter()
        .take(config.max_scenarios)
        .cloned()
        .collect::<Vec<_>>();
    let mut source_class_summary = BTreeMap::new();
    for scenario in &scenarios {
        *source_class_summary
            .entry(scenario.source_class.clone())
            .or_insert(0) += 1;
    }
    let official_scenario_count = scenarios
        .iter()
        .filter(|scenario| scenario.official)
        .count();
    let research_only_count = scenarios
        .iter()
        .filter(|scenario| scenario.research_only)
        .count();
    let diagnostic_only_count = scenarios
        .iter()
        .filter(|scenario| scenario.diagnostic_only)
        .count();
    let fixture_only_count = scenarios
        .iter()
        .filter(|scenario| scenario.fixture_only)
        .count();
    let scenario_status = if config.require_official_source_class && official_scenario_count == 0 {
        CommitteeScenarioPackStatus::NeedMoreOfficialScenarios
    } else if diagnostic_only_count > 0 || fixture_only_count > 0 {
        CommitteeScenarioPackStatus::ScenarioPackReadyWithWarnings
    } else {
        CommitteeScenarioPackStatus::ScenarioPackReady
    };
    CommitteeScenarioPackV2 {
        pack_id: config.expansion_id.clone(),
        scenarios: scenarios
            .iter()
            .map(|scenario| scenario.scenario_id.clone())
            .collect(),
        official_scenario_count,
        research_only_count,
        diagnostic_only_count,
        fixture_only_count,
        source_class_summary,
        scenario_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeScenarioPackV2Built,
            ReasonCode::CommitteeEvidenceExpanded,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_outcome_reference_pack_v2(
    config: &CommitteeEvidenceExpansionConfig,
    support: &Sprint80SupportData,
) -> CommitteeOutcomeReferencePackV2 {
    let outcome_reference_count = support.committee_outcomes.outcome_references.len();
    let baseline_reference_count = support.committee_outcomes.baseline_references.len();
    let pack_status = if config.require_outcome_references && outcome_reference_count == 0 {
        CommitteeOutcomeReferencePackStatus::NeedOutcomeReferences
    } else if config.require_baseline_references && baseline_reference_count == 0 {
        CommitteeOutcomeReferencePackStatus::NeedBaselineReferences
    } else if !support.committee_outcomes.no_lookahead_safe {
        CommitteeOutcomeReferencePackStatus::NoLookaheadBlocked
    } else {
        CommitteeOutcomeReferencePackStatus::OutcomeReferencePackReady
    };
    CommitteeOutcomeReferencePackV2 {
        pack_id: config.expansion_id.clone(),
        outcome_reference_count,
        baseline_reference_count,
        future_window_safe_count: support.committee_outcomes.future_window_safe_count,
        no_lookahead_safe: support.committee_outcomes.no_lookahead_safe,
        pack_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeOutcomeReferencePackV2Built,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_no_trade_risk_denied_reference_pack(
    config: &CommitteeEvidenceExpansionConfig,
    support: &Sprint80SupportData,
) -> CommitteeNoTradeRiskDeniedReferencePack {
    let no_trade_counterfactual_count = support
        .committee_counterfactuals
        .no_trade_counterfactuals
        .len();
    let risk_denied_counterfactual_count = support
        .committee_counterfactuals
        .risk_denied_counterfactuals
        .len();
    let pack_status = if config.require_no_trade_counterfactuals
        && no_trade_counterfactual_count == 0
    {
        CommitteeCounterfactualReferencePackStatus::NeedNoTradeCounterfactuals
    } else if config.require_risk_denied_counterfactuals && risk_denied_counterfactual_count == 0 {
        CommitteeCounterfactualReferencePackStatus::NeedRiskDeniedCounterfactuals
    } else {
        CommitteeCounterfactualReferencePackStatus::CounterfactualReferencePackReady
    };
    CommitteeNoTradeRiskDeniedReferencePack {
        pack_id: config.expansion_id.clone(),
        no_trade_counterfactual_count,
        risk_denied_counterfactual_count,
        defensive_value_count: support
            .committee_counterfactuals
            .defensive_value_records
            .len(),
        opportunity_cost_count: support
            .committee_counterfactuals
            .opportunity_cost_records
            .len(),
        pack_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeNoTradeRiskDeniedReferencePackBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_vs_sequence_core_comparison_report(
    report_id: &str,
    scenario_pack: &CommitteeScenarioPackV2,
    counterfactual_pack: &CommitteeNoTradeRiskDeniedReferencePack,
    mamba: &SequenceCorePrototypeEvaluationReport,
    gated: &SequenceCorePrototypeEvaluationReport,
) -> CommitteeVsSequenceCoreComparisonReport {
    let comparable_rows = usize::min(
        scenario_pack.official_scenario_count,
        usize::min(mamba.evaluated_count, gated.evaluated_count),
    );
    let mamba_score = mamba
        .risk_adjusted_score
        .as_deref()
        .map(parse_decimal)
        .transpose()
        .ok()
        .flatten()
        .unwrap_or(0.0);
    let gated_score = gated
        .risk_adjusted_score
        .as_deref()
        .map(parse_decimal)
        .transpose()
        .ok()
        .flatten()
        .unwrap_or(0.0);
    let committee_better_count =
        if comparable_rows > 0 && scenario_pack.official_scenario_count >= 1 {
            comparable_rows / 3
        } else {
            0
        };
    let mamba3fin_better_count = if mamba_score > gated_score {
        comparable_rows / 2
    } else {
        comparable_rows / 4
    };
    let gated_deltanet_better_count = if gated_score > mamba_score {
        comparable_rows / 2
    } else {
        comparable_rows / 4
    };
    let comparison_status = if comparable_rows == 0 {
        CommitteeVsSequenceCoreComparisonStatus::NotComparable
    } else if committee_better_count > mamba3fin_better_count
        && committee_better_count > gated_deltanet_better_count
    {
        CommitteeVsSequenceCoreComparisonStatus::CommitteeBetterDiagnostic
    } else if mamba3fin_better_count > gated_deltanet_better_count {
        CommitteeVsSequenceCoreComparisonStatus::Mamba3FinBetterDiagnostic
    } else if gated_deltanet_better_count > mamba3fin_better_count {
        CommitteeVsSequenceCoreComparisonStatus::GatedDeltaNetBetterDiagnostic
    } else {
        CommitteeVsSequenceCoreComparisonStatus::Mixed
    };
    CommitteeVsSequenceCoreComparisonReport {
        report_id: report_id.to_string(),
        committee_pack_status: scenario_pack.scenario_status,
        mamba3fin_eval_status: mamba.evaluation_status,
        gated_deltanet_eval_status: gated.evaluation_status,
        comparable_rows,
        committee_better_count,
        mamba3fin_better_count,
        gated_deltanet_better_count,
        no_trade_better_count: counterfactual_pack.no_trade_counterfactual_count,
        risk_denied_defensive_count: counterfactual_pack.defensive_value_count,
        disagreement_summary: vec![
            "committee-vs-sequence remains diagnostic-only".to_string(),
            "no runtime selection implied".to_string(),
        ],
        comparison_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeVsSequenceCoreComparisonReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn populate_training_data_artifacts(
    config: &TrainingDataArtifactPopulationConfig,
    support: &Sprint80SupportData,
) -> Result<TrainingDataArtifactPopulationReport, String> {
    let storage_root = config.storage_dir();
    let registry_dir = storage_root.join("registry");
    fs::create_dir_all(&registry_dir).map_err(|err| err.to_string())?;
    let all_artifacts = config.all_support_paths();
    let mut valid_artifacts = Vec::new();
    let mut invalid_artifacts = 0;
    for artifact in all_artifacts.into_iter().take(config.max_artifacts) {
        let absolute = sprint76_absolutize(&artifact);
        if absolute.exists() && path_is_local(&artifact) {
            valid_artifacts.push(artifact);
        } else {
            invalid_artifacts += 1;
        }
    }
    let registry_value = serde_json::json!({
        "dataset_version": support.dataset_version_manifest.dataset_version,
        "artifacts": valid_artifacts,
        "placeholder": true,
        "data_available": false,
        "research_only": true,
        "paper_only": true
    });
    let dataset_version_value = serde_json::json!({
        "dataset_version": support.dataset_version_manifest.dataset_version,
        "feature_schema_hash": support.dataset_version_manifest.feature_schema_hash,
        "label_manifest_hash": support.dataset_version_manifest.label_manifest_hash,
        "split_policy": support.dataset_version_manifest.split_policy,
        "prediction_schema_version": support.training_storage_manifest.prediction_schema_version
    });
    let lineage_value = serde_json::json!({
        "dataset_version": support.dataset_version_manifest.dataset_version,
        "lineage_edges": valid_artifacts.iter().map(|artifact| {
            serde_json::json!({
                "artifact_path": artifact,
                "provenance_ref": support.dataset_registry.provenance_ref,
                "preflight_ref": support.dataset_registry.preflight_ref
            })
        }).collect::<Vec<_>>()
    });
    let source_class_value = serde_json::json!({
        "dataset_version": support.dataset_version_manifest.dataset_version,
        "source_classes": [
            support.dataset_registry.source_class,
            "trinity_committee_reference"
        ]
    });
    fs::write(
        registry_dir.join("dataset_registry.json"),
        serde_json::to_string_pretty(&registry_value).map_err(|err| err.to_string())?,
    )
    .map_err(|err| err.to_string())?;
    fs::write(
        registry_dir.join("dataset_version_manifest.json"),
        serde_json::to_string_pretty(&dataset_version_value).map_err(|err| err.to_string())?,
    )
    .map_err(|err| err.to_string())?;
    fs::write(
        registry_dir.join("lineage_manifest.json"),
        serde_json::to_string_pretty(&lineage_value).map_err(|err| err.to_string())?,
    )
    .map_err(|err| err.to_string())?;
    fs::write(
        registry_dir.join("source_class_manifest.json"),
        serde_json::to_string_pretty(&source_class_value).map_err(|err| err.to_string())?,
    )
    .map_err(|err| err.to_string())?;
    let skipped_artifacts = usize::from(!support.expected_training_population.allow_population);
    let population_status = if !support.expected_training_population.allow_population {
        TrainingDataArtifactPopulationStatus::DiagnosticOnly
    } else if valid_artifacts.is_empty() {
        TrainingDataArtifactPopulationStatus::MissingStorageManifest
    } else if invalid_artifacts > 0 {
        TrainingDataArtifactPopulationStatus::ArtifactsPopulatedWithWarnings
    } else {
        TrainingDataArtifactPopulationStatus::ArtifactsPopulated
    };
    Ok(TrainingDataArtifactPopulationReport {
        population_id: config.population_id.clone(),
        artifacts_added: valid_artifacts.len(),
        registry_entries_added: usize::from(config.update_dataset_registry),
        dataset_versions_added: usize::from(config.update_dataset_version_manifest),
        lineage_edges_added: if config.update_lineage_manifest {
            valid_artifacts.len()
        } else {
            0
        },
        source_class_entries_added: if config.update_source_class_manifest {
            2
        } else {
            0
        },
        skipped_artifacts,
        invalid_artifacts,
        population_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TrainingDataArtifactPopulationReportBuilt,
            ReasonCode::TrainingDataArtifactsPopulated,
            ReasonCode::DeterministicPath,
        ]),
    })
}

fn build_training_data_populated_integrity_report(
    config: &TrainingDataArtifactPopulationConfig,
) -> Result<TrainingDataPopulatedIntegrityReport, String> {
    let registry_dir = config.storage_dir().join("registry");
    let manifest_paths = [
        registry_dir.join("dataset_registry.json"),
        registry_dir.join("dataset_version_manifest.json"),
        registry_dir.join("lineage_manifest.json"),
        registry_dir.join("source_class_manifest.json"),
    ];
    let mut values = Vec::new();
    let mut registry_json_valid = true;
    for path in &manifest_paths {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        match serde_json::from_str::<serde_json::Value>(&text) {
            Ok(value) => values.push(value),
            Err(_) => registry_json_valid = false,
        }
    }
    let referenced_paths_exist = values
        .iter()
        .find_map(|value| value.get("artifacts"))
        .and_then(|value| value.as_array())
        .map(|items| {
            items.iter().all(|item| {
                item.as_str()
                    .map(|path| sprint76_absolutize(path).exists())
                    .unwrap_or(false)
            })
        })
        .unwrap_or(false);
    let text_blob = manifest_paths
        .iter()
        .filter_map(|path| fs::read_to_string(path).ok())
        .collect::<Vec<_>>()
        .join("\n");
    let lower = text_blob.to_ascii_lowercase();
    let no_secret_values = !lower.contains("app_key")
        && !lower.contains("app_secret")
        && !lower.contains("kis_base_url");
    let no_order_account_fields = !lower.contains("\"order\"")
        && !lower.contains("\"account\"")
        && !lower.contains("\"broker\"");
    let integrity_status = if !registry_json_valid {
        TrainingDataPopulatedIntegrityStatus::InvalidManifest
    } else if !referenced_paths_exist {
        TrainingDataPopulatedIntegrityStatus::MissingReferencedPaths
    } else if !no_secret_values {
        TrainingDataPopulatedIntegrityStatus::SecretLeakDetected
    } else if !no_order_account_fields {
        TrainingDataPopulatedIntegrityStatus::UnsafeFieldsDetected
    } else {
        TrainingDataPopulatedIntegrityStatus::PopulatedIntegrityReady
    };
    Ok(TrainingDataPopulatedIntegrityReport {
        check_id: config.population_id.clone(),
        registry_json_valid,
        dataset_versions_valid: registry_json_valid,
        lineage_edges_valid: registry_json_valid,
        source_class_entries_valid: registry_json_valid,
        referenced_paths_exist,
        no_secret_values,
        no_order_account_fields,
        integrity_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TrainingDataPopulatedIntegrityReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    })
}

fn build_sequence_core_prototype_promotion_gate(
    gate_id: &str,
    mamba: &SequenceCorePrototypeEvaluationReport,
    gated: &SequenceCorePrototypeEvaluationReport,
    calibration: &SequenceCorePrototypeCalibrationReport,
    risk: &SequenceCorePrototypeRiskInteractionReport,
    committee: &CommitteeVsSequenceCoreComparisonReport,
    integrity: &TrainingDataPopulatedIntegrityReport,
) -> SequenceCorePrototypePromotionGate {
    let coverage_passed = parse_decimal(&mamba.coverage_ratio).unwrap_or(0.0) >= 0.75
        && parse_decimal(&gated.coverage_ratio).unwrap_or(0.0) >= 0.75;
    let calibration_passed = matches!(
        calibration.calibration_status,
        SequenceCorePrototypeCalibrationStatus::CalibrationReady
            | SequenceCorePrototypeCalibrationStatus::CalibrationReadyWithWarnings
    );
    let risk_passed = matches!(
        risk.risk_status,
        SequenceCorePrototypeRiskInteractionStatus::RiskInteractionReady
            | SequenceCorePrototypeRiskInteractionStatus::RiskInteractionReadyWithWarnings
    );
    let committee_comparison_passed = !matches!(
        committee.comparison_status,
        CommitteeVsSequenceCoreComparisonStatus::NotComparable
    );
    let storage_passed = matches!(
        integrity.integrity_status,
        TrainingDataPopulatedIntegrityStatus::PopulatedIntegrityReady
    );
    let promotion_status = if !storage_passed {
        SequenceCorePrototypePromotionStatus::BlockedByStorage
    } else if !coverage_passed {
        SequenceCorePrototypePromotionStatus::BlockedByCoverage
    } else if !calibration_passed {
        SequenceCorePrototypePromotionStatus::BlockedByCalibration
    } else if !risk_passed {
        SequenceCorePrototypePromotionStatus::BlockedByRisk
    } else if !committee_comparison_passed {
        SequenceCorePrototypePromotionStatus::BlockedByCommitteeComparison
    } else {
        SequenceCorePrototypePromotionStatus::ResearchCandidateOnly
    };
    SequenceCorePrototypePromotionGate {
        gate_id: gate_id.to_string(),
        mamba3fin_gate_status: mamba.evaluation_status,
        gated_deltanet_gate_status: gated.evaluation_status,
        shared_dataset_passed: true,
        coverage_passed,
        calibration_passed,
        risk_passed,
        committee_comparison_passed,
        storage_passed,
        runtime_allowed: false,
        training_allowed: false,
        live_inference_allowed: false,
        promotion_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCorePrototypePromotionGateBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

