fn build_sequence_core_prototype_summary(
    comparison: &SequenceCorePrototypeComparisonReport,
    committee: &CommitteeVsSequenceCoreComparisonReport,
    population: &TrainingDataArtifactPopulationReport,
    integrity: &TrainingDataPopulatedIntegrityReport,
    promotion: &SequenceCorePrototypePromotionGate,
) -> String {
    format!(
        "prototype_comparison_status={:?}\ncommittee_comparison_status={:?}\nartifact_population_status={:?}\npopulated_integrity_status={:?}\npromotion_status={:?}\nrecommendations={}",
        comparison.comparison_status,
        committee.comparison_status,
        population.population_status,
        integrity.integrity_status,
        promotion.promotion_status,
        stable_ordered_strings(&[
            "CommitteeEvidenceExpanded".to_string(),
            "GatedDeltaNetPrototypeEvaluated".to_string(),
            "HoldGatedDeltaNetRuntimeDeferred".to_string(),
            "HoldMambaRuntimeDeferred".to_string(),
            "KeepPaperOnly".to_string(),
            "KeepResearchOnly".to_string(),
            "KeepTrinity".to_string(),
            "Mamba3FinPrototypeEvaluated".to_string(),
            "NeedMoreRealEvidence".to_string(),
            "SequenceCoreComparisonDiagnosticOnly".to_string(),
            "SequenceCorePrototypeComparisonReady".to_string(),
            "TrainingDataArtifactsPopulated".to_string(),
        ])
        .join(" | "),
    )
}

fn write_sequence_core_prototype_bundle(
    config: &SequenceCorePrototypeComparisonConfig,
    registry: &SequenceCorePrototypeArtifactRegistry,
    mamba_spec: &Mamba3FinPrototypeArtifactSpec,
    gated_spec: &GatedDeltaNetPrototypeArtifactSpec,
    mamba_import: &SequenceCorePrototypePredictionImportReport,
    gated_import: &SequenceCorePrototypePredictionImportReport,
    mamba_eval: &SequenceCorePrototypeEvaluationReport,
    gated_eval: &SequenceCorePrototypeEvaluationReport,
    comparison: &SequenceCorePrototypeComparisonReport,
    calibration: &SequenceCorePrototypeCalibrationReport,
    risk: &SequenceCorePrototypeRiskInteractionReport,
    ablation: &SequenceCorePrototypeAblationReport,
    promotion: &SequenceCorePrototypePromotionGate,
    committee_scenario: &CommitteeScenarioPackV2,
    committee_outcome: &CommitteeOutcomeReferencePackV2,
    committee_counterfactual: &CommitteeNoTradeRiskDeniedReferencePack,
    committee_vs_sequence: &CommitteeVsSequenceCoreComparisonReport,
    population: &TrainingDataArtifactPopulationReport,
    integrity: &TrainingDataPopulatedIntegrityReport,
    panel: &ControlTowerSequencePrototypePanel,
    final_summary: &str,
) -> Result<(OperatorBriefingStorageReport, String), String> {
    let dir = config.output_dir();
    fs::create_dir_all(&dir).map_err(|err| err.to_string())?;
    write_text_report(&dir, "prototype_artifact_registry.txt", registry)?;
    write_text_report(&dir, "mamba3fin_artifact_spec.txt", mamba_spec)?;
    write_text_report(&dir, "gated_deltanet_artifact_spec.txt", gated_spec)?;
    write_text_report(&dir, "mamba3fin_prediction_import.txt", mamba_import)?;
    write_text_report(&dir, "gated_deltanet_prediction_import.txt", gated_import)?;
    write_text_report(&dir, "mamba3fin_evaluation.txt", mamba_eval)?;
    write_text_report(&dir, "gated_deltanet_evaluation.txt", gated_eval)?;
    write_text_report(&dir, "prototype_comparison.txt", comparison)?;
    write_text_report(&dir, "prototype_calibration.txt", calibration)?;
    write_text_report(&dir, "prototype_risk_interaction.txt", risk)?;
    write_text_report(&dir, "prototype_ablation.txt", ablation)?;
    write_text_report(&dir, "prototype_promotion_gate.txt", promotion)?;
    write_text_report(&dir, "committee_scenario_pack_v2.txt", committee_scenario)?;
    write_text_report(
        &dir,
        "committee_outcome_reference_pack_v2.txt",
        committee_outcome,
    )?;
    write_text_report(
        &dir,
        "committee_counterfactual_reference_pack.txt",
        committee_counterfactual,
    )?;
    write_text_report(
        &dir,
        "committee_vs_sequence_core_comparison.txt",
        committee_vs_sequence,
    )?;
    write_text_report(&dir, "training_data_artifact_population.txt", population)?;
    write_text_report(&dir, "training_data_populated_integrity.txt", integrity)?;
    write_text_report(&dir, "control_tower_sequence_prototype_panel.txt", panel)?;
    fs::write(dir.join("summary.txt"), final_summary).map_err(|err| err.to_string())?;
    let storage_bytes = fs::read_dir(&dir)
        .map_err(|err| err.to_string())?
        .filter_map(Result::ok)
        .filter_map(|entry| entry.metadata().ok().map(|meta| meta.len() as usize))
        .sum::<usize>();
    let storage_report = OperatorBriefingStorageReport {
        artifact_count: 21,
        storage_bytes,
        max_bytes: config.max_bytes as usize,
        within_budget: storage_bytes <= config.max_bytes as usize,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    };
    write_text_report(&dir, "storage_report.txt", &storage_report)?;
    Ok((storage_report, final_summary.to_string()))
}

