fn default_prototype_interpretation_output_root() -> String {
    "target/soma_prototype_interpretation".to_string()
}

fn default_two_models() -> usize {
    2
}

fn load_json_file<T>(path: &str) -> Result<T, String>
where
    T: for<'de> Deserialize<'de>,
{
    let text = fs::read_to_string(sprint76_absolutize(path)).map_err(|err| err.to_string())?;
    serde_json::from_str(&text).map_err(|err| err.to_string())
}

fn load_prototype_comparison_interpretation_inputs(
    config: &PrototypeComparisonInterpretationConfig,
) -> Result<PrototypeComparisonInterpretationInputs, String> {
    let mut bundle: Option<SequenceCorePrototypeComparisonBundle> = None;
    let mut comparison_report: Option<SequenceCorePrototypeComparisonReport> = None;
    for path in &config.sequence_core_prototype_comparison_paths {
        if bundle.is_none() {
            if let Ok(parsed_bundle) = load_json_file::<SequenceCorePrototypeComparisonBundle>(path)
            {
                comparison_report = Some(parsed_bundle.prototype_comparison_report.clone());
                bundle = Some(parsed_bundle);
                continue;
            }
        }
        if comparison_report.is_none() {
            comparison_report = Some(load_json_file(path)?);
        }
    }

    let mut mamba_eval = bundle
        .as_ref()
        .map(|value| value.mamba3fin_evaluation_report.clone());
    let mut gated_eval = bundle
        .as_ref()
        .map(|value| value.gated_deltanet_evaluation_report.clone());
    for path in &config.prototype_evaluation_paths {
        let report: SequenceCorePrototypeEvaluationReport = load_json_file(path)?;
        match report.family {
            SequenceCoreCandidateFamily::Mamba3Fin => mamba_eval = Some(report),
            SequenceCoreCandidateFamily::GatedDeltaNet => gated_eval = Some(report),
            _ => {}
        }
    }

    let calibration_report = config
        .prototype_calibration_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.prototype_calibration_report.clone())
        })
        .ok_or_else(|| {
            "prototype interpretation requires prototype calibration report".to_string()
        })?;

    let risk_report = config
        .prototype_risk_interaction_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.prototype_risk_interaction_report.clone())
        })
        .ok_or_else(|| {
            "prototype interpretation requires prototype risk interaction report".to_string()
        })?;

    let ablation_report = config
        .prototype_ablation_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.prototype_ablation_report.clone())
        })
        .ok_or_else(|| "prototype interpretation requires prototype ablation report".to_string())?;

    let committee_vs_sequence = config
        .committee_vs_sequence_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.committee_vs_sequence_core_comparison_report.clone())
        })
        .ok_or_else(|| {
            "prototype interpretation requires committee vs sequence report".to_string()
        })?;

    let committee_scenario_pack = config
        .committee_scenario_pack_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.committee_scenario_pack_v2.clone())
        })
        .ok_or_else(|| "prototype interpretation requires committee scenario pack".to_string())?;

    let committee_outcome_pack = config
        .committee_outcome_pack_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.committee_outcome_reference_pack_v2.clone())
        })
        .ok_or_else(|| "prototype interpretation requires committee outcome pack".to_string())?;

    let committee_counterfactual_pack = config
        .committee_counterfactual_pack_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.committee_no_trade_risk_denied_reference_pack.clone())
        })
        .ok_or_else(|| {
            "prototype interpretation requires committee counterfactual pack".to_string()
        })?;

    let training_population_input = config
        .training_artifact_population_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| Sprint81TrainingArtifactPopulationInput {
                    report: value.training_data_artifact_population_report.clone(),
                    artifact_counts_by_kind: BTreeMap::new(),
                    artifact_counts_by_source_class: BTreeMap::new(),
                })
        })
        .ok_or_else(|| {
            "prototype interpretation requires training artifact population report".to_string()
        })?;

    let training_integrity_report = config
        .training_populated_integrity_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.training_data_populated_integrity_report.clone())
        })
        .ok_or_else(|| {
            "prototype interpretation requires training populated integrity report".to_string()
        })?;

    let comparison_report = comparison_report
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.prototype_comparison_report.clone())
        })
        .ok_or_else(|| {
            "prototype interpretation requires sequence core prototype comparison".to_string()
        })?;

    let mamba3fin_evaluation_report = mamba_eval
        .ok_or_else(|| "prototype interpretation requires Mamba3Fin evaluation".to_string())?;
    let gated_deltanet_evaluation_report = gated_eval
        .ok_or_else(|| "prototype interpretation requires Gated DeltaNet evaluation".to_string())?;
    let promotion_gate = config
        .prototype_promotion_gate_paths
        .first()
        .map(|path| load_json_file(path))
        .transpose()?
        .or_else(|| {
            bundle
                .as_ref()
                .map(|value| value.prototype_promotion_gate.clone())
        })
        .unwrap_or_else(|| SequenceCorePrototypePromotionGate {
            gate_id: config.interpretation_id.clone(),
            mamba3fin_gate_status: mamba3fin_evaluation_report.evaluation_status,
            gated_deltanet_gate_status: gated_deltanet_evaluation_report.evaluation_status,
            shared_dataset_passed: config.require_common_dataset,
            coverage_passed: parse_decimal(&mamba3fin_evaluation_report.coverage_ratio)
                .unwrap_or(0.0)
                >= 0.75
                && parse_decimal(&gated_deltanet_evaluation_report.coverage_ratio).unwrap_or(0.0)
                    >= 0.75,
            calibration_passed: calibration_report.calibration_status
                != SequenceCorePrototypeCalibrationStatus::PoorCalibration,
            risk_passed: !matches!(
                risk_report.risk_status,
                SequenceCorePrototypeRiskInteractionStatus::PoorRiskBehavior
                    | SequenceCorePrototypeRiskInteractionStatus::MissingRiskReferences
            ),
            committee_comparison_passed: committee_vs_sequence.comparable_rows > 0,
            storage_passed: training_integrity_report.referenced_paths_exist,
            runtime_allowed: false,
            training_allowed: false,
            live_inference_allowed: false,
            promotion_status: SequenceCorePrototypePromotionStatus::ResearchCandidateOnly,
            reason_codes: stable_reason_codes(&[
                ReasonCode::DeterministicPath,
                ReasonCode::SequenceCoreComparisonDiagnosticOnly,
            ]),
        });

    Ok(PrototypeComparisonInterpretationInputs {
        comparison_report,
        mamba3fin_evaluation_report,
        gated_deltanet_evaluation_report,
        calibration_report,
        risk_report,
        ablation_report,
        promotion_gate,
        committee_vs_sequence,
        committee_scenario_pack,
        committee_outcome_pack,
        committee_counterfactual_pack,
        training_population_report: training_population_input.report,
        training_population_counts_by_kind: training_population_input.artifact_counts_by_kind,
        training_population_counts_by_source_class: training_population_input
            .artifact_counts_by_source_class,
        training_integrity_report,
    })
}

fn evidence_weight_for_source(source: PrototypeEvidenceSourceWeight) -> f64 {
    match source {
        PrototypeEvidenceSourceWeight::OfficialKIS => 1.0,
        PrototypeEvidenceSourceWeight::OfficialKRXReference => 0.9,
        PrototypeEvidenceSourceWeight::OfficialAlphaVantageFallback => 0.7,
        PrototypeEvidenceSourceWeight::ResearchOnly => 0.45,
        PrototypeEvidenceSourceWeight::DiagnosticOnly => 0.25,
        PrototypeEvidenceSourceWeight::FixtureOnly => 0.10,
        PrototypeEvidenceSourceWeight::Unknown => 0.0,
    }
}

fn source_class_to_weight(name: &str) -> PrototypeEvidenceSourceWeight {
    match name.to_ascii_lowercase().as_str() {
        "officialkis" | "official_kis" => PrototypeEvidenceSourceWeight::OfficialKIS,
        "officialkrxreference" | "official_krx_reference" => {
            PrototypeEvidenceSourceWeight::OfficialKRXReference
        }
        "officialalphavantagefallback" | "official_alpha_vantage_fallback" => {
            PrototypeEvidenceSourceWeight::OfficialAlphaVantageFallback
        }
        "researchonly" | "research_only" => PrototypeEvidenceSourceWeight::ResearchOnly,
        "diagnosticonly" | "diagnostic_only" | "chairtrace" | "risktrace" => {
            PrototypeEvidenceSourceWeight::DiagnosticOnly
        }
        "fixtureonly" | "fixture_only" => PrototypeEvidenceSourceWeight::FixtureOnly,
        _ => PrototypeEvidenceSourceWeight::Unknown,
    }
}

fn confidence_level_from_score(
    score: f64,
    diagnostic_only: bool,
) -> PrototypeComparisonConfidenceLevel {
    if diagnostic_only {
        PrototypeComparisonConfidenceLevel::DiagnosticOnly
    } else if score >= 0.75 {
        PrototypeComparisonConfidenceLevel::High
    } else if score >= 0.50 {
        PrototypeComparisonConfidenceLevel::Medium
    } else if score > 0.0 {
        PrototypeComparisonConfidenceLevel::Low
    } else {
        PrototypeComparisonConfidenceLevel::Insufficient
    }
}

fn build_prototype_evidence_weighting_policy(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
) -> PrototypeEvidenceWeightingPolicy {
    let mut source_weights = BTreeMap::new();
    for source in [
        PrototypeEvidenceSourceWeight::OfficialKIS,
        PrototypeEvidenceSourceWeight::OfficialKRXReference,
        PrototypeEvidenceSourceWeight::OfficialAlphaVantageFallback,
        PrototypeEvidenceSourceWeight::ResearchOnly,
        PrototypeEvidenceSourceWeight::DiagnosticOnly,
        PrototypeEvidenceSourceWeight::FixtureOnly,
        PrototypeEvidenceSourceWeight::Unknown,
    ] {
        source_weights.insert(source, format_decimal(evidence_weight_for_source(source)));
    }
    let official_weight = inputs
        .committee_scenario_pack
        .source_class_summary
        .iter()
        .map(|(key, count)| {
            evidence_weight_for_source(source_class_to_weight(key)) * (*count as f64)
        })
        .sum::<f64>();
    let official_reference_count = inputs.committee_scenario_pack.official_scenario_count
        + inputs.committee_outcome_pack.outcome_reference_count
        + inputs.committee_outcome_pack.baseline_reference_count;
    let policy_status = if official_reference_count == 0 || official_weight < 1.0 {
        PrototypeEvidenceWeightingPolicyStatus::NeedsOfficialEvidence
    } else if inputs.committee_scenario_pack.official_scenario_count == 0 {
        PrototypeEvidenceWeightingPolicyStatus::DiagnosticOnly
    } else {
        PrototypeEvidenceWeightingPolicyStatus::WeightingPolicyReady
    };
    let mut confidence_thresholds = BTreeMap::new();
    confidence_thresholds.insert("Low".to_string(), format_decimal(0.25));
    confidence_thresholds.insert("Medium".to_string(), format_decimal(0.50));
    confidence_thresholds.insert("High".to_string(), format_decimal(0.75));
    PrototypeEvidenceWeightingPolicy {
        policy_id: config.interpretation_id.clone(),
        source_weights,
        minimum_official_weight: format_decimal(1.0),
        diagnostic_cap: format_decimal(0.25),
        fixture_cap: format_decimal(0.10),
        research_only_cap: format_decimal(0.45),
        required_reference_types: vec![
            CommitteeReferenceCoverageDimension::Scenario,
            CommitteeReferenceCoverageDimension::Outcome,
            CommitteeReferenceCoverageDimension::Baseline,
            CommitteeReferenceCoverageDimension::NoTradeCounterfactual,
            CommitteeReferenceCoverageDimension::RiskDeniedCounterfactual,
        ],
        confidence_thresholds,
        policy_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::PrototypeEvidenceWeightingPolicyBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_reference_coverage_audit_v2(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
) -> CommitteeReferenceCoverageAuditV2 {
    let source_classes = &inputs.committee_scenario_pack.source_class_summary;
    let official_count = inputs.committee_scenario_pack.official_scenario_count;
    let research_only_count = inputs.committee_scenario_pack.research_only_count;
    let diagnostic_only_count = inputs.committee_scenario_pack.diagnostic_only_count;
    let fixture_only_count = inputs.committee_scenario_pack.fixture_only_count;
    let chair_trace_count = source_classes.get("ChairTrace").copied().unwrap_or(0);
    let risk_trace_count = source_classes.get("RiskTrace").copied().unwrap_or(0);
    let no_lookahead_count = usize::from(inputs.committee_outcome_pack.no_lookahead_safe);
    let cells = vec![
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::Scenario,
            inputs.committee_scenario_pack.scenarios.len(),
            official_count,
            research_only_count,
            diagnostic_only_count,
            fixture_only_count,
            inputs.committee_scenario_pack.scenarios.len() >= 3,
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::Outcome,
            inputs.committee_outcome_pack.outcome_reference_count,
            inputs.committee_outcome_pack.future_window_safe_count,
            0,
            0,
            0,
            inputs.committee_outcome_pack.outcome_reference_count > 0,
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::Baseline,
            inputs.committee_outcome_pack.baseline_reference_count,
            inputs.committee_outcome_pack.baseline_reference_count,
            0,
            0,
            0,
            inputs.committee_outcome_pack.baseline_reference_count > 0,
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::NoTradeCounterfactual,
            inputs
                .committee_counterfactual_pack
                .no_trade_counterfactual_count,
            inputs
                .committee_counterfactual_pack
                .no_trade_counterfactual_count,
            0,
            0,
            0,
            inputs
                .committee_counterfactual_pack
                .no_trade_counterfactual_count
                > 0,
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::RiskDeniedCounterfactual,
            inputs
                .committee_counterfactual_pack
                .risk_denied_counterfactual_count,
            inputs
                .committee_counterfactual_pack
                .risk_denied_counterfactual_count,
            0,
            0,
            0,
            inputs
                .committee_counterfactual_pack
                .risk_denied_counterfactual_count
                > 0,
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::CommitteeReplay,
            inputs.committee_vs_sequence.comparable_rows,
            inputs.committee_vs_sequence.comparable_rows,
            0,
            0,
            0,
            inputs.committee_vs_sequence.comparable_rows > 0,
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::ChairTrace,
            chair_trace_count,
            0,
            0,
            chair_trace_count,
            0,
            chair_trace_count > 0,
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::RiskTrace,
            risk_trace_count,
            0,
            0,
            risk_trace_count,
            0,
            risk_trace_count > 0,
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::SourceClass,
            source_classes.len(),
            usize::from(official_count > 0),
            usize::from(research_only_count > 0),
            usize::from(diagnostic_only_count > 0),
            usize::from(fixture_only_count > 0),
            !source_classes.is_empty(),
        ),
        build_committee_reference_coverage_cell(
            CommitteeReferenceCoverageDimension::NoLookahead,
            no_lookahead_count,
            no_lookahead_count,
            0,
            0,
            0,
            inputs.committee_outcome_pack.no_lookahead_safe,
        ),
    ];
    let insufficient_dimensions = cells
        .iter()
        .filter(|cell| !cell.sufficient)
        .map(|cell| cell.dimension)
        .collect::<Vec<_>>();
    let audit_status = if official_count == 0 && config.require_committee_reference_coverage {
        CommitteeReferenceCoverageAuditStatus::NeedMoreOfficialReferences
    } else if insufficient_dimensions.contains(&CommitteeReferenceCoverageDimension::Outcome) {
        CommitteeReferenceCoverageAuditStatus::NeedMoreOutcomeReferences
    } else if insufficient_dimensions
        .contains(&CommitteeReferenceCoverageDimension::NoTradeCounterfactual)
        && config.require_no_trade_reference
    {
        CommitteeReferenceCoverageAuditStatus::NeedMoreNoTradeReferences
    } else if insufficient_dimensions
        .contains(&CommitteeReferenceCoverageDimension::RiskDeniedCounterfactual)
        && config.require_risk_denied_reference
    {
        CommitteeReferenceCoverageAuditStatus::NeedMoreRiskDeniedReferences
    } else if !insufficient_dimensions.is_empty() {
        CommitteeReferenceCoverageAuditStatus::CommitteeReferenceCoverageReadyWithWarnings
    } else {
        CommitteeReferenceCoverageAuditStatus::CommitteeReferenceCoverageReady
    };
    CommitteeReferenceCoverageAuditV2 {
        audit_id: config.interpretation_id.clone(),
        cells,
        total_reference_count: inputs.committee_scenario_pack.scenarios.len()
            + inputs.committee_outcome_pack.outcome_reference_count
            + inputs.committee_outcome_pack.baseline_reference_count
            + inputs
                .committee_counterfactual_pack
                .no_trade_counterfactual_count
            + inputs
                .committee_counterfactual_pack
                .risk_denied_counterfactual_count,
        official_reference_count: official_count
            + inputs.committee_outcome_pack.future_window_safe_count
            + inputs.committee_outcome_pack.baseline_reference_count,
        insufficient_dimensions,
        audit_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeReferenceCoverageAuditV2Built,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_reference_coverage_cell(
    dimension: CommitteeReferenceCoverageDimension,
    count: usize,
    official_count: usize,
    research_only_count: usize,
    diagnostic_count: usize,
    fixture_count: usize,
    sufficient: bool,
) -> CommitteeReferenceCoverageCell {
    CommitteeReferenceCoverageCell {
        dimension,
        count,
        official_count,
        research_only_count,
        diagnostic_count,
        fixture_count,
        sufficient,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeReferenceCoverageAuditV2Built,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_prototype_comparison_confidence_report(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
    policy: &PrototypeEvidenceWeightingPolicy,
    audit: &CommitteeReferenceCoverageAuditV2,
    defensive: &NoTradeRiskDeniedInterpretationReport,
) -> PrototypeComparisonConfidenceReport {
    let official_weight = audit.official_reference_count as f64;
    let total_weight = audit.total_reference_count as f64;
    let evidence_ratio = if total_weight > 0.0 {
        official_weight / total_weight
    } else {
        0.0
    };
    let fixture_dominates = inputs.committee_scenario_pack.fixture_only_count
        > inputs.committee_scenario_pack.official_scenario_count;
    let diagnostic_only = matches!(
        policy.policy_status,
        PrototypeEvidenceWeightingPolicyStatus::DiagnosticOnly
    );
    let mut weak_evidence_reasons = Vec::new();
    if fixture_dominates {
        weak_evidence_reasons
            .push("fixture evidence dominates committee scenario pack".to_string());
    }
    if audit.official_reference_count == 0 {
        weak_evidence_reasons.push("official committee references are missing".to_string());
    }
    if defensive.interpretation_status != NoTradeRiskDeniedInterpretationStatus::DefensiveAxesReady
    {
        weak_evidence_reasons.push("NoTrade/RiskDenied depth is incomplete".to_string());
    }
    let base_score = if diagnostic_only { 0.0 } else { evidence_ratio };
    let mamba_score = base_score
        * parse_decimal(&inputs.mamba3fin_evaluation_report.coverage_ratio).unwrap_or(0.0);
    let gated_score = base_score
        * parse_decimal(&inputs.gated_deltanet_evaluation_report.coverage_ratio).unwrap_or(0.0);
    let committee_score = if audit.total_reference_count == 0 {
        0.0
    } else {
        audit.official_reference_count as f64 / audit.total_reference_count as f64
    };
    let no_trade_score = if inputs
        .committee_counterfactual_pack
        .no_trade_counterfactual_count
        == 0
    {
        0.0
    } else {
        committee_score
    };
    let risk_denied_score = if inputs
        .committee_counterfactual_pack
        .risk_denied_counterfactual_count
        == 0
    {
        0.0
    } else {
        committee_score
    };
    let confidence_status = if matches!(
        policy.policy_status,
        PrototypeEvidenceWeightingPolicyStatus::NeedsOfficialEvidence
    ) {
        PrototypeComparisonConfidenceStatus::InsufficientEvidence
    } else if !weak_evidence_reasons.is_empty() {
        PrototypeComparisonConfidenceStatus::ConfidenceReadyWithWarnings
    } else {
        PrototypeComparisonConfidenceStatus::ConfidenceReady
    };
    PrototypeComparisonConfidenceReport {
        report_id: config.interpretation_id.clone(),
        mamba3fin_confidence: confidence_level_from_score(mamba_score, diagnostic_only),
        gated_deltanet_confidence: confidence_level_from_score(gated_score, diagnostic_only),
        committee_confidence: confidence_level_from_score(committee_score, diagnostic_only),
        no_trade_confidence: confidence_level_from_score(no_trade_score, diagnostic_only),
        risk_denied_confidence: confidence_level_from_score(risk_denied_score, diagnostic_only),
        evidence_weight_summary: vec![
            format!(
                "official_reference_count={}",
                audit.official_reference_count
            ),
            format!("total_reference_count={}", audit.total_reference_count),
            format!("official_ratio={}", format_decimal(committee_score)),
        ],
        weak_evidence_reasons,
        confidence_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::PrototypeComparisonConfidenceReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_no_trade_risk_denied_interpretation_report(
    config: &PrototypeComparisonInterpretationConfig,
    counterfactual_pack: &CommitteeNoTradeRiskDeniedReferencePack,
    committee_vs_sequence: &CommitteeVsSequenceCoreComparisonReport,
    risk_report: &SequenceCorePrototypeRiskInteractionReport,
) -> NoTradeRiskDeniedInterpretationReport {
    let interpretation_status = if counterfactual_pack.no_trade_counterfactual_count == 0 {
        NoTradeRiskDeniedInterpretationStatus::NeedMoreNoTradeReferences
    } else if counterfactual_pack.risk_denied_counterfactual_count == 0 {
        NoTradeRiskDeniedInterpretationStatus::NeedMoreRiskDeniedReferences
    } else {
        NoTradeRiskDeniedInterpretationStatus::DefensiveAxesReady
    };
    NoTradeRiskDeniedInterpretationReport {
        report_id: config.interpretation_id.clone(),
        no_trade_better_count: committee_vs_sequence.no_trade_better_count,
        risk_denied_defensive_count: committee_vs_sequence.risk_denied_defensive_count,
        prototype_overtrade_count: risk_report.over_risk_count,
        prototype_undertrade_count: risk_report.under_risk_count,
        no_trade_interpretation: format!(
            "NoTrade outperformed prototype axes in {} comparable cases",
            committee_vs_sequence.no_trade_better_count
        ),
        risk_denied_interpretation: format!(
            "RiskDenied preserved defensive value in {} comparable cases",
            committee_vs_sequence.risk_denied_defensive_count
        ),
        interpretation_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::NoTradeRiskDeniedInterpretationReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_prototype_winner_interpretation_gate(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
    confidence_status: PrototypeComparisonConfidenceStatus,
    committee_reference_status: CommitteeReferenceCoverageAuditStatus,
    defensive_status: NoTradeRiskDeniedInterpretationStatus,
) -> PrototypeWinnerInterpretationGate {
    let selected_interpretation = if matches!(
        confidence_status,
        PrototypeComparisonConfidenceStatus::InsufficientEvidence
    ) {
        PrototypeWinnerInterpretationStatus::BlockedByEvidence
    } else if matches!(
        committee_reference_status,
        CommitteeReferenceCoverageAuditStatus::NeedMoreOutcomeReferences
            | CommitteeReferenceCoverageAuditStatus::NeedMoreNoTradeReferences
            | CommitteeReferenceCoverageAuditStatus::NeedMoreRiskDeniedReferences
            | CommitteeReferenceCoverageAuditStatus::NeedMoreOfficialReferences
    ) {
        PrototypeWinnerInterpretationStatus::BlockedByCommitteeReferenceCoverage
    } else if defensive_status != NoTradeRiskDeniedInterpretationStatus::DefensiveAxesReady
        || matches!(
            inputs.risk_report.risk_status,
            SequenceCorePrototypeRiskInteractionStatus::PoorRiskBehavior
                | SequenceCorePrototypeRiskInteractionStatus::MissingRiskReferences
        )
    {
        PrototypeWinnerInterpretationStatus::BlockedByRiskInterpretation
    } else {
        match inputs.committee_vs_sequence.comparison_status {
            CommitteeVsSequenceCoreComparisonStatus::CommitteeBetterDiagnostic => {
                PrototypeWinnerInterpretationStatus::CommitteeBetterDiagnostic
            }
            _ => match inputs.comparison_report.comparison_status {
                SequenceCorePrototypeComparisonStatus::Mamba3FinBetterDiagnostic => {
                    PrototypeWinnerInterpretationStatus::Mamba3FinBetterDiagnostic
                }
                SequenceCorePrototypeComparisonStatus::GatedDeltaNetBetterDiagnostic => {
                    PrototypeWinnerInterpretationStatus::GatedDeltaNetBetterDiagnostic
                }
                SequenceCorePrototypeComparisonStatus::Mixed
                | SequenceCorePrototypeComparisonStatus::ComparisonReady
                | SequenceCorePrototypeComparisonStatus::ComparisonReadyWithWarnings => {
                    PrototypeWinnerInterpretationStatus::MixedOrInconclusive
                }
                _ => PrototypeWinnerInterpretationStatus::NoWinnerDiagnostic,
            },
        }
    };
    PrototypeWinnerInterpretationGate {
        gate_id: config.interpretation_id.clone(),
        raw_comparison_status: inputs.comparison_report.comparison_status,
        confidence_status,
        calibration_status: inputs.calibration_report.calibration_status,
        risk_status: inputs.risk_report.risk_status,
        ablation_status: inputs.ablation_report.ablation_status,
        committee_reference_status,
        no_trade_reference_status: defensive_status,
        risk_denied_reference_status: defensive_status,
        selected_interpretation,
        runtime_allowed: false,
        training_allowed: false,
        live_inference_allowed: false,
        reason_codes: stable_reason_codes(&[
            ReasonCode::PrototypeWinnerInterpretationGateBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_disagreement_cell(
    axis: PrototypeDisagreementAxis,
    comparable_rows: usize,
    disagreement_count: usize,
    severe_disagreement_count: usize,
) -> PrototypeDisagreementCell {
    let disagreement_count = disagreement_count.min(comparable_rows);
    let agreement_count = comparable_rows.saturating_sub(disagreement_count);
    PrototypeDisagreementCell {
        axis,
        comparable_rows,
        agreement_count,
        disagreement_count,
        disagreement_rate: format_decimal(if comparable_rows == 0 {
            0.0
        } else {
            disagreement_count as f64 / comparable_rows as f64
        }),
        severe_disagreement_count: severe_disagreement_count.min(disagreement_count),
        reason_codes: stable_reason_codes(&[
            ReasonCode::PrototypeDisagreementMatrixBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_prototype_disagreement_matrix(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
) -> PrototypeDisagreementMatrix {
    let comparison_rows = inputs.comparison_report.comparable_rows;
    let committee_rows = inputs.committee_vs_sequence.comparable_rows;
    let mixed_disagreement = if matches!(
        inputs.comparison_report.comparison_status,
        SequenceCorePrototypeComparisonStatus::Mixed
    ) {
        comparison_rows / 2
    } else {
        comparison_rows / 4
    };
    let poor_risk = matches!(
        inputs.risk_report.risk_status,
        SequenceCorePrototypeRiskInteractionStatus::PoorRiskBehavior
    );
    let cells = vec![
        build_disagreement_cell(
            PrototypeDisagreementAxis::Mamba3FinVsGatedDeltaNet,
            comparison_rows,
            mixed_disagreement,
            usize::from(poor_risk) * (mixed_disagreement / 2),
        ),
        build_disagreement_cell(
            PrototypeDisagreementAxis::Mamba3FinVsCommittee,
            committee_rows,
            inputs.committee_vs_sequence.committee_better_count,
            inputs.committee_vs_sequence.risk_denied_defensive_count / 2,
        ),
        build_disagreement_cell(
            PrototypeDisagreementAxis::GatedDeltaNetVsCommittee,
            committee_rows,
            inputs.committee_vs_sequence.committee_better_count,
            inputs.committee_vs_sequence.risk_denied_defensive_count / 2,
        ),
        build_disagreement_cell(
            PrototypeDisagreementAxis::Mamba3FinVsNoTrade,
            committee_rows,
            inputs.committee_vs_sequence.no_trade_better_count,
            inputs.risk_report.over_risk_count,
        ),
        build_disagreement_cell(
            PrototypeDisagreementAxis::GatedDeltaNetVsNoTrade,
            committee_rows,
            inputs.committee_vs_sequence.no_trade_better_count,
            inputs.risk_report.over_risk_count,
        ),
        build_disagreement_cell(
            PrototypeDisagreementAxis::CommitteeVsNoTrade,
            committee_rows,
            inputs.committee_vs_sequence.no_trade_better_count,
            inputs.committee_vs_sequence.no_trade_better_count / 2,
        ),
        build_disagreement_cell(
            PrototypeDisagreementAxis::Mamba3FinVsRiskDenied,
            committee_rows,
            inputs.committee_vs_sequence.risk_denied_defensive_count,
            inputs.risk_report.over_risk_count,
        ),
        build_disagreement_cell(
            PrototypeDisagreementAxis::GatedDeltaNetVsRiskDenied,
            committee_rows,
            inputs.committee_vs_sequence.risk_denied_defensive_count,
            inputs.risk_report.over_risk_count,
        ),
        build_disagreement_cell(
            PrototypeDisagreementAxis::CommitteeVsRiskDenied,
            committee_rows,
            inputs.committee_vs_sequence.risk_denied_defensive_count,
            inputs.committee_vs_sequence.risk_denied_defensive_count / 2,
        ),
    ];
    let total_rows = cells.iter().map(|cell| cell.comparable_rows).sum::<usize>();
    let total_disagreement = cells
        .iter()
        .map(|cell| cell.disagreement_count)
        .sum::<usize>();
    let overall_disagreement_rate = if total_rows == 0 {
        0.0
    } else {
        total_disagreement as f64 / total_rows as f64
    };
    let matrix_status = if comparison_rows < 2 || committee_rows < 2 {
        PrototypeDisagreementMatrixStatus::InsufficientComparableRows
    } else if overall_disagreement_rate >= 0.40 {
        PrototypeDisagreementMatrixStatus::HighDisagreement
    } else {
        PrototypeDisagreementMatrixStatus::DisagreementMatrixReady
    };
    PrototypeDisagreementMatrix {
        matrix_id: config.interpretation_id.clone(),
        cells,
        overall_disagreement_rate: format_decimal(overall_disagreement_rate),
        matrix_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::PrototypeDisagreementMatrixBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_prototype_failure_mode_report(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
    policy: &PrototypeEvidenceWeightingPolicy,
    audit: &CommitteeReferenceCoverageAuditV2,
    defensive: &NoTradeRiskDeniedInterpretationReport,
) -> PrototypeFailureModeReport {
    let mut failure_modes_by_family = BTreeMap::new();
    for (name, evaluation) in [
        ("mamba3fin".to_string(), &inputs.mamba3fin_evaluation_report),
        (
            "gated_deltanet".to_string(),
            &inputs.gated_deltanet_evaluation_report,
        ),
    ] {
        let mut modes = Vec::new();
        if parse_decimal(&evaluation.coverage_ratio).unwrap_or(0.0) < 0.75 {
            modes.push(PrototypeFailureModeKind::LowCoverage);
        }
        if matches!(
            inputs.calibration_report.calibration_status,
            SequenceCorePrototypeCalibrationStatus::PoorCalibration
        ) {
            modes.push(PrototypeFailureModeKind::PoorCalibration);
        }
        if matches!(
            inputs.risk_report.risk_status,
            SequenceCorePrototypeRiskInteractionStatus::PoorRiskBehavior
        ) {
            modes.push(PrototypeFailureModeKind::PoorRiskBehavior);
        }
        if matches!(
            inputs.ablation_report.ablation_status,
            SequenceCorePrototypeAblationStatus::AblationSensitive
                | SequenceCorePrototypeAblationStatus::AblationUnstable
        ) {
            modes.push(PrototypeFailureModeKind::HighAblationSensitivity);
        }
        if defensive.no_trade_better_count == 0 {
            modes.push(PrototypeFailureModeKind::WeakNoTradeComparison);
        }
        if defensive.risk_denied_defensive_count == 0 {
            modes.push(PrototypeFailureModeKind::WeakRiskDeniedAlignment);
        }
        failure_modes_by_family.insert(name, modes);
    }
    let mut top_failure_modes = failure_modes_by_family
        .values()
        .flatten()
        .copied()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    if matches!(
        policy.policy_status,
        PrototypeEvidenceWeightingPolicyStatus::NeedsOfficialEvidence
    ) {
        top_failure_modes.push(PrototypeFailureModeKind::InsufficientOfficialEvidence);
    }
    if !audit.insufficient_dimensions.is_empty() {
        top_failure_modes.push(PrototypeFailureModeKind::InsufficientCommitteeReference);
    }
    if inputs.promotion_gate.coverage_passed == false
        || matches!(
            inputs.comparison_report.comparison_status,
            SequenceCorePrototypeComparisonStatus::NotComparable
        )
    {
        top_failure_modes.push(PrototypeFailureModeKind::ContractMismatch);
    }
    top_failure_modes.sort();
    top_failure_modes.dedup();
    let remediation_actions = top_failure_modes
        .iter()
        .map(|mode| match mode {
            PrototypeFailureModeKind::LowCoverage => {
                "add more prototype predictions on the shared dataset".to_string()
            }
            PrototypeFailureModeKind::PoorCalibration => {
                "inspect probability quality before stronger interpretation".to_string()
            }
            PrototypeFailureModeKind::PoorRiskBehavior => {
                "review NoTrade and RiskDenied defensive divergences".to_string()
            }
            PrototypeFailureModeKind::HighAblationSensitivity => {
                "stabilize prototype metrics under ablation stress".to_string()
            }
            PrototypeFailureModeKind::WeakNoTradeComparison => {
                "add NoTrade reference depth".to_string()
            }
            PrototypeFailureModeKind::WeakRiskDeniedAlignment => {
                "add RiskDenied counterfactual depth".to_string()
            }
            PrototypeFailureModeKind::ContractMismatch => {
                "re-check common prototype contract alignment".to_string()
            }
            PrototypeFailureModeKind::InsufficientCommitteeReference => {
                "expand committee reference coverage".to_string()
            }
            PrototypeFailureModeKind::InsufficientOfficialEvidence => {
                "collect more official evidence before raising confidence".to_string()
            }
            PrototypeFailureModeKind::Unknown => "review diagnostic bundle manually".to_string(),
        })
        .collect::<Vec<_>>();
    let report_status = if top_failure_modes.is_empty() {
        PrototypeFailureModeReportStatus::NoMajorFailureModes
    } else if top_failure_modes.iter().any(|mode| {
        matches!(
            mode,
            PrototypeFailureModeKind::InsufficientCommitteeReference
                | PrototypeFailureModeKind::InsufficientOfficialEvidence
        )
    }) {
        PrototypeFailureModeReportStatus::InsufficientEvidence
    } else {
        PrototypeFailureModeReportStatus::FailureModesReady
    };
    PrototypeFailureModeReport {
        report_id: config.interpretation_id.clone(),
        failure_modes_by_family,
        top_failure_modes,
        remediation_actions,
        report_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::PrototypeFailureModeReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_prototype_calibration_risk_synthesis_report(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
) -> PrototypeCalibrationRiskSynthesisReport {
    let synthesis_status = if matches!(
        inputs.risk_report.risk_status,
        SequenceCorePrototypeRiskInteractionStatus::MissingRiskReferences
    ) {
        PrototypeCalibrationRiskSynthesisStatus::MissingRiskReferences
    } else if matches!(
        inputs.calibration_report.calibration_status,
        SequenceCorePrototypeCalibrationStatus::PoorCalibration
    ) {
        PrototypeCalibrationRiskSynthesisStatus::PoorCalibration
    } else if matches!(
        inputs.risk_report.risk_status,
        SequenceCorePrototypeRiskInteractionStatus::PoorRiskBehavior
    ) {
        PrototypeCalibrationRiskSynthesisStatus::PoorRiskBehavior
    } else {
        PrototypeCalibrationRiskSynthesisStatus::CalibrationRiskSynthesisReady
    };
    PrototypeCalibrationRiskSynthesisReport {
        report_id: config.interpretation_id.clone(),
        mamba3fin_calibration_summary: format!(
            "status={:?}; coverage={}",
            inputs.calibration_report.calibration_status,
            inputs.mamba3fin_evaluation_report.coverage_ratio
        ),
        gated_deltanet_calibration_summary: format!(
            "status={:?}; coverage={}",
            inputs.calibration_report.calibration_status,
            inputs.gated_deltanet_evaluation_report.coverage_ratio
        ),
        mamba3fin_risk_summary: format!(
            "status={:?}; no_trade={}",
            inputs.risk_report.risk_status,
            inputs
                .mamba3fin_evaluation_report
                .no_trade_comparison
                .clone()
                .unwrap_or_else(|| "n/a".to_string())
        ),
        gated_deltanet_risk_summary: format!(
            "status={:?}; no_trade={}",
            inputs.risk_report.risk_status,
            inputs
                .gated_deltanet_evaluation_report
                .no_trade_comparison
                .clone()
                .unwrap_or_else(|| "n/a".to_string())
        ),
        risk_denied_alignment_summary: inputs.risk_report.risk_denied_alignment.clone(),
        no_trade_alignment_summary: inputs.risk_report.no_trade_alignment.clone(),
        synthesis_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::PrototypeCalibrationRiskSynthesisReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_reference_depth_closure_plan(
    config: &PrototypeComparisonInterpretationConfig,
    audit: &CommitteeReferenceCoverageAuditV2,
) -> CommitteeReferenceDepthClosurePlan {
    let mut actions = Vec::new();
    for dimension in &audit.insufficient_dimensions {
        actions.push(match dimension {
            CommitteeReferenceCoverageDimension::Scenario => {
                CommitteeReferenceDepthClosureAction::AddOfficialScenarios
            }
            CommitteeReferenceCoverageDimension::Outcome => {
                CommitteeReferenceDepthClosureAction::AddOutcomeReferences
            }
            CommitteeReferenceCoverageDimension::Baseline => {
                CommitteeReferenceDepthClosureAction::AddBaselineReferences
            }
            CommitteeReferenceCoverageDimension::NoTradeCounterfactual => {
                CommitteeReferenceDepthClosureAction::AddNoTradeCounterfactuals
            }
            CommitteeReferenceCoverageDimension::RiskDeniedCounterfactual => {
                CommitteeReferenceDepthClosureAction::AddRiskDeniedCounterfactuals
            }
            CommitteeReferenceCoverageDimension::ChairTrace => {
                CommitteeReferenceDepthClosureAction::AddChairTrace
            }
            CommitteeReferenceCoverageDimension::RiskTrace => {
                CommitteeReferenceDepthClosureAction::AddRiskTrace
            }
            CommitteeReferenceCoverageDimension::NoLookahead => {
                CommitteeReferenceDepthClosureAction::AddNoLookaheadProof
            }
            _ => CommitteeReferenceDepthClosureAction::NoAction,
        });
    }
    if actions.is_empty() {
        actions.push(CommitteeReferenceDepthClosureAction::NoAction);
    }
    let mut target_counts = BTreeMap::new();
    target_counts.insert("scenario".to_string(), 3);
    target_counts.insert("outcome".to_string(), 1);
    target_counts.insert("baseline".to_string(), 1);
    target_counts.insert("no_trade".to_string(), 1);
    target_counts.insert("risk_denied".to_string(), 1);
    let plan_status = if audit.audit_status
        == CommitteeReferenceCoverageAuditStatus::NeedMoreOfficialReferences
    {
        CommitteeReferenceDepthClosurePlanStatus::NeedOfficialEvidence
    } else if actions.iter().any(|action| {
        matches!(
            action,
            CommitteeReferenceDepthClosureAction::AddNoTradeCounterfactuals
                | CommitteeReferenceDepthClosureAction::AddRiskDeniedCounterfactuals
        )
    }) {
        CommitteeReferenceDepthClosurePlanStatus::NeedCounterfactualDepth
    } else if actions.iter().any(|action| {
        matches!(
            action,
            CommitteeReferenceDepthClosureAction::AddChairTrace
                | CommitteeReferenceDepthClosureAction::AddRiskTrace
        )
    }) {
        CommitteeReferenceDepthClosurePlanStatus::NeedTraceDepth
    } else {
        CommitteeReferenceDepthClosurePlanStatus::ClosurePlanReady
    };
    CommitteeReferenceDepthClosurePlan {
        plan_id: config.interpretation_id.clone(),
        missing_dimensions: audit.insufficient_dimensions.clone(),
        actions: actions.clone(),
        target_counts,
        operator_actions: actions
            .iter()
            .map(|action| format!("action={action:?}"))
            .collect(),
        plan_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeReferenceDepthClosurePlanBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn parse_committee_scenario_parts(scenario: &str) -> Vec<&str> {
    scenario.split(':').collect::<Vec<_>>()
}

fn build_committee_scenario_representativeness_report(
    config: &PrototypeComparisonInterpretationConfig,
    pack: &CommitteeScenarioPackV2,
) -> CommitteeScenarioRepresentativenessReport {
    let mut symbols = BTreeSet::new();
    let mut timeframes = BTreeSet::new();
    let mut markets = BTreeSet::new();
    let mut regimes = BTreeSet::new();
    let mut outcomes = BTreeMap::new();
    for scenario in &pack.scenarios {
        let parts = parse_committee_scenario_parts(scenario);
        if parts.len() >= 5 {
            markets.insert(parts[0].to_string());
            symbols.insert(parts[1].to_string());
            timeframes.insert(parts[2].to_string());
            regimes.insert(parts[3].to_string());
            *outcomes.entry(parts[4].to_string()).or_insert(0usize) += 1;
        }
    }
    let official_ratio = if pack.scenarios.is_empty() {
        0.0
    } else {
        pack.official_scenario_count as f64 / pack.scenarios.len() as f64
    };
    let representativeness_status = if symbols.len() < 2 {
        CommitteeScenarioRepresentativenessStatus::NeedsMoreSymbols
    } else if timeframes.len() < 2 {
        CommitteeScenarioRepresentativenessStatus::NeedsMoreTimeframes
    } else if outcomes.len() < 2 {
        CommitteeScenarioRepresentativenessStatus::NeedsMoreOutcomeDiversity
    } else if regimes.len() < 2 {
        CommitteeScenarioRepresentativenessStatus::NeedsMoreMarketRegimes
    } else {
        CommitteeScenarioRepresentativenessStatus::RepresentativeEnoughForResearch
    };
    CommitteeScenarioRepresentativenessReport {
        report_id: config.interpretation_id.clone(),
        symbol_count: symbols.len(),
        timeframe_count: timeframes.len(),
        market_count: markets.len(),
        regime_count: Some(regimes.len()),
        outcome_distribution: outcomes,
        official_ratio: format_decimal(official_ratio),
        representativeness_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeScenarioRepresentativenessReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn find_disagreement_cell(
    matrix: &PrototypeDisagreementMatrix,
    axis: PrototypeDisagreementAxis,
) -> PrototypeDisagreementCell {
    matrix
        .cells
        .iter()
        .find(|cell| cell.axis == axis)
        .cloned()
        .expect("disagreement cell")
}

fn build_committee_sequence_disagreement_report(
    config: &PrototypeComparisonInterpretationConfig,
    matrix: &PrototypeDisagreementMatrix,
) -> CommitteeSequenceDisagreementReport {
    let committee_vs_mamba3fin =
        find_disagreement_cell(matrix, PrototypeDisagreementAxis::Mamba3FinVsCommittee);
    let committee_vs_gated_deltanet =
        find_disagreement_cell(matrix, PrototypeDisagreementAxis::GatedDeltaNetVsCommittee);
    let committee_vs_no_trade =
        find_disagreement_cell(matrix, PrototypeDisagreementAxis::CommitteeVsNoTrade);
    let committee_vs_risk_denied =
        find_disagreement_cell(matrix, PrototypeDisagreementAxis::CommitteeVsRiskDenied);
    let report_status =
        if matrix.matrix_status == PrototypeDisagreementMatrixStatus::InsufficientComparableRows {
            CommitteeSequenceDisagreementReportStatus::InsufficientComparableRows
        } else if matrix.matrix_status == PrototypeDisagreementMatrixStatus::HighDisagreement {
            CommitteeSequenceDisagreementReportStatus::HighDisagreementNeedsReview
        } else {
            CommitteeSequenceDisagreementReportStatus::DisagreementReportReady
        };
    CommitteeSequenceDisagreementReport {
        report_id: config.interpretation_id.clone(),
        committee_vs_mamba3fin: committee_vs_mamba3fin.clone(),
        committee_vs_gated_deltanet: committee_vs_gated_deltanet.clone(),
        committee_vs_no_trade: committee_vs_no_trade.clone(),
        committee_vs_risk_denied: committee_vs_risk_denied.clone(),
        disagreement_hotspots: [
            committee_vs_mamba3fin.clone(),
            committee_vs_gated_deltanet.clone(),
            committee_vs_no_trade.clone(),
            committee_vs_risk_denied.clone(),
        ]
        .into_iter()
        .filter(|cell| parse_decimal(&cell.disagreement_rate).unwrap_or(0.0) >= 0.40)
        .map(|cell| format!("{:?}", cell.axis))
        .collect(),
        recommended_review_items: [
            committee_vs_mamba3fin,
            committee_vs_gated_deltanet,
            committee_vs_no_trade,
            committee_vs_risk_denied,
        ]
        .into_iter()
        .filter(|cell| cell.severe_disagreement_count > 0)
        .map(|cell| format!("review {:?}", cell.axis))
        .collect(),
        report_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeSequenceDisagreementReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_training_artifact_lineage_completeness_report(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
) -> TrainingArtifactLineageCompletenessReport {
    let counts = &inputs.training_population_counts_by_kind;
    let dataset_registry_present = inputs.training_population_report.registry_entries_added > 0
        || counts.get("dataset_registry").copied().unwrap_or(0) > 0;
    let dataset_version_present = inputs.training_population_report.dataset_versions_added > 0
        || counts.get("dataset_version").copied().unwrap_or(0) > 0;
    let source_class_present = inputs.training_population_report.source_class_entries_added > 0
        || counts.get("source_class").copied().unwrap_or(0) > 0;
    let feature_schema_present = counts.get("feature_schema").copied().unwrap_or(0) > 0;
    let label_manifest_present = counts.get("label_manifest").copied().unwrap_or(0) > 0;
    let split_manifest_present = counts.get("split_manifest").copied().unwrap_or(0) > 0;
    let no_lookahead_proof_present = counts.get("no_lookahead_proof").copied().unwrap_or(0) > 0;
    let prediction_artifacts_present = counts.get("prediction_csv").copied().unwrap_or(0) > 0;
    let model_card_artifacts_present = counts.get("model_card").copied().unwrap_or(0) > 0;
    let evaluation_artifacts_present = counts.get("evaluation_report").copied().unwrap_or(0) > 0;
    let committee_reference_artifacts_present =
        counts.get("committee_reference_pack").copied().unwrap_or(0) > 0;
    let mut missing_artifacts = Vec::new();
    for (present, name) in [
        (dataset_registry_present, "dataset_registry"),
        (dataset_version_present, "dataset_version"),
        (source_class_present, "source_class"),
        (feature_schema_present, "feature_schema"),
        (label_manifest_present, "label_manifest"),
        (split_manifest_present, "split_manifest"),
        (no_lookahead_proof_present, "no_lookahead_proof"),
    ] {
        if !present {
            missing_artifacts.push(name.to_string());
        }
    }
    let completeness_status = if !missing_artifacts.is_empty()
        || !inputs.training_integrity_report.referenced_paths_exist
    {
        TrainingArtifactLineageCompletenessStatus::MissingCriticalArtifacts
    } else if !prediction_artifacts_present
        || !model_card_artifacts_present
        || !evaluation_artifacts_present
        || !committee_reference_artifacts_present
    {
        TrainingArtifactLineageCompletenessStatus::LineageCompleteWithWarnings
    } else {
        TrainingArtifactLineageCompletenessStatus::LineageComplete
    };
    TrainingArtifactLineageCompletenessReport {
        report_id: config.interpretation_id.clone(),
        dataset_registry_present,
        dataset_version_present,
        source_class_present,
        feature_schema_present,
        label_manifest_present,
        split_manifest_present,
        no_lookahead_proof_present,
        prediction_artifacts_present,
        model_card_artifacts_present,
        evaluation_artifacts_present,
        committee_reference_artifacts_present,
        missing_artifacts,
        completeness_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TrainingArtifactLineageCompletenessReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_training_artifact_reference_depth_report(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
) -> TrainingArtifactReferenceDepthReport {
    let weak_reference_kinds = inputs
        .training_population_counts_by_kind
        .iter()
        .filter(|(_, count)| **count == 0)
        .map(|(kind, _)| kind.clone())
        .collect::<Vec<_>>();
    let official_artifacts = inputs
        .training_population_counts_by_source_class
        .get("OfficialKIS")
        .copied()
        .unwrap_or(0)
        + inputs
            .training_population_counts_by_source_class
            .get("OfficialKRXReference")
            .copied()
            .unwrap_or(0);
    let minimum_reference_depth_met = inputs
        .training_population_counts_by_kind
        .get("prediction_csv")
        .copied()
        .unwrap_or(0)
        >= 2
        && inputs
            .training_population_counts_by_kind
            .get("committee_reference_pack")
            .copied()
            .unwrap_or(0)
            > 0
        && official_artifacts > 0;
    let depth_status = if inputs
        .training_population_counts_by_kind
        .get("prediction_csv")
        .copied()
        .unwrap_or(0)
        < 2
    {
        TrainingArtifactReferenceDepthStatus::NeedMorePredictionArtifacts
    } else if inputs
        .training_population_counts_by_kind
        .get("committee_reference_pack")
        .copied()
        .unwrap_or(0)
        == 0
    {
        TrainingArtifactReferenceDepthStatus::NeedMoreCommitteeArtifacts
    } else if official_artifacts == 0 {
        TrainingArtifactReferenceDepthStatus::NeedMoreOfficialArtifacts
    } else if !weak_reference_kinds.is_empty() {
        TrainingArtifactReferenceDepthStatus::ReferenceDepthReadyWithWarnings
    } else {
        TrainingArtifactReferenceDepthStatus::ReferenceDepthReady
    };
    TrainingArtifactReferenceDepthReport {
        report_id: config.interpretation_id.clone(),
        artifact_counts_by_kind: inputs.training_population_counts_by_kind.clone(),
        artifact_counts_by_source_class: inputs.training_population_counts_by_source_class.clone(),
        minimum_reference_depth_met,
        weak_reference_kinds,
        depth_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TrainingArtifactReferenceDepthReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_evidence_weighted_sequence_core_decision_gate(
    _config: &PrototypeComparisonInterpretationConfig,
    policy: &PrototypeEvidenceWeightingPolicy,
    confidence: &PrototypeComparisonConfidenceReport,
    winner_gate: &PrototypeWinnerInterpretationGate,
    disagreement: &PrototypeDisagreementMatrix,
    audit: &CommitteeReferenceCoverageAuditV2,
    lineage: &TrainingArtifactLineageCompletenessReport,
) -> EvidenceWeightedSequenceCoreDecisionGate {
    let decision_status = if winner_gate.selected_interpretation
        == PrototypeWinnerInterpretationStatus::Mamba3FinBetterDiagnostic
    {
        EvidenceWeightedSequenceCoreDecisionStatus::PreferMamba3FinDiagnostic
    } else if winner_gate.selected_interpretation
        == PrototypeWinnerInterpretationStatus::GatedDeltaNetBetterDiagnostic
    {
        EvidenceWeightedSequenceCoreDecisionStatus::PreferGatedDeltaNetDiagnostic
    } else if winner_gate.selected_interpretation
        == PrototypeWinnerInterpretationStatus::CommitteeBetterDiagnostic
    {
        EvidenceWeightedSequenceCoreDecisionStatus::PreferCommitteeDiagnostic
    } else if matches!(
        policy.policy_status,
        PrototypeEvidenceWeightingPolicyStatus::NeedsOfficialEvidence
    ) || matches!(
        confidence.confidence_status,
        PrototypeComparisonConfidenceStatus::InsufficientEvidence
    ) {
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreEvidence
    } else if matches!(
        audit.audit_status,
        CommitteeReferenceCoverageAuditStatus::NeedMoreOutcomeReferences
            | CommitteeReferenceCoverageAuditStatus::NeedMoreNoTradeReferences
            | CommitteeReferenceCoverageAuditStatus::NeedMoreRiskDeniedReferences
            | CommitteeReferenceCoverageAuditStatus::NeedMoreOfficialReferences
    ) {
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreCommitteeReferences
    } else if lineage.completeness_status
        == TrainingArtifactLineageCompletenessStatus::MissingCriticalArtifacts
    {
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreEvidence
    } else if disagreement.matrix_status == PrototypeDisagreementMatrixStatus::HighDisagreement {
        EvidenceWeightedSequenceCoreDecisionStatus::MixedOrInconclusive
    } else {
        EvidenceWeightedSequenceCoreDecisionStatus::KeepBothAsResearchCandidates
    };
    let final_recommendation = match decision_status {
        EvidenceWeightedSequenceCoreDecisionStatus::KeepBothAsResearchCandidates => {
            SequenceCorePrototypeFinalRecommendation::KeepBothAsResearchCandidates
        }
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreCommitteeReferences => {
            SequenceCorePrototypeFinalRecommendation::NeedCommitteeComparison
        }
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreEvidence => {
            SequenceCorePrototypeFinalRecommendation::NeedMoreRealEvidence
        }
        _ => SequenceCorePrototypeFinalRecommendation::HoldRuntimeDeferred,
    };
    EvidenceWeightedSequenceCoreDecisionGate {
        gate_id: "sequence-core-decision".to_string(),
        evidence_weighting_status: policy.policy_status,
        confidence_status: confidence.confidence_status,
        winner_gate_status: winner_gate.selected_interpretation,
        disagreement_status: disagreement.matrix_status,
        committee_reference_status: audit.audit_status,
        training_lineage_status: lineage.completeness_status,
        decision_status,
        runtime_allowed: false,
        training_allowed: false,
        live_inference_allowed: false,
        final_recommendation,
        reason_codes: stable_reason_codes(&[
            ReasonCode::EvidenceWeightedSequenceCoreDecisionGateBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_prototype_comparison_interpretation_report(
    config: &PrototypeComparisonInterpretationConfig,
    inputs: &PrototypeComparisonInterpretationInputs,
    winner_gate: &PrototypeWinnerInterpretationGate,
    audit: &CommitteeReferenceCoverageAuditV2,
    defensive: &NoTradeRiskDeniedInterpretationReport,
    lineage: &TrainingArtifactLineageCompletenessReport,
    decision_gate: &EvidenceWeightedSequenceCoreDecisionGate,
) -> PrototypeComparisonInterpretationReport {
    let mut final_recommendations = vec![
        PrototypeComparisonInterpretationStatus::KeepTrinity,
        PrototypeComparisonInterpretationStatus::KeepResearchOnly,
        PrototypeComparisonInterpretationStatus::KeepPaperOnly,
        PrototypeComparisonInterpretationStatus::HoldMambaRuntimeDeferred,
        PrototypeComparisonInterpretationStatus::HoldGatedDeltaNetRuntimeDeferred,
    ];
    let interpretation_status = match decision_gate.decision_status {
        EvidenceWeightedSequenceCoreDecisionStatus::PreferMamba3FinDiagnostic => {
            final_recommendations
                .push(PrototypeComparisonInterpretationStatus::Mamba3FinResearchCandidate);
            PrototypeComparisonInterpretationStatus::PrototypeComparisonDiagnosticOnly
        }
        EvidenceWeightedSequenceCoreDecisionStatus::PreferGatedDeltaNetDiagnostic => {
            final_recommendations
                .push(PrototypeComparisonInterpretationStatus::GatedDeltaNetResearchCandidate);
            PrototypeComparisonInterpretationStatus::PrototypeComparisonDiagnosticOnly
        }
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreCommitteeReferences => {
            final_recommendations
                .push(PrototypeComparisonInterpretationStatus::NeedMoreCommitteeReferenceCoverage);
            PrototypeComparisonInterpretationStatus::NeedMoreCommitteeReferenceCoverage
        }
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreEvidence => {
            if defensive.interpretation_status
                != NoTradeRiskDeniedInterpretationStatus::DefensiveAxesReady
            {
                final_recommendations
                    .push(PrototypeComparisonInterpretationStatus::NeedMoreNoTradeRiskDeniedDepth);
            } else {
                final_recommendations
                    .push(PrototypeComparisonInterpretationStatus::NeedMoreRealEvidence);
            }
            PrototypeComparisonInterpretationStatus::MixedOrInconclusive
        }
        EvidenceWeightedSequenceCoreDecisionStatus::KeepBothAsResearchCandidates => {
            final_recommendations
                .push(PrototypeComparisonInterpretationStatus::PrototypeInterpretationReady);
            PrototypeComparisonInterpretationStatus::PrototypeInterpretationReady
        }
        _ => PrototypeComparisonInterpretationStatus::MixedOrInconclusive,
    };
    PrototypeComparisonInterpretationReport {
        report_id: config.interpretation_id.clone(),
        raw_comparison_status: inputs.comparison_report.comparison_status,
        mamba3fin_signal: if inputs.comparison_report.comparison_status
            == SequenceCorePrototypeComparisonStatus::Mamba3FinBetterDiagnostic
        {
            PrototypeComparisonInterpretationStatus::Mamba3FinResearchCandidate
        } else {
            PrototypeComparisonInterpretationStatus::HoldMambaRuntimeDeferred
        },
        gated_deltanet_signal: if inputs.comparison_report.comparison_status
            == SequenceCorePrototypeComparisonStatus::GatedDeltaNetBetterDiagnostic
        {
            PrototypeComparisonInterpretationStatus::GatedDeltaNetResearchCandidate
        } else {
            PrototypeComparisonInterpretationStatus::HoldGatedDeltaNetRuntimeDeferred
        },
        committee_reference_signal: if matches!(
            audit.audit_status,
            CommitteeReferenceCoverageAuditStatus::CommitteeReferenceCoverageReady
                | CommitteeReferenceCoverageAuditStatus::CommitteeReferenceCoverageReadyWithWarnings
        ) {
            PrototypeComparisonInterpretationStatus::KeepTrinity
        } else {
            PrototypeComparisonInterpretationStatus::NeedMoreCommitteeReferenceCoverage
        },
        no_trade_risk_denied_signal: if defensive.interpretation_status
            == NoTradeRiskDeniedInterpretationStatus::DefensiveAxesReady
        {
            PrototypeComparisonInterpretationStatus::KeepResearchOnly
        } else {
            PrototypeComparisonInterpretationStatus::NeedMoreNoTradeRiskDeniedDepth
        },
        training_lineage_signal: if lineage.completeness_status
            == TrainingArtifactLineageCompletenessStatus::MissingCriticalArtifacts
        {
            PrototypeComparisonInterpretationStatus::NeedMoreRealEvidence
        } else {
            PrototypeComparisonInterpretationStatus::KeepPaperOnly
        },
        interpretation_summary: vec![
            format!("winner_gate={:?}", winner_gate.selected_interpretation),
            format!("committee_reference={:?}", audit.audit_status),
            format!("decision_gate={:?}", decision_gate.decision_status),
        ],
        final_recommendations,
        interpretation_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::PrototypeComparisonInterpretationReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_control_tower_prototype_interpretation_panel(
    config: &PrototypeComparisonInterpretationConfig,
    interpretation: &PrototypeComparisonInterpretationReport,
    confidence: &PrototypeComparisonConfidenceReport,
    winner_gate: &PrototypeWinnerInterpretationGate,
    disagreement: &PrototypeDisagreementMatrix,
    audit: &CommitteeReferenceCoverageAuditV2,
    defensive: &NoTradeRiskDeniedInterpretationReport,
    lineage: &TrainingArtifactLineageCompletenessReport,
    decision_gate: &EvidenceWeightedSequenceCoreDecisionGate,
    runbook: &SequenceCoreDecisionRunbook,
) -> ControlTowerPrototypeInterpretationPanel {
    ControlTowerPrototypeInterpretationPanel {
        panel_id: config.interpretation_id.clone(),
        prototype_interpretation_status: interpretation.interpretation_status,
        confidence_status: confidence.confidence_status,
        winner_gate_status: winner_gate.selected_interpretation,
        disagreement_status: disagreement.matrix_status,
        committee_reference_status: audit.audit_status,
        no_trade_risk_denied_status: defensive.interpretation_status,
        lineage_completeness_status: lineage.completeness_status,
        decision_gate_status: decision_gate.decision_status,
        mamba3fin_status: interpretation.mamba3fin_signal,
        gated_deltanet_status: interpretation.gated_deltanet_signal,
        runtime_deferred_status:
            "runtime deferred; no Mamba/Gated runtime, no training, no live inference".to_string(),
        next_actions: runbook
            .steps
            .iter()
            .take(4)
            .map(|step| format!("{step:?}"))
            .collect(),
        warnings: vec![
            "read-only static interpretation panel".to_string(),
            "no runtime or training selection".to_string(),
        ],
        reason_codes: stable_reason_codes(&[
            ReasonCode::ControlTowerPrototypeInterpretationPanelBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_sequence_core_decision_runbook(
    config: &PrototypeComparisonInterpretationConfig,
    decision_gate: &EvidenceWeightedSequenceCoreDecisionGate,
    closure_plan: &CommitteeReferenceDepthClosurePlan,
) -> SequenceCoreDecisionRunbook {
    let mut steps = vec![
        SequenceCoreDecisionRunbookStepKind::RunPrototypeInterpretation,
        SequenceCoreDecisionRunbookStepKind::AuditCommitteeReferenceCoverage,
        SequenceCoreDecisionRunbookStepKind::BuildCommitteeReferenceClosurePlan,
        SequenceCoreDecisionRunbookStepKind::RunDisagreementReport,
        SequenceCoreDecisionRunbookStepKind::RunTrainingLineageCompleteness,
        SequenceCoreDecisionRunbookStepKind::RefreshControlTower,
    ];
    let mut blocked_steps = Vec::new();
    let (primary_next_step, runbook_status) = match decision_gate.decision_status {
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreCommitteeReferences => {
            blocked_steps.push(SequenceCoreDecisionRunbookStepKind::StopDueToWeakEvidence);
            (
                SequenceCoreDecisionRunbookStepKind::BuildCommitteeReferenceClosurePlan,
                SequenceCoreDecisionRunbookStatus::NeedMoreCommitteeReferences,
            )
        }
        EvidenceWeightedSequenceCoreDecisionStatus::NeedMoreEvidence => {
            blocked_steps.push(SequenceCoreDecisionRunbookStepKind::StopDueToWeakEvidence);
            (
                SequenceCoreDecisionRunbookStepKind::RunPrototypeInterpretation,
                SequenceCoreDecisionRunbookStatus::NeedMoreRealEvidence,
            )
        }
        _ => {
            blocked_steps.push(SequenceCoreDecisionRunbookStepKind::StopDueToRuntimeDeferred);
            (
                SequenceCoreDecisionRunbookStepKind::RefreshControlTower,
                SequenceCoreDecisionRunbookStatus::RunbookReady,
            )
        }
    };
    if closure_plan.plan_status != CommitteeReferenceDepthClosurePlanStatus::ClosurePlanReady {
        steps.push(SequenceCoreDecisionRunbookStepKind::BuildCommitteeReferenceClosurePlan);
    }
    SequenceCoreDecisionRunbook {
        runbook_id: config.interpretation_id.clone(),
        steps,
        primary_next_step,
        blocked_steps,
        runbook_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCoreDecisionRunbookBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_prototype_comparison_interpretation_summary(
    interpretation: &PrototypeComparisonInterpretationReport,
    confidence: &PrototypeComparisonConfidenceReport,
    winner_gate: &PrototypeWinnerInterpretationGate,
    audit: &CommitteeReferenceCoverageAuditV2,
    decision_gate: &EvidenceWeightedSequenceCoreDecisionGate,
) -> String {
    [
        format!(
            "interpretation_status={:?}",
            interpretation.interpretation_status
        ),
        format!("confidence_status={:?}", confidence.confidence_status),
        format!("winner_gate={:?}", winner_gate.selected_interpretation),
        format!("committee_reference={:?}", audit.audit_status),
        format!("decision_gate={:?}", decision_gate.decision_status),
    ]
    .join("\n")
}

fn write_prototype_interpretation_storage_artifacts(
    config: &PrototypeComparisonInterpretationConfig,
    interpretation: &PrototypeComparisonInterpretationReport,
    policy: &PrototypeEvidenceWeightingPolicy,
    confidence: &PrototypeComparisonConfidenceReport,
    winner_gate: &PrototypeWinnerInterpretationGate,
    disagreement: &PrototypeDisagreementMatrix,
    failure_modes: &PrototypeFailureModeReport,
    synthesis: &PrototypeCalibrationRiskSynthesisReport,
    defensive: &NoTradeRiskDeniedInterpretationReport,
    audit: &CommitteeReferenceCoverageAuditV2,
    closure_plan: &CommitteeReferenceDepthClosurePlan,
    representativeness: &CommitteeScenarioRepresentativenessReport,
    committee_disagreement: &CommitteeSequenceDisagreementReport,
    decision_gate: &EvidenceWeightedSequenceCoreDecisionGate,
    lineage: &TrainingArtifactLineageCompletenessReport,
    reference_depth: &TrainingArtifactReferenceDepthReport,
    panel: &ControlTowerPrototypeInterpretationPanel,
    runbook: &SequenceCoreDecisionRunbook,
    final_summary: &str,
) -> Result<(OperatorBriefingStorageReport, String), String> {
    let dir = config.output_dir();
    fs::create_dir_all(&dir).map_err(|err| err.to_string())?;
    write_text_report(
        &dir,
        "prototype_comparison_interpretation.txt",
        interpretation,
    )?;
    write_text_report(&dir, "evidence_weighting_policy.txt", policy)?;
    write_text_report(&dir, "comparison_confidence.txt", confidence)?;
    write_text_report(&dir, "winner_interpretation_gate.txt", winner_gate)?;
    write_text_report(&dir, "disagreement_matrix.txt", disagreement)?;
    write_text_report(&dir, "failure_modes.txt", failure_modes)?;
    write_text_report(&dir, "calibration_risk_synthesis.txt", synthesis)?;
    write_text_report(&dir, "no_trade_risk_denied_interpretation.txt", defensive)?;
    write_text_report(&dir, "committee_reference_coverage_v2.txt", audit)?;
    write_text_report(
        &dir,
        "committee_reference_depth_closure_plan.txt",
        closure_plan,
    )?;
    write_text_report(
        &dir,
        "committee_scenario_representativeness.txt",
        representativeness,
    )?;
    write_text_report(
        &dir,
        "committee_sequence_disagreement.txt",
        committee_disagreement,
    )?;
    write_text_report(&dir, "evidence_weighted_decision_gate.txt", decision_gate)?;
    write_text_report(&dir, "training_lineage_completeness.txt", lineage)?;
    write_text_report(&dir, "training_reference_depth.txt", reference_depth)?;
    write_text_report(
        &dir,
        "control_tower_prototype_interpretation_panel.txt",
        panel,
    )?;
    write_text_report(&dir, "sequence_core_decision_runbook.txt", runbook)?;
    fs::write(dir.join("summary.txt"), final_summary).map_err(|err| err.to_string())?;
    let storage_bytes = fs::read_dir(&dir)
        .map_err(|err| err.to_string())?
        .filter_map(Result::ok)
        .filter_map(|entry| entry.metadata().ok().map(|meta| meta.len() as usize))
        .sum::<usize>();
    let storage_report = OperatorBriefingStorageReport {
        artifact_count: 18,
        storage_bytes,
        max_bytes: config.max_bytes as usize,
        within_budget: storage_bytes <= config.max_bytes as usize,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    };
    write_text_report(&dir, "storage_report.txt", &storage_report)?;
    Ok((storage_report, final_summary.to_string()))
}

