fn default_official_evidence_depth_output_root() -> String {
    "target/soma_official_evidence_depth".to_string()
}

fn default_sprint82_max_symbols() -> usize {
    64
}

fn default_sprint82_max_timeframes() -> usize {
    16
}

fn default_sprint82_max_horizons() -> usize {
    16
}

impl OfficialEvidenceDepthExpansionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.expansion_id.trim().is_empty() {
            return Err("official evidence depth config requires expansion_id".to_string());
        }
        if !path_is_local(&self.output_root) {
            return Err("official evidence depth output_root must be local".to_string());
        }
        for path in self.all_support_paths() {
            if !path_is_local(&path) {
                return Err("official evidence depth paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(&path);
            if !absolute.exists() {
                return Err(format!(
                    "official evidence depth path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        if self.max_rows == 0
            || self.max_symbols == 0
            || self.max_timeframes == 0
            || self.max_horizons == 0
            || self.max_bytes == 0
        {
            return Err("official evidence depth limits must be positive".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.output_root).join(&self.expansion_id)
    }

    fn all_support_paths(&self) -> Vec<String> {
        stable_ordered_strings(
            &self
                .sprint81_interpretation_paths
                .iter()
                .chain(self.real_evidence_paths.iter())
                .chain(self.kis_canonical_csv_paths.iter())
                .chain(self.kis_provenance_paths.iter())
                .chain(self.kis_preflight_paths.iter())
                .chain(self.sequence_export_manifest_paths.iter())
                .chain(self.feature_schema_manifest_paths.iter())
                .chain(self.label_manifest_paths.iter())
                .chain(self.committee_reference_paths.iter())
                .cloned()
                .collect::<Vec<_>>(),
        )
    }
}

impl CommitteeReferenceClosureConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.closure_id.trim().is_empty() {
            return Err("committee reference closure config requires closure_id".to_string());
        }
        if !path_is_local(&self.output_root) {
            return Err("committee reference closure output_root must be local".to_string());
        }
        for path in self.all_support_paths() {
            if !path_is_local(&path) {
                return Err("committee reference closure paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(&path);
            if !absolute.exists() {
                return Err(format!(
                    "committee reference closure path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        Ok(())
    }

    fn all_support_paths(&self) -> Vec<String> {
        stable_ordered_strings(
            &self
                .committee_reference_audit_paths
                .iter()
                .chain(self.committee_reference_depth_plan_paths.iter())
                .chain(self.official_evidence_depth_paths.iter())
                .chain(self.scenario_pack_paths.iter())
                .chain(self.outcome_pack_paths.iter())
                .chain(self.baseline_pack_paths.iter())
                .chain(self.no_trade_pack_paths.iter())
                .chain(self.risk_denied_pack_paths.iter())
                .chain(self.chair_trace_paths.iter())
                .chain(self.risk_trace_paths.iter())
                .cloned()
                .collect::<Vec<_>>(),
        )
    }
}

fn load_official_evidence_depth_inputs(
    config: &OfficialEvidenceDepthExpansionConfig,
) -> Result<OfficialEvidenceDepthInputs, String> {
    let sprint81_summary = config
        .sprint81_interpretation_paths
        .first()
        .map(|path| load_json_file::<Sprint82InterpretationSummaryInput>(path))
        .transpose()?
        .ok_or_else(|| {
            "official evidence depth requires sprint81 interpretation summary".to_string()
        })?;

    let mut snapshots = Vec::new();
    let mut confidence_snapshots = Vec::new();
    for path in &config.real_evidence_paths {
        if let Ok(snapshot) = load_json_file::<Sprint82OfficialEvidenceSnapshot>(path) {
            snapshots.push(snapshot);
            continue;
        }
        if let Ok(confidence) = load_json_file::<Sprint82ConfidenceSnapshot>(path) {
            confidence_snapshots.push(confidence);
        }
    }
    let before_snapshot = snapshots
        .first()
        .cloned()
        .ok_or_else(|| "official evidence depth requires before snapshot".to_string())?;
    let after_snapshot = snapshots
        .get(1)
        .cloned()
        .unwrap_or_else(|| before_snapshot.clone());
    let previous_confidence = confidence_snapshots.first().cloned().unwrap_or_default();
    let current_confidence = confidence_snapshots
        .get(1)
        .cloned()
        .unwrap_or_else(|| previous_confidence.clone());

    let mut official_scenario_pack_v3: Option<OfficialScenarioReferencePackV3> = None;
    let mut official_outcome_pack_v3: Option<OfficialOutcomeReferencePackV3> = None;
    let mut official_baseline_pack_v3: Option<OfficialBaselineReferencePackV3> = None;
    let mut official_no_trade_pack_v3: Option<OfficialNoTradeCounterfactualPackV3> = None;
    let mut official_risk_denied_pack_v3: Option<OfficialRiskDeniedCounterfactualPackV3> = None;
    for path in &config.committee_reference_paths {
        if official_scenario_pack_v3.is_none() {
            if let Ok(value) = load_json_file(path) {
                official_scenario_pack_v3 = Some(value);
                continue;
            }
        }
        if official_outcome_pack_v3.is_none() {
            if let Ok(value) = load_json_file(path) {
                official_outcome_pack_v3 = Some(value);
                continue;
            }
        }
        if official_baseline_pack_v3.is_none() {
            if let Ok(value) = load_json_file(path) {
                official_baseline_pack_v3 = Some(value);
                continue;
            }
        }
        if official_no_trade_pack_v3.is_none() {
            if let Ok(value) = load_json_file(path) {
                official_no_trade_pack_v3 = Some(value);
                continue;
            }
        }
        if official_risk_denied_pack_v3.is_none() {
            if let Ok(value) = load_json_file(path) {
                official_risk_denied_pack_v3 = Some(value);
            }
        }
    }

    Ok(OfficialEvidenceDepthInputs {
        sprint81_summary,
        before_snapshot,
        after_snapshot,
        previous_confidence,
        current_confidence,
        official_scenario_pack_v3: official_scenario_pack_v3
            .ok_or_else(|| "official evidence depth requires scenario pack v3".to_string())?,
        official_outcome_pack_v3: official_outcome_pack_v3
            .ok_or_else(|| "official evidence depth requires outcome pack v3".to_string())?,
        official_baseline_pack_v3: official_baseline_pack_v3
            .ok_or_else(|| "official evidence depth requires baseline pack v3".to_string())?,
        official_no_trade_pack_v3: official_no_trade_pack_v3
            .ok_or_else(|| "official evidence depth requires no-trade pack v3".to_string())?,
        official_risk_denied_pack_v3: official_risk_denied_pack_v3
            .ok_or_else(|| "official evidence depth requires risk-denied pack v3".to_string())?,
    })
}

fn build_official_evidence_depth_expansion_report(
    config: &OfficialEvidenceDepthExpansionConfig,
    inputs: &OfficialEvidenceDepthInputs,
) -> OfficialEvidenceDepthExpansionReport {
    let expansion_status = if config.require_provenance && !inputs.after_snapshot.provenance_ready {
        OfficialEvidenceDepthExpansionStatus::MissingProvenance
    } else if config.require_preflight && !inputs.after_snapshot.preflight_ready {
        OfficialEvidenceDepthExpansionStatus::MissingPreflight
    } else if config.require_no_lookahead && !inputs.after_snapshot.no_lookahead_safe {
        OfficialEvidenceDepthExpansionStatus::NoLookaheadBlocked
    } else if config.require_source_class && inputs.after_snapshot.source_promotions_detected > 0 {
        OfficialEvidenceDepthExpansionStatus::SourceBoundaryBlocked
    } else if inputs.after_snapshot.official_rows <= inputs.before_snapshot.official_rows {
        OfficialEvidenceDepthExpansionStatus::NeedMoreOfficialEvidence
    } else if inputs.after_snapshot.official_complete_rows
        <= inputs.before_snapshot.official_complete_rows
    {
        OfficialEvidenceDepthExpansionStatus::OfficialEvidenceDepthExpandedWithWarnings
    } else {
        OfficialEvidenceDepthExpansionStatus::OfficialEvidenceDepthExpanded
    };
    OfficialEvidenceDepthExpansionReport {
        expansion_id: config.expansion_id.clone(),
        rows_before: inputs.before_snapshot.rows,
        rows_after: inputs.after_snapshot.rows,
        official_rows_before: inputs.before_snapshot.official_rows,
        official_rows_after: inputs.after_snapshot.official_rows,
        official_complete_rows_before: inputs.before_snapshot.official_complete_rows,
        official_complete_rows_after: inputs.after_snapshot.official_complete_rows,
        symbols_before: inputs.before_snapshot.symbol_count,
        symbols_after: inputs.after_snapshot.symbol_count,
        timeframes_before: inputs.before_snapshot.timeframe_count,
        timeframes_after: inputs.after_snapshot.timeframe_count,
        horizons_before: inputs.before_snapshot.horizon_count,
        horizons_after: inputs.after_snapshot.horizon_count,
        added_official_rows: inputs
            .after_snapshot
            .official_rows
            .saturating_sub(inputs.before_snapshot.official_rows),
        added_complete_rows: inputs
            .after_snapshot
            .official_complete_rows
            .saturating_sub(inputs.before_snapshot.official_complete_rows),
        expansion_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::OfficialEvidenceDepthExpansionReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_reference_closure_report_from_snapshots(
    closure_id: &str,
    before: &Sprint82OfficialEvidenceSnapshot,
    after: &Sprint82OfficialEvidenceSnapshot,
    require_scenarios: bool,
    require_outcomes: bool,
    require_baselines: bool,
    require_no_trade: bool,
    require_risk_denied: bool,
    require_chair_trace: bool,
    require_risk_trace: bool,
) -> CommitteeReferenceClosureReport {
    let closure_status = if require_scenarios && after.scenario_count == 0 {
        CommitteeReferenceClosureStatus::NeedMoreScenarios
    } else if require_outcomes && after.outcome_count == 0 {
        CommitteeReferenceClosureStatus::NeedMoreOutcomes
    } else if require_baselines && after.baseline_count == 0 {
        CommitteeReferenceClosureStatus::NeedMoreBaselines
    } else if require_no_trade && after.no_trade_count == 0 {
        CommitteeReferenceClosureStatus::NeedMoreNoTrade
    } else if require_risk_denied && after.risk_denied_count == 0 {
        CommitteeReferenceClosureStatus::NeedMoreRiskDenied
    } else if (require_chair_trace && !after.chair_trace_ready)
        || (require_risk_trace && !after.risk_trace_ready)
    {
        CommitteeReferenceClosureStatus::NeedChairRiskTrace
    } else if after.scenario_count > before.scenario_count
        || after.outcome_count > before.outcome_count
        || after.baseline_count > before.baseline_count
        || after.no_trade_count > before.no_trade_count
        || after.risk_denied_count > before.risk_denied_count
    {
        CommitteeReferenceClosureStatus::CommitteeReferencesImproved
    } else {
        CommitteeReferenceClosureStatus::CommitteeReferencesClosed
    };
    CommitteeReferenceClosureReport {
        closure_id: closure_id.to_string(),
        scenario_count_before: before.scenario_count,
        scenario_count_after: after.scenario_count,
        outcome_count_before: before.outcome_count,
        outcome_count_after: after.outcome_count,
        baseline_count_before: before.baseline_count,
        baseline_count_after: after.baseline_count,
        no_trade_count_before: before.no_trade_count,
        no_trade_count_after: after.no_trade_count,
        risk_denied_count_before: before.risk_denied_count,
        risk_denied_count_after: after.risk_denied_count,
        chair_trace_ready: after.chair_trace_ready,
        risk_trace_ready: after.risk_trace_ready,
        closure_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeReferenceClosureReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_defensive_counterfactual_depth_report(
    report_id: &str,
    after: &Sprint82OfficialEvidenceSnapshot,
    no_trade_pack: &OfficialNoTradeCounterfactualPackV3,
    risk_denied_pack: &OfficialRiskDeniedCounterfactualPackV3,
) -> DefensiveCounterfactualDepthReport {
    let depth_status = if after.official_rows == 0 {
        DefensiveCounterfactualDepthStatus::NeedMoreOfficialDepth
    } else if no_trade_pack.no_trade_counterfactual_count == 0 {
        DefensiveCounterfactualDepthStatus::NeedMoreNoTradeDepth
    } else if risk_denied_pack.risk_denied_counterfactual_count == 0 {
        DefensiveCounterfactualDepthStatus::NeedMoreRiskDeniedDepth
    } else if no_trade_pack.no_trade_better_count == 0
        || risk_denied_pack.defensive_value_count == 0
    {
        DefensiveCounterfactualDepthStatus::DefensiveDepthReadyWithWarnings
    } else {
        DefensiveCounterfactualDepthStatus::DefensiveDepthReady
    };
    DefensiveCounterfactualDepthReport {
        report_id: report_id.to_string(),
        no_trade_depth: no_trade_pack.no_trade_counterfactual_count,
        risk_denied_depth: risk_denied_pack.risk_denied_counterfactual_count,
        defensive_value_summary: format!(
            "avoided_bad_trades={}",
            no_trade_pack.avoided_bad_trade_count
        ),
        opportunity_cost_summary: format!(
            "opportunity_cost={}",
            risk_denied_pack.opportunity_cost_count
        ),
        no_trade_interpretation: format!(
            "NoTrade remained better in {} official counterfactual cases",
            no_trade_pack.no_trade_better_count
        ),
        risk_denied_interpretation: format!(
            "RiskDenied preserved defensive value in {} official counterfactual cases",
            risk_denied_pack.defensive_value_count
        ),
        depth_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DefensiveCounterfactualDepthReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_official_reference_quality_report(
    report_id: &str,
    after: &Sprint82OfficialEvidenceSnapshot,
) -> OfficialReferenceQualityReport {
    let rows = usize::max(after.rows, 1) as f64;
    let quality_status = if !after.no_lookahead_safe && after.unsafe_rows > 0 {
        OfficialReferenceQualityStatus::NoLookaheadBlocked
    } else if after.source_boundary_violation_count > 0 {
        OfficialReferenceQualityStatus::SourceBoundaryViolation
    } else if after.official_complete_rows == 0 {
        OfficialReferenceQualityStatus::NeedMoreOfficialCompleteRows
    } else if after.outcome_count == 0
        || after.baseline_count == 0
        || after.no_trade_count == 0
        || after.risk_denied_count == 0
    {
        OfficialReferenceQualityStatus::NeedMoreReferences
    } else if after.official_complete_rows < after.official_rows {
        OfficialReferenceQualityStatus::ReferenceQualityReadyWithWarnings
    } else {
        OfficialReferenceQualityStatus::ReferenceQualityReady
    };
    OfficialReferenceQualityReport {
        report_id: report_id.to_string(),
        official_ratio: format_decimal(after.official_rows as f64 / rows),
        complete_ratio: format_decimal(after.official_complete_rows as f64 / rows),
        outcome_reference_ratio: format_decimal(after.outcome_count as f64 / rows),
        baseline_reference_ratio: format_decimal(after.baseline_count as f64 / rows),
        no_trade_reference_ratio: format_decimal(after.no_trade_count as f64 / rows),
        risk_denied_reference_ratio: format_decimal(after.risk_denied_count as f64 / rows),
        no_lookahead_safe_ratio: format_decimal(after.safe_rows as f64 / rows),
        source_boundary_violation_count: after.source_boundary_violation_count,
        quality_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::OfficialReferenceQualityReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_official_reference_diversity_report(
    report_id: &str,
    after: &Sprint82OfficialEvidenceSnapshot,
) -> OfficialReferenceDiversityReport {
    let diversity_status = if after.symbol_count < 2 {
        OfficialReferenceDiversityStatus::NeedMoreSymbols
    } else if after.timeframe_count < 2 {
        OfficialReferenceDiversityStatus::NeedMoreTimeframes
    } else if after.horizon_count < 2 {
        OfficialReferenceDiversityStatus::NeedMoreHorizons
    } else if after.outcome_distribution.len() < 2 {
        OfficialReferenceDiversityStatus::NeedOutcomeDiversity
    } else {
        OfficialReferenceDiversityStatus::ReferenceDiversityReady
    };
    OfficialReferenceDiversityReport {
        report_id: report_id.to_string(),
        symbol_count: after.symbol_count,
        market_count: after.market_count,
        timeframe_count: after.timeframe_count,
        horizon_count: after.horizon_count,
        outcome_distribution: after.outcome_distribution.clone(),
        regime_distribution: Some(after.regime_distribution.clone()),
        diversity_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::OfficialReferenceDiversityReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_official_reference_no_lookahead_audit(
    audit_id: &str,
    after: &Sprint82OfficialEvidenceSnapshot,
) -> OfficialReferenceNoLookaheadAudit {
    let audit_status = if after.checked_rows == 0 {
        OfficialReferenceNoLookaheadAuditStatus::InsufficientRows
    } else if after.unsafe_rows > 0 || !after.no_lookahead_safe {
        OfficialReferenceNoLookaheadAuditStatus::NoLookaheadViolation
    } else {
        OfficialReferenceNoLookaheadAuditStatus::NoLookaheadReady
    };
    OfficialReferenceNoLookaheadAudit {
        audit_id: audit_id.to_string(),
        checked_rows: after.checked_rows,
        safe_rows: after.safe_rows,
        unsafe_rows: after.unsafe_rows,
        violation_examples: after.violation_examples.clone(),
        audit_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::OfficialReferenceNoLookaheadAuditBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_official_reference_source_boundary_audit(
    audit_id: &str,
    after: &Sprint82OfficialEvidenceSnapshot,
) -> OfficialReferenceSourceBoundaryAudit {
    let audit_status =
        if after.source_promotions_detected > 0 || after.source_boundary_violation_count > 0 {
            OfficialReferenceSourceBoundaryAuditStatus::SourceBoundaryViolation
        } else {
            OfficialReferenceSourceBoundaryAuditStatus::SourceBoundaryReady
        };
    OfficialReferenceSourceBoundaryAudit {
        audit_id: audit_id.to_string(),
        official_rows: after
            .source_class_counts
            .get("OfficialKIS")
            .copied()
            .unwrap_or(0)
            + after
                .source_class_counts
                .get("OfficialKRXReference")
                .copied()
                .unwrap_or(0),
        research_only_rows: after
            .source_class_counts
            .get("ResearchOnly")
            .copied()
            .unwrap_or(0),
        diagnostic_rows: after
            .source_class_counts
            .get("DiagnosticOnly")
            .copied()
            .unwrap_or(0),
        fixture_rows: after
            .source_class_counts
            .get("FixtureOnly")
            .copied()
            .unwrap_or(0),
        source_promotions_detected: after.source_promotions_detected,
        audit_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::OfficialReferenceSourceBoundaryAuditBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn confidence_level_rank(level: PrototypeComparisonConfidenceLevel) -> i32 {
    match level {
        PrototypeComparisonConfidenceLevel::High => 4,
        PrototypeComparisonConfidenceLevel::Medium => 3,
        PrototypeComparisonConfidenceLevel::Low => 2,
        PrototypeComparisonConfidenceLevel::Insufficient => 1,
        PrototypeComparisonConfidenceLevel::DiagnosticOnly => 0,
    }
}

fn build_sequence_core_confidence_rerun_report(
    rerun_id: &str,
    previous: &Sprint82ConfidenceSnapshot,
    current: &Sprint82ConfidenceSnapshot,
) -> SequenceCoreConfidenceRerunReport {
    let score_before = confidence_level_rank(previous.mamba3fin_confidence)
        + confidence_level_rank(previous.gated_deltanet_confidence)
        + confidence_level_rank(previous.committee_confidence)
        + confidence_level_rank(previous.no_trade_confidence)
        + confidence_level_rank(previous.risk_denied_confidence);
    let score_after = confidence_level_rank(current.mamba3fin_confidence)
        + confidence_level_rank(current.gated_deltanet_confidence)
        + confidence_level_rank(current.committee_confidence)
        + confidence_level_rank(current.no_trade_confidence)
        + confidence_level_rank(current.risk_denied_confidence);
    let rerun_status = if matches!(
        current.confidence_status,
        PrototypeComparisonConfidenceStatus::InsufficientEvidence
    ) {
        SequenceCoreConfidenceRerunStatus::NeedMoreEvidence
    } else if score_after > score_before {
        SequenceCoreConfidenceRerunStatus::ConfidenceImproved
    } else if score_after < score_before {
        SequenceCoreConfidenceRerunStatus::ConfidenceWorsened
    } else {
        SequenceCoreConfidenceRerunStatus::ConfidenceUnchanged
    };
    SequenceCoreConfidenceRerunReport {
        rerun_id: rerun_id.to_string(),
        previous_confidence_status: previous.confidence_status,
        current_confidence_status: current.confidence_status,
        mamba3fin_previous_confidence: previous.mamba3fin_confidence,
        mamba3fin_current_confidence: current.mamba3fin_confidence,
        gated_deltanet_previous_confidence: previous.gated_deltanet_confidence,
        gated_deltanet_current_confidence: current.gated_deltanet_confidence,
        committee_previous_confidence: previous.committee_confidence,
        committee_current_confidence: current.committee_confidence,
        no_trade_previous_confidence: previous.no_trade_confidence,
        no_trade_current_confidence: current.no_trade_confidence,
        risk_denied_previous_confidence: previous.risk_denied_confidence,
        risk_denied_current_confidence: current.risk_denied_confidence,
        confidence_improved: score_after > score_before,
        rerun_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::SequenceCoreConfidenceRerunReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_evidence_weighted_decision_gate_v2(
    gate_id: &str,
    official: &OfficialEvidenceDepthExpansionReport,
    closure: &CommitteeReferenceClosureReport,
    defensive: &DefensiveCounterfactualDepthReport,
    quality: &OfficialReferenceQualityReport,
    diversity: &OfficialReferenceDiversityReport,
    no_lookahead: &OfficialReferenceNoLookaheadAudit,
    source_boundary: &OfficialReferenceSourceBoundaryAudit,
    rerun: &SequenceCoreConfidenceRerunReport,
) -> EvidenceWeightedDecisionGateV2 {
    let decision_status = if matches!(
        official.expansion_status,
        OfficialEvidenceDepthExpansionStatus::NeedMoreOfficialEvidence
            | OfficialEvidenceDepthExpansionStatus::MissingProvenance
            | OfficialEvidenceDepthExpansionStatus::MissingPreflight
    ) {
        EvidenceWeightedDecisionGateV2Status::NeedMoreOfficialEvidence
    } else if matches!(
        closure.closure_status,
        CommitteeReferenceClosureStatus::NeedMoreScenarios
            | CommitteeReferenceClosureStatus::NeedMoreOutcomes
            | CommitteeReferenceClosureStatus::NeedMoreBaselines
            | CommitteeReferenceClosureStatus::NeedMoreNoTrade
            | CommitteeReferenceClosureStatus::NeedMoreRiskDenied
            | CommitteeReferenceClosureStatus::NeedChairRiskTrace
    ) {
        EvidenceWeightedDecisionGateV2Status::NeedMoreCommitteeReferences
    } else if matches!(
        defensive.depth_status,
        DefensiveCounterfactualDepthStatus::NeedMoreNoTradeDepth
            | DefensiveCounterfactualDepthStatus::NeedMoreRiskDeniedDepth
            | DefensiveCounterfactualDepthStatus::NeedMoreOfficialDepth
    ) {
        EvidenceWeightedDecisionGateV2Status::NeedMoreDefensiveCounterfactuals
    } else if matches!(
        rerun.rerun_status,
        SequenceCoreConfidenceRerunStatus::NeedMoreEvidence
    ) || matches!(
        quality.quality_status,
        OfficialReferenceQualityStatus::NeedMoreOfficialCompleteRows
            | OfficialReferenceQualityStatus::NeedMoreReferences
    ) || matches!(
        diversity.diversity_status,
        OfficialReferenceDiversityStatus::NeedMoreSymbols
            | OfficialReferenceDiversityStatus::NeedMoreTimeframes
            | OfficialReferenceDiversityStatus::NeedMoreHorizons
            | OfficialReferenceDiversityStatus::NeedOutcomeDiversity
    ) || matches!(
        no_lookahead.audit_status,
        OfficialReferenceNoLookaheadAuditStatus::NoLookaheadViolation
    ) || matches!(
        source_boundary.audit_status,
        OfficialReferenceSourceBoundaryAuditStatus::SourceBoundaryViolation
    ) {
        EvidenceWeightedDecisionGateV2Status::MixedOrInconclusive
    } else {
        EvidenceWeightedDecisionGateV2Status::KeepBothAsResearchCandidates
    };
    let final_recommendation = match decision_status {
        EvidenceWeightedDecisionGateV2Status::KeepBothAsResearchCandidates => {
            PrototypeComparisonInterpretationStatus::KeepResearchOnly
        }
        EvidenceWeightedDecisionGateV2Status::NeedMoreOfficialEvidence => {
            PrototypeComparisonInterpretationStatus::NeedMoreRealEvidence
        }
        EvidenceWeightedDecisionGateV2Status::NeedMoreCommitteeReferences => {
            PrototypeComparisonInterpretationStatus::NeedMoreCommitteeReferenceCoverage
        }
        EvidenceWeightedDecisionGateV2Status::NeedMoreDefensiveCounterfactuals => {
            PrototypeComparisonInterpretationStatus::NeedMoreNoTradeRiskDeniedDepth
        }
        _ => PrototypeComparisonInterpretationStatus::MixedOrInconclusive,
    };
    EvidenceWeightedDecisionGateV2 {
        gate_id: gate_id.to_string(),
        official_evidence_depth_status: official.expansion_status,
        committee_reference_closure_status: closure.closure_status,
        defensive_counterfactual_status: defensive.depth_status,
        reference_quality_status: quality.quality_status,
        reference_diversity_status: diversity.diversity_status,
        no_lookahead_status: no_lookahead.audit_status,
        source_boundary_status: source_boundary.audit_status,
        confidence_rerun_status: rerun.rerun_status,
        decision_status,
        runtime_allowed: false,
        training_allowed: false,
        live_inference_allowed: false,
        final_recommendation,
        reason_codes: stable_reason_codes(&[
            ReasonCode::EvidenceWeightedDecisionGateV2Built,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_committee_vs_prototype_reference_closure_report(
    report_id: &str,
    before: &Sprint82OfficialEvidenceSnapshot,
    after: &Sprint82OfficialEvidenceSnapshot,
) -> CommitteeVsPrototypeReferenceClosureReport {
    let closure_status = if after.comparable_rows_mamba == 0
        || after.comparable_rows_gated == 0
        || after.comparable_rows_no_trade == 0
        || after.comparable_rows_risk_denied == 0
    {
        CommitteeVsPrototypeReferenceClosureStatus::NeedMoreComparableRows
    } else if after.comparable_rows_mamba > before.comparable_rows_mamba
        || after.comparable_rows_gated > before.comparable_rows_gated
        || after.comparable_rows_no_trade > before.comparable_rows_no_trade
        || after.comparable_rows_risk_denied > before.comparable_rows_risk_denied
    {
        CommitteeVsPrototypeReferenceClosureStatus::ComparisonReferencesImproved
    } else {
        CommitteeVsPrototypeReferenceClosureStatus::ComparisonReferencesClosed
    };
    CommitteeVsPrototypeReferenceClosureReport {
        report_id: report_id.to_string(),
        comparable_rows_before: before.comparable_rows_mamba
            + before.comparable_rows_gated
            + before.comparable_rows_no_trade
            + before.comparable_rows_risk_denied,
        comparable_rows_after: after.comparable_rows_mamba
            + after.comparable_rows_gated
            + after.comparable_rows_no_trade
            + after.comparable_rows_risk_denied,
        committee_vs_mamba3fin_rows: after.comparable_rows_mamba,
        committee_vs_gated_deltanet_rows: after.comparable_rows_gated,
        committee_vs_no_trade_rows: after.comparable_rows_no_trade,
        committee_vs_risk_denied_rows: after.comparable_rows_risk_denied,
        closure_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::CommitteeVsPrototypeReferenceClosureReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_training_artifact_reference_depth_closure_report(
    report_id: &str,
    before: &Sprint82OfficialEvidenceSnapshot,
    after: &Sprint82OfficialEvidenceSnapshot,
) -> TrainingArtifactReferenceDepthClosureReport {
    let closure_status = if after.prediction_artifact_count == 0 {
        TrainingArtifactReferenceDepthClosureStatus::NeedMorePredictionArtifacts
    } else if after.committee_artifact_count == 0 {
        TrainingArtifactReferenceDepthClosureStatus::NeedMoreCommitteeArtifacts
    } else if after.official_artifact_count == 0 {
        TrainingArtifactReferenceDepthClosureStatus::NeedMoreOfficialArtifacts
    } else if after.prediction_artifact_count > before.prediction_artifact_count
        || after.committee_artifact_count > before.committee_artifact_count
        || after.official_artifact_count > before.official_artifact_count
    {
        TrainingArtifactReferenceDepthClosureStatus::TrainingReferenceDepthImproved
    } else {
        TrainingArtifactReferenceDepthClosureStatus::TrainingReferenceDepthClosed
    };
    TrainingArtifactReferenceDepthClosureReport {
        report_id: report_id.to_string(),
        prediction_artifact_count_before: before.prediction_artifact_count,
        prediction_artifact_count_after: after.prediction_artifact_count,
        committee_artifact_count_before: before.committee_artifact_count,
        committee_artifact_count_after: after.committee_artifact_count,
        official_artifact_count_before: before.official_artifact_count,
        official_artifact_count_after: after.official_artifact_count,
        weak_reference_kinds_before: before.weak_reference_kinds.clone(),
        weak_reference_kinds_after: after.weak_reference_kinds.clone(),
        closure_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::TrainingArtifactReferenceDepthClosureReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

