impl CommitteeReferenceClosureRunner {
    pub fn run(
        &self,
        config: &CommitteeReferenceClosureConfig,
    ) -> Result<CommitteeReferenceClosureReport, String> {
        config.validate()?;
        let mut snapshots = Vec::new();
        for path in &config.official_evidence_depth_paths {
            if let Ok(snapshot) = load_json_file::<Sprint82OfficialEvidenceSnapshot>(path) {
                snapshots.push(snapshot);
            }
        }
        let before = snapshots
            .first()
            .cloned()
            .ok_or_else(|| "committee reference closure requires before snapshot".to_string())?;
        let after = snapshots.get(1).cloned().unwrap_or_else(|| before.clone());
        Ok(build_committee_reference_closure_report_from_snapshots(
            &config.closure_id,
            &before,
            &after,
            config.require_scenarios,
            config.require_outcomes,
            config.require_baselines,
            config.require_no_trade,
            config.require_risk_denied,
            config.require_chair_trace,
            config.require_risk_trace,
        ))
    }
}

