fn default_sprint83_output_root() -> String {
    "target/soma_sprint83_acceptance_recovery".to_string()
}

fn default_sprint83_max_fixture_bytes() -> u64 {
    262_144
}

fn default_sprint83_max_cli_smoke_commands() -> usize {
    32
}

impl Sprint83AcceptanceRecoveryConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        let config: Self = toml::from_str(&text).map_err(|err| err.to_string())?;
        config.validate()?;
        Ok(config)
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.recovery_id.trim().is_empty() {
            return Err("sprint83 acceptance recovery config requires recovery_id".to_string());
        }
        if !path_is_local(&self.output_root) {
            return Err("sprint83 acceptance recovery output_root must be local".to_string());
        }
        for path in self
            .sprint82_report_paths
            .iter()
            .chain(self.sprint82_fixture_paths.iter())
            .chain(self.sprint82_cli_smoke_paths.iter())
            .chain(self.workspace_timing_paths.iter())
        {
            if !path_is_local(path) {
                return Err("sprint83 acceptance recovery paths must be local".to_string());
            }
            let absolute = sprint76_absolutize(path);
            if !absolute.exists() {
                return Err(format!(
                    "sprint83 acceptance recovery path does not exist: {}",
                    absolute.display()
                ));
            }
        }
        if self.max_fixture_bytes == 0 || self.max_cli_smoke_commands == 0 {
            return Err("sprint83 acceptance recovery limits must be positive".to_string());
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        sprint76_absolutize(&self.output_root).join(&self.recovery_id)
    }
}

impl EvidenceDepthFixtureHardeningConfig {
    pub fn from_recovery_config(config: &Sprint83AcceptanceRecoveryConfig) -> Self {
        Self {
            hardening_id: config.recovery_id.clone(),
            sprint82_fixture_paths: config.sprint82_fixture_paths.clone(),
            output_root: config.output_root.clone(),
            max_fixture_bytes: config.max_fixture_bytes,
            require_fixture_determinism: config.require_fixture_determinism,
            require_source_boundary_audit: config.require_source_boundary_audit,
            require_no_lookahead_audit: config.require_no_lookahead_audit,
            reason_codes: config.reason_codes.clone(),
        }
    }
}

fn load_sprint83_inputs(
    config: &Sprint83AcceptanceRecoveryConfig,
) -> Result<Sprint83Inputs, String> {
    let report_summary = config
        .sprint82_report_paths
        .first()
        .map(|path| load_json_file::<Sprint83ReportSummaryInput>(path))
        .transpose()?
        .ok_or_else(|| {
            "sprint83 acceptance recovery requires sprint82 report summary".to_string()
        })?;
    let fixture_manifest = config
        .sprint82_fixture_paths
        .iter()
        .find_map(|path| load_json_file::<Sprint83FixtureManifest>(path).ok())
        .ok_or_else(|| "sprint83 acceptance recovery requires fixture manifest".to_string())?;
    let cli_smoke_manifest = config
        .sprint82_cli_smoke_paths
        .first()
        .map(|path| load_json_file::<Sprint83CliSmokeManifest>(path))
        .transpose()?
        .ok_or_else(|| {
            "sprint83 acceptance recovery requires sprint82 cli smoke manifest".to_string()
        })?;
    let workspace_attempts = config
        .workspace_timing_paths
        .first()
        .map(|path| load_json_file::<Sprint83WorkspaceAttemptsInput>(path))
        .transpose()?
        .ok_or_else(|| {
            "sprint83 acceptance recovery requires workspace attempts input".to_string()
        })?;
    Ok(Sprint83Inputs {
        report_summary,
        fixture_manifest,
        cli_smoke_manifest,
        workspace_attempts,
    })
}

fn sprint83_required_fixture_kinds() -> &'static [&'static str] {
    &[
        "official_evidence_depth_before",
        "official_evidence_depth_after",
        "official_scenarios_v3",
        "official_outcomes_v3",
        "official_baselines_v3",
        "official_notrade_counterfactuals_v3",
        "official_riskdenied_counterfactuals_v3",
        "sequence_core_confidence_before",
        "sequence_core_confidence_after",
        "expected_summary",
    ]
}

fn sprint83_fixture_entry_by_kind<'a>(
    manifest: &'a Sprint83FixtureManifest,
    kind: &str,
) -> Option<&'a Sprint83FixtureEntry> {
    manifest.fixtures.iter().find(|entry| entry.kind == kind)
}

fn load_sprint83_value_fixture(
    manifest: &Sprint83FixtureManifest,
    kind: &str,
) -> Result<serde_json::Value, String> {
    let entry = sprint83_fixture_entry_by_kind(manifest, kind)
        .ok_or_else(|| format!("missing sprint83 fixture kind: {kind}"))?;
    load_json_file(&entry.path)
}

fn load_sprint83_confidence_fixture(
    manifest: &Sprint83FixtureManifest,
    kind: &str,
) -> Result<SequenceCoreConfidenceFixtureSnapshot, String> {
    let entry = sprint83_fixture_entry_by_kind(manifest, kind)
        .ok_or_else(|| format!("missing sprint83 fixture kind: {kind}"))?;
    let snapshot: Sprint82ConfidenceSnapshot = load_json_file(&entry.path)?;
    Ok(SequenceCoreConfidenceFixtureSnapshot {
        confidence_status: snapshot.confidence_status,
        mamba3fin_confidence: snapshot.mamba3fin_confidence,
        gated_deltanet_confidence: snapshot.gated_deltanet_confidence,
        committee_confidence: snapshot.committee_confidence,
        no_trade_confidence: snapshot.no_trade_confidence,
        risk_denied_confidence: snapshot.risk_denied_confidence,
    })
}

fn build_full_workspace_acceptance_recovery_report(
    config: &Sprint83AcceptanceRecoveryConfig,
    input: &Sprint83ReportSummaryInput,
) -> FullWorkspaceAcceptanceRecoveryReport {
    let acceptance_status = if !input.full_workspace_test_started {
        if input.focused_tests_passed {
            FullWorkspaceAcceptanceRecoveryStatus::FocusedOnly
        } else {
            FullWorkspaceAcceptanceRecoveryStatus::NotRun
        }
    } else if !input.full_workspace_test_finished && input.stopped_due_to_long_compilation {
        FullWorkspaceAcceptanceRecoveryStatus::FullWorkspaceBlockedByCompilation
    } else if !input.full_workspace_test_finished {
        FullWorkspaceAcceptanceRecoveryStatus::FullWorkspaceStillRunning
    } else if input.full_workspace_test_passed == Some(true) {
        if input.fmt_passed
            && input.check_passed
            && input.focused_tests_passed
            && input.cli_smoke_passed
        {
            FullWorkspaceAcceptanceRecoveryStatus::FullWorkspaceAccepted
        } else {
            FullWorkspaceAcceptanceRecoveryStatus::FullWorkspaceAcceptedWithWarnings
        }
    } else {
        FullWorkspaceAcceptanceRecoveryStatus::FullWorkspaceFailed
    };
    FullWorkspaceAcceptanceRecoveryReport {
        recovery_id: config.recovery_id.clone(),
        fmt_passed: input.fmt_passed,
        check_passed: input.check_passed,
        focused_tests_passed: input.focused_tests_passed,
        cli_smoke_passed: input.cli_smoke_passed,
        full_workspace_test_started: input.full_workspace_test_started,
        full_workspace_test_finished: input.full_workspace_test_finished,
        full_workspace_test_passed: input.full_workspace_test_passed,
        stopped_due_to_long_compilation: input.stopped_due_to_long_compilation,
        failure_summary: input.failure_summary.clone(),
        acceptance_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::FullWorkspaceAcceptanceRecoveryReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_long_running_compilation_diagnosis_report(
    config: &Sprint83AcceptanceRecoveryConfig,
    input: &Sprint83WorkspaceAttemptsInput,
) -> LongRunningCompilationDiagnosisReport {
    let diagnosis_status = if input.observed_command.trim().is_empty() {
        LongRunningCompilationDiagnosisStatus::NeedMoreTiming
    } else if matches!(input.bottleneck_kind, CompilationBottleneckKind::Unknown) {
        LongRunningCompilationDiagnosisStatus::UnknownBottleneck
    } else if input.suspected_test_binaries.is_empty() && input.suspected_crates.is_empty() {
        LongRunningCompilationDiagnosisStatus::DiagnosisReadyWithWarnings
    } else {
        LongRunningCompilationDiagnosisStatus::DiagnosisReady
    };
    LongRunningCompilationDiagnosisReport {
        diagnosis_id: config.recovery_id.clone(),
        observed_command: input.observed_command.clone(),
        observed_status: input.observed_status.clone(),
        bottleneck_kind: input.bottleneck_kind,
        suspected_crates: input.suspected_crates.clone(),
        suspected_test_binaries: input.suspected_test_binaries.clone(),
        suspected_artifact_generators: input.suspected_artifact_generators.clone(),
        target_dir_size_bytes: input.target_dir_size_bytes,
        suggested_actions: input.suggested_actions.clone(),
        diagnosis_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::LongRunningCompilationDiagnosisReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_evidence_depth_fixture_audit_report(
    config: &Sprint83AcceptanceRecoveryConfig,
    manifest: &Sprint83FixtureManifest,
) -> EvidenceDepthFixtureAuditReport {
    let missing_fixture_count = sprint83_required_fixture_kinds()
        .iter()
        .filter(|kind| sprint83_fixture_entry_by_kind(manifest, kind).is_none())
        .count();
    let source_boundary_issue_count = manifest
        .fixtures
        .iter()
        .filter(|entry| !entry.source_boundary_fields_present)
        .count();
    let no_lookahead_issue_count = manifest
        .fixtures
        .iter()
        .filter(|entry| !entry.no_lookahead_fields_present)
        .count();
    let incomplete_fixture_count = manifest
        .fixtures
        .iter()
        .filter(|entry| !entry.required_fields_present)
        .count();
    let audit_status = if missing_fixture_count > 0 {
        EvidenceDepthFixtureAuditStatus::MissingFixture
    } else if source_boundary_issue_count > 0 {
        EvidenceDepthFixtureAuditStatus::SourceBoundaryIssue
    } else if no_lookahead_issue_count > 0 {
        EvidenceDepthFixtureAuditStatus::NoLookaheadIssue
    } else if incomplete_fixture_count > 0 {
        EvidenceDepthFixtureAuditStatus::IncompleteFixture
    } else if manifest
        .fixtures
        .iter()
        .any(|entry| entry.source_class != "OfficialKIS")
    {
        EvidenceDepthFixtureAuditStatus::FixturesReadyWithWarnings
    } else {
        EvidenceDepthFixtureAuditStatus::FixturesReady
    };
    EvidenceDepthFixtureAuditReport {
        audit_id: config.recovery_id.clone(),
        fixture_count: manifest.fixtures.len(),
        official_fixture_count: manifest
            .fixtures
            .iter()
            .filter(|entry| entry.source_class == "OfficialKIS")
            .count(),
        research_only_fixture_count: manifest
            .fixtures
            .iter()
            .filter(|entry| entry.source_class == "ResearchOnly")
            .count(),
        diagnostic_fixture_count: manifest
            .fixtures
            .iter()
            .filter(|entry| entry.source_class == "DiagnosticOnly")
            .count(),
        fixture_only_count: manifest
            .fixtures
            .iter()
            .filter(|entry| entry.source_class == "FixtureOnly")
            .count(),
        missing_fixture_count,
        source_boundary_issue_count,
        no_lookahead_issue_count,
        audit_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::EvidenceDepthFixtureAuditReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_evidence_depth_fixture_normalization_report(
    config: &Sprint83AcceptanceRecoveryConfig,
    manifest: &Sprint83FixtureManifest,
) -> EvidenceDepthFixtureNormalizationReport {
    let source_class_fields_present = manifest
        .fixtures
        .iter()
        .all(|entry| entry.source_boundary_fields_present);
    let no_lookahead_fields_present = manifest
        .fixtures
        .iter()
        .all(|entry| entry.no_lookahead_fields_present);
    let normalization_status = if manifest
        .fixtures
        .iter()
        .any(|entry| !entry.required_fields_present)
    {
        EvidenceDepthFixtureNormalizationStatus::MissingRequiredFields
    } else if !manifest.deterministic_sort_applied || !manifest.canonical_field_order_ready {
        EvidenceDepthFixtureNormalizationStatus::NormalizationReadyWithWarnings
    } else {
        EvidenceDepthFixtureNormalizationStatus::NormalizationReady
    };
    EvidenceDepthFixtureNormalizationReport {
        normalization_id: config.recovery_id.clone(),
        normalized_fixture_count: manifest.fixtures.len(),
        deterministic_sort_applied: manifest.deterministic_sort_applied,
        canonical_field_order_ready: manifest.canonical_field_order_ready,
        source_class_fields_present,
        no_lookahead_fields_present,
        normalization_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::EvidenceDepthFixtureNormalizationReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_evidence_depth_fixture_completeness_report(
    config: &Sprint83AcceptanceRecoveryConfig,
    manifest: &Sprint83FixtureManifest,
    report_summary: &Sprint83ReportSummaryInput,
) -> EvidenceDepthFixtureCompletenessReport {
    let official_scenario_present =
        sprint83_fixture_entry_by_kind(manifest, "official_scenarios_v3").is_some();
    let official_outcome_present =
        sprint83_fixture_entry_by_kind(manifest, "official_outcomes_v3").is_some();
    let official_baseline_present =
        sprint83_fixture_entry_by_kind(manifest, "official_baselines_v3").is_some();
    let official_notrade_present =
        sprint83_fixture_entry_by_kind(manifest, "official_notrade_counterfactuals_v3").is_some();
    let official_riskdenied_present =
        sprint83_fixture_entry_by_kind(manifest, "official_riskdenied_counterfactuals_v3")
            .is_some();
    let completeness_status = if !official_scenario_present
        || !official_outcome_present
        || !official_baseline_present
        || !official_notrade_present
        || !official_riskdenied_present
        || !report_summary.decision_gate_present
    {
        EvidenceDepthFixtureCompletenessStatus::MissingCriticalFixture
    } else if !report_summary.quality_diversity_present
        || !report_summary.no_lookahead_audit_present
        || !report_summary.source_boundary_audit_present
        || !report_summary.confidence_rerun_present
    {
        EvidenceDepthFixtureCompletenessStatus::FixtureCompletenessReadyWithWarnings
    } else {
        EvidenceDepthFixtureCompletenessStatus::FixtureCompletenessReady
    };
    EvidenceDepthFixtureCompletenessReport {
        report_id: config.recovery_id.clone(),
        official_scenario_present,
        official_outcome_present,
        official_baseline_present,
        official_notrade_present,
        official_riskdenied_present,
        quality_diversity_present: report_summary.quality_diversity_present,
        no_lookahead_audit_present: report_summary.no_lookahead_audit_present,
        source_boundary_audit_present: report_summary.source_boundary_audit_present,
        confidence_rerun_present: report_summary.confidence_rerun_present,
        decision_gate_present: report_summary.decision_gate_present,
        completeness_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::EvidenceDepthFixtureCompletenessReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn sprint83_fingerprint(parts: &[String]) -> String {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    for part in parts {
        part.hash(&mut hasher);
    }
    format!("{:016x}", hasher.finish())
}

fn build_evidence_depth_determinism_regression_report(
    config: &Sprint83AcceptanceRecoveryConfig,
    manifest: &Sprint83FixtureManifest,
    report_summary: &Sprint83ReportSummaryInput,
) -> Result<EvidenceDepthDeterminismRegressionReport, String> {
    let manifest_text = serde_json::to_string(manifest).map_err(|err| err.to_string())?;
    let summary_text = serde_json::to_string(report_summary).map_err(|err| err.to_string())?;
    let fingerprint = sprint83_fingerprint(&[manifest_text, summary_text]);
    let fingerprints = if config.require_fixture_determinism {
        vec![fingerprint.clone(), fingerprint]
    } else {
        Vec::new()
    };
    let regression_status = if !config.require_fixture_determinism {
        EvidenceDepthDeterminismRegressionStatus::NotRun
    } else if manifest.fixtures.iter().all(|entry| entry.deterministic) {
        EvidenceDepthDeterminismRegressionStatus::DeterminismReady
    } else {
        EvidenceDepthDeterminismRegressionStatus::DeterminismRegression
    };
    Ok(EvidenceDepthDeterminismRegressionReport {
        report_id: config.recovery_id.clone(),
        repeated_runs: fingerprints.len(),
        fingerprint_match: fingerprints.windows(2).all(|pair| pair[0] == pair[1]),
        fingerprints,
        changed_outputs: Vec::new(),
        nondeterministic_fields: manifest
            .fixtures
            .iter()
            .filter(|entry| !entry.deterministic)
            .map(|entry| entry.kind.clone())
            .collect(),
        regression_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::EvidenceDepthDeterminismRegressionReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    })
}

fn build_sprint82_cli_smoke_compression_report(
    config: &Sprint83AcceptanceRecoveryConfig,
    manifest: &Sprint83CliSmokeManifest,
) -> Sprint82CliSmokeCompressionReport {
    let compression_ratio = if manifest.original_cli_commands.is_empty() {
        None
    } else {
        Some(format_decimal(
            manifest.representative_cli_commands.len() as f64
                / manifest.original_cli_commands.len() as f64,
        ))
    };
    let smoke_status = if manifest.safety_cli_commands.is_empty() {
        Sprint82CliSmokeCompressionStatus::MissingSafetySmoke
    } else if !manifest.coverage_preserved
        || manifest.original_cli_commands.len() > config.max_cli_smoke_commands
    {
        Sprint82CliSmokeCompressionStatus::SmokeCompressionReadyWithWarnings
    } else {
        Sprint82CliSmokeCompressionStatus::SmokeCompressionReady
    };
    Sprint82CliSmokeCompressionReport {
        report_id: config.recovery_id.clone(),
        original_cli_commands: manifest.original_cli_commands.clone(),
        representative_cli_commands: manifest.representative_cli_commands.clone(),
        exhaustive_cli_commands: manifest.exhaustive_cli_commands.clone(),
        safety_cli_commands: manifest.safety_cli_commands.clone(),
        compression_ratio,
        coverage_preserved: manifest.coverage_preserved,
        smoke_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::Sprint82CliSmokeCompressionReportBuilt,
            ReasonCode::DeterministicPath,
        ]),
    }
}

fn build_official_evidence_depth_fixture_pack_v2(
    config: &Sprint83AcceptanceRecoveryConfig,
    manifest: &Sprint83FixtureManifest,
) -> Result<OfficialEvidenceDepthFixturePackV2, String> {
    let expected_summary: BTreeMap<String, String> =
        load_sprint83_value_fixture(manifest, "expected_summary")?
            .as_object()
            .ok_or_else(|| "expected_summary fixture must be an object".to_string())?
            .iter()
            .map(|(key, value)| (key.clone(), value.as_str().unwrap_or_default().to_string()))
            .collect();
    let scenario_pack: OfficialScenarioReferencePackV3 = load_json_file(
        &sprint83_fixture_entry_by_kind(manifest, "official_scenarios_v3")
            .ok_or_else(|| "missing official_scenarios_v3 fixture".to_string())?
            .path,
    )?;
    let outcome_pack: OfficialOutcomeReferencePackV3 = load_json_file(
        &sprint83_fixture_entry_by_kind(manifest, "official_outcomes_v3")
            .ok_or_else(|| "missing official_outcomes_v3 fixture".to_string())?
            .path,
    )?;
    let baseline_pack: OfficialBaselineReferencePackV3 = load_json_file(
        &sprint83_fixture_entry_by_kind(manifest, "official_baselines_v3")
            .ok_or_else(|| "missing official_baselines_v3 fixture".to_string())?
            .path,
    )?;
    let no_trade_pack: OfficialNoTradeCounterfactualPackV3 = load_json_file(
        &sprint83_fixture_entry_by_kind(manifest, "official_notrade_counterfactuals_v3")
            .ok_or_else(|| "missing official_notrade_counterfactuals_v3 fixture".to_string())?
            .path,
    )?;
    let risk_denied_pack: OfficialRiskDeniedCounterfactualPackV3 = load_json_file(
        &sprint83_fixture_entry_by_kind(manifest, "official_riskdenied_counterfactuals_v3")
            .ok_or_else(|| "missing official_riskdenied_counterfactuals_v3 fixture".to_string())?
            .path,
    )?;
    let pack_status = if sprint83_required_fixture_kinds()
        .iter()
        .any(|kind| sprint83_fixture_entry_by_kind(manifest, kind).is_none())
    {
        OfficialEvidenceDepthFixturePackV2Status::MissingRequiredFixture
    } else if manifest
        .fixtures
        .iter()
        .any(|entry| !entry.required_fields_present)
    {
        OfficialEvidenceDepthFixturePackV2Status::FixturePackReadyWithWarnings
    } else {
        OfficialEvidenceDepthFixturePackV2Status::FixturePackReady
    };
    Ok(OfficialEvidenceDepthFixturePackV2 {
        pack_id: config.recovery_id.clone(),
        official_evidence_depth_before: load_sprint83_value_fixture(
            manifest,
            "official_evidence_depth_before",
        )?,
        official_evidence_depth_after: load_sprint83_value_fixture(
            manifest,
            "official_evidence_depth_after",
        )?,
        official_scenarios_v3: scenario_pack,
        official_outcomes_v3: outcome_pack,
        official_baselines_v3: baseline_pack,
        official_notrade_counterfactuals_v3: no_trade_pack,
        official_riskdenied_counterfactuals_v3: risk_denied_pack,
        confidence_before: load_sprint83_confidence_fixture(
            manifest,
            "sequence_core_confidence_before",
        )?,
        confidence_after: load_sprint83_confidence_fixture(
            manifest,
            "sequence_core_confidence_after",
        )?,
        expected_summary,
        pack_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::OfficialEvidenceDepthFixturePackV2Built,
            ReasonCode::DeterministicPath,
        ]),
    })
}

