impl WorkspaceWideTestSurfaceAuditConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.audit_id.trim().is_empty() {
            return Err("workspace-wide test surface audit config requires audit_id".to_string());
        }
        for path in self
            .sprint84_bundle_paths
            .iter()
            .chain(self.test_inventory_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.target_test_binary_names.iter())
        {
            if path.contains("://") {
                return Err(format!(
                    "workspace-wide test surface audit paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.audit_id)
    }

    fn target_binaries(&self) -> Vec<String> {
        if self.target_test_binary_names.is_empty() {
            default_sprint85_target_test_binaries()
        } else {
            self.target_test_binary_names.clone()
        }
    }
}

fn sprint85_file_name(path: &str) -> &str {
    Path::new(path)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(path)
}

fn sprint85_classify_name(name: &str) -> RemainingTestBinaryFamily {
    let lowercase = name.to_ascii_lowercase();
    if lowercase.contains("cli_safety") {
        RemainingTestBinaryFamily::CliSafety
    } else if lowercase.contains("determinism") || lowercase.contains("fingerprint") {
        RemainingTestBinaryFamily::Determinism
    } else if lowercase.contains("live_safety")
        || lowercase.contains("dashboard_serve")
        || lowercase.contains("control_tower_ui")
        || lowercase.contains("ui_framework")
        || lowercase.contains("runtime_state")
        || lowercase.contains("safety")
    {
        RemainingTestBinaryFamily::SafetyGuard
    } else if lowercase.contains("complete_row")
        || lowercase.contains("outcome")
        || lowercase.contains("closure")
    {
        RemainingTestBinaryFamily::CompleteRowClosure
    } else if lowercase.contains("artifact")
        || lowercase.contains("render")
        || lowercase.contains("cache")
        || lowercase.contains("golden")
    {
        RemainingTestBinaryFamily::ArtifactRendering
    } else if lowercase.contains("persona")
        || lowercase.contains("committee")
        || lowercase.contains("operational")
    {
        RemainingTestBinaryFamily::PersonaOperational
    } else {
        RemainingTestBinaryFamily::Unknown
    }
}

fn load_sprint85_inputs(
    config: &WorkspaceWideTestSurfaceAuditConfig,
) -> Result<Sprint85Inputs, String> {
    let mut sprint84_summary = None;
    let mut domain_plan_expected = None;
    let mut acceptance_attempt_expected = None;
    let mut full_gate_recovery_expected = None;
    for path in &config.sprint84_bundle_paths {
        let name = sprint85_file_name(path);
        if name == "sprint84_summary.json" {
            sprint84_summary = Some(load_json_file(path)?);
        } else if name == "domain_suite_plan_expected.json" {
            domain_plan_expected = Some(load_json_file(path)?);
        } else if name == "workspace_acceptance_attempt_expected.json" {
            acceptance_attempt_expected = Some(load_json_file(path)?);
        } else if name == "full_gate_recovery_expected.json" {
            full_gate_recovery_expected = Some(load_json_file(path)?);
        }
    }
    let mut inventory_before = None;
    let mut inventory_after = None;
    for path in &config.test_inventory_paths {
        let name = sprint85_file_name(path);
        if name == "remaining_test_binary_inventory_before.json" {
            inventory_before = Some(load_json_file(path)?);
        } else if name == "remaining_test_binary_inventory_after.json" {
            inventory_after = Some(load_json_file(path)?);
        }
    }
    Ok(Sprint85Inputs {
        sprint84_summary: sprint84_summary
            .ok_or_else(|| "missing sprint84_summary.json".to_string())?,
        inventory_before: inventory_before
            .ok_or_else(|| "missing remaining_test_binary_inventory_before.json".to_string())?,
        inventory_after: inventory_after
            .ok_or_else(|| "missing remaining_test_binary_inventory_after.json".to_string())?,
        domain_plan_expected: domain_plan_expected
            .ok_or_else(|| "missing domain_suite_plan_expected.json".to_string())?,
        acceptance_attempt_expected: acceptance_attempt_expected
            .ok_or_else(|| "missing workspace_acceptance_attempt_expected.json".to_string())?,
        full_gate_recovery_expected: full_gate_recovery_expected
            .ok_or_else(|| "missing full_gate_recovery_expected.json".to_string())?,
    })
}

fn family_key(family: RemainingTestBinaryFamily) -> String {
    format!("{family:?}")
}

fn build_remaining_test_binary_family_classifier(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    inventory_before: &RemainingTestBinaryInventory,
) -> RemainingTestBinaryFamilyClassifier {
    let mut classified_records = Vec::new();
    let mut unknown_records = Vec::new();
    for record in &inventory_before.records {
        let classified = RemainingTestBinaryRecord {
            family: sprint85_classify_name(&record.binary_name),
            ..record.clone()
        };
        if classified.family == RemainingTestBinaryFamily::Unknown {
            unknown_records.push(classified.clone());
        }
        classified_records.push(classified);
    }
    let classifier_status = if unknown_records.len() > 2 {
        RemainingTestBinaryFamilyClassifierStatus::TooManyUnknowns
    } else if unknown_records.is_empty() {
        RemainingTestBinaryFamilyClassifierStatus::ClassifierReady
    } else {
        RemainingTestBinaryFamilyClassifierStatus::ClassifierReadyWithWarnings
    };
    RemainingTestBinaryFamilyClassifier {
        classifier_id: config.audit_id.clone(),
        rules: vec![
            "complete_row / outcome / closure -> CompleteRowClosure".to_string(),
            "artifact / render / cache / golden -> ArtifactRendering".to_string(),
            "persona / committee / operational -> PersonaOperational".to_string(),
            "cli_safety / remote path -> CliSafety".to_string(),
            "determinism / fingerprint -> Determinism".to_string(),
            "guard / forbidden / absence / safety -> SafetyGuard".to_string(),
        ],
        classified_records,
        unknown_records,
        classifier_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_remaining_test_binary_inventory(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    classifier: &RemainingTestBinaryFamilyClassifier,
) -> RemainingTestBinaryInventory {
    let target_binaries = config.target_binaries();
    let filtered_records = classifier
        .classified_records
        .iter()
        .filter(|record| target_binaries.contains(&record.binary_name))
        .cloned()
        .collect::<Vec<_>>();
    let mut family_distribution = BTreeMap::new();
    for record in &filtered_records {
        *family_distribution
            .entry(family_key(record.family))
            .or_insert(0) += 1;
    }
    let high_volume_count = filtered_records
        .iter()
        .filter(|record| record.consolidation_candidate)
        .count();
    RemainingTestBinaryInventory {
        inventory_id: config.audit_id.clone(),
        records: filtered_records.clone(),
        total_remaining_count: filtered_records.len(),
        high_volume_count,
        family_distribution,
        inventory_status: if classifier.unknown_records.is_empty() {
            RemainingTestBinaryInventoryStatus::RemainingInventoryReady
        } else {
            RemainingTestBinaryInventoryStatus::RemainingInventoryReadyWithWarnings
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_workspace_wide_test_surface_audit_report(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    inventory: &RemainingTestBinaryInventory,
) -> WorkspaceWideTestSurfaceAuditReport {
    let high_volume_test_binaries = inventory
        .records
        .iter()
        .filter(|record| record.consolidation_candidate)
        .map(|record| record.binary_name.clone())
        .collect::<Vec<_>>();
    let named_bottleneck_binaries = inventory
        .records
        .iter()
        .filter(|record| {
            matches!(
                sprint85_file_name(&record.binary_name),
                "complete_row_closure_v2.rs"
                    | "artifact_render_cache_plan.rs"
                    | "persona_operational_status.rs"
            )
        })
        .map(|record| record.binary_name.clone())
        .collect::<Vec<_>>();
    let keep_separate_candidates = inventory
        .records
        .iter()
        .filter_map(|record| {
            record
                .keep_separate_reason
                .as_ref()
                .map(|_| record.binary_name.clone())
        })
        .collect::<Vec<_>>();
    WorkspaceWideTestSurfaceAuditReport {
        audit_id: config.audit_id.clone(),
        total_test_binaries_before: Some(inventory.total_remaining_count),
        high_volume_test_binaries,
        named_bottleneck_binaries,
        family_counts: inventory.family_distribution.clone(),
        consolidation_candidates: inventory
            .records
            .iter()
            .filter(|record| record.consolidation_candidate)
            .map(|record| record.binary_name.clone())
            .collect(),
        keep_separate_candidates,
        audit_status: if config.cargo_metadata_paths.is_empty() {
            WorkspaceWideTestSurfaceAuditStatus::TestSurfaceAuditReadyWithWarnings
        } else {
            WorkspaceWideTestSurfaceAuditStatus::TestSurfaceAuditReady
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_domain_grouped_test_suite_plan(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    inventory: &RemainingTestBinaryInventory,
) -> DomainGroupedTestSuitePlan {
    let mut grouped_suites = BTreeMap::new();
    for suite in [
        SPRINT85_DOMAIN_SUITE_COMPLETE_ROW,
        SPRINT85_DOMAIN_SUITE_ARTIFACT,
        SPRINT85_DOMAIN_SUITE_PERSONA,
        SPRINT85_DOMAIN_SUITE_SAFETY,
        SPRINT85_DOMAIN_SUITE_CLI,
        SPRINT85_DOMAIN_SUITE_DETERMINISM,
    ] {
        grouped_suites.insert(suite.to_string(), Vec::new());
    }
    let mut tests_to_move = Vec::new();
    let mut assertions_to_preserve = 0usize;
    let mut safety_guards_to_preserve = 0usize;
    let mut keep_separate = 0usize;
    for record in &inventory.records {
        if record.keep_separate_reason.is_some() {
            keep_separate += 1;
            continue;
        }
        let suite = match record.family {
            RemainingTestBinaryFamily::CompleteRowClosure => SPRINT85_DOMAIN_SUITE_COMPLETE_ROW,
            RemainingTestBinaryFamily::ArtifactRendering => SPRINT85_DOMAIN_SUITE_ARTIFACT,
            RemainingTestBinaryFamily::PersonaOperational => SPRINT85_DOMAIN_SUITE_PERSONA,
            RemainingTestBinaryFamily::SafetyGuard => SPRINT85_DOMAIN_SUITE_SAFETY,
            RemainingTestBinaryFamily::CliSafety => SPRINT85_DOMAIN_SUITE_CLI,
            RemainingTestBinaryFamily::Determinism => SPRINT85_DOMAIN_SUITE_DETERMINISM,
            _ => continue,
        };
        grouped_suites
            .get_mut(suite)
            .expect("suite exists")
            .push(record.binary_name.clone());
        tests_to_move.push(record.binary_name.clone());
        assertions_to_preserve += 1;
        if matches!(
            record.family,
            RemainingTestBinaryFamily::SafetyGuard | RemainingTestBinaryFamily::CliSafety
        ) {
            safety_guards_to_preserve += 1;
        }
    }
    grouped_suites.retain(|_, tests| !tests.is_empty());
    let binaries_before = inventory.total_remaining_count as isize;
    let binaries_after = grouped_suites.len() as isize + keep_separate as isize;
    let expected_binary_delta = binaries_before - binaries_after;
    let plan_status = if expected_binary_delta > 0 {
        DomainGroupedTestSuitePlanStatus::DomainSuitePlanReady
    } else {
        DomainGroupedTestSuitePlanStatus::NeedManualReview
    };
    DomainGroupedTestSuitePlan {
        plan_id: config.audit_id.clone(),
        grouped_suites,
        tests_to_move,
        assertions_to_preserve,
        safety_guards_to_preserve,
        expected_binary_delta,
        semantic_risk: if keep_separate > 0 {
            TestBinaryConsolidationSemanticRisk::Medium
        } else {
            TestBinaryConsolidationSemanticRisk::Low
        },
        plan_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_domain_grouped_test_suite_report(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    plan: &DomainGroupedTestSuitePlan,
    inventory_before: &RemainingTestBinaryInventory,
    inventory_after: &RemainingTestBinaryInventory,
) -> DomainGroupedTestSuiteReport {
    let report_status =
        if inventory_after.total_remaining_count < inventory_before.total_remaining_count {
            if plan.semantic_risk == TestBinaryConsolidationSemanticRisk::Low {
                DomainGroupedTestSuiteReportStatus::DomainSuitesReady
            } else {
                DomainGroupedTestSuiteReportStatus::DomainSuitesReadyWithWarnings
            }
        } else {
            DomainGroupedTestSuiteReportStatus::NoReduction
        };
    DomainGroupedTestSuiteReport {
        report_id: config.audit_id.clone(),
        suites_created: plan.grouped_suites.keys().cloned().collect(),
        tests_grouped: plan.tests_to_move.len(),
        assertions_preserved: plan.assertions_to_preserve,
        safety_assertions_preserved: plan.safety_guards_to_preserve,
        binaries_before: Some(inventory_before.total_remaining_count),
        binaries_after: Some(inventory_after.total_remaining_count),
        report_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

