fn build_shared_fixture_harness_adoption_report(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    plan: &DomainGroupedTestSuitePlan,
    inventory: &RemainingTestBinaryInventory,
) -> SharedFixtureHarnessAdoptionReport {
    let helpers_used = vec![
        "load_json_fixture".to_string(),
        "load_toml_fixture".to_string(),
        "load_csv_fixture".to_string(),
        "temp_output_dir_for_test".to_string(),
        "assert_deterministic_text".to_string(),
        "assert_no_secret_like_values".to_string(),
        "assert_no_order_account_fields".to_string(),
        "assert_no_runtime_fields".to_string(),
        "assert_source_boundary_preserved".to_string(),
        "assert_no_lookahead_preserved".to_string(),
    ];
    let remaining_duplicate_setup = inventory
        .records
        .iter()
        .filter_map(|record| {
            record
                .keep_separate_reason
                .as_ref()
                .map(|_| record.binary_name.clone())
        })
        .collect::<Vec<_>>();
    SharedFixtureHarnessAdoptionReport {
        adoption_id: config.audit_id.clone(),
        target_families: vec![
            RemainingTestBinaryFamily::CompleteRowClosure,
            RemainingTestBinaryFamily::ArtifactRendering,
            RemainingTestBinaryFamily::PersonaOperational,
            RemainingTestBinaryFamily::SafetyGuard,
            RemainingTestBinaryFamily::CliSafety,
            RemainingTestBinaryFamily::Determinism,
        ],
        migrated_tests: plan.tests_to_move.clone(),
        helpers_used,
        duplicate_setup_removed: plan.expected_binary_delta.max(0) as usize,
        remaining_duplicate_setup,
        adoption_status: if plan.expected_binary_delta > 0 {
            SharedFixtureHarnessAdoptionStatus::HarnessAdoptionReadyWithWarnings
        } else {
            SharedFixtureHarnessAdoptionStatus::NeedMoreMigration
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

