fn build_workspace_wide_acceptance_attempt_v3(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    expected: &serde_json::Value,
    audit: &WorkspaceWideTestSurfaceAuditReport,
) -> WorkspaceWideAcceptanceAttemptV3 {
    let fmt_passed = expected["fmt_passed"].as_bool().unwrap_or(false);
    let check_passed = expected["check_passed"].as_bool().unwrap_or(false);
    let domain_suites_passed = expected["domain_suites_passed"].as_bool().unwrap_or(false);
    let safety_guard_suite_passed = expected["safety_guard_suite_passed"]
        .as_bool()
        .unwrap_or(false);
    let cli_safety_suite_passed = expected["cli_safety_suite_passed"]
        .as_bool()
        .unwrap_or(false);
    let determinism_suite_passed = expected["determinism_suite_passed"]
        .as_bool()
        .unwrap_or(false);
    let representative_smoke_passed = expected["representative_smoke_passed"]
        .as_bool()
        .unwrap_or(false);
    let safety_smoke_passed = expected["safety_smoke_passed"].as_bool().unwrap_or(false);
    let full_workspace_started = expected["full_workspace_started"]
        .as_bool()
        .unwrap_or(false);
    let full_workspace_finished = expected["full_workspace_finished"]
        .as_bool()
        .unwrap_or(false);
    let full_workspace_passed = expected
        .get("full_workspace_passed")
        .and_then(serde_json::Value::as_bool);
    let full_workspace_duration_ms = expected
        .get("full_workspace_duration_ms")
        .and_then(serde_json::Value::as_u64);
    let full_workspace_blockers = audit.named_bottleneck_binaries.clone();
    let attempt_status = if full_workspace_finished && full_workspace_passed == Some(true) {
        WorkspaceWideAcceptanceAttemptV3Status::FullWorkspaceAccepted
    } else if full_workspace_finished && full_workspace_passed == Some(false) {
        WorkspaceWideAcceptanceAttemptV3Status::FullWorkspaceFailed
    } else if domain_suites_passed
        && safety_guard_suite_passed
        && cli_safety_suite_passed
        && determinism_suite_passed
    {
        WorkspaceWideAcceptanceAttemptV3Status::FullWorkspaceStillBlocked
    } else if domain_suites_passed {
        WorkspaceWideAcceptanceAttemptV3Status::FocusedOnly
    } else {
        WorkspaceWideAcceptanceAttemptV3Status::NotRun
    };
    WorkspaceWideAcceptanceAttemptV3 {
        attempt_id: config.audit_id.clone(),
        fmt_passed,
        check_passed,
        domain_suites_passed,
        safety_guard_suite_passed,
        cli_safety_suite_passed,
        determinism_suite_passed,
        representative_smoke_passed,
        safety_smoke_passed,
        full_workspace_started,
        full_workspace_finished,
        full_workspace_passed,
        full_workspace_duration_ms,
        full_workspace_blockers,
        attempt_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_full_workspace_gate_recovery_report_v3(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    previous: &Sprint85SummaryInput,
    plan: &DomainGroupedTestSuitePlan,
    adoption: &SharedFixtureHarnessAdoptionReport,
    smoke: &WorkspaceWideSmokePolicyV2,
    attempt: &WorkspaceWideAcceptanceAttemptV3,
) -> FullWorkspaceGateRecoveryReportV3 {
    let current_gate_status = format!("{:?}", attempt.attempt_status);
    let recovery_status = match attempt.attempt_status {
        WorkspaceWideAcceptanceAttemptV3Status::FullWorkspaceAccepted
        | WorkspaceWideAcceptanceAttemptV3Status::FullWorkspaceAcceptedWithWarnings => {
            FullWorkspaceGateRecoveryReportV3Status::GateRecovered
        }
        WorkspaceWideAcceptanceAttemptV3Status::FullWorkspaceFailed => {
            FullWorkspaceGateRecoveryReportV3Status::GateFailed
        }
        WorkspaceWideAcceptanceAttemptV3Status::FullWorkspaceStillBlocked
            if plan.expected_binary_delta > 0 =>
        {
            FullWorkspaceGateRecoveryReportV3Status::GateImprovedButBlocked
        }
        _ => FullWorkspaceGateRecoveryReportV3Status::GateStillBlocked,
    };
    FullWorkspaceGateRecoveryReportV3 {
        report_id: config.audit_id.clone(),
        previous_gate_status: previous.previous_gate_status.clone(),
        current_gate_status,
        binary_count_delta: Some(plan.expected_binary_delta),
        grouped_suite_status: format!("{:?}", plan.plan_status),
        harness_adoption_status: format!("{:?}", adoption.adoption_status),
        smoke_policy_status: format!("{:?}", smoke.policy_status),
        safety_coverage_status: if attempt.safety_guard_suite_passed && attempt.safety_smoke_passed
        {
            "safety coverage preserved".to_string()
        } else {
            "safety coverage incomplete".to_string()
        },
        remaining_blockers: attempt.full_workspace_blockers.clone(),
        recovery_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_remaining_workspace_blocker_drilldown_report(
    config: &WorkspaceWideTestSurfaceAuditConfig,
    audit: &WorkspaceWideTestSurfaceAuditReport,
    classifier: &RemainingTestBinaryFamilyClassifier,
) -> RemainingWorkspaceBlockerDrilldownReport {
    let blocker_family = audit
        .named_bottleneck_binaries
        .first()
        .map(|name| format!("{:?}", sprint85_classify_name(name)))
        .unwrap_or_else(|| "Unknown".to_string());
    let suspected_files = classifier
        .classified_records
        .iter()
        .filter(|record| {
            audit
                .named_bottleneck_binaries
                .contains(&record.binary_name)
        })
        .filter_map(|record| {
            record
                .test_file
                .clone()
                .or(Some(record.binary_name.clone()))
        })
        .collect::<Vec<_>>();
    let report_status = if audit.named_bottleneck_binaries.is_empty() {
        RemainingWorkspaceBlockerDrilldownReportStatus::NoBlockers
    } else {
        RemainingWorkspaceBlockerDrilldownReportStatus::BlockersExplained
    };
    RemainingWorkspaceBlockerDrilldownReport {
        report_id: config.audit_id.clone(),
        remaining_blockers: audit.named_bottleneck_binaries.clone(),
        blocker_family,
        suspected_files,
        suggested_next_actions: vec![
            "collapse remaining high-volume families conservatively".to_string(),
            "keep full workspace gate as final acceptance".to_string(),
        ],
        report_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

