const SPRINT86_SUITE_LEGACY: &str = "tests/workspace_legacy_regression_suite.rs";

fn default_sprint86_output_root() -> String {
    "target/soma_sprint86_residual_gate_recovery".to_string()
}

fn default_sprint86_observed_binary_names() -> Vec<String> {
    [
        "official_expansion_status_mapping",
        "committee_scenario_materializer_v2",
        "committee_replay",
        "control_tower_briefing_panel",
        "external_prediction_import_v2",
        "experiment_determinism",
        "model_ops_operator_qa",
    ]
    .into_iter()
    .map(str::to_string)
    .collect()
}

impl ResidualWorkspaceBinaryAuditConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.audit_id.trim().is_empty() {
            return Err("residual workspace binary audit config requires audit_id".to_string());
        }
        for path in self
            .sprint85_bundle_paths
            .iter()
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.full_workspace_attempt_paths.iter())
            .chain(self.observed_binary_names.iter())
        {
            if path.contains("://") {
                return Err(format!(
                    "residual workspace binary audit paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.audit_id)
    }
}

fn sprint86_file_name(path: &str) -> &str {
    Path::new(path)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(path)
}

fn sprint86_classify_name(name: &str) -> ResidualIntegrationFamily {
    let lowercase = name.to_ascii_lowercase();
    if lowercase.contains("official_expansion")
        || lowercase.contains("official_status")
        || lowercase.contains("official_ready")
    {
        ResidualIntegrationFamily::OfficialExpansion
    } else if lowercase.contains("committee_scenario")
        || lowercase.contains("committee_materializer")
        || lowercase.contains("committee_replay")
    {
        ResidualIntegrationFamily::CommitteeScenarioReplay
    } else if lowercase.contains("operator_briefing_determinism")
        || lowercase.contains("experiment_determinism")
        || lowercase.contains("fingerprint")
        || lowercase.contains("determinism")
    {
        ResidualIntegrationFamily::ExperimentDeterminism
    } else if lowercase.contains("control_tower")
        || lowercase.contains("briefing")
        || lowercase.contains("static_briefing")
        || lowercase.contains("panel")
    {
        ResidualIntegrationFamily::ControlTowerBriefing
    } else if lowercase.contains("external_prediction")
        || lowercase.contains("prediction_import")
        || lowercase.contains("model_card")
        || lowercase.contains("external_model_evaluation")
        || lowercase.contains("promotion_gate")
        || lowercase.contains("previous_external")
    {
        ResidualIntegrationFamily::ExternalPrediction
    } else if lowercase.contains("model_ops")
        || lowercase.contains("operator_qa")
        || lowercase.contains("review_queue")
        || lowercase.contains("watchlist")
        || lowercase.contains("checklist")
    {
        ResidualIntegrationFamily::ModelOpsQA
    } else if lowercase.contains("cli")
        || lowercase.contains("help")
        || lowercase.contains("remote")
    {
        ResidualIntegrationFamily::CliSafety
    } else if lowercase.contains("guard")
        || lowercase.contains("safety")
        || lowercase.contains("absence")
    {
        ResidualIntegrationFamily::SafetyGuard
    } else {
        ResidualIntegrationFamily::Unknown
    }
}

fn load_sprint86_inputs(
    config: &ResidualWorkspaceBinaryAuditConfig,
) -> Result<Sprint86Inputs, String> {
    let mut sprint85_summary = None;
    for path in &config.sprint85_bundle_paths {
        if sprint86_file_name(path) == "sprint85_summary.json" {
            sprint85_summary = Some(load_json_file(path)?);
        }
    }
    let mut inventory_before = None;
    let mut inventory_after = None;
    let mut classifier_expected = None;
    for path in &config.cargo_metadata_paths {
        match sprint86_file_name(path) {
            "residual_binaries_before.json" => inventory_before = Some(load_json_file(path)?),
            "residual_binaries_after.json" => inventory_after = Some(load_json_file(path)?),
            "residual_family_classifier_expected.json" => {
                classifier_expected = Some(load_json_file(path)?)
            }
            _ => {}
        }
    }
    let mut compile_only_sample = None;
    let mut full_workspace_expected = None;
    let mut safety_expected = None;
    for path in &config.full_workspace_attempt_paths {
        match sprint86_file_name(path) {
            "compile_only_attempt_sample.json" => compile_only_sample = Some(load_json_file(path)?),
            "full_workspace_attempt_v4_expected.json" => {
                full_workspace_expected = Some(load_json_file(path)?)
            }
            "safety_coverage_expected.json" => safety_expected = Some(load_json_file(path)?),
            _ => {}
        }
    }
    Ok(Sprint86Inputs {
        sprint85_summary: sprint85_summary
            .ok_or_else(|| "missing sprint85_summary.json".to_string())?,
        inventory_before: inventory_before
            .ok_or_else(|| "missing residual_binaries_before.json".to_string())?,
        inventory_after: inventory_after
            .ok_or_else(|| "missing residual_binaries_after.json".to_string())?,
        classifier_expected: classifier_expected
            .ok_or_else(|| "missing residual_family_classifier_expected.json".to_string())?,
        compile_only_sample: compile_only_sample
            .ok_or_else(|| "missing compile_only_attempt_sample.json".to_string())?,
        full_workspace_expected: full_workspace_expected
            .ok_or_else(|| "missing full_workspace_attempt_v4_expected.json".to_string())?,
        safety_expected: safety_expected
            .ok_or_else(|| "missing safety_coverage_expected.json".to_string())?,
    })
}

fn build_residual_workspace_binary_audit_report(
    config: &ResidualWorkspaceBinaryAuditConfig,
    inventory_before: &ResidualBinaryInventory,
) -> ResidualWorkspaceBinaryAuditReport {
    let observed_binaries = config.observed_binary_names.clone();
    let residual_binaries = inventory_before
        .records
        .iter()
        .map(|record| record.binary_name.clone())
        .collect::<Vec<_>>();
    let already_grouped_binaries = residual_binaries
        .iter()
        .filter(|name| {
            name.contains("complete_row_closure_suite")
                || name.contains("artifact_rendering_suite")
                || name.contains("persona_operational_suite")
        })
        .cloned()
        .collect::<Vec<_>>();
    let newly_observed_binaries = observed_binaries
        .iter()
        .filter(|observed| {
            residual_binaries
                .iter()
                .any(|binary| binary.contains(*observed))
        })
        .cloned()
        .collect::<Vec<_>>();
    ResidualWorkspaceBinaryAuditReport {
        audit_id: config.audit_id.clone(),
        observed_binaries,
        newly_observed_binaries,
        already_grouped_binaries,
        residual_binaries: residual_binaries.clone(),
        family_counts: inventory_before.family_distribution.clone(),
        consolidation_candidates: inventory_before
            .records
            .iter()
            .filter(|record| record.consolidation_candidate)
            .map(|record| record.binary_name.clone())
            .collect(),
        keep_separate_candidates: inventory_before
            .records
            .iter()
            .filter_map(|record| {
                record
                    .keep_separate_reason
                    .as_ref()
                    .map(|_| record.binary_name.clone())
            })
            .collect(),
        audit_status: if config.cargo_metadata_paths.is_empty() {
            ResidualWorkspaceBinaryAuditStatus::NeedCargoMetadata
        } else {
            ResidualWorkspaceBinaryAuditStatus::ResidualAuditReadyWithWarnings
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_residual_integration_family_classifier(
    config: &ResidualWorkspaceBinaryAuditConfig,
    inventory_before: &ResidualBinaryInventory,
    expected: &BTreeMap<String, String>,
) -> Result<ResidualIntegrationFamilyClassifier, String> {
    let mut classified_records = Vec::new();
    let mut unknown_records = Vec::new();
    for record in &inventory_before.records {
        let classified_family = sprint86_classify_name(&record.binary_name);
        if let Some(expected_family) = expected.get(&record.binary_name) {
            if expected_family != &format!("{classified_family:?}") {
                return Err(format!(
                    "residual family classifier mismatch for {}",
                    record.binary_name
                ));
            }
        }
        let classified = ResidualBinaryRecord {
            family: classified_family,
            ..record.clone()
        };
        if classified.family == ResidualIntegrationFamily::Unknown {
            unknown_records.push(classified.clone());
        }
        classified_records.push(classified);
    }
    let classifier_status = if unknown_records.is_empty() {
        ResidualIntegrationFamilyClassifierStatus::ClassifierReady
    } else if unknown_records.len() <= 2 {
        ResidualIntegrationFamilyClassifierStatus::ClassifierReadyWithWarnings
    } else {
        ResidualIntegrationFamilyClassifierStatus::TooManyUnknowns
    };
    Ok(ResidualIntegrationFamilyClassifier {
        classifier_id: config.audit_id.clone(),
        rules: vec![
            "official_expansion / official_status / KIS status mapping -> OfficialExpansion"
                .to_string(),
            "committee_scenario / committee_materializer / committee_replay -> CommitteeScenarioReplay"
                .to_string(),
            "control_tower / briefing / panel -> ControlTowerBriefing".to_string(),
            "external_prediction / prediction_import / model_card -> ExternalPrediction"
                .to_string(),
            "experiment_determinism / deterministic / fingerprint -> ExperimentDeterminism"
                .to_string(),
            "model_ops / operator_qa / review_queue / checklist -> ModelOpsQA".to_string(),
            "guard / forbidden / absence / safety -> SafetyGuard".to_string(),
            "cli / help / remote config -> CliSafety".to_string(),
        ],
        classified_records,
        unknown_records,
        classifier_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    })
}

fn build_residual_binary_consolidation_plan(
    config: &ResidualWorkspaceBinaryAuditConfig,
    inventory_before: &ResidualBinaryInventory,
    inventory_after: &ResidualBinaryInventory,
) -> ResidualBinaryConsolidationPlan {
    let mut planned_suites = BTreeMap::new();
    for suite in [
        SPRINT86_SUITE_OFFICIAL,
        SPRINT86_SUITE_COMMITTEE,
        SPRINT86_SUITE_BRIEFING,
        SPRINT86_SUITE_EXTERNAL,
        SPRINT86_SUITE_DETERMINISM,
        SPRINT86_SUITE_MODEL_OPS,
        SPRINT86_SUITE_LEGACY,
    ] {
        planned_suites.insert(suite.to_string(), Vec::new());
    }
    let mut tests_to_move = Vec::new();
    let mut safety_guards_to_preserve = 0usize;
    for record in &inventory_before.records {
        if record.keep_separate_reason.is_some() {
            continue;
        }
        let suite = match record.family {
            ResidualIntegrationFamily::OfficialExpansion => SPRINT86_SUITE_OFFICIAL,
            ResidualIntegrationFamily::CommitteeScenarioReplay => SPRINT86_SUITE_COMMITTEE,
            ResidualIntegrationFamily::ControlTowerBriefing => SPRINT86_SUITE_BRIEFING,
            ResidualIntegrationFamily::ExternalPrediction => SPRINT86_SUITE_EXTERNAL,
            ResidualIntegrationFamily::ExperimentDeterminism => SPRINT86_SUITE_DETERMINISM,
            ResidualIntegrationFamily::ModelOpsQA => SPRINT86_SUITE_MODEL_OPS,
            _ => SPRINT86_SUITE_LEGACY,
        };
        planned_suites
            .get_mut(suite)
            .expect("suite present")
            .push(record.binary_name.clone());
        tests_to_move.push(record.binary_name.clone());
        if matches!(
            record.family,
            ResidualIntegrationFamily::CliSafety | ResidualIntegrationFamily::SafetyGuard
        ) {
            safety_guards_to_preserve += 1;
        }
    }
    planned_suites.retain(|_, tests| !tests.is_empty());
    ResidualBinaryConsolidationPlan {
        plan_id: config.audit_id.clone(),
        target_binaries: inventory_before
            .records
            .iter()
            .map(|record| record.binary_name.clone())
            .collect(),
        planned_suites,
        assertions_to_preserve: tests_to_move.len(),
        safety_guards_to_preserve,
        expected_binary_delta: inventory_before.total_remaining_count as isize
            - inventory_after.total_remaining_count as isize,
        semantic_risk: TestBinaryConsolidationSemanticRisk::Medium,
        tests_to_move,
        plan_status: ResidualBinaryConsolidationPlanStatus::ResidualConsolidationPlanReady,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_legacy_integration_migration_report(
    config: &ResidualWorkspaceBinaryAuditConfig,
    plan: &ResidualBinaryConsolidationPlan,
    inventory_before: &ResidualBinaryInventory,
) -> LegacyIntegrationMigrationReport {
    let mut keep_separate_reasons = BTreeMap::new();
    let kept_separate_files = inventory_before
        .records
        .iter()
        .filter_map(|record| {
            record.keep_separate_reason.as_ref().map(|reason| {
                keep_separate_reasons.insert(record.binary_name.clone(), reason.clone());
                record.binary_name.clone()
            })
        })
        .collect::<Vec<_>>();
    LegacyIntegrationMigrationReport {
        report_id: config.audit_id.clone(),
        migrated_files: plan.tests_to_move.clone(),
        migrated_assertions: vec![
            "official expansion status mapping preserved".to_string(),
            "committee scenario/replay assertions preserved".to_string(),
            "Control Tower briefing static/read-only assertions preserved".to_string(),
            "external prediction schema/model-card/promotion assertions preserved".to_string(),
            "experiment determinism assertions preserved".to_string(),
            "model ops QA / review queue / watchlist assertions preserved".to_string(),
        ],
        kept_separate_files,
        keep_separate_reasons,
        removed_duplicate_setup_count: plan.expected_binary_delta.max(0) as usize,
        migration_status: if plan.expected_binary_delta > 0 {
            LegacyIntegrationMigrationReportStatus::MigrationReadyWithWarnings
        } else {
            LegacyIntegrationMigrationReportStatus::NeedManualReview
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_compile_only_workspace_attempt_report(
    config: &ResidualWorkspaceBinaryAuditConfig,
    sample: &Sprint86CompileOnlyInput,
) -> CompileOnlyWorkspaceAttemptReport {
    let compile_status = if sample.started && sample.finished && sample.passed == Some(true) {
        CompileOnlyWorkspaceCompileStatus::CompileOnlyPassed
    } else if sample.started && !sample.finished {
        CompileOnlyWorkspaceCompileStatus::CompileOnlyStillBlocked
    } else if sample.finished && sample.passed == Some(false) {
        CompileOnlyWorkspaceCompileStatus::CompileOnlyFailed
    } else {
        CompileOnlyWorkspaceCompileStatus::NotRun
    };
    CompileOnlyWorkspaceAttemptReport {
        report_id: config.audit_id.clone(),
        command: "cargo test --workspace --no-run".to_string(),
        started: sample.started,
        finished: sample.finished,
        passed: sample.passed,
        duration_ms: sample.duration_ms,
        blocked_binaries: sample.blocked_binaries.clone(),
        compile_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_cargo_test_no_run_gate_report(
    config: &ResidualWorkspaceBinaryAuditConfig,
    compile_only: &CompileOnlyWorkspaceAttemptReport,
    sample: &Sprint86CompileOnlyInput,
) -> CargoTestNoRunGateReport {
    let gate_status = match compile_only.compile_status {
        CompileOnlyWorkspaceCompileStatus::CompileOnlyPassed => {
            CargoTestNoRunGateStatus::NoRunGatePassed
        }
        CompileOnlyWorkspaceCompileStatus::CompileOnlyStillBlocked => {
            CargoTestNoRunGateStatus::NoRunGateStillBlocked
        }
        CompileOnlyWorkspaceCompileStatus::CompileOnlyFailed => {
            CargoTestNoRunGateStatus::NoRunGateFailed
        }
        CompileOnlyWorkspaceCompileStatus::NotRun => CargoTestNoRunGateStatus::NotRun,
    };
    CargoTestNoRunGateReport {
        gate_id: config.audit_id.clone(),
        compile_only_status: compile_only.compile_status,
        residual_binaries: compile_only.blocked_binaries.clone(),
        suspected_crates: sample.suspected_crates.clone(),
        gate_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_full_workspace_acceptance_attempt_v4(
    config: &ResidualWorkspaceBinaryAuditConfig,
    compile_only: &CompileOnlyWorkspaceAttemptReport,
    expected: &Sprint86FullWorkspaceInput,
) -> FullWorkspaceAcceptanceAttemptV4 {
    let attempt_status = if expected.full_workspace_finished
        && expected.full_workspace_passed == Some(true)
    {
        FullWorkspaceAcceptanceAttemptV4Status::FullWorkspaceAccepted
    } else if compile_only.compile_status
        == CompileOnlyWorkspaceCompileStatus::CompileOnlyStillBlocked
        && !expected.full_workspace_started
    {
        FullWorkspaceAcceptanceAttemptV4Status::CompileOnlyBlocked
    } else if expected.full_workspace_started && !expected.full_workspace_finished {
        FullWorkspaceAcceptanceAttemptV4Status::FullWorkspaceStillBlocked
    } else if expected.full_workspace_finished && expected.full_workspace_passed == Some(false) {
        FullWorkspaceAcceptanceAttemptV4Status::FullWorkspaceFailed
    } else if expected.residual_grouped_suites_passed {
        FullWorkspaceAcceptanceAttemptV4Status::FocusedOnly
    } else {
        FullWorkspaceAcceptanceAttemptV4Status::NotRun
    };
    FullWorkspaceAcceptanceAttemptV4 {
        attempt_id: config.audit_id.clone(),
        fmt_passed: expected.fmt_passed,
        check_passed: expected.check_passed,
        domain_suites_passed: true,
        residual_grouped_suites_passed: expected.residual_grouped_suites_passed,
        workspace_safety_guard_passed: expected.workspace_safety_guard_passed,
        workspace_cli_safety_passed: expected.workspace_cli_safety_passed,
        workspace_determinism_passed: expected.workspace_determinism_passed,
        representative_smoke_passed: expected.representative_smoke_passed,
        safety_smoke_passed: expected.safety_smoke_passed,
        compile_only_started: compile_only.started,
        compile_only_finished: compile_only.finished,
        compile_only_passed: compile_only.passed,
        full_workspace_started: expected.full_workspace_started,
        full_workspace_finished: expected.full_workspace_finished,
        full_workspace_passed: expected.full_workspace_passed,
        full_workspace_duration_ms: expected.full_workspace_duration_ms,
        full_workspace_blockers: expected.full_workspace_blockers.clone(),
        attempt_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_full_workspace_gate_recovery_report_v4(
    config: &ResidualWorkspaceBinaryAuditConfig,
    summary: &Sprint86SummaryInput,
    plan: &ResidualBinaryConsolidationPlan,
    compile_only: &CompileOnlyWorkspaceAttemptReport,
    attempt: &FullWorkspaceAcceptanceAttemptV4,
    safety: &SafetyCoveragePreservationReportV2,
) -> FullWorkspaceGateRecoveryReportV4 {
    let recovery_status = match attempt.attempt_status {
        FullWorkspaceAcceptanceAttemptV4Status::FullWorkspaceAccepted
        | FullWorkspaceAcceptanceAttemptV4Status::FullWorkspaceAcceptedWithWarnings => {
            FullWorkspaceGateRecoveryReportV4Status::GateRecovered
        }
        FullWorkspaceAcceptanceAttemptV4Status::FullWorkspaceFailed => {
            FullWorkspaceGateRecoveryReportV4Status::GateFailed
        }
        FullWorkspaceAcceptanceAttemptV4Status::CompileOnlyBlocked
        | FullWorkspaceAcceptanceAttemptV4Status::FullWorkspaceStillBlocked
            if plan.expected_binary_delta > 0 =>
        {
            FullWorkspaceGateRecoveryReportV4Status::GateImprovedButBlocked
        }
        _ => FullWorkspaceGateRecoveryReportV4Status::GateStillBlocked,
    };
    FullWorkspaceGateRecoveryReportV4 {
        report_id: config.audit_id.clone(),
        previous_gate_status: summary.previous_gate_status.clone(),
        current_gate_status: format!("{:?}", attempt.attempt_status),
        binary_count_delta: Some(plan.expected_binary_delta),
        residual_suite_status: format!("{:?}", plan.plan_status),
        compile_only_status: format!("{:?}", compile_only.compile_status),
        full_workspace_status: format!("{:?}", attempt.attempt_status),
        safety_coverage_status: format!("{:?}", safety.safety_status),
        remaining_blockers: attempt.full_workspace_blockers.clone(),
        recovery_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_residual_workspace_blocker_drilldown_v2(
    config: &ResidualWorkspaceBinaryAuditConfig,
    attempt: &FullWorkspaceAcceptanceAttemptV4,
    sample: &Sprint86CompileOnlyInput,
) -> ResidualWorkspaceBlockerDrilldownV2 {
    let blocker = attempt
        .full_workspace_blockers
        .first()
        .cloned()
        .unwrap_or_else(|| sample.blocked_binaries.first().cloned().unwrap_or_default());
    let family = if blocker.is_empty() {
        "Unknown".to_string()
    } else {
        format!("{:?}", sprint86_classify_name(&blocker))
    };
    let recommended_suite_target = match sprint86_classify_name(&blocker) {
        ResidualIntegrationFamily::OfficialExpansion => Some(SPRINT86_SUITE_OFFICIAL.to_string()),
        ResidualIntegrationFamily::CommitteeScenarioReplay => {
            Some(SPRINT86_SUITE_COMMITTEE.to_string())
        }
        ResidualIntegrationFamily::ControlTowerBriefing => {
            Some(SPRINT86_SUITE_BRIEFING.to_string())
        }
        ResidualIntegrationFamily::ExternalPrediction => Some(SPRINT86_SUITE_EXTERNAL.to_string()),
        ResidualIntegrationFamily::ExperimentDeterminism => {
            Some(SPRINT86_SUITE_DETERMINISM.to_string())
        }
        ResidualIntegrationFamily::ModelOpsQA => Some(SPRINT86_SUITE_MODEL_OPS.to_string()),
        _ => Some(SPRINT86_SUITE_LEGACY.to_string()),
    };
    ResidualWorkspaceBlockerDrilldownV2 {
        report_id: config.audit_id.clone(),
        blockers: if attempt.full_workspace_blockers.is_empty() {
            sample.blocked_binaries.clone()
        } else {
            attempt.full_workspace_blockers.clone()
        },
        blocker_family: family,
        suspected_files: if blocker.is_empty() {
            Vec::new()
        } else {
            vec![blocker]
        },
        suspected_crates: sample.suspected_crates.clone(),
        suggested_next_actions: vec![
            "continue collapsing residual integration families conservatively".to_string(),
            "treat compile-only and full-workspace states separately".to_string(),
        ],
        recommended_suite_target,
        report_status: if attempt.full_workspace_blockers.is_empty()
            && sample.blocked_binaries.is_empty()
        {
            ResidualWorkspaceBlockerDrilldownV2Status::NoBlockers
        } else {
            ResidualWorkspaceBlockerDrilldownV2Status::BlockersExplained
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_workspace_binary_delta_report_v2(
    config: &ResidualWorkspaceBinaryAuditConfig,
    inventory_before: &ResidualBinaryInventory,
    inventory_after: &ResidualBinaryInventory,
    plan: &ResidualBinaryConsolidationPlan,
) -> WorkspaceBinaryDeltaReportV2 {
    let delta_status =
        if inventory_after.total_remaining_count < inventory_before.total_remaining_count {
            WorkspaceBinaryDeltaReportV2Status::BinarySurfaceReducedWithWarnings
        } else {
            WorkspaceBinaryDeltaReportV2Status::SampleBackedOnly
        };
    WorkspaceBinaryDeltaReportV2 {
        report_id: config.audit_id.clone(),
        binary_count_before: Some(inventory_before.total_remaining_count),
        binary_count_after: Some(inventory_after.total_remaining_count),
        grouped_suite_count: 7,
        moved_test_count: plan.tests_to_move.len(),
        kept_separate_count: inventory_before
            .records
            .iter()
            .filter(|record| record.keep_separate_reason.is_some())
            .count(),
        sample_backed: true,
        measured: false,
        delta_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

