    pub fn run_full_gate_recovery_v4(
        &self,
        config: &ResidualWorkspaceBinaryAuditConfig,
    ) -> Result<FullWorkspaceGateRecoveryReportV4, String> {
        Ok(self.run(config)?.full_workspace_gate_recovery_report_v4)
    }

