const SPRINT87_SUITE_FUTURE_WINDOW: &str = "tests/future_window_requirements_suite.rs";
const SPRINT87_SUITE_OFFICIAL_DIVERSITY: &str = "tests/official_diversity_suite.rs";
const SPRINT87_SUITE_TRINITY: &str = "tests/trinity_operational_loop_suite.rs";
const SPRINT87_SUITE_DATASET_EXPORT: &str = "tests/dataset_export_suite.rs";
const SPRINT87_SUITE_CONTROL_TOWER: &str = "tests/control_tower_v1_suite.rs";
const SPRINT87_SUITE_CANDLE_EXPANSION: &str = "tests/candle_expansion_ops_suite.rs";
const SPRINT87_SUITE_EXTERNAL: &str = "tests/external_prediction_family_suite.rs";
const SPRINT87_SUITE_KRX: &str = "tests/krx_evidence_suite.rs";
const SPRINT87_SUITE_DASHBOARD: &str = "tests/dashboard_renderer_suite.rs";
const SPRINT87_SUITE_BASELINE: &str = "tests/baseline_signal_suite.rs";
const SPRINT87_SUITE_COUNTERFACTUAL: &str = "tests/counterfactual_backfill_suite.rs";

fn default_sprint87_output_root() -> String {
    "target/soma_sprint87_compile_gate_recovery".to_string()
}

fn default_sprint87_observed_compile_families() -> Vec<String> {
    [
        "future_window_requirements",
        "official_diversity_report",
        "trinity_operational_loop",
        "dataset_export",
        "control_tower_v1",
        "candle_expansion_ops",
        "external_prediction",
        "krx_evidence_job_plan",
        "dashboard_renderer",
        "committee_cli_safety",
        "baseline_signal",
        "counterfactual_backfill",
    ]
    .into_iter()
    .map(str::to_string)
    .collect()
}

impl WorkspaceCompileGraphAuditConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.audit_id.trim().is_empty() {
            return Err("workspace compile graph audit config requires audit_id".to_string());
        }
        for path in self
            .sprint86_bundle_paths
            .iter()
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(self.compile_only_attempt_paths.iter())
            .chain(self.full_workspace_attempt_paths.iter())
            .chain(self.observed_compile_families.iter())
        {
            if path.contains("://") {
                return Err(format!(
                    "workspace compile graph audit paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.audit_id)
    }
}

fn sprint87_file_name(path: &str) -> &str {
    Path::new(path)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(path)
}

fn sprint87_family_enabled(
    config: &WorkspaceCompileGraphAuditConfig,
    family: CompileFamilyV2,
) -> bool {
    match family {
        CompileFamilyV2::FutureWindow => config.include_future_window_family,
        CompileFamilyV2::OfficialDiversity => config.include_official_diversity_family,
        CompileFamilyV2::TrinityOperational => config.include_trinity_operational_family,
        CompileFamilyV2::DatasetExport => config.include_dataset_export_family,
        CompileFamilyV2::ControlTowerV1 => config.include_control_tower_v1_family,
        CompileFamilyV2::CandleExpansionOps => config.include_candle_expansion_family,
        CompileFamilyV2::ExternalPrediction => config.include_external_prediction_family,
        CompileFamilyV2::KrxEvidence => config.include_krx_evidence_family,
        CompileFamilyV2::DashboardRenderer => config.include_dashboard_renderer_family,
        CompileFamilyV2::BaselineSignal => config.include_baseline_signal_family,
        CompileFamilyV2::CounterfactualBackfill => config.include_counterfactual_backfill_family,
        _ => true,
    }
}

fn sprint87_classify_name(name: &str) -> CompileFamilyV2 {
    let lowercase = name.to_ascii_lowercase();
    if lowercase.contains("future_window") || lowercase == "futurewindow" {
        CompileFamilyV2::FutureWindow
    } else if lowercase.contains("official_diversity")
        || lowercase.contains("official_evidence_diversity")
        || lowercase.contains("outcome_diversity")
        || lowercase == "officialdiversity"
    {
        CompileFamilyV2::OfficialDiversity
    } else if lowercase.contains("trinity_operational") || lowercase == "trinityoperational" {
        CompileFamilyV2::TrinityOperational
    } else if lowercase.contains("dataset_export")
        || lowercase.contains("sequence_dataset_export")
        || lowercase == "datasetexport"
    {
        CompileFamilyV2::DatasetExport
    } else if lowercase.contains("control_tower_v1") || lowercase == "controltowerv1" {
        CompileFamilyV2::ControlTowerV1
    } else if lowercase.contains("candle_expansion") || lowercase == "candleexpansionops" {
        CompileFamilyV2::CandleExpansionOps
    } else if lowercase.contains("external_prediction")
        || lowercase.contains("ext_model_b_prediction")
        || lowercase == "externalprediction"
    {
        CompileFamilyV2::ExternalPrediction
    } else if lowercase.contains("krx_evidence")
        || lowercase.contains("krx_collection")
        || lowercase == "krxevidence"
    {
        CompileFamilyV2::KrxEvidence
    } else if lowercase.contains("dashboard_renderer")
        || lowercase.contains("dashboard_v1_renderer")
        || lowercase == "dashboardrenderer"
    {
        CompileFamilyV2::DashboardRenderer
    } else if lowercase.contains("committee_cli_safety") || lowercase == "committeeclisafety" {
        CompileFamilyV2::CommitteeCliSafety
    } else if lowercase.contains("baseline_signal") || lowercase == "baselinesignal" {
        CompileFamilyV2::BaselineSignal
    } else if lowercase.contains("counterfactual_backfill")
        || lowercase.contains("counterfactual_completion")
        || lowercase == "counterfactualbackfill"
    {
        CompileFamilyV2::CounterfactualBackfill
    } else if lowercase.contains("cli_safety") || lowercase.contains("remote") {
        CompileFamilyV2::CliSafety
    } else if lowercase.contains("determinism") {
        CompileFamilyV2::Determinism
    } else if lowercase.contains("safety") || lowercase.contains("guard") {
        CompileFamilyV2::SafetyGuard
    } else {
        CompileFamilyV2::Unknown
    }
}

fn sprint87_suite_target_for_family(family: CompileFamilyV2) -> Option<&'static str> {
    match family {
        CompileFamilyV2::FutureWindow => Some(SPRINT87_SUITE_FUTURE_WINDOW),
        CompileFamilyV2::OfficialDiversity => Some(SPRINT87_SUITE_OFFICIAL_DIVERSITY),
        CompileFamilyV2::TrinityOperational => Some(SPRINT87_SUITE_TRINITY),
        CompileFamilyV2::DatasetExport => Some(SPRINT87_SUITE_DATASET_EXPORT),
        CompileFamilyV2::ControlTowerV1 => Some(SPRINT87_SUITE_CONTROL_TOWER),
        CompileFamilyV2::CandleExpansionOps => Some(SPRINT87_SUITE_CANDLE_EXPANSION),
        CompileFamilyV2::ExternalPrediction => Some(SPRINT87_SUITE_EXTERNAL),
        CompileFamilyV2::KrxEvidence => Some(SPRINT87_SUITE_KRX),
        CompileFamilyV2::DashboardRenderer => Some(SPRINT87_SUITE_DASHBOARD),
        CompileFamilyV2::BaselineSignal => Some(SPRINT87_SUITE_BASELINE),
        CompileFamilyV2::CounterfactualBackfill => Some(SPRINT87_SUITE_COUNTERFACTUAL),
        _ => None,
    }
}

fn load_sprint87_inputs(
    config: &WorkspaceCompileGraphAuditConfig,
) -> Result<Sprint87Inputs, String> {
    let mut sprint86_summary = None;
    for path in &config.sprint86_bundle_paths {
        if sprint87_file_name(path) == "sprint86_summary.json" {
            sprint86_summary = Some(load_json_file(path)?);
        }
    }
    let mut inventory_before = None;
    let mut inventory_after = None;
    let mut metadata_sample = None;
    for path in &config.cargo_metadata_paths {
        match sprint87_file_name(path) {
            "compile_families_before.json" => inventory_before = Some(load_json_file(path)?),
            "compile_families_after.json" => inventory_after = Some(load_json_file(path)?),
            "cargo_metadata_sample.json" => metadata_sample = Some(load_json_file(path)?),
            _ => {}
        }
    }
    let mut timings_sample = None;
    for path in &config.cargo_timings_paths {
        if sprint87_file_name(path) == "cargo_timings_sample.json" {
            timings_sample = Some(load_json_file(path)?);
        }
    }
    let mut no_run_sample = None;
    for path in &config.compile_only_attempt_paths {
        if sprint87_file_name(path) == "no_run_attempt_sample.json" {
            no_run_sample = Some(load_json_file(path)?);
        }
    }
    let mut full_workspace_expected = None;
    let mut safety_expected = None;
    for path in &config.full_workspace_attempt_paths {
        match sprint87_file_name(path) {
            "full_workspace_attempt_v5_expected.json" => {
                full_workspace_expected = Some(load_json_file(path)?)
            }
            "safety_coverage_v3_expected.json" => safety_expected = Some(load_json_file(path)?),
            _ => {}
        }
    }
    Ok(Sprint87Inputs {
        sprint86_summary: sprint86_summary
            .ok_or_else(|| "missing sprint86_summary.json".to_string())?,
        inventory_before: inventory_before
            .ok_or_else(|| "missing compile_families_before.json".to_string())?,
        inventory_after: inventory_after
            .ok_or_else(|| "missing compile_families_after.json".to_string())?,
        metadata_sample: metadata_sample
            .ok_or_else(|| "missing cargo_metadata_sample.json".to_string())?,
        timings_sample: timings_sample
            .ok_or_else(|| "missing cargo_timings_sample.json".to_string())?,
        no_run_sample: no_run_sample
            .ok_or_else(|| "missing no_run_attempt_sample.json".to_string())?,
        full_workspace_expected: full_workspace_expected
            .ok_or_else(|| "missing full_workspace_attempt_v5_expected.json".to_string())?,
        safety_expected: safety_expected
            .ok_or_else(|| "missing safety_coverage_v3_expected.json".to_string())?,
    })
}

fn build_workspace_compile_graph_audit_report(
    config: &WorkspaceCompileGraphAuditConfig,
    inventory_before: &CompileFamilyInventoryV2,
    metadata: &Sprint87CargoMetadataInput,
    timings: &Sprint87CargoTimingsInput,
) -> WorkspaceCompileGraphAuditReport {
    let target_families_for_grouping = inventory_before
        .records
        .iter()
        .filter(|record| {
            record.consolidation_candidate && sprint87_family_enabled(config, record.family)
        })
        .map(|record| format!("{:?}", record.family))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let audit_status = if timings.full_workspace_blocker_families.is_empty() {
        WorkspaceCompileGraphAuditStatus::CompileGraphAuditReady
    } else {
        WorkspaceCompileGraphAuditStatus::CompileGraphAuditReadyWithWarnings
    };
    WorkspaceCompileGraphAuditReport {
        audit_id: config.audit_id.clone(),
        observed_compile_families: config.observed_compile_families.clone(),
        compile_only_blocker_families: timings.compile_only_blocker_families.clone(),
        full_workspace_blocker_families: timings.full_workspace_blocker_families.clone(),
        target_families_for_grouping,
        dev_dependency_fanout_summary: format!(
            "{} dev dependencies, {} heavy candidates",
            metadata.dev_dependencies.len(),
            metadata.heavy_dev_dependency_candidates.len()
        ),
        feature_unification_summary: format!(
            "{} feature sets, {} repeated variants",
            metadata.feature_sets_detected.len(),
            metadata.repeated_feature_variants.len()
        ),
        audit_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_test_target_fanout_report(
    config: &WorkspaceCompileGraphAuditConfig,
    metadata: &Sprint87CargoMetadataInput,
) -> TestTargetFanoutReport {
    let fanout_status = if metadata.keep_separate_targets.is_empty() {
        TestTargetFanoutStatus::FanoutReportReady
    } else {
        TestTargetFanoutStatus::FanoutReportReadyWithWarnings
    };
    TestTargetFanoutReport {
        report_id: config.audit_id.clone(),
        total_integration_test_targets: Some(metadata.total_integration_test_targets),
        broad_family_targets: metadata.broad_family_targets.clone(),
        grouped_targets_existing: metadata.grouped_targets_existing.clone(),
        keep_separate_targets: metadata.keep_separate_targets.clone(),
        candidate_targets_for_grouping: metadata.candidate_targets_for_grouping.clone(),
        fanout_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

