fn build_remaining_compile_family_classifier_v2(
    config: &WorkspaceCompileGraphAuditConfig,
    inventory_before: &CompileFamilyInventoryV2,
) -> Result<RemainingCompileFamilyClassifierV2, String> {
    let mut classified_records = Vec::new();
    let mut unknown_records = Vec::new();
    for record in &inventory_before.records {
        let classified = sprint87_classify_name(&record.binary_name);
        if classified != record.family && record.family != CompileFamilyV2::Unknown {
            return Err(format!(
                "compile family classifier mismatch for {}",
                record.binary_name
            ));
        }
        let mut classified_record = record.clone();
        classified_record.family = classified;
        if classified == CompileFamilyV2::Unknown {
            unknown_records.push(classified_record.clone());
        }
        classified_records.push(classified_record);
    }
    let classifier_status = if unknown_records.is_empty() {
        RemainingCompileFamilyClassifierV2Status::ClassifierReady
    } else {
        RemainingCompileFamilyClassifierV2Status::ClassifierReadyWithWarnings
    };
    Ok(RemainingCompileFamilyClassifierV2 {
        classifier_id: config.audit_id.clone(),
        rules: vec![
            "future_window -> FutureWindow".to_string(),
            "official_diversity / official_evidence_diversity / outcome_diversity -> OfficialDiversity".to_string(),
            "trinity_operational -> TrinityOperational".to_string(),
            "dataset_export / sequence_dataset_export -> DatasetExport".to_string(),
            "control_tower_v1 -> ControlTowerV1".to_string(),
            "candle_expansion -> CandleExpansionOps".to_string(),
            "external_prediction / ext_model_b_prediction -> ExternalPrediction".to_string(),
            "krx_evidence / krx_collection -> KrxEvidence".to_string(),
            "dashboard_renderer -> DashboardRenderer".to_string(),
            "committee_cli_safety -> CommitteeCliSafety".to_string(),
            "baseline_signal -> BaselineSignal".to_string(),
            "counterfactual_backfill / counterfactual_completion -> CounterfactualBackfill".to_string(),
        ],
        classified_records,
        unknown_records,
        classifier_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    })
}

fn build_compile_heavy_family_consolidation_plan(
    config: &WorkspaceCompileGraphAuditConfig,
    inventory_before: &CompileFamilyInventoryV2,
    inventory_after: &CompileFamilyInventoryV2,
) -> CompileHeavyFamilyConsolidationPlan {
    let mut planned_suites: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut tests_to_move = Vec::new();
    for record in &inventory_before.records {
        if record.consolidation_candidate && sprint87_family_enabled(config, record.family) {
            tests_to_move.push(record.binary_name.clone());
            if let Some(suite) = sprint87_suite_target_for_family(record.family) {
                planned_suites
                    .entry(suite.to_string())
                    .or_default()
                    .push(record.binary_name.clone());
            }
        }
    }
    let keep_separate_count = inventory_before
        .records
        .iter()
        .filter(|record| record.keep_separate_reason.is_some())
        .count();
    let expected_test_target_delta =
        inventory_before.total_target_count as isize - inventory_after.total_target_count as isize;
    let semantic_risk = if keep_separate_count > 0 {
        TestBinaryConsolidationSemanticRisk::Medium
    } else {
        TestBinaryConsolidationSemanticRisk::Low
    };
    CompileHeavyFamilyConsolidationPlan {
        plan_id: config.audit_id.clone(),
        target_families: planned_suites.keys().cloned().collect::<Vec<_>>(),
        planned_suites,
        tests_to_move: tests_to_move.clone(),
        assertions_to_preserve: tests_to_move.len(),
        safety_guards_to_preserve: 8,
        expected_test_target_delta,
        semantic_risk,
        plan_status: CompileHeavyFamilyConsolidationPlanStatus::CompileHeavyPlanReady,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_compile_only_attempt_v2_report(
    config: &WorkspaceCompileGraphAuditConfig,
    no_run_sample: &Sprint87NoRunAttemptInput,
) -> CompileOnlyAttemptV2Report {
    let compile_status = if no_run_sample.finished && no_run_sample.passed == Some(true) {
        CompileOnlyAttemptV2Status::CompileOnlyPassed
    } else if no_run_sample.finished && no_run_sample.passed == Some(false) {
        CompileOnlyAttemptV2Status::CompileOnlyFailed
    } else if no_run_sample.started {
        CompileOnlyAttemptV2Status::CompileOnlyStillBlocked
    } else {
        CompileOnlyAttemptV2Status::NotRun
    };
    CompileOnlyAttemptV2Report {
        report_id: config.audit_id.clone(),
        command: "cargo test --workspace --no-run --quiet".to_string(),
        started: no_run_sample.started,
        finished: no_run_sample.finished,
        passed: no_run_sample.passed,
        duration_ms: no_run_sample.duration_ms,
        blocked_families: no_run_sample.blocked_families.clone(),
        blocked_test_targets: no_run_sample.blocked_test_targets.clone(),
        compile_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_no_run_acceptance_gate_v2(
    config: &WorkspaceCompileGraphAuditConfig,
    compile_only: &CompileOnlyAttemptV2Report,
    full_workspace: &Sprint87FullWorkspaceInput,
) -> NoRunAcceptanceGateV2 {
    let grouped_suite_status = if full_workspace.broad_family_suites_passed {
        "BroadFamilySuitesReady".to_string()
    } else {
        "NeedFurtherConsolidation".to_string()
    };
    let safety_suite_status = if full_workspace.safety_guard_suite_passed
        && full_workspace.workspace_cli_safety_passed
        && full_workspace.workspace_determinism_passed
    {
        "SafetySuitesReady".to_string()
    } else {
        "SafetySuitesBlocked".to_string()
    };
    let no_run_gate_status = match compile_only.compile_status {
        CompileOnlyAttemptV2Status::CompileOnlyPassed => {
            NoRunAcceptanceGateV2Status::NoRunGatePassed
        }
        CompileOnlyAttemptV2Status::CompileOnlyFailed => {
            NoRunAcceptanceGateV2Status::NoRunGateFailed
        }
        CompileOnlyAttemptV2Status::CompileOnlyStillBlocked => {
            NoRunAcceptanceGateV2Status::NoRunGateStillBlocked
        }
        CompileOnlyAttemptV2Status::NotRun => NoRunAcceptanceGateV2Status::NotRun,
    };
    NoRunAcceptanceGateV2 {
        gate_id: config.audit_id.clone(),
        compile_only_status: compile_only.compile_status,
        grouped_suite_status,
        safety_suite_status,
        no_run_gate_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_full_workspace_acceptance_attempt_v5(
    config: &WorkspaceCompileGraphAuditConfig,
    compile_only: &CompileOnlyAttemptV2Report,
    full_workspace: &Sprint87FullWorkspaceInput,
) -> FullWorkspaceAcceptanceAttemptV5 {
    let attempt_status = if full_workspace.full_workspace_finished
        && full_workspace.full_workspace_passed == Some(true)
        && full_workspace.fmt_passed
        && full_workspace.check_passed
        && full_workspace.broad_family_suites_passed
        && full_workspace.safety_guard_suite_passed
        && full_workspace.workspace_cli_safety_passed
        && full_workspace.workspace_determinism_passed
        && full_workspace.representative_smoke_passed
        && full_workspace.safety_smoke_passed
    {
        FullWorkspaceAcceptanceAttemptV5Status::FullWorkspaceAccepted
    } else if matches!(
        compile_only.compile_status,
        CompileOnlyAttemptV2Status::CompileOnlyStillBlocked
            | CompileOnlyAttemptV2Status::CompileOnlyFailed
    ) {
        FullWorkspaceAcceptanceAttemptV5Status::CompileOnlyBlocked
    } else if full_workspace.full_workspace_started {
        FullWorkspaceAcceptanceAttemptV5Status::FullWorkspaceStillBlocked
    } else if full_workspace.broad_family_suites_passed {
        FullWorkspaceAcceptanceAttemptV5Status::FocusedOnly
    } else {
        FullWorkspaceAcceptanceAttemptV5Status::NotRun
    };
    FullWorkspaceAcceptanceAttemptV5 {
        attempt_id: config.audit_id.clone(),
        fmt_passed: full_workspace.fmt_passed,
        check_passed: full_workspace.check_passed,
        broad_family_suites_passed: full_workspace.broad_family_suites_passed,
        safety_guard_suite_passed: full_workspace.safety_guard_suite_passed,
        workspace_cli_safety_passed: full_workspace.workspace_cli_safety_passed,
        workspace_determinism_passed: full_workspace.workspace_determinism_passed,
        representative_smoke_passed: full_workspace.representative_smoke_passed,
        safety_smoke_passed: full_workspace.safety_smoke_passed,
        compile_only_started: compile_only.started,
        compile_only_finished: compile_only.finished,
        compile_only_passed: compile_only.passed,
        full_workspace_started: full_workspace.full_workspace_started,
        full_workspace_finished: full_workspace.full_workspace_finished,
        full_workspace_passed: full_workspace.full_workspace_passed,
        full_workspace_duration_ms: full_workspace.full_workspace_duration_ms,
        full_workspace_blockers: full_workspace.full_workspace_blockers.clone(),
        attempt_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_workspace_compile_gate_recovery_report(
    config: &WorkspaceCompileGraphAuditConfig,
    sprint86_summary: &Sprint87SummaryInput,
    plan: &CompileHeavyFamilyConsolidationPlan,
    dev_dependency: &DevDependencyFanoutReport,
    feature_unification: &WorkspaceFeatureUnificationReport,
    compile_only: &CompileOnlyAttemptV2Report,
    attempt: &FullWorkspaceAcceptanceAttemptV5,
    safety: &SafetyCoveragePreservationReportV3,
) -> WorkspaceCompileGateRecoveryReport {
    let current_compile_only_status = format!("{:?}", compile_only.compile_status);
    let current_full_workspace_status = format!("{:?}", attempt.attempt_status);
    let recovery_status = if attempt.attempt_status
        == FullWorkspaceAcceptanceAttemptV5Status::FullWorkspaceAccepted
    {
        WorkspaceCompileGateRecoveryReportStatus::FullGateRecovered
    } else if compile_only.compile_status == CompileOnlyAttemptV2Status::CompileOnlyPassed
        && sprint86_summary.previous_compile_only_status != "CompileOnlyPassed"
    {
        WorkspaceCompileGateRecoveryReportStatus::CompileGateRecovered
    } else if plan.expected_test_target_delta > 0 {
        WorkspaceCompileGateRecoveryReportStatus::GateImprovedButBlocked
    } else {
        WorkspaceCompileGateRecoveryReportStatus::GateStillBlocked
    };
    WorkspaceCompileGateRecoveryReport {
        report_id: config.audit_id.clone(),
        previous_compile_only_status: sprint86_summary.previous_compile_only_status.clone(),
        current_compile_only_status,
        previous_full_workspace_status: sprint86_summary.previous_full_workspace_status.clone(),
        current_full_workspace_status,
        target_delta: Some(plan.expected_test_target_delta),
        broad_suite_status: format!("{:?}", plan.plan_status),
        dev_dependency_status: format!("{:?}", dev_dependency.dependency_status),
        feature_unification_status: format!("{:?}", feature_unification.report_status),
        safety_coverage_status: format!("{:?}", safety.safety_status),
        remaining_blockers: attempt.full_workspace_blockers.clone(),
        recovery_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_workspace_compile_blocker_drilldown_v3(
    config: &WorkspaceCompileGraphAuditConfig,
    inventory_before: &CompileFamilyInventoryV2,
    timings: &Sprint87CargoTimingsInput,
    attempt: &FullWorkspaceAcceptanceAttemptV5,
) -> WorkspaceCompileBlockerDrilldownV3 {
    let blockers = if attempt.full_workspace_blockers.is_empty() {
        timings.full_workspace_blocker_families.clone()
    } else {
        attempt.full_workspace_blockers.clone()
    };
    let blocker_family_name = blockers
        .first()
        .cloned()
        .unwrap_or_else(|| "none".to_string());
    let blocker_family = sprint87_classify_name(&blocker_family_name);
    let suspected_files = inventory_before
        .records
        .iter()
        .filter(|record| record.family == blocker_family)
        .map(|record| record.binary_name.clone())
        .collect::<Vec<_>>();
    let report_status = if blockers.is_empty() {
        WorkspaceCompileBlockerDrilldownV3Status::NoBlockers
    } else {
        WorkspaceCompileBlockerDrilldownV3Status::BlockersExplained
    };
    WorkspaceCompileBlockerDrilldownV3 {
        report_id: config.audit_id.clone(),
        blockers,
        blocker_family: format!("{:?}", blocker_family),
        suspected_files,
        suspected_crates: timings.suspected_crates.clone(),
        suspected_dev_dependencies: timings.suspected_dev_dependencies.clone(),
        suspected_feature_variants: timings.suspected_feature_variants.clone(),
        recommended_suite_target: sprint87_suite_target_for_family(blocker_family)
            .map(str::to_string),
        suggested_next_actions: vec![
            "keep grouped suites conservative".to_string(),
            "re-run cargo test --workspace --no-run after migration".to_string(),
            "re-observe full workspace blockers without claiming a pass".to_string(),
        ],
        report_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_test_target_delta_report_v3(
    config: &WorkspaceCompileGraphAuditConfig,
    inventory_before: &CompileFamilyInventoryV2,
    inventory_after: &CompileFamilyInventoryV2,
    plan: &CompileHeavyFamilyConsolidationPlan,
) -> TestTargetDeltaReportV3 {
    let delta_status = if inventory_before.total_target_count > inventory_after.total_target_count {
        TestTargetDeltaReportV3Status::SampleBackedOnly
    } else {
        TestTargetDeltaReportV3Status::NoMeasuredReduction
    };
    let kept_separate_count = inventory_before
        .records
        .iter()
        .filter(|record| record.keep_separate_reason.is_some())
        .count();
    TestTargetDeltaReportV3 {
        report_id: config.audit_id.clone(),
        target_count_before: Some(inventory_before.total_target_count),
        target_count_after: Some(inventory_after.total_target_count),
        moved_test_count: plan.tests_to_move.len(),
        grouped_suite_count: inventory_after
            .records
            .iter()
            .filter(|record| record.consolidation_candidate)
            .count(),
        kept_separate_count,
        measured: false,
        sample_backed: true,
        delta_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

