#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SevenBlockerFamilyRecoveryConfig {
    pub recovery_id: String,
    #[serde(default)]
    pub sprint87_bundle_paths: Vec<String>,
    #[serde(default)]
    pub compile_gate_report_paths: Vec<String>,
    #[serde(default)]
    pub blocker_drilldown_paths: Vec<String>,
    #[serde(default)]
    pub cargo_metadata_paths: Vec<String>,
    #[serde(default)]
    pub cargo_timings_paths: Vec<String>,
    #[serde(default = "default_sprint88_output_root")]
    pub output_root: String,
    #[serde(default = "default_sprint88_blocker_families")]
    pub blocker_families: Vec<CompileFamilyV2>,
    #[serde(default = "default_sprint88_ordered_family_queue")]
    pub ordered_family_queue: Vec<CompileFamilyV2>,
    #[serde(default)]
    pub run_per_family_probes: bool,
    #[serde(default)]
    pub run_no_run_after_each_family: bool,
    #[serde(default)]
    pub run_full_after_each_family: bool,
    #[serde(default = "default_true")]
    pub preserve_assertions: bool,
    #[serde(default = "default_true")]
    pub preserve_safety_guards: bool,
    #[serde(default = "default_true")]
    pub require_committee_cli_safety_isolation: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for SevenBlockerFamilyRecoveryConfig {
    fn default() -> Self {
        Self {
            recovery_id: "sprint88-seven-blocker-recover".to_string(),
            sprint87_bundle_paths: Vec::new(),
            compile_gate_report_paths: Vec::new(),
            blocker_drilldown_paths: Vec::new(),
            cargo_metadata_paths: Vec::new(),
            cargo_timings_paths: Vec::new(),
            output_root: default_sprint88_output_root(),
            blocker_families: default_sprint88_blocker_families(),
            ordered_family_queue: default_sprint88_ordered_family_queue(),
            run_per_family_probes: false,
            run_no_run_after_each_family: false,
            run_full_after_each_family: false,
            preserve_assertions: true,
            preserve_safety_guards: true,
            require_committee_cli_safety_isolation: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl SevenBlockerFamilyRecoveryConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.recovery_id.trim().is_empty() {
            return Err("seven blocker family recovery config requires recovery_id".to_string());
        }
        for path in self
            .sprint87_bundle_paths
            .iter()
            .chain(self.compile_gate_report_paths.iter())
            .chain(self.blocker_drilldown_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if path.contains("://") {
                return Err(format!(
                    "seven blocker family recovery paths must be local: {path}"
                ));
            }
        }
        if self.require_committee_cli_safety_isolation
            && !self
                .ordered_family_queue
                .contains(&CompileFamilyV2::CommitteeCliSafety)
        {
            return Err(
                "committee_cli_safety isolation is required but the ordered queue omits it"
                    .to_string(),
            );
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.recovery_id)
    }
}

