#[derive(Clone, Debug, Default)]
pub struct Sprint88SevenBlockerRecoveryRunner;

pub type SevenBlockerFamilyRecoveryRunner = Sprint88SevenBlockerRecoveryRunner;

fn default_sprint88_output_root() -> String {
    "target/soma_sprint88_seven_blocker_recovery".to_string()
}

fn default_sprint88_ordered_family_queue() -> Vec<CompileFamilyV2> {
    vec![
        CompileFamilyV2::CandleExpansionOps,
        CompileFamilyV2::ExternalPrediction,
        CompileFamilyV2::KrxEvidence,
        CompileFamilyV2::DashboardRenderer,
        CompileFamilyV2::CommitteeCliSafety,
        CompileFamilyV2::BaselineSignal,
        CompileFamilyV2::CounterfactualBackfill,
    ]
}

fn default_sprint88_blocker_families() -> Vec<CompileFamilyV2> {
    default_sprint88_ordered_family_queue()
}

fn sprint88_family_label(family: CompileFamilyV2) -> String {
    format!("{family:?}")
}

fn sprint88_family_test_target(family: CompileFamilyV2) -> &'static str {
    match family {
        CompileFamilyV2::CandleExpansionOps => "candle_expansion_ops_suite",
        CompileFamilyV2::ExternalPrediction => "external_prediction_family_suite",
        CompileFamilyV2::KrxEvidence => "krx_evidence_suite",
        CompileFamilyV2::DashboardRenderer => "dashboard_renderer_suite",
        CompileFamilyV2::CommitteeCliSafety => "committee_cli_safety",
        CompileFamilyV2::BaselineSignal => "baseline_signal_suite",
        CompileFamilyV2::CounterfactualBackfill => "counterfactual_backfill_suite",
        _ => "workspace_safety_guard_suite",
    }
}

fn sprint88_file_name(path: &str) -> &str {
    Path::new(path)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(path)
}

fn sprint88_probe_record<'a>(
    catalog: &'a Sprint88PerFamilyProbeCatalog,
    family: CompileFamilyV2,
) -> Result<&'a Sprint88PerFamilyProbeSample, String> {
    catalog
        .families
        .iter()
        .find(|record| record.family == family)
        .ok_or_else(|| {
            format!(
                "missing Sprint 88 probe sample for {}",
                sprint88_family_label(family)
            )
        })
}

fn sprint88_expected_actions(family: CompileFamilyV2) -> Vec<FamilyReductionAction> {
    match family {
        CompileFamilyV2::CandleExpansionOps => vec![
            FamilyReductionAction::ReuseGroupedSuite,
            FamilyReductionAction::MoveRemainingAssertions,
            FamilyReductionAction::ApplySharedFixtureHarness,
        ],
        CompileFamilyV2::ExternalPrediction => vec![
            FamilyReductionAction::ReuseGroupedSuite,
            FamilyReductionAction::CollapseFeatureVariant,
            FamilyReductionAction::ApplySharedFixtureHarness,
        ],
        CompileFamilyV2::KrxEvidence => vec![
            FamilyReductionAction::ReuseGroupedSuite,
            FamilyReductionAction::ReduceFixtureSetupDuplication,
        ],
        CompileFamilyV2::DashboardRenderer => vec![
            FamilyReductionAction::ReuseGroupedSuite,
            FamilyReductionAction::ReduceGoldenRenderDuplication,
        ],
        CompileFamilyV2::CommitteeCliSafety => {
            vec![FamilyReductionAction::KeepSeparateForIsolation]
        }
        CompileFamilyV2::BaselineSignal => vec![
            FamilyReductionAction::ReuseGroupedSuite,
            FamilyReductionAction::MoveRemainingAssertions,
        ],
        CompileFamilyV2::CounterfactualBackfill => vec![
            FamilyReductionAction::ReuseGroupedSuite,
            FamilyReductionAction::MoveRemainingAssertions,
        ],
        _ => vec![FamilyReductionAction::NoAction],
    }
}

fn sprint88_assertions_to_preserve(family: CompileFamilyV2) -> usize {
    match family {
        CompileFamilyV2::CandleExpansionOps => 6,
        CompileFamilyV2::ExternalPrediction => 8,
        CompileFamilyV2::KrxEvidence => 6,
        CompileFamilyV2::DashboardRenderer => 6,
        CompileFamilyV2::CommitteeCliSafety => 6,
        CompileFamilyV2::BaselineSignal => 5,
        CompileFamilyV2::CounterfactualBackfill => 7,
        _ => 0,
    }
}

fn sprint88_safety_guards_to_preserve(family: CompileFamilyV2) -> usize {
    match family {
        CompileFamilyV2::DashboardRenderer | CompileFamilyV2::CommitteeCliSafety => 3,
        CompileFamilyV2::CandleExpansionOps
        | CompileFamilyV2::ExternalPrediction
        | CompileFamilyV2::KrxEvidence
        | CompileFamilyV2::BaselineSignal
        | CompileFamilyV2::CounterfactualBackfill => 2,
        _ => 0,
    }
}

fn sprint88_semantic_risk(family: CompileFamilyV2) -> TestBinaryConsolidationSemanticRisk {
    match family {
        CompileFamilyV2::CommitteeCliSafety => TestBinaryConsolidationSemanticRisk::High,
        CompileFamilyV2::CandleExpansionOps
        | CompileFamilyV2::ExternalPrediction
        | CompileFamilyV2::KrxEvidence
        | CompileFamilyV2::BaselineSignal
        | CompileFamilyV2::CounterfactualBackfill => TestBinaryConsolidationSemanticRisk::Medium,
        CompileFamilyV2::DashboardRenderer => TestBinaryConsolidationSemanticRisk::Low,
        _ => TestBinaryConsolidationSemanticRisk::Low,
    }
}

fn sprint88_dependency_impact_by_family() -> BTreeMap<String, Vec<String>> {
    BTreeMap::from([
        (
            sprint88_family_label(CompileFamilyV2::BaselineSignal),
            vec!["serde_json".to_string()],
        ),
        (
            sprint88_family_label(CompileFamilyV2::CandleExpansionOps),
            vec![
                "serde_json".to_string(),
                "tempfile".to_string(),
                "insta".to_string(),
            ],
        ),
        (
            sprint88_family_label(CompileFamilyV2::CounterfactualBackfill),
            vec!["serde_json".to_string(), "tempfile".to_string()],
        ),
        (
            sprint88_family_label(CompileFamilyV2::DashboardRenderer),
            vec!["serde_json".to_string(), "insta".to_string()],
        ),
        (
            sprint88_family_label(CompileFamilyV2::ExternalPrediction),
            vec!["serde_json".to_string(), "tempfile".to_string()],
        ),
        (
            sprint88_family_label(CompileFamilyV2::KrxEvidence),
            vec!["serde_json".to_string()],
        ),
    ])
}

fn load_sprint88_inputs(
    config: &SevenBlockerFamilyRecoveryConfig,
) -> Result<Sprint88Inputs, String> {
    let mut sprint87_summary = None;
    let mut queue = None;
    let mut probe_catalog = None;
    let mut candle_expected = None;
    let mut external_expected = None;
    let mut krx_expected = None;
    let mut dashboard_expected = None;
    let mut committee_expected = None;
    let mut baseline_expected = None;
    let mut counterfactual_expected = None;
    let mut workspace_gate_expected = None;
    let mut safety_expected = None;
    for path in config
        .sprint87_bundle_paths
        .iter()
        .chain(config.compile_gate_report_paths.iter())
        .chain(config.blocker_drilldown_paths.iter())
        .chain(config.cargo_metadata_paths.iter())
        .chain(config.cargo_timings_paths.iter())
    {
        match sprint88_file_name(path) {
            "sprint87_summary.json" => sprint87_summary = Some(load_json_file(path)?),
            "seven_blocker_queue.json" => queue = Some(load_json_file(path)?),
            "per_family_probe_sample.json" => probe_catalog = Some(load_json_file(path)?),
            "candle_expansion_recovery_expected.json" => {
                candle_expected = Some(load_json_file(path)?)
            }
            "external_prediction_recovery_expected.json" => {
                external_expected = Some(load_json_file(path)?)
            }
            "krx_evidence_recovery_expected.json" => krx_expected = Some(load_json_file(path)?),
            "dashboard_renderer_recovery_expected.json" => {
                dashboard_expected = Some(load_json_file(path)?)
            }
            "committee_cli_safety_isolation_expected.json" => {
                committee_expected = Some(load_json_file(path)?)
            }
            "baseline_signal_recovery_expected.json" => {
                baseline_expected = Some(load_json_file(path)?)
            }
            "counterfactual_backfill_recovery_expected.json" => {
                counterfactual_expected = Some(load_json_file(path)?)
            }
            "workspace_gate_recovery_v5_expected.json" => {
                workspace_gate_expected = Some(load_json_file(path)?)
            }
            "safety_coverage_v4_expected.json" => safety_expected = Some(load_json_file(path)?),
            _ => {}
        }
    }
    Ok(Sprint88Inputs {
        sprint87_summary: sprint87_summary
            .ok_or_else(|| "missing sprint87_summary.json".to_string())?,
        queue: queue.ok_or_else(|| "missing seven_blocker_queue.json".to_string())?,
        per_family_probe_catalog: probe_catalog
            .ok_or_else(|| "missing per_family_probe_sample.json".to_string())?,
        candle_expected: candle_expected
            .ok_or_else(|| "missing candle_expansion_recovery_expected.json".to_string())?,
        external_expected: external_expected
            .ok_or_else(|| "missing external_prediction_recovery_expected.json".to_string())?,
        krx_expected: krx_expected
            .ok_or_else(|| "missing krx_evidence_recovery_expected.json".to_string())?,
        dashboard_expected: dashboard_expected
            .ok_or_else(|| "missing dashboard_renderer_recovery_expected.json".to_string())?,
        committee_expected: committee_expected
            .ok_or_else(|| "missing committee_cli_safety_isolation_expected.json".to_string())?,
        baseline_expected: baseline_expected
            .ok_or_else(|| "missing baseline_signal_recovery_expected.json".to_string())?,
        counterfactual_expected: counterfactual_expected
            .ok_or_else(|| "missing counterfactual_backfill_recovery_expected.json".to_string())?,
        workspace_gate_expected: workspace_gate_expected
            .ok_or_else(|| "missing workspace_gate_recovery_v5_expected.json".to_string())?,
        safety_expected: safety_expected
            .ok_or_else(|| "missing safety_coverage_v4_expected.json".to_string())?,
    })
}

fn build_per_family_compile_probe_config(
    config: &SevenBlockerFamilyRecoveryConfig,
    family: CompileFamilyV2,
    sample: &Sprint88PerFamilyProbeSample,
) -> PerFamilyCompileProbeConfig {
    PerFamilyCompileProbeConfig {
        probe_id: format!("{}-{}", config.recovery_id, sprint88_family_label(family)),
        family,
        commands: if sample.commands.is_empty() {
            vec![format!(
                "cargo test --test {} --no-run --quiet",
                sprint88_family_test_target(family)
            )]
        } else {
            sample.commands.clone()
        },
        output_root: config.output_root.clone(),
        run_real_commands: config.run_per_family_probes,
        timeout_ms: None,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_family_reduction_plan(
    config: &SevenBlockerFamilyRecoveryConfig,
    family: CompileFamilyV2,
    sample: &Sprint88PerFamilyProbeSample,
) -> FamilyReductionPlan {
    let actions = if sample.reduction_actions.is_empty() {
        sprint88_expected_actions(family)
    } else {
        sample.reduction_actions.clone()
    };
    FamilyReductionPlan {
        plan_id: format!("{}-{}", config.recovery_id, sprint88_family_label(family)),
        family,
        actions,
        assertions_to_preserve: sprint88_assertions_to_preserve(family),
        safety_guards_to_preserve: sprint88_safety_guards_to_preserve(family),
        expected_target_delta: sample.target_delta,
        semantic_risk: sprint88_semantic_risk(family),
        plan_status: if family == CompileFamilyV2::CommitteeCliSafety {
            FamilyReductionPlanStatus::NeedManualReview
        } else {
            FamilyReductionPlanStatus::FamilyPlanReady
        },
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

fn build_family_reduction_report(
    config: &SevenBlockerFamilyRecoveryConfig,
    family: CompileFamilyV2,
    sample: &Sprint88PerFamilyProbeSample,
    plan: &FamilyReductionPlan,
) -> FamilyReductionReport {
    FamilyReductionReport {
        report_id: format!("{}-{}", config.recovery_id, sprint88_family_label(family)),
        family,
        actions_applied: plan.actions.clone(),
        assertions_preserved: sample.assertions_preserved,
        safety_guards_preserved: sample.safety_guards_preserved,
        target_delta: sample.target_delta,
        report_status: sample.reduction_report_status,
        reason_codes: stable_reason_codes(&[
            ReasonCode::DeterministicPath,
            ReasonCode::LocalFileOnly,
        ]),
    }
}

