fn build_per_family_compile_probe_reports(
    config: &SevenBlockerFamilyRecoveryConfig,
    queue: &[CompileFamilyV2],
    catalog: &Sprint88PerFamilyProbeCatalog,
) -> Result<Vec<PerFamilyCompileProbeReport>, String> {
    queue
        .iter()
        .map(|family| {
            let sample = sprint88_probe_record(catalog, *family)?;
            let probe_config = build_per_family_compile_probe_config(config, *family, sample);
            Ok(PerFamilyCompileProbeReport {
                probe_id: probe_config.probe_id,
                family: *family,
                command_results: sample.command_results.clone(),
                compile_only_result: sample.compile_only_result.clone(),
                execution_result: sample.execution_result.clone(),
                wall_time_ms: sample.wall_time_ms,
                probe_status: sample.compile_probe_status,
                reason_codes: stable_reason_codes(&[
                    ReasonCode::DeterministicPath,
                    ReasonCode::LocalFileOnly,
                ]),
            })
        })
        .collect()
}

