#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct CandleExpansionRealReductionConfig {
    pub reduction_id: String,
    #[serde(default)]
    pub sprint88_bundle_paths: Vec<String>,
    #[serde(default)]
    pub candle_expansion_suite_paths: Vec<String>,
    #[serde(default)]
    pub official_candle_expansion_runner_paths: Vec<String>,
    #[serde(default)]
    pub cargo_metadata_paths: Vec<String>,
    #[serde(default)]
    pub cargo_timings_paths: Vec<String>,
    #[serde(default = "default_sprint89_output_root")]
    pub output_root: String,
    #[serde(default = "default_sprint89_target_family")]
    pub target_family: CompileFamilyV2,
    #[serde(default)]
    pub run_real_no_run_after_reduction: bool,
    #[serde(default)]
    pub run_real_full_after_reduction: bool,
    #[serde(default = "default_true")]
    pub preserve_assertions: bool,
    #[serde(default = "default_true")]
    pub preserve_safety_guards: bool,
    #[serde(default = "default_true")]
    pub preserve_source_boundary: bool,
    #[serde(default = "default_true")]
    pub preserve_no_lookahead: bool,
    #[serde(default = "default_true")]
    pub preserve_storage_budget_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_missing_auth_checks: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for CandleExpansionRealReductionConfig {
    fn default() -> Self {
        Self {
            reduction_id: "sprint89-candle-recover".to_string(),
            sprint88_bundle_paths: Vec::new(),
            candle_expansion_suite_paths: Vec::new(),
            official_candle_expansion_runner_paths: Vec::new(),
            cargo_metadata_paths: Vec::new(),
            cargo_timings_paths: Vec::new(),
            output_root: default_sprint89_output_root(),
            target_family: default_sprint89_target_family(),
            run_real_no_run_after_reduction: false,
            run_real_full_after_reduction: false,
            preserve_assertions: true,
            preserve_safety_guards: true,
            preserve_source_boundary: true,
            preserve_no_lookahead: true,
            preserve_storage_budget_checks: true,
            preserve_missing_auth_checks: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl CandleExpansionRealReductionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.reduction_id.trim().is_empty() {
            return Err("candle expansion real reduction config requires reduction_id".to_string());
        }
        if self.target_family != CompileFamilyV2::CandleExpansionOps {
            return Err(
                "candle expansion real reduction target_family must remain CandleExpansionOps"
                    .to_string(),
            );
        }
        for path in self
            .sprint88_bundle_paths
            .iter()
            .chain(self.candle_expansion_suite_paths.iter())
            .chain(self.official_candle_expansion_runner_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if path.contains("://") {
                return Err(format!(
                    "candle expansion real reduction paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.reduction_id)
    }
}

