#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ExternalPredictionRealReductionConfig {
    pub reduction_id: String,
    #[serde(default)]
    pub sprint89_bundle_paths: Vec<String>,
    #[serde(default)]
    pub external_prediction_suite_paths: Vec<String>,
    #[serde(default)]
    pub external_prediction_import_v2_paths: Vec<String>,
    #[serde(default)]
    pub sequence_core_prototype_paths: Vec<String>,
    #[serde(default)]
    pub model_card_fixture_paths: Vec<String>,
    #[serde(default)]
    pub prediction_schema_fixture_paths: Vec<String>,
    #[serde(default)]
    pub cargo_metadata_paths: Vec<String>,
    #[serde(default)]
    pub cargo_timings_paths: Vec<String>,
    #[serde(default = "default_sprint90_output_root")]
    pub output_root: String,
    #[serde(default = "default_sprint90_target_family")]
    pub target_family: CompileFamilyV2,
    #[serde(default)]
    pub run_real_no_run_after_reduction: bool,
    #[serde(default)]
    pub run_real_full_after_reduction: bool,
    #[serde(default = "default_true")]
    pub preserve_assertions: bool,
    #[serde(default = "default_true")]
    pub preserve_safety_guards: bool,
    #[serde(default = "default_true")]
    pub preserve_prediction_schema_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_model_card_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_duplicate_rejection: bool,
    #[serde(default = "default_true")]
    pub preserve_probability_sanity: bool,
    #[serde(default = "default_true")]
    pub preserve_forbidden_column_rejection: bool,
    #[serde(default = "default_true")]
    pub preserve_runtime_deferred_checks: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for ExternalPredictionRealReductionConfig {
    fn default() -> Self {
        Self {
            reduction_id: "sprint90-external-prediction-recover".to_string(),
            sprint89_bundle_paths: Vec::new(),
            external_prediction_suite_paths: Vec::new(),
            external_prediction_import_v2_paths: Vec::new(),
            sequence_core_prototype_paths: Vec::new(),
            model_card_fixture_paths: Vec::new(),
            prediction_schema_fixture_paths: Vec::new(),
            cargo_metadata_paths: Vec::new(),
            cargo_timings_paths: Vec::new(),
            output_root: default_sprint90_output_root(),
            target_family: default_sprint90_target_family(),
            run_real_no_run_after_reduction: false,
            run_real_full_after_reduction: false,
            preserve_assertions: true,
            preserve_safety_guards: true,
            preserve_prediction_schema_checks: true,
            preserve_model_card_checks: true,
            preserve_duplicate_rejection: true,
            preserve_probability_sanity: true,
            preserve_forbidden_column_rejection: true,
            preserve_runtime_deferred_checks: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl ExternalPredictionRealReductionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.reduction_id.trim().is_empty() {
            return Err(
                "external prediction real reduction config requires reduction_id".to_string(),
            );
        }
        if self.target_family != CompileFamilyV2::ExternalPrediction {
            return Err(
                "external prediction real reduction target_family must remain ExternalPrediction"
                    .to_string(),
            );
        }
        for path in self
            .sprint89_bundle_paths
            .iter()
            .chain(self.external_prediction_suite_paths.iter())
            .chain(self.external_prediction_import_v2_paths.iter())
            .chain(self.sequence_core_prototype_paths.iter())
            .chain(self.model_card_fixture_paths.iter())
            .chain(self.prediction_schema_fixture_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if path.contains("://") {
                return Err(format!(
                    "external prediction real reduction paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.reduction_id)
    }
}

