fn build_external_prediction_real_reduction_report(
    config: &ExternalPredictionRealReductionConfig,
    plan: &ExternalPredictionRealReductionPlan,
    assertion_report: &ExternalPredictionAssertionMigrationReport,
    fixture_report: &ExternalPredictionFixtureSetupReductionReport,
    feature_variant_report: &ExternalPredictionFeatureVariantReductionReport,
    schema_report: &ExternalPredictionSchemaPreservationReport,
    model_card_report: &ExternalPredictionModelCardPreservationReport,
    evaluation_report: &ExternalPredictionEvaluationPreservationReport,
) -> ExternalPredictionRealReductionReport {
    let grouped_suite_verified = sprint89_any_path_exists(&plan.target_files);
    let reduced = grouped_suite_verified
        && assertion_report.assertions_remaining == 0
        && config.preserve_assertions
        && config.preserve_safety_guards
        && schema_report.schema_status
            == ExternalPredictionSchemaPreservationStatus::SchemaPreserved
        && model_card_report.model_card_status
            == ExternalPredictionModelCardPreservationStatus::ModelCardPreserved
        && evaluation_report.evaluation_status
            == ExternalPredictionEvaluationPreservationStatus::EvaluationPreserved
        && feature_variant_report.reduction_status
            != ExternalPredictionFeatureVariantReductionStatus::UnsafeToReduce;
    ExternalPredictionRealReductionReport {
        report_id: format!("{}-reduction", config.reduction_id),
        target_suite: plan
            .target_files
            .first()
            .cloned()
            .unwrap_or_else(|| "tests/external_prediction_family_suite.rs".to_string()),
        donor_files: plan.donor_files.clone(),
        grouped_suite_verified,
        assertions_preserved: config.preserve_assertions && assertion_report.assertions_found > 0,
        safety_guards_preserved: config.preserve_safety_guards,
        schema_checks_preserved: schema_report.schema_status
            == ExternalPredictionSchemaPreservationStatus::SchemaPreserved,
        model_card_checks_preserved: model_card_report.model_card_status
            == ExternalPredictionModelCardPreservationStatus::ModelCardPreserved,
        duplicate_rejection_preserved: config.preserve_duplicate_rejection,
        probability_sanity_preserved: config.preserve_probability_sanity,
        forbidden_column_rejection_preserved: config.preserve_forbidden_column_rejection,
        runtime_deferred_checks_preserved: config.preserve_runtime_deferred_checks,
        shared_fixture_harness_used: fixture_report.shared_fixture_harness_used,
        reduction_status: if reduced {
            ExternalPredictionRealReductionStatus::ExternalPredictionRealReduced
        } else {
            ExternalPredictionRealReductionStatus::ExternalPredictionStillPrimaryBlocker
        },
        reason_codes: sprint90_reason_codes(&[]),
    }
}

