fn build_seven_blocker_queue_progress_report_v6(
    config: &ExternalPredictionRealReductionConfig,
    inputs: &Sprint90Inputs,
    reduction_report: &ExternalPredictionRealReductionReport,
) -> SevenBlockerQueueProgressReportV6 {
    let reduced = reduction_report.reduction_status
        == ExternalPredictionRealReductionStatus::ExternalPredictionRealReduced;
    let current_queue = if reduced {
        inputs.queue_expected.reduced_queue.clone()
    } else {
        inputs.summary.previous_remaining_blockers.clone()
    };
    SevenBlockerQueueProgressReportV6 {
        report_id: format!("{}-queue-progress", config.reduction_id),
        previous_queue: inputs.summary.previous_remaining_blockers.clone(),
        current_queue: current_queue.clone(),
        completed_families: if reduced {
            vec!["ExternalPrediction".to_string()]
        } else {
            Vec::new()
        },
        reduced_families: if reduced {
            vec!["ExternalPrediction".to_string()]
        } else {
            Vec::new()
        },
        still_blocked_families: current_queue.clone(),
        primary_next_family: if reduced {
            inputs.queue_expected.reduced_primary_next_family.clone()
        } else {
            "ExternalPrediction".to_string()
        },
        queue_status: if current_queue.is_empty() {
            SevenBlockerQueueProgressStatusV5::QueueClosed
        } else if reduced {
            SevenBlockerQueueProgressStatusV5::QueueAdvanced
        } else {
            SevenBlockerQueueProgressStatusV5::QueueUnchanged
        },
        reason_codes: sprint90_reason_codes(&[]),
    }
}

