#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct KrxEvidenceRealReductionConfig {
    pub reduction_id: String,
    #[serde(default)]
    pub sprint90_bundle_paths: Vec<String>,
    #[serde(default)]
    pub krx_evidence_suite_paths: Vec<String>,
    #[serde(default)]
    pub krx_evidence_job_plan_paths: Vec<String>,
    #[serde(default)]
    pub krx_collection_paths: Vec<String>,
    #[serde(default)]
    pub krx_auth_fixture_paths: Vec<String>,
    #[serde(default)]
    pub krx_endpoint_template_fixture_paths: Vec<String>,
    #[serde(default)]
    pub cargo_metadata_paths: Vec<String>,
    #[serde(default)]
    pub cargo_timings_paths: Vec<String>,
    #[serde(default = "default_sprint91_output_root")]
    pub output_root: String,
    #[serde(default = "default_sprint91_target_family")]
    pub target_family: CompileFamilyV2,
    #[serde(default)]
    pub run_real_no_run_after_reduction: bool,
    #[serde(default)]
    pub run_real_full_after_reduction: bool,
    #[serde(default = "default_true")]
    pub preserve_assertions: bool,
    #[serde(default = "default_true")]
    pub preserve_safety_guards: bool,
    #[serde(default = "default_true")]
    pub preserve_missing_auth_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_endpoint_template_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_market_data_only_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_no_order_account_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_source_boundary_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_deterministic_status_checks: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for KrxEvidenceRealReductionConfig {
    fn default() -> Self {
        Self {
            reduction_id: "sprint91-krx-evidence-recover".to_string(),
            sprint90_bundle_paths: Vec::new(),
            krx_evidence_suite_paths: Vec::new(),
            krx_evidence_job_plan_paths: Vec::new(),
            krx_collection_paths: Vec::new(),
            krx_auth_fixture_paths: Vec::new(),
            krx_endpoint_template_fixture_paths: Vec::new(),
            cargo_metadata_paths: Vec::new(),
            cargo_timings_paths: Vec::new(),
            output_root: default_sprint91_output_root(),
            target_family: default_sprint91_target_family(),
            run_real_no_run_after_reduction: false,
            run_real_full_after_reduction: false,
            preserve_assertions: true,
            preserve_safety_guards: true,
            preserve_missing_auth_checks: true,
            preserve_endpoint_template_checks: true,
            preserve_market_data_only_checks: true,
            preserve_no_order_account_checks: true,
            preserve_source_boundary_checks: true,
            preserve_deterministic_status_checks: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl KrxEvidenceRealReductionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.reduction_id.trim().is_empty() {
            return Err("krx evidence real reduction config requires reduction_id".to_string());
        }
        if self.target_family != CompileFamilyV2::KrxEvidence {
            return Err(
                "krx evidence real reduction target_family must remain KrxEvidence".to_string(),
            );
        }
        for path in self
            .sprint90_bundle_paths
            .iter()
            .chain(self.krx_evidence_suite_paths.iter())
            .chain(self.krx_evidence_job_plan_paths.iter())
            .chain(self.krx_collection_paths.iter())
            .chain(self.krx_auth_fixture_paths.iter())
            .chain(self.krx_endpoint_template_fixture_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if path.contains("://") {
                return Err(format!(
                    "krx evidence real reduction paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.reduction_id)
    }
}

