fn sprint91_suite_paths(config: &KrxEvidenceRealReductionConfig) -> Vec<String> {
    if config.krx_evidence_suite_paths.is_empty() {
        vec!["tests/krx_evidence_suite.rs".to_string()]
    } else {
        config.krx_evidence_suite_paths.clone()
    }
}

fn sprint91_donor_paths(config: &KrxEvidenceRealReductionConfig) -> Vec<String> {
    if !config.krx_evidence_job_plan_paths.is_empty() || !config.krx_collection_paths.is_empty() {
        let mut paths = config.krx_evidence_job_plan_paths.clone();
        paths.extend(config.krx_collection_paths.iter().cloned());
        return paths;
    }
    vec![
        "tests/krx_evidence_job_plan.rs".to_string(),
        "tests/krx_collection_dry_run.rs".to_string(),
        "tests/krx_collection_batch_plan.rs".to_string(),
        "tests/krx_collection_closure_runner.rs".to_string(),
        "tests/krx_collection_closure_cli_safety.rs".to_string(),
        "tests/krx_raw_archive_secret_safety.rs".to_string(),
        "tests/krx_canonical_batch_validation.rs".to_string(),
        "tests/krx_candle_sufficiency.rs".to_string(),
        "tests/krx_outcome_link_closure.rs".to_string(),
        "tests/krx_downstream_rerun_v2.rs".to_string(),
    ]
}

fn load_sprint91_inputs(config: &KrxEvidenceRealReductionConfig) -> Result<Sprint91Inputs, String> {
    let mut summary = None;
    let mut plan_expected = None;
    let mut assertion_expected = None;
    let mut auth_expected = None;
    let mut endpoint_expected = None;
    let mut source_expected = None;
    let mut market_expected = None;
    let mut compile_impact_sample = None;
    let mut no_run_sample = None;
    let mut full_gate_sample = None;
    let mut queue_expected = None;
    let mut safety_expected = None;
    for path in config
        .sprint90_bundle_paths
        .iter()
        .chain(config.krx_auth_fixture_paths.iter())
        .chain(config.krx_endpoint_template_fixture_paths.iter())
        .chain(config.cargo_metadata_paths.iter())
        .chain(config.cargo_timings_paths.iter())
    {
        match sprint89_file_name(path) {
            "sprint90_summary.json" => summary = Some(load_json_file(path)?),
            "krx_reduction_plan_expected.json" => plan_expected = Some(load_json_file(path)?),
            "krx_assertion_migration_expected.json" => {
                assertion_expected = Some(load_json_file(path)?)
            }
            "krx_auth_boundary_expected.json" => auth_expected = Some(load_json_file(path)?),
            "krx_endpoint_template_expected.json" => {
                endpoint_expected = Some(load_json_file(path)?)
            }
            "krx_source_boundary_expected.json" => source_expected = Some(load_json_file(path)?),
            "krx_market_data_only_expected.json" => market_expected = Some(load_json_file(path)?),
            "krx_compile_impact_sample.json" => compile_impact_sample = Some(load_json_file(path)?),
            "krx_no_run_rerun_sample.json" => no_run_sample = Some(load_json_file(path)?),
            "krx_full_gate_rerun_sample.json" => full_gate_sample = Some(load_json_file(path)?),
            "queue_progress_v7_expected.json" => queue_expected = Some(load_json_file(path)?),
            "safety_coverage_v7_expected.json" => safety_expected = Some(load_json_file(path)?),
            _ => {}
        }
    }
    Ok(Sprint91Inputs {
        summary: summary.ok_or_else(|| "missing sprint90_summary.json".to_string())?,
        plan_expected: plan_expected
            .ok_or_else(|| "missing krx_reduction_plan_expected.json".to_string())?,
        assertion_expected: assertion_expected
            .ok_or_else(|| "missing krx_assertion_migration_expected.json".to_string())?,
        auth_expected: auth_expected
            .ok_or_else(|| "missing krx_auth_boundary_expected.json".to_string())?,
        endpoint_expected: endpoint_expected
            .ok_or_else(|| "missing krx_endpoint_template_expected.json".to_string())?,
        source_expected: source_expected
            .ok_or_else(|| "missing krx_source_boundary_expected.json".to_string())?,
        market_expected: market_expected
            .ok_or_else(|| "missing krx_market_data_only_expected.json".to_string())?,
        compile_impact_sample: compile_impact_sample
            .ok_or_else(|| "missing krx_compile_impact_sample.json".to_string())?,
        no_run_sample: no_run_sample
            .ok_or_else(|| "missing krx_no_run_rerun_sample.json".to_string())?,
        full_gate_sample: full_gate_sample
            .ok_or_else(|| "missing krx_full_gate_rerun_sample.json".to_string())?,
        queue_expected: queue_expected
            .ok_or_else(|| "missing queue_progress_v7_expected.json".to_string())?,
        safety_expected: safety_expected
            .ok_or_else(|| "missing safety_coverage_v7_expected.json".to_string())?,
    })
}

fn sprint91_reason_codes(extra: &[ReasonCode]) -> Vec<ReasonCode> {
    sprint90_reason_codes(extra)
}

fn build_krx_evidence_real_reduction_plan(
    config: &KrxEvidenceRealReductionConfig,
    inputs: &Sprint91Inputs,
) -> Result<KrxEvidenceRealReductionPlan, String> {
    let target_files = if inputs.plan_expected.target_files.is_empty() {
        sprint91_suite_paths(config)
    } else {
        inputs.plan_expected.target_files.clone()
    };
    let donor_files = if !inputs.assertion_expected.donor_files.is_empty() {
        inputs.assertion_expected.donor_files.clone()
    } else if !inputs.plan_expected.donor_files.is_empty() {
        inputs.plan_expected.donor_files.clone()
    } else {
        sprint91_donor_paths(config)
    };
    let mut actions = vec![
        KrxEvidenceRealReductionAction::VerifyGroupedSuiteCoverage,
        KrxEvidenceRealReductionAction::ApplySharedFixtureHarness,
        KrxEvidenceRealReductionAction::RemoveDuplicateSetupOnly,
        KrxEvidenceRealReductionAction::ReduceKrxAuthFixtureDuplication,
        KrxEvidenceRealReductionAction::ReduceEndpointTemplateFixtureDuplication,
        KrxEvidenceRealReductionAction::ReduceRawArchiveFixtureDuplication,
    ];
    if !donor_files.is_empty() {
        actions.push(KrxEvidenceRealReductionAction::MoveRemainingAssertions);
    }
    if !inputs
        .assertion_expected
        .high_risk_assertions_kept_separate
        .is_empty()
    {
        actions.push(KrxEvidenceRealReductionAction::KeepSeparateForIsolation);
    }
    let semantic_risk = if !config.preserve_assertions || !config.preserve_safety_guards {
        TestBinaryConsolidationSemanticRisk::High
    } else if !inputs
        .assertion_expected
        .high_risk_assertions_kept_separate
        .is_empty()
        || donor_files.len() > 6
    {
        TestBinaryConsolidationSemanticRisk::Medium
    } else {
        TestBinaryConsolidationSemanticRisk::Low
    };
    let plan_status = if target_files.is_empty() {
        KrxEvidenceRealReductionPlanStatus::DiagnosticOnly
    } else if !config.preserve_assertions || !config.preserve_safety_guards {
        KrxEvidenceRealReductionPlanStatus::TooRisky
    } else if !inputs
        .assertion_expected
        .high_risk_assertions_kept_separate
        .is_empty()
    {
        KrxEvidenceRealReductionPlanStatus::NeedManualReview
    } else {
        KrxEvidenceRealReductionPlanStatus::KrxReductionPlanReady
    };
    Ok(KrxEvidenceRealReductionPlan {
        plan_id: format!("{}-plan", config.reduction_id),
        target_files: target_files.clone(),
        donor_files,
        actions,
        assertions_to_preserve: sprint89_count_assertions(&target_files)?,
        safety_guards_to_preserve: 7,
        auth_fixture_duplication: inputs.plan_expected.auth_fixture_duplication.clone(),
        endpoint_template_fixture_duplication: inputs
            .plan_expected
            .endpoint_template_fixture_duplication
            .clone(),
        raw_archive_fixture_duplication: inputs
            .plan_expected
            .raw_archive_fixture_duplication
            .clone(),
        expected_target_delta: inputs.plan_expected.expected_target_delta,
        semantic_risk,
        plan_status,
        reason_codes: sprint91_reason_codes(&[]),
    })
}

fn build_krx_evidence_assertion_migration_report(
    config: &KrxEvidenceRealReductionConfig,
    plan: &KrxEvidenceRealReductionPlan,
    inputs: &Sprint91Inputs,
) -> Result<KrxEvidenceAssertionMigrationReport, String> {
    let assertions_found = sprint89_count_assertions(&plan.target_files)?;
    let assertions_remaining = inputs
        .assertion_expected
        .high_risk_assertions_kept_separate
        .len();
    let assertions_migrated = assertions_found.saturating_sub(assertions_remaining);
    let migration_status = if assertions_remaining == 0 {
        CandleExpansionAssertionMigrationStatus::AssertionsMigrated
    } else if assertions_migrated > 0 {
        CandleExpansionAssertionMigrationStatus::AssertionsMigratedWithWarnings
    } else {
        CandleExpansionAssertionMigrationStatus::AssertionsRemaining
    };
    Ok(KrxEvidenceAssertionMigrationReport {
        report_id: format!("{}-assertions", config.reduction_id),
        donor_files: plan.donor_files.clone(),
        target_suite: if inputs.assertion_expected.target_suite.is_empty() {
            plan.target_files
                .first()
                .cloned()
                .unwrap_or_else(|| "tests/krx_evidence_suite.rs".to_string())
        } else {
            inputs.assertion_expected.target_suite.clone()
        },
        assertions_found,
        assertions_migrated,
        assertions_remaining,
        high_risk_assertions_kept_separate: inputs
            .assertion_expected
            .high_risk_assertions_kept_separate
            .clone(),
        migration_status,
        reason_codes: sprint91_reason_codes(&[]),
    })
}

fn build_krx_evidence_fixture_setup_reduction_report(
    config: &KrxEvidenceRealReductionConfig,
    plan: &KrxEvidenceRealReductionPlan,
) -> KrxEvidenceFixtureSetupReductionReport {
    let all_dups = plan
        .auth_fixture_duplication
        .iter()
        .chain(plan.endpoint_template_fixture_duplication.iter())
        .chain(plan.raw_archive_fixture_duplication.iter())
        .cloned()
        .collect::<Vec<_>>();
    let duplicate_json_loads_removed = count_prefixed(&all_dups, "json:");
    let duplicate_csv_loads_removed = count_prefixed(&all_dups, "csv:");
    let duplicate_toml_loads_removed = count_prefixed(&all_dups, "toml:");
    let duplicate_output_dirs_removed = count_prefixed(&all_dups, "output_dir:");
    let duplicate_auth_fixtures_removed = count_prefixed(&all_dups, "auth_fixture:");
    let duplicate_endpoint_template_fixtures_removed =
        count_prefixed(&all_dups, "endpoint_template:");
    let total_removed = duplicate_json_loads_removed
        + duplicate_csv_loads_removed
        + duplicate_toml_loads_removed
        + duplicate_output_dirs_removed
        + duplicate_auth_fixtures_removed
        + duplicate_endpoint_template_fixtures_removed;
    KrxEvidenceFixtureSetupReductionReport {
        report_id: format!("{}-fixture-setup", config.reduction_id),
        duplicate_json_loads_removed,
        duplicate_csv_loads_removed,
        duplicate_toml_loads_removed,
        duplicate_output_dirs_removed,
        duplicate_auth_fixtures_removed,
        duplicate_endpoint_template_fixtures_removed,
        shared_fixture_harness_used: plan
            .actions
            .contains(&KrxEvidenceRealReductionAction::ApplySharedFixtureHarness),
        deterministic_output_preserved: config.preserve_deterministic_status_checks,
        reduction_status: if total_removed == 0 {
            CandleExpansionFixtureSetupReductionStatus::NoReduction
        } else if config.preserve_deterministic_status_checks {
            CandleExpansionFixtureSetupReductionStatus::FixtureSetupReduced
        } else {
            CandleExpansionFixtureSetupReductionStatus::FixtureSetupReducedWithWarnings
        },
        reason_codes: sprint91_reason_codes(&[]),
    }
}

