fn build_krx_evidence_compile_impact_report(
    config: &KrxEvidenceRealReductionConfig,
    inputs: &Sprint91Inputs,
) -> KrxEvidenceCompileImpactReport {
    let sample = &inputs.compile_impact_sample;
    let impact_status = if sample.measured {
        if sample.target_count_before.is_some() && sample.target_count_after.is_some() {
            CandleExpansionCompileImpactStatus::CompileImpactMeasured
        } else {
            CandleExpansionCompileImpactStatus::CompileImpactFailed
        }
    } else if sample.sample_backed {
        CandleExpansionCompileImpactStatus::CompileImpactSampleBacked
    } else if !sample.blocked_targets.is_empty() {
        CandleExpansionCompileImpactStatus::CompileImpactStillBlocked
    } else {
        CandleExpansionCompileImpactStatus::CompileImpactNotRun
    };
    KrxEvidenceCompileImpactReport {
        report_id: format!("{}-compile-impact", config.reduction_id),
        target_count_before: sample.target_count_before,
        target_count_after: sample.target_count_after,
        krx_family_delta: sample
            .target_count_before
            .zip(sample.target_count_after)
            .map(|(before, after)| before as i64 - after as i64),
        compile_duration_before_ms: sample.compile_duration_before_ms,
        compile_duration_after_ms: sample.compile_duration_after_ms,
        measured: sample.measured,
        sample_backed: sample.sample_backed,
        blocked_targets: sample.blocked_targets.clone(),
        impact_status,
        reason_codes: sprint91_reason_codes(&[]),
    }
}

fn build_krx_evidence_real_reduction_report(
    config: &KrxEvidenceRealReductionConfig,
    plan: &KrxEvidenceRealReductionPlan,
    assertion_report: &KrxEvidenceAssertionMigrationReport,
    fixture_report: &KrxEvidenceFixtureSetupReductionReport,
    auth_report: &KrxEvidenceAuthBoundaryPreservationReport,
    endpoint_report: &KrxEvidenceEndpointTemplatePreservationReport,
    source_report: &KrxEvidenceSourceBoundaryPreservationReport,
    market_report: &KrxEvidenceMarketDataOnlyPreservationReport,
    compile_impact: &KrxEvidenceCompileImpactReport,
) -> KrxEvidenceRealReductionReport {
    let preserved = auth_report.auth_status
        == KrxEvidenceAuthBoundaryPreservationStatus::AuthBoundaryPreserved
        && endpoint_report.endpoint_status
            == KrxEvidenceEndpointTemplatePreservationStatus::EndpointTemplatePreserved
        && source_report.source_boundary_status
            == KrxEvidenceSourceBoundaryPreservationStatus::SourceBoundaryPreserved
        && market_report.market_data_status
            == KrxEvidenceMarketDataOnlyPreservationStatus::MarketDataOnlyPreserved;
    let with_warning_preserved = auth_report.auth_status
        != KrxEvidenceAuthBoundaryPreservationStatus::AuthBoundaryRegression
        && endpoint_report.endpoint_status
            != KrxEvidenceEndpointTemplatePreservationStatus::EndpointTemplateRegression
        && source_report.source_boundary_status
            != KrxEvidenceSourceBoundaryPreservationStatus::SourceBoundaryRegression
        && market_report.market_data_status
            != KrxEvidenceMarketDataOnlyPreservationStatus::MarketDataBoundaryRegression;
    let reduction_status = if plan.plan_status == KrxEvidenceRealReductionPlanStatus::DiagnosticOnly
    {
        KrxEvidenceRealReductionStatus::DiagnosticOnly
    } else if !sprint89_any_path_exists(&plan.target_files)
        || assertion_report.assertions_found == 0
    {
        KrxEvidenceRealReductionStatus::NoReduction
    } else if plan.plan_status == KrxEvidenceRealReductionPlanStatus::KrxReductionPlanReady
        && assertion_report.assertions_remaining == 0
        && fixture_report.reduction_status
            != CandleExpansionFixtureSetupReductionStatus::NoReduction
        && preserved
        && compile_impact.impact_status != CandleExpansionCompileImpactStatus::CompileImpactFailed
    {
        KrxEvidenceRealReductionStatus::KrxEvidenceRealReduced
    } else if with_warning_preserved
        && config.preserve_assertions
        && config.preserve_safety_guards
        && compile_impact.impact_status != CandleExpansionCompileImpactStatus::CompileImpactFailed
    {
        KrxEvidenceRealReductionStatus::KrxEvidenceReducedWithWarnings
    } else {
        KrxEvidenceRealReductionStatus::KrxEvidenceStillPrimaryBlocker
    };
    KrxEvidenceRealReductionReport {
        report_id: format!("{}-reduction", config.reduction_id),
        reduction_plan_status: plan.plan_status,
        assertion_migration_status: assertion_report.migration_status,
        fixture_setup_reduction_status: fixture_report.reduction_status,
        auth_boundary_status: auth_report.auth_status,
        endpoint_template_status: endpoint_report.endpoint_status,
        source_boundary_status: source_report.source_boundary_status,
        market_data_only_status: market_report.market_data_status,
        compile_impact_status: compile_impact.impact_status,
        reduction_status,
        reason_codes: sprint91_reason_codes(&[]),
    }
}

fn build_krx_evidence_no_run_gate_rerun_report(
    config: &KrxEvidenceRealReductionConfig,
    inputs: &Sprint91Inputs,
    current_queue: &[String],
) -> KrxEvidenceNoRunGateRerunReport {
    let sample = &inputs.no_run_sample;
    let started = config.run_real_no_run_after_reduction;
    let remaining_blocker_families = if config.run_real_no_run_after_reduction {
        if sample.remaining_blocker_families.is_empty()
            && !sample.finished
            && sample.passed != Some(true)
        {
            current_queue.to_vec()
        } else {
            sample.remaining_blocker_families.clone()
        }
    } else {
        current_queue.to_vec()
    };
    let status = if !config.run_real_no_run_after_reduction {
        KrxEvidenceNoRunGateRerunStatus::NotRun
    } else if sample.finished
        && sample.passed == Some(true)
        && remaining_blocker_families.is_empty()
    {
        KrxEvidenceNoRunGateRerunStatus::NoRunRecoveredAfterKrxEvidence
    } else if sample.finished
        && sample.passed == Some(false)
        && remaining_blocker_families.is_empty()
    {
        KrxEvidenceNoRunGateRerunStatus::NoRunFailedAfterKrxEvidence
    } else {
        KrxEvidenceNoRunGateRerunStatus::NoRunStillBlockedAfterKrxEvidence
    };
    KrxEvidenceNoRunGateRerunReport {
        report_id: format!("{}-no-run-rerun", config.reduction_id),
        command: "cargo test --workspace --no-run --quiet".to_string(),
        started,
        finished: config.run_real_no_run_after_reduction && sample.finished,
        passed: if config.run_real_no_run_after_reduction {
            sample.passed
        } else {
            None
        },
        duration_ms: if config.run_real_no_run_after_reduction {
            sample.duration_ms
        } else {
            None
        },
        rerun_after_family: CompileFamilyV2::KrxEvidence,
        remaining_blocker_families,
        status,
        reason_codes: sprint91_reason_codes(&[]),
    }
}

