#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct KrxEvidenceWarningClosureConfig {
    pub closure_id: String,
    #[serde(default)]
    pub sprint91_bundle_paths: Vec<String>,
    #[serde(default)]
    pub krx_evidence_reduction_paths: Vec<String>,
    #[serde(default)]
    pub krx_assertion_migration_paths: Vec<String>,
    #[serde(default)]
    pub krx_secret_safety_paths: Vec<String>,
    #[serde(default)]
    pub krx_raw_archive_paths: Vec<String>,
    #[serde(default)]
    pub krx_market_data_boundary_paths: Vec<String>,
    #[serde(default)]
    pub workspace_gate_paths: Vec<String>,
    #[serde(default = "default_sprint92_output_root")]
    pub output_root: String,
    #[serde(default = "default_sprint92_target_family")]
    pub target_family: CompileFamilyV2,
    #[serde(default)]
    pub allow_dashboard_renderer_entry_if_closed: bool,
    #[serde(default = "default_true")]
    pub require_secret_safety_isolation_decision: bool,
    #[serde(default = "default_true")]
    pub require_raw_archive_redaction_coverage: bool,
    #[serde(default = "default_true")]
    pub require_warning_free_reduction: bool,
    #[serde(default = "default_true")]
    pub require_manual_review_closure: bool,
    #[serde(default = "default_true")]
    pub preserve_assertions: bool,
    #[serde(default = "default_true")]
    pub preserve_safety_guards: bool,
    #[serde(default = "default_true")]
    pub preserve_market_data_only_checks: bool,
    #[serde(default = "default_true")]
    pub preserve_no_order_account_checks: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for KrxEvidenceWarningClosureConfig {
    fn default() -> Self {
        Self {
            closure_id: "sprint92-krx-warning-close".to_string(),
            sprint91_bundle_paths: Vec::new(),
            krx_evidence_reduction_paths: Vec::new(),
            krx_assertion_migration_paths: Vec::new(),
            krx_secret_safety_paths: Vec::new(),
            krx_raw_archive_paths: Vec::new(),
            krx_market_data_boundary_paths: Vec::new(),
            workspace_gate_paths: Vec::new(),
            output_root: default_sprint92_output_root(),
            target_family: default_sprint92_target_family(),
            allow_dashboard_renderer_entry_if_closed: false,
            require_secret_safety_isolation_decision: true,
            require_raw_archive_redaction_coverage: true,
            require_warning_free_reduction: true,
            require_manual_review_closure: true,
            preserve_assertions: true,
            preserve_safety_guards: true,
            preserve_market_data_only_checks: true,
            preserve_no_order_account_checks: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl KrxEvidenceWarningClosureConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.closure_id.trim().is_empty() {
            return Err("krx evidence warning closure config requires closure_id".to_string());
        }
        if self.target_family != CompileFamilyV2::KrxEvidence {
            return Err(
                "krx evidence warning closure target_family must remain KrxEvidence".to_string(),
            );
        }
        for path in self
            .sprint91_bundle_paths
            .iter()
            .chain(self.krx_evidence_reduction_paths.iter())
            .chain(self.krx_assertion_migration_paths.iter())
            .chain(self.krx_secret_safety_paths.iter())
            .chain(self.krx_raw_archive_paths.iter())
            .chain(self.krx_market_data_boundary_paths.iter())
            .chain(self.workspace_gate_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if !path_is_local(path) {
                return Err(format!(
                    "krx evidence warning closure paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.closure_id)
    }
}

