#[derive(Clone, Debug, Default)]
pub struct Sprint92KrxWarningClosureRunner;

fn default_sprint92_output_root() -> String {
    "target/soma_sprint92_krx_warning_closure".to_string()
}

fn default_sprint92_target_family() -> CompileFamilyV2 {
    CompileFamilyV2::KrxEvidence
}

fn sprint92_reason_codes(extra: &[ReasonCode]) -> Vec<ReasonCode> {
    sprint91_reason_codes(extra)
}

fn sprint92_read_text(path: &str) -> Result<String, String> {
    fs::read_to_string(sprint76_absolutize(path)).map_err(|err| err.to_string())
}

fn sprint92_override_path(paths: &[String], expected_file_name: &str, fallback: &str) -> String {
    paths
        .iter()
        .find(|path| sprint89_file_name(path) == expected_file_name)
        .cloned()
        .unwrap_or_else(|| fallback.to_string())
}

fn sprint92_load_bundle_dir(root: &Path, loaded: &mut Sprint92LoadedInputs) -> Result<(), String> {
    let bundle_files = [
        "krx_evidence_real_reduction.txt",
        "krx_evidence_assertion_migration.txt",
        "real_no_run_gate_attempt_v6.txt",
        "real_full_workspace_gate_attempt_v9.txt",
        "measured_target_delta_v7.txt",
        "remaining_blocker_queue_v7.txt",
        "safety_coverage_preservation_v7.txt",
    ];
    for name in bundle_files {
        let path = root.join(name);
        if !path.exists() {
            continue;
        }
        let text = fs::read_to_string(&path).map_err(|err| err.to_string())?;
        match name {
            "krx_evidence_real_reduction.txt" => {
                loaded.previous_reduction =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "krx_evidence_assertion_migration.txt" => {
                loaded.previous_assertion =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_no_run_gate_attempt_v6.txt" => {
                loaded.previous_real_no_run =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_full_workspace_gate_attempt_v9.txt" => {
                loaded.previous_real_full =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "measured_target_delta_v7.txt" => {
                loaded.previous_measured_delta =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "remaining_blocker_queue_v7.txt" => {
                loaded.previous_remaining_queue =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "safety_coverage_preservation_v7.txt" => {
                loaded.previous_safety =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            _ => {}
        }
    }
    Ok(())
}

fn sprint92_parse_previous_reduction_status(value: &str) -> KrxEvidenceRealReductionStatus {
    match value {
        "KrxEvidenceRealReduced" => KrxEvidenceRealReductionStatus::KrxEvidenceRealReduced,
        "KrxEvidenceReducedWithWarnings" => {
            KrxEvidenceRealReductionStatus::KrxEvidenceReducedWithWarnings
        }
        "KrxEvidenceStillPrimaryBlocker" => {
            KrxEvidenceRealReductionStatus::KrxEvidenceStillPrimaryBlocker
        }
        "NoReduction" => KrxEvidenceRealReductionStatus::NoReduction,
        _ => KrxEvidenceRealReductionStatus::DiagnosticOnly,
    }
}

fn sprint92_parse_no_run_status(value: &str) -> RealNoRunGateAttemptV7Status {
    match value {
        "RealNoRunPassed" => RealNoRunGateAttemptV7Status::RealNoRunPassed,
        "RealNoRunFailed" => RealNoRunGateAttemptV7Status::RealNoRunFailed,
        "NotRun" => RealNoRunGateAttemptV7Status::NotRun,
        _ => RealNoRunGateAttemptV7Status::RealNoRunStillBlocked,
    }
}

fn sprint92_parse_full_status(value: &str) -> RealFullWorkspaceGateAttemptV10Status {
    match value {
        "FullWorkspaceAccepted" => RealFullWorkspaceGateAttemptV10Status::FullWorkspaceAccepted,
        "FullWorkspaceFailed" => RealFullWorkspaceGateAttemptV10Status::FullWorkspaceFailed,
        "NotRun" => RealFullWorkspaceGateAttemptV10Status::NotRun,
        _ => RealFullWorkspaceGateAttemptV10Status::FullWorkspaceStillBlocked,
    }
}

fn sprint92_default_previous_reduction(
    config: &KrxEvidenceWarningClosureConfig,
    summary: &Sprint92SummaryInput,
) -> KrxEvidenceRealReductionReport {
    KrxEvidenceRealReductionReport {
        report_id: format!("{}-previous-reduction", config.closure_id),
        reduction_plan_status: KrxEvidenceRealReductionPlanStatus::NeedManualReview,
        assertion_migration_status: if summary.assertions_remaining == 0 {
            KrxEvidenceAssertionMigrationStatus::AssertionsMigrated
        } else {
            KrxEvidenceAssertionMigrationStatus::AssertionsMigratedWithWarnings
        },
        fixture_setup_reduction_status: KrxEvidenceFixtureSetupReductionStatus::FixtureSetupReduced,
        auth_boundary_status: KrxEvidenceAuthBoundaryPreservationStatus::AuthBoundaryPreserved,
        endpoint_template_status:
            KrxEvidenceEndpointTemplatePreservationStatus::EndpointTemplatePreserved,
        source_boundary_status:
            KrxEvidenceSourceBoundaryPreservationStatus::SourceBoundaryPreserved,
        market_data_only_status:
            KrxEvidenceMarketDataOnlyPreservationStatus::MarketDataOnlyPreserved,
        compile_impact_status: KrxEvidenceCompileImpactStatus::CompileImpactSampleBacked,
        reduction_status: sprint92_parse_previous_reduction_status(&summary.previous_status),
        reason_codes: sprint92_reason_codes(&[]),
    }
}

fn sprint92_default_previous_assertion(
    config: &KrxEvidenceWarningClosureConfig,
    summary: &Sprint92SummaryInput,
) -> KrxEvidenceAssertionMigrationReport {
    KrxEvidenceAssertionMigrationReport {
        report_id: format!("{}-previous-assertions", config.closure_id),
        donor_files: sprint91_donor_paths(&KrxEvidenceRealReductionConfig::default()),
        target_suite: "tests/krx_evidence_suite.rs".to_string(),
        assertions_found: summary.assertions_found,
        assertions_migrated: summary.assertions_migrated,
        assertions_remaining: summary.assertions_remaining,
        high_risk_assertions_kept_separate: if summary.isolated_sentinel.is_empty() {
            Vec::new()
        } else {
            vec![summary.isolated_sentinel.clone()]
        },
        migration_status: if summary.assertions_remaining == 0 {
            KrxEvidenceAssertionMigrationStatus::AssertionsMigrated
        } else {
            KrxEvidenceAssertionMigrationStatus::AssertionsMigratedWithWarnings
        },
        reason_codes: sprint92_reason_codes(&[]),
    }
}

fn sprint92_default_measured_delta(
    config: &KrxEvidenceWarningClosureConfig,
    summary: &Sprint92SummaryInput,
) -> MeasuredTargetDeltaReportV7 {
    MeasuredTargetDeltaReportV7 {
        report_id: format!("{}-previous-measured-delta", config.closure_id),
        target_count_before: summary.previous_target_count_before,
        target_count_after: summary.previous_target_count_after,
        krx_family_delta: match (
            summary.previous_target_count_before,
            summary.previous_target_count_after,
        ) {
            (Some(before), Some(after)) => Some(before as i64 - after as i64),
            _ => None,
        },
        measured: false,
        sample_backed: true,
        timing_available: false,
        delta_status: MeasuredTargetDeltaV7Status::SampleBackedOnly,
        reason_codes: sprint92_reason_codes(&[]),
    }
}

#[allow(dead_code)]
fn sprint92_default_no_run_attempt(
    config: &KrxEvidenceWarningClosureConfig,
    summary: &Sprint92SummaryInput,
) -> RealNoRunGateAttemptV6 {
    let status = sprint92_parse_no_run_status(&summary.previous_no_run_status);
    RealNoRunGateAttemptV6 {
        attempt_id: format!("{}-previous-real-no-run", config.closure_id),
        command: "cargo test --workspace --no-run --quiet".to_string(),
        started: status != RealNoRunGateAttemptV7Status::NotRun,
        finished: matches!(
            status,
            RealNoRunGateAttemptV7Status::RealNoRunPassed
                | RealNoRunGateAttemptV7Status::RealNoRunFailed
        ),
        passed: match status {
            RealNoRunGateAttemptV7Status::RealNoRunPassed => Some(true),
            RealNoRunGateAttemptV7Status::RealNoRunFailed => Some(false),
            _ => None,
        },
        duration_ms: summary.no_run_timeout_ms,
        rerun_after_family: Some(CompileFamilyV2::KrxEvidence),
        blocked_families: summary.previous_remaining_blockers.clone(),
        no_run_status: status,
        reason_codes: sprint92_reason_codes(&[]),
    }
}

#[allow(dead_code)]
fn sprint92_default_full_attempt(
    config: &KrxEvidenceWarningClosureConfig,
    summary: &Sprint92SummaryInput,
) -> RealFullWorkspaceGateAttemptV9 {
    let status = sprint92_parse_full_status(&summary.previous_full_status);
    RealFullWorkspaceGateAttemptV9 {
        attempt_id: format!("{}-previous-real-full", config.closure_id),
        command: "cargo test --workspace --quiet".to_string(),
        started: status != RealFullWorkspaceGateAttemptV10Status::NotRun,
        finished: matches!(
            status,
            RealFullWorkspaceGateAttemptV10Status::FullWorkspaceAccepted
                | RealFullWorkspaceGateAttemptV10Status::FullWorkspaceFailed
        ),
        passed: match status {
            RealFullWorkspaceGateAttemptV10Status::FullWorkspaceAccepted => Some(true),
            RealFullWorkspaceGateAttemptV10Status::FullWorkspaceFailed => Some(false),
            _ => None,
        },
        duration_ms: summary.full_timeout_ms,
        rerun_after_family: Some(CompileFamilyV2::KrxEvidence),
        blocked_families: summary.previous_remaining_blockers.clone(),
        full_status: status,
        reason_codes: sprint92_reason_codes(&[]),
    }
}

