#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct RealWorkspaceTimeoutAttributionConfig {
    pub attribution_id: String,
    #[serde(default)]
    pub sprint92_bundle_paths: Vec<String>,
    #[serde(default)]
    pub krx_warning_closure_paths: Vec<String>,
    #[serde(default)]
    pub previous_no_run_attempt_paths: Vec<String>,
    #[serde(default)]
    pub previous_full_attempt_paths: Vec<String>,
    #[serde(default)]
    pub dashboard_renderer_precheck_paths: Vec<String>,
    #[serde(default)]
    pub cargo_metadata_paths: Vec<String>,
    #[serde(default)]
    pub cargo_message_paths: Vec<String>,
    #[serde(default)]
    pub rustc_process_snapshot_paths: Vec<String>,
    #[serde(default)]
    pub target_dir_snapshot_paths: Vec<String>,
    #[serde(default = "default_sprint93_output_root")]
    pub output_root: String,
    #[serde(default)]
    pub run_diagnostic_no_run: bool,
    #[serde(default)]
    pub run_diagnostic_full: bool,
    #[serde(default)]
    pub diagnostic_timeout_ms: Option<u64>,
    #[serde(default = "default_true")]
    pub capture_cargo_json_messages: bool,
    #[serde(default = "default_true")]
    pub capture_rustc_process_snapshots: bool,
    #[serde(default = "default_true")]
    pub capture_target_dir_growth: bool,
    #[serde(default = "default_true")]
    pub require_krx_non_primary_proof_for_dashboard_entry: bool,
    #[serde(default = "default_true")]
    pub preserve_safety_guards: bool,
    #[serde(default = "default_true")]
    pub preserve_krx_isolated_sentinel: bool,
    #[serde(default = "default_sprint76_reason_codes")]
    pub reason_codes: Vec<ReasonCode>,
}

impl Default for RealWorkspaceTimeoutAttributionConfig {
    fn default() -> Self {
        Self {
            attribution_id: "sprint93-timeout-attribution".to_string(),
            sprint92_bundle_paths: Vec::new(),
            krx_warning_closure_paths: Vec::new(),
            previous_no_run_attempt_paths: Vec::new(),
            previous_full_attempt_paths: Vec::new(),
            dashboard_renderer_precheck_paths: Vec::new(),
            cargo_metadata_paths: Vec::new(),
            cargo_message_paths: Vec::new(),
            rustc_process_snapshot_paths: Vec::new(),
            target_dir_snapshot_paths: Vec::new(),
            output_root: default_sprint93_output_root(),
            run_diagnostic_no_run: false,
            run_diagnostic_full: false,
            diagnostic_timeout_ms: None,
            capture_cargo_json_messages: true,
            capture_rustc_process_snapshots: true,
            capture_target_dir_growth: true,
            require_krx_non_primary_proof_for_dashboard_entry: true,
            preserve_safety_guards: true,
            preserve_krx_isolated_sentinel: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl RealWorkspaceTimeoutAttributionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.attribution_id.trim().is_empty() {
            return Err(
                "real workspace timeout attribution config requires attribution_id".to_string(),
            );
        }
        for path in self
            .sprint92_bundle_paths
            .iter()
            .chain(self.krx_warning_closure_paths.iter())
            .chain(self.previous_no_run_attempt_paths.iter())
            .chain(self.previous_full_attempt_paths.iter())
            .chain(self.dashboard_renderer_precheck_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_message_paths.iter())
            .chain(self.rustc_process_snapshot_paths.iter())
            .chain(self.target_dir_snapshot_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if !path_is_local(path) {
                return Err(format!(
                    "real workspace timeout attribution paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.attribution_id)
    }
}

