#[derive(Clone, Debug, Default)]
pub struct Sprint93TimeoutAttributionRunner;

fn default_sprint93_output_root() -> String {
    "target/soma_sprint93_timeout_attribution".to_string()
}

fn sprint93_reason_codes(extra: &[ReasonCode]) -> Vec<ReasonCode> {
    sprint92_reason_codes(extra)
}

fn sprint93_read_text(path: &str) -> Result<String, String> {
    fs::read_to_string(sprint76_absolutize(path)).map_err(|err| err.to_string())
}

fn sprint93_load_bundle_dir(root: &Path, loaded: &mut Sprint93LoadedInputs) -> Result<(), String> {
    let bundle_files = [
        "dashboard_renderer_readiness_precheck.txt",
        "dashboard_renderer_entry_gate.txt",
        "real_no_run_gate_attempt_v7.txt",
        "real_full_workspace_gate_attempt_v10.txt",
        "remaining_blocker_queue_v8.txt",
        "safety_coverage_preservation_v8.txt",
        "krx_evidence_warning_closure.txt",
        "sprint92_summary.json",
        "no_run_diagnostic_messages_sample.json",
        "full_diagnostic_messages_sample.json",
        "rustc_process_snapshots_sample.json",
        "target_dir_growth_sample.json",
    ];
    for name in bundle_files {
        let path = root.join(name);
        if !path.exists() {
            continue;
        }
        let text = fs::read_to_string(&path).map_err(|err| err.to_string())?;
        match name {
            "dashboard_renderer_readiness_precheck.txt" => {
                loaded.previous_precheck =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "dashboard_renderer_entry_gate.txt" => {
                loaded.previous_entry =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_no_run_gate_attempt_v7.txt" => {
                loaded.previous_no_run =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_full_workspace_gate_attempt_v10.txt" => {
                loaded.previous_full =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "remaining_blocker_queue_v8.txt" => {
                loaded.previous_remaining_queue =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "safety_coverage_preservation_v8.txt" => {
                loaded.previous_safety =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "krx_evidence_warning_closure.txt" => {
                loaded.previous_warning_closure =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "sprint92_summary.json" => {
                loaded.summary = Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "no_run_diagnostic_messages_sample.json" => {
                loaded.no_run_capture =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "full_diagnostic_messages_sample.json" => {
                loaded.full_capture =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "rustc_process_snapshots_sample.json" => {
                loaded.rustc_snapshots =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "target_dir_growth_sample.json" => {
                loaded.target_dir_growth =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            _ => {}
        }
    }
    Ok(())
}

fn sprint93_parse_precheck_status(value: &str) -> DashboardRendererReadinessPrecheckStatus {
    match value {
        "DashboardRendererPrecheckReady" => {
            DashboardRendererReadinessPrecheckStatus::DashboardRendererPrecheckReady
        }
        "DashboardRendererPrecheckBlocked" => {
            DashboardRendererReadinessPrecheckStatus::DashboardRendererPrecheckBlocked
        }
        "DiagnosticOnly" => DashboardRendererReadinessPrecheckStatus::DiagnosticOnly,
        _ => DashboardRendererReadinessPrecheckStatus::DashboardRendererPrecheckReadyWithWarnings,
    }
}

fn sprint93_parse_no_run_status(value: &str) -> RealNoRunGateAttemptV8Status {
    sprint92_parse_no_run_status(value)
}

fn sprint93_parse_full_status(value: &str) -> RealFullWorkspaceGateAttemptV11Status {
    sprint92_parse_full_status(value)
}

