fn sprint93_infer_timeout_status(
    timeout_ms: Option<u64>,
    krx: &[String],
    non_krx: &[String],
) -> WorkspaceTimeoutAttributionStatus {
    if timeout_ms.unwrap_or_default() == 0 {
        WorkspaceTimeoutAttributionStatus::NotRun
    } else if !non_krx.is_empty() {
        WorkspaceTimeoutAttributionStatus::TimeoutAttributedToNonKrx
    } else if !krx.is_empty() {
        WorkspaceTimeoutAttributionStatus::TimeoutAttributedToKrx
    } else {
        WorkspaceTimeoutAttributionStatus::TimeoutStillUnknown
    }
}

fn sprint93_message_target(record: &Sprint93CargoMessageRecord) -> Option<String> {
    record
        .target_name
        .clone()
        .filter(|value| !value.trim().is_empty())
}

fn sprint93_message_package(record: &Sprint93CargoMessageRecord) -> Option<String> {
    record
        .package_name
        .clone()
        .or_else(|| record.crate_name.clone())
        .filter(|value| !value.trim().is_empty())
}

fn sprint93_last_unique_strings(values: Vec<String>, limit: usize) -> Vec<String> {
    let mut seen = BTreeSet::new();
    let mut collected = Vec::new();
    for value in values.into_iter().rev() {
        if value.trim().is_empty() || !seen.insert(value.clone()) {
            continue;
        }
        collected.push(value);
        if collected.len() == limit {
            break;
        }
    }
    collected.reverse();
    collected
}

fn sprint93_family_from_strings(
    explicit: Option<&str>,
    target_name: Option<&str>,
    package_name: Option<&str>,
) -> CargoTargetProgressFamily {
    if let Some(explicit) = explicit {
        match explicit {
            "KrxEvidence" | "krx" | "krx-evidence" => {
                return CargoTargetProgressFamily::KrxEvidence;
            }
            "DashboardRenderer" | "dashboard" | "dashboard-renderer" => {
                return CargoTargetProgressFamily::DashboardRenderer;
            }
            "CommitteeCliSafety" | "committee-cli-safety" => {
                return CargoTargetProgressFamily::CommitteeCliSafety;
            }
            "BaselineSignal" | "baseline-signal" => {
                return CargoTargetProgressFamily::BaselineSignal;
            }
            "CounterfactualBackfill" | "counterfactual-backfill" => {
                return CargoTargetProgressFamily::CounterfactualBackfill;
            }
            "Other" | "other" => return CargoTargetProgressFamily::Other,
            _ => {}
        }
    }
    let haystack = format!(
        "{} {}",
        target_name.unwrap_or_default().to_ascii_lowercase(),
        package_name.unwrap_or_default().to_ascii_lowercase()
    );
    if haystack.trim().is_empty() {
        CargoTargetProgressFamily::Unknown
    } else if haystack.contains("krx") {
        CargoTargetProgressFamily::KrxEvidence
    } else if haystack.contains("dashboard") {
        CargoTargetProgressFamily::DashboardRenderer
    } else if haystack.contains("committee") && haystack.contains("cli") {
        CargoTargetProgressFamily::CommitteeCliSafety
    } else if haystack.contains("baseline") {
        CargoTargetProgressFamily::BaselineSignal
    } else if haystack.contains("counterfactual") {
        CargoTargetProgressFamily::CounterfactualBackfill
    } else {
        CargoTargetProgressFamily::Other
    }
}

fn sprint93_redact_secret_like_text(text: &str) -> String {
    text.split_whitespace()
        .map(|token| {
            let lower = token.to_ascii_lowercase();
            if (lower.contains("api_key=")
                || lower.contains("secret=")
                || lower.contains("token=")
                || lower.contains("password="))
                && !lower.contains("redacted")
            {
                let key = token.split('=').next().unwrap_or(token);
                format!("{}=[REDACTED]", key)
            } else {
                token.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

fn sprint93_secret_free_text(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    !lower.contains("api_key=")
        && !lower.contains("secret=")
        && !lower.contains("token=")
        && !lower.contains("password=")
        && !lower.contains("approval_key=")
}

fn load_sprint93_inputs(
    config: &RealWorkspaceTimeoutAttributionConfig,
) -> Result<Sprint93Inputs, String> {
    let mut loaded = Sprint93LoadedInputs::default();
    for path in config
        .sprint92_bundle_paths
        .iter()
        .chain(config.krx_warning_closure_paths.iter())
        .chain(config.previous_no_run_attempt_paths.iter())
        .chain(config.previous_full_attempt_paths.iter())
        .chain(config.dashboard_renderer_precheck_paths.iter())
        .chain(config.cargo_metadata_paths.iter())
        .chain(config.cargo_message_paths.iter())
        .chain(config.rustc_process_snapshot_paths.iter())
        .chain(config.target_dir_snapshot_paths.iter())
    {
        let absolute = sprint76_absolutize(path);
        if absolute.is_dir() {
            sprint93_load_bundle_dir(&absolute, &mut loaded)?;
            continue;
        }
        match sprint89_file_name(path) {
            "sprint92_summary.json" => loaded.summary = Some(load_json_file(path)?),
            "real_no_run_gate_attempt_v7.txt" => {
                loaded.previous_no_run = Some(load_json_file(path)?)
            }
            "real_full_workspace_gate_attempt_v10.txt" => {
                loaded.previous_full = Some(load_json_file(path)?)
            }
            "dashboard_renderer_readiness_precheck.txt" => {
                loaded.previous_precheck = Some(load_json_file(path)?)
            }
            "dashboard_renderer_entry_gate.txt" => {
                loaded.previous_entry = Some(load_json_file(path)?)
            }
            "remaining_blocker_queue_v8.txt" => {
                loaded.previous_remaining_queue = Some(load_json_file(path)?)
            }
            "safety_coverage_preservation_v8.txt" => {
                loaded.previous_safety = Some(load_json_file(path)?)
            }
            "krx_evidence_warning_closure.txt" => {
                loaded.previous_warning_closure = Some(load_json_file(path)?)
            }
            "no_run_diagnostic_messages_sample.json" => {
                loaded.no_run_capture = Some(load_json_file(path)?)
            }
            "full_diagnostic_messages_sample.json" => {
                loaded.full_capture = Some(load_json_file(path)?)
            }
            "rustc_process_snapshots_sample.json" => {
                loaded.rustc_snapshots = Some(load_json_file(path)?)
            }
            "target_dir_growth_sample.json" => {
                loaded.target_dir_growth = Some(load_json_file(path)?)
            }
            _ => {}
        }
    }

    let summary = loaded.summary.ok_or_else(|| {
        "missing sprint92_summary.json for sprint93 timeout attribution".to_string()
    })?;
    let previous_no_run = loaded
        .previous_no_run
        .unwrap_or_else(|| sprint93_default_previous_no_run(config, &summary));
    let previous_full = loaded
        .previous_full
        .unwrap_or_else(|| sprint93_default_previous_full(config, &summary));
    let previous_precheck = loaded
        .previous_precheck
        .unwrap_or_else(|| sprint93_default_previous_precheck(config, &summary));
    let previous_entry = loaded
        .previous_entry
        .unwrap_or_else(|| sprint93_default_previous_entry(config, &summary));
    let previous_remaining_queue = loaded
        .previous_remaining_queue
        .unwrap_or_else(|| sprint93_default_previous_remaining_queue(config, &summary));
    let previous_safety = loaded
        .previous_safety
        .unwrap_or_else(|| sprint93_default_previous_safety(config));
    let _previous_warning_closure = loaded
        .previous_warning_closure
        .unwrap_or_else(|| sprint93_default_previous_warning_closure(config, &summary));

    Ok(Sprint93Inputs {
        summary,
        previous_no_run_status: previous_no_run.no_run_status,
        previous_full_status: previous_full.full_status,
        previous_precheck,
        previous_entry,
        previous_remaining_queue,
        previous_safety,
        no_run_capture: loaded.no_run_capture,
        full_capture: loaded.full_capture,
        rustc_snapshots: loaded.rustc_snapshots,
        target_dir_growth: loaded.target_dir_growth,
        raw_archive_text: sprint93_read_text("tests/krx_raw_archive_secret_safety.rs")?,
        dashboard_renderer_text: sprint93_read_text("src/ui/dashboard_renderer.rs")?,
        workspace_cli_safety_text: sprint93_read_text("tests/workspace_cli_safety_suite.rs")?,
    })
}

fn build_real_no_run_diagnostic_pass_report(
    config: &RealWorkspaceTimeoutAttributionConfig,
    capture: Option<&Sprint93CargoDiagnosticCapture>,
) -> RealNoRunDiagnosticPassReport {
    let command = capture
        .and_then(|capture| (!capture.command.is_empty()).then(|| capture.command.clone()))
        .unwrap_or_else(|| "cargo test --workspace --no-run --message-format=json".to_string());
    let captured_targets = capture
        .map(|capture| {
            stable_ordered_strings(
                &capture
                    .messages
                    .iter()
                    .filter_map(sprint93_message_target)
                    .collect::<Vec<_>>(),
            )
        })
        .unwrap_or_default();
    let last_seen_targets = capture
        .map(|capture| {
            sprint93_last_unique_strings(
                capture
                    .messages
                    .iter()
                    .filter_map(sprint93_message_target)
                    .collect(),
                3,
            )
        })
        .unwrap_or_default();
    let last_seen_crates = capture
        .map(|capture| {
            sprint93_last_unique_strings(
                capture
                    .messages
                    .iter()
                    .filter_map(sprint93_message_package)
                    .collect(),
                3,
            )
        })
        .unwrap_or_default();
    let status = match capture {
        Some(capture) if capture.finished && capture.passed == Some(true) => {
            RealNoRunDiagnosticPassStatus::DiagnosticNoRunPassed
        }
        Some(capture) if capture.finished && capture.passed == Some(false) => {
            RealNoRunDiagnosticPassStatus::DiagnosticNoRunFailed
        }
        Some(_) => RealNoRunDiagnosticPassStatus::DiagnosticNoRunStillBlocked,
        None => RealNoRunDiagnosticPassStatus::NotRun,
    };
    RealNoRunDiagnosticPassReport {
        report_id: format!("{}-diagnostic-no-run", config.attribution_id),
        command,
        message_format: "json".to_string(),
        started: capture.map(|capture| capture.started).unwrap_or(false),
        finished: capture.map(|capture| capture.finished).unwrap_or(false),
        passed: capture.and_then(|capture| capture.passed),
        duration_ms: capture.and_then(|capture| capture.duration_ms),
        captured_targets,
        last_seen_targets,
        last_seen_crates,
        timeout_ms: capture
            .and_then(|capture| capture.timeout_ms)
            .or(config.diagnostic_timeout_ms),
        status,
        reason_codes: sprint93_reason_codes(&[]),
    }
}

