impl Default for DashboardRendererRealReductionConfig {
    fn default() -> Self {
        Self {
            reduction_id: "sprint94-dashboard-renderer-recovery".to_string(),
            sprint93_bundle_paths: vec![
                "target/soma_sprint93_timeout_attribution/sprint93-timeout-attribution".to_string(),
                "examples/sprint94_data/sprint93_summary.json".to_string(),
            ],
            dashboard_renderer_suite_paths: default_sprint94_suite_paths(),
            dashboard_renderer_paths: default_sprint94_dashboard_paths(),
            dashboard_snapshot_paths: default_sprint94_snapshot_paths(),
            control_tower_panel_paths: default_sprint94_control_tower_paths(),
            dashboard_secret_redaction_paths: default_sprint94_secret_paths(),
            cargo_metadata_paths: Vec::new(),
            cargo_timings_paths: Vec::new(),
            output_root: default_sprint94_output_root(),
            target_family: default_sprint94_target_family(),
            run_real_no_run_after_reduction: false,
            run_real_full_after_reduction: false,
            preserve_assertions: true,
            preserve_safety_guards: true,
            preserve_static_read_only_checks: true,
            preserve_secret_redaction_checks: true,
            preserve_no_action_controls: true,
            preserve_no_browser_execution: true,
            preserve_determinism_checks: true,
            preserve_no_external_assets: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl DashboardRendererRealReductionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.reduction_id.trim().is_empty() {
            return Err(
                "dashboard renderer real reduction config requires reduction_id".to_string(),
            );
        }
        if self.target_family != "DashboardRenderer" {
            return Err(
                "dashboard renderer real reduction target_family must stay DashboardRenderer"
                    .to_string(),
            );
        }
        for path in self
            .sprint93_bundle_paths
            .iter()
            .chain(self.dashboard_renderer_suite_paths.iter())
            .chain(self.dashboard_renderer_paths.iter())
            .chain(self.dashboard_snapshot_paths.iter())
            .chain(self.control_tower_panel_paths.iter())
            .chain(self.dashboard_secret_redaction_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if !path_is_local(path) {
                return Err(format!(
                    "dashboard renderer real reduction paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.reduction_id)
    }
}

