#[derive(Clone, Debug, Default)]
pub struct Sprint94DashboardRendererRecoveryRunner;

fn sprint94_reason_codes(extra: &[ReasonCode]) -> Vec<ReasonCode> {
    sprint93_reason_codes(extra)
}

fn sprint94_example_path(path: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(path)
}

fn sprint94_relative_path(path: &str) -> String {
    path.strip_prefix(&format!("{}/", env!("CARGO_MANIFEST_DIR")))
        .unwrap_or(path)
        .to_string()
}

fn sprint94_existing_texts(paths: &[String]) -> Result<Vec<(String, String)>, String> {
    let mut collected = Vec::new();
    for path in paths {
        let absolute = sprint76_absolutize(path);
        if !absolute.exists() {
            continue;
        }
        let text = fs::read_to_string(&absolute).map_err(|err| err.to_string())?;
        collected.push((
            sprint94_relative_path(&absolute.display().to_string()),
            text,
        ));
    }
    Ok(collected)
}

fn sprint94_load_bundle_dir(root: &Path, loaded: &mut Sprint94LoadedInputs) -> Result<(), String> {
    let bundle_files = [
        "dashboard_renderer_entry_release.txt",
        "remaining_blocker_queue_v9.txt",
        "real_no_run_gate_attempt_v8.txt",
        "real_full_workspace_gate_attempt_v11.txt",
        "safety_coverage_preservation_v9.txt",
    ];
    for name in bundle_files {
        let path = root.join(name);
        if !path.exists() {
            continue;
        }
        let text = fs::read_to_string(&path).map_err(|err| err.to_string())?;
        match name {
            "dashboard_renderer_entry_release.txt" => {
                loaded.previous_entry_release =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "remaining_blocker_queue_v9.txt" => {
                loaded.previous_remaining_queue =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_no_run_gate_attempt_v8.txt" => {
                loaded.previous_no_run =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_full_workspace_gate_attempt_v11.txt" => {
                loaded.previous_full =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "safety_coverage_preservation_v9.txt" => {
                loaded.previous_safety =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            _ => {}
        }
    }
    Ok(())
}

fn sprint94_load_inputs(
    config: &DashboardRendererRealReductionConfig,
) -> Result<Sprint94LoadedInputs, String> {
    let mut loaded = Sprint94LoadedInputs::default();
    for path in &config.sprint93_bundle_paths {
        let absolute = sprint76_absolutize(path);
        if absolute.is_dir() {
            sprint94_load_bundle_dir(&absolute, &mut loaded)?;
            continue;
        }
        if !absolute.exists() {
            continue;
        }
        let text = fs::read_to_string(&absolute).map_err(|err| err.to_string())?;
        let name = absolute
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or_default();
        match name {
            "sprint93_summary.json" => {
                loaded.summary = Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "dashboard_renderer_entry_release.txt" => {
                loaded.previous_entry_release =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "remaining_blocker_queue_v9.txt" => {
                loaded.previous_remaining_queue =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_no_run_gate_attempt_v8.txt" => {
                loaded.previous_no_run =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_full_workspace_gate_attempt_v11.txt" => {
                loaded.previous_full =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "safety_coverage_preservation_v9.txt" => {
                loaded.previous_safety =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            _ => {}
        }
    }
    for path in config
        .cargo_timings_paths
        .iter()
        .chain(config.cargo_metadata_paths.iter())
    {
        let absolute = sprint76_absolutize(path);
        if !absolute.exists() {
            continue;
        }
        let text = fs::read_to_string(&absolute).map_err(|err| err.to_string())?;
        if let Ok(sample) = serde_json::from_str::<Sprint94CompileImpactSampleInput>(&text) {
            loaded.compile_impact_sample = Some(sample);
            break;
        }
    }
    Ok(loaded)
}

