fn sprint94_render_probe(
    config: &DashboardRendererRealReductionConfig,
) -> Result<Sprint94RenderProbe, String> {
    let mut source = crate::ui::dashboard_state::DashboardSourceConfig::from_toml_path(
        &sprint94_example_path("examples/soma_dashboard_source_kis_control_tower.toml"),
    )?;
    source.output_root = config
        .output_dir()
        .join("render-probe-source")
        .display()
        .to_string();
    let first_state =
        crate::ui::dashboard_snapshot::DashboardSnapshotBuilder::default().build(&source)?;
    let second_state =
        crate::ui::dashboard_snapshot::DashboardSnapshotBuilder::default().build(&source)?;

    let mut render = crate::ui::dashboard_renderer::DashboardRenderConfig::from_toml_path(
        &sprint94_example_path("examples/soma_dashboard_render_static.toml"),
    )?;
    render.output_root = config
        .output_dir()
        .join("render-probe-render")
        .display()
        .to_string();
    let first_report =
        crate::ui::dashboard_renderer::DashboardRenderer::default().render(&render)?;
    let first_html = fs::read_to_string(first_report.html_path.clone().unwrap_or_default())
        .map_err(|err| err.to_string())?;
    let first_json = fs::read_to_string(first_report.json_path.clone().unwrap_or_default())
        .map_err(|err| err.to_string())?;
    let first_text = fs::read_to_string(first_report.text_path.clone().unwrap_or_default())
        .map_err(|err| err.to_string())?;

    let second_report =
        crate::ui::dashboard_renderer::DashboardRenderer::default().render(&render)?;
    let second_html = fs::read_to_string(second_report.html_path.clone().unwrap_or_default())
        .map_err(|err| err.to_string())?;
    let second_json = fs::read_to_string(second_report.json_path.clone().unwrap_or_default())
        .map_err(|err| err.to_string())?;
    let second_text = fs::read_to_string(second_report.text_path.clone().unwrap_or_default())
        .map_err(|err| err.to_string())?;

    Ok(Sprint94RenderProbe {
        first_state_json: first_state.to_json_string()?,
        second_state_json: second_state.to_json_string()?,
        first_fingerprint: first_state.fingerprint.clone(),
        second_fingerprint: second_state.fingerprint.clone(),
        html_first: first_html,
        html_second: second_html,
        json_first: first_json,
        json_second: second_json,
        text_first: first_text,
        text_second: second_text,
    })
}

fn sprint94_secret_probe(
    config: &DashboardRendererRealReductionConfig,
) -> Result<Sprint94SecretProbe, String> {
    let mut state = crate::ui::dashboard_state::DashboardState::default();
    state.dashboard_id = "sprint94-secret-dashboard".to_string();
    state.provider_panel = crate::ui::dashboard_panels::ProviderPanel::default();
    state.provider_panel.kis_status.endpoint_policy_status =
        "https://example.kis.local/path?token=abc123".to_string();
    state.warnings = vec![
        "KIS_APP_KEY=secret-value".to_string(),
        "KIS_APP_SECRET=top-secret-value".to_string(),
        "KIS_WS_APPROVAL_KEY=approval-secret".to_string(),
        "KRX_API_KEY=krx-secret".to_string(),
        "KIS_BASE_URL=https://example.kis.local/path?token=abc123".to_string(),
        "password=hunter2".to_string(),
    ];
    state = state.with_fingerprint();
    let (redacted_state, redaction_report) =
        crate::ui::dashboard_secret_redaction::redact_dashboard_state(&state)?;
    let probe_dir = config.output_dir().join("secret-probe");
    fs::create_dir_all(&probe_dir).map_err(|err| err.to_string())?;
    let state_path = probe_dir.join("redacted_dashboard_state.json");
    fs::write(&state_path, redacted_state.to_json_string()?).map_err(|err| err.to_string())?;
    let render = crate::ui::dashboard_renderer::DashboardRenderConfig {
        dashboard_id: "sprint94-secret-dashboard".to_string(),
        dashboard_state_path: Some(state_path.display().to_string()),
        output_root: probe_dir.display().to_string(),
        ..crate::ui::dashboard_renderer::DashboardRenderConfig::default()
    };
    let report = crate::ui::dashboard_renderer::DashboardRenderer::default().render(&render)?;
    Ok(Sprint94SecretProbe {
        html: fs::read_to_string(report.html_path.unwrap_or_default())
            .map_err(|err| err.to_string())?,
        json: fs::read_to_string(report.json_path.unwrap_or_default())
            .map_err(|err| err.to_string())?,
        text: fs::read_to_string(report.text_path.unwrap_or_default())
            .map_err(|err| err.to_string())?,
        redaction_report,
    })
}

fn sprint94_no_secret_like_values(text: &str) -> bool {
    let lowercase = text.to_ascii_lowercase();
    ![
        "secret-value",
        "top-secret-value",
        "approval-secret",
        "krx-secret",
        "hunter2",
        "abc123",
        "token=",
        "password=",
    ]
    .iter()
    .any(|needle| lowercase.contains(needle))
}

fn sprint94_contains_any(text: &str, values: &[&str]) -> bool {
    values.iter().any(|value| text.contains(value))
}

fn sprint94_build_plan(
    config: &DashboardRendererRealReductionConfig,
    suite_texts: &[(String, String)],
    previous_entry: &DashboardRendererEntryReleaseReport,
) -> DashboardRendererRealReductionPlan {
    let suite_blob = suite_texts
        .iter()
        .map(|(_, text)| text.as_str())
        .collect::<Vec<_>>()
        .join("\n");
    let mut actions = BTreeSet::from([
        DashboardRendererRealReductionAction::VerifyGroupedSuiteCoverage,
        DashboardRendererRealReductionAction::MoveRemainingAssertions,
        DashboardRendererRealReductionAction::ApplySharedFixtureHarness,
        DashboardRendererRealReductionAction::ReduceDashboardStateFixtureDuplication,
        DashboardRendererRealReductionAction::ReduceHtmlGoldenDuplication,
        DashboardRendererRealReductionAction::ReduceJsonTxtGoldenDuplication,
        DashboardRendererRealReductionAction::ConsolidateSecretRedactionFixture,
        DashboardRendererRealReductionAction::KeepSeparateForIsolation,
    ]);
    if suite_blob.contains("sprint52_output_dir") {
        actions.insert(DashboardRendererRealReductionAction::RemoveDuplicateSetupOnly);
    }
    let target_files = if config.dashboard_renderer_suite_paths.is_empty() {
        default_sprint94_suite_paths()
    } else {
        config
            .dashboard_renderer_suite_paths
            .iter()
            .map(|path| sprint94_relative_path(path))
            .collect()
    };
    let plan_status = if previous_entry.current_entry_status == "DashboardRendererEntryReleased"
        && suite_blob.contains("dashboard_snapshot_writes_artifacts_and_enforces_limits")
    {
        DashboardRendererRealReductionPlanStatus::DashboardReductionPlanReady
    } else {
        DashboardRendererRealReductionPlanStatus::NeedManualReview
    };
    DashboardRendererRealReductionPlan {
        plan_id: format!("{}-plan", config.reduction_id),
        target_files,
        donor_files: SPRINT94_ALL_DONOR_FILES.iter().map(|value| value.to_string()).collect(),
        actions: actions.into_iter().collect(),
        assertions_to_preserve: vec![
            "static local renderer outputs without action controls".to_string(),
            "dashboard snapshot artifact generation limits".to_string(),
            "dashboard config remote rejection and no broker/order/account fields".to_string(),
            "missing reports stay reason-coded instead of fatal".to_string(),
            "research-only dashboard state with deterministic fingerprint".to_string(),
            "provider/evidence/committee/chair/risk panel invariants".to_string(),
            "secret-state redaction isolation".to_string(),
            "redaction report determinism isolation".to_string(),
        ],
        safety_guards_to_preserve: vec![
            "static read-only html".to_string(),
            "local-only output paths".to_string(),
            "paper/research-only labels".to_string(),
            "secret redaction across html/json/txt".to_string(),
            "no browser execution".to_string(),
            "no order/account/trade controls".to_string(),
            "no external remote assets".to_string(),
            "deterministic rendering".to_string(),
        ],
        dashboard_state_fixture_duplication: vec![
            "dashboard_snapshot.rs duplicated dashboard source config setup".to_string(),
            "dashboard_panels.rs duplicated dashboard snapshot build helper".to_string(),
        ],
        html_golden_duplication: vec![
            "dashboard_v1_renderer.rs duplicated safe static HTML checks already covered by grouped suites"
                .to_string(),
            "dashboard_renderer_suite.rs now carries the owner_action_draft_dir assertion"
                .to_string(),
        ],
        json_txt_golden_duplication: vec![
            "dashboard_snapshot.rs duplicated dashboard_state.json/dashboard_state.txt artifact checks"
                .to_string(),
        ],
        secret_redaction_fixture_duplication: vec![
            "artifact_rendering_suite.rs secret-state fixture remains isolated instead of being duplicated"
                .to_string(),
        ],
        expected_target_delta: Some(-4),
        semantic_risk: DashboardRendererRealReductionSemanticRisk::Low,
        plan_status,
        reason_codes: sprint94_reason_codes(&[]),
    }
}

fn sprint94_build_assertion_migration_report(
    config: &DashboardRendererRealReductionConfig,
    suite_texts: &[(String, String)],
) -> DashboardRendererAssertionMigrationReport {
    let suite_blob = suite_texts
        .iter()
        .map(|(_, text)| text.as_str())
        .collect::<Vec<_>>()
        .join("\n");
    let migrated = SPRINT94_MIGRATED_ASSERTIONS
        .iter()
        .filter(|(_, pattern)| suite_blob.contains(pattern))
        .count();
    let kept_separate = SPRINT94_HIGH_RISK_ASSERTIONS
        .iter()
        .map(|(file, test, reason)| format!("{file}::{test} => {reason}"))
        .collect::<Vec<_>>();
    let assertions_found = SPRINT94_MIGRATED_ASSERTIONS.len() + SPRINT94_HIGH_RISK_ASSERTIONS.len();
    let assertions_remaining = SPRINT94_HIGH_RISK_ASSERTIONS.len();
    let migration_status = if migrated == SPRINT94_MIGRATED_ASSERTIONS.len() {
        if assertions_remaining == 0 {
            DashboardRendererAssertionMigrationStatus::AssertionsMigrated
        } else {
            DashboardRendererAssertionMigrationStatus::AssertionsMigratedWithWarnings
        }
    } else if migrated == 0 {
        DashboardRendererAssertionMigrationStatus::NeedManualReview
    } else {
        DashboardRendererAssertionMigrationStatus::AssertionsRemaining
    };
    DashboardRendererAssertionMigrationReport {
        report_id: format!("{}-assertion-migration", config.reduction_id),
        donor_files: SPRINT94_ALL_DONOR_FILES
            .iter()
            .map(|value| value.to_string())
            .collect(),
        target_suites: config
            .dashboard_renderer_suite_paths
            .iter()
            .map(|path| sprint94_relative_path(path))
            .collect(),
        assertions_found,
        assertions_migrated: migrated,
        assertions_remaining,
        high_risk_assertions_kept_separate: kept_separate,
        migration_status,
        reason_codes: sprint94_reason_codes(&[]),
    }
}

