fn sprint94_build_static_safety_report(
    config: &DashboardRendererRealReductionConfig,
    probe: &Sprint94RenderProbe,
) -> DashboardRendererStaticSafetyPreservationReport {
    let static_html_preserved = probe.html_first.contains("Read-only local dashboard")
        && !probe.html_first.contains("<script");
    let local_only_output_preserved = path_is_local(&config.output_root);
    let read_only_semantics_preserved = probe.html_first.contains("No broker, order, account");
    let copy_only_commands_preserved = !sprint94_contains_any(
        &probe.html_first,
        &["<form", "POST", "<button", "onclick=", "onsubmit="],
    );
    let paper_only_labels_preserved =
        probe.html_first.contains("Paper approved") && probe.first_state_json.contains("Research");
    let no_external_remote_assets = !sprint94_contains_any(
        &probe.html_first,
        &["http://", "https://", "cdn", "src=\"//"],
    );
    let static_safety_status = if static_html_preserved
        && local_only_output_preserved
        && read_only_semantics_preserved
        && copy_only_commands_preserved
        && paper_only_labels_preserved
        && no_external_remote_assets
    {
        DashboardRendererStaticSafetyStatus::StaticSafetyPreserved
    } else {
        DashboardRendererStaticSafetyStatus::StaticSafetyRegression
    };
    DashboardRendererStaticSafetyPreservationReport {
        report_id: format!("{}-static-safety", config.reduction_id),
        static_html_preserved,
        local_only_output_preserved,
        read_only_semantics_preserved,
        copy_only_commands_preserved,
        paper_only_labels_preserved,
        no_external_remote_assets,
        static_safety_status,
        reason_codes: sprint94_reason_codes(&[]),
    }
}

fn sprint94_build_secret_redaction_report(
    config: &DashboardRendererRealReductionConfig,
    secret_probe: &Sprint94SecretProbe,
    secret_texts: &[(String, String)],
) -> DashboardRendererSecretRedactionPreservationReport {
    let secret_blob = secret_texts
        .iter()
        .map(|(_, text)| text.to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join("\n");
    let html_secret_redaction_preserved = sprint94_no_secret_like_values(&secret_probe.html);
    let json_secret_redaction_preserved = sprint94_no_secret_like_values(&secret_probe.json);
    let txt_secret_redaction_preserved = sprint94_no_secret_like_values(&secret_probe.text);
    let url_token_redaction_preserved = secret_probe.json.contains("configured(redacted;base_url=")
        && !secret_probe.json.contains("abc123");
    let env_key_name_only_preserved = secret_blob.contains("kis_app_key")
        && secret_blob.contains("krx_api_key")
        && sprint94_no_secret_like_values(&secret_probe.json);
    let no_raw_secret_values = html_secret_redaction_preserved
        && json_secret_redaction_preserved
        && txt_secret_redaction_preserved;
    let diagnostic_logs_secret_free = secret_probe.redaction_report.passed && no_raw_secret_values;
    let redaction_status = if no_raw_secret_values
        && url_token_redaction_preserved
        && env_key_name_only_preserved
        && diagnostic_logs_secret_free
    {
        DashboardRendererSecretRedactionStatus::SecretRedactionPreserved
    } else {
        DashboardRendererSecretRedactionStatus::SecretRedactionRegression
    };
    DashboardRendererSecretRedactionPreservationReport {
        report_id: format!("{}-secret-redaction", config.reduction_id),
        html_secret_redaction_preserved,
        json_secret_redaction_preserved,
        txt_secret_redaction_preserved,
        url_token_redaction_preserved,
        env_key_name_only_preserved,
        no_raw_secret_values,
        diagnostic_logs_secret_free,
        redaction_status,
        reason_codes: sprint94_reason_codes(&[]),
    }
}

fn sprint94_build_no_browser_execution_report(
    config: &DashboardRendererRealReductionConfig,
    probe: &Sprint94RenderProbe,
    control_tower_texts: &[(String, String)],
) -> DashboardRendererNoBrowserExecutionReport {
    let control_blob = control_tower_texts
        .iter()
        .map(|(_, text)| text.to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join("\n");
    let no_dashboard_serve = control_blob.contains("deferredforsafety")
        || control_blob.contains("enable_dashboard_serve");
    let no_browser_execution_controls = !sprint94_contains_any(
        &probe.html_first.to_ascii_lowercase(),
        &["<script", "onclick=", "onsubmit=", "fetch(", "websocket"],
    );
    let no_js_execution_dependency = !control_blob.contains("javascript")
        && !control_blob.contains("wasm-bindgen")
        && !probe.html_first.contains("<script");
    let no_remote_assets = !sprint94_contains_any(
        &probe.html_first,
        &["http://", "https://", "src=\"//", "href=\"//"],
    );
    let no_post_forms =
        !sprint94_contains_any(&probe.html_first, &["<form", "POST", "method=\"post"]);
    let no_event_handlers_for_execution = !sprint94_contains_any(
        &probe.html_first.to_ascii_lowercase(),
        &["onclick", "onchange", "onsubmit", "onload"],
    );
    let browser_status = if no_dashboard_serve
        && no_browser_execution_controls
        && no_js_execution_dependency
        && no_remote_assets
        && no_post_forms
        && no_event_handlers_for_execution
    {
        DashboardRendererNoBrowserExecutionStatus::NoBrowserExecutionPreserved
    } else {
        DashboardRendererNoBrowserExecutionStatus::BrowserExecutionRegression
    };
    DashboardRendererNoBrowserExecutionReport {
        report_id: format!("{}-no-browser", config.reduction_id),
        no_dashboard_serve,
        no_browser_execution_controls,
        no_js_execution_dependency,
        no_remote_assets,
        no_post_forms,
        no_event_handlers_for_execution,
        browser_status,
        reason_codes: sprint94_reason_codes(&[]),
    }
}

