impl Default for CommitteeCliSafetyReductionConfig {
    fn default() -> Self {
        Self {
            reduction_id: "sprint95-committee-cli-safety-recover".to_string(),
            sprint94_bundle_paths: vec![
                "target/soma_sprint94_dashboard_renderer_recovery/sprint94-dashboard-renderer-recover"
                    .to_string(),
                "examples/sprint95_data/sprint94_summary.json".to_string(),
            ],
            committee_cli_safety_paths: default_sprint95_committee_paths(),
            workspace_cli_safety_suite_paths: default_sprint95_workspace_cli_paths(),
            workspace_safety_guard_suite_paths: default_sprint95_workspace_guard_paths(),
            command_surface_manifest_paths: default_sprint95_command_surface_paths(),
            help_text_fixture_paths: default_sprint95_help_text_paths(),
            cargo_metadata_paths: Vec::new(),
            cargo_timings_paths: Vec::new(),
            output_root: default_sprint95_output_root(),
            target_family: default_sprint95_target_family(),
            run_real_no_run_after_reduction: false,
            run_real_full_after_reduction: false,
            preserve_assertions: true,
            preserve_safety_guards: true,
            preserve_remote_path_rejection: true,
            preserve_help_text_checks: true,
            preserve_forbidden_command_checks: true,
            preserve_runtime_deferred_checks: true,
            preserve_persona_expansion_guards: true,
            preserve_order_account_guards: true,
            preserve_browser_execution_guards: true,
            preserve_determinism_checks: true,
            require_isolation_decision: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl CommitteeCliSafetyReductionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.reduction_id.trim().is_empty() {
            return Err("committee cli safety reduction config requires reduction_id".to_string());
        }
        if self.target_family != "CommitteeCliSafety" {
            return Err(
                "committee cli safety reduction target_family must stay CommitteeCliSafety"
                    .to_string(),
            );
        }
        for path in self
            .sprint94_bundle_paths
            .iter()
            .chain(self.committee_cli_safety_paths.iter())
            .chain(self.workspace_cli_safety_suite_paths.iter())
            .chain(self.workspace_safety_guard_suite_paths.iter())
            .chain(self.command_surface_manifest_paths.iter())
            .chain(self.help_text_fixture_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if !path_is_local(path) {
                return Err(format!(
                    "committee cli safety reduction paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.reduction_id)
    }
}

