pub struct Sprint95CommitteeCliSafetyRecoveryRunner;

fn sprint95_reason_codes(extra: &[ReasonCode]) -> Vec<ReasonCode> {
    sprint94_reason_codes(extra)
}

fn sprint95_relative_path(path: &str) -> String {
    path.strip_prefix(&format!("{}/", env!("CARGO_MANIFEST_DIR")))
        .unwrap_or(path)
        .to_string()
}

fn sprint95_existing_texts(paths: &[String]) -> Result<Vec<(String, String)>, String> {
    let mut collected = Vec::new();
    for path in paths {
        let absolute = sprint76_absolutize(path);
        if !absolute.exists() {
            continue;
        }
        let text = fs::read_to_string(&absolute).map_err(|err| err.to_string())?;
        collected.push((
            sprint95_relative_path(&absolute.display().to_string()),
            text,
        ));
    }
    Ok(collected)
}

fn sprint95_text_blob(texts: &[(String, String)]) -> String {
    texts
        .iter()
        .map(|(_, text)| text.as_str())
        .collect::<Vec<_>>()
        .join("\n")
}

