fn sprint95_load_bundle_dir(root: &Path, loaded: &mut Sprint95LoadedInputs) -> Result<(), String> {
    let bundle_files = [
        "remaining_blocker_queue_v10.txt",
        "real_no_run_gate_attempt_v9.txt",
        "real_full_workspace_gate_attempt_v12.txt",
        "workspace_gate_recovery_v11.txt",
        "safety_coverage_preservation_v10.txt",
    ];
    for name in bundle_files {
        let path = root.join(name);
        if !path.exists() {
            continue;
        }
        let text = fs::read_to_string(&path).map_err(|err| err.to_string())?;
        match name {
            "remaining_blocker_queue_v10.txt" => {
                loaded.previous_queue =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "workspace_gate_recovery_v11.txt" => {
                loaded.previous_workspace =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "safety_coverage_preservation_v10.txt" => {
                loaded.previous_safety =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "real_no_run_gate_attempt_v9.txt" => {
                if let Ok(previous) = serde_json::from_str::<RealNoRunGateAttemptV9>(&text) {
                    loaded.previous_no_run = Some(RealNoRunGateAttemptV10 {
                        attempt_id: previous.attempt_id,
                        command: previous.command,
                        started: previous.started,
                        finished: previous.finished,
                        passed: previous.passed,
                        duration_ms: previous.duration_ms,
                        rerun_after_family: previous.rerun_after_family,
                        blocked_families: previous.blocked_families,
                        no_run_status: match previous.no_run_status {
                            RealNoRunGateAttemptV9Status::RealNoRunPassed => {
                                RealNoRunGateAttemptV10Status::RealNoRunPassed
                            }
                            RealNoRunGateAttemptV9Status::RealNoRunStillBlocked => {
                                RealNoRunGateAttemptV10Status::RealNoRunStillBlocked
                            }
                            RealNoRunGateAttemptV9Status::RealNoRunFailed => {
                                RealNoRunGateAttemptV10Status::RealNoRunFailed
                            }
                            RealNoRunGateAttemptV9Status::NotRun => {
                                RealNoRunGateAttemptV10Status::NotRun
                            }
                        },
                        reason_codes: previous.reason_codes,
                    });
                }
            }
            "real_full_workspace_gate_attempt_v12.txt" => {
                if let Ok(previous) = serde_json::from_str::<RealFullWorkspaceGateAttemptV12>(&text)
                {
                    loaded.previous_full = Some(RealFullWorkspaceGateAttemptV13 {
                        attempt_id: previous.attempt_id,
                        command: previous.command,
                        started: previous.started,
                        finished: previous.finished,
                        passed: previous.passed,
                        duration_ms: previous.duration_ms,
                        rerun_after_family: previous.rerun_after_family,
                        blocked_families: previous.blocked_families,
                        full_status: match previous.full_status {
                            RealFullWorkspaceGateAttemptV12Status::FullWorkspaceAccepted => {
                                RealFullWorkspaceGateAttemptV13Status::FullWorkspaceAccepted
                            }
                            RealFullWorkspaceGateAttemptV12Status::FullWorkspaceStillBlocked => {
                                RealFullWorkspaceGateAttemptV13Status::FullWorkspaceStillBlocked
                            }
                            RealFullWorkspaceGateAttemptV12Status::FullWorkspaceFailed => {
                                RealFullWorkspaceGateAttemptV13Status::FullWorkspaceFailed
                            }
                            RealFullWorkspaceGateAttemptV12Status::NotRun => {
                                RealFullWorkspaceGateAttemptV13Status::NotRun
                            }
                        },
                        reason_codes: previous.reason_codes,
                    });
                }
            }
            _ => {}
        }
    }
    Ok(())
}

fn sprint95_load_inputs(
    config: &CommitteeCliSafetyReductionConfig,
) -> Result<Sprint95LoadedInputs, String> {
    let mut loaded = Sprint95LoadedInputs::default();
    for path in &config.sprint94_bundle_paths {
        let absolute = sprint76_absolutize(path);
        if absolute.is_dir() {
            sprint95_load_bundle_dir(&absolute, &mut loaded)?;
            continue;
        }
        if !absolute.exists() {
            continue;
        }
        let text = fs::read_to_string(&absolute).map_err(|err| err.to_string())?;
        let name = absolute
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or_default();
        match name {
            "sprint94_summary.json" => {
                loaded.summary = Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "remaining_blocker_queue_v10.txt" => {
                loaded.previous_queue =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "workspace_gate_recovery_v11.txt" => {
                loaded.previous_workspace =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            "safety_coverage_preservation_v10.txt" => {
                loaded.previous_safety =
                    Some(serde_json::from_str(&text).map_err(|err| err.to_string())?)
            }
            _ => {}
        }
    }
    for path in config
        .cargo_timings_paths
        .iter()
        .chain(config.cargo_metadata_paths.iter())
    {
        let absolute = sprint76_absolutize(path);
        if !absolute.exists() {
            continue;
        }
        let text = fs::read_to_string(&absolute).map_err(|err| err.to_string())?;
        if let Ok(sample) = serde_json::from_str::<Sprint95CompileImpactSampleInput>(&text) {
            loaded.compile_impact_sample = Some(sample);
            break;
        }
    }
    Ok(loaded)
}

fn sprint95_build_plan(
    config: &CommitteeCliSafetyReductionConfig,
    previous_queue: &RemainingBlockerQueueV10,
) -> CommitteeCliSafetyReductionPlan {
    let mut actions = BTreeSet::from([
        CommitteeCliSafetyReductionAction::VerifyWorkspaceCliSafetySuiteCoverage,
        CommitteeCliSafetyReductionAction::VerifyWorkspaceSafetyGuardSuiteCoverage,
        CommitteeCliSafetyReductionAction::KeepIsolatedSentinel,
        CommitteeCliSafetyReductionAction::SplitHighRiskCliSafety,
        CommitteeCliSafetyReductionAction::ApplySharedFixtureHarness,
        CommitteeCliSafetyReductionAction::ReduceHelpTextFixtureDuplication,
        CommitteeCliSafetyReductionAction::ReduceCommandSurfaceFixtureDuplication,
    ]);
    if !config.committee_cli_safety_paths.is_empty() {
        actions.insert(CommitteeCliSafetyReductionAction::MoveRemainingAssertions);
    }
    let plan_status = if previous_queue.primary_next_family == "CommitteeCliSafety"
        && config
            .workspace_cli_safety_suite_paths
            .iter()
            .any(|path| path.ends_with("workspace_cli_safety_suite.rs"))
        && config
            .workspace_safety_guard_suite_paths
            .iter()
            .any(|path| path.ends_with("workspace_safety_guard_suite.rs"))
    {
        CommitteeCliSafetyReductionPlanStatus::CommitteeCliSafetyPlanReady
    } else {
        CommitteeCliSafetyReductionPlanStatus::NeedManualReview
    };
    CommitteeCliSafetyReductionPlan {
        plan_id: format!("{}-plan", config.reduction_id),
        target_files: config
            .workspace_cli_safety_suite_paths
            .iter()
            .chain(config.workspace_safety_guard_suite_paths.iter())
            .map(|path| sprint95_relative_path(path))
            .collect(),
        donor_files: SPRINT95_ALL_DONOR_FILES
            .iter()
            .map(|value| value.to_string())
            .collect(),
        actions: actions.into_iter().collect(),
        assertions_to_preserve: vec![
            "committee help stays research-only/local-only and deterministic".to_string(),
            "committee remote config paths remain rejected".to_string(),
            "forbidden train/runtime/live/order/account/broker/browser commands stay absent"
                .to_string(),
            "runtime-deferred semantics remain unchanged".to_string(),
            "exactly three active personas remain enforced".to_string(),
            "Risk Governor remains absolute veto for chair/persona flow".to_string(),
            "dedicated committee smoke CLI execution sentinel remains isolated".to_string(),
        ],
        safety_guards_to_preserve: vec![
            "remote path rejection".to_string(),
            "research-only and paper-only help text".to_string(),
            "forbidden command absence".to_string(),
            "runtime deferred".to_string(),
            "persona expansion guard".to_string(),
            "order/account guard".to_string(),
            "browser execution guard".to_string(),
            "deterministic CLI surface".to_string(),
        ],
        high_risk_cli_safety_assertions: SPRINT95_HIGH_RISK_ASSERTIONS
            .iter()
            .map(|(file, test, reason)| format!("{file}::{test} => {reason}"))
            .collect(),
        remote_path_fixture_duplication: vec![
            "committee_cli_safety.rs and workspace_cli_safety_suite.rs both assert remote config rejection"
                .to_string(),
        ],
        help_text_fixture_duplication: vec![
            "committee_cli_safety.rs and sprint95_cli_safety.rs both pin research-only help wording"
                .to_string(),
        ],
        command_surface_fixture_duplication: vec![
            "workspace_cli_safety_suite.rs and sprint95_cli_safety.rs both pin forbidden root help surface"
                .to_string(),
        ],
        expected_target_delta: Some(0),
        semantic_risk: CommitteeCliSafetyReductionSemanticRisk::High,
        plan_status,
        reason_codes: sprint95_reason_codes(&[]),
    }
}

fn sprint95_build_isolation_decision(
    config: &CommitteeCliSafetyReductionConfig,
    suite_blob: &str,
) -> CommitteeCliSafetyIsolationDecision {
    let represented_assertion_count = SPRINT95_REPRESENTED_ASSERTIONS
        .iter()
        .filter(|(_, _, representation)| suite_blob.contains(representation))
        .count();
    let remaining_isolated_assertion_count = SPRINT95_HIGH_RISK_ASSERTIONS.len();
    let decision_status = if config.require_isolation_decision {
        CommitteeCliSafetyIsolationDecisionStatus::KeepPermanentIsolatedSentinel
    } else {
        CommitteeCliSafetyIsolationDecisionStatus::UnsafeToMerge
    };
    CommitteeCliSafetyIsolationDecision {
        decision_id: format!("{}-isolation-decision", config.reduction_id),
        current_isolation_status: "CommitteeCliSafety remains isolated from Sprint 94".to_string(),
        decision_status,
        isolation_reason:
            "grouped suites represent broad CLI safety guarantees, but committee-smoke execution remains a permanent isolated sentinel"
                .to_string(),
        merged_assertion_count: 0,
        represented_assertion_count,
        remaining_isolated_assertion_count,
        high_risk_assertion_count: SPRINT95_HIGH_RISK_ASSERTIONS.len(),
        safety_risk: CommitteeCliSafetyIsolationSafetyRisk::High,
        reason_codes: sprint95_reason_codes(&[]),
    }
}

fn sprint95_build_assertion_migration_report(
    config: &CommitteeCliSafetyReductionConfig,
    suite_blob: &str,
) -> CommitteeCliSafetyAssertionMigrationReport {
    let assertions_represented = SPRINT95_REPRESENTED_ASSERTIONS
        .iter()
        .filter(|(_, _, representation)| suite_blob.contains(representation))
        .count();
    let assertions_found =
        SPRINT95_REPRESENTED_ASSERTIONS.len() + SPRINT95_HIGH_RISK_ASSERTIONS.len();
    let assertions_remaining_isolated = SPRINT95_HIGH_RISK_ASSERTIONS.len();
    let assertions_remaining_uncovered =
        assertions_found.saturating_sub(assertions_represented + assertions_remaining_isolated);
    let migration_status = if assertions_represented > 0 && assertions_remaining_uncovered == 0 {
        CommitteeCliSafetyAssertionMigrationStatus::AssertionsRepresentedWithIsolatedSentinel
    } else if assertions_represented > 0 {
        CommitteeCliSafetyAssertionMigrationStatus::AssertionsRemaining
    } else {
        CommitteeCliSafetyAssertionMigrationStatus::NeedManualReview
    };
    CommitteeCliSafetyAssertionMigrationReport {
        report_id: format!("{}-assertion-migration", config.reduction_id),
        donor_files: SPRINT95_ALL_DONOR_FILES
            .iter()
            .map(|value| value.to_string())
            .collect(),
        target_suites: config
            .workspace_cli_safety_suite_paths
            .iter()
            .chain(config.workspace_safety_guard_suite_paths.iter())
            .map(|path| sprint95_relative_path(path))
            .collect(),
        assertions_found,
        assertions_migrated: 0,
        assertions_represented,
        assertions_remaining_isolated,
        assertions_remaining_uncovered,
        high_risk_assertions_kept_separate: SPRINT95_HIGH_RISK_ASSERTIONS
            .iter()
            .map(|(file, test, reason)| format!("{file}::{test} => {reason}"))
            .collect(),
        migration_status,
        reason_codes: sprint95_reason_codes(&[]),
    }
}

