fn sprint95_build_remote_path_report(
    config: &CommitteeCliSafetyReductionConfig,
    suite_blob: &str,
    command_blob: &str,
) -> CommitteeCliSafetyRemotePathPreservationReport {
    let remote_config_rejection_preserved =
        suite_blob.contains("config path must be local") && config.preserve_remote_path_rejection;
    let remote_data_path_rejection_preserved = remote_config_rejection_preserved;
    let remote_output_path_rejection_preserved = config.validate().is_ok();
    let url_like_path_rejection_preserved = !path_is_local("https://example.com/config.toml")
        && !path_is_local("http://example.com/config.toml");
    let local_only_message_preserved = command_blob.contains("local-only")
        || command_blob.contains("Research-only local experiment harness");
    let remote_path_status = if remote_config_rejection_preserved
        && remote_data_path_rejection_preserved
        && remote_output_path_rejection_preserved
        && url_like_path_rejection_preserved
        && local_only_message_preserved
    {
        CommitteeCliSafetyRemotePathStatus::RemotePathRejectionPreserved
    } else {
        CommitteeCliSafetyRemotePathStatus::RemotePathRegression
    };
    CommitteeCliSafetyRemotePathPreservationReport {
        report_id: format!("{}-remote-path", config.reduction_id),
        remote_config_rejection_preserved,
        remote_data_path_rejection_preserved,
        remote_output_path_rejection_preserved,
        url_like_path_rejection_preserved,
        local_only_message_preserved,
        remote_path_status,
        reason_codes: sprint95_reason_codes(&[]),
    }
}

