fn sprint95_build_persona_guard_report(
    config: &CommitteeCliSafetyReductionConfig,
    help_blob: &str,
    guard_blob: &str,
) -> CommitteeCliSafetyPersonaExpansionGuardReport {
    let help_lower = help_blob.to_ascii_lowercase();
    let active = crate::league::persona_card_lite::active_persona_cards_lite();
    let ids = active
        .iter()
        .map(|card| card.persona_id.as_str())
        .collect::<Vec<_>>();
    let exactly_three_active_personas_preserved = ids
        == vec![
            "trend_breakout_fast",
            "defensive_value_risk",
            "cycle_regime_guard",
        ];
    let no_six_persona_activation = active.len() != 6;
    let no_twelve_persona_activation = active.len() != 12;
    let no_eighteen_persona_activation = active.len() != 18;
    let no_runtime_llm_committee_judge =
        help_lower.contains("no runtime llm path exists") || help_lower.contains("no runtime llm");
    let chair_cannot_bypass_risk =
        guard_blob.contains("ChairV0 exists but cannot bypass Risk Governor");
    let persona_cannot_bypass_risk =
        guard_blob.contains("keep trinity and avoid 6/12/18 active expansion");
    let persona_guard_status = if exactly_three_active_personas_preserved
        && no_six_persona_activation
        && no_twelve_persona_activation
        && no_eighteen_persona_activation
        && no_runtime_llm_committee_judge
        && chair_cannot_bypass_risk
        && persona_cannot_bypass_risk
    {
        CommitteeCliSafetyPersonaGuardStatus::PersonaExpansionGuardPreserved
    } else {
        CommitteeCliSafetyPersonaGuardStatus::PersonaExpansionRegression
    };
    CommitteeCliSafetyPersonaExpansionGuardReport {
        report_id: format!("{}-persona-guard", config.reduction_id),
        exactly_three_active_personas_preserved,
        no_six_persona_activation,
        no_twelve_persona_activation,
        no_eighteen_persona_activation,
        no_runtime_llm_committee_judge,
        chair_cannot_bypass_risk,
        persona_cannot_bypass_risk,
        persona_guard_status,
        reason_codes: sprint95_reason_codes(&[]),
    }
}

