fn default_sprint96_bundle_paths() -> Vec<String> {
    vec![
        "target/soma_sprint95_committee_cli_safety_recovery/sprint95-committee-cli-safety-recover"
            .to_string(),
        "examples/sprint96_data/sprint95_summary.json".to_string(),
    ]
}

impl Default for BaselineSignalRealReductionConfig {
    fn default() -> Self {
        Self {
            reduction_id: "sprint96-baseline-signal-recover".to_string(),
            sprint95_bundle_paths: default_sprint96_bundle_paths(),
            baseline_signal_suite_paths: default_sprint96_baseline_suite_paths(),
            baseline_signal_paths: default_sprint96_baseline_paths(),
            no_trade_fixture_paths: default_sprint96_no_trade_paths(),
            risk_governor_fixture_paths: default_sprint96_risk_governor_paths(),
            feature_regime_fixture_paths: default_sprint96_feature_regime_paths(),
            data_quality_fixture_paths: default_sprint96_data_quality_paths(),
            cargo_metadata_paths: Vec::new(),
            cargo_timings_paths: Vec::new(),
            output_root: default_sprint96_output_root(),
            target_family: default_sprint96_target_family(),
            run_real_no_run_after_reduction: false,
            run_real_full_after_reduction: false,
            preserve_assertions: true,
            preserve_safety_guards: true,
            preserve_no_trade_default: true,
            preserve_risk_governor_veto: true,
            preserve_poor_data_quality_denial: true,
            preserve_feature_regime_flow: true,
            preserve_source_boundary_checks: true,
            preserve_no_lookahead_checks: true,
            preserve_research_only_interpretation: true,
            preserve_determinism_checks: true,
            reason_codes: default_sprint76_reason_codes(),
        }
    }
}

impl BaselineSignalRealReductionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.reduction_id.trim().is_empty() {
            return Err("baseline signal real reduction config requires reduction_id".to_string());
        }
        if self.target_family != "BaselineSignal" {
            return Err(
                "baseline signal real reduction target_family must stay BaselineSignal".to_string(),
            );
        }
        for path in self
            .sprint95_bundle_paths
            .iter()
            .chain(self.baseline_signal_suite_paths.iter())
            .chain(self.baseline_signal_paths.iter())
            .chain(self.no_trade_fixture_paths.iter())
            .chain(self.risk_governor_fixture_paths.iter())
            .chain(self.feature_regime_fixture_paths.iter())
            .chain(self.data_quality_fixture_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if !path_is_local(path) {
                return Err(format!(
                    "baseline signal real reduction paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.reduction_id)
    }
}

