fn sprint96_build_entry_consumed_report(
    config: &BaselineSignalRealReductionConfig,
    previous_entry: &BaselineSignalEntryGate,
    reduction_status: BaselineSignalRealReductionStatus,
) -> BaselineSignalEntryConsumedReport {
    let reduction_started = sprint96_reduction_is_closed(reduction_status);
    let entry_consumed = matches!(
        previous_entry.gate_status,
        BaselineSignalEntryGateStatus::BaselineSignalEntryReady
    ) && reduction_started;
    let consumed_status = if entry_consumed {
        BaselineSignalEntryConsumedStatus::EntryConsumedForBaselineSignal
    } else if matches!(
        previous_entry.gate_status,
        BaselineSignalEntryGateStatus::BaselineSignalEntryReady
    ) {
        BaselineSignalEntryConsumedStatus::EntryReadyButNotConsumed
    } else {
        BaselineSignalEntryConsumedStatus::EntryBlocked
    };
    BaselineSignalEntryConsumedReport {
        report_id: format!("{}-entry-consumed", config.reduction_id),
        previous_entry_status: format!("{:?}", previous_entry.gate_status),
        reduction_started,
        entry_consumed,
        consumed_for_family: CompileFamilyV2::BaselineSignal,
        consumed_status,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_build_counterfactual_precheck(
    config: &BaselineSignalRealReductionConfig,
    counterfactual_blob: &str,
) -> CounterfactualBackfillReadinessPrecheckReport {
    let counterfactual_backfill_family_present =
        sprint76_absolutize("src/league/counterfactual_backfill_plan.rs").exists();
    let counterfactual_backfill_suite_present =
        sprint76_absolutize("tests/counterfactual_backfill_suite.rs").exists();
    let no_trade_counterfactual_checks_present = counterfactual_blob
        .contains("no_trade_counterfactual_available")
        || counterfactual_blob.contains("NoTrade");
    let risk_denied_counterfactual_checks_present = counterfactual_blob
        .contains("risk_denied_counterfactual_available")
        || counterfactual_blob.contains("MissingRiskDeniedCounterfactual")
        || counterfactual_blob.contains("MissingRiskDecision");
    let defensive_value_checks_present =
        counterfactual_blob.contains("avoided_loss") || counterfactual_blob.contains("defensive");
    let opportunity_cost_checks_present =
        counterfactual_blob.contains("missed_gain") || counterfactual_blob.contains("opportunity");
    let no_fabricated_outcome_checks_present = counterfactual_blob
        .contains("SkippedMissingOutcome")
        || counterfactual_blob.contains("outcome_reference_available: false");
    let no_lookahead_checks_present = counterfactual_blob.contains("NoLookaheadViolation")
        || counterfactual_blob.contains("no_lookahead_safe");
    let deterministic_backfill_checks_present =
        counterfactual_blob.contains("assert_eq!(first.to_text(), second.to_text())");
    let precheck_status = if counterfactual_backfill_family_present
        && counterfactual_backfill_suite_present
        && no_trade_counterfactual_checks_present
        && risk_denied_counterfactual_checks_present
        && defensive_value_checks_present
        && opportunity_cost_checks_present
        && no_fabricated_outcome_checks_present
        && no_lookahead_checks_present
        && deterministic_backfill_checks_present
    {
        CounterfactualBackfillReadinessPrecheckStatus::CounterfactualBackfillPrecheckReady
    } else {
        CounterfactualBackfillReadinessPrecheckStatus::CounterfactualBackfillPrecheckBlocked
    };
    CounterfactualBackfillReadinessPrecheckReport {
        report_id: format!("{}-counterfactual-precheck", config.reduction_id),
        counterfactual_backfill_family_present,
        counterfactual_backfill_suite_present,
        no_trade_counterfactual_checks_present,
        risk_denied_counterfactual_checks_present,
        defensive_value_checks_present,
        opportunity_cost_checks_present,
        no_fabricated_outcome_checks_present,
        no_lookahead_checks_present,
        deterministic_backfill_checks_present,
        precheck_status,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_build_queue_progress_report(
    config: &BaselineSignalRealReductionConfig,
    previous_queue: &RemainingBlockerQueueV11,
    reduction_status: BaselineSignalRealReductionStatus,
) -> SevenBlockerQueueProgressReportV12 {
    let current_queue = sprint96_current_remaining_blockers(previous_queue, reduction_status);
    let mut completed_families = previous_queue.completed_families.clone();
    if sprint96_reduction_is_closed(reduction_status) {
        completed_families.push("BaselineSignal".to_string());
        completed_families = stable_ordered_strings(&completed_families);
    }
    let queue_status = if current_queue.is_empty() {
        SevenBlockerQueueProgressStatusV12::QueueClosed
    } else if sprint96_reduction_is_closed(reduction_status) {
        SevenBlockerQueueProgressStatusV12::QueueAdvanced
    } else {
        SevenBlockerQueueProgressStatusV12::QueueBlockedByBaselineSignal
    };
    SevenBlockerQueueProgressReportV12 {
        report_id: format!("{}-queue-progress-v12", config.reduction_id),
        previous_queue: previous_queue.ordered_remaining_families.clone(),
        current_queue: current_queue.clone(),
        completed_families,
        reduced_families: if sprint96_reduction_is_closed(reduction_status) {
            vec!["BaselineSignal".to_string()]
        } else {
            Vec::new()
        },
        isolated_families: previous_queue.isolated_families.clone(),
        still_blocked_families: current_queue.clone(),
        primary_next_family: current_queue
            .first()
            .cloned()
            .unwrap_or_else(|| "None".to_string()),
        queue_status,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_build_measured_target_delta_report(
    config: &BaselineSignalRealReductionConfig,
    compile_impact: &BaselineSignalCompileImpactReport,
) -> MeasuredTargetDeltaReportV12 {
    let delta_status = if compile_impact.measured {
        MeasuredTargetDeltaStatusV12::MeasuredTargetDeltaReady
    } else if compile_impact.sample_backed {
        MeasuredTargetDeltaStatusV12::SampleBackedOnly
    } else {
        MeasuredTargetDeltaStatusV12::NotRun
    };
    MeasuredTargetDeltaReportV12 {
        report_id: format!("{}-measured-target-delta-v12", config.reduction_id),
        target_count_before: compile_impact.target_count_before,
        target_count_after: compile_impact.target_count_after,
        baseline_signal_delta: compile_impact.baseline_signal_delta,
        measured: compile_impact.measured,
        sample_backed: compile_impact.sample_backed,
        timing_available: compile_impact.compile_duration_before_ms.is_some()
            && compile_impact.compile_duration_after_ms.is_some(),
        delta_status,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_build_safety_report(
    config: &BaselineSignalRealReductionConfig,
    previous_safety: &SafetyCoveragePreservationReportV11,
    no_trade: &BaselineSignalNoTradeDefaultPreservationReport,
    poor_data: &BaselineSignalPoorDataQualityDenialReport,
    risk: &BaselineSignalRiskGovernorVetoPreservationReport,
    research: &BaselineSignalResearchOnlyPreservationReport,
) -> SafetyCoveragePreservationReportV12 {
    let safety_status = if previous_safety.live_trading_guard_present
        && previous_safety.broker_guard_present
        && previous_safety.order_guard_present
        && previous_safety.account_guard_present
        && previous_safety.runtime_llm_guard_present
        && previous_safety.mamba_runtime_guard_present
        && previous_safety.gated_runtime_guard_present
        && previous_safety.model_training_guard_present
        && previous_safety.rust_neural_training_guard_present
        && previous_safety.python_training_dependency_guard_present
        && previous_safety.secret_guard_present
        && previous_safety.no_lookahead_guard_present
        && previous_safety.source_boundary_guard_present
        && previous_safety.browser_execution_guard_present
        && previous_safety.ui_order_control_guard_present
        && previous_safety.committee_cli_safety_isolated_or_safely_represented
        && matches!(
            no_trade.no_trade_status,
            BaselineSignalNoTradeDefaultStatus::NoTradeDefaultPreserved
                | BaselineSignalNoTradeDefaultStatus::NoTradeDefaultPreservedWithWarnings
        )
        && matches!(
            poor_data.denial_status,
            BaselineSignalPoorDataQualityDenialStatus::PoorDataQualityDenialPreserved
                | BaselineSignalPoorDataQualityDenialStatus::PoorDataQualityDenialPreservedWithWarnings
        )
        && matches!(
            risk.veto_status,
            BaselineSignalRiskGovernorVetoStatus::RiskGovernorVetoPreserved
                | BaselineSignalRiskGovernorVetoStatus::RiskGovernorVetoPreservedWithWarnings
        )
        && matches!(
            research.research_status,
            BaselineSignalResearchOnlyStatus::ResearchOnlyPreserved
                | BaselineSignalResearchOnlyStatus::ResearchOnlyPreservedWithWarnings
        )
    {
        SafetyCoveragePreservationReportV12Status::SafetyCoveragePreserved
    } else {
        SafetyCoveragePreservationReportV12Status::SafetyCoverageMissing
    };
    SafetyCoveragePreservationReportV12 {
        report_id: format!("{}-safety-v12", config.reduction_id),
        live_trading_guard_present: previous_safety.live_trading_guard_present,
        broker_guard_present: previous_safety.broker_guard_present,
        order_guard_present: previous_safety.order_guard_present,
        account_guard_present: previous_safety.account_guard_present,
        runtime_llm_guard_present: previous_safety.runtime_llm_guard_present,
        mamba_runtime_guard_present: previous_safety.mamba_runtime_guard_present,
        gated_runtime_guard_present: previous_safety.gated_runtime_guard_present,
        model_training_guard_present: previous_safety.model_training_guard_present,
        rust_neural_training_guard_present: previous_safety.rust_neural_training_guard_present,
        python_training_dependency_guard_present: previous_safety
            .python_training_dependency_guard_present,
        secret_guard_present: previous_safety.secret_guard_present,
        no_lookahead_guard_present: previous_safety.no_lookahead_guard_present,
        source_boundary_guard_present: previous_safety.source_boundary_guard_present,
        browser_execution_guard_present: previous_safety.browser_execution_guard_present,
        ui_order_control_guard_present: previous_safety.ui_order_control_guard_present,
        committee_cli_safety_isolated: previous_safety.committee_cli_safety_isolated_or_safely_represented,
        baseline_no_trade_default_preserved: matches!(
            no_trade.no_trade_status,
            BaselineSignalNoTradeDefaultStatus::NoTradeDefaultPreserved
                | BaselineSignalNoTradeDefaultStatus::NoTradeDefaultPreservedWithWarnings
        ),
        baseline_risk_governor_veto_preserved: matches!(
            risk.veto_status,
            BaselineSignalRiskGovernorVetoStatus::RiskGovernorVetoPreserved
                | BaselineSignalRiskGovernorVetoStatus::RiskGovernorVetoPreservedWithWarnings
        ),
        baseline_poor_data_quality_denial_preserved: matches!(
            poor_data.denial_status,
            BaselineSignalPoorDataQualityDenialStatus::PoorDataQualityDenialPreserved
                | BaselineSignalPoorDataQualityDenialStatus::PoorDataQualityDenialPreservedWithWarnings
        ),
        baseline_research_only_preserved: matches!(
            research.research_status,
            BaselineSignalResearchOnlyStatus::ResearchOnlyPreserved
                | BaselineSignalResearchOnlyStatus::ResearchOnlyPreservedWithWarnings
        ),
        baseline_no_live_signal_activation: research.no_live_signal_activation,
        safety_status,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_current_no_run_status(
    previous_workspace: &WorkspaceGateRecoveryV12,
    no_run_attempt: &RealNoRunGateAttemptV11,
) -> String {
    if matches!(
        no_run_attempt.no_run_status,
        RealNoRunGateAttemptV11Status::NotRun
    ) {
        previous_workspace.current_no_run_status.clone()
    } else {
        format!("{:?}", no_run_attempt.no_run_status)
    }
}

fn sprint96_current_full_status(
    previous_workspace: &WorkspaceGateRecoveryV12,
    full_attempt: &RealFullWorkspaceGateAttemptV14,
) -> String {
    if matches!(
        full_attempt.full_status,
        RealFullWorkspaceGateAttemptV14Status::NotRun
    ) {
        previous_workspace.current_full_status.clone()
    } else {
        format!("{:?}", full_attempt.full_status)
    }
}

fn sprint96_build_counterfactual_entry_gate(
    config: &BaselineSignalRealReductionConfig,
    reduction_status: BaselineSignalRealReductionStatus,
    safety: &SafetyCoveragePreservationReportV12,
    previous_workspace: &WorkspaceGateRecoveryV12,
    no_run_attempt: &RealNoRunGateAttemptV11,
    full_attempt: &RealFullWorkspaceGateAttemptV14,
) -> CounterfactualBackfillEntryGate {
    let no_run_status = sprint96_current_no_run_status(previous_workspace, no_run_attempt);
    let full_status = sprint96_current_full_status(previous_workspace, full_attempt);
    let counterfactual_backfill_next_allowed = sprint96_reduction_is_closed(reduction_status)
        && matches!(
            safety.safety_status,
            SafetyCoveragePreservationReportV12Status::SafetyCoveragePreserved
        );
    let gate_status = if counterfactual_backfill_next_allowed {
        CounterfactualBackfillEntryGateStatus::CounterfactualBackfillEntryReady
    } else if !sprint96_reduction_is_closed(reduction_status) {
        CounterfactualBackfillEntryGateStatus::CounterfactualBackfillEntryBlockedByBaselineSignal
    } else if !matches!(
        safety.safety_status,
        SafetyCoveragePreservationReportV12Status::SafetyCoveragePreserved
    ) {
        CounterfactualBackfillEntryGateStatus::CounterfactualBackfillEntryBlockedBySafety
    } else {
        CounterfactualBackfillEntryGateStatus::CounterfactualBackfillEntryBlockedByUnknownGateCause
    };
    CounterfactualBackfillEntryGate {
        gate_id: format!("{}-counterfactual-entry-gate", config.reduction_id),
        baseline_signal_reduction_status: reduction_status,
        baseline_signal_safety_status: safety.safety_status,
        no_run_status,
        full_status,
        counterfactual_backfill_next_allowed,
        gate_status,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_build_workspace_recovery(
    config: &BaselineSignalRealReductionConfig,
    previous_workspace: &WorkspaceGateRecoveryV12,
    no_run_attempt: &RealNoRunGateAttemptV11,
    full_attempt: &RealFullWorkspaceGateAttemptV14,
    reduction_status: BaselineSignalRealReductionStatus,
    measured_delta: &MeasuredTargetDeltaReportV12,
    queue_progress: &SevenBlockerQueueProgressReportV12,
    safety: &SafetyCoveragePreservationReportV12,
    remaining_blockers: &[String],
) -> WorkspaceGateRecoveryV13 {
    let current_no_run_status = sprint96_current_no_run_status(previous_workspace, no_run_attempt);
    let current_full_status = sprint96_current_full_status(previous_workspace, full_attempt);
    let recovery_status = if current_no_run_status == "RealNoRunPassed"
        && current_full_status == "FullWorkspaceAccepted"
    {
        WorkspaceGateRecoveryV13Status::GateRecovered
    } else if sprint96_reduction_is_closed(reduction_status) {
        WorkspaceGateRecoveryV13Status::GateImprovedButBlocked
    } else {
        WorkspaceGateRecoveryV13Status::GateStillBlocked
    };
    WorkspaceGateRecoveryV13 {
        report_id: format!("{}-workspace-gate-recovery-v13", config.reduction_id),
        previous_no_run_status: previous_workspace.current_no_run_status.clone(),
        current_no_run_status,
        previous_full_status: previous_workspace.current_full_status.clone(),
        current_full_status,
        baseline_signal_reduction_status: reduction_status,
        measured_delta_status: measured_delta.delta_status,
        queue_progress_status: queue_progress.queue_status,
        safety_coverage_status: safety.safety_status,
        remaining_blockers: remaining_blockers.to_vec(),
        recovery_status,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_build_remaining_queue_report(
    config: &BaselineSignalRealReductionConfig,
    queue_progress: &SevenBlockerQueueProgressReportV12,
    counterfactual_gate: &CounterfactualBackfillEntryGate,
) -> RemainingBlockerQueueV12 {
    let queue_status = if queue_progress.current_queue.is_empty() {
        RemainingBlockerQueueV12Status::QueueClosed
    } else if queue_progress.primary_next_family == "BaselineSignal" {
        RemainingBlockerQueueV12Status::QueueBlockedByBaselineSignal
    } else if queue_progress.current_queue.len() < queue_progress.previous_queue.len() {
        RemainingBlockerQueueV12Status::QueueAdvanced
    } else {
        RemainingBlockerQueueV12Status::QueueReady
    };
    RemainingBlockerQueueV12 {
        queue_id: format!("{}-remaining-queue-v12", config.reduction_id),
        ordered_remaining_families: queue_progress.current_queue.clone(),
        primary_next_family: queue_progress.primary_next_family.clone(),
        completed_families: queue_progress.completed_families.clone(),
        isolated_families: queue_progress.isolated_families.clone(),
        blocked_families: queue_progress.still_blocked_families.clone(),
        counterfactual_backfill_entry_allowed: counterfactual_gate
            .counterfactual_backfill_next_allowed,
        queue_status,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_build_panel(
    config: &BaselineSignalRealReductionConfig,
    reduction_report: &BaselineSignalRealReductionReport,
    assertion: &BaselineSignalAssertionMigrationReport,
    fixture: &BaselineSignalFixtureSetupReductionReport,
    feature: &BaselineSignalFeatureRegimeFlowPreservationReport,
    no_trade: &BaselineSignalNoTradeDefaultPreservationReport,
    poor_data: &BaselineSignalPoorDataQualityDenialReport,
    risk: &BaselineSignalRiskGovernorVetoPreservationReport,
    source_boundary: &BaselineSignalSourceBoundaryPreservationReport,
    no_lookahead: &BaselineSignalNoLookaheadPreservationReport,
    research: &BaselineSignalResearchOnlyPreservationReport,
    determinism: &BaselineSignalDeterminismPreservationReport,
    compile: &BaselineSignalCompileImpactReport,
    no_run: &BaselineSignalNoRunGateRerunReport,
    full: &BaselineSignalFullGateRerunReport,
    measured_delta: &MeasuredTargetDeltaReportV12,
    queue_progress: &SevenBlockerQueueProgressReportV12,
    counterfactual_gate: &CounterfactualBackfillEntryGate,
    counterfactual_precheck: &CounterfactualBackfillReadinessPrecheckReport,
    safety: &SafetyCoveragePreservationReportV12,
) -> ControlTowerBaselineSignalRecoveryPanel {
    let mut warnings = Vec::new();
    if compile.impact_status == BaselineSignalCompileImpactStatus::CompileImpactSampleBacked {
        warnings
            .push("compile impact remains sample-backed only; no real timing claim".to_string());
    }
    if no_run.status == BaselineSignalNoRunGateRerunStatus::NotRun {
        warnings
            .push("no-run rerun not executed; blocked status remains authoritative".to_string());
    }
    if full.status == BaselineSignalFullGateRerunStatus::NotRun {
        warnings.push(
            "full workspace rerun not executed; full workspace acceptance remains unresolved"
                .to_string(),
        );
    }
    if !matches!(
        counterfactual_precheck.precheck_status,
        CounterfactualBackfillReadinessPrecheckStatus::CounterfactualBackfillPrecheckReady
    ) {
        warnings.push(
            "CounterfactualBackfill remains entry/precheck only until readiness precheck is green"
                .to_string(),
        );
    }
    ControlTowerBaselineSignalRecoveryPanel {
        panel_id: format!("{}-control-tower-panel", config.reduction_id),
        baseline_signal_reduction_status: reduction_report.reduction_status,
        assertion_migration_status: assertion.migration_status,
        fixture_setup_reduction_status: fixture.reduction_status,
        feature_regime_status: feature.flow_status,
        no_trade_default_status: no_trade.no_trade_status,
        poor_data_quality_status: poor_data.denial_status,
        risk_governor_veto_status: risk.veto_status,
        source_boundary_status: source_boundary.source_boundary_status,
        no_lookahead_status: no_lookahead.no_lookahead_status,
        research_only_status: research.research_status,
        determinism_status: determinism.determinism_status,
        compile_impact_status: compile.impact_status,
        no_run_gate_status: no_run.status,
        full_gate_status: full.status,
        measured_delta_status: measured_delta.delta_status,
        queue_progress_status: queue_progress.queue_status,
        counterfactual_backfill_entry_status: counterfactual_gate.gate_status,
        safety_coverage_status: safety.safety_status,
        runtime_deferred_summary: "ResearchOnly".to_string(),
        primary_next_family: queue_progress.primary_next_family.clone(),
        next_actions: vec![
            "Keep BaselineSignal conservative: no trade, veto, quality, boundary, and no-lookahead guards remain absolute.".to_string(),
            "Advance CounterfactualBackfill entry/precheck only; do not begin reduction in Sprint 96.".to_string(),
            "Keep no-run/full workspace reporting honest until explicit reruns finish.".to_string(),
        ],
        warnings,
        reason_codes: sprint96_reason_codes(&[]),
    }
}

fn sprint96_storage_report(
    values: &[(&str, serde_json::Value)],
) -> Result<OperatorBriefingStorageReport, String> {
    let mut storage_bytes = 0usize;
    for (_, value) in values {
        storage_bytes += serde_json::to_string_pretty(value)
            .map_err(|err| err.to_string())?
            .len();
    }
    Ok(OperatorBriefingStorageReport {
        artifact_count: values.len(),
        storage_bytes,
        max_bytes: 1_000_000,
        within_budget: storage_bytes <= 1_000_000,
        reason_codes: sprint96_reason_codes(&[]),
    })
}

