impl CounterfactualBackfillRealReductionConfig {
    pub fn from_toml_path(path: &Path) -> Result<Self, String> {
        let text = fs::read_to_string(path).map_err(|err| err.to_string())?;
        toml::from_str(&text).map_err(|err| err.to_string())
    }

    pub fn validate(&self) -> Result<(), String> {
        if self.reduction_id.trim().is_empty() {
            return Err(
                "counterfactual backfill real reduction config requires reduction_id".to_string(),
            );
        }
        if self.target_family != "CounterfactualBackfill" {
            return Err(
                "counterfactual backfill real reduction target_family must stay CounterfactualBackfill"
                    .to_string(),
            );
        }
        for path in self
            .sprint96_bundle_paths
            .iter()
            .chain(self.counterfactual_backfill_suite_paths.iter())
            .chain(self.counterfactual_backfill_paths.iter())
            .chain(self.no_trade_fixture_paths.iter())
            .chain(self.risk_denied_fixture_paths.iter())
            .chain(self.defensive_value_fixture_paths.iter())
            .chain(self.opportunity_cost_fixture_paths.iter())
            .chain(self.no_fabricated_outcome_paths.iter())
            .chain(self.no_lookahead_fixture_paths.iter())
            .chain(self.source_boundary_paths.iter())
            .chain(self.cargo_metadata_paths.iter())
            .chain(self.cargo_timings_paths.iter())
            .chain(std::iter::once(&self.output_root))
        {
            if !path_is_local(path) {
                return Err(format!(
                    "counterfactual backfill real reduction paths must be local: {path}"
                ));
            }
        }
        Ok(())
    }

    pub fn output_dir(&self) -> PathBuf {
        PathBuf::from(&self.output_root).join(&self.reduction_id)
    }
}

