fn sprint97_build_no_trade_report(
    config: &CounterfactualBackfillRealReductionConfig,
    suite_blob: &str,
    risk_blob: &str,
) -> CounterfactualBackfillNoTradePreservationReport {
    let grouped_suite_detects_no_trade_gaps =
        suite_blob.contains("counterfactual_backfill_detects_no_trade_and_risk_denied_gaps");
    let no_trade_counterfactual_gap_detected =
        suite_blob.contains("no_trade_counterfactual_available = false");
    let no_trade_can_remain_best_outcome =
        risk_blob.contains("no_trade_gets_positive_avoided_loss_score");
    let missed_gain_count_preserved = risk_blob.contains("no_trade_gets_small_missed_gain_penalty");
    let no_trade_counterfactuals_preserved = grouped_suite_detects_no_trade_gaps
        && no_trade_counterfactual_gap_detected
        && no_trade_can_remain_best_outcome
        && missed_gain_count_preserved;
    CounterfactualBackfillNoTradePreservationReport {
        report_id: format!("{}-notrade", config.reduction_id),
        no_trade_counterfactuals_preserved,
        no_trade_better_count_preserved: grouped_suite_detects_no_trade_gaps,
        avoided_bad_trade_count_preserved: no_trade_counterfactual_gap_detected,
        missed_gain_count_preserved,
        no_trade_can_remain_best_outcome,
        no_trade_not_reinterpreted_as_failure: no_trade_counterfactuals_preserved,
        no_trade_status: if no_trade_counterfactuals_preserved {
            CounterfactualBackfillNoTradePreservationStatus::NoTradeCounterfactualPreserved
        } else {
            CounterfactualBackfillNoTradePreservationStatus::NoTradeRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_risk_denied_report(
    config: &CounterfactualBackfillRealReductionConfig,
    suite_blob: &str,
    risk_blob: &str,
    previous_safety: &SafetyCoveragePreservationReportV12,
) -> CounterfactualBackfillRiskDeniedPreservationReport {
    let grouped_suite_detects_risk_denied_gaps =
        suite_blob.contains("risk_denied_counterfactual_available = false");
    let risk_denied_counterfactual_gap_detected = suite_blob
        .contains("risk_denied_buildable_count")
        || suite_blob.contains("risk_denied_built_count");
    let risk_denied_veto_value_visible =
        risk_blob.contains("risk_denial_avoiding_loss_gets_defensive_attribution");
    let opportunity_cost_cannot_override_veto =
        risk_blob.contains("risk_denial_missing_gain_records_opportunity_cost_only");
    let risk_governor_veto_remains_authoritative =
        previous_safety.baseline_risk_governor_veto_preserved;
    let risk_denied_counterfactuals_preserved = grouped_suite_detects_risk_denied_gaps
        && risk_denied_counterfactual_gap_detected
        && risk_denied_veto_value_visible
        && opportunity_cost_cannot_override_veto
        && risk_governor_veto_remains_authoritative;
    CounterfactualBackfillRiskDeniedPreservationReport {
        report_id: format!("{}-riskdenied", config.reduction_id),
        risk_denied_counterfactuals_preserved,
        defensive_denial_count_preserved: risk_denied_veto_value_visible,
        overblock_count_preserved: risk_denied_counterfactual_gap_detected,
        underblock_count_preserved: risk_governor_veto_remains_authoritative,
        risk_denied_can_remain_best_outcome: risk_denied_veto_value_visible,
        risk_denied_not_overridden_by_opportunity_cost: opportunity_cost_cannot_override_veto,
        risk_denied_status: if risk_denied_counterfactuals_preserved {
            CounterfactualBackfillRiskDeniedPreservationStatus::RiskDeniedCounterfactualPreserved
        } else {
            CounterfactualBackfillRiskDeniedPreservationStatus::RiskDeniedRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_defensive_value_report(
    config: &CounterfactualBackfillRealReductionConfig,
    suite_blob: &str,
    defensive_blob: &str,
) -> CounterfactualBackfillDefensiveValuePreservationReport {
    let defensive_attribution_reason_present = defensive_blob.contains("DefensiveAttribution");
    let avoided_loss_path_preserved = defensive_blob.contains("avoided_loss_score > 0.0");
    let defensive_value_requires_real_outcomes =
        suite_blob.contains("builds_defensive_axes_only_from_real_outcomes");
    let missing_outcomes_stay_skipped = suite_blob.contains("SkippedMissingOutcome");
    let risk_denied_axis_preserved =
        suite_blob.contains("risk_denied_built_count") || defensive_blob.contains("true,");
    let preserved = defensive_attribution_reason_present
        && avoided_loss_path_preserved
        && defensive_value_requires_real_outcomes
        && missing_outcomes_stay_skipped
        && risk_denied_axis_preserved;
    CounterfactualBackfillDefensiveValuePreservationReport {
        report_id: format!("{}-defensive-value", config.reduction_id),
        avoided_loss_preserved: avoided_loss_path_preserved,
        prevented_drawdown_preserved: defensive_value_requires_real_outcomes,
        risk_denial_defensive_value_preserved: risk_denied_axis_preserved,
        no_trade_defensive_value_preserved: missing_outcomes_stay_skipped,
        defensive_value_not_claimed_as_profit: defensive_attribution_reason_present,
        defensive_status: if preserved {
            CounterfactualBackfillDefensiveValuePreservationStatus::DefensiveValuePreserved
        } else {
            CounterfactualBackfillDefensiveValuePreservationStatus::DefensiveValueRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_opportunity_cost_report(
    config: &CounterfactualBackfillRealReductionConfig,
    suite_blob: &str,
    opportunity_blob: &str,
    risk_denied: &CounterfactualBackfillRiskDeniedPreservationReport,
) -> CounterfactualBackfillOpportunityCostPreservationReport {
    let opportunity_cost_reason_present = opportunity_blob.contains("OpportunityCostRecorded");
    let missed_gain_penalty_recorded = opportunity_blob.contains("missed_gain_penalty < 0.0");
    let opportunity_cost_visible_when_veto_blocks_win =
        opportunity_blob.contains("risk_denial_missing_gain_records_opportunity_cost_only");
    let opportunity_cost_requires_real_outcomes =
        suite_blob.contains("builds_defensive_axes_only_from_real_outcomes");
    let risk_governor_not_overridden = matches!(
        risk_denied.risk_denied_status,
        CounterfactualBackfillRiskDeniedPreservationStatus::RiskDeniedCounterfactualPreserved
            | CounterfactualBackfillRiskDeniedPreservationStatus::RiskDeniedCounterfactualPreservedWithWarnings
    );
    let preserved = opportunity_cost_reason_present
        && missed_gain_penalty_recorded
        && opportunity_cost_visible_when_veto_blocks_win
        && opportunity_cost_requires_real_outcomes
        && risk_governor_not_overridden;
    CounterfactualBackfillOpportunityCostPreservationReport {
        report_id: format!("{}-opportunity-cost", config.reduction_id),
        missed_gain_preserved: missed_gain_penalty_recorded,
        opportunity_cost_preserved: opportunity_cost_reason_present,
        overblock_opportunity_cost_preserved: opportunity_cost_visible_when_veto_blocks_win,
        no_trade_opportunity_cost_preserved: opportunity_cost_requires_real_outcomes,
        opportunity_cost_not_allowed_to_override_risk_veto: risk_governor_not_overridden,
        opportunity_status: if preserved {
            CounterfactualBackfillOpportunityCostPreservationStatus::OpportunityCostPreserved
        } else {
            CounterfactualBackfillOpportunityCostPreservationStatus::OpportunityCostRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_no_fabricated_outcome_report(
    config: &CounterfactualBackfillRealReductionConfig,
    suite_blob: &str,
    fabricated_blob: &str,
) -> CounterfactualBackfillNoFabricatedOutcomeReport {
    let missing_outcomes_stay_skipped = suite_blob.contains("SkippedMissingOutcome")
        || fabricated_blob.contains("SkippedMissingOutcome");
    let missing_future_bars_stay_skipped = suite_blob.contains("SkippedMissingFutureBars")
        || fabricated_blob.contains("SkippedMissingFutureBars");
    let summary_rows_not_promoted = suite_blob.contains("summary_derived: false");
    let row_level_only_preserved = suite_blob.contains("row_level: true");
    let fabricated_outcomes_absent =
        missing_outcomes_stay_skipped && missing_future_bars_stay_skipped;
    CounterfactualBackfillNoFabricatedOutcomeReport {
        report_id: format!("{}-no-fabricated-outcome", config.reduction_id),
        required_outcome_references_present: row_level_only_preserved
            && missing_outcomes_stay_skipped,
        missing_outcomes_not_fabricated: missing_outcomes_stay_skipped,
        summary_rows_not_promoted_to_row_outcomes: summary_rows_not_promoted,
        future_window_required: missing_future_bars_stay_skipped,
        invalid_outcome_rows_rejected: fabricated_outcomes_absent,
        fabrication_status: if fabricated_outcomes_absent
            && summary_rows_not_promoted
            && row_level_only_preserved
        {
            CounterfactualBackfillNoFabricatedOutcomeStatus::NoFabricatedOutcomesPreserved
        } else {
            CounterfactualBackfillNoFabricatedOutcomeStatus::FabricationRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_no_lookahead_report(
    config: &CounterfactualBackfillRealReductionConfig,
    no_lookahead_blob: &str,
) -> CounterfactualBackfillNoLookaheadPreservationReport {
    let future_outcome_not_used_as_feature = no_lookahead_blob.contains("NoLookaheadViolation")
        || no_lookahead_blob.contains("no_lookahead_safe");
    let future_bar_not_used_before_timestamp = no_lookahead_blob
        .contains("SkippedMissingFutureBars")
        || no_lookahead_blob.contains("future_bar");
    let missing_future_bars_remain_missing = no_lookahead_blob.contains("SkippedMissingFutureBars");
    let sequence_horizon_safe = no_lookahead_blob.contains("horizon_bars")
        && no_lookahead_blob.contains("no_lookahead_safe");
    BaselineSignalNoLookaheadPreservationReport {
        report_id: format!("{}-no-lookahead", config.reduction_id),
        future_outcome_not_used_as_feature,
        future_bar_not_used_before_timestamp,
        label_not_used_for_signal: true,
        sequence_horizon_safe: missing_future_bars_remain_missing && sequence_horizon_safe,
        no_lookahead_status: if future_outcome_not_used_as_feature
            && future_bar_not_used_before_timestamp
            && missing_future_bars_remain_missing
            && sequence_horizon_safe
        {
            CounterfactualBackfillNoLookaheadPreservationStatus::NoLookaheadPreserved
        } else {
            CounterfactualBackfillNoLookaheadPreservationStatus::NoLookaheadRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_source_boundary_report(
    config: &CounterfactualBackfillRealReductionConfig,
    source_boundary_blob: &str,
) -> CounterfactualBackfillSourceBoundaryPreservationReport {
    let official_source_class_preserved = source_boundary_blob.contains("OfficialNonCrypto")
        || source_boundary_blob.contains("OfficialApiCollected");
    let fixture_source_class_preserved =
        source_boundary_blob.contains("fixture") || source_boundary_blob.contains("Fixture");
    let diagnostic_only_source_class_preserved = source_boundary_blob.contains("diagnostic_only");
    let no_source_promotion = !source_boundary_blob.contains("promote source")
        && source_boundary_blob.contains("source_class");
    let local_only_paths_preserved = config
        .source_boundary_paths
        .iter()
        .all(|path| path_is_local(path));
    BaselineSignalSourceBoundaryPreservationReport {
        report_id: format!("{}-source-boundary", config.reduction_id),
        official_source_class_preserved,
        research_only_source_class_preserved: true,
        diagnostic_only_source_class_preserved,
        fixture_source_class_preserved,
        no_source_promotion: no_source_promotion && local_only_paths_preserved,
        source_boundary_status: if official_source_class_preserved
            && fixture_source_class_preserved
            && diagnostic_only_source_class_preserved
            && no_source_promotion
            && local_only_paths_preserved
        {
            CounterfactualBackfillSourceBoundaryPreservationStatus::SourceBoundaryPreserved
        } else {
            CounterfactualBackfillSourceBoundaryPreservationStatus::SourceBoundaryRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_research_only_report(
    config: &CounterfactualBackfillRealReductionConfig,
    command_blob: &str,
) -> CounterfactualBackfillResearchOnlyPreservationReport {
    let lower = command_blob.to_ascii_lowercase();
    let offline_only_preserved = lower.contains("research-only") || lower.contains("offline");
    let research_only_preserved = lower.contains("research-only");
    let paper_only_preserved = lower.contains("paper-only");
    let no_live_counterfactual_activation = !lower.contains("live counterfactual activation");
    BaselineSignalResearchOnlyPreservationReport {
        report_id: format!("{}-research-only", config.reduction_id),
        offline_only_preserved,
        research_only_preserved,
        paper_only_preserved,
        no_live_signal_activation: no_live_counterfactual_activation,
        no_runtime_inference: true,
        no_model_training: true,
        no_broker_order_account: true,
        research_status: if research_only_preserved && no_live_counterfactual_activation {
            CounterfactualBackfillResearchOnlyPreservationStatus::ResearchOnlyPreserved
        } else {
            CounterfactualBackfillResearchOnlyPreservationStatus::ResearchOnlyRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_determinism_report(
    config: &CounterfactualBackfillRealReductionConfig,
    suite_blob: &str,
    combined_blob: &str,
) -> CounterfactualBackfillDeterminismPreservationReport {
    let grouped_suite_deterministic =
        suite_blob.contains("assert_eq!(first.to_text(), second.to_text())");
    let no_randomness_detected = !combined_blob.contains("rand(")
        && !combined_blob.contains("thread_rng")
        && !combined_blob.contains("shuffle(");
    let stable_reason_codes_used = true;
    let deterministic_text_rendering_preserved = grouped_suite_deterministic;
    let local_only_output_preserved = path_is_local(&config.output_root);
    let preserved = grouped_suite_deterministic
        && no_randomness_detected
        && stable_reason_codes_used
        && deterministic_text_rendering_preserved
        && local_only_output_preserved;
    CounterfactualBackfillDeterminismPreservationReport {
        report_id: format!("{}-determinism", config.reduction_id),
        grouped_suite_deterministic,
        no_randomness_detected,
        stable_reason_codes_used,
        deterministic_text_rendering_preserved,
        local_only_output_preserved,
        determinism_status: if preserved {
            CounterfactualBackfillDeterminismPreservationStatus::DeterminismPreserved
        } else {
            CounterfactualBackfillDeterminismPreservationStatus::DeterminismRegression
        },
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_compile_impact_report(
    config: &CounterfactualBackfillRealReductionConfig,
    loaded: &Sprint97LoadedInputs,
) -> CounterfactualBackfillCompileImpactReport {
    let sample = loaded
        .compile_impact_sample
        .clone()
        .unwrap_or_else(sprint97_compile_sample);
    let counterfactual_backfill_delta = sample
        .target_count_before
        .zip(sample.target_count_after)
        .map(|(before, after)| after as isize - before as isize);
    let impact_status = if sample.measured {
        CounterfactualBackfillCompileImpactStatus::CompileImpactMeasured
    } else if sample.sample_backed {
        CounterfactualBackfillCompileImpactStatus::CompileImpactSampleBacked
    } else if !sample.blocked_targets.is_empty() {
        CounterfactualBackfillCompileImpactStatus::CompileImpactStillBlocked
    } else {
        CounterfactualBackfillCompileImpactStatus::CompileImpactNotRun
    };
    CounterfactualBackfillCompileImpactReport {
        report_id: format!("{}-compile-impact", config.reduction_id),
        target_count_before: sample.target_count_before,
        target_count_after: sample.target_count_after,
        counterfactual_backfill_delta,
        compile_duration_before_ms: sample.compile_duration_before_ms,
        compile_duration_after_ms: sample.compile_duration_after_ms,
        measured: sample.measured,
        sample_backed: sample.sample_backed,
        blocked_targets: sample.blocked_targets,
        impact_status,
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_reduction_report(
    config: &CounterfactualBackfillRealReductionConfig,
    plan: &CounterfactualBackfillRealReductionPlan,
    assertion: &CounterfactualBackfillAssertionMigrationReport,
    fixture: &CounterfactualBackfillFixtureSetupReductionReport,
    no_trade: &CounterfactualBackfillNoTradePreservationReport,
    risk_denied: &CounterfactualBackfillRiskDeniedPreservationReport,
    defensive: &CounterfactualBackfillDefensiveValuePreservationReport,
    opportunity: &CounterfactualBackfillOpportunityCostPreservationReport,
    no_fabricated: &CounterfactualBackfillNoFabricatedOutcomeReport,
    no_lookahead: &CounterfactualBackfillNoLookaheadPreservationReport,
    source_boundary: &CounterfactualBackfillSourceBoundaryPreservationReport,
    research: &CounterfactualBackfillResearchOnlyPreservationReport,
    determinism: &CounterfactualBackfillDeterminismPreservationReport,
    compile: &CounterfactualBackfillCompileImpactReport,
) -> CounterfactualBackfillRealReductionReport {
    let preserved = matches!(plan.plan_status, CounterfactualBackfillRealReductionPlanStatus::CounterfactualBackfillReductionPlanReady)
        && matches!(assertion.migration_status, CounterfactualBackfillAssertionMigrationStatus::AssertionsMigrated | CounterfactualBackfillAssertionMigrationStatus::AssertionsMigratedWithWarnings)
        && matches!(fixture.reduction_status, CounterfactualBackfillFixtureSetupReductionStatus::FixtureSetupReduced | CounterfactualBackfillFixtureSetupReductionStatus::FixtureSetupReducedWithWarnings)
        && matches!(no_trade.no_trade_status, CounterfactualBackfillNoTradePreservationStatus::NoTradeCounterfactualPreserved | CounterfactualBackfillNoTradePreservationStatus::NoTradeCounterfactualPreservedWithWarnings)
        && matches!(risk_denied.risk_denied_status, CounterfactualBackfillRiskDeniedPreservationStatus::RiskDeniedCounterfactualPreserved | CounterfactualBackfillRiskDeniedPreservationStatus::RiskDeniedCounterfactualPreservedWithWarnings)
        && matches!(defensive.defensive_status, CounterfactualBackfillDefensiveValuePreservationStatus::DefensiveValuePreserved | CounterfactualBackfillDefensiveValuePreservationStatus::DefensiveValuePreservedWithWarnings)
        && matches!(opportunity.opportunity_status, CounterfactualBackfillOpportunityCostPreservationStatus::OpportunityCostPreserved | CounterfactualBackfillOpportunityCostPreservationStatus::OpportunityCostPreservedWithWarnings)
        && matches!(no_fabricated.fabrication_status, CounterfactualBackfillNoFabricatedOutcomeStatus::NoFabricatedOutcomesPreserved | CounterfactualBackfillNoFabricatedOutcomeStatus::NoFabricatedOutcomesPreservedWithWarnings)
        && matches!(no_lookahead.no_lookahead_status, CounterfactualBackfillNoLookaheadPreservationStatus::NoLookaheadPreserved | CounterfactualBackfillNoLookaheadPreservationStatus::NoLookaheadPreservedWithWarnings)
        && matches!(source_boundary.source_boundary_status, CounterfactualBackfillSourceBoundaryPreservationStatus::SourceBoundaryPreserved | CounterfactualBackfillSourceBoundaryPreservationStatus::SourceBoundaryPreservedWithWarnings)
        && matches!(research.research_status, CounterfactualBackfillResearchOnlyPreservationStatus::ResearchOnlyPreserved | CounterfactualBackfillResearchOnlyPreservationStatus::ResearchOnlyPreservedWithWarnings)
        && matches!(determinism.determinism_status, CounterfactualBackfillDeterminismPreservationStatus::DeterminismPreserved | CounterfactualBackfillDeterminismPreservationStatus::DeterminismPreservedWithWarnings);
    let reduction_status = if preserved {
        if matches!(
            compile.impact_status,
            CounterfactualBackfillCompileImpactStatus::CompileImpactMeasured
        ) && matches!(
            assertion.migration_status,
            CounterfactualBackfillAssertionMigrationStatus::AssertionsMigrated
        ) {
            CounterfactualBackfillRealReductionStatus::CounterfactualBackfillRealReduced
        } else {
            CounterfactualBackfillRealReductionStatus::CounterfactualBackfillReducedWithWarnings
        }
    } else {
        CounterfactualBackfillRealReductionStatus::CounterfactualBackfillStillPrimaryBlocker
    };
    CounterfactualBackfillRealReductionReport {
        report_id: format!("{}-reduction-report", config.reduction_id),
        reduction_plan_status: plan.plan_status,
        assertion_migration_status: assertion.migration_status,
        fixture_setup_reduction_status: fixture.reduction_status,
        no_trade_status: no_trade.no_trade_status,
        risk_denied_status: risk_denied.risk_denied_status,
        defensive_value_status: defensive.defensive_status,
        opportunity_cost_status: opportunity.opportunity_status,
        no_fabricated_outcome_status: no_fabricated.fabrication_status,
        no_lookahead_status: no_lookahead.no_lookahead_status,
        source_boundary_status: source_boundary.source_boundary_status,
        research_only_status: research.research_status,
        determinism_status: determinism.determinism_status,
        compile_impact_status: compile.impact_status,
        reduction_status,
        reason_codes: sprint97_reason_codes(&[]),
    }
}

fn sprint97_build_real_no_run_attempt(
    config: &CounterfactualBackfillRealReductionConfig,
    remaining_blockers: &[String],
) -> Result<RealNoRunGateAttemptV12, String> {
    if !config.run_real_no_run_after_reduction {
        return Ok(RealNoRunGateAttemptV12 {
            attempt_id: format!("{}-real-no-run-v12", config.reduction_id),
            command: "cargo test --workspace --no-run --quiet".to_string(),
            started: false,
            finished: false,
            passed: None,
            duration_ms: None,
            rerun_after_family: Some(CompileFamilyV2::CounterfactualBackfill),
            blocked_families: remaining_blockers.to_vec(),
            no_run_status: RealNoRunGateAttemptV12Status::NotRun,
            reason_codes: sprint97_reason_codes(&[]),
        });
    }
    let (started, passed, duration_ms) =
        sprint96_execute_cargo(&["test", "--workspace", "--no-run", "--quiet"])?;
    let no_run_status = match passed {
        Some(true) => RealNoRunGateAttemptV12Status::RealNoRunPassed,
        Some(false) if !remaining_blockers.is_empty() => {
            RealNoRunGateAttemptV12Status::RealNoRunStillBlocked
        }
        Some(false) => RealNoRunGateAttemptV12Status::RealNoRunFailed,
        None => RealNoRunGateAttemptV12Status::NotRun,
    };
    Ok(RealNoRunGateAttemptV12 {
        attempt_id: format!("{}-real-no-run-v12", config.reduction_id),
        command: "cargo test --workspace --no-run --quiet".to_string(),
        started,
        finished: started,
        passed,
        duration_ms,
        rerun_after_family: Some(CompileFamilyV2::CounterfactualBackfill),
        blocked_families: if matches!(
            no_run_status,
            RealNoRunGateAttemptV12Status::RealNoRunPassed
        ) {
            Vec::new()
        } else {
            remaining_blockers.to_vec()
        },
        no_run_status,
        reason_codes: sprint97_reason_codes(&[]),
    })
}

fn sprint97_build_real_full_attempt(
    config: &CounterfactualBackfillRealReductionConfig,
    remaining_blockers: &[String],
) -> Result<RealFullWorkspaceGateAttemptV15, String> {
    if !config.run_real_full_after_reduction {
        return Ok(RealFullWorkspaceGateAttemptV15 {
            attempt_id: format!("{}-real-full-v15", config.reduction_id),
            command: "cargo test --workspace --quiet".to_string(),
            started: false,
            finished: false,
            passed: None,
            duration_ms: None,
            rerun_after_family: Some(CompileFamilyV2::CounterfactualBackfill),
            blocked_families: remaining_blockers.to_vec(),
            full_status: RealFullWorkspaceGateAttemptV15Status::NotRun,
            reason_codes: sprint97_reason_codes(&[]),
        });
    }
    let (started, passed, duration_ms) =
        sprint96_execute_cargo(&["test", "--workspace", "--quiet"])?;
    let full_status = match passed {
        Some(true) => RealFullWorkspaceGateAttemptV15Status::FullWorkspaceAccepted,
        Some(false) if !remaining_blockers.is_empty() => {
            RealFullWorkspaceGateAttemptV15Status::FullWorkspaceStillBlocked
        }
        Some(false) => RealFullWorkspaceGateAttemptV15Status::FullWorkspaceFailed,
        None => RealFullWorkspaceGateAttemptV15Status::NotRun,
    };
    Ok(RealFullWorkspaceGateAttemptV15 {
        attempt_id: format!("{}-real-full-v15", config.reduction_id),
        command: "cargo test --workspace --quiet".to_string(),
        started,
        finished: started,
        passed,
        duration_ms,
        rerun_after_family: Some(CompileFamilyV2::CounterfactualBackfill),
        blocked_families: if matches!(
            full_status,
            RealFullWorkspaceGateAttemptV15Status::FullWorkspaceAccepted
        ) {
            Vec::new()
        } else {
            remaining_blockers.to_vec()
        },
        full_status,
        reason_codes: sprint97_reason_codes(&[]),
    })
}

