impl Sprint97CounterfactualBackfillRecoveryRunner {
    pub fn run(
        &self,
        config: &CounterfactualBackfillRealReductionConfig,
    ) -> Result<Sprint97CounterfactualBackfillRecoveryBundle, String> {
        config.validate()?;
        let loaded = sprint97_load_inputs(config)?;
        let previous_queue = loaded
            .previous_queue
            .clone()
            .unwrap_or_else(|| sprint97_default_previous_queue(config));
        let previous_safety = loaded
            .previous_safety
            .clone()
            .unwrap_or_else(|| sprint97_default_previous_safety(config));
        let previous_workspace = loaded
            .previous_workspace
            .clone()
            .unwrap_or_else(|| sprint97_default_previous_workspace(config));
        let previous_entry = loaded
            .previous_entry
            .clone()
            .unwrap_or_else(|| sprint97_default_previous_entry(config));
        let previous_precheck = loaded
            .previous_precheck
            .clone()
            .unwrap_or_else(|| sprint97_default_previous_precheck(config));

        let suite_texts = sprint95_existing_texts(&config.counterfactual_backfill_suite_paths)?;
        let donor_texts = sprint95_existing_texts(&config.counterfactual_backfill_paths)?;
        let risk_texts = sprint95_existing_texts(&config.no_trade_fixture_paths)?;
        let defensive_texts = sprint95_existing_texts(&config.defensive_value_fixture_paths)?;
        let fabricated_texts = sprint95_existing_texts(&config.no_fabricated_outcome_paths)?;
        let no_lookahead_texts = sprint95_existing_texts(&config.no_lookahead_fixture_paths)?;
        let source_boundary_texts = sprint95_existing_texts(&config.source_boundary_paths)?;
        let command_texts = sprint95_existing_texts(&["src/bin/soma_experiment.rs".to_string()])?;

        let suite_blob = sprint95_text_blob(&suite_texts);
        let risk_blob = sprint95_text_blob(&risk_texts);
        let defensive_blob = sprint95_text_blob(&defensive_texts);
        let fabricated_blob = sprint95_text_blob(&fabricated_texts);
        let no_lookahead_blob = sprint95_text_blob(&no_lookahead_texts);
        let source_boundary_blob = sprint95_text_blob(&source_boundary_texts);
        let command_blob = sprint95_text_blob(&command_texts);
        let combined_blob = format!(
            "{}\n{}\n{}\n{}",
            suite_blob, risk_blob, fabricated_blob, source_boundary_blob
        );

        let plan = sprint97_build_plan(config, &previous_queue);
        let assertion = sprint97_build_assertion_migration_report(config, &donor_texts);
        let fixture = sprint97_build_fixture_setup_reduction_report(config);
        let no_trade = sprint97_build_no_trade_report(config, &suite_blob, &risk_blob);
        let risk_denied =
            sprint97_build_risk_denied_report(config, &suite_blob, &risk_blob, &previous_safety);
        let defensive = sprint97_build_defensive_value_report(config, &suite_blob, &defensive_blob);
        let opportunity = sprint97_build_opportunity_cost_report(
            config,
            &suite_blob,
            &defensive_blob,
            &risk_denied,
        );
        let no_fabricated =
            sprint97_build_no_fabricated_outcome_report(config, &suite_blob, &fabricated_blob);
        let no_lookahead = sprint97_build_no_lookahead_report(config, &no_lookahead_blob);
        let source_boundary = sprint97_build_source_boundary_report(config, &source_boundary_blob);
        let research = sprint97_build_research_only_report(config, &command_blob);
        let determinism = sprint97_build_determinism_report(config, &suite_blob, &combined_blob);
        let compile_impact = sprint97_build_compile_impact_report(config, &loaded);
        let reduction = sprint97_build_reduction_report(
            config,
            &plan,
            &assertion,
            &fixture,
            &no_trade,
            &risk_denied,
            &defensive,
            &opportunity,
            &no_fabricated,
            &no_lookahead,
            &source_boundary,
            &research,
            &determinism,
            &compile_impact,
        );

        let remaining_blockers =
            sprint97_current_remaining_blockers(&previous_queue, reduction.reduction_status);
        let no_run_attempt = sprint97_build_real_no_run_attempt(config, &remaining_blockers)?;
        let full_attempt = sprint97_build_real_full_attempt(config, &remaining_blockers)?;
        let no_run_rerun = CounterfactualBackfillNoRunGateRerunReport {
            report_id: format!("{}-no-run-rerun", config.reduction_id),
            command: no_run_attempt.command.clone(),
            started: no_run_attempt.started,
            finished: no_run_attempt.finished,
            passed: no_run_attempt.passed,
            duration_ms: no_run_attempt.duration_ms,
            rerun_after_family: CompileFamilyV2::CounterfactualBackfill,
            remaining_blocker_families: if matches!(no_run_attempt.no_run_status, RealNoRunGateAttemptV12Status::RealNoRunPassed) { Vec::new() } else { remaining_blockers.clone() },
            status: match no_run_attempt.no_run_status {
                RealNoRunGateAttemptV12Status::RealNoRunPassed => CounterfactualBackfillNoRunGateRerunStatus::NoRunRecoveredAfterCounterfactualBackfill,
                RealNoRunGateAttemptV12Status::RealNoRunStillBlocked => CounterfactualBackfillNoRunGateRerunStatus::NoRunStillBlockedAfterCounterfactualBackfill,
                RealNoRunGateAttemptV12Status::RealNoRunFailed => CounterfactualBackfillNoRunGateRerunStatus::NoRunFailedAfterCounterfactualBackfill,
                RealNoRunGateAttemptV12Status::NotRun => CounterfactualBackfillNoRunGateRerunStatus::NotRun,
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let full_rerun = CounterfactualBackfillFullGateRerunReport {
            report_id: format!("{}-full-rerun", config.reduction_id),
            command: full_attempt.command.clone(),
            started: full_attempt.started,
            finished: full_attempt.finished,
            passed: full_attempt.passed,
            duration_ms: full_attempt.duration_ms,
            rerun_after_family: CompileFamilyV2::CounterfactualBackfill,
            remaining_blocker_families: if matches!(full_attempt.full_status, RealFullWorkspaceGateAttemptV15Status::FullWorkspaceAccepted) { Vec::new() } else { remaining_blockers.clone() },
            status: match full_attempt.full_status {
                RealFullWorkspaceGateAttemptV15Status::FullWorkspaceAccepted => CounterfactualBackfillFullGateRerunStatus::FullWorkspaceAcceptedAfterCounterfactualBackfill,
                RealFullWorkspaceGateAttemptV15Status::FullWorkspaceStillBlocked => CounterfactualBackfillFullGateRerunStatus::FullWorkspaceStillBlockedAfterCounterfactualBackfill,
                RealFullWorkspaceGateAttemptV15Status::FullWorkspaceFailed => CounterfactualBackfillFullGateRerunStatus::FullWorkspaceFailedAfterCounterfactualBackfill,
                RealFullWorkspaceGateAttemptV15Status::NotRun => CounterfactualBackfillFullGateRerunStatus::NotRun,
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let entry_consumed = CounterfactualBackfillEntryConsumedReport {
            report_id: format!("{}-entry-consumed", config.reduction_id),
            previous_entry_status: format!("{:?}", previous_entry.gate_status),
            reduction_started: sprint97_reduction_is_closed(reduction.reduction_status),
            entry_consumed: matches!(
                previous_entry.gate_status,
                CounterfactualBackfillEntryGateStatus::CounterfactualBackfillEntryReady
            ) && sprint97_reduction_is_closed(reduction.reduction_status),
            consumed_for_family: CompileFamilyV2::CounterfactualBackfill,
            consumed_status: if matches!(
                previous_entry.gate_status,
                CounterfactualBackfillEntryGateStatus::CounterfactualBackfillEntryReady
            ) && sprint97_reduction_is_closed(reduction.reduction_status)
            {
                CounterfactualBackfillEntryConsumedStatus::EntryConsumedForCounterfactualBackfill
            } else if matches!(
                previous_entry.gate_status,
                CounterfactualBackfillEntryGateStatus::CounterfactualBackfillEntryReady
            ) {
                CounterfactualBackfillEntryConsumedStatus::EntryReadyButNotConsumed
            } else {
                CounterfactualBackfillEntryConsumedStatus::EntryBlocked
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let safety = SafetyCoveragePreservationReportV13 {
            report_id: format!("{}-safety-v13", config.reduction_id),
            live_trading_guard_present: previous_safety.live_trading_guard_present,
            broker_guard_present: previous_safety.broker_guard_present,
            order_guard_present: previous_safety.order_guard_present,
            account_guard_present: previous_safety.account_guard_present,
            runtime_llm_guard_present: previous_safety.runtime_llm_guard_present,
            mamba_runtime_guard_present: previous_safety.mamba_runtime_guard_present,
            gated_runtime_guard_present: previous_safety.gated_runtime_guard_present,
            model_training_guard_present: previous_safety.model_training_guard_present,
            rust_neural_training_guard_present: previous_safety.rust_neural_training_guard_present,
            python_training_dependency_guard_present: previous_safety.python_training_dependency_guard_present,
            secret_guard_present: previous_safety.secret_guard_present,
            no_lookahead_guard_present: previous_safety.no_lookahead_guard_present,
            source_boundary_guard_present: previous_safety.source_boundary_guard_present,
            browser_execution_guard_present: previous_safety.browser_execution_guard_present,
            ui_order_control_guard_present: previous_safety.ui_order_control_guard_present,
            committee_cli_safety_isolated: previous_safety.committee_cli_safety_isolated,
            baseline_no_trade_default_preserved: previous_safety.baseline_no_trade_default_preserved,
            baseline_risk_governor_veto_preserved: previous_safety
                .baseline_risk_governor_veto_preserved,
            counterfactual_no_trade_preserved: matches!(no_trade.no_trade_status, CounterfactualBackfillNoTradePreservationStatus::NoTradeCounterfactualPreserved | CounterfactualBackfillNoTradePreservationStatus::NoTradeCounterfactualPreservedWithWarnings),
            counterfactual_risk_denied_preserved: matches!(risk_denied.risk_denied_status, CounterfactualBackfillRiskDeniedPreservationStatus::RiskDeniedCounterfactualPreserved | CounterfactualBackfillRiskDeniedPreservationStatus::RiskDeniedCounterfactualPreservedWithWarnings),
            counterfactual_defensive_value_preserved: matches!(defensive.defensive_status, CounterfactualBackfillDefensiveValuePreservationStatus::DefensiveValuePreserved | CounterfactualBackfillDefensiveValuePreservationStatus::DefensiveValuePreservedWithWarnings),
            counterfactual_opportunity_cost_preserved: matches!(opportunity.opportunity_status, CounterfactualBackfillOpportunityCostPreservationStatus::OpportunityCostPreserved | CounterfactualBackfillOpportunityCostPreservationStatus::OpportunityCostPreservedWithWarnings),
            counterfactual_no_fabricated_outcomes_preserved: matches!(no_fabricated.fabrication_status, CounterfactualBackfillNoFabricatedOutcomeStatus::NoFabricatedOutcomesPreserved | CounterfactualBackfillNoFabricatedOutcomeStatus::NoFabricatedOutcomesPreservedWithWarnings),
            counterfactual_no_lookahead_preserved: matches!(no_lookahead.no_lookahead_status, CounterfactualBackfillNoLookaheadPreservationStatus::NoLookaheadPreserved | CounterfactualBackfillNoLookaheadPreservationStatus::NoLookaheadPreservedWithWarnings),
            counterfactual_source_boundary_preserved: matches!(source_boundary.source_boundary_status, CounterfactualBackfillSourceBoundaryPreservationStatus::SourceBoundaryPreserved | CounterfactualBackfillSourceBoundaryPreservationStatus::SourceBoundaryPreservedWithWarnings),
            counterfactual_research_only_preserved: matches!(research.research_status, CounterfactualBackfillResearchOnlyPreservationStatus::ResearchOnlyPreserved | CounterfactualBackfillResearchOnlyPreservationStatus::ResearchOnlyPreservedWithWarnings),
            queue_closure_separate_from_workspace_acceptance: true,
            safety_status: SafetyCoveragePreservationReportV13Status::SafetyCoveragePreserved,
            reason_codes: sprint97_reason_codes(&[]),
        };
        let queue_closure_allowed = sprint97_reduction_is_closed(reduction.reduction_status)
            && matches!(
                entry_consumed.consumed_status,
                CounterfactualBackfillEntryConsumedStatus::EntryConsumedForCounterfactualBackfill
            )
            && matches!(
                previous_precheck.precheck_status,
                CounterfactualBackfillReadinessPrecheckStatus::CounterfactualBackfillPrecheckReady
                    | CounterfactualBackfillReadinessPrecheckStatus::CounterfactualBackfillPrecheckReadyWithWarnings
            )
            && matches!(
                safety.safety_status,
                SafetyCoveragePreservationReportV13Status::SafetyCoveragePreserved
                    | SafetyCoveragePreservationReportV13Status::SafetyCoveragePreservedWithWarnings
            );
        let queue_closed = queue_closure_allowed && remaining_blockers.is_empty();
        let full_workspace_status =
            sprint97_current_full_status(&previous_workspace, &full_attempt);
        let final_gate = FinalBlockerQueueClosureGate {
            gate_id: format!("{}-final-queue-gate", config.reduction_id),
            counterfactual_backfill_reduction_status: reduction.reduction_status,
            counterfactual_safety_status: safety.safety_status,
            remaining_family_count: remaining_blockers.len(),
            full_workspace_status: full_workspace_status.clone(),
            queue_closure_allowed,
            gate_status: if !queue_closure_allowed {
                FinalBlockerQueueClosureGateStatus::FinalBlockerQueueBlockedByCounterfactualBackfill
            } else if queue_closed
                && matches!(
                    full_attempt.full_status,
                    RealFullWorkspaceGateAttemptV15Status::FullWorkspaceAccepted
                )
            {
                FinalBlockerQueueClosureGateStatus::FinalBlockerQueueClosed
            } else if queue_closed {
                FinalBlockerQueueClosureGateStatus::FinalBlockerQueueClosedWithWorkspaceStillBlocked
            } else {
                FinalBlockerQueueClosureGateStatus::FinalBlockerQueueStillOpen
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let completed_families = if queue_closed {
            vec![
                "BaselineSignal".to_string(),
                "DashboardRenderer".to_string(),
                "KrxEvidence".to_string(),
                "CounterfactualBackfill".to_string(),
            ]
        } else {
            previous_queue.completed_families.clone()
        };
        let final_report = FinalBlockerQueueClosureReport {
            report_id: format!("{}-final-queue-report", config.reduction_id),
            previous_queue: previous_queue.ordered_remaining_families.clone(),
            current_queue: remaining_blockers.clone(),
            completed_families: completed_families.clone(),
            isolated_families: previous_queue.isolated_families.clone(),
            remaining_families: remaining_blockers.clone(),
            queue_closure_gate_status: final_gate.gate_status,
            closure_status: if queue_closed
                && matches!(
                    full_attempt.full_status,
                    RealFullWorkspaceGateAttemptV15Status::FullWorkspaceAccepted
                ) {
                FinalBlockerQueueClosureStatus::QueueClosed
            } else if queue_closed {
                FinalBlockerQueueClosureStatus::QueueClosedWithWorkspaceStillBlocked
            } else {
                FinalBlockerQueueClosureStatus::QueueStillOpen
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let truth_gate = WorkspaceAcceptanceTruthGate {
            gate_id: format!("{}-workspace-truth-gate", config.reduction_id),
            no_run_status: sprint97_current_no_run_status(&previous_workspace, &no_run_attempt),
            full_workspace_status: full_workspace_status.clone(),
            full_workspace_finished: full_attempt.finished,
            full_workspace_passed: full_attempt.passed,
            can_claim_full_acceptance: matches!(
                full_attempt.full_status,
                RealFullWorkspaceGateAttemptV15Status::FullWorkspaceAccepted
            ),
            truth_status: match full_attempt.full_status {
                RealFullWorkspaceGateAttemptV15Status::FullWorkspaceAccepted => {
                    WorkspaceAcceptanceTruthGateStatus::FullWorkspaceAccepted
                }
                RealFullWorkspaceGateAttemptV15Status::FullWorkspaceStillBlocked => {
                    WorkspaceAcceptanceTruthGateStatus::FullWorkspaceStillBlocked
                }
                RealFullWorkspaceGateAttemptV15Status::FullWorkspaceFailed => {
                    WorkspaceAcceptanceTruthGateStatus::FullWorkspaceFailed
                }
                RealFullWorkspaceGateAttemptV15Status::NotRun => {
                    WorkspaceAcceptanceTruthGateStatus::FullWorkspaceNotRun
                }
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let queue_progress = SevenBlockerQueueProgressReportV13 {
            report_id: format!("{}-queue-progress-v13", config.reduction_id),
            previous_queue: previous_queue.ordered_remaining_families.clone(),
            current_queue: remaining_blockers.clone(),
            completed_families: completed_families.clone(),
            reduced_families: if queue_closed {
                vec!["CounterfactualBackfill".to_string()]
            } else {
                Vec::new()
            },
            isolated_families: previous_queue.isolated_families.clone(),
            still_blocked_families: remaining_blockers.clone(),
            primary_next_family: remaining_blockers.first().cloned(),
            queue_status: if queue_closed
                && matches!(
                    truth_gate.truth_status,
                    WorkspaceAcceptanceTruthGateStatus::FullWorkspaceAccepted
                ) {
                SevenBlockerQueueProgressStatusV13::QueueClosed
            } else if queue_closed {
                SevenBlockerQueueProgressStatusV13::QueueClosedWithWorkspaceStillBlocked
            } else if remaining_blockers == previous_queue.ordered_remaining_families {
                SevenBlockerQueueProgressStatusV13::QueueBlockedByCounterfactualBackfill
            } else {
                SevenBlockerQueueProgressStatusV13::QueueUnchanged
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let measured_delta = MeasuredTargetDeltaReportV13 {
            report_id: format!("{}-measured-target-delta-v13", config.reduction_id),
            target_count_before: compile_impact.target_count_before,
            target_count_after: compile_impact.target_count_after,
            counterfactual_backfill_delta: compile_impact.counterfactual_backfill_delta,
            measured: compile_impact.measured,
            sample_backed: compile_impact.sample_backed,
            timing_available: compile_impact.compile_duration_before_ms.is_some()
                && compile_impact.compile_duration_after_ms.is_some(),
            delta_status: if compile_impact.measured {
                MeasuredTargetDeltaStatusV13::MeasuredTargetDeltaReady
            } else if compile_impact.sample_backed {
                MeasuredTargetDeltaStatusV13::SampleBackedOnly
            } else {
                MeasuredTargetDeltaStatusV13::NotRun
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let remaining_queue = RemainingBlockerQueueV13 {
            queue_id: format!("{}-remaining-queue-v13", config.reduction_id),
            ordered_remaining_families: remaining_blockers.clone(),
            primary_next_family: queue_progress.primary_next_family.clone(),
            completed_families: queue_progress.completed_families.clone(),
            isolated_families: queue_progress.isolated_families.clone(),
            blocked_families: remaining_blockers.clone(),
            final_blocker_queue_closed: queue_closed,
            queue_status: if queue_closed
                && matches!(
                    truth_gate.truth_status,
                    WorkspaceAcceptanceTruthGateStatus::FullWorkspaceAccepted
                ) {
                RemainingBlockerQueueV13Status::QueueClosed
            } else if queue_closed {
                RemainingBlockerQueueV13Status::QueueClosedWithWorkspaceStillBlocked
            } else if queue_closure_allowed {
                RemainingBlockerQueueV13Status::QueueReady
            } else {
                RemainingBlockerQueueV13Status::QueueBlockedByCounterfactualBackfill
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let workspace_recovery = WorkspaceGateRecoveryV14 {
            report_id: format!("{}-workspace-gate-recovery-v14", config.reduction_id),
            previous_no_run_status: previous_workspace.current_no_run_status.clone(),
            current_no_run_status: truth_gate.no_run_status.clone(),
            previous_full_status: previous_workspace.current_full_status.clone(),
            current_full_status: truth_gate.full_workspace_status.clone(),
            counterfactual_backfill_reduction_status: reduction.reduction_status,
            final_blocker_queue_status: final_report.closure_status,
            workspace_acceptance_truth_status: truth_gate.truth_status,
            measured_delta_status: measured_delta.delta_status,
            queue_progress_status: queue_progress.queue_status,
            safety_coverage_status: safety.safety_status,
            remaining_blockers: remaining_blockers.clone(),
            recovery_status: if matches!(
                truth_gate.truth_status,
                WorkspaceAcceptanceTruthGateStatus::FullWorkspaceAccepted
            ) {
                WorkspaceGateRecoveryV14Status::GateRecovered
            } else if queue_closed {
                WorkspaceGateRecoveryV14Status::GateImprovedButBlocked
            } else {
                WorkspaceGateRecoveryV14Status::GateStillBlocked
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let remaining_risk = WorkspaceAcceptanceRemainingRiskReport {
            report_id: format!("{}-workspace-remaining-risk", config.reduction_id),
            full_workspace_status: truth_gate.full_workspace_status.clone(),
            compile_only_status: truth_gate.no_run_status.clone(),
            queue_status: format!("{:?}", final_report.closure_status),
            sample_backed_delta_status: format!("{:?}", measured_delta.delta_status),
            measured_timing_status: if measured_delta.timing_available {
                "MeasuredTimingAvailable".to_string()
            } else {
                "MeasuredTimingMissing".to_string()
            },
            remaining_risks: {
                let mut risks = Vec::new();
                if !matches!(
                    truth_gate.truth_status,
                    WorkspaceAcceptanceTruthGateStatus::FullWorkspaceAccepted
                ) {
                    risks.push("FullWorkspaceStillBlocked".to_string());
                }
                if !measured_delta.timing_available {
                    risks.push("MeasuredTimingMissing".to_string());
                }
                if compile_impact.impact_status
                    == CounterfactualBackfillCompileImpactStatus::CompileImpactSampleBacked
                {
                    risks.push("SampleBackedOnly".to_string());
                }
                if !matches!(
                    no_run_rerun.status,
                    CounterfactualBackfillNoRunGateRerunStatus::NoRunRecoveredAfterCounterfactualBackfill
                ) {
                    risks.push("UnknownCargoCost".to_string());
                }
                risks
            },
            risk_status: if matches!(
                truth_gate.truth_status,
                WorkspaceAcceptanceTruthGateStatus::FullWorkspaceAccepted
            ) {
                WorkspaceAcceptanceRemainingRiskStatus::AcceptanceRiskClosed
            } else {
                WorkspaceAcceptanceRemainingRiskStatus::AcceptanceRiskRemaining
            },
            reason_codes: sprint97_reason_codes(&[]),
        };
        let panel = ControlTowerCounterfactualBackfillRecoveryPanel {
            panel_id: format!("{}-control-tower-panel", config.reduction_id),
            counterfactual_backfill_reduction_status: reduction.reduction_status,
            assertion_migration_status: assertion.migration_status,
            fixture_setup_reduction_status: fixture.reduction_status,
            no_trade_counterfactual_status: no_trade.no_trade_status,
            risk_denied_counterfactual_status: risk_denied.risk_denied_status,
            defensive_value_status: defensive.defensive_status,
            opportunity_cost_status: opportunity.opportunity_status,
            no_fabricated_outcome_status: no_fabricated.fabrication_status,
            no_lookahead_status: no_lookahead.no_lookahead_status,
            source_boundary_status: source_boundary.source_boundary_status,
            research_only_status: research.research_status,
            determinism_status: determinism.determinism_status,
            compile_impact_status: compile_impact.impact_status,
            no_run_gate_status: no_run_rerun.status,
            full_gate_status: full_rerun.status,
            final_queue_closure_status: final_report.closure_status,
            workspace_truth_status: truth_gate.truth_status,
            measured_delta_status: measured_delta.delta_status,
            safety_coverage_status: safety.safety_status,
            runtime_deferred_summary: "ResearchOnly".to_string(),
            primary_next_family: remaining_queue.primary_next_family.clone(),
            next_actions: vec![
                "Keep CounterfactualBackfill conservative: NoTrade, RiskDenied, defensive value, opportunity cost, and missing-outcome guards remain absolute.".to_string(),
                "Treat final queue closure separately from quiet full workspace acceptance.".to_string(),
                "Keep runtime, live trading, broker/account, browser execution, and training deferred.".to_string(),
            ],
            warnings: remaining_risk.remaining_risks.clone(),
            reason_codes: sprint97_reason_codes(&[]),
        };
        let final_summary = format!(
            "counterfactual_backfill={:?}; final_queue={:?}; workspace_truth={:?}; no_run_rerun={:?}; full_rerun={:?}; compile_impact={:?}",
            reduction.reduction_status,
            final_report.closure_status,
            truth_gate.truth_status,
            no_run_rerun.status,
            full_rerun.status,
            compile_impact.impact_status,
        );
        let storage_values = vec![
            (
                "counterfactual_backfill_real_reduction_plan",
                serde_json::to_value(&plan).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_real_reduction_report",
                serde_json::to_value(&reduction).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_assertion_migration_report",
                serde_json::to_value(&assertion).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_fixture_setup_reduction_report",
                serde_json::to_value(&fixture).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_no_trade_preservation_report",
                serde_json::to_value(&no_trade).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_risk_denied_preservation_report",
                serde_json::to_value(&risk_denied).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_defensive_value_preservation_report",
                serde_json::to_value(&defensive).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_opportunity_cost_preservation_report",
                serde_json::to_value(&opportunity).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_no_fabricated_outcome_report",
                serde_json::to_value(&no_fabricated).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_no_lookahead_preservation_report",
                serde_json::to_value(&no_lookahead).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_source_boundary_preservation_report",
                serde_json::to_value(&source_boundary).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_research_only_preservation_report",
                serde_json::to_value(&research).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_determinism_preservation_report",
                serde_json::to_value(&determinism).map_err(|err| err.to_string())?,
            ),
            (
                "counterfactual_backfill_compile_impact_report",
                serde_json::to_value(&compile_impact).map_err(|err| err.to_string())?,
            ),
            (
                "final_blocker_queue_closure_report",
                serde_json::to_value(&final_report).map_err(|err| err.to_string())?,
            ),
            (
                "workspace_acceptance_truth_gate",
                serde_json::to_value(&truth_gate).map_err(|err| err.to_string())?,
            ),
            ("summary", serde_json::Value::String(final_summary.clone())),
        ];
        let storage_report = sprint96_storage_report(&storage_values)?;
        let bundle = Sprint97CounterfactualBackfillRecoveryBundle {
            counterfactual_backfill_real_reduction_plan: plan,
            counterfactual_backfill_real_reduction_report: reduction,
            counterfactual_backfill_assertion_migration_report: assertion,
            counterfactual_backfill_fixture_setup_reduction_report: fixture,
            counterfactual_backfill_no_trade_preservation_report: no_trade,
            counterfactual_backfill_risk_denied_preservation_report: risk_denied,
            counterfactual_backfill_defensive_value_preservation_report: defensive,
            counterfactual_backfill_opportunity_cost_preservation_report: opportunity,
            counterfactual_backfill_no_fabricated_outcome_report: no_fabricated,
            counterfactual_backfill_no_lookahead_preservation_report: no_lookahead,
            counterfactual_backfill_source_boundary_preservation_report: source_boundary,
            counterfactual_backfill_research_only_preservation_report: research,
            counterfactual_backfill_determinism_preservation_report: determinism,
            counterfactual_backfill_compile_impact_report: compile_impact,
            counterfactual_backfill_no_run_gate_rerun_report: no_run_rerun,
            counterfactual_backfill_full_gate_rerun_report: full_rerun,
            counterfactual_backfill_entry_consumed_report: entry_consumed,
            final_blocker_queue_closure_gate: final_gate,
            final_blocker_queue_closure_report: final_report,
            workspace_acceptance_truth_gate: truth_gate,
            workspace_acceptance_remaining_risk_report: remaining_risk,
            seven_blocker_queue_progress_report_v13: queue_progress,
            measured_target_delta_report_v13: measured_delta,
            real_no_run_gate_attempt_v12: no_run_attempt,
            real_full_workspace_gate_attempt_v15: full_attempt,
            workspace_gate_recovery_v14: workspace_recovery,
            remaining_blocker_queue_v13: remaining_queue,
            safety_coverage_preservation_report_v13: safety,
            control_tower_counterfactual_backfill_recovery_panel: panel,
            storage_report,
            final_summary,
            reason_codes: sprint97_reason_codes(&[]),
        };
        sprint97_write_bundle(&config.output_dir(), &bundle)?;
        Ok(bundle)
    }

    pub fn run_sprint97_counterfactual_backfill_recover(
        &self,
        config: &CounterfactualBackfillRealReductionConfig,
    ) -> Result<Sprint97CounterfactualBackfillRecoveryBundle, String> {
        self.run(config)
    }
}

pub fn load_sprint97_counterfactual_backfill_recovery_config(
    path: impl AsRef<Path>,
) -> Result<CounterfactualBackfillRealReductionConfig, String> {
    CounterfactualBackfillRealReductionConfig::from_toml_path(path.as_ref())
}

pub fn run_sprint97_counterfactual_backfill_recovery(
    config: &CounterfactualBackfillRealReductionConfig,
) -> Result<Sprint97CounterfactualBackfillRecoveryBundle, String> {
    Sprint97CounterfactualBackfillRecoveryRunner.run(config)
}

pub fn run_sprint97_counterfactual_backfill_recovery_from_path(
    path: impl AsRef<Path>,
) -> Result<Sprint97CounterfactualBackfillRecoveryBundle, String> {
    let config = load_sprint97_counterfactual_backfill_recovery_config(path)?;
    Sprint97CounterfactualBackfillRecoveryRunner.run(&config)
}
